import { COLORS, FONT_STAT_SECTION, FONT_SUB , FONT_SMALL } from '@egoless-do/core';
import type { Plan, PlanStatus } from '@egoless-do/core';
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { View, Text, AppState } from 'react-native';

import { useTheme, useT } from './UI';

interface Props {
  plan: Plan;
}

interface CountdownTime {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
}

type CountdownType = 'start' | 'end' | 'overdue' | 'none';

function getCountdownType(plan: Plan, now: Date): CountdownType {
  const { status, startDate, endDate } = plan;
  
  // 不显示倒计时的状态
  if (status === 'paused' || status === 'completed' || status === 'cancelled') {
    return 'none';
  }
  
  const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  
  // 未开始计划
  if (status === 'not_started') {
    return 'start';
  }
  
  // 进行中的计划
  if (status === 'in_progress') {
    // 检查是否超期
    if (endDate < today) {
      return 'overdue';
    }
    return 'end';
  }
  
  return 'none';
}

function calculateTimeDiff(targetDate: string, now: Date, isOverdue: boolean = false): CountdownTime {
  // Parse date components manually to get local midnight (not UTC).
  // new Date('2026-01-15T00:00:00') would be UTC midnight, which is wrong
  // for users outside UTC+0.
  const [y, m, d] = targetDate.split('-').map(Number);
  const target = new Date(y, m - 1, d);
  const diffMs = isOverdue 
    ? now.getTime() - target.getTime()
    : target.getTime() - now.getTime();
  
  if (diffMs <= 0) {
    return { days: 0, hours: 0, minutes: 0, seconds: 0 };
  }
  
  const totalSeconds = Math.floor(diffMs / 1000);
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  
  return { days, hours, minutes, seconds };
}

function formatNumber(num: number): string {
  return String(num).padStart(2, '0');
}

export default function PlanCountdown({ plan }: Props) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  
  const [now, setNow] = useState(() => new Date());
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  
  const countdownType = getCountdownType(plan, now);
  
  // 计算倒计时
  const calculateCountdown = useCallback((): CountdownTime => {
    switch (countdownType) {
      case 'start':
        return calculateTimeDiff(plan.startDate, now, false);
      case 'end':
        return calculateTimeDiff(plan.endDate, now, false);
      case 'overdue':
        return calculateTimeDiff(plan.endDate, now, true);
      default:
        return { days: 0, hours: 0, minutes: 0, seconds: 0 };
    }
  }, [countdownType, plan.startDate, plan.endDate, now]);
  
  const time = calculateCountdown();
  
  // 每秒更新倒计时
  useEffect(() => {
    if (countdownType === 'none') return;
    
    intervalRef.current = setInterval(() => {
      setNow(new Date());
    }, 1000);
    
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [countdownType]);
  
  // 监听 AppState 变化，恢复时立即刷新
  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextAppState) => {
      if (nextAppState === 'active') {
        setNow(new Date());
      }
    });
    
    return () => {
      subscription.remove();
    };
  }, []);
  
  // 不显示倒计时
  if (countdownType === 'none') {
    return null;
  }
  
  // 获取标签和颜色
  const getLabelAndColor = () => {
    switch (countdownType) {
      case 'start':
        return { label: T('planCountdownStart'), color: COLORS.BLUE };
      case 'end':
        return { label: T('planCountdownEnd'), color: P };
      case 'overdue':
        return { label: T('planDelayed'), color: COLORS.RED };
      default:
        return { label: '', color: P };
    }
  };
  
  const { label, color } = getLabelAndColor();
  
  return (
    <View style={{
      backgroundColor: `${color}10`,
      borderRadius: 12,
      padding: 16,
      marginTop: 12,
      alignItems: 'center',
    }}>
      <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>
        {label}
      </Text>
      <View style={{ flexDirection: 'row', alignItems: 'baseline', gap: 4 }}>
        {time.days > 0 && (
          <View style={{ alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color }}>
              {formatNumber(time.days)}
            </Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('planDays')}</Text>
          </View>
        )}
        {time.days > 0 && (
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color, marginHorizontal: 2 }}>:</Text>
        )}
        <View style={{ alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color }}>
            {formatNumber(time.hours)}
          </Text>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('planHours')}</Text>
        </View>
        <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color, marginHorizontal: 2 }}>:</Text>
        <View style={{ alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color }}>
            {formatNumber(time.minutes)}
          </Text>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('planMinutes')}</Text>
        </View>
        <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color, marginHorizontal: 2 }}>:</Text>
        <View style={{ alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color }}>
            {formatNumber(time.seconds)}
          </Text>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('planSeconds')}</Text>
        </View>
      </View>
    </View>
  );
}

import React, { useEffect, useRef, useMemo, useState } from 'react';
import { View, Animated, Dimensions, StyleSheet, Platform, useWindowDimensions } from 'react-native';
import Svg, { Line } from 'react-native-svg';

const { width: INITIAL_WIDTH, height: INITIAL_HEIGHT } = Dimensions.get('window');

// 检测是否为低端设备（基于平台和屏幕尺寸）
const isLowEndDevice = Platform.OS === 'android' && (INITIAL_WIDTH < 400 || INITIAL_HEIGHT < 800);

// ─── 星星层次配置 ───────────────────────────────────────────────
// 根据设备性能动态调整星星数量
const LAYERS = isLowEndDevice
  ? [
      // 低端设备：减少星星数量（共 60 颗）
      { count: 30, minSize: 0.5, maxSize: 1.2, minOpacity: 0.2, maxOpacity: 0.5, twinkleSpeed: [3000, 6000] },
      { count: 20, minSize: 1.0, maxSize: 2.0, minOpacity: 0.4, maxOpacity: 0.8, twinkleSpeed: [2000, 4000] },
      { count: 8,  minSize: 2.0, maxSize: 3.5, minOpacity: 0.7, maxOpacity: 1.0, twinkleSpeed: [1500, 3000] },
      { count: 2,  minSize: 4.0, maxSize: 6.0, minOpacity: 0.85, maxOpacity: 1.0, twinkleSpeed: [1000, 2000] },
    ]
  : [
      // 高端设备：完整星星数量（共 188 颗）
      { count: 100, minSize: 0.5, maxSize: 1.2, minOpacity: 0.2, maxOpacity: 0.5, twinkleSpeed: [3000, 6000] },
      { count: 60,  minSize: 1.0, maxSize: 2.0, minOpacity: 0.4, maxOpacity: 0.8, twinkleSpeed: [2000, 4000] },
      { count: 20,  minSize: 2.0, maxSize: 3.5, minOpacity: 0.7, maxOpacity: 1.0, twinkleSpeed: [1500, 3000] },
      { count: 8,   minSize: 4.0, maxSize: 6.0, minOpacity: 0.85, maxOpacity: 1.0, twinkleSpeed: [1000, 2000] },
    ];

// 低端设备减少流星数量
const SHOOTING_STAR_COUNT = isLowEndDevice ? 1 : 3;

// ─── 星座连线配置 ───────────────────────────────────────────────
const CONSTELLATION_LINE_COLOR = 'rgba(150, 130, 255, 0.15)';

// ─── 接口定义 ──────────────────────────────────────────────────
interface StarProps {
  x: number;
  y: number;
  size: number;
  minOpacity: number;
  maxOpacity: number;
  twinkleSpeed: number[];
  color: string;
  glowColor: string;
}

interface ConstellationLine {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

// ─── 星星颜色生成（带光晕色） ────────────────────────────────────
function getStarColor(): { color: string; glowColor: string } {
  const rand = Math.random();
  if (rand < 0.55) return { color: '#ffffff', glowColor: 'rgba(200, 200, 255, 0.6)' };
  if (rand < 0.70) return { color: '#e8e0ff', glowColor: 'rgba(180, 160, 255, 0.5)' };
  if (rand < 0.82) return { color: '#ffe8d0', glowColor: 'rgba(255, 200, 150, 0.5)' };
  if (rand < 0.92) return { color: '#d0e8ff', glowColor: 'rgba(150, 200, 255, 0.5)' };
  if (rand < 0.97) return { color: '#ffd0d0', glowColor: 'rgba(255, 180, 180, 0.4)' };
  return { color: '#d0ffe0', glowColor: 'rgba(180, 255, 200, 0.4)' };
}

// ─── 亮星星组件（带十字光芒） ────────────────────────────────────
function BrightStar({ x, y, size, minOpacity, maxOpacity, twinkleSpeed, color, glowColor }: StarProps) {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.3)).current;
  const rotateAnim = useRef(new Animated.Value(0)).current;
  const mountedRef = useRef(true);
  const loopRef = useRef<Animated.CompositeAnimation | null>(null);
  const activeAnimRef = useRef<Animated.CompositeAnimation | null>(null);

  useEffect(() => {
    mountedRef.current = true;
    const animate = () => {
      if (!mountedRef.current) return;
      const introParallel = Animated.parallel([
        Animated.timing(opacity, { toValue: maxOpacity, duration: 2000, useNativeDriver: true }),
        Animated.spring(scale, { toValue: 1, friction: 2, tension: 20, useNativeDriver: true }),
      ]);
      const intro = Animated.sequence([
        Animated.delay(Math.random() * 3000),
        introParallel,
      ]);
      activeAnimRef.current = intro;
      intro.start(() => {
        const twinkle = () => {
          if (!mountedRef.current) return;
          const d1 = twinkleSpeed[0] + Math.random() * (twinkleSpeed[1] - twinkleSpeed[0]);
          const d2 = twinkleSpeed[0] + Math.random() * (twinkleSpeed[1] - twinkleSpeed[0]);
          const seq = Animated.sequence([
            Animated.timing(opacity, { toValue: minOpacity + Math.random() * 0.2, duration: d1, useNativeDriver: true }),
            Animated.timing(opacity, { toValue: maxOpacity, duration: d2, useNativeDriver: true }),
          ]);
          activeAnimRef.current = seq;
          seq.start(twinkle);
        };
        twinkle();
        loopRef.current = Animated.loop(
          Animated.timing(rotateAnim, { toValue: 1, duration: 20000, useNativeDriver: true })
        );
        loopRef.current.start();
      });
    };
    animate();
    return () => {
      mountedRef.current = false;
      activeAnimRef.current?.stop();
      loopRef.current?.stop();
    };
  }, []);

  const rotation = rotateAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  const spikeLength = size * 2.5;

  return (
    <Animated.View
      style={{
        position: 'absolute',
        left: x - spikeLength / 2,
        top: y - spikeLength / 2,
        width: spikeLength,
        height: spikeLength,
        opacity,
        transform: [{ scale }, { rotate: rotation }],
      }}
    >
      <View style={{
        position: 'absolute',
        top: '50%',
        left: '10%',
        right: '10%',
        height: 1,
        backgroundColor: color,
        opacity: 0.4,
        shadowColor: glowColor,
        shadowRadius: 4,
        shadowOpacity: 0.8,
      }} />
      <View style={{
        position: 'absolute',
        left: '50%',
        top: '10%',
        bottom: '10%',
        width: 1,
        backgroundColor: color,
        opacity: 0.4,
        shadowColor: glowColor,
        shadowRadius: 4,
        shadowOpacity: 0.8,
      }} />
      <View style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        width: size,
        height: size,
        borderRadius: size / 2,
        marginTop: -size / 2,
        marginLeft: -size / 2,
        backgroundColor: color,
        shadowColor: glowColor,
        shadowRadius: size * 2,
        shadowOpacity: 1,
      }} />
    </Animated.View>
  );
}

// ─── 普通星星组件 ────────────────────────────────────────────────
function Star({ x, y, size, minOpacity, maxOpacity, twinkleSpeed, color, glowColor }: StarProps) {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.3)).current;
  const mountedRef = useRef(true);
  const activeAnimRef = useRef<Animated.CompositeAnimation | null>(null);

  useEffect(() => {
    mountedRef.current = true;
    const animate = () => {
      if (!mountedRef.current) return;
      const introParallel = Animated.parallel([
        Animated.timing(opacity, { toValue: maxOpacity, duration: 1500, useNativeDriver: true }),
        Animated.spring(scale, { toValue: 1, friction: 3, tension: 30, useNativeDriver: true }),
      ]);
      const intro = Animated.sequence([
        Animated.delay(Math.random() * 2000),
        introParallel,
      ]);
      activeAnimRef.current = intro;
      intro.start(() => {
        const twinkle = () => {
          if (!mountedRef.current) return;
          const d1 = twinkleSpeed[0] + Math.random() * (twinkleSpeed[1] - twinkleSpeed[0]);
          const d2 = twinkleSpeed[0] + Math.random() * (twinkleSpeed[1] - twinkleSpeed[0]);
          const seq = Animated.sequence([
            Animated.timing(opacity, { toValue: minOpacity + Math.random() * (maxOpacity - minOpacity) * 0.5, duration: d1, useNativeDriver: true }),
            Animated.timing(opacity, { toValue: maxOpacity - Math.random() * (maxOpacity - minOpacity) * 0.3, duration: d2, useNativeDriver: true }),
          ]);
          activeAnimRef.current = seq;
          seq.start(twinkle);
        };
        twinkle();
      });
    };
    animate();
    return () => {
      mountedRef.current = false;
      activeAnimRef.current?.stop();
    };
  }, []);

  return (
    <Animated.View
      style={[
        styles.star,
        {
          left: x,
          top: y,
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: color,
          shadowColor: glowColor,
          shadowRadius: size * 1.5,
          opacity,
          transform: [{ scale }],
        },
      ]}
    />
  );
}

// ─── 流星组件 ────────────────────────────────────────────────────
function ShootingStar({ delay: initialDelay, screenW, screenH }: { delay: number; screenW: number; screenH: number }) {
  const translateX = useRef(new Animated.Value(-100)).current;
  const translateY = useRef(new Animated.Value(-100)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const tailScale = useRef(new Animated.Value(0)).current;
  const mountedRef = useRef(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    mountedRef.current = true;
    const animate = () => {
      if (!mountedRef.current) return;
      const startX = Math.random() * screenW * 0.5;
      const startY = Math.random() * screenH * 0.3;
      const distance = 0.4 + Math.random() * 0.4;
      const endX = startX + screenW * distance;
      const endY = startY + screenH * distance * 0.6;
      const duration = 600 + Math.random() * 400;

      translateX.setValue(startX);
      translateY.setValue(startY);

      const shotAnim = [
        Animated.delay(initialDelay + Math.random() * 10000),
        Animated.parallel([
          Animated.timing(opacity, { toValue: 1, duration: 50, useNativeDriver: true }),
          Animated.timing(tailScale, { toValue: 1, duration: 100, useNativeDriver: true }),
        ]),
        Animated.parallel([
          Animated.timing(translateX, { toValue: endX, duration, useNativeDriver: true }),
          Animated.timing(translateY, { toValue: endY, duration, useNativeDriver: true }),
        ]),
        Animated.parallel([
          Animated.timing(opacity, { toValue: 0, duration: 200, useNativeDriver: true }),
          Animated.timing(tailScale, { toValue: 0, duration: 200, useNativeDriver: true }),
        ]),
      ];
      Animated.sequence(shotAnim).start(() => {
        if (!mountedRef.current) return;
        timerRef.current = setTimeout(animate, 3000 + Math.random() * 8000);
      });
    };
    animate();
    return () => { mountedRef.current = false; if (timerRef.current) clearTimeout(timerRef.current); };
  }, []);

  return (
    <Animated.View
      style={[
        styles.shootingStar,
        {
          opacity,
          transform: [{ translateX }, { translateY }, { rotate: '35deg' }],
        },
      ]}
    >
      <View style={styles.shootingStarHead} />
      <Animated.View style={[styles.shootingStarTail, { transform: [{ scaleX: tailScale }] }]} />
    </Animated.View>
  );
}

// ─── 星座连线生成 ────────────────────────────────────────────────
function generateConstellations(stars: StarProps[]): ConstellationLine[] {
  if (stars.length < 2) return [];

  const lines: ConstellationLine[] = [];
  const maxDist = 180;
  const used = new Set<number>();
  const groups: StarProps[][] = [];

  for (let i = 0; i < stars.length; i++) {
    if (used.has(i)) continue;
    const group: StarProps[] = [stars[i]];
    used.add(i);

    for (let j = 0; j < stars.length; j++) {
      if (used.has(j)) continue;
      const last = group[group.length - 1];
      const dist = Math.sqrt((last.x - stars[j].x) ** 2 + (last.y - stars[j].y) ** 2);
      if (dist < maxDist && group.length < 4) {
        group.push(stars[j]);
        used.add(j);
      }
    }
    if (group.length >= 2) groups.push(group);
  }

  for (const group of groups) {
    for (let i = 0; i < group.length - 1; i++) {
      lines.push({
        x1: group[i].x,
        y1: group[i].y,
        x2: group[i + 1].x,
        y2: group[i + 1].y,
      });
    }
    if (group.length >= 3 && Math.random() > 0.4) {
      lines.push({
        x1: group[0].x,
        y1: group[0].y,
        x2: group[group.length - 1].x,
        y2: group[group.length - 1].y,
      });
    }
  }

  return lines;
}

