export default function StarfieldBackground() {
  const { width: screenW, height: screenH } = useWindowDimensions();
  const scaleX = screenW / INITIAL_WIDTH;
  const scaleY = screenH / INITIAL_HEIGHT;
  const allStars = useRef<StarProps[]>(
    LAYERS.flatMap(layer =>
      Array.from({ length: layer.count }, () => {
        const { color, glowColor } = getStarColor();
        return {
          x: Math.random() * INITIAL_WIDTH,
          y: Math.random() * INITIAL_HEIGHT,
          size: layer.minSize + Math.random() * (layer.maxSize - layer.minSize),
          minOpacity: layer.minOpacity,
          maxOpacity: layer.maxOpacity,
          twinkleSpeed: layer.twinkleSpeed,
          color,
          glowColor,
        };
      })
    )
  ).current;

  // Scale star positions to current dimensions (star sizes stay constant)
  const scaledStars = useMemo(
    () => allStars.map(s => ({ ...s, x: s.x * scaleX, y: s.y * scaleY })),
    [scaleX, scaleY]
  );

  const brightStars = useMemo(() => scaledStars.filter(s => s.size >= 4), [scaledStars]);
  const normalStars = useMemo(() => scaledStars.filter(s => s.size < 4), [scaledStars]);
  // 低端设备跳过星座连线计算
  // NOTE: isLowEndDevice is a module-level constant — including it in deps is harmless
  // but unnecessary. Kept for clarity that the computation depends on device capability.
  const constellationLines = useMemo(
    () => isLowEndDevice ? [] : generateConstellations(brightStars),
    [brightStars] // eslint-disable-line react-hooks/exhaustive-deps -- isLowEndDevice is constant
  );

  return (
    <View style={styles.container} pointerEvents="none">
      {/* 星座连线层（低端设备跳过） */}
      {!isLowEndDevice && (
        <Svg
          style={StyleSheet.absoluteFill}
          width={screenW}
          height={screenH}
        >
          {constellationLines.map((line, index) => (
            <Line
              key={`line-${index}`}
              x1={line.x1}
              y1={line.y1}
              x2={line.x2}
              y2={line.y2}
              stroke={CONSTELLATION_LINE_COLOR}
              strokeWidth={0.5}
            />
          ))}
        </Svg>
      )}

      {/* 普通星星层 */}
      {normalStars.map((star, index) => (
        <Star key={`star-${index}`} {...star} />
      ))}

      {/* 大亮星层（带十字光芒） */}
      {brightStars.map((star, index) => (
        <BrightStar key={`bright-${index}`} {...star} />
      ))}

      {/* 流星层（最顶层） */}
      {Array.from({ length: SHOOTING_STAR_COUNT }, (_, i) => (
        <ShootingStar key={`shooting-${i}`} delay={2000 + i * 4000} screenW={screenW} screenH={screenH} />
      ))}
    </View>
  );
}

