          <View style={{ backgroundColor: active ? 'rgba(255,255,255,.3)' : `${c}20`, paddingHorizontal:5, paddingVertical:1, borderRadius:8 }}>
            <Text style={{ color: active ? activeText : c, fontSize: FONT_SMALL(), fontWeight:'600' }}>{count}</Text>
          </View>
