// ─── SQL Helper Functions ──────────────────────────────────────────
// Centralized SQL utilities for safe parameterized queries.
// Prevents SQL injection by validating column/table names.

import type { SQLiteDatabase } from 'expo-sqlite';

/** Validate that a name contains only safe characters (alphanumeric + underscore). */
export function isValidSqlName(name: string): boolean {
  return /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name);
}

/** Build a parameterized SET clause from column names.
 *  Returns { clause, values } for use with db.runAsync.
 *  Throws if any column name contains invalid characters. */
export function buildSetClause(
  columns: string[],
  values: (string | number | null)[],
): { clause: string; values: (string | number | null)[] } {
  for (const col of columns) {
    if (!isValidSqlName(col)) {
      throw new Error(`Invalid SQL column name: ${col}`);
    }
  }
  const clause = columns.map(c => `${c}=?`).join(',');
  return { clause, values };
}

/** Build a parameterized INSERT statement.
 *  Returns the full SQL string and values array. */
export function buildInsertStatement(
  table: string,
  columns: string[],
  values: (string | number | null)[],
): { sql: string; values: (string | number | null)[] } {
  if (!isValidSqlName(table)) {
    throw new Error(`Invalid SQL table name: ${table}`);
  }
  for (const col of columns) {
    if (!isValidSqlName(col)) {
      throw new Error(`Invalid SQL column name: ${col}`);
    }
  }
  const placeholders = columns.map(() => '?').join(',');
  const sql = `INSERT INTO ${table} (${columns.join(',')}) VALUES (${placeholders})`;
  return { sql, values };
}

/** Build a parameterized UPDATE statement with SET clause. */
export function buildUpdateStatement(
  table: string,
  setColumns: string[],
  setValues: (string | number | null)[],
  whereColumn: string,
  whereValue: string | number,
): { sql: string; values: (string | number | null)[] } {
  if (!isValidSqlName(table)) {
    throw new Error(`Invalid SQL table name: ${table}`);
  }
  if (!isValidSqlName(whereColumn)) {
    throw new Error(`Invalid SQL where column: ${whereColumn}`);
  }
  const { clause, values } = buildSetClause(setColumns, setValues);
  const sql = `UPDATE ${table} SET ${clause} WHERE ${whereColumn}=?`;
  return { sql, values: [...values, whereValue] };
}

/** Build a parameterized DELETE statement with IN clause. */
export function buildDeleteInStatement(
  table: string,
  column: string,
  ids: (string | number)[],
): { sql: string; values: (string | number)[] } {
  if (!isValidSqlName(table)) {
    throw new Error(`Invalid SQL table name: ${table}`);
  }
  if (!isValidSqlName(column)) {
    throw new Error(`Invalid SQL column name: ${column}`);
  }
  if (!ids.length) {
    throw new Error('buildDeleteInStatement: ids array is empty');
  }
  const placeholders = ids.map(() => '?').join(',');
  const sql = `DELETE FROM ${table} WHERE ${column} IN (${placeholders})`;
  return { sql, values: ids };
}

/** Build a parameterized SELECT statement with IN clause. */
export function buildSelectInStatement<T>(
  table: string,
  column: string,
  ids: (string | number)[],
  selectColumns = '*',
): { sql: string; values: (string | number)[] } {
  if (!isValidSqlName(table)) {
    throw new Error(`Invalid SQL table name: ${table}`);
  }
  if (!isValidSqlName(column)) {
    throw new Error(`Invalid SQL column name: ${column}`);
  }
  if (!ids.length) {
    throw new Error('buildSelectInStatement: ids array is empty');
  }
  const placeholders = ids.map(() => '?').join(',');
  const sql = `SELECT ${selectColumns} FROM ${table} WHERE ${column} IN (${placeholders})`;
  return { sql, values: ids };
}

/** Sync queue UPSERT SQL — safe for concurrent access.
 *  When a 'syncing' item is overwritten, preserves the in-flight operation/status
 *  but updates the payload so the next sync round picks up the latest data.
 *  Exception: 'delete' operations always win to prevent data resurrection. */
export const SYNC_QUEUE_UPSERT_SQL = `INSERT INTO sync_queue (entity, entity_id, operation, payload, created_at, status)
  VALUES (?, ?, ?, ?, ?, ?)
  ON CONFLICT(entity, entity_id) DO UPDATE SET
    operation = CASE WHEN excluded.operation = 'delete' THEN 'delete' WHEN sync_queue.status = 'syncing' THEN sync_queue.operation ELSE excluded.operation END,
    payload = excluded.payload,
    created_at = CASE WHEN sync_queue.status = 'syncing' AND excluded.operation != 'delete' THEN sync_queue.created_at ELSE excluded.created_at END,
    status = CASE WHEN excluded.operation = 'delete' THEN 'pending' WHEN sync_queue.status = 'syncing' THEN 'syncing' ELSE 'pending' END,
    retry_count = CASE WHEN sync_queue.status = 'syncing' AND excluded.operation != 'delete' THEN sync_queue.retry_count ELSE 0 END,
    next_retry_at = 0,
    last_error = NULL`;

// ─── Mobile sync queue (SQLite-backed) ──────────────────────────
import type { SyncEntity } from '@egoless-do/core';
import { createLogger } from '@egoless-do/core';

import { openDatabase, withDbLock } from './schema';
import { buildDeleteInStatement, buildSelectInStatement, SYNC_QUEUE_UPSERT_SQL } from './sqlHelper';

const log = createLogger('DB');

const MAX_QUEUE_SIZE = 2000; // Increased from 1000 for better offline capacity
const QUEUE_WARN_SIZE = 1500; // Warn user when queue reaches this threshold

// Callback triggered after successful enqueue (set by SyncService)
let _onEnqueued: (() => void) | null = null;
export function setOnEnqueuedCallback(fn: () => void) { _onEnqueued = fn; }

export interface SyncQueueItem {
  id: number;
  entity: SyncEntity;
  entity_id: string;
  operation: 'upsert' | 'delete';
  payload: string;
  created_at: number;
  retry_count: number;
  last_error: string | null;
  status: 'pending' | 'syncing' | 'failed' | 'conflict';
  next_retry_at: number;
}

/** Enqueue a change for later sync. Deduplicates by (entity, entity_id) atomically. */
export async function enqueueChange(
  entity: SyncEntity,
  entityId: string,
  operation: 'upsert' | 'delete',
  payload: unknown,
): Promise<void> {
  try {
    const db = await openDatabase();
    // Evict + insert atomically to prevent race conditions
    await withDbLock(async () => {
      const count = await db.getFirstAsync<{ c: number }>('SELECT COUNT(*) as c FROM sync_queue');
      if ((count?.c ?? 0) >= MAX_QUEUE_SIZE) {
        await db.runAsync("DELETE FROM sync_queue WHERE id = (SELECT id FROM sync_queue WHERE status != 'syncing' ORDER BY created_at ASC LIMIT 1)");
        log.warn(`Queue full (${MAX_QUEUE_SIZE}), evicted oldest item for ${entity}:${entityId}`);
      }
      await db.runAsync(
        SYNC_QUEUE_UPSERT_SQL,
        [entity, entityId, operation, JSON.stringify(payload), Date.now(), 'pending'],
      );
    });
    // Trigger debounced sync after successful enqueue
    _onEnqueued?.();
  } catch (err) {
    log.error(err, { message: 'enqueue failed' });
    throw err;
  }
}

/** Drain up to `limit` pending items from the queue, ordered by creation time. Atomically marks them as 'syncing'. */
export async function drainQueue(limit = 50): Promise<SyncQueueItem[]> {
  const db = await openDatabase();
  const now = Date.now();
  return withDbLock(async () => {
    const items = await db.getAllAsync<SyncQueueItem>(
      "SELECT * FROM sync_queue WHERE status = 'pending' AND (next_retry_at = 0 OR next_retry_at <= ?) ORDER BY id LIMIT ?",
      [now, limit],
    );
    if (items.length > 0) {
      const ids = items.map(i => i.id);
      const placeholders = ids.map(() => '?').join(',');
      await db.runAsync(
        `UPDATE sync_queue SET status = 'syncing' WHERE id IN (${placeholders}) AND status = 'pending'`,
        ids,
      );
    }
    return items;
  });
}

/** Get all items with a specific status. */
export async function getQueueItemsByStatus(
  status: SyncQueueItem['status'],
  limit = 100,
): Promise<SyncQueueItem[]> {
  const db = await openDatabase();
  return db.getAllAsync<SyncQueueItem>(
    'SELECT * FROM sync_queue WHERE status = ? ORDER BY id LIMIT ?',
    [status, limit],
  );
}

/** Remove processed queue items by their IDs. */
export async function removeQueueItems(ids: number[]): Promise<void> {
  if (!ids.length) return;
  const db = await openDatabase();
  const { sql, values } = buildDeleteInStatement('sync_queue', 'id', ids);
  await db.runAsync(sql, values);
}

/** Mark a queue item as failed with error message. */
export async function markQueueItemFailed(id: number, error: string): Promise<void> {
  const db = await openDatabase();
  await db.runAsync(
    "UPDATE sync_queue SET status = 'failed', last_error = ?, retry_count = retry_count + 1 WHERE id = ?",
    [error, id],
  );
}

/** Mark a queue item for retry with backoff delay. Resets status to pending. */
export async function markQueueItemRetry(id: number, attempt: number, nextRetryAt: number): Promise<void> {
  const db = await openDatabase();
  await db.runAsync(
    "UPDATE sync_queue SET status = 'pending', retry_count = ?, next_retry_at = ? WHERE id = ?",
    [attempt, nextRetryAt, id],
  );
}

/** Mark a queue item as conflict (increments retry_count to prevent infinite retry loops). */
export async function markQueueItemConflict(id: number, error: string): Promise<void> {
  const db = await openDatabase();
  await db.runAsync(
    "UPDATE sync_queue SET status = 'conflict', last_error = ?, retry_count = retry_count + 1 WHERE id = ?",
    [error, id],
  );
}

/** Reset failed/conflict items back to pending for retry. */
export async function resetQueueItemsForRetry(ids: number[]): Promise<void> {
  if (!ids.length) return;
  const db = await openDatabase();
  const { sql, values } = buildSelectInStatement('sync_queue', 'id', ids);
  // Use the IN clause to build the UPDATE
  const inClause = sql.replace('SELECT * FROM sync_queue WHERE id IN ', 'id IN');
  await db.runAsync(
    `UPDATE sync_queue SET status = 'pending', last_error = NULL WHERE ${inClause} AND retry_count < 5`,
    values,
  );
}

/** Reset failed/conflict items back to pending for retry. Batched to prevent push storms. */
export async function resetAllPendingForRetry(batchSize = 50): Promise<number> {
  const db = await openDatabase();
  const result = await db.runAsync(
    `UPDATE sync_queue SET status = 'pending', next_retry_at = 0
     WHERE id IN (SELECT id FROM sync_queue WHERE status IN ('failed', 'conflict', 'syncing')
                  AND retry_count < 10
                  ORDER BY created_at LIMIT ?)`,
    [batchSize],
  );
  return result.changes;
}

/** Get the count of pending queue items. */
export async function getQueueCount(): Promise<number> {
  const db = await openDatabase();
  const row = await db.getFirstAsync<{ count: number }>(
    "SELECT COUNT(*) as count FROM sync_queue WHERE status = 'pending'",
  );
  return row?.count ?? 0;
}

/** Get the count of all non-resolved queue items. */
export async function getTotalQueueCount(): Promise<number> {
  const db = await openDatabase();
  const row = await db.getFirstAsync<{ count: number }>(
    "SELECT COUNT(*) as count FROM sync_queue WHERE status != 'syncing'",
  );
  return row?.count ?? 0;
}

/** Clear all queue items. */
export async function clearQueue(): Promise<void> {
  const db = await openDatabase();
  await db.runAsync('DELETE FROM sync_queue');
}

/**
 * Remove stale queue items.
 * - Failed/conflict items older than 7 days are removed (shorter window to avoid stale retries).
 * - Default maxAgeMs is 7 days (was 30 days).
 */
export async function pruneStaleQueueItems(maxAgeMs = 7 * 24 * 60 * 60 * 1000): Promise<number> {
  const db = await openDatabase();
  const cutoff = Date.now() - maxAgeMs;
  const result = await db.runAsync(
    "DELETE FROM sync_queue WHERE created_at < ? AND (status = 'failed' OR status = 'conflict')",
    [cutoff]
  );
  return result.changes;
}

// ── Sync metadata helpers ────────────────────────────────────────

/** Get the last sync timestamp for an entity. */
export async function getLastSyncTimestamp(entity: string): Promise<string> {
  const db = await openDatabase();
  const row = await db.getFirstAsync<{ last_sync_timestamp: string }>(
    'SELECT last_sync_timestamp FROM sync_metadata WHERE entity = ?',
    [entity],
  );
  return row?.last_sync_timestamp ?? '1970-01-01T00:00:00.000Z';
}

/** Update the last sync timestamp for an entity. */
export async function setLastSyncTimestamp(entity: string, timestamp: string): Promise<void> {
  const db = await openDatabase();
  await db.runAsync(
    `INSERT INTO sync_metadata (entity, last_sync_timestamp, last_sync_status, updated_at)
     VALUES (?, ?, 'success', datetime('now'))
     ON CONFLICT(entity) DO UPDATE SET last_sync_timestamp = ?, last_sync_status = 'success', updated_at = datetime('now')`,
    [entity, timestamp, timestamp],
  );
}

/** Get all sync metadata entries. */
export async function getAllSyncMetadata(): Promise<Array<{ entity: string; last_sync_timestamp: string; last_sync_status: string }>> {
  const db = await openDatabase();
  return db.getAllAsync<{ entity: string; last_sync_timestamp: string; last_sync_status: string }>(
    'SELECT * FROM sync_metadata',
  );
}

// ── Sync progress (for phased initial sync) ──────────────────────

export interface SyncProgressRow {
  entity: string;
  phase: number;
  status: 'pending' | 'downloading' | 'done' | 'failed';
  pulled_count: number;
  total_count: number;
  last_page: number;
  last_error: string | null;
  retry_count: number;
  next_retry_at: number;
  updated_at: number;
}

/** Get sync progress for a specific entity. */
export async function getSyncProgress(entity: string): Promise<SyncProgressRow | null> {
  const db = await openDatabase();
  return db.getFirstAsync<SyncProgressRow>(
    'SELECT * FROM sync_progress WHERE entity = ?',
    [entity],
  );
}

/** Get all sync progress entries. */
export async function getAllSyncProgress(): Promise<SyncProgressRow[]> {
  const db = await openDatabase();
  return db.getAllAsync<SyncProgressRow>('SELECT * FROM sync_progress ORDER BY phase, entity');
}

/** Upsert sync progress for an entity. */
export async function updateSyncProgress(entity: string, fields: Partial<Omit<SyncProgressRow, 'entity'>>): Promise<void> {
  const db = await openDatabase();
  const allowedFields = new Set(['phase', 'status', 'pulled_count', 'total_count', 'last_page', 'last_error', 'retry_count', 'next_retry_at']);
  // Always include required fields with defaults for INSERT
  const cols = ['entity', 'updated_at', 'phase', 'status'];
  const vals: (string | number)[] = [entity, Date.now(), 0, 'pending'];
  for (const [key, value] of Object.entries(fields)) {
    if (value !== undefined && allowedFields.has(key)) {
      // Override default if provided
      const idx = cols.indexOf(key);
      if (idx >= 0) {
        vals[idx] = value as string | number;
      } else {
        cols.push(key);
        vals.push(value as string | number);
      }
    }
  }
  const placeholders = cols.map(() => '?').join(',');
  const updateCols = cols.filter(c => c !== 'entity');
  const updateSets = updateCols.map(c => `${c} = excluded.${c}`).join(', ');
  await db.runAsync(
    `INSERT INTO sync_progress (${cols.join(',')}) VALUES (${placeholders})
     ON CONFLICT(entity) DO UPDATE SET ${updateSets}`,
    vals,
  );
}

/** Reset all sync progress (called before a new initial sync). */
export async function resetSyncProgress(): Promise<void> {
  const db = await openDatabase();
  await db.runAsync('DELETE FROM sync_progress');
}

import { apiCheckEmail, apiSendCode, apiResetPassword, validatePassword, FONT_TITLE, FONT_SUB, FONT_BUTTON, FONT_ERROR, FONT_STAT_SECTION } from '@egoless-do/core';
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { View, Text, TouchableOpacity, KeyboardAvoidingView, Platform, ScrollView } from 'react-native';

import { useTheme, useT, PrimaryButton, ThemedInput, Card } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';

const COOLDOWN = 60;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function ForgotPasswordScreen() {
  const TH = useTheme();
  const T = useT();
  const nav = useRootNavigation();

  const [email, setEmail] = useState('');
  const [code, setCode] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const navTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [sending, setSending] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [step, setStep] = useState<1 | 2>(1);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    return () => { if (navTimerRef.current) clearTimeout(navTimerRef.current); };
  }, []);

  const startCooldown = useCallback(() => {
    setCooldown(COOLDOWN);
    timerRef.current = setInterval(() => {
      setCooldown(prev => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  }, []);

  useEffect(() => {
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, []);

  const handleSendCode = async () => {
    if (!email || !EMAIL_REGEX.test(email)) {
      setError(T('authInvalidEmailAddr'));
      return;
    }
    setError('');
    setSending(true);
    try {
      const checkRes = await apiCheckEmail(email);
      if (checkRes.available) {
        setError(T('authEmailNotRegisteredShort'));
        return;
      }
      await apiSendCode(email, 'reset');
      startCooldown();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : T('authSendFailed'));
    } finally {
      setSending(false);
    }
  };

  const handleVerifyCode = () => {
    setError('');
    if (!code.trim()) {
      setError(T('authEnterVerifyCode'));
      return;
    }
    setStep(2);
  };

  const handleResetPassword = async () => {
    setError('');
    const pwdErr = validatePassword(password);
    if (pwdErr) {
      setError(pwdErr);
      return;
    }
    if (password !== confirm) {
      setError(T('authPasswordMismatch'));
      return;
    }

    setLoading(true);
    try {
      await apiResetPassword(email, code, password);
      setSuccess(T('authResetSuccess'));
      navTimerRef.current = setTimeout(() => nav.navigate('Login'), 1500);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : T('authResetFailed'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={{ flex: 1, backgroundColor: TH.bg }}
    >
      <ScrollView
        contentContainerStyle={{ flexGrow: 1, justifyContent: 'center' }}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        <View style={{ paddingHorizontal: 24 }}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', textAlign: 'center', marginBottom: 4, color: TH.text }}>心流纪</Text>
          <Text style={{ fontSize: FONT_SUB(), color: TH.primary, textAlign: 'center', marginBottom: 8, letterSpacing: 1 }}>Egoless Do</Text>
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, textAlign: 'center', marginBottom: 32 }}>
            {step === 1 ? T('authVerifyEmail') : T('authSetNewPassword')}
          </Text>

          <Card style={{ marginBottom: 16 }}>
            {step === 1 ? (
              <>
                <ThemedInput
                  value={email}
                  onChangeText={setEmail}
                  placeholder={T('authEmailPlaceholder')}
                  keyboardType="email-address"
                  autoCapitalize="none"
                  style={{ marginBottom: 12 }}
                />
                <View style={{ flexDirection: 'row', gap: 10, marginBottom: 12 }}>
                  <View style={{ flex: 1 }}>
                    <ThemedInput
                      value={code}
                      onChangeText={setCode}
                      placeholder={T('authVerifyCodePlaceholder')}
                      keyboardType="number-pad"
                      maxLength={6}
                      style={{ marginBottom: 0 }}
                    />
                  </View>
                  <TouchableOpacity
                    onPress={handleSendCode}
                    disabled={sending || cooldown > 0}
                    style={{
                      paddingHorizontal: 16, borderRadius: 10,
                      backgroundColor: sending || cooldown > 0 ? 'rgba(129,140,248,.3)' : TH.primary,
                      justifyContent: 'center', alignItems: 'center', opacity: sending || cooldown > 0 ? 0.6 : 1,
                    }}
                  >
                    <Text style={{ color: '#fff', fontSize: FONT_SUB(), fontWeight: '600' }}>
                      {cooldown > 0 ? `${cooldown}s` : sending ? T('authSending') : T('authSendCode')}
                    </Text>
                  </TouchableOpacity>
                </View>
              </>
            ) : (
              <>
                <ThemedInput
                  value={password}
                  onChangeText={setPassword}
                  placeholder={T('authNewPasswordPlaceholder')}
                  secureTextEntry
                  style={{ marginBottom: 12 }}
                />
                <ThemedInput
                  value={confirm}
                  onChangeText={setConfirm}
                  placeholder={T('authConfirmNewPasswordPlaceholder')}
                  secureTextEntry
                  style={{ marginBottom: 4 }}
                />
              </>
            )}
          </Card>

          {error !== '' && (
            <Text style={{ color: '#ff6b6b', fontSize: FONT_ERROR(), textAlign: 'center', marginBottom: 12 }}>
              {error}
            </Text>
          )}
          {success !== '' && (
            <Text style={{ color: '#10b981', fontSize: FONT_SUB(), textAlign: 'center', marginBottom: 12 }}>
              {success}
            </Text>
          )}

          <PrimaryButton
            label={step === 1 ? T('authNextStep') : loading ? T('authResetting') : T('authResetPassword')}
            onPress={step === 1 ? handleVerifyCode : handleResetPassword}
            style={{ marginBottom: 16, opacity: loading ? 0.7 : 1 }}
          />

          <TouchableOpacity onPress={() => nav.navigate('Login')} activeOpacity={0.7}>
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center' }}>
              <Text style={{ color: TH.primary }}>{T('authBackToLogin')}</Text>
            </Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

import { FONT_TITLE, FONT_SUB, FONT_BUTTON, FONT_ERROR, FONT_STAT_SECTION, createLogger, MFARequiredError } from '@egoless-do/core';
import { Image } from 'expo-image';
import React, { useState } from 'react';
import { View, Text, TouchableOpacity, KeyboardAvoidingView, Platform, ScrollView, ImageRequireSource } from 'react-native';
import { useShallow } from 'zustand/react/shallow';

import { useTheme, useT, PrimaryButton, ThemedInput, Card } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, type MobileStore } from '../../store/useAppStore';

import { registerExpoPushToken } from './pushTokenRegistration';

const log = createLogger('Auth');

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function LoginScreen() {
  const TH = useTheme();
  const T = useT();
  const nav = useRootNavigation();
  const login = useAppStore(useShallow((s: MobileStore) => s.login));
  const isLoading = useAppStore(useShallow((s: MobileStore) => s.auth.isLoading));

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [emailError, setEmailError] = useState('');
  // MFA step-up state
  const [mfaToken, setMfaToken] = useState<string | null>(null);
  const [mfaCode, setMfaCode] = useState('');
  const [mfaError, setMfaError] = useState('');

  const navigateAfterLogin = () => {
    nav.reset({ index: 0, routes: [{ name: 'MainTabs' }] });
    const token = useAppStore.getState().auth.token;
    if (token) {
      setTimeout(() => { void registerExpoPushToken(token); }, 0);
    }
  };

  const handleEmailBlur = () => {
    if (email && !EMAIL_REGEX.test(email)) {
      setEmailError(T('authInvalidEmail'));
    } else {
      setEmailError('');
    }
  };

  const handleEmailChange = (text: string) => {
    setEmail(text);
    // Real-time format validation on change
    if (emailError) {
      setEmailError(text && !EMAIL_REGEX.test(text) ? T('authInvalidEmail') : '');
    }
  };

  const handleLogin = async () => {
    setError('');
    if (!email.trim() || !password.trim()) {
      setError(T('authFillEmailPassword'));
      return;
    }
    if (email && !EMAIL_REGEX.test(email)) {
      setEmailError(T('authInvalidEmail'));
      return;
    }
    try {
      await login(email.trim(), password);
      navigateAfterLogin();
    } catch (e: unknown) {
      // MFA step-up: server requires a second factor. Switch to MFA input view.
      if (e instanceof MFARequiredError) {
        setMfaToken(e.mfaToken);
        setMfaCode('');
        setMfaError('');
        return;
      }
      // Don't reveal whether email exists — show generic error
      setError(T('authLoginFailed'));
    }
  };

  const handleVerifyMfa = async () => {
    setMfaError('');
    if (!mfaToken || !mfaCode.trim()) {
      setMfaError(T('authMfaCodePlaceholder'));
      return;
    }
    try {
      await useAppStore.getState().verifyMfaLogin(mfaToken, mfaCode.trim());
      navigateAfterLogin();
    } catch {
      setMfaError(T('authMfaInvalid'));
    }
  };

  // ── MFA challenge view ──
  if (mfaToken) {
    return (
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        style={{ flex: 1, backgroundColor: TH.bg }}
      >
        <ScrollView
          contentContainerStyle={{ flexGrow: 1, justifyContent: 'center' }}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={{ paddingHorizontal: 24 }}>
            <Text style={{ color: TH.primary, fontSize: FONT_TITLE(), textAlign: 'center', marginBottom: 24 }}>
              {T('authMfaRequired')}
            </Text>
            <Card style={{ marginBottom: 16 }}>
              <ThemedInput
                value={mfaCode}
                onChangeText={setMfaCode}
                placeholder={T('authMfaCodePlaceholder')}
                keyboardType="number-pad"
                maxLength={6}
                style={{ marginBottom: mfaError ? 4 : 0, ...(mfaError ? { borderColor: '#ef4444' } : {}) }}
              />
            </Card>
            {mfaError !== '' && (
              <Text style={{ color: '#ff6b6b', fontSize: FONT_ERROR(), textAlign: 'center', marginBottom: 12 }}>
                {mfaError}
              </Text>
            )}
            <PrimaryButton
              label={isLoading ? T('authMfaVerifying') : T('authMfaVerifyBtn')}
              onPress={handleVerifyMfa}
              style={{ marginBottom: 16, opacity: isLoading ? 0.7 : 1 }}
            />
            <TouchableOpacity
              onPress={() => { setMfaToken(null); setMfaCode(''); setMfaError(''); }}
              activeOpacity={0.7}
            >
              <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center' }}>
                {T('authForgotPassword')}
              </Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    );
  }

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={{ flex: 1, backgroundColor: TH.bg }}
    >
      <ScrollView
        contentContainerStyle={{ flexGrow: 1, justifyContent: 'center' }}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        <View style={{ paddingHorizontal: 24 }}>
          <Image
            source={require('../../../assets/sign-logo.png') as ImageRequireSource}
            style={{
              width: 320,
              height: 128,
              alignSelf: 'center',
              marginBottom: 40,
            }}
            contentFit="contain"
          />

          <Card style={{ marginBottom: 16 }}>
            <ThemedInput
              value={email}
              onChangeText={handleEmailChange}
              onBlur={handleEmailBlur}
              placeholder={T('authEmailPlaceholder')}
              keyboardType="email-address"
              autoCapitalize="none"
              style={{ marginBottom: emailError ? 4 : 12, ...(emailError ? { borderColor: '#ef4444' } : {}) }}
            />
            {emailError ? (
              <Text style={{ color: '#ef4444', fontSize: FONT_ERROR(), marginBottom: 12 }}>{emailError}</Text>
            ) : null}
            <ThemedInput
              value={password}
              onChangeText={setPassword}
              placeholder={T('authPasswordPlaceholder')}
              secureTextEntry
              style={{ marginBottom: 4 }}
            />
          </Card>

          {error !== '' && (
            <Text style={{ color: '#ff6b6b', fontSize: FONT_ERROR(), textAlign: 'center', marginBottom: 12 }}>
              {error}
            </Text>
          )}

          <PrimaryButton
            label={isLoading ? T('authLoginLoading') : T('authLoginBtn')}
            onPress={handleLogin}
            style={{ marginBottom: 16, opacity: isLoading ? 0.7 : 1 }}
          />

          <TouchableOpacity onPress={() => nav.navigate('Register')} activeOpacity={0.7}>
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', marginBottom: 12 }}>
              {T('authNoAccount')}<Text style={{ color: TH.primary }}>{T('authGoRegister')}</Text>
            </Text>
          </TouchableOpacity>

          <TouchableOpacity onPress={() => nav.navigate('ForgotPassword')} activeOpacity={0.7}>
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center' }}>
              <Text style={{ color: TH.primary }}>{T('authForgotPassword')}</Text>
            </Text>
          </TouchableOpacity>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

import { apiSendCode, validatePassword, FONT_SUB, FONT_BUTTON, FONT_ERROR } from '@egoless-do/core';
import { Image } from 'expo-image';
import React, { useState, useRef, useCallback, useEffect } from 'react';
import { View, Text, TouchableOpacity, KeyboardAvoidingView, Platform, ScrollView } from 'react-native';
import { useShallow } from 'zustand/react/shallow';

import { useTheme, useT, PrimaryButton, ThemedInput, Card } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, type MobileStore } from '../../store/useAppStore';


const COOLDOWN = 60;

