import { EXERCISE_SOUNDS } from '@egoless-do/core';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { useState, useEffect, useCallback, useRef } from 'react';

import { audioSessionManager } from '../../../services/AudioSessionManager';

const SOUND_FILES: Record<string, number> = {
  '海潮': require('../../../../assets/sounds/ocean.mp3') as number,
  '雨声': require('../../../../assets/sounds/rain.mp3') as number,
  '钵声': require('../../../../assets/sounds/bowl.mp3') as number,
  '鸟叫': require('../../../../assets/sounds/birds.mp3') as number,
  '流水': require('../../../../assets/sounds/flowing-stream.mp3') as number,
  '风铃': require('../../../../assets/sounds/wind-chimes.mp3') as number,
};
const BELL_FILE = require('../../../../assets/sounds/temple_bell.mp3') as number;

export function useExerciseAudio() {
  const [selectedSound, setSelectedSound] = useState<string>('无');
  const [showSoundPicker, setShowSoundPicker] = useState(false);
  const shouldAutoPlayRef = useRef(false);

  // 环境音播放器
  const bgSource = SOUND_FILES[selectedSound];
  const bgPlayer = useAudioPlayer(bgSource ?? undefined);

  // 钟声播放器（独立，不受管理器影响）
  const bellPlayer = useAudioPlayer(BELL_FILE);

  useEffect(() => {
    bgPlayer.loop = true;
    bgPlayer.volume = 0.25;
  }, [bgPlayer]);

  useEffect(() => {
    bellPlayer.volume = 0.5;
  }, [bellPlayer]);

  // Auto-play when bgPlayer source changes after selectSound
  useEffect(() => {
    if (shouldAutoPlayRef.current) {
      shouldAutoPlayRef.current = false;
      const allowed = audioSessionManager.requestPlay('ambient');
      if (allowed) {
        bgPlayer.play();
      }
    }
  }, [bgSource, bgPlayer, audioSessionManager]);

  // Init audio session + restore last selected sound
  useEffect(() => {
    setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: false }).catch(() => {});
    AsyncStorage.getItem('sport_selected_sound').then(v => {
      if (v && EXERCISE_SOUNDS.some(s => s.key === v)) setSelectedSound(v);
    }).catch(() => {});
  }, []);

  // Persist selected sound
  useEffect(() => {
    AsyncStorage.setItem('sport_selected_sound', selectedSound).catch(() => {});
  }, [selectedSound]);

  const playBell = useCallback(() => {
    void bellPlayer.seekTo(0);
    bellPlayer.play();
  }, [bellPlayer]);

  const selectSound = useCallback((key: string) => {
    setSelectedSound(key);

    if (key === '无') {
      shouldAutoPlayRef.current = false;
      bgPlayer.pause();
      audioSessionManager.notifyStopped('ambient');
    } else {
      // Mark for auto-play; actual play happens in useEffect after source updates
      shouldAutoPlayRef.current = true;
    }
    setShowSoundPicker(false);
  }, [bgPlayer]);

  // 环境音和钟声在组件卸载时停止，并通知管理器
  const selectedSoundRef = useRef(selectedSound);
  const bgPlayerRef = useRef(bgPlayer);
  const bellPlayerRef = useRef(bellPlayer);
  useEffect(() => { selectedSoundRef.current = selectedSound; }, [selectedSound]);
  useEffect(() => { bgPlayerRef.current = bgPlayer; }, [bgPlayer]);
  useEffect(() => { bellPlayerRef.current = bellPlayer; }, [bellPlayer]);
  useEffect(() => {
    return () => {
      // remove() releases native resources; best-effort since hook may release first
      try { bgPlayerRef.current.remove(); } catch {}
      try { bellPlayerRef.current.remove(); } catch {}
      if (selectedSoundRef.current !== '无') {
        audioSessionManager.notifyStopped('ambient');
      }
    };
  }, []);

  const cycleSound = useCallback(() => {
    setSelectedSound(prev => {
      const idx = EXERCISE_SOUNDS.findIndex(s => s.key === prev);
      const next = EXERCISE_SOUNDS[(idx + 1) % EXERCISE_SOUNDS.length];
      if (next.key === '无') {
        bgPlayer.pause();
        audioSessionManager.notifyStopped('ambient');
      } else {
        shouldAutoPlayRef.current = true;
      }
      setShowSoundPicker(false);
      return next.key;
    });
  }, [bgPlayer]);

  /** Stop all audio immediately (call on exercise end, not unmount) */
  const stopAll = useCallback(() => {
    try { bgPlayer.pause(); } catch {}
    try { bellPlayer.pause(); } catch {}
    audioSessionManager.notifyStopped('ambient');
  }, [bgPlayer, bellPlayer]);

  // Unmount cleanup — best-effort; stopAll should be called explicitly before navigation
  useEffect(() => {
    return () => {
      try { bgPlayerRef.current.remove(); } catch {}
      try { bellPlayerRef.current.remove(); } catch {}
      if (selectedSoundRef.current !== '无') {
        audioSessionManager.notifyStopped('ambient');
      }
    };
  }, []);

  return {
    selectedSound, setSelectedSound,
    showSoundPicker, setShowSoundPicker,
    bgPlayer, bellPlayer,
    playBell, selectSound, cycleSound, stopAll,
  };
}

import { REP_MILESTONES, TIME_MILESTONES, getSoftTarget, TARGET_PRESETS, getSportType } from '@egoless-do/core';
import type { SportType } from '@egoless-do/core';
import * as Haptics from 'expo-haptics';
import { useState, useRef, useCallback } from 'react';
import { Animated, Easing } from 'react-native';

export interface UseExerciseTargetsParams {
  sportName: string;
  sportType: SportType;
  mode: 'free' | 'target';
  targetType: string;
  targetValue: number;
  sec: number;
  distKm: number;
  calories: number;
  totalReps: number;
  playBell: () => void;
  T: (key: string) => string;
}

export function useExerciseTargets(params: UseExerciseTargetsParams) {
  const { sportName, sportType, mode, targetType, targetValue, sec, distKm, calories, totalReps, playBell, T } = params;

  const reachedMilestonesRef = useRef(new Set<number>());
  const [milestoneText, setMilestoneText] = useState<string | null>(null);
  const milestoneAnim = useRef(new Animated.Value(0)).current;
  const softTargetBellPlayedRef = useRef(false);
  const pulseAnim = useRef(new Animated.Value(0.6)).current;
  const [showCelebration, setShowCelebration] = useState(false);
  const celebrateAnim = useRef(new Animated.Value(0)).current;

  // Pulse animation
  // Caller should start the loop in a useEffect

  // Target progress
  const targetProgress = mode === 'target' ? (() => {
    if (targetValue <= 0) return 0;
    if (targetType === 'distance') return Math.min(distKm / targetValue, 1);
    if (targetType === 'time')     return Math.min(sec / targetValue, 1);
    if (targetType === 'calories') return Math.min(calories / targetValue, 1);
    if (targetType === 'reps')     return Math.min(totalReps / targetValue, 1);
    return 0;
  })() : 0;

  // Soft target
  const softTarget = mode === 'free' ? getSoftTarget(sportName) : undefined;
  const softTargetValue = softTarget ? (softTarget.unit === 'min' ? softTarget.intermediate * 60 : softTarget.intermediate) : 0;
  const softTargetProgress = softTargetValue > 0
    ? Math.min((sportType === 'repetition' ? totalReps : sec) / softTargetValue, 1)
    : 0;
  const softTargetReached = softTargetProgress >= 1;
  const softTargetLabel = softTarget
    ? (softTarget.unit === 'min' ? T('exerciseSoftTargetMin').replace('{n}', String(softTarget.intermediate)) : T('exerciseSoftTargetReps').replace('{n}', String(softTarget.intermediate)))
    : '';

  // Celebration
  const triggerCelebration = useCallback(() => {
    setShowCelebration(true);
    celebrateAnim.setValue(0);
    Animated.sequence([
      Animated.timing(celebrateAnim, { toValue: 1, duration: 300, easing: Easing.out(Easing.back(1.5)), useNativeDriver: true }),
      Animated.delay(600),
      Animated.timing(celebrateAnim, { toValue: 0, duration: 200, useNativeDriver: true }),
    ]).start(() => setShowCelebration(false));
  }, [celebrateAnim]);

  // Check target reached (fire once)
  const targetReachedRef = useRef(false);
  const checkTargetReached = useCallback(() => {
    if (mode !== 'target') return;
    let reached = false;
    if (targetType === 'distance' && distKm >= targetValue) reached = true;
    if (targetType === 'time' && sec >= targetValue) reached = true;
    if (targetType === 'calories' && calories >= targetValue) reached = true;
    if (targetType === 'reps' && totalReps >= targetValue) reached = true;
    if (reached && !targetReachedRef.current) {
      targetReachedRef.current = true;
      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      triggerCelebration();
      playBell();
    }
  }, [mode, targetType, targetValue, sec, distKm, calories, totalReps, triggerCelebration, playBell]);

  // Milestone check
  const checkMilestone = useCallback(() => {
    const milestones = sportType === 'repetition' ? REP_MILESTONES : TIME_MILESTONES;
    const currentValue = sportType === 'repetition' ? totalReps : sec;
    for (const m of milestones) {
      if (currentValue >= m.value && !reachedMilestonesRef.current.has(m.value)) {
        reachedMilestonesRef.current.add(m.value);
        setMilestoneText(m.label);
        void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        playBell();
        milestoneAnim.setValue(0);
        Animated.sequence([
          Animated.timing(milestoneAnim, { toValue: 1, duration: 300, useNativeDriver: true }),
          Animated.delay(1500),
          Animated.timing(milestoneAnim, { toValue: 0, duration: 300, useNativeDriver: true }),
        ]).start(() => setMilestoneText(null));
        break;
      }
    }
  }, [sportType, totalReps, sec, playBell, milestoneAnim]);

  // Soft target bell
  const checkSoftTargetBell = useCallback(() => {
    if (softTargetReached && !softTargetBellPlayedRef.current) {
      softTargetBellPlayedRef.current = true;
      void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      playBell();
    }
    if (!softTargetReached) {
      softTargetBellPlayedRef.current = false;
    }
  }, [softTargetReached, playBell]);

  return {
    targetProgress,
    softTarget, softTargetProgress, softTargetReached, softTargetLabel,
    milestoneText, milestoneAnim,
    showCelebration, celebrateAnim, triggerCelebration,
    pulseAnim,
    checkTargetReached, checkMilestone, checkSoftTargetBell,
  };
}

import * as Haptics from 'expo-haptics';
import { useState, useEffect, useRef, useCallback } from 'react';
import { Animated, Easing } from 'react-native';

export type Page = 'prep' | 'countdown' | 'active' | 'paused' | 'report' | 'transition' | 'combo_report';

export function useExerciseTimer() {
  const [page, setPage]         = useState<Page>('prep');
  const [sec, setSec]           = useState(0);
  const [active, setActive]     = useState(false);
  const [countdown, setCountdown] = useState(3);
  const [pausedSec, setPausedSec] = useState(0);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const holdTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const holdAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const pulseAnim = useRef(new Animated.Value(0)).current;

  // Main timer
  useEffect(() => {
    if (page === 'active' && active) {
      timerRef.current = setInterval(() => setSec(s => s + 1), 1000);
    } else {
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [page, active]);

  // Countdown
  useEffect(() => {
    if (page !== 'countdown') return;
    if (countdown <= 0) {
      setPage('active');
      setActive(true);
      return;
    }
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    const t = setTimeout(() => setCountdown(c => c - 1), 1000);
    return () => clearTimeout(t);
  }, [page, countdown]);

  // Cleanup hold timeout and animation listener on unmount
  useEffect(() => () => {
    if (holdTimeoutRef.current) clearTimeout(holdTimeoutRef.current);
    holdAnim.removeAllListeners();
    holdAnim.stopAnimation();
  }, []);

  const handleGo = useCallback(() => { setCountdown(3); setPage('countdown'); }, []);

  const handlePause = useCallback(() => {
    setActive(false);
    setPage('paused');
  }, []);

  const handleContinue = useCallback(() => {
    setPage('active');
    setActive(true);
  }, []);

  const handleHoldStart = useCallback(() => {
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    holdAnim.setValue(0);
    holdAnim.removeAllListeners();

    // Spring scale: overshoot to 1.2 then settle
    Animated.spring(scaleAnim, {
      toValue: 1.2, damping: 8, stiffness: 200, useNativeDriver: true,
    }).start();

    // Linear progress ring fill over 3s
    const anim = Animated.timing(holdAnim, {
      toValue: 1, duration: 3000, easing: Easing.linear, useNativeDriver: false,
    });
    holdAnim.addListener(({ value }) => {
      if (value >= 1) {
        holdAnim.removeAllListeners();
        void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
        // Pulse wave
        pulseAnim.setValue(0);
        Animated.timing(pulseAnim, { toValue: 1, duration: 400, easing: Easing.out(Easing.ease), useNativeDriver: true }).start();
        // Spring back scale
        Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
        holdTimeoutRef.current = setTimeout(() => {
          if (holdTimeoutRef.current !== null) setPage('report');
        }, 400);
      }
    });
    anim.start();
  }, [holdAnim, scaleAnim, pulseAnim]);

  const handleHoldEnd = useCallback(() => {
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    holdAnim.removeAllListeners();
    // Spring back scale
    Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
    // Clear ring
    holdAnim.stopAnimation(() => {
      Animated.timing(holdAnim, { toValue: 0, duration: 200, useNativeDriver: false }).start();
    });
  }, [holdAnim, scaleAnim]);

  const reset = useCallback(() => {
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    setSec(0);
    setPage('prep');
    setActive(false);
    setCountdown(3);
    setPausedSec(0);
    holdAnim.setValue(0);
    scaleAnim.setValue(1);
    pulseAnim.setValue(0);
  }, [holdAnim, scaleAnim, pulseAnim]);

  return {
    page, setPage, sec, setSec, active, setActive,
    countdown, pausedSec,
    holdAnim, scaleAnim, pulseAnim, timerRef,
    handleGo, handlePause, handleContinue, handleHoldStart, handleHoldEnd,
    reset,
  };
}

import { COLORS, FONT_HERO, FONT_SUB, FONT_STAT_CARD, FONT_STAT_SECTION, FONT_TITLE, FONT_CLOSE, FONT_BODY, fmt } from '@egoless-do/core';
