            <View style={{ flexDirection: 'row', marginTop: 16, gap: 8 }}>
              {['inhale', 'hold', 'exhale'].map(p => (
                <View key={p} style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: breathPhase === p ? COLORS.GREEN : 'rgba(255,255,255,.2)' }} />
              ))}
