  durationValue: { fontSize: FONT_STAT_SECTION_SIZE, fontWeight: '800', color: '#fff', fontVariant: ['tabular-nums'] },
  durationLabel: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)', marginTop: 2 },
