import { COLORS, FONT_HERO, FONT_SUB, FONT_STAT_CARD, FONT_TITLE, fmt, getMinDuration } from '@egoless-do/core';
import { Play, Pause } from 'lucide-react-native';
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { View, Text, TouchableOpacity, Animated, Alert } from 'react-native';
import Svg, { Circle } from 'react-native-svg';

import MeditationMusicBar from '../../../components/MeditationMusicBar';

import type { ExercisePageProps } from './types';

export default function PausedPage(props: ExercisePageProps) {
  const {
    sportName, sportType, sec, holdAnim, scaleAnim, pulseAnim, isGpsSport, distKm, sets, currentSetReps,
    musicTrack, musicIsPlaying, musicLoop, onMusicTogglePlay, onMusicToggleLoop, onPressMusic,
    handleContinue, handleHoldEnd,
    setPage, onGoBack, T,
  } = props;

  const pausedReps = sets.reduce((s, set) => s + set.reps, 0) + currentSetReps;

  const btnSize = 88;
  const ringRadius = 40;
  const ringCircumference = 2 * Math.PI * ringRadius;
  const ringSvgSize = btnSize + 16;
  const ringCenter = ringSvgSize / 2;

  const [holding, setHolding] = useState(false);
  const [ringOffset, setRingOffset] = useState(ringCircumference);
  const startTimeRef = useRef(0);
  const rafRef = useRef<number | null>(null);
  const navigateTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const stopAnimation = useCallback(() => {
    if (rafRef.current != null) { cancelAnimationFrame(rafRef.current); rafRef.current = null; }
  }, []);

  const onHoldStart = useCallback(() => {
    setHolding(true);
    setRingOffset(ringCircumference);
    startTimeRef.current = Date.now();
    Animated.spring(scaleAnim, { toValue: 1.2, damping: 8, stiffness: 200, useNativeDriver: true }).start();
    const tick = () => {
      const p = Math.min((Date.now() - startTimeRef.current) / 3000, 1);
      setRingOffset(ringCircumference * (1 - p));
      if (p < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        // 检查最短时长阈值
        const minDur = getMinDuration(sportName);
        if (sec < minDur) {
          setHolding(false);
          setRingOffset(ringCircumference);
          Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
          Alert.alert(T('exerciseTooShort'), T('exerciseTooShortMsg'), [
            { text: T('exerciseContinue'), style: 'cancel' },
            { text: T('exerciseEnd'), style: 'destructive', onPress: () => onGoBack?.() },
          ]);
        } else {
          pulseAnim.setValue(0);
          Animated.timing(pulseAnim, { toValue: 1, duration: 400, useNativeDriver: true }).start();
          Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
          if (navigateTimerRef.current) clearTimeout(navigateTimerRef.current);
          navigateTimerRef.current = setTimeout(() => setPage?.('report'), 400);
        }
      }
    };
    rafRef.current = requestAnimationFrame(tick);
  }, [scaleAnim, pulseAnim, ringCircumference, sportName, sec, setPage, onGoBack]);

  const onHoldEnd = useCallback(() => {
    stopAnimation();
    setHolding(false);
    setRingOffset(ringCircumference);
    Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
    handleHoldEnd();
  }, [stopAnimation, scaleAnim, handleHoldEnd, ringCircumference]);

  useEffect(() => () => stopAnimation(), [stopAnimation]);
  useEffect(() => () => { if (navigateTimerRef.current) clearTimeout(navigateTimerRef.current); }, []);

  const strokeDashoffset = holding ? ringOffset : ringCircumference;

  return (
    <View style={{ flex: 1, backgroundColor: '#1a1a2e' }}>
      {/* Zone 1: Top bar */}
      <View style={{ paddingTop: 56, paddingHorizontal: 20, paddingBottom: 12, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
        <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: '#fff' }}>{T('exercisePaused')}</Text>
      </View>

      {/* Music bar */}
      {musicTrack && (
        <View style={{ paddingHorizontal: 20, marginBottom: 8 }}>
          <MeditationMusicBar
            track={musicTrack}
            isActive
            isPlaying={musicIsPlaying ?? false}
            primaryColor={COLORS.ORANGE}
            loop={musicLoop}
            onTogglePlay={onMusicTogglePlay}
            onToggleLoop={onMusicToggleLoop}
            onPress={onPressMusic}
          />
        </View>
      )}

      {/* Zone 2: Main content */}
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 24 }}>
        <View style={{ flexDirection: 'row', gap: 24, marginBottom: 32 }}>
          <View style={{ alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: '#fff' }}>{fmt(sec)}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)' }}>{T('exerciseTotalDuration')}</Text>
          </View>
          {sportType === 'repetition' && (
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: '#fff' }}>{pausedReps}</Text>
              <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)' }}>{T('exerciseReps')}</Text>
            </View>
          )}
          <View style={{ alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: '#fff' }}>{sets.length}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)' }}>{T('exerciseSets')}</Text>
          </View>
          <View style={{ alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: COLORS.ORANGE }}>{props.calories}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)' }}>kcal</Text>
          </View>
        </View>

        <Text style={{ fontSize: FONT_HERO(), fontWeight: '900', color: '#fff' }}>
          {isGpsSport ? distKm.toFixed(2) : sportType === 'repetition' ? pausedReps : Math.floor(sec / 60)}
        </Text>
        <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.5)', marginTop: 4 }}>
          {isGpsSport ? 'km' : sportType === 'repetition' ? T('exerciseReps') : 'min'}
        </Text>
        <Text style={{ fontSize: FONT_STAT_CARD(), color: 'rgba(255,255,255,.7)', marginTop: 16 }}>{fmt(sec)}</Text>
      </View>

      {/* Zone 3: Bottom bar */}
      <View style={{ paddingBottom: 48, paddingHorizontal: 24, alignItems: 'center' }}>
        <View style={{ flexDirection: 'row', gap: 32, alignItems: 'center' }}>
          {/* Hold to finish — left */}
          <TouchableOpacity
            onPressIn={onHoldStart}
            onPressOut={onHoldEnd}
            activeOpacity={1}
            style={{ width: ringSvgSize, height: ringSvgSize, alignItems: 'center', justifyContent: 'center' }}>
            {/* Pulse wave */}
            <Animated.View style={{
              position: 'absolute',
              width: btnSize, height: btnSize, borderRadius: btnSize / 2,
              borderWidth: 3, borderColor: 'rgba(255,255,255,.7)',
              transform: [{ scale: pulseAnim.interpolate({ inputRange: [0, 1], outputRange: [1, 1.8] }) }],
              opacity: pulseAnim.interpolate({ inputRange: [0, 1], outputRange: [0.7, 0] }),
            }} />

            {/* Button with spring scale */}
            <Animated.View style={{
              width: btnSize, height: btnSize, borderRadius: btnSize / 2,
              backgroundColor: COLORS.RED,
              alignItems: 'center', justifyContent: 'center',
              transform: [{ scale: scaleAnim }],
            }}>
              <Pause size={36} color="#fff" />
            </Animated.View>

            {/* SVG progress ring — rendered ON TOP of button, pass-through touches */}
            <View pointerEvents="none" style={{ position: 'absolute', width: ringSvgSize, height: ringSvgSize }}>
              <Svg width={ringSvgSize} height={ringSvgSize}>
                <Circle cx={ringCenter} cy={ringCenter} r={ringRadius}
                  stroke="rgba(255,255,255,.2)" strokeWidth={5} fill="none" />
                <Circle cx={ringCenter} cy={ringCenter} r={ringRadius}
                  stroke="#fff" strokeWidth={5} fill="none"
                  strokeDasharray={ringCircumference}
                  strokeDashoffset={strokeDashoffset}
                  strokeLinecap="round" rotation="-90" origin={`${ringCenter},${ringCenter}`} />
              </Svg>
            </View>
          </TouchableOpacity>

          {/* Continue — right (larger, more prominent) */}
          <TouchableOpacity onPress={handleContinue}
            style={{ width: 100, height: 100, borderRadius: 50, backgroundColor: COLORS.GREEN, alignItems: 'center', justifyContent: 'center', shadowColor: COLORS.GREEN, shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.4, shadowRadius: 8, elevation: 8 }}>
            <Play size={40} color="#fff" />
          </TouchableOpacity>
        </View>
        <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.4)', marginTop: 16, textAlign: 'center' }}>
          {T('exerciseHoldToEnd')}
        </Text>
      </View>
    </View>
  );
}

import { FONT_BACK, FONT_BODY, FONT_SUB, FONT_HERO, FONT_STAT_SECTION, fmt, TARGET_PRESETS, getSoftTarget } from '@egoless-do/core';
import type { MusicTrack , ExerciseEntry } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useState } from 'react';
import { View, Text, TouchableOpacity, TextInput, Alert, KeyboardAvoidingView, Platform, StyleSheet } from 'react-native';

import type { ExercisePageProps } from './types';

export default function PrepPage(props: ExercisePageProps) {
  const {
    sportName, sportType, bg, mode, setMode, targetType, setTargetType, targetValue, setTargetValue,
    breathGuideEnabled, setBreathGuideEnabled, isMeditative,
    handleGo, onGoBack, exerciseLog, T, TH,
    musicTrack, onPressMusic,
  } = props;

  const presets: Record<string, Array<{ label: string; labelEn: string; value: number }> | undefined> = TARGET_PRESETS[sportType] ?? {};
  const availableTargetTypes = Object.keys(presets) as Array<'distance' | 'time' | 'calories' | 'reps'>;
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [customInputValue, setCustomInputValue] = useState('');
  const [customTargetValue, setCustomTargetValue] = useState<Record<string, number>>({});
  const isCustomActive = (t: string) => !!customTargetValue[t] && !presets[t]?.some((p: { value: number }) => p.value === targetValue);

  const modeLabels = {
    free: sportType === 'repetition' ? T('exerciseFreeReps') : sportType === 'timed' ? T('exerciseFreeSport') : T('exerciseFreeRun'),
    target: sportType === 'repetition' ? T('exerciseTargetReps') : sportType === 'timed' ? T('exerciseTargetSport') : T('exerciseTargetRun'),
  };

  const targetTypeLabels: Record<string, string> = {
    distance: T('exerciseDistanceGoal'),
    time: T('exerciseTimeGoal'),
    calories: T('exerciseCalGoal'),
    reps: T('exerciseRepsGoal'),
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={[styles.container, { backgroundColor: bg }]}
    >
      {/* Header */}
      <View style={styles.header}>
        <View style={styles.headerRow}>
          <Text style={styles.headerTitle}>{sportName}</Text>
          <TouchableOpacity onPress={onGoBack}>
            <X size={22} color="rgba(255,255,255,.9)" />
          </TouchableOpacity>
        </View>

        {/* Music selector — inline compact */}
        <View style={styles.musicBar}>
          <TouchableOpacity onPress={onPressMusic} style={styles.musicBarButton}>
            <Text style={[styles.musicBarText, { color: musicTrack ? '#fff' : 'rgba(255,255,255,.6)' }]}>
              {musicTrack ? `🎵 ${musicTrack.name}` : `🎵 ${T('exerciseAddMusic')}`}
            </Text>
            <Text style={styles.musicBarArrow}>▸</Text>
          </TouchableOpacity>
        </View>

        {/* Mode toggle */}
        <View style={styles.modeToggle}>
          {(['free', 'target'] as const).map(m => (
            <TouchableOpacity key={m} onPress={() => setMode(m)}
              style={mode === m ? styles.modeOptionActive : styles.modeOptionInactive}>
              <Text style={{ color: '#fff', fontWeight: mode === m ? '700' : '400', fontSize: FONT_BODY() }}>
                {modeLabels[m]}
              </Text>
            </TouchableOpacity>
          ))}
        </View>

        {/* Target selection */}
        {mode === 'target' && (
          <View style={styles.targetSection}>
            <View style={styles.targetTypeRow}>
              {availableTargetTypes.map(t => (
                <TouchableOpacity key={t} onPress={() => { setTargetType(t); setTargetValue(presets[t]?.[0]?.value ?? 0); setShowCustomInput(false); setCustomInputValue(''); }}
                  style={targetType === t ? styles.targetTypePillActive : styles.targetTypePillInactive}>
                  <Text style={{ color: '#fff', fontSize: FONT_SUB(), fontWeight: targetType === t ? '700' : '400' }}>
                    {targetTypeLabels[t] ?? t}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
            <View style={styles.presetRow}>
              {(presets[targetType as keyof typeof presets] ?? []).map((p: { label: string; value: number }) => (
                <TouchableOpacity key={p.label} onPress={() => { setTargetValue(p.value); setShowCustomInput(false); setCustomInputValue(''); setCustomTargetValue(v => { const n = { ...v }; delete n[targetType]; return n; }); }}
                  style={targetValue === p.value ? styles.presetPillActive : styles.presetPillInactive}>
                  <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: targetValue === p.value ? '700' : '400' }}>{p.label}</Text>
                </TouchableOpacity>
              ))}
              {(targetType === 'time' || targetType === 'calories') && (() => {
                const customActive = isCustomActive(targetType);
                const customLabel = customActive
                  ? (targetType === 'time' ? `${customTargetValue[targetType] / 60} ${T('exerciseMin')}` : `${customTargetValue[targetType]} kcal`)
                  : T('exerciseCustom');
                return (
                  <TouchableOpacity onPress={() => {
                    if (customActive) {
                      setShowCustomInput(false);
                      setCustomInputValue('');
                      setCustomTargetValue(v => { const n = { ...v }; delete n[targetType]; return n; });
                      const firstPreset = presets[targetType]?.[0]?.value ?? 0;
                      setTargetValue(firstPreset);
                    } else {
                      setShowCustomInput(v => !v);
                    }
                  }}
                    style={customActive || showCustomInput ? styles.presetPillActive : styles.presetPillInactive}>
                    <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: customActive || showCustomInput ? '700' : '400' }}>{customLabel}</Text>
                  </TouchableOpacity>
                );
              })()}
            </View>
            {showCustomInput && (targetType === 'time' || targetType === 'calories') && (
              <View style={styles.customInputRow}>
                <TextInput
                  value={customInputValue}
                  onChangeText={setCustomInputValue}
                  keyboardType="numeric"
                  placeholder={targetType === 'time' ? '30' : '200'}
                  placeholderTextColor="rgba(255,255,255,.7)"
                  style={styles.customInput}
                />
                <Text style={styles.customUnitLabel}>
                  {targetType === 'time' ? T('exerciseMin') : 'kcal'}
                </Text>
                <TouchableOpacity onPress={() => {
                  const num = parseFloat(customInputValue);
                  if (isNaN(num) || num <= 0) {
                    Alert.alert('', T('exerciseCustomInvalid'));
                    return;
                  }
                  const finalValue = targetType === 'time' ? Math.round(num * 60) : Math.round(num);
                  setTargetValue(finalValue);
                  setCustomTargetValue(v => ({ ...v, [targetType]: finalValue }));
                  setCustomInputValue('');
                  setShowCustomInput(false);
                }}
                  style={styles.customConfirmBtn}>
                  <Text style={styles.customConfirmText}>{T('commonConfirm')}</Text>
                </TouchableOpacity>
              </View>
            )}
          </View>
        )}

        {/* Breathing guide toggle (meditative sports) */}
        {isMeditative && (
          <TouchableOpacity onPress={() => setBreathGuideEnabled(v => !v)}
            style={styles.breathToggle}>
            <Text style={styles.breathToggleLabel}>{T('exerciseBreathGuide')}</Text>
            <View style={[styles.switchTrack, { backgroundColor: breathGuideEnabled ? (TH?.accent ?? '#18CEFF') : 'rgba(255,255,255,.2)' }]}>
              <View style={breathGuideEnabled ? styles.switchThumbOn : styles.switchThumbOff} />
            </View>
          </TouchableOpacity>
        )}

        {/* Soft target recommendation */}
        {mode === 'free' && (() => {
          const st = getSoftTarget(sportName);
          if (!st) return null;
          const label = st.unit === 'min' ? T('exerciseSoftTargetMin').replace('{n}', String(st.intermediate)) : T('exerciseSoftTargetReps').replace('{n}', String(st.intermediate));
          return (
            <View style={styles.softTargetCard}>
              <Text style={styles.softTargetText}>{label}</Text>
            </View>
          );
        })()}

        {/* Last workout data */}
        {(() => {
          const lastEntry = exerciseLog?.filter((e: ExerciseEntry) => !e.deleted && e.sportKey === sportName).slice(-1)[0];
          if (!lastEntry) return null;
          return (
            <View style={styles.lastWorkoutCard}>
              <Text style={styles.lastWorkoutText}>
                {T('exerciseLastTime')} {lastEntry.durationSec ? fmt(lastEntry.durationSec) : ''}{lastEntry.reps ? ` · ${lastEntry.reps} ${T('exerciseReps')}` : ''}{lastEntry.calories ? ` · ${lastEntry.calories}kcal` : ''}
              </Text>
            </View>
          );
        })()}
      </View>

      {/* Centered circle + GO button */}
      <View style={styles.goSection}>
        <View style={styles.circle}>
          {sportType === 'repetition' ? (
            <>
              <Text style={styles.circleValue}>0</Text>
              <Text style={styles.circleUnit}>{T('exerciseReps')}</Text>
            </>
          ) : sportType === 'timed' ? (
            <>
              <Text style={styles.circleValue}>0:00</Text>
              <Text style={styles.circleUnit}>{T('exerciseMin')}</Text>
            </>
          ) : (
            <>
              <Text style={styles.circleValue}>0.00</Text>
              <Text style={styles.circleUnit}>km</Text>
            </>
          )}
        </View>

        <TouchableOpacity onPress={handleGo}
          style={styles.goButton}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '900', color: bg, letterSpacing: 4 }}>GO</Text>
        </TouchableOpacity>
      </View>
    </KeyboardAvoidingView>
  );
}

