// ─── useHabitForm: habit add/edit form state ─────────────────────
import { track } from '../../../analytics/track';
import { Events } from '../../../analytics/events';
import { activeOnly } from '@egoless-do/core';
import type { Habit, HabitLink } from '@egoless-do/core';
import { useState, useCallback } from 'react';

import { useAppStore, useShallowStore } from '../../../store/useAppStore';
import { requestNotificationPermission, rescheduleAllHabitReminders } from '../../notifications/NotificationService';

export interface HabitFormState {
  name: string;
  startDate: string;
  targetDays: number;
  goal: string;
  insight: string;
  createTag: boolean;
  alarmEnabled: boolean;
  alarmHour: number;
  alarmMinute: number;
  link: HabitLink;
  linkConfig: { targetHours?: number; targetMinutes?: number };
}

const emptyForm: HabitFormState = {
  name: '',
  startDate: '',  // will be set by caller using tomorrow()
  targetDays: 21,
  goal: '',
  insight: '',
  createTag: false,
  alarmEnabled: false,
  alarmHour: 8,
  alarmMinute: 0,
  link: 'none',
  linkConfig: {},
};

export function useHabitForm(defaultStartDate: string) {
  const { addHabit, updateHabit } = useShallowStore(s => ({
    addHabit: s.addHabit,
    updateHabit: s.updateHabit,
  }));

  const [showAdd, setShowAdd] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<HabitFormState>({ ...emptyForm, startDate: defaultStartDate });
  const [showAlarmPicker, setShowAlarmPicker] = useState(false);

  const openAdd = useCallback(() => {
    setEditingId(null);
    setForm({ ...emptyForm, startDate: defaultStartDate });
    setShowAdd(true);
  }, [defaultStartDate]);

  const openEdit = useCallback((h: Habit) => {
    setEditingId(h.id);
    setForm({
      name: h.name,
      startDate: h.startDate,
      targetDays: h.targetDays,
      goal: h.goal,
      insight: h.insight,
      createTag: h.createTag,
      alarmEnabled: h.alarmEnabled,
      alarmHour: h.alarmHour,
      alarmMinute: h.alarmMinute,
      link: h.link ?? 'none',
      linkConfig: h.linkConfig ?? {},
    });
    setShowAdd(true);
  }, []);

  const saveHabit = useCallback(async () => {
    if (!form.name.trim()) return;
    if (editingId) {
      updateHabit(editingId, { ...form, targetDays: +form.targetDays });
    } else {
      addHabit({ ...form, targetDays: +form.targetDays });
      // PostHog: 习惯创建
      track(Events.HABIT_CREATED, {
        habit_category: 'custom',
        target_days: +form.targetDays,
        has_alarm: form.alarmEnabled || false,
      });
    }
    setShowAdd(false);
    if (form.alarmEnabled) {
      const granted = await requestNotificationPermission();
      if (granted) {
        const habits = activeOnly(useAppStore.getState().habits ?? []) as Habit[];
        await rescheduleAllHabitReminders(habits).catch(() => {});
      }
    }
  }, [form, editingId, addHabit, updateHabit]);

  const closeForm = useCallback(() => setShowAdd(false), []);

  return {
    showAdd,
    editingId,
    form,
    setForm,
    showAlarmPicker,
    setShowAlarmPicker,
    openAdd,
    openEdit,
    saveHabit,
    closeForm,
  };
}

// ─── Health Service — Apple HealthKit / Health Connect abstraction ──
import type { ExerciseEntry } from '@egoless-do/core';
import { dateStr, MS_PER_DAY, createLogger } from '@egoless-do/core';
import { Platform, Alert } from 'react-native';

const log = createLogger('Health');

// ── Sport key → HealthKit / Health Connect workout type mapping ──
const SPORT_TO_HK_WORKOUT: Record<string, string> = {
  '户外骑行': 'cycling',
  '室内跑步': 'running',
  '爬楼梯': 'stairClimbing',
  '跳绳': 'jumpRope',
  '羽毛球': 'badminton',
  '足球': 'soccer',
  '篮球': 'basketball',
  '乒乓球': 'tableTennis',
  '网球': 'tennis',
  '瑜伽': 'yoga',
  '游泳': 'swimming',
};

const SPORT_TO_HC_EXERCISE: Record<string, string> = {
  '户外骑行': 'Biking',
  '室内跑步': 'Running',
  '爬楼梯': 'StairClimbing',
  '跳绳': 'JumpRope',
  '羽毛球': 'Badminton',
  '足球': 'Football',
  '篮球': 'Basketball',
  '乒乓球': 'TableTennis',
  '网球': 'Tennis',
  '瑜伽': 'Yoga',
  '游泳': 'Swimming',
};

// ── Minimal typed surfaces for the dynamically required health modules ──
// Both react-native-health and react-native-health-connect ship no TypeScript
// declarations, so we declare the exact subset of methods this file uses.

interface HealthKitPermissionSet { read: string[]; write: string[]; }
interface HealthKitModule {
  PermissionKind: { StepCount: string; Weight: string; Workout: string };
  initHealthKit(
    options: { permissions: HealthKitPermissionSet },
    callback: (err: string) => void,
  ): void;
  getStepCount(
    options: { startDate: string; endDate: string },
    callback: (err: string, result: { value: number }) => void,
  ): void;
  getLatestWeight(
    options: { unit: string; startDate: string; endDate: string },
    callback: (err: string, result: { value: number; startDate: string }) => void,
  ): void;
  saveWorkout(
    options: Record<string, unknown>,
    callback: (err: string) => void,
  ): void;
}

interface HealthConnectRecord {
  count?: number;
  weight?: { inKilograms: number } | number;
  time?: string;
}
interface HealthConnectModule {
  initialize(): Promise<unknown>;
  requestPermissions(
    permissions: Array<{ accessType: string; recordType: string }>,
  ): Promise<Array<unknown>>;
  readRecords(
    recordType: string,
    options: Record<string, unknown>,
  ): Promise<{ records: HealthConnectRecord[] }>;
  insertRecords(records: Array<Record<string, unknown>>): Promise<unknown>;
}

// Modules are dynamically required (they may not be installed in all build targets).
let healthKit: HealthKitModule | null = null;
let healthConnect: HealthConnectModule | null = null;

function getHealthKit(): HealthKitModule | null {
  if (!healthKit) {
    try {
      healthKit = (require('react-native-health') as { default: HealthKitModule } | null)?.default ?? null;
    } catch {
      return null;
    }
  }
  return healthKit;
}

function getHealthConnect(): HealthConnectModule | null {
  if (!healthConnect) {
    try {
      healthConnect = require('react-native-health-connect') as HealthConnectModule | null;
    } catch {
      return null;
    }
  }
  return healthConnect;
}

export function isHealthAvailable(): boolean {
  if (Platform.OS === 'web') return false;
  if (Platform.OS === 'ios') return !!getHealthKit();
  if (Platform.OS === 'android') return !!getHealthConnect();
  return false;
}

export async function requestHealthPermissions(): Promise<boolean> {
  try {
    if (Platform.OS === 'ios') {
      const HK = getHealthKit();
      if (!HK) return false;
      return new Promise((resolve) => {
        HK.initHealthKit(
          {
            permissions: {
              read: [
                HK.PermissionKind.StepCount,
                HK.PermissionKind.Weight,
                HK.PermissionKind.Workout,
              ],
              write: [
                HK.PermissionKind.Workout,
                HK.PermissionKind.Weight,
              ],
            },
          },
          (err: string) => {
            if (err) {
              log.warn('iOS init error:', err);
              resolve(false);
            } else {
              resolve(true);
            }
          },
        );
      });
    }

    if (Platform.OS === 'android') {
      const HC = getHealthConnect();
      if (!HC) return false;
      await HC.initialize();
      const result = await HC.requestPermissions([
        { accessType: 'read', recordType: 'Steps' },
        { accessType: 'read', recordType: 'Weight' },
        { accessType: 'read', recordType: 'ExerciseSession' },
        { accessType: 'write', recordType: 'ExerciseSession' },
        { accessType: 'write', recordType: 'Weight' },
      ]);
      return result && result.length > 0;
    }

    return false;
  } catch (e) {
    log.warn('Permission request failed:', e);
    return false;
  }
}

export async function readTodaySteps(): Promise<number> {
  try {
    const now = new Date();
    const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (Platform.OS === 'ios') {
      const HK = getHealthKit();
      if (!HK) return 0;
      return new Promise((resolve) => {
        HK.getStepCount(
          { startDate: startOfDay.toISOString(), endDate: now.toISOString() },
          (err: string, result: { value: number }) => {
            if (err) {
              log.warn('iOS step count error:', err);
              resolve(0);
            } else {
              resolve(Math.round(result?.value ?? 0));
            }
          },
        );
      });
    }

    if (Platform.OS === 'android') {
      const HC = getHealthConnect();
      if (!HC) return 0;
      const result = await HC.readRecords('Steps', {
        timeRangeFilter: {
          operator: 'between',
          startTime: startOfDay.toISOString(),
          endTime: now.toISOString(),
        },
      });
      // readRecords 返回 { records: HealthConnectRecord[] }（类型定义见上）
      const records = result.records;
      return records.reduce((sum: number, r: { count?: number }) => sum + (r.count ?? 0), 0);
    }

    return 0;
  } catch (e) {
    log.warn('readTodaySteps failed:', e);
    return 0;
  }
}

export async function readLatestWeight(): Promise<{ value: number; date: string } | null> {
  try {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - 30 * MS_PER_DAY);

    if (Platform.OS === 'ios') {
      const HK = getHealthKit();
      if (!HK) return null;
      return new Promise((resolve) => {
        HK.getLatestWeight(
          { unit: 'kg', startDate: thirtyDaysAgo.toISOString(), endDate: now.toISOString() },
          (err: string, result: { value: number; startDate: string }) => {
            if (err || !result) {
              resolve(null);
            } else {
              resolve({
                value: Math.round(result.value * 10) / 10,
                date: result.startDate.slice(0, 10),
              });
            }
          },
        );
      });
    }

    if (Platform.OS === 'android') {
      const HC = getHealthConnect();
      if (!HC) return null;
      const result = await HC.readRecords('Weight', {
        timeRangeFilter: {
          operator: 'between',
          startTime: thirtyDaysAgo.toISOString(),
          endTime: now.toISOString(),
        },
        ascendingOrder: false,
        pageSize: 1,
      });
      const records = result.records ?? result;
      if (!Array.isArray(records) || records.length === 0) return null;
      const r = records[0];
      const weightVal = r.weight;
      const kg = typeof weightVal === 'object' && weightVal != null ? weightVal.inKilograms : weightVal;
      if (kg === null || kg === undefined || isNaN(kg)) return null;
      return {
        value: Math.round(kg * 10) / 10,
        date: r.time?.slice(0, 10) ?? dateStr(),
      };
    }

    return null;
  } catch (e) {
    log.warn('readLatestWeight failed:', e);
    return null;
  }
}

export async function writeWorkout(entry: ExerciseEntry): Promise<boolean> {
  try {
    if (Platform.OS === 'ios') {
      const HK = getHealthKit();
      if (!HK) return false;
      const workoutType = SPORT_TO_HK_WORKOUT[entry.sportKey] ?? 'other';
      return new Promise((resolve) => {
        HK.saveWorkout(
          {
            type: workoutType,
            startDate: new Date(entry.timestamp).toISOString(),
            endDate: new Date(entry.timestamp + entry.durationSec * 1000).toISOString(),
            energyBurned: entry.calories ?? 0,
            energyBurnedUnit: 'kcal',
            distance: entry.distanceKm ?? 0,
            distanceUnit: 'km',
          },
          (err: string) => {
            if (err) {
              log.warn('iOS saveWorkout error:', err);
              resolve(false);
            } else {
              resolve(true);
            }
          },
        );
      });
    }

    if (Platform.OS === 'android') {
      const HC = getHealthConnect();
      if (!HC) return false;
      const exerciseType = SPORT_TO_HC_EXERCISE[entry.sportKey] ?? 'OtherWorkout';
      await HC.insertRecords([
        {
          recordType: 'ExerciseSession',
          exerciseType,
          startTime: new Date(entry.timestamp).toISOString(),
          endTime: new Date(entry.timestamp + entry.durationSec * 1000).toISOString(),
          energy: entry.calories
            ? { value: entry.calories, unit: 'kilocalories' }
            : undefined,
          distance: entry.distanceKm
            ? { value: entry.distanceKm * 1000, unit: 'meters' }
            : undefined,
          title: entry.sportKey,
        },
      ]);
      return true;
    }

    return false;
  } catch (e) {
    log.warn('writeWorkout failed:', e);
    return false;
  }
}

export async function performHealthSync(store: {
  healthSyncEnabled: boolean;
  checkinHistory: { date: string; weight?: number; deleted?: boolean }[];
  setTodaySteps: (n: number) => void;
  syncWeightFromHealth: (w: number) => void;
}): Promise<void> {
  if (!store.healthSyncEnabled || !isHealthAvailable()) return;

  try {
    // Read steps
    const steps = await readTodaySteps();
    store.setTodaySteps(steps);

    // Read weight — only if user hasn't entered weight today
    const today = dateStr();
    const todayCheckin = (store.checkinHistory ?? []).find((c) => !c.deleted && c.date === today);
    if (todayCheckin?.weight == null) {
      const weight = await readLatestWeight();
      if (weight && weight.date === today) {
        store.syncWeightFromHealth(weight.value);
      }
    }
  } catch (e) {
    log.warn('performHealthSync failed:', e);
  }
}

import { FONT_BODY, FONT_SUB, FONT_STAT_CARD, FONT_SMALL } from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import { Check, Pencil, Target, BarChart3, Shield } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useTheme, useT } from '../../../components/UI';


interface Props {
  status: 'draft' | 'done' | 'editing';
  bannerGrad: string[];
  bannerStatusText: string;
  bannerTimeText: string | null;
  isToday: boolean;
  totalCompleted: number;
  viewDateStats: { totalDays: number; streak: number };
  streak: number;
  showGrace: boolean;
  graceAvailable: boolean;
  onStatsPress: () => void;
}

export default function Banner({
  status, bannerGrad, bannerStatusText, bannerTimeText,
  isToday, totalCompleted, viewDateStats, streak,
  showGrace, graceAvailable, onStatsPress,
}: Props) {
  const TH = useTheme();
  const T = useT();

  return (
    <LinearGradient
      colors={bannerGrad}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={{ borderRadius: 16, padding: 18, marginBottom: 12 }}
    >
      {/* Status — prominent */}
      <View style={{ alignItems: 'center', marginBottom: 14 }}>
        <View style={{
          flexDirection: 'row', alignItems: 'center', gap: 8,
          backgroundColor: 'rgba(255,255,255,.2)', borderRadius: 20,
          paddingHorizontal: 16, paddingVertical: 6,
        }}>
          {status === 'done'
            ? <Check size={18} color="#fff" />
            : status === 'editing'
            ? <Pencil size={18} color="#fff" />
            : <Target size={18} color="#fff" />
          }
          <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BODY() }}>
            {bannerStatusText}
          </Text>
        </View>
        {bannerTimeText ? (
          <Text style={{ color: 'rgba(255,255,255,.6)', fontSize: FONT_SUB(), marginTop: 6 }}>{bannerTimeText}</Text>
        ) : null}
      </View>

      {/* Stats row */}
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
        <TouchableOpacity style={{ alignItems: 'center', flex: 1 }} onPress={onStatsPress} activeOpacity={0.7}>
          <Text style={{ color: 'rgba(255,255,255,.6)', fontSize: FONT_SUB() }}>{T('totalCompleted')}</Text>
          <Text style={{ color: '#fff', fontWeight: '800', fontSize: FONT_STAT_CARD() }}>{String(isToday ? totalCompleted : viewDateStats.totalDays)}</Text>
          <Text style={{ color: 'rgba(255,255,255,.5)', fontSize: FONT_SMALL() }}>{T('days')}</Text>
          <BarChart3 size={12} color="rgba(255,255,255,.7)" style={{ marginTop: 4 }} />
        </TouchableOpacity>
        <View style={{ width: 1, height: 40, backgroundColor: 'rgba(255,255,255,.2)' }} />
        <TouchableOpacity style={{ alignItems: 'center', flex: 1 }} onPress={onStatsPress} activeOpacity={0.7}>
          <Text style={{ color: 'rgba(255,255,255,.6)', fontSize: FONT_SUB() }}>{T('streak')}</Text>
          <Text style={{ color: '#fff', fontWeight: '800', fontSize: FONT_STAT_CARD() }}>{String(isToday ? streak : viewDateStats.streak)}</Text>
          <Text style={{ color: 'rgba(255,255,255,.5)', fontSize: FONT_SMALL() }}>{T('days')}</Text>
          {isToday && showGrace && graceAvailable ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 3, marginTop: 4 }}>
              <Shield size={10} color="rgba(255,255,255,.7)" />
              <Text style={{ color: 'rgba(255,255,255,.7)', fontSize: FONT_SMALL() }}>{T('graceStreakPending')}</Text>
            </View>
          ) : (
            <BarChart3 size={12} color="rgba(255,255,255,.7)" style={{ marginTop: 4 }} />
          )}
        </TouchableOpacity>
      </View>
    </LinearGradient>
  );
}

