import { FONT_BODY, FONT_SUB, FONT_TITLE, computeLongestStreak, INCOMPLETE_REASONS, parseCheckinNote, MS_PER_WEEK , FONT_STAT_SECTION } from '@egoless-do/core';
import type { CheckinEntry } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useMemo } from 'react';
import { View, Text, Modal, TouchableOpacity, ScrollView, FlatList } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import CalendarGrid from '../../../components/charts/CalendarGrid';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


interface CheckinStatsModalProps {
  visible: boolean;
  onClose: () => void;
}

export default function CheckinStatsModal({ visible, onClose }: CheckinStatsModalProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { checkinHistory, streak } = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    streak: s.streak,
  }));
  const insets = useSafeAreaInsets();

  const historyArr = checkinHistory ?? [];
  const totalCompleted = useMemo(() => historyArr.filter((c: CheckinEntry) => c.done && !c.deleted).length, [historyArr]);

  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth();

  // 本月打卡天数
  const monthDone = useMemo(() => {
    return historyArr.filter((c: CheckinEntry) => {
      if (!c.done || c.deleted) return false;
      const [cy, cm, cd] = c.date.split('-').map(Number);
      const d = new Date(cy, cm - 1, cd);
      return d.getFullYear() === currentYear && d.getMonth() === currentMonth;
    }).length;
  }, [historyArr, currentYear, currentMonth]);

  // 本月已过天数
  const monthPassed = today.getDate();

  // 本月完成率
  const monthRate = useMemo(() => {
    if (monthPassed === 0) return 0;
    return Math.round((monthDone / monthPassed) * 100);
  }, [monthDone, monthPassed]);

  // 最长连续记录
  const longestStreak = useMemo(() => {
    return computeLongestStreak(historyArr.filter((c: CheckinEntry) => c.done && !c.deleted).map(c => c.date));
  }, [historyArr]);

  // 平均每周打卡
  const avgPerWeek = useMemo(() => {
    if (historyArr.length === 0) return 0;
    const dates = historyArr.filter((c: CheckinEntry) => c.done && !c.deleted).map(c => c.date).sort();
    if (dates.length === 0) return 0;
    const [fy, fm, fd] = dates[0].split('-').map(Number);
    const firstDate = new Date(fy, fm - 1, fd);
    const [ly, lm, ld] = dates[dates.length - 1].split('-').map(Number);
    const lastDate = new Date(ly, lm - 1, ld);
    const weeks = Math.max(1, Math.ceil((lastDate.getTime() - firstDate.getTime()) / MS_PER_WEEK));
    return Math.round((totalCompleted / weeks) * 10) / 10;
  }, [historyArr, totalCompleted]);

  const stats = [
    { label: T('monthCompletionRate'), value: `${monthRate}%`, sub: `${monthDone}/${monthPassed} ${T('days')}` },
    { label: T('monthCheckinDays'), value: monthDone, sub: `${T('total')} ${new Date(currentYear, currentMonth + 1, 0).getDate()} ${T('days')}` },
    { label: T('longestStreak'), value: longestStreak, sub: T('days') },
    { label: T('totalCompleted'), value: totalCompleted, sub: T('days') },
    { label: T('streak'), value: streak, sub: T('days') },
    { label: T('avgPerWeek'), value: avgPerWeek, sub: T('days') },
  ];

  // 本月未完成原因分布
  const reasonDistribution = useMemo(() => {
    const counts: Record<string, number> = {};
    historyArr
      .filter((c: CheckinEntry) => {
        if (c.done || c.deleted) return false;
        const [cy, cm, cd] = c.date.split('-').map(Number);
        const d = new Date(cy, cm - 1, cd);
        return d.getFullYear() === currentYear && d.getMonth() === currentMonth;
      })
      .forEach((c: CheckinEntry) => {
        const parsed = parseCheckinNote(c.note ?? '');
        if (parsed.incompleteReason) {
          counts[parsed.incompleteReason] = (counts[parsed.incompleteReason] ?? 0) + 1;
        }
      });
    return INCOMPLETE_REASONS
      .map(r => ({ ...r, count: counts[r.code] ?? 0 }))
      .filter(r => r.count > 0)
      .sort((a, b) => b.count - a.count);
  }, [historyArr, currentYear, currentMonth]);

  return (
    <Modal visible={visible} animationType="slide" transparent>
      <View style={{ flex: 1, backgroundColor: `${TH.bg}E6` }}>
        <View style={{ flex: 1, backgroundColor: TH.bg }}>
          {/* Header */}
          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 16, paddingTop: insets.top + 12, paddingBottom: 12, borderBottomWidth: 1, borderBottomColor: TH.border }}>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{T('checkinStats')}</Text>
            <TouchableOpacity onPress={onClose} style={{ padding: 8 }}>
              <X size={24} color={TH.text} />
            </TouchableOpacity>
          </View>

          <ScrollView style={{ flex: 1 }} contentContainerStyle={{ padding: 16, paddingBottom: 16 + insets.bottom }}>
            {/* Calendar */}
            <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 16, borderWidth: 1, borderColor: TH.border }}>
              <CalendarGrid
                history={historyArr.filter((c: CheckinEntry) => !c.deleted).map((c: CheckinEntry) => ({ date: c.date, done: c.done, grace: c.grace }))}
                primaryColor={P}
                textColor={TH.text}
                subColor={TH.sub}
                borderColor={TH.border}
              />
            </View>

            {/* Stats Grid */}
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginBottom: reasonDistribution.length > 0 ? 16 : 0 }}>
              {stats.map((stat, i) => (
                <View key={i} style={{ backgroundColor: TH.card, borderRadius: 14, padding: 12, width: '48%', borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
                  <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '700', color: P }}>{stat.value}</Text>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>{stat.label}</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 2, textAlign: 'center' }}>{stat.sub}</Text>
                </View>
              ))}
            </View>

            {/* Incomplete Reason Distribution */}
            {reasonDistribution.length > 0 && (
              <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, borderWidth: 1, borderColor: TH.border }}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 12 }}>{T('incompleteReasonStats')}</Text>
                <FlatList
                  data={reasonDistribution}
                  keyExtractor={(item) => item.code}
                  renderItem={({ item: r }) => {
                    const labelKey = `incompleteReason${r.code.charAt(0).toUpperCase() + r.code.slice(1)}` as string;
                    return (
                      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: 8 }}>
                        <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>{r.icon} {T(labelKey)}</Text>
                        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: P }}>{r.count} {T('days')}</Text>
                      </View>
                    );
                  }}
                  scrollEnabled={false}
                  removeClippedSubviews={true}
                />
              </View>
            )}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

import { COLORS, FONT_BODY, FONT_SUB, FONT_BUTTON, FONT_TITLE, FONT_STAT_CARD, FONT_LABEL , FONT_STAT_SECTION } from '@egoless-do/core';
import { Utensils, Pencil, X } from 'lucide-react-native';
import React, { useState, useMemo, memo } from 'react';
import {
  View, Text, TouchableOpacity, Modal, TextInput, StyleSheet,
} from 'react-native';

import AddFoodModal from '../../../components/AddFoodModal';
import { useTheme, useT, ProgressBar } from '../../../components/UI';



interface FoodItem {
  id: string;
  name: string;
  calories: number;
}

interface RecentFood {
  name: string;
  calories: number;
}

interface HomeFoodSectionProps {
  /** Food items for the current view date */
  foods: FoodItem[];
  /** Total calories for the view date */
  totalCal: number;
  /** Recent food entries for quick re-add */
  recentFoods: RecentFood[];
  /** Whether viewing today */
  isToday: boolean;
  /** Calorie goal */
  calGoal: number;
  /** Whether the section is read-only */
  isReadOnly: boolean;
  /** Delete a food entry */
  onDeleteFood: (id: string) => void;
  /** Add a food entry */
  onAddFood: (food: { name: string; calories: number; timestamp: number }) => void;
  /** Called after any food change so parent can re-save */
  onFoodChanged: () => void;
  /** Set calorie goal */
  onSetCalGoal: (goal: number) => void;
}

const HomeFoodSection = memo(function HomeFoodSection({
  foods, totalCal, recentFoods, isToday, calGoal, isReadOnly,
  onDeleteFood, onAddFood, onFoodChanged, onSetCalGoal,
}: HomeFoodSectionProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;

  const [showFood, setShowFood] = useState(false);
  const [showCG, setShowCG] = useState(false);
  const [cgi, setCgi] = useState(String(calGoal));
  const [portionFood, setPortionFood] = useState<{ name: string; calories: number } | null>(null);
  const [portion, setPortion] = useState(1);

  const todayFoods = foods.slice(0, 3);
  const todayFoodTotal = foods.length;

  return (
    <>
      {/* ── Food card ── */}
      <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 12, borderWidth: 1, borderColor: TH.border }}>
        <View style={styles.cardHeaderRow}>
          <View style={styles.iconLabelRow}>
            <Utensils size={16} color={P} />
            <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('todayFood')}</Text>
          </View>
          <View style={styles.iconLabelRow}>
            {isToday ? (
              <>
                <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                  <Text style={{ fontWeight: '600', color: P }}>{String(totalCal)}</Text> / {String(calGoal)} kcal
                </Text>
                <TouchableOpacity onPress={() => { setCgi(String(calGoal)); setShowCG(true); }}>
                  <Pencil size={14} color={TH.sub} />
                </TouchableOpacity>
              </>
            ) : (
              <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                <Text style={{ fontWeight: '600', color: P }}>{String(totalCal)}</Text> kcal
              </Text>
            )}
          </View>
        </View>
        <ProgressBar pct={calGoal > 0 ? Math.min(totalCal / calGoal * 100, 100) : 0} color={P} />

        {/* Recent Foods (today only) */}
        {isToday && recentFoods.length > 0 && (
          <View style={styles.sectionSpacing}>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 6 }}>{T('recentFoods')}</Text>
            <View style={styles.recentFoodRow}>
              {recentFoods.map(f => (
                <TouchableOpacity key={f.name} onPress={() => { setPortionFood(f); setPortion(1); }}
                  style={{ flex: 1, borderRadius: 10, padding: 10, alignItems: 'center', backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border }}>
                  <Text style={{ color: TH.text, fontSize: FONT_SUB(), textAlign: 'center' }} numberOfLines={1}>{f.name}</Text>
                  <Text style={{ color: P, fontSize: FONT_SUB(), fontWeight: '600' }}>{String(f.calories)}kcal</Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        )}

        {/* Food List */}
        {todayFoods.length > 0 && (
          <View style={styles.sectionSpacing}>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 6 }}>{T('todayFood')} ({String(todayFoodTotal)})</Text>
            {todayFoods.map(f => (
              <View key={f.id} style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 6, borderBottomWidth: 1, borderBottomColor: TH.border }}>
                <Text style={{ color: TH.text, fontSize: FONT_BODY(), flex: 1 }} numberOfLines={1}>{f.name}</Text>
                <Text style={{ color: P, fontSize: FONT_SUB(), fontWeight: '600', marginRight: 8 }}>{String(f.calories)} kcal</Text>
                {isToday && (
                  <TouchableOpacity onPress={() => onDeleteFood(f.id)}>
                    <X size={16} color={TH.sub} />
                  </TouchableOpacity>
                )}
              </View>
            ))}
          </View>
        )}

        {/* Add food button (today only) */}
        {isToday && (
          <TouchableOpacity onPress={() => setShowFood(true)}
            style={{ marginTop: 10, borderRadius: 10, padding: 11, alignItems: 'center', borderWidth: 1.5, borderColor: P }}>
            <Text style={{ color: P, fontWeight: '600', fontSize: FONT_BUTTON() }}>{T('addFoodBtn')}</Text>
          </TouchableOpacity>
        )}
      </View>

      <AddFoodModal visible={showFood} onClose={() => setShowFood(false)} onFoodAdded={() => {
        onFoodChanged();
      }} />

      {/* Portion Selector Modal (for recent foods) */}
      <Modal visible={!!portionFood} transparent animationType="fade" onRequestClose={() => setPortionFood(null)}>
        <View style={styles.modalOverlay}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24 }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text, marginBottom: 4 }}>{portionFood?.name}</Text>
            <Text style={{ color: TH.sub, fontSize: FONT_BODY(), marginBottom: 16 }}>{T('foodPerUnit')} {portionFood?.calories} kcal</Text>
            <View style={styles.portionButtonRow}>
              {[0.5, 1, 1.5, 2].map(p => (
                <TouchableOpacity key={p} onPress={() => setPortion(p)}
                  style={{
                    flex: 1, paddingVertical: 10, borderRadius: 12, alignItems: 'center',
                    backgroundColor: portion === p ? P : TH.card,
                    borderWidth: portion === p ? 0 : 1, borderColor: TH.border,
                  }}>
                  <Text style={{ color: portion === p ? '#fff' : TH.text, fontWeight: portion === p ? '700' : '400', fontSize: FONT_BODY() }}>
                    {p}份
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
            <View style={styles.totalRow}>
              <Text style={{ color: TH.sub, fontSize: FONT_BODY() }}>{T('foodTotalCal')}</Text>
              <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: COLORS.ORANGE }}>
                {String(Math.round((portionFood?.calories ?? 0) * portion))} <Text style={{ fontSize: FONT_SUB(), fontWeight: '400', color: TH.sub }}>kcal</Text>
              </Text>
            </View>
            <View style={styles.modalButtonRow}>
              <TouchableOpacity onPress={() => setPortionFood(null)}
                style={{ flex: 1, padding: 12, borderRadius: 12, borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
                <Text style={{ color: TH.sub, fontSize: FONT_BODY() }}>{T('cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => {
                if (portionFood) {
                  onAddFood({ name: portionFood.name, calories: Math.round(portionFood.calories * portion), timestamp: Date.now() });
                  setPortionFood(null);
                  onFoodChanged();
                }
              }}
                style={{ flex: 1, padding: 12, borderRadius: 12, backgroundColor: P, alignItems: 'center' }}>
                <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BODY() }}>{T('confirm')}</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* Calorie Goal Modal */}
      <Modal visible={showCG} transparent animationType="fade" onRequestClose={() => setShowCG(false)}>
        <View style={styles.modalOverlay}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, alignItems: 'center' }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), marginBottom: 6, color: TH.text }}>{T('calGoalSetting')}</Text>
            <Text style={{ fontSize: FONT_BODY(), color: TH.sub, marginBottom: 16 }}>{T('calGoalHint')}</Text>
            <TextInput
              value={cgi} onChangeText={setCgi} keyboardType="numeric"
              style={{
                width: '100%', fontSize: FONT_STAT_CARD(), fontWeight: '700', textAlign: 'center',
                backgroundColor: TH.card, borderWidth: 2, borderColor: COLORS.BLUE,
                borderRadius: 12, padding: 14, color: TH.text, marginBottom: 20,
              }}
            />
            <View style={styles.calGoalButtonRow}>
              <TouchableOpacity onPress={() => setShowCG(false)}
                style={{ flex: 1, padding: 12, borderRadius: 12, borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
                <Text style={{ color: TH.sub, fontSize: FONT_BODY() }}>{T('cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={() => { onSetCalGoal(Math.max(500, Math.min(10000, +cgi || 2000))); setShowCG(false); }}
                style={{ flex: 1, padding: 12, borderRadius: 12, backgroundColor: P, alignItems: 'center' }}>
                <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BUTTON() }}>{T('save')}</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </>
  );
});

const styles = StyleSheet.create({
  cardHeaderRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 6,
  },
  iconLabelRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  sectionSpacing: {
    marginTop: 10,
  },
  recentFoodRow: {
    flexDirection: 'row',
    gap: 8,
  },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,.65)',
    justifyContent: 'center',
    padding: 24,
  },
  portionButtonRow: {
    flexDirection: 'row',
    gap: 8,
    marginBottom: 16,
  },
  totalRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'baseline',
    marginBottom: 16,
  },
  modalButtonRow: {
    flexDirection: 'row',
    gap: 10,
  },
  calGoalButtonRow: {
    flexDirection: 'row',
    gap: 10,
    width: '100%',
  },
});

export default HomeFoodSection;

