export default function CheckinHistoryScreen() {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { checkinHistory, clearAllReviews } = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    clearAllReviews: s.clearAllReviews,
  }));
  const nav = useRootNavigation();

  const [activeTab, setActiveTab] = useState<'history' | 'weekReview' | 'monthReview'>('weekReview');

  const sorted = useMemo(() =>
    (checkinHistory ?? []).filter(c => !c.deleted).sort((a, b) => {
      const ta = a.timestamp ?? new Date(a.date).getTime();
      const tb = b.timestamp ?? new Date(b.date).getTime();
      return tb - ta;
    }),
    [checkinHistory]
  );

  const { items: paginatedSorted, hasMore, loadMore, isLoading } = usePagination({
    data: sorted,
    pageSize: 30,
  });

  const grouped = useMemo(() => {
    const map = new Map<string, typeof paginatedSorted>();
    for (const h of paginatedSorted) {
      const key = h.date.slice(0, 7);
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(h);
    }
    return Array.from(map.entries());
  }, [paginatedSorted]);

  const formatMonth = useCallback((key: string) => {
    const [y, m] = key.split('-');
    return T('dateYearMonth').replace('{year}', y).replace('{month}', m);
  }, [T]);

  const formatDay = useCallback((dateStr: string) => {
    const parts = dateStr.split('-');
    return parts.length >= 3 ? `${parseInt(parts[1])}-${parseInt(parts[2])}` : dateStr;
  }, []);

  const weekdays = [T('weekdaySun'), T('weekdayMon'), T('weekdayTue'), T('weekdayWed'), T('weekdayThu'), T('weekdayFri'), T('weekdaySat')];
  const getWeekday = useCallback((ds: string) => {
    const [y, m, d] = ds.split('-').map(Number);
    const date = new Date(y, m - 1, d);
    return isNaN(date.getTime()) ? '' : weekdays[date.getDay()];
  }, [weekdays]);

  const handleClearReviews = useCallback(() => {
    Alert.alert(
      T('clearReviewData'),
      T('clearReviewDataConfirm'),
      [
        { text: T('cancel'), style: 'cancel' },
        {
          text: T('confirm'),
          style: 'destructive',
          onPress: () => {
            clearAllReviews();
            Alert.alert(T('done'), T('clearReviewDataDone'));
          }
        },
      ]
    );
  }, [T, clearAllReviews]);

  const renderItem = useCallback(({ item: [monthKey, items] }: { item: [string, typeof sorted] }) => {
    const isLastGroup = monthKey === grouped[0]?.[0];
    return (
      <View key={monthKey} style={styles.historyGroup}>
        <View style={styles.monthHeaderRow}>
          <View style={[styles.monthDot, { backgroundColor: P }]} />
          <Text style={[styles.monthLabel, { fontSize: FONT_SUB(), color: TH.text }]}>{formatMonth(monthKey)}</Text>
          <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>{items.length} {T('days')}</Text>
        </View>

        {items.map((h, idx) => {
          const isLast = isLastGroup && idx === items.length - 1;
          const parsed = parseCheckinNote(h.note ?? '');
          const tags: { icon: string; text: string }[] = [];
          if (parsed.fasted) tags.push({ icon: '🔥', text: T('checkinAbstinence') });
          if (parsed.waterMl > 0) tags.push({ icon: '💧', text: `${parsed.waterMl}ml` });
          if (parsed.food > 0) tags.push({ icon: '🍽️', text: `${parsed.food}kcal` });
          for (const pr of parsed.practices) {
            if (PRACTICE_LABELS[pr]) tags.push({ icon: PRACTICE_ICONS[pr], text: T(PRACTICE_LABELS[pr]) });
          }
          for (const name of parsed.habits) tags.push({ icon: '✓', text: name });
          for (const name of parsed.customs) tags.push({ icon: '✦', text: name });
          for (const item of parsed.planItems) tags.push({ icon: '☐', text: String(typeof item === 'string' ? item : item.name ?? item.id ?? '') });

          return (
            <View key={h.date ?? idx} style={styles.timelineRow}>
              <View style={styles.timelineCol}>
                <View style={[styles.timelineDot, { backgroundColor: h.done ? COLORS.GREEN : COLORS.RED }]} />
                {!isLast && <View style={[styles.timelineLine, { backgroundColor: `${P}30` }]} />}
              </View>

              <TouchableOpacity
                onPress={() => nav.navigate('CheckinDetail', { date: h.date })}
                activeOpacity={0.7}
                style={[styles.card, { backgroundColor: TH.card, borderLeftColor: h.done ? COLORS.GREEN : COLORS.RED }]}
              >
                <View style={styles.cardHeaderRow}>
                  <View style={[styles.centerRow, styles.gap6]}>
                    <Text style={[styles.badgeText, { fontSize: FONT_BADGE(), color: TH.sub }]}>{formatDay(h.date)}</Text>
                    <Text style={[styles.badgeText, { fontSize: FONT_BADGE(), color: TH.sub }]}>{T('dateWeekdayPrefix')}{getWeekday(h.date)}</Text>
                  </View>
                  <View style={[styles.centerRow, styles.gap6]}>
                    {h.grace && (
                      <View style={styles.graceBadge}>
                        <Shield size={10} color={COLORS.ORANGE} />
                        <Text style={[styles.badgeText, { fontSize: FONT_BADGE(), color: COLORS.ORANGE }]}>
                          {T('graceTitle')}
                        </Text>
                      </View>
                    )}
                    <View style={[styles.doneBadge, { backgroundColor: h.done ? 'rgba(16,185,129,.15)' : 'rgba(239,68,68,.1)' }]}>
                      <Text style={[styles.badgeText, { fontSize: FONT_BADGE(), color: h.done ? COLORS.GREEN : COLORS.RED }]}>
                        {h.done ? T('checkinDone') : T('checkinNotDone')}
                      </Text>
                    </View>
                  </View>
                </View>

                {parsed.userNote ? (
                  <Text style={[styles.userNote, { fontSize: FONT_SUB(), color: TH.text }]} numberOfLines={2}>{parsed.userNote}</Text>
                ) : null}

                {tags.length > 0 && (
                  <View style={styles.tagsContainer}>
                    {tags.map((tag, i) => (
                      <View key={i} style={[styles.tagItem, { backgroundColor: `${P}12` }]}>
                        <Text style={styles.tagIcon}>{tag.icon}</Text>
                        <Text style={[styles.tagText, { color: TH.sub }]}>{tag.text}</Text>
                      </View>
                    ))}
                  </View>
                )}

                <View style={[styles.streakRow, styles.gap12]}>
                  {h.streak > 0 && <Text style={[styles.streakText, { fontSize: FONT_BADGE(), color: TH.sub }]}>{T('checkinStreak')}: {String(h.streak)} {T('days')}</Text>}
                  {h.weight ? <Text style={[styles.streakText, { fontSize: FONT_BADGE(), color: TH.sub }]}>{String(h.weight)} {T('checkinKg')}</Text> : null}
                </View>
              </TouchableOpacity>
            </View>
          );
        })}
      </View>
    );
  }, [grouped, P, TH.text, TH.sub, TH.card, T, formatMonth, formatDay, getWeekday, nav]);

  const keyExtractor = useCallback((item: [string, typeof sorted]) => item[0], []);

  const ListEmptyComponent = useMemo(() => (
    <Text style={{ textAlign: 'center', marginTop: 60, color: TH.sub, fontSize: FONT_EMPTY() }}>
      {T('checkinNoRecords')}
    </Text>
  ), [TH.sub, T]);

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <View style={styles.headerBar}>
        <View style={styles.centerRow}>
          <TouchableOpacity onPress={() => nav.goBack()}>
            <Text style={{ color: TH.text, fontSize: FONT_BACK() }}>←</Text>
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: TH.text, fontSize: FONT_TITLE() }]}>{T('checkinHistory')}</Text>
        </View>
        <TouchableOpacity
          onPress={handleClearReviews}
          style={styles.clearButton}
        >
          <Text style={styles.clearButtonText}>{T('clearReviewData')}</Text>
        </TouchableOpacity>
      </View>

      {/* Tab切换 */}
      <View style={styles.tabRow}>
        {(['weekReview', 'monthReview', 'history'] as const).map(tab => {
          const active = activeTab === tab;
          const labels = { history: T('history'), weekReview: T('reviewWeek'), monthReview: T('reviewMonth') };
          return (
            <TouchableOpacity
              key={tab}
              onPress={() => setActiveTab(tab)}
              style={[styles.tabButton, {
                backgroundColor: active ? `${P}18` : 'transparent',
                borderWidth: active ? 1 : 0, borderColor: active ? P : 'transparent',
              }]}
            >
              <Text style={[styles.tabText, {
                fontSize: FONT_BODY(), fontWeight: active ? '600' : '400',
                color: active ? P : TH.sub,
              }]}>
                {labels[tab]}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* 内容区域 */}
      {activeTab === 'weekReview' ? (
        <ReviewView period="week" />
      ) : activeTab === 'monthReview' ? (
        <ReviewView period="month" />
      ) : (
        <FlashList
          data={paginatedSorted.length === 0 ? [] : grouped}
          renderItem={renderItem}
          keyExtractor={keyExtractor}
          ListEmptyComponent={ListEmptyComponent}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          onEndReached={hasMore ? loadMore : undefined}
          onEndReachedThreshold={0.5}
          ListFooterComponent={hasMore && isLoading ? <ActivityIndicator style={styles.footerLoader} /> : null}
        />
      )}
    </SafeAreaView>
  );
}

import { COLORS, getFoodLogByDate, getActivePlan, getTodayItems, getTodayCustomTodos, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BUTTON, parseCheckinNote } from '@egoless-do/core';
import type { CheckinEntry, PlanItem, DailyCustomTodo, Habit } from '@egoless-do/core';
import { useRoute, RouteProp } from '@react-navigation/native';
import {
  Utensils, Droplets, Scale, Sparkles,
  ClipboardList, Check, Shield, Plus,
  ChevronLeft,
} from 'lucide-react-native';
import React, { useState, useMemo, useCallback } from 'react';
import {
  View, Text, ScrollView, SectionList, TouchableOpacity, TextInput,
  KeyboardAvoidingView, Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT, Checkbox, ThemedInput } from '../../../components/UI';
import { useRootNavigation, type RootStackParamList } from '../../../navigation/hooks';
import { useShallowStore } from '../../../store/useAppStore';


/** Parse weight string, return undefined if invalid or out of range (1-500 kg) */
function parseWeight(raw: string | undefined): number | undefined {
  if (!raw) return undefined;
  const n = parseFloat(raw);
  return Number.isFinite(n) && n > 0 && n <= 500 ? n : undefined;
}

type DayCheckinRoute = RouteProp<RootStackParamList, 'DayCheckin'>;

export default function DayCheckinScreen() {
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const nav   = useRootNavigation();
  const route = useRoute<DayCheckinRoute>();
  const { date, graceMode } = route.params;
  const isGraceMode = !!graceMode;

  const store = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    foodLog: s.foodLog,
    plans: s.plans,
    planItemCheckins: s.planItemCheckins,
    planItems: s.planItems,
    dailyCustomTodos: s.dailyCustomTodos,
    habits: s.habits,
    userProfile: s.userProfile,
    weightUnit: s.weightUnit,
    checkinHabit: s.checkinHabit,
    checkinPlanItem: s.checkinPlanItem,
    uncheckinPlanItem: s.uncheckinPlanItem,
    submitCheckin: s.submitCheckin,
    addGraceRecord: s.addGraceRecord,
    toggleDailyCustomTodo: s.toggleDailyCustomTodo,
    addFood: s.addFood,
  }));

  const [submitted, setSubmitted] = useState(false);

  // ── Existing checkin for this date ──
  const existing = useMemo(() =>
    (store.checkinHistory ?? []).find((c: CheckinEntry) => !c.deleted && c.date === date),
    [store.checkinHistory, date],
  );
  const parsed = useMemo(() => parseCheckinNote(existing?.note ?? ''), [existing]);

  // ── Plan items ──
  const activePlan = useMemo(() => getActivePlan(store.plans ?? []), [store.plans]);
  const planCheckins = (store.planItemCheckins ?? []).filter(c => !c.deleted);
  const todayPlanItems = useMemo(() => {
    if (!activePlan) return [];
    return getTodayItems(store.planItems ?? [], activePlan, date, planCheckins);
  }, [store.planItems, activePlan, date, planCheckins]);
  const dailyCustomTodos = useMemo(() => {
    if (!activePlan) return [];
    return getTodayCustomTodos(store.dailyCustomTodos ?? [], activePlan.id, date);
  }, [store.dailyCustomTodos, activePlan, date]);
  const activeHabits = useMemo(() =>
    (store.habits ?? []).filter(h => !h.deleted && h.status === 'inProgress'),
    [store.habits],
  );

  // ── Section list discriminator ──
  type CheckinSectionKind = 'plan' | 'todo' | 'habit';
  interface CheckinSection {
    kind: CheckinSectionKind;
    title: string;
    data: ReadonlyArray<PlanItem | DailyCustomTodo | Habit>;
  }

  // ── Merge the 3 nested FlatLists into a single SectionList ──
  const sections = useMemo<CheckinSection[]>(() => {
    const out: CheckinSection[] = [];
    if (todayPlanItems.length > 0) out.push({ kind: 'plan', title: T('planTodoList'), data: todayPlanItems });
    if (dailyCustomTodos.length > 0) out.push({ kind: 'todo', title: T('planDailyCustomTodos'), data: dailyCustomTodos });
    if (activeHabits.length > 0) out.push({ kind: 'habit', title: T('checkinHabitCheck'), data: activeHabits });
    return out;
  }, [todayPlanItems, dailyCustomTodos, activeHabits, T]);
  const [planToggles, setPlanToggles] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    if (!activePlan) return initial;
    const items = (store.planItems ?? []).filter(i => !i.deleted && i.planId === activePlan.id);
    items.forEach(item => {
      if (item.link === 'manual' || item.link === 'reflection') {
        initial[item.id] = planCheckins.some(c => c.planItemId === item.id && c.date === date && c.done);
      }
    });
    return initial;
  });

  // ── Food for this date (read-only) ──
  const viewDateFoods = useMemo(() =>
    getFoodLogByDate((store.foodLog ?? []).filter(f => !f.deleted && f.name), date),
    [store.foodLog, date],
  );
  const totalCal = useMemo(() => viewDateFoods.reduce((a, f) => a + f.calories, 0), [viewDateFoods]);

  // ── Food add state ──
  const [showFoodAdd, setShowFoodAdd] = useState(false);
  const [foodName, setFoodName] = useState('');
  const [foodCal, setFoodCal] = useState('');

  /** Compute a noon timestamp for the target date (for food entries) */
  const dateTimestamp = useMemo(() => new Date(date + 'T12:00:00').getTime(), [date]);

  // ── Local state ──
  const [weight, setWeight] = useState(() => existing?.weight != null ? String(existing.weight) : String(store.userProfile?.weight ?? '65'));
  const [waterInput, setWaterInput] = useState(() => String(parsed.waterMl || ''));
  const [note, setNote] = useState(() => parsed.userNote);
  const [habitCheckins, setHabitCheckins] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    (store.habits ?? []).filter(h => !h.deleted && h.status === 'inProgress').forEach(h => {
      initial[h.id] = h.checkedDates?.includes(date) ?? false;
    });
    return initial;
  });

  // ── Submit — always done=true for grace makeup check-in ──
  const submit = useCallback(() => {
    if (submitted) return;

    // Process habit checkins
    Object.entries(habitCheckins).forEach(([id, checked]) => {
      const habit = (store.habits ?? []).find(h => !h.deleted && h.id === id);
      const alreadyDone = habit?.checkedDates?.includes(date) ?? false;
      if (checked !== alreadyDone) store.checkinHabit(id, date);
    });

    // Save plan item toggles
    Object.entries(planToggles).forEach(([itemId, desired]) => {
      const current = planCheckins.some(c => c.planItemId === itemId && c.date === date && c.done);
      if (desired && !current) store.checkinPlanItem(itemId, date);
      if (!desired && current) store.uncheckinPlanItem(itemId, date);
    });

    // Build note JSON
    const noteData: Record<string, unknown> = {};
    if (note) noteData.note = note;
    const waterMlVal = parseInt(waterInput) || 0;
    if (waterMlVal > 0) noteData.water = waterMlVal;
    const checkedHabits = Object.entries(habitCheckins)
      .filter(([, checked]) => checked)
      .map(([id]) => (store.habits ?? []).find(h => !h.deleted && h.id === id)?.name)
      .filter(Boolean);
    if (checkedHabits.length) noteData.habits = checkedHabits;
    const doneCustomTodos = dailyCustomTodos
      .filter(t => t.done)
      .map(t => t.name);
    if (doneCustomTodos.length) noteData.customs = doneCustomTodos;
    const donePlanItems = todayPlanItems
      .filter(item => planToggles[item.id] ?? planCheckins.some(c => c.planItemId === item.id && c.date === date && c.done))
      .map(item => item.name);
    if (donePlanItems.length) noteData.planItems = donePlanItems;
    if (totalCal > 0) noteData.food = totalCal;

    const weightNum = parseWeight(weight);
    store.submitCheckin(true, JSON.stringify(noteData), date, weightNum);

    // Grace mode: record grace
    if (isGraceMode) {
      store.addGraceRecord(date);
    }

    setSubmitted(true);
    nav.goBack();
  }, [submitted, habitCheckins, planToggles, planCheckins, dailyCustomTodos, todayPlanItems, date, isGraceMode, waterInput, note, totalCal, weight, store, nav]);

  // ── Render helpers ──
  const renderPlanItem = useCallback(({ item }: { item: PlanItem }) => {
    const storeDone = planCheckins.some(c => c.planItemId === item.id && c.date === date && c.done);
    const done = planToggles[item.id] ?? storeDone;
    return (
      <View style={{
        flexDirection:'row', alignItems:'center', paddingVertical:8,
        paddingHorizontal:4, borderRadius:8,
        backgroundColor: done ? `${P}10` : 'transparent',
        marginBottom:4,
      }}>
        <Checkbox on={done} onChange={() => setPlanToggles(prev => ({ ...prev, [item.id]: !done }))} accessibilityLabel={`${done ? '取消' : '完成'} ${item.name}`} />
        <View style={{ flex:1, marginLeft:8 }}>
          <Text style={{
            fontSize:FONT_BODY(), color: done ? TH.sub : TH.text,
            textDecorationLine: done ? 'line-through' : 'none',
          }} numberOfLines={1}>{item.name}</Text>
        </View>
      </View>
    );
  }, [planCheckins, date, planToggles, P, TH, setPlanToggles]);

  const renderTodoItem = useCallback(({ item: todo }: { item: DailyCustomTodo }) => (
    <View style={{
      flexDirection:'row', alignItems:'center', paddingVertical:8,
      paddingHorizontal:4, borderRadius:8,
      backgroundColor: todo.done ? `${P}10` : 'transparent',
      marginBottom:4,
    }}>
      <Checkbox on={todo.done} onChange={() => store.toggleDailyCustomTodo(todo.id, date)} accessibilityLabel={`${todo.done ? '取消' : '完成'} ${todo.name}`} />
      <Text style={{
        flex:1, marginLeft:8, fontSize:FONT_BODY(),
        color: todo.done ? TH.sub : TH.text,
        textDecorationLine: todo.done ? 'line-through' : 'none',
      }}>{todo.name}</Text>
    </View>
  ), [P, TH, store, date]);

  const renderHabitItem = useCallback(({ item: h }: { item: Habit }) => (
    <View style={{
      flexDirection:'row', alignItems:'center', paddingVertical:8,
      paddingHorizontal:4, borderRadius:8, marginBottom:4,
    }}>
      <Checkbox on={!!habitCheckins[h.id]} onChange={() => setHabitCheckins(c => ({ ...c, [h.id]:!c[h.id] }))} accessibilityLabel={`${habitCheckins[h.id] ? '取消' : '打卡'} ${h.name}`} />
      <View style={{ flex:1, marginLeft:8 }}>
        <Text style={{ fontSize:FONT_BODY(), color:TH.text }}>{h.name}</Text>
        <Text style={{ fontSize:FONT_SUB(), color:TH.sub }}>{String(h.streak)} {T('checkinStreak')}</Text>
      </View>
    </View>
  ), [habitCheckins, setHabitCheckins, TH, T]);

  // ── SectionList renderers (unified for plan/todo/habit) ──
  const renderSectionItem = useCallback(({ item, section }: { item: PlanItem | DailyCustomTodo | Habit; section: CheckinSection }) => {
    switch (section.kind) {
      case 'plan':
        return renderPlanItem({ item: item as PlanItem });
      case 'todo':
        return renderTodoItem({ item: item as DailyCustomTodo });
      case 'habit':
        return renderHabitItem({ item: item as Habit });
    }
  }, [renderPlanItem, renderTodoItem, renderHabitItem]);

  const renderSectionHeader = useCallback(({ section }: { section: CheckinSection }) => (
    <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>{section.title}</Text>
  ), [TH]);

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: TH.bg }}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        style={{ flex: 1 }}
      >
        {/* ── Header ── */}
        <View style={{
          flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16,
          paddingVertical: 14, borderBottomWidth: 1, borderBottomColor: TH.border,
        }}>
          <TouchableOpacity onPress={() => nav.goBack()} accessibilityLabel={T('commonBack')}>
            <ChevronLeft size={24} color={TH.text} />
          </TouchableOpacity>
          <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE(), marginLeft: 12 }}>
            {isGraceMode ? T('graceCheckinTitle') : T('checkinDetailTitle')}
          </Text>
        </View>

        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={{ padding: 16, paddingBottom: 40 }}
          showsVerticalScrollIndicator={false}
        >
          {/* ── Grace mode banner ── */}
          {isGraceMode && (
            <View style={{
              flexDirection: 'row', alignItems: 'center', gap: 8,
              padding: 12, borderRadius: 10, marginBottom: 12,
              backgroundColor: `${COLORS.ORANGE}15`, borderWidth: 1, borderColor: `${COLORS.ORANGE}30`,
            }}>
              <Shield size={16} color={COLORS.ORANGE} />
              <Text style={{ fontSize: FONT_SUB(), color: COLORS.ORANGE, flex: 1 }}>
                {T('graceCheckinHint')} · {date}
              </Text>
            </View>
          )}

          {/* ── Tasks card ── */}
          <View style={{ backgroundColor:TH.card, borderRadius:16, padding:14, marginBottom:12 }}>
            <View style={{ flexDirection:'row', alignItems:'center', gap:8, marginBottom:14 }}>
              <ClipboardList size={18} color={P} />
              <Text style={{ fontWeight:'600', fontSize:FONT_BODY(), color:TH.text }}>
                {isGraceMode ? `${date} ${T('graceTitle')}` : T('planTodoList')}
              </Text>
            </View>

            {/* Merged plan / todos / habits into one SectionList */}
            {sections.length > 0 && (
              <SectionList
                sections={sections}
                keyExtractor={(item) => item.id}
                renderItem={renderSectionItem}
                renderSectionHeader={renderSectionHeader}
                scrollEnabled={false}
                removeClippedSubviews={true}
                stickySectionHeadersEnabled={false}
              />
            )}
          </View>

          {/* ── Data card: Weight + Water + Food ── */}
          <View style={{ backgroundColor:TH.card, borderRadius:16, padding:14, marginBottom:12 }}>
            <View style={{ flexDirection:'row', alignItems:'center', gap:8, marginBottom:14 }}>
              <Scale size={18} color={P} />
              <Text style={{ fontWeight:'600', fontSize:FONT_BODY(), color:TH.text }}>
                {T('todayWeight')} / {T('water')} / {T('checkinFood')}
              </Text>
            </View>

            {/* Weight */}
            <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between', paddingVertical:10, borderBottomWidth:1, borderBottomColor:TH.border }}>
              <View style={{ flexDirection:'row', alignItems:'center', gap:8 }}>
                <Scale size={16} color={P} />
                <Text style={{ color:TH.text, fontSize:FONT_BODY() }}>{T('todayWeight')}</Text>
              </View>
              <View style={{ flexDirection:'row', alignItems:'center', gap:6 }}>
                <TextInput
                  value={weight}
                  onChangeText={setWeight}
                  placeholder="..."
                  placeholderTextColor={TH.sub}
                  keyboardType="numeric"
                  accessibilityLabel={T('todayWeight')}
                  style={{ width:60, textAlign:'center', borderWidth:1, borderColor:TH.border, borderRadius:8, paddingVertical:6, color:TH.text, fontWeight:'600', fontSize:FONT_BODY(), backgroundColor:TH.card }}
                />
                <Text style={{ color:TH.sub, fontSize:FONT_SUB() }}>{store.weightUnit === 'kg' ? T('checkinKg') : T('checkinLb')}</Text>
              </View>
            </View>

            {/* Water */}
            <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between', paddingVertical:10, borderBottomWidth:1, borderBottomColor:TH.border }}>
              <View style={{ flexDirection:'row', alignItems:'center', gap:8 }}>
                <Droplets size={16} color={P} />
                <Text style={{ color:TH.text, fontSize:FONT_BODY() }}>{T('water')}</Text>
              </View>
              <View style={{ flexDirection:'row', alignItems:'center', gap:6 }}>
                <TextInput
                  value={waterInput}
                  onChangeText={setWaterInput}
                  placeholder="0"
                  placeholderTextColor={TH.sub}
                  keyboardType="numeric"
                  accessibilityLabel={T('water')}
                  style={{ width:60, textAlign:'center', borderWidth:1, borderColor:TH.border, borderRadius:8, paddingVertical:6, color:TH.text, fontWeight:'600', fontSize:FONT_BODY(), backgroundColor:TH.card }}
                />
                <Text style={{ color:TH.sub, fontSize:FONT_SUB() }}>ml</Text>
              </View>
            </View>

            {/* Food */}
            <View style={{ paddingVertical:10 }}>
              <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between' }}>
                <View style={{ flexDirection:'row', alignItems:'center', gap:8 }}>
                  <Utensils size={16} color={P} />
                  <Text style={{ color:TH.text, fontSize:FONT_BODY() }}>{T('checkinFood')}</Text>
                </View>
                <View style={{ flexDirection:'row', alignItems:'center', gap:8 }}>
                  <Text style={{ fontSize:FONT_TITLE(), fontWeight:'600', color:P }}>{String(totalCal)}</Text>
                  <Text style={{ color:TH.sub, fontSize:FONT_SUB() }}>kcal</Text>
                  <TouchableOpacity onPress={() => setShowFoodAdd(!showFoodAdd)}
                    accessibilityLabel={T('addFood')}
                    style={{ width:24, height:24, borderRadius:12, backgroundColor:P, alignItems:'center', justifyContent:'center' }}>
                    <Plus size={14} color="#fff" />
                  </TouchableOpacity>
                </View>
              </View>
              {showFoodAdd && (
                <View style={{ marginTop:10, padding:10, backgroundColor:TH.cardSolid, borderRadius:10, borderWidth:1, borderColor:TH.border }}>
                  <View style={{ flexDirection:'row', gap:8, marginBottom:8 }}>
                    <ThemedInput value={foodName} onChangeText={setFoodName} placeholder={T('foodName')} accessibilityLabel={T('foodName')} style={{ flex:2, padding:7 }} />
                    <ThemedInput value={foodCal} onChangeText={setFoodCal} placeholder={T('calories2')} keyboardType="numeric" accessibilityLabel={T('calories2')} style={{ flex:1, padding:7 }} />
                  </View>
                  <View style={{ flexDirection:'row', gap:8 }}>
                    <TouchableOpacity onPress={() => {
                      if (foodName.trim()) {
                        store.addFood({ name: foodName, calories: +foodCal || 0, note: '', timestamp: dateTimestamp });
                        setFoodName('');
                        setFoodCal('');
                        setShowFoodAdd(false);
                      }
                    }}
                      accessibilityLabel={T('confirm')}
                      style={{ flex:1, padding:8, borderRadius:8, backgroundColor:P, alignItems:'center' }}>
                      <Text style={{ color:'#fff', fontWeight:'600', fontSize:FONT_BUTTON() }}>{T('confirm')}</Text>
                    </TouchableOpacity>
                    <TouchableOpacity onPress={() => { setShowFoodAdd(false); setFoodName(''); setFoodCal(''); }}
                      accessibilityLabel={T('commonCancel')}
                      style={{ paddingVertical:8, paddingHorizontal:12, borderRadius:8, borderWidth:1, borderColor:TH.border, alignItems:'center' }}>
                      <Text style={{ color:TH.sub, fontSize:FONT_BUTTON() }}>{T('commonCancel')}</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              )}
            </View>
          </View>

          {/* ── Note card ── */}
          <View style={{ backgroundColor:TH.card, borderRadius:16, padding:14, marginBottom:12 }}>
            <View style={{ flexDirection:'row', alignItems:'center', gap:8, marginBottom:10 }}>
              <Sparkles size={18} color={P} />
              <Text style={{ fontWeight:'600', fontSize:FONT_BODY(), color:TH.text }}>{T('checkinNote')}</Text>
            </View>
            <ThemedInput value={note} onChangeText={setNote} placeholder={T('checkinNotePlaceholder')} accessibilityLabel={T('checkinNote')} multiline numberOfLines={3} />
          </View>

          {/* ── Submit button ── */}
          <TouchableOpacity onPress={submit} accessibilityLabel={T('graceCheckinSubmit')} style={{
            paddingVertical:14, borderRadius:12, alignItems:'center', marginBottom:10,
            backgroundColor: '#17EAD9',
          }}>
            <View style={{ flexDirection:'row', alignItems:'center', gap:6 }}>
              <Check size={18} color="#fff" />
              <Text style={{ color:'#fff', fontWeight:'700', fontSize:FONT_BUTTON() }}>
                {T('graceCheckinSubmit')}
              </Text>
            </View>
          </TouchableOpacity>

          {/* ── Cancel ── */}
          <TouchableOpacity onPress={() => nav.goBack()} accessibilityLabel={T('commonCancel')} style={{
            paddingVertical:14, borderRadius:12, alignItems:'center',
            borderWidth:1, borderColor:TH.border,
          }}>
            <Text style={{ color:TH.sub, fontSize:FONT_BUTTON() }}>{T('commonCancel')}</Text>
          </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

import { COLORS, getTodayFoodLog, dateStr, FONT_TITLE, FONT_BODY, FONT_BUTTON, FONT_SUB, FONT_STAT_CARD, FONT_STAT_SECTION, FONT_BACK, FONT_EMPTY } from '@egoless-do/core';
import { ChevronDown, ChevronRight, X } from 'lucide-react-native';
import React, { useState, useMemo } from 'react';
import { View, Text, ScrollView, StyleSheet, TouchableOpacity, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import AddFoodModal from '../../../components/AddFoodModal';
import { Card, useTheme, useT, ScreenHeader } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


export default function FoodLogPage() {
  const nav   = useRootNavigation();
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const { foodLog, calGoal, deleteFood } = useShallowStore(s => ({
    foodLog: s.foodLog,
    calGoal: s.calGoal,
    deleteFood: s.deleteFood,
  }));
  const [showAdd, setShowAdd]     = useState(false);
  const [showHistory, setShowHistory] = useState(true);

  const filteredFoodLog = useMemo(() => (foodLog ?? []).filter(f => !f.deleted), [foodLog]);
  const totalCal = useMemo(() => getTodayFoodLog(filteredFoodLog).reduce((a, f) => a + (f.calories ?? 0), 0), [filteredFoodLog]);

  const historyGroups = useMemo(() => {
    const today = dateStr();
    const past = filteredFoodLog.filter(f => dateStr(new Date(f.timestamp)) !== today);
    const groups: Record<string, typeof past> = {};
    for (const f of past) {
      const d = dateStr(new Date(f.timestamp));
      (groups[d] ??= []).push(f);
    }
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [filteredFoodLog]);

  const totalHistoryCal = useMemo(() => historyGroups.reduce((sum, [, entries]) => sum + entries.reduce((a, f) => a + (f.calories ?? 0), 0), 0), [historyGroups]);
  const totalRecords = useMemo(() => historyGroups.reduce((sum, [, entries]) => sum + entries.length, 0), [historyGroups]);


  const confirmDelete = (id: string) => {
    Alert.alert('', T('foodDeleteConfirm'), [
      { text: T('commonCancel'), style: 'cancel' },
      { text: T('commonConfirm'), style: 'destructive', onPress: () => deleteFood(id) },
    ]);
  };

  return (
    <SafeAreaView style={{ flex:1, backgroundColor: TH.bg }}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        <ScreenHeader title={T('foodTitle')} onBack={() => nav.goBack()} />

        <Card style={styles.todayCard}>
          <Text style={{ color:TH.sub, fontSize:FONT_BODY(), marginBottom:8 }}>{T('foodTodayKcal')}</Text>
          <View style={styles.todayRow}>
            <Text style={{ fontSize:FONT_STAT_SECTION(), fontWeight:'800', color:P }}>{String(totalCal)}</Text>
            <Text style={{ fontSize:FONT_BACK(), color:TH.sub }}>/ {calGoal}</Text>
          </View>
          <Text style={[styles.remainingText, { color: totalCal > calGoal ? COLORS.RED : COLORS.GREEN, fontSize:FONT_BODY() }]}>{T('foodRemaining')}: {String(Math.max(0, calGoal - totalCal))} kcal</Text>
        </Card>

        <Card>
          {(() => {
            const todayLog = getTodayFoodLog(filteredFoodLog);
            return todayLog.length === 0 ? (
              <Text style={[styles.emptyText, { color:TH.sub, fontSize:FONT_EMPTY() }]}>{T('foodEmpty')}</Text>
            ) : (
              todayLog.map((f, idx) => (
                <View key={f.id} style={[styles.todayItem, idx < todayLog.length - 1 && { borderBottomWidth: 1, borderBottomColor: TH.border }]}>
                  <View style={styles.itemNameCol}>
                    <Text style={{ fontWeight:'600', fontSize:FONT_BODY(), color:TH.text }}>{f.name}</Text>
                    {f.note ? <Text style={{ fontSize:FONT_SUB(), color:TH.sub }}>{f.note}</Text> : null}
                  </View>
                  <Text style={[styles.boldText, { color:P }]}>{String(f.calories ?? 0)} kcal</Text>
                </View>
              ))
            );
          })()}
        </Card>

        <TouchableOpacity onPress={() => setShowAdd(true)}
          style={[styles.addButton, { backgroundColor:P }]}>
          <Text style={[styles.addButtonText, { fontSize:FONT_BUTTON() }]}>{T('foodAdd')}</Text>
        </TouchableOpacity>

        {/* ── History ── */}
        <View style={styles.historySection}>
          <TouchableOpacity onPress={() => setShowHistory(v => !v)}
            style={[styles.historyToggleButton, { marginBottom: showHistory ? 12 : 0 }]}>
            <View style={styles.historyToggleView}>
              <Text style={{ fontWeight:'700', fontSize:FONT_TITLE(), color:TH.text }}>{T('foodHistory')}</Text>
              {showHistory ? <ChevronDown size={18} color={TH.text} /> : <ChevronRight size={18} color={TH.text} />}
            </View>
          </TouchableOpacity>
          {showHistory && (
            <>
              {/* Summary stats */}
              {historyGroups.length > 0 && (
                <View style={[styles.historyStatsRow, { backgroundColor:TH.card, borderWidth:1, borderColor:TH.border }]}>
                  {[
                    { value: String(historyGroups.length), label: '天' },
                    { value: String(totalRecords), label: '条记录' },
                    { value: String(totalHistoryCal), label: 'kcal' },
                  ].map(st => (
                    <View key={st.label} style={styles.statItem}>
                      <Text style={{ fontSize:FONT_STAT_CARD(), fontWeight:'800', color:P }}>{String(st.value)}</Text>
                      <Text style={{ fontSize:FONT_SUB(), color:TH.sub, marginTop:2 }}>{st.label}</Text>
                    </View>
                  ))}
                </View>
              )}
              {historyGroups.length === 0 ? (
                <Text style={[styles.emptyText, { color:TH.sub, fontSize:FONT_EMPTY() }]}>{T('foodNoHistory')}</Text>
              ) : (
                <View style={styles.timelineContainer}>
                  {/* Timeline vertical line */}
                  <View style={[styles.timelineLine, { backgroundColor:TH.border }]} />
                  {historyGroups.map(([date, entries]) => {
                    const dayCal = entries.reduce((a, f) => a + (f.calories ?? 0), 0);
                    return (
                      <View key={date} style={styles.timelineEntry}>
                        {/* Timeline dot */}
                        <View style={[styles.timelineDot, { backgroundColor:P, borderColor:TH.bg }]} />
                        {/* Card */}
                        <View style={[styles.historyCard, { backgroundColor:TH.card, borderWidth:1, borderColor:TH.border }]}>
                          <View style={[styles.historyHeader, { borderBottomColor:TH.border, backgroundColor:`${P}08` }]}>
                            <Text style={[styles.dateText, { fontSize:FONT_BODY(), color:TH.text }]}>{date}</Text>
                            <Text style={{ fontSize:FONT_BODY(), color:P, fontWeight:'700' }}>{dayCal} kcal</Text>
                          </View>
                          {entries.map((f, i) => (
                            <View key={f.id} style={[styles.historyEntryItem, { borderTopWidth: i > 0 ? 1 : 0, borderTopColor:TH.border }]}>
                              <View style={styles.itemNameCol}>
                                <Text style={{ fontWeight:'600', fontSize:FONT_BODY(), color:TH.text }}>{f.name}</Text>
                                {f.note ? <Text style={{ fontSize:FONT_SUB(), color:TH.sub, marginLeft:8 }}>{f.note}</Text> : null}
                              </View>
                              <View style={styles.calorieRow}>
                                <Text style={{ fontWeight:'700', color:P, fontSize:FONT_BODY() }}>{String(f.calories ?? 0)} kcal</Text>
                                <TouchableOpacity onPress={() => confirmDelete(f.id)} style={styles.deleteButton}>
                                  <X size={18} color="rgba(255,255,255,.7)" />
                                </TouchableOpacity>
                              </View>
                            </View>
                          ))}
                        </View>
                      </View>
                    );
                  })}
                </View>
              )}
            </>
          )}
        </View>
      </ScrollView>

      <AddFoodModal visible={showAdd} onClose={() => setShowAdd(false)} />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  scrollContent: { padding: 16, paddingBottom: 40 },
  todayCard: { alignItems: 'center', paddingVertical: 20 },
  todayRow: { flexDirection: 'row', alignItems: 'baseline', gap: 8 },
  remainingText: { marginTop: 6 },
  emptyText: { textAlign: 'center', padding: 24 },
  todayItem: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 8, paddingHorizontal: 12 },
  itemNameCol: { flex: 1 },
  boldText: { fontWeight: '700' },
  addButton: { borderRadius: 12, padding: 14, alignItems: 'center', marginTop: 12 },
  addButtonText: { color: '#fff', fontWeight: '700' },
  historySection: { marginTop: 24 },
  historyToggleButton: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  historyToggleView: { flexDirection: 'row', alignItems: 'center', gap: 4 },
  historyStatsRow: { flexDirection: 'row', borderRadius: 14, paddingVertical: 14, marginBottom: 16 },
  statItem: { flex: 1, alignItems: 'center' },
  timelineContainer: { position: 'relative', paddingLeft: 20 },
  timelineLine: { position: 'absolute', left: 6, top: 6, bottom: 6, width: 2, borderRadius: 1 },
  timelineEntry: { position: 'relative', marginBottom: 16 },
  timelineDot: { position: 'absolute', left: -17, top: 14, width: 10, height: 10, borderRadius: 5, borderWidth: 2 },
  historyCard: { borderRadius: 12, overflow: 'hidden' },
  historyHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 10, paddingHorizontal: 14, borderBottomWidth: 1 },
  dateText: { fontWeight: '600' },
  historyEntryItem: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 8, paddingHorizontal: 14 },
  calorieRow: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  deleteButton: { paddingLeft: 8 },
});

import { COLORS, yesterday, dateStr, FONT_BODY, FONT_TITLE, FONT_SUB, FONT_SMALL, FONT_TINY,
  getMonthGraceCount, getRemainingGrace, isGraceAvailable } from '@egoless-do/core';
import { Shield, ShieldCheck, CheckCircle2, Clock, Calendar, Settings } from 'lucide-react-native';
import React, { useMemo, useCallback } from 'react';
import { View, Text, ScrollView, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, useTheme, useT, ScreenHeader } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import { useShallowStore } from '../../../store/useAppStore';

export default function GracePage() {
  const nav   = useRootNavigation();
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const { checkinHistory, userProfile, graceHistory, updateUserProfile } = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    userProfile: s.userProfile,
    graceHistory: s.graceHistory,
    updateUserProfile: s.updateUserProfile,
  }));

  const yStr = yesterday();
  const currentMonth = dateStr().slice(0, 7); // "2026-06"

  const yesterdayRecord = checkinHistory?.find(h => !h.deleted && h.date === yStr);
  const yesterdayDone = yesterdayRecord?.done === true;
  const missed = !yesterdayDone;

  // Quota
  const quota = userProfile?.graceMonthlyQuota ?? 2;
  const monthUsed = useMemo(() => getMonthGraceCount(graceHistory ?? [], currentMonth), [graceHistory, currentMonth]);
  const remaining = useMemo(() => getRemainingGrace(graceHistory ?? [], quota, currentMonth), [graceHistory, quota, currentMonth]);
  const available = useMemo(() => isGraceAvailable(graceHistory ?? [], quota, currentMonth, yStr), [graceHistory, quota, currentMonth, yStr]);

  // Grace history (sorted by date desc)
  const graceHistorySorted = useMemo(() =>
    (graceHistory ?? []).filter(g => !g.deleted).sort((a, b) => b.date.localeCompare(a.date)),
    [graceHistory],
  );

  const handleRestore = useCallback(() => {
    if (!available) return;
    nav.navigate('DayCheckin', { date: yStr, graceMode: true });
  }, [available, nav, yStr]);

  const updateQuota = useCallback((q: number) => {
    updateUserProfile({ graceMonthlyQuota: q });
  }, [updateUserProfile]);

  // Quota selector options
  const quotaOptions = [0, 1, 2, 3, 4, 5];

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: TH.bg }}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={{ padding: 16, paddingBottom: 32 }}
        showsVerticalScrollIndicator={false}
      >
        <ScreenHeader title={T('graceTitle')} onBack={() => nav.goBack()} />

        {/* Status Card */}
        <Card style={{ padding: 20, marginBottom: 12 }}>
          <View style={{ alignItems: 'center', marginBottom: 16 }}>
            {missed ? (
              available ? (
                <View style={{ alignItems: 'center' }}>
                  <Shield size={48} color={P} />
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginTop: 12 }}>
                    {T('graceNeedRestore')}
                  </Text>
                </View>
              ) : (
                <View style={{ alignItems: 'center' }}>
                  <Shield size={48} color={TH.sub} />
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: COLORS.ORANGE, marginTop: 12 }}>
                    {T('graceQuotaExhausted')}
                  </Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 4 }}>
                    {T('graceQuotaReset')}
                  </Text>
                </View>
              )
            ) : (
              <View style={{ alignItems: 'center' }}>
                <CheckCircle2 size={48} color={COLORS.GREEN} />
                <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: COLORS.GREEN, marginTop: 12 }}>
                  {T('graceAlreadyDone')}
                </Text>
              </View>
            )}
          </View>

          {/* Yesterday status */}
          <View style={{
            flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
            padding: 14, backgroundColor: TH.card, borderRadius: 12, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
              <Clock size={18} color={TH.sub} />
              <View>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{yStr}</Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('graceYesterday')}</Text>
              </View>
            </View>
            <View style={{
              paddingHorizontal: 10, paddingVertical: 4, borderRadius: 8,
              backgroundColor: missed ? `${COLORS.ORANGE}20` : `${COLORS.GREEN}20`,
            }}>
              <Text style={{
                fontSize: FONT_SUB(), fontWeight: '600',
                color: missed ? COLORS.ORANGE : COLORS.GREEN,
              }}>
                {missed ? T('graceNotDone') : T('graceDone')}
              </Text>
            </View>
          </View>

          {/* Restore button */}
          {missed && available && (
            <TouchableOpacity
              onPress={handleRestore}
              style={{
                flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
                gap: 8, paddingVertical: 14, borderRadius: 12, backgroundColor: P,
              }}
            >
              <Shield size={18} color="#fff" />
              <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BODY() }}>
                {T('graceButton')}
              </Text>
            </TouchableOpacity>
          )}

          {/* Grace hint */}
          {missed && !available && quota > 0 && (
            <View style={{ padding: 12, alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>
                {T('graceQuotaUsed').replace('{used}', String(monthUsed)).replace('{total}', String(quota))}
              </Text>
            </View>
          )}
        </Card>

        {/* Quota Progress */}
        {quota > 0 && (
          <Card style={{ padding: 16, marginBottom: 12 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('graceQuotaUsed').replace('{used}', String(monthUsed)).replace('{total}', String(quota))}
              </Text>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{remaining} {T('graceUsedTimes')}</Text>
            </View>
            <View style={{ height: 8, backgroundColor: TH.border, borderRadius: 4, overflow: 'hidden' }}>
              <View style={{
                height: 8, borderRadius: 4,
                width: `${Math.min(100, (monthUsed / quota) * 100)}%`,
                backgroundColor: monthUsed >= quota ? COLORS.ORANGE : P,
              }} />
            </View>
          </Card>
        )}

        {/* Quota Setting */}
        <Card style={{ padding: 16, marginBottom: 12 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
            <Settings size={16} color={P} />
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
              {T('graceSettingTitle')}
            </Text>
          </View>
          <View style={{ flexDirection: 'row', gap: 8 }}>
            {quotaOptions.map(q => (
              <TouchableOpacity
                key={q}
                onPress={() => updateQuota(q)}
                style={{
                  flex: 1, paddingVertical: 10, borderRadius: 10, alignItems: 'center',
                  backgroundColor: quota === q ? P : TH.card,
                  borderWidth: 1, borderColor: quota === q ? P : TH.border,
                }}
              >
                <Text style={{
                  fontSize: FONT_BODY(), fontWeight: '700',
                  color: quota === q ? '#fff' : TH.text,
                }}>{q}</Text>
              </TouchableOpacity>
            ))}
          </View>
          <Text style={{ fontSize: FONT_TINY(), color: TH.sub, marginTop: 8 }}>
            {T('graceSettingHint')}
          </Text>
        </Card>

        {/* Grace History Timeline */}
        <Card style={{ padding: 16, marginBottom: 12 }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
            <Calendar size={16} color={P} />
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
              {T('graceHistory')}
            </Text>
          </View>
          {graceHistorySorted.length === 0 ? (
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, textAlign: 'center', padding: 12 }}>
              {T('graceHistoryEmpty')}
            </Text>
          ) : (
            <View>
              {graceHistorySorted.map((entry, idx) => {
                const restoredDate = new Date(entry.restoredAt);
                const timeStr = restoredDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                return (
                  <View key={entry.date} style={{
                    flexDirection: 'row', alignItems: 'flex-start', gap: 12,
                    paddingBottom: idx < graceHistorySorted.length - 1 ? 12 : 0,
                    marginBottom: idx < graceHistorySorted.length - 1 ? 12 : 0,
                    borderBottomWidth: idx < graceHistorySorted.length - 1 ? 1 : 0,
                    borderBottomColor: TH.border,
                  }}>
                    <View style={{
                      width: 8, height: 8, borderRadius: 4, backgroundColor: P,
                      marginTop: 6,
                    }} />
                    <View style={{ flex: 1 }}>
                      <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                        {entry.date}
                      </Text>
                      <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>
                        {T('graceCheckinTitle')} · {timeStr}
                      </Text>
                    </View>
                  </View>
                );
              })}
            </View>
          )}
        </Card>

        {/* Info Card */}
        <Card style={{ padding: 16 }}>
          <Text style={{ fontSize: FONT_BODY(), color: TH.sub, lineHeight: 22 }}>
            {T('graceDesc')}
          </Text>
        </Card>
      </ScrollView>
    </SafeAreaView>
  );
}

import { THEMES, COLORS, cardTextColor, dateStr, yesterday, addDays, getFoodLogByDate, getRecentFoods, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BUTTON, FONT_STAT_CARD, FONT_SMALL, FONT_LABEL, FONT_CARD_TITLE, parseCheckinNote, getActivePlan, getTodayItems, getTodayCustomTodos, isPlanDelayed, getIncompleteItems, INCOMPLETE_REASONS, getStatsForDate, isGraceAvailable, createLogger, formatTime } from '@egoless-do/core';
import type { CheckinEntry, Habit } from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import {
  Scale, Footprints,
  Droplets, Pencil, Check, X, Star, Sparkles,
  ClipboardList, Target, BarChart3,
  ChevronLeft, ChevronRight, Calendar,
} from 'lucide-react-native';
import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import {
  View, Text, ScrollView, TouchableOpacity,
  StatusBar, Modal, TextInput,
  KeyboardAvoidingView, Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useShallow } from 'zustand/react/shallow';

import { useTheme, useT, ProgressBar, Checkbox, ThemedInput } from '../../../components/UI';
import SimpleHeader from '../../../navigation/SimpleHeader';
import { useRootNavigation } from '../../../navigation/hooks';
import { useNavigateToTab } from '../../../navigation/useAppNavigation';
import { useAppStore, useShallowStore, type MobileStore } from '../../../store/useAppStore';
import { useDateNavigation } from '../hooks/useDateNavigation';

const log = createLogger('Home');
import Banner from '../components/Banner';
import CheckinStatsModal from '../components/CheckinStatsModal';
import DateBar from '../components/DateBar';
import DelayedReminder from '../components/DelayedReminder';
import GraceReminder from '../components/GraceReminder';
import HomeBubble from '../components/HomeBubble';
import HomeFoodSection from '../components/HomeFoodSection';
import HomePlanSection from '../components/HomePlanSection';

type CheckinStatus = 'draft' | 'done' | 'editing';

/** Habit row — extracted from the former scrollEnabled={false} FlatList so the
 *  check-in card renders all its rows with a single inline .map() instead of a
 *  nested virtualised list. */
function HabitItem({ habit, viewDate, TH, P, T, isReadOnly, onToggle }: {
  habit: Habit;
  viewDate: string;
  TH: ReturnType<typeof useTheme>;
  P: string;
  T: (key: string) => string;
  isReadOnly: boolean;
  onToggle: (id: string) => void;
}) {
  const habitDone = habit.checkedDates?.includes(viewDate) ?? false;
  return (
    <View style={{
      flexDirection: 'row', alignItems: 'center',
      justifyContent: 'space-between', paddingVertical: 12,
      borderBottomWidth: 1, borderBottomColor: TH.border,
    }}>
      <View style={styles.flexRowGap10}>
        <Star size={16} color={P} />
        <View>
          <Text style={{ color: isReadOnly && !habitDone ? TH.sub : TH.text, fontSize: FONT_BODY(), opacity: isReadOnly && !habitDone ? 0.5 : 1 }}>{habit.name}</Text>
          <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{String(habit.streak)} {T('checkinStreak')}</Text>
        </View>
      </View>
      {isReadOnly ? (
        habitDone
          ? <Check size={18} color={COLORS.GREEN} />
          : <X size={18} color={TH.sub} />
      ) : (
        <Checkbox on={habitDone} onChange={() => onToggle(habit.id)} accessibilityLabel={`${habit.name} ${habitDone ? T('done') : T('notDone')}`} />
      )}
    </View>
  );
}

/** Parse weight string, return undefined if invalid or out of range (1-500 kg) */
function parseWeight(raw: string | undefined): number | undefined {
  if (!raw) return undefined;
  const n = parseFloat(raw);
  return Number.isFinite(n) && n > 0 && n <= 500 ? n : undefined;
}

export default function HomeScreen() {
  // ═══════════════════════════════════════════════════════════════
  // Section 1: Store Data & Navigation
  // ═══════════════════════════════════════════════════════════════
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const {
    checkinHistory, plans, planItemCheckins, planItems, dailyCustomTodos,
    foodLog, habits, streak, waterMl, waterGoal, calGoal,
    healthSyncEnabled, todaySteps, userProfile, graceHistory,
    setWeightUnit, submitCheckin, checkinHabit, addWater,
    setWaterGoal, setCalGoal, checkAutoStatus, autoSyncPlanItems,
    checkinPlanItem, uncheckinPlanItem, toggleDailyCustomTodo,
    addFood, deleteFood,
  } = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    plans: s.plans,
    planItemCheckins: s.planItemCheckins,
    planItems: s.planItems,
    dailyCustomTodos: s.dailyCustomTodos,
    foodLog: s.foodLog,
    habits: s.habits,
    streak: s.streak,
    waterMl: s.waterMl,
    waterGoal: s.waterGoal,
    calGoal: s.calGoal,
    healthSyncEnabled: s.healthSyncEnabled,
    todaySteps: s.todaySteps,
    userProfile: s.userProfile,
    graceHistory: s.graceHistory,
    setWeightUnit: s.setWeightUnit,
    submitCheckin: s.submitCheckin,
    checkinHabit: s.checkinHabit,
    addWater: s.addWater,
    setWaterGoal: s.setWaterGoal,
    setCalGoal: s.setCalGoal,
    checkAutoStatus: s.checkAutoStatus,
    autoSyncPlanItems: s.autoSyncPlanItems,
    checkinPlanItem: s.checkinPlanItem,
    uncheckinPlanItem: s.uncheckinPlanItem,
    toggleDailyCustomTodo: s.toggleDailyCustomTodo,
    addFood: s.addFood,
    deleteFood: s.deleteFood,
  }));
  const nav   = useRootNavigation();
  const navigateToTab = useNavigateToTab();
  const language = useAppStore(useShallow((s: MobileStore) => s.language));

  // ── Date state ──
  const { viewDate, isToday, goToDate, onTouchStart, onTouchEnd, viewDateRef } = useDateNavigation();

  const weightUnit = useShallowStore(s => s.weightUnit);

  // ── 性能优化：streak 懒加载 ──
  useEffect(() => {
    const state = useAppStore.getState();
    if (state.streak === undefined || state.streak === null) {
      state.calculateStreak();
    }
  }, []);

  // ═══════════════════════════════════════════════════════════════
  // Section 2: Derived Data & Status
  // ═══════════════════════════════════════════════════════════════

  // ── Existing checkin ──
  const todayRecord = useMemo(
    () => (checkinHistory ?? []).find((c: CheckinEntry) => !c.deleted && c.date === viewDate),
    [checkinHistory, viewDate],
  );
  const parsed = useMemo(() => parseCheckinNote(todayRecord?.note ?? ''), [todayRecord]);

  // ── Local state (initialized from existing record) ──
  const [showStatsModal, setShowStatsModal] = useState(false);
  const [localDone, setLocalDone] = useState<boolean | null>(() => todayRecord?.done ?? null);
  const [note, setNote] = useState(() => parsed.userNote);
  const [weight, setWeight] = useState(() => {
    if (todayRecord?.weight != null) return String(todayRecord.weight);
    // Default to profile weight on new day
    const profileWeight = userProfile?.weight;
    return profileWeight != null ? String(profileWeight) : '';
  });
  // habitCheckins derived from store — no local state needed

  // ── Plan items ──
  const activePlan = useMemo(() => getActivePlan(plans ?? []), [plans]);
  const planCheckins = useMemo(() => (planItemCheckins ?? []).filter(c => !c.deleted), [planItemCheckins]);
  const todayPlanItems = useMemo(() => {
    if (!activePlan) return [];
    return getTodayItems(planItems ?? [], activePlan, viewDate, planCheckins);
  }, [planItems, activePlan, viewDate, planCheckins]);
  const dailyCustomTodosMemo = useMemo(() => {
    if (!activePlan) return [];
    return getTodayCustomTodos(dailyCustomTodos ?? [], activePlan.id, viewDate);
  }, [dailyCustomTodos, activePlan, viewDate]);
  // planToggles derived from store — no local state needed

  // ── Modals ──
  const [showWG, setShowWG] = useState(false);
  const [showReasonModal, setShowReasonModal] = useState(false);
  const [incompleteItems, setIncompleteItems] = useState<ReturnType<typeof getIncompleteItems>>([]);
  const [selectedReason, setSelectedReason] = useState<string>('');
  const [reasonNote, setReasonNote] = useState('');
  const [wgi, setWgi] = useState(String(waterGoal));

  // ── Derived data ──
  const viewDateFoods = useMemo(() => getFoodLogByDate((foodLog ?? []).filter(f => !f.deleted && f.name), viewDate), [foodLog, viewDate]);
  const totalCal = useMemo(() => viewDateFoods.reduce((a, f) => a + f.calories, 0), [viewDateFoods]);
  const recentFoods = useMemo(() => getRecentFoods((foodLog ?? []).filter(f => !f.deleted), 3), [foodLog]);
  const totalCompleted = useMemo(
    () => (checkinHistory ?? []).filter((c: CheckinEntry) => c.done && !c.deleted).length,
    [checkinHistory],
  );
  const viewDateStats = useMemo(
    () => getStatsForDate(checkinHistory ?? [], viewDate),
    [checkinHistory, viewDate],
  );
  const activeHabits = useMemo(
    () => (habits ?? []).filter(h => !h.deleted && h.status === 'inProgress'),
    [habits],
  );

  // ── Status derivation ──
  const status: CheckinStatus = todayRecord
    ? (todayRecord.done ? 'done' : 'editing')
    : 'draft';

  // Whether fields are locked (read-only from done status)
  const isLocked = status === 'done';
  // Whether in read-only mode (past dates or locked)
  const isReadOnly = !isToday || isLocked;

  // ═══════════════════════════════════════════════════════════════
  // Section 3: Gesture Handling & Effects
  // ═══════════════════════════════════════════════════════════════

  // ── Swipe gesture (instant page switch) — handled by useDateNavigation ──
  const noteRef = useRef(note);
  noteRef.current = note;
  const weightRef = useRef(weight);
  weightRef.current = weight;
  const localDoneRef = useRef(localDone);
  localDoneRef.current = localDone;

  // ── Re-sync local state when todayRecord changes ──
  useEffect(() => {
    if (!todayRecord) {
      // No record for this date — reset local state
      setLocalDone(null);
      setNote('');
      setWeight('');
      return;
    }
    const p = parseCheckinNote(todayRecord.note ?? '');
    setLocalDone(todayRecord.done ?? null);
    setNote(p.userNote);
    setWeight(todayRecord.weight != null ? String(todayRecord.weight) : '');
  }, [todayRecord?.date, todayRecord?.updatedAt]);

  // ── Build JSON note ──
  const buildNote = useCallback(() => {
    const s = useAppStore.getState();
    const noteData: Record<string, unknown> = {};
    if (note) noteData.note = note;
    if (s.waterMl > 0) noteData.water = s.waterMl;
    const checkedHabits = (s.habits ?? [])
      .filter(h => !h.deleted && h.status === 'inProgress' && h.checkedDates?.includes(viewDate))
      .map(h => h.name);
    if (checkedHabits.length) noteData.habits = checkedHabits;
    // 每日自定义待办 — read directly from store to avoid stale closure
    const currentPlan = getActivePlan(s.plans ?? []);
    const freshCustomTodos = currentPlan
      ? getTodayCustomTodos(s.dailyCustomTodos ?? [], currentPlan.id, viewDate)
      : [];
    const doneCustomTodos = freshCustomTodos
      .filter(t => t.done)
      .map(t => t.name);
    if (doneCustomTodos.length) noteData.customs = doneCustomTodos;
    // 计划事项 — read directly from store to avoid stale closure
    const freshPlanCheckins = (s.planItemCheckins ?? []).filter(c => !c.deleted);
    const freshTodayPlanItems = currentPlan
      ? getTodayItems(s.planItems ?? [], currentPlan, viewDate, freshPlanCheckins)
      : [];
    const donePlanItems = freshTodayPlanItems
      .filter(item => freshPlanCheckins.some(c => c.planItemId === item.id && c.date === viewDate && c.done))
      .map(item => item.name);
    if (donePlanItems.length) noteData.planItems = donePlanItems;
    if (totalCal > 0) noteData.food = totalCal;
    return JSON.stringify(noteData);
  }, [note, totalCal, viewDate]);

  // ── Real-time save ──
  // ═══════════════════════════════════════════════════════════════
  // Section 4: Event Handlers & Callbacks
  // ═══════════════════════════════════════════════════════════════

  const saveField = useCallback((doneOverride?: boolean) => {
    const done = doneOverride ?? localDoneRef.current ?? false;
    const weightNum = weightRef.current ? parseWeight(weightRef.current) : undefined;
    useAppStore.getState().submitCheckin(done, buildNote(), undefined, weightNum);
  }, [buildNote]);

  // ── Field change handlers ──
  const toggleHabit = useCallback((id: string) => {
    if (isReadOnly) return;
    checkinHabit(id, viewDate);
    setTimeout(() => saveField(), 0);
  }, [isReadOnly, checkinHabit, viewDate, saveField]);

  const addWaterCb = useCallback((ml: number) => {
    if (!isToday) return;
    addWater(ml);
    // 无论打卡状态如何，都更新饮水数据
    setTimeout(() => {
      const s = useAppStore.getState();
      const weightNum = weightRef.current ? parseWeight(weightRef.current) : undefined;
      s.submitCheckin(localDoneRef.current ?? false, buildNote(), undefined, weightNum);
    }, 0);
  }, [addWater, buildNote, isToday]);

  const handleFoodChanged = useCallback(() => {
    setTimeout(() => {
      const s = useAppStore.getState();
      const weightNum = weightRef.current ? parseWeight(weightRef.current) : undefined;
      s.submitCheckin(localDoneRef.current ?? false, buildNote(), undefined, weightNum);
    }, 0);
  }, [buildNote]);

  const saveWeight = useCallback((val: string) => {
    setWeight(val);
    const parsed = val ? parseFloat(val) : undefined;
    const w = parsed !== undefined && !isNaN(parsed) ? parsed : undefined;
    // 无论打卡状态如何，都更新体重数据
    useAppStore.getState().submitCheckin(localDoneRef.current ?? false, buildNote(), undefined, w);
  }, [buildNote]);

  const saveNote = useCallback((val: string) => {
    setNote(val);
    // Save on blur, not on every keystroke
  }, []);

  const handleNoteBlur = useCallback(() => {
    saveField();
  }, [saveField]);

  // ── Status change handlers ──
  const handleSetDone = useCallback(() => {
    const s = useAppStore.getState();
    const items = getIncompleteItems({
      habits: (s.habits ?? []).filter(h => !h.deleted && h.status === 'inProgress'),
      planItems: todayPlanItems,
      planItemCheckins: planCheckins,
      today: viewDate,
    });
    if (items.length > 0) {
      setIncompleteItems(items);
      setSelectedReason('');
      setReasonNote('');
      setShowReasonModal(true);
      return;
    }
    setLocalDone(true);
    submitCheckin(true, buildNote(), undefined, parseWeight(weight));
  }, [submitCheckin, buildNote, weight, todayPlanItems, planCheckins, viewDate]);

  const handleEdit = useCallback(() => {
    setLocalDone(false);
    submitCheckin(false, buildNote(), undefined, parseWeight(weight));
  }, [submitCheckin, buildNote, weight]);

  const confirmDoneWithReason = useCallback(() => {
    if (!selectedReason || !reasonNote.trim()) return;
    setShowReasonModal(false);
    setLocalDone(true);
    const noteStr = buildNote();
    const noteData: Record<string, unknown> = JSON.parse(noteStr) as Record<string, unknown>;
    noteData.incompleteReason = selectedReason;
    noteData.incompleteNote = reasonNote.trim();
    submitCheckin(true, JSON.stringify(noteData), undefined, parseWeight(weight));
  }, [buildNote, selectedReason, reasonNote, submitCheckin, weight]);

  const togglePlanItem = useCallback((itemId: string) => {
    if (isReadOnly) return;
    const current = planCheckins.some(c => c.planItemId === itemId && c.date === viewDate && c.done);
    if (current) {
      uncheckinPlanItem(itemId);
    } else {
      checkinPlanItem(itemId);
    }
    setTimeout(() => saveField(), 0);
  }, [isReadOnly, planCheckins, viewDate, uncheckinPlanItem, checkinPlanItem, saveField]);

  const toggleCustomTodo = useCallback((id: string) => {
    if (isReadOnly) return;
    toggleDailyCustomTodo(id);
    setTimeout(() => saveField(), 0);
  }, [isReadOnly, toggleDailyCustomTodo, saveField]);

  // ── Extracted inline arrow functions ──
  const openStatsModal = useCallback(() => setShowStatsModal(true), []);
  const closeStatsModal = useCallback(() => setShowStatsModal(false), []);
  const closeWaterGoalModal = useCallback(() => setShowWG(false), []);
  const closeReasonModal = useCallback(() => setShowReasonModal(false), []);
  const goToGrace = useCallback(() => nav.navigate('Grace'), [nav]);
  const goToPlan = useCallback(() => navigateToTab('Plan'), [navigateToTab]);
  const dismissDelayedReminder = useCallback(() => setShowDelayedReminder(false), []);
  const toggleWeightUnit = useCallback(() => setWeightUnit(weightUnit === 'kg' ? 'lb' : 'kg'), [weightUnit, setWeightUnit]);
  const openWaterGoal = useCallback(() => { setWgi(String(waterGoal)); setShowWG(true); }, [waterGoal]);
  const saveWaterGoal = useCallback(() => {
    setWaterGoal(Math.max(500, Math.min(3000, +wgi || 2000)));
    setShowWG(false);
  }, [wgi, setWaterGoal]);
  const handleSaveWeight = useCallback(() => saveWeight(weight), [saveWeight, weight]);

  // ── Auto-sync plan items and health data on mount ──
  useEffect(() => {
    checkAutoStatus();
    autoSyncPlanItems();
  }, [checkAutoStatus, autoSyncPlanItems]);

  useEffect(() => {
    if (!healthSyncEnabled) return;
    import('../../health/HealthService').then(({ performHealthSync }) => {
      return performHealthSync(useAppStore.getState());
    }).catch((e) => log.error(e));
  }, [healthSyncEnabled]);

  // ── Banner gradient ──
  const bannerGrad: [string, string] = status === 'done'
    ? ['#7117EA', '#EA6060']
    : status === 'editing'
    ? ['#8446FF', '#18CEFF']
    : ['#8446FF', '#18CEFF'];

  const viewDateLabel = (() => {
    const d = new Date(viewDate + 'T00:00:00');
    return `${d.getMonth() + 1}月${d.getDate()}日打卡`;
  })();
  const bannerStatusText = status === 'done'
    ? (isToday ? T('checkinDoneBanner') : T('checkinDoneHistory'))
    : status === 'editing'
    ? T('checkinModifyNotDone')
    : (isToday ? T('checkinDoneToday') : T('checkinNotDoneBanner'));

  const bannerTimeText = todayRecord?.timestamp
    ? formatTime(new Date(todayRecord.timestamp), language, { hour: '2-digit', minute: '2-digit' })
    : '';

  // ── Grace reminder ──
  const yStr = yesterday();
  const yesterdayRecord = useMemo(() => (checkinHistory ?? []).find((h: CheckinEntry) => !h.deleted && h.date === yStr), [checkinHistory, yStr]);
  const dayBeforeYesterdayStr = useMemo(() => { const d = new Date(); d.setDate(d.getDate() - 2); return dateStr(d); }, []);
  const dayBeforeYesterdayRecord = useMemo(() => (checkinHistory ?? []).find((h: CheckinEntry) => !h.deleted && h.date === dayBeforeYesterdayStr), [checkinHistory, dayBeforeYesterdayStr]);
  const showGrace = isToday && yesterdayRecord?.done !== true && dayBeforeYesterdayRecord?.done === true;
  const currentMonth = dateStr().slice(0, 7);
  const graceQuota = userProfile?.graceMonthlyQuota ?? 2;
  const graceAvailable = isGraceAvailable(graceHistory ?? [], graceQuota, currentMonth, yStr);

  // ── Delayed plan reminder ──
  const [showDelayedReminder, setShowDelayedReminder] = useState(true);
  const delayedPlan = useMemo(() => {
    return (plans ?? []).find(p => !p.deleted && isPlanDelayed(p, dateStr()));
  }, [plans]);
  const showDelayed = isToday && delayedPlan && showDelayedReminder;

  // ── No record state ──
  const hasRecord = !!todayRecord;

  // ═══════════════════════════════════════════════════════════════
  // Section 5: Render
  // ═══════════════════════════════════════════════════════════════

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={styles.flex1}
    >
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: TH.bg }}>
      <StatusBar barStyle={TH === THEMES.light ? 'dark-content' : 'light-content'} />
      <SimpleHeader routeName="Home" />
        <View style={styles.flex1}
          onTouchStart={onTouchStart}
          onTouchEnd={onTouchEnd}
        >
          <ScrollView
            contentContainerStyle={{ paddingBottom: 32 }}
            showsVerticalScrollIndicator={false}
          >
            <View style={{ padding: 16, paddingBottom: 0 }}>

              {/* ── Date Bar (hidden on today) ── */}
              <DateBar viewDate={viewDate} onNavigate={goToDate} />

              {/* ── No record state ── */}
              {!hasRecord && !isToday ? (
                <View style={{
                  backgroundColor: TH.card, borderRadius: 16, padding: 40, marginBottom: 12,
                  borderWidth: 1, borderColor: TH.border, alignItems: 'center',
                }}>
                  <Calendar size={40} color={TH.sub} style={{ marginBottom: 12 }} />
                  <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('noCheckinRecord')}</Text>
                </View>
              ) : (
                <>
              {/* ── Banner: stats + status ── */}
              <Banner
                status={status}
                bannerGrad={bannerGrad}
                bannerStatusText={bannerStatusText}
                bannerTimeText={bannerTimeText}
                isToday={isToday}
                totalCompleted={totalCompleted}
                viewDateStats={viewDateStats}
                streak={streak}
                showGrace={showGrace}
                graceAvailable={graceAvailable}
                onStatsPress={openStatsModal}
              />

              {/* ── Grace reminder ── */}
              {showGrace && <GraceReminder onPress={goToGrace} />}

              {/* ── Delayed plan reminder ── */}
              {showDelayed && delayedPlan && <DelayedReminder plan={delayedPlan} onGoToPlan={goToPlan} onDismiss={dismissDelayedReminder} />}

              {/* ── Check-in form / details ── */}
              <View style={[styles.cardWithBorder, { backgroundColor: TH.card, borderColor: TH.border }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 16 }}>
                  <ClipboardList size={16} color={P} />
                  <Text style={{ fontWeight: '700', fontSize: FONT_CARD_TITLE(), color: TH.text }}>
                    {isReadOnly ? (isToday && status === 'done' ? '今日目标已达成，点赞 👍' : viewDateLabel) : (isToday ? T('checkinDoneToday') : viewDateLabel)}
                  </Text>
                </View>

                {/* Plan items & custom todos */}
                <HomePlanSection
                  todayPlanItems={todayPlanItems}
                  dailyCustomTodos={dailyCustomTodosMemo}
                  planCheckins={planCheckins}
                  viewDate={viewDate}
                  isReadOnly={isReadOnly}
                  onTogglePlanItem={togglePlanItem}
                  onToggleCustomTodo={toggleCustomTodo}
                />

                {/* Habits */}
                {activeHabits.length > 0 && (
                  <>
                    <Text style={{ color: TH.sub, fontSize: FONT_LABEL(), marginTop: 16, marginBottom: 8 }}>{T('checkinHabitCheck')}</Text>
                    {activeHabits.map((h) => (
                      <HabitItem
                        key={h.id}
                        habit={h}
                        viewDate={viewDate}
                        TH={TH}
                        P={P}
                        T={T}
                        isReadOnly={isReadOnly}
                        onToggle={toggleHabit}
                      />
                    ))}
                  </>
                )}

              </View>

              {/* ── Weight card ── */}
              <View style={[styles.cardWithBorder, { backgroundColor: TH.card, borderColor: TH.border }]}>
                <View style={styles.flexRowBetween}>
                  <View style={styles.flexRowGap6}>
                    <Scale size={16} color={P} />
                    <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('todayWeight')}</Text>
                  </View>
                  <View style={styles.flexRowGap6}>
                    {isReadOnly ? (
                      <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: P }}>
                        {weight || '—'}
                      </Text>
                    ) : (
                      <TextInput
                        value={weight}
                        onChangeText={setWeight}
                        onBlur={handleSaveWeight}
                        placeholder="—"
                        placeholderTextColor={TH.sub}
                        keyboardType="numeric"
                        style={{
                          width: 70, textAlign: 'center', borderWidth: 1, borderColor: TH.border,
                          borderRadius: 8, paddingVertical: 6, color: TH.text, fontWeight: '700',
                          fontSize: FONT_BODY(), backgroundColor: TH.card,
                        }}
                      />
                    )}
                    <TouchableOpacity
                      onPress={toggleWeightUnit}
                      accessibilityLabel={weightUnit === 'kg' ? '切换为磅' : '切换为千克'}
                      style={{ paddingHorizontal: 8, paddingVertical: 4, borderRadius: 6, backgroundColor: `${P}20` }}
                    >
                      <Text style={{ color: P, fontWeight: '600', fontSize: FONT_SUB() }}>{weightUnit === 'kg' ? 'kg' : 'lb'}</Text>
                    </TouchableOpacity>
                  </View>
                </View>
                {/* Steps */}
                {isToday && healthSyncEnabled && todaySteps != null ? (
                  <View style={[styles.flexRowBetween, styles.marginTop10]}>
                    <View style={styles.flexRowGap6}>
                      <Footprints size={16} color={P} />
                      <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('todaySteps')}</Text>
                    </View>
                    <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: P }}>
                      {todaySteps.toLocaleString()}
                    </Text>
                  </View>
                ) : !isToday ? (
                  <View style={[styles.flexRowBetween, styles.marginTop10]}>
                    <View style={styles.flexRowGap6}>
                      <Footprints size={16} color={P} />
                      <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('todaySteps')}</Text>
                    </View>
                    <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: TH.sub }}>--</Text>
                  </View>
                ) : null}
              </View>

              {/* ── Water card ── */}
              <View style={[styles.cardWithBorder, { backgroundColor: TH.card, borderColor: TH.border }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: 6 }}>
                  <View style={styles.flexRowGap6}>
                    <Droplets size={16} color={P} />
                    <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('water')}</Text>
                  </View>
                  <View style={styles.flexRowGap6}>
                    {isToday ? (
                      <>
                        <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                          <Text style={{ fontWeight: '600', color: P }}>{String(waterMl)}</Text> / {String(waterGoal)} ml
                        </Text>
                        <TouchableOpacity onPress={openWaterGoal} accessibilityLabel="编辑饮水目标">
                          <Pencil size={14} color={TH.sub} />
                        </TouchableOpacity>
                      </>
                    ) : (
                      <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                        <Text style={{ fontWeight: '600', color: P }}>{String(parsed.waterMl)}</Text> ml
                      </Text>
                    )}
                  </View>
                </View>
                {isToday ? (
                  <>
                    <ProgressBar pct={waterGoal > 0 ? waterMl / waterGoal * 100 : 0} color={P} />
                    <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
                      {[200, 250, 350, 500].map(ml => (
                        <TouchableOpacity key={ml} onPress={() => addWaterCb(ml)}
                          accessibilityLabel={`添加${ml}毫升水`}
                          style={{ flex: 1, borderRadius: 10, padding: 10, alignItems: 'center', backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border }}>
                          <Text style={{ color: P, fontWeight: '600', fontSize: FONT_SUB() }}>{ml}ml</Text>
                        </TouchableOpacity>
                      ))}
                    </View>
                  </>
                ) : (
                  <ProgressBar pct={waterGoal > 0 ? parsed.waterMl / waterGoal * 100 : 0} color={P} />
                )}
              </View>

              {/* ── Food section ── */}
              <HomeFoodSection
                foods={viewDateFoods}
                totalCal={totalCal}
                recentFoods={recentFoods}
                isToday={isToday}
                calGoal={calGoal}
                isReadOnly={isReadOnly}
                onDeleteFood={deleteFood}
                onAddFood={addFood}
                onFoodChanged={handleFoodChanged}
                onSetCalGoal={setCalGoal}
              />

              {/* ── Reflection card ── */}
              <View style={[styles.cardWithBorder, { backgroundColor: TH.card, borderColor: TH.border, marginTop: 12 }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                  <Sparkles size={16} color={P} />
                  <Text style={{ fontWeight: '600', color: TH.text, fontSize: FONT_BODY() }}>{T('checkinNote')}</Text>
                </View>
                {isReadOnly ? (
                  <Text style={{ color: TH.text, fontSize: FONT_BODY(), lineHeight: 22 }}>
                    {note || '—'}
                  </Text>
                ) : (
                  <ThemedInput
                    value={note}
                    onChangeText={saveNote}
                    onBlur={handleNoteBlur}
                    placeholder={T('checkinNotePlaceholder')}
                    multiline
                    numberOfLines={3}
                    style={{ minHeight: 80 }}
                  />
                )}
              </View>

              {/* ── Status button (today only) ── */}
              {isToday && (
                isLocked ? (
                  <TouchableOpacity
                    onPress={handleEdit}
                    accessibilityLabel={T('checkinModify')}
                    style={{ backgroundColor: P, borderRadius: 12, padding: 14, alignItems: 'center', marginBottom: 12 }}
                  >
                    <View style={styles.flexRowGap6}>
                      <Pencil size={18} color="#fff" />
                      <Text style={[styles.whiteTextBold, { fontSize: FONT_BUTTON() }]}>{T('checkinModify')}</Text>
                    </View>
                  </TouchableOpacity>
                ) : (
                  <TouchableOpacity onPress={handleSetDone}
                    accessibilityLabel={T('checkinSubmit')}
                    style={{ backgroundColor: TH.accent, borderRadius: 12, padding: 14, alignItems: 'center', marginBottom: 12 }}>
                    <View style={styles.flexRowGap6}>
                      <Check size={18} color="#fff" />
                      <Text style={{ fontWeight: '700', fontSize: FONT_BUTTON(), color: '#fff' }}>
                        {T('checkinSubmit')}
                      </Text>
                    </View>
                  </TouchableOpacity>
                )
              )}

                </>
              )}

            </View>
          </ScrollView>
        </View>

      {/* ── Floating bubble (draggable) ── */}
      <HomeBubble
        visible={!isToday}
        onTap={() => goToDate(dateStr())}
      />

      {/* Water Goal Modal */}
      <Modal visible={showWG} transparent animationType="fade" onRequestClose={closeWaterGoalModal}>
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.65)', justifyContent: 'center', padding: 24 }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, alignItems: 'center' }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), marginBottom: 6, color: TH.text }}>{T('waterGoalSetting')}</Text>
            <Text style={{ fontSize: FONT_BODY(), color: TH.sub, marginBottom: 16 }}>{T('waterGoalHint')}</Text>
            <TextInput
              value={wgi} onChangeText={setWgi} keyboardType="numeric"
              style={{
                width: '100%', fontSize: FONT_STAT_CARD(), fontWeight: '700', textAlign: 'center',
                backgroundColor: TH.card, borderWidth: 2, borderColor: COLORS.BLUE,
                borderRadius: 12, padding: 14, color: TH.text, marginBottom: 20,
              }}
            />
            <View style={{ flexDirection: 'row', gap: 10, width: '100%' }}>
              <TouchableOpacity onPress={closeWaterGoalModal}
                accessibilityLabel={T('cancel')}
                style={{ flex: 1, padding: 12, borderRadius: 12, borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
                <Text style={{ color: TH.sub, fontSize: FONT_BODY() }}>{T('cancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={saveWaterGoal}
                accessibilityLabel={T('save')}
                style={{ flex: 1, padding: 12, borderRadius: 12, backgroundColor: P, alignItems: 'center' }}>
                <Text style={[styles.whiteTextBold, { fontSize: FONT_BUTTON() }]}>{T('save')}</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* Incomplete Reason Modal */}
      <Modal visible={showReasonModal} transparent animationType="fade" onRequestClose={closeReasonModal}>
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.65)' }}>
          <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} style={styles.flex1}>
            <ScrollView contentContainerStyle={{ flexGrow: 1, justifyContent: 'center', padding: 24 }} keyboardShouldPersistTaps="handled">
              <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24 }}>
              <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text, marginBottom: 12 }}>{T('incompleteReasonTitle')}</Text>

              {/* Incomplete items list */}
              <View style={{ marginBottom: 16 }}>
                {incompleteItems.map((item, i) => (
                  <View key={i} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                    <X size={16} color="#C53364" style={{ marginRight: 8 }} />
                    <Text style={{ fontSize: FONT_TITLE(), color: TH.sub }}>{item.name}</Text>
                  </View>
                ))}
              </View>

              {/* Reason options */}
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginBottom: 16 }}>
                {INCOMPLETE_REASONS.map(r => {
                  const labelKey = `incompleteReason${r.code.charAt(0).toUpperCase() + r.code.slice(1)}` as string;
                  const selected = selectedReason === r.code;
                  return (
                    <TouchableOpacity key={r.code} onPress={() => setSelectedReason(r.code)}
                      accessibilityLabel={`${r.icon} ${T(labelKey)}`}
                      style={{
                        paddingHorizontal: 14, paddingVertical: 10, borderRadius: 12,
                        borderWidth: 1.5, borderColor: selected ? P : TH.border,
                        backgroundColor: selected ? `${P}15` : 'transparent',
                      }}>
                      <Text style={{ fontSize: FONT_BODY(), color: selected ? P : TH.text }}>
                        {r.icon} {T(labelKey)}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              {/* Additional note */}
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}><Text style={{ color: '#EF4444' }}>*</Text> {T('incompleteReasonNote')}</Text>
              <TextInput
                value={reasonNote} onChangeText={setReasonNote}
                placeholder={T('incompleteReasonNotePlaceholder')}
                placeholderTextColor={TH.sub}
                multiline
                style={{
                  width: '100%', minHeight: 60, backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border,
                  borderRadius: 12, padding: 12, color: TH.text, fontSize: FONT_BODY(), marginBottom: 20,
                  textAlignVertical: 'top',
                }}
              />

              {/* Buttons */}
              <View style={{ flexDirection: 'row', gap: 10 }}>
                <TouchableOpacity onPress={closeReasonModal}
                  accessibilityLabel={T('incompleteReasonBack')}
                  style={{ flex: 1, padding: 14, borderRadius: 12, borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
                  <Text style={{ color: TH.sub, fontSize: FONT_BUTTON() }}>{T('incompleteReasonBack')}</Text>
                </TouchableOpacity>
                <TouchableOpacity onPress={confirmDoneWithReason} disabled={!selectedReason || !reasonNote.trim()}
                  accessibilityLabel={T('incompleteReasonConfirm')}
                  style={{ flex: 1, padding: 14, borderRadius: 12, backgroundColor: selectedReason && reasonNote.trim() ? P : TH.border, alignItems: 'center' }}>
                  <Text style={[styles.whiteTextBold, { fontSize: FONT_BUTTON() }]}>{T('incompleteReasonConfirm')}</Text>
                </TouchableOpacity>
              </View>
            </View>
            </ScrollView>
          </KeyboardAvoidingView>
        </View>
      </Modal>

      <CheckinStatsModal
        visible={showStatsModal}
        onClose={closeStatsModal}
      />
    </SafeAreaView>
    </KeyboardAvoidingView>
  );
}

const styles = {
  flex1: { flex: 1 },
  flexRow: { flexDirection: 'row' as const, alignItems: 'center' as const },
  flexRowGap6: { flexDirection: 'row' as const, alignItems: 'center' as const, gap: 6 },
  flexRowGap10: { flexDirection: 'row' as const, alignItems: 'center' as const, gap: 10 },
  flexRowBetween: { flexDirection: 'row' as const, alignItems: 'center' as const, justifyContent: 'space-between' as const },
  center: { alignItems: 'center' as const },
  centerFlex1: { alignItems: 'center' as const, flex: 1 },
  padding6: { padding: 6 },
  marginTop4: { marginTop: 4 },
  marginTop10: { marginTop: 10 },
  card: { borderRadius: 16, padding: 16, marginBottom: 12 },
  cardWithBorder: { borderRadius: 16, padding: 16, marginBottom: 12, borderWidth: 1 },
  cardPadded: { borderRadius: 16, padding: 14, marginBottom: 12 },
  pillBadge: { flexDirection: 'row' as const, alignItems: 'center' as const, gap: 8, borderRadius: 20, paddingHorizontal: 16, paddingVertical: 6 },
  separator: { width: 1, height: 40 },
  // Text styles (theme-dependent, use with array merge)
  textBold: { fontWeight: '600' as const },
  textSemiBold: { fontWeight: '700' as const },
  textExtraBold: { fontWeight: '800' as const },
  whiteText: { color: '#fff' },
  whiteTextBold: { color: '#fff', fontWeight: '700' as const },
  whiteTextExtraBold: { color: '#fff', fontWeight: '800' as const },
  whiteSubText: { color: 'rgba(255,255,255,.6)' },
  whiteDimText: { color: 'rgba(255,255,255,.5)' },
  whiteSeparator: { backgroundColor: 'rgba(255,255,255,.2)' },
};

import { COLORS, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BADGE , FONT_STAT_SECTION } from '@egoless-do/core';
import type { CheckinReview } from '@egoless-do/core';
import { useRoute, RouteProp } from '@react-navigation/native';
import { 
  ChevronLeft, TrendingUp, TrendingDown,
  AlertTriangle, CheckCircle, Target,
  BarChart3
} from 'lucide-react-native';
import React from 'react';
import { View, Text, ScrollView, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import { useRootNavigation, type RootStackParamList } from '../../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


type DetailRoute = RouteProp<RootStackParamList, 'ReviewDetail'>;

export default function ReviewDetailScreen() {
  const TH = useTheme();
  const T = useT();
  const { checkinReviews } = useShallowStore(s => ({
    checkinReviews: s.checkinReviews,
  }));
  const nav = useRootNavigation();
  const route = useRoute<DetailRoute>();
  const reviewId = route.params?.reviewId ?? '';

  const review = (checkinReviews ?? []).find((r: CheckinReview) => !r.deleted && r.id === reviewId);

  if (!review) {
    return (
      <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 14 }}>
          <TouchableOpacity onPress={() => nav.goBack()}>
            <ChevronLeft size={24} color={TH.text} />
          </TouchableOpacity>
        </View>
        <Text style={{ textAlign: 'center', color: TH.sub, padding: 40, fontSize: FONT_SUB() }}>
          {T('reviewNoData')}
        </Text>
      </SafeAreaView>
    );
  }

  const periodLabel = review.period === 'week' ? T('reviewWeekTitle') : T('reviewMonthTitle');

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 14 }}>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <ChevronLeft size={24} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE(), marginLeft: 12 }}>
          {periodLabel}
        </Text>
      </View>

      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }} showsVerticalScrollIndicator={false}>
        {/* 日期范围 */}
        <View style={{ marginBottom: 16 }}>
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>
            {review.startDate} - {review.endDate}
          </Text>
        </View>

        {/* 核心指标 */}
        <View style={{ flexDirection: 'row', gap: 8, marginBottom: 16 }}>
          <View style={{
            flex: 1, backgroundColor: TH.card, borderRadius: 14, padding: 16,
            alignItems: 'center', borderWidth: 1, borderColor: TH.border,
          }}>
            <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '700', color: TH.primary }}>
              {review.completionRate}%
            </Text>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, marginTop: 4 }}>
              {T('reviewCompletionRate')}
            </Text>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 2 }}>
              {String(review.doneDays)}/{String(review.totalDays)} {T('days')}
            </Text>
          </View>
          <View style={{
            flex: 1, backgroundColor: TH.card, borderRadius: 14, padding: 16,
            alignItems: 'center', borderWidth: 1, borderColor: TH.border,
          }}>
            <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '700', color: TH.primary }}>
              {String(review.streakDays)}
            </Text>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, marginTop: 4 }}>
              {T('reviewStreakDays')}
            </Text>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 2 }}>
              {T('days')}
            </Text>
          </View>
          <View style={{
            flex: 1, backgroundColor: TH.card, borderRadius: 14, padding: 16,
            alignItems: 'center', borderWidth: 1, borderColor: TH.border,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              {review.comparison.completionRateDiff > 0 ? (
                <TrendingUp size={16} color={COLORS.GREEN} />
              ) : review.comparison.completionRateDiff < 0 ? (
                <TrendingDown size={16} color={COLORS.RED} />
              ) : null}
              <Text style={{ 
                fontSize: FONT_STAT_SECTION(), fontWeight: '700', 
                color: review.comparison.completionRateDiff > 0 ? COLORS.GREEN : 
                       review.comparison.completionRateDiff < 0 ? COLORS.RED : TH.text 
              }}>
                {review.comparison.completionRateDiff > 0 ? '+' : ''}{review.comparison.completionRateDiff}%
              </Text>
            </View>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, marginTop: 4 }}>
              {T('reviewVsPrevious')}
            </Text>
          </View>
        </View>

        {/* 未完成分析 */}
        {review.incompleteReasons.length > 0 && (
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 16,
            borderWidth: 1, borderColor: TH.border, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
              <AlertTriangle size={18} color="#F59E0B" />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('reviewIncompleteAnalysis')}
              </Text>
            </View>
            {review.incompleteReasons.map((r, i) => (
              <View key={i} style={{
                flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
                paddingVertical: 6, borderBottomWidth: i < review.incompleteReasons.length - 1 ? 1 : 0,
                borderBottomColor: TH.border,
              }}>
                <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>
                  {r.icon} {r.code}
                </Text>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.primary }}>
                  {String(r.count)} {T('reviewTimes')} ({String(r.percentage)}%)
                </Text>
              </View>
            ))}
          </View>
        )}

        {/* 习惯养成 */}
        {review.habitProgress.length > 0 && (
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 16,
            borderWidth: 1, borderColor: TH.border, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
              <CheckCircle size={18} color={COLORS.GREEN} />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('reviewHabitProgress')}
              </Text>
            </View>
            {review.habitProgress.map((habit, i) => (
              <View key={habit.id} style={{
                paddingVertical: 8,
                borderBottomWidth: i < review.habitProgress.length - 1 ? 1 : 0,
                borderBottomColor: TH.border,
              }}>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>{habit.name}</Text>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.primary, fontWeight: '600' }}>
                    {habit.progress}%
                  </Text>
                </View>
                <View style={{ height: 6, backgroundColor: TH.border, borderRadius: 3, overflow: 'hidden' }}>
                  <View style={{
                    height: 6,
                    width: `${habit.progress}%`,
                    backgroundColor: habit.progress >= 80 ? COLORS.GREEN : habit.progress >= 60 ? '#F59E0B' : COLORS.RED,
                    borderRadius: 3,
                  }} />
                </View>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: 4 }}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>
                    {String(habit.doneDays)}/{String(habit.targetDays)} {T('days')}
                  </Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>
                    {T('reviewStreak')}: {String(habit.streak)} {T('days')}
                  </Text>
                </View>
              </View>
            ))}
          </View>
        )}

        {/* 计划任务 */}
        {review.planProgress.length > 0 && (
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 16,
            borderWidth: 1, borderColor: TH.border, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
              <Target size={18} color={TH.primary} />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('reviewPlanProgress')}
              </Text>
            </View>
            {review.planProgress.map((plan, i) => (
              <View key={plan.planId} style={{
                paddingVertical: 8,
                borderBottomWidth: i < review.planProgress.length - 1 ? 1 : 0,
                borderBottomColor: TH.border,
              }}>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>{plan.planName}</Text>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.primary, fontWeight: '600' }}>
                    {plan.progress}%
                  </Text>
                </View>
                <View style={{ height: 6, backgroundColor: TH.border, borderRadius: 3, overflow: 'hidden' }}>
                  <View style={{
                    height: 6,
                    width: `${plan.progress}%`,
                    backgroundColor: TH.primary,
                    borderRadius: 3,
                  }} />
                </View>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 4 }}>
                  {String(plan.completedItems)}/{String(plan.totalItems)} {T('reviewTasks')}
                </Text>
              </View>
            ))}
          </View>
        )}

        {/* 健康指标 */}
        {review.metrics && Object.keys(review.metrics).length > 0 && (
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 16,
            borderWidth: 1, borderColor: TH.border, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
              <BarChart3 size={18} color={TH.text} />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('reviewHealthMetrics')}
              </Text>
            </View>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
              {review.metrics.avgWeight !== undefined && (
                <View style={{ width: '48%', backgroundColor: TH.bg, borderRadius: 12, padding: 12, borderWidth: 1, borderColor: TH.border }}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>⚖️ {T('reviewWeight')}</Text>
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginTop: 4 }}>
                    {String(review.metrics.avgWeight)}kg
                  </Text>
                  {review.comparison.weightDiff !== undefined && review.comparison.weightDiff !== 0 && (
                    <Text style={{ fontSize: FONT_SUB(), color: review.comparison.weightDiff > 0 ? COLORS.RED : COLORS.GREEN }}>
                      {review.comparison.weightDiff > 0 ? '+' : ''}{String(review.comparison.weightDiff)}kg
                    </Text>
                  )}
                </View>
              )}
              {review.metrics.avgWater !== undefined && (
                <View style={{ width: '48%', backgroundColor: TH.bg, borderRadius: 12, padding: 12, borderWidth: 1, borderColor: TH.border }}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>💧 {T('reviewWater')}</Text>
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginTop: 4 }}>
                    {String(review.metrics.avgWater)}ml
                  </Text>
                </View>
              )}
              {review.metrics.avgCalories !== undefined && (
                <View style={{ width: '48%', backgroundColor: TH.bg, borderRadius: 12, padding: 12, borderWidth: 1, borderColor: TH.border }}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>🍽️ {T('reviewCalories')}</Text>
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginTop: 4 }}>
                    {String(review.metrics.avgCalories)}kcal
                  </Text>
                </View>
              )}
              {review.metrics.totalExerciseMin !== undefined && (
                <View style={{ width: '48%', backgroundColor: TH.bg, borderRadius: 12, padding: 12, borderWidth: 1, borderColor: TH.border }}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>🏃 {T('reviewExercise')}</Text>
                  <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginTop: 4 }}>
                    {String(review.metrics.totalExerciseMin)}min
                  </Text>
                </View>
              )}
            </View>
          </View>
        )}

        {/* AI分析 */}
        {review.aiSummary && (
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 16,
            borderWidth: 1, borderColor: TH.border, marginBottom: 16,
          }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }}>
              <Text style={{ fontSize: FONT_TITLE() }}>💡</Text>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {T('reviewAIAnalysis')}
              </Text>
            </View>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, lineHeight: 24, marginBottom: 12 }}>
              {review.aiSummary}
            </Text>
            {review.highlights.length > 0 && (
              <View style={{ marginBottom: 12 }}>
                <Text style={{ fontSize: FONT_SUB(), color: COLORS.GREEN, fontWeight: '600', marginBottom: 6 }}>
                  ✨ {T('reviewHighlights')}
                </Text>
                {review.highlights.map((h, i) => (
                  <View key={i} style={{ flexDirection: 'row', alignItems: 'flex-start', marginBottom: 4 }}>
                    <Text style={{ fontSize: FONT_BODY(), color: COLORS.GREEN, marginRight: 6 }}>•</Text>
                    <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }}>{h}</Text>
                  </View>
                ))}
              </View>
            )}
            {review.improvements.length > 0 && (
              <View>
                <Text style={{ fontSize: FONT_SUB(), color: '#F59E0B', fontWeight: '600', marginBottom: 6 }}>
                  💪 {T('reviewImprovements')}
                </Text>
                {review.improvements.map((imp, i) => (
                  <View key={i} style={{ flexDirection: 'row', alignItems: 'flex-start', marginBottom: 4 }}>
                    <Text style={{ fontSize: FONT_BODY(), color: '#F59E0B', marginRight: 6 }}>•</Text>
                    <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }}>{imp}</Text>
                  </View>
                ))}
              </View>
            )}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

import { COLORS, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BADGE, FONT_EMPTY, FONT_BACK } from '@egoless-do/core';
import type { CheckinReview } from '@egoless-do/core';
import { ChevronLeft, TrendingUp, TrendingDown } from 'lucide-react-native';
import React, { useMemo, useState, useCallback } from 'react';
import { View, Text, ScrollView, TouchableOpacity, FlatList } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


export default function ReviewHistoryScreen() {
  const TH = useTheme();
  const T = useT();
  const { checkinReviews } = useShallowStore(s => ({
    checkinReviews: s.checkinReviews,
  }));
  const nav = useRootNavigation();

  const [activeTab, setActiveTab] = useState<'week' | 'month'>('week');

  const reviews = useMemo(() => {
    return (checkinReviews ?? [])
      .filter(r => r.period === activeTab && !r.deleted)
      .sort((a, b) => b.generatedAt - a.generatedAt);
  }, [checkinReviews, activeTab]);

  const grouped = useMemo(() => {
    const map = new Map<string, CheckinReview[]>();
    for (const r of reviews) {
      const year = r.startDate.slice(0, 4);
      const month = r.startDate.slice(5, 7);
      const key = `${year}-${month}`;
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(r);
    }
    return Array.from(map.entries());
  }, [reviews]);

  const formatMonth = useCallback((key: string) => {
    const [y, m] = key.split('-');
    return `${y}年${parseInt(m)}月`;
  }, []);

  const formatWeekRange = useCallback((review: CheckinReview) => {
    const start = review.startDate.slice(5);
    const end = review.endDate.slice(5);
    return `${start} - ${end}`;
  }, []);

  const renderItem = useCallback(({ item: [monthKey, items] }: { item: [string, CheckinReview[]] }) => (
    <View key={monthKey} style={{ marginBottom: 20 }}>
      {/* 月份标题 */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12, marginLeft: 4 }}>
        <View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: TH.primary }} />
        <Text style={{ fontSize: FONT_SUB(), fontWeight: '700', color: TH.text }}>
          {formatMonth(monthKey)}
        </Text>
        <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>
          {items.length} {activeTab === 'week' ? '周' : '月'}
        </Text>
      </View>

      {/* 复盘列表 */}
      {items.map((review) => (
        <TouchableOpacity
          key={review.id}
          onPress={() => nav.navigate('ReviewDetail', { reviewId: review.id })}
          activeOpacity={0.7}
          style={{
            backgroundColor: TH.card, borderRadius: 12, padding: 14,
            marginBottom: 10, marginLeft: 18,
            borderLeftWidth: 3, borderLeftColor: TH.primary,
          }}
        >
          {/* 日期范围 */}
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
              {formatWeekRange(review)}
            </Text>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              {review.comparison.completionRateDiff > 0 ? (
                <TrendingUp size={14} color={COLORS.GREEN} />
              ) : review.comparison.completionRateDiff < 0 ? (
                <TrendingDown size={14} color={COLORS.RED} />
              ) : null}
              <Text style={{
                fontSize: FONT_SUB(),
                color: review.comparison.completionRateDiff > 0 ? COLORS.GREEN :
                       review.comparison.completionRateDiff < 0 ? COLORS.RED : TH.sub,
              }}>
                {review.comparison.completionRateDiff > 0 ? '+' : ''}{review.comparison.completionRateDiff}%
              </Text>
            </View>
          </View>

          {/* 核心指标 */}
          <View style={{ flexDirection: 'row', gap: 12, marginBottom: 8 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('reviewCompletionRate')}:</Text>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.primary }}>
                {review.completionRate}%
              </Text>
            </View>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('reviewStreakDays')}:</Text>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                {String(review.streakDays)}{T('days')}
              </Text>
            </View>
          </View>

          {/* AI总结预览 */}
          {review.aiSummary && (
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub }} numberOfLines={2}>
              {review.aiSummary}
            </Text>
          )}
        </TouchableOpacity>
      ))}
    </View>
  ), [activeTab, formatMonth, formatWeekRange, nav, T, TH.card, TH.primary, TH.sub, TH.text]);

  const keyExtractor = useCallback((item: [string, CheckinReview[]]) => item[0], []);

  const ListEmptyComponent = useMemo(() => (
    <View style={{ alignItems: 'center', marginTop: 60 }}>
      <Text style={{ fontSize: FONT_EMPTY(), color: TH.sub }}>
        {T('reviewNoHistory')}
      </Text>
    </View>
  ), [TH.sub, T]);

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 14 }}>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <ChevronLeft size={24} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE(), marginLeft: 12 }}>
          {T('reviewHistoryTitle')}
        </Text>
      </View>

      {/* Tab切换 */}
      <View style={{ flexDirection: 'row', paddingHorizontal: 16, marginBottom: 16, gap: 8 }}>
        {(['week', 'month'] as const).map(tab => {
          const active = activeTab === tab;
          return (
            <TouchableOpacity
              key={tab}
              onPress={() => setActiveTab(tab)}
              style={{
                flex: 1, paddingVertical: 10, borderRadius: 10,
                backgroundColor: active ? `${TH.primary}18` : 'transparent',
                borderWidth: active ? 1 : 0, borderColor: active ? TH.primary : 'transparent',
              }}
            >
              <Text style={{
                textAlign: 'center', fontSize: FONT_BODY(), fontWeight: active ? '600' : '400',
                color: active ? TH.primary : TH.sub,
              }}>
                {tab === 'week' ? T('reviewWeek') : T('reviewMonth')}
              </Text>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* 内容 */}
      <FlatList
        data={reviews.length === 0 ? [] : grouped}
        renderItem={renderItem}
        keyExtractor={keyExtractor}
        removeClippedSubviews={true}
        ListEmptyComponent={ListEmptyComponent}
        contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 40 }}
        showsVerticalScrollIndicator={false}
      />
    </SafeAreaView>
  );
}

import {
  COLORS,
  detectStreakBreaks, computeLongestStreak, computeCurrentStreak,
  computeBreakInsights, computeHypotheticalStreak, generateEncouragement, getRecoveryData,
  FONT_STAT_SECTION, FONT_SUB, FONT_BODY, FONT_BADGE, FONT_TINY, FONT_SMALL } from '@egoless-do/core';
import { PartyPopper, ArrowRight, Flame, Heart, Clock, Sprout, Shield } from 'lucide-react-native';
import React, { useMemo, useCallback } from 'react';
import { View, Text, ScrollView, Pressable, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT, ScreenHeader, Card } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';

export default function StreakBreakScreen() {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { checkinHistory, graceHistory, userProfile } = useShallowStore(s => ({
    checkinHistory: s.checkinHistory,
    graceHistory: s.graceHistory,
    userProfile: s.userProfile,
  }));
  const nav = useRootNavigation();

  const history = (checkinHistory ?? []).filter(c => !c.deleted);
  const graceHistoryArr = graceHistory ?? [];
  const quota = userProfile?.graceMonthlyQuota ?? 2;

  const breaks = useMemo(() => detectStreakBreaks(history), [history]);
  const doneDates = useMemo(() => history.filter(c => c.done).map(c => c.date), [history]);
  const longestStreak = useMemo(() => computeLongestStreak(doneDates), [doneDates]);
  const currentStreak = useMemo(() => computeCurrentStreak(history), [history]);
  const insight = useMemo(() => computeBreakInsights(breaks, history), [breaks, history]);
  const recovery = useMemo(() => getRecoveryData(history, breaks), [history, breaks]);
  const encouragement = useMemo(
    () => generateEncouragement(breaks, longestStreak, doneDates.length, currentStreak, insight),
    [breaks, longestStreak, doneDates, currentStreak, insight],
  );
  const hypotheticals = useMemo(
    () => breaks.map(b => computeHypotheticalStreak(b, history, graceHistoryArr, quota)),
    [breaks, history, graceHistoryArr, quota],
  );

  const handleCheckin = useCallback(() => {
    // Go back to main tabs and switch to Home tab
    nav.goBack();
  }, [nav]);

  const weekdayLabels = ['一', '二', '三', '四', '五', '六', '日'];
  const monthLabels = insight.monthlyTrend.map(t => {
    const m = parseInt(t.month.split('-')[1]);
    return `${m}月`;
  });


  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <ScrollView contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}>
        <ScreenHeader title={T('streakBreakTitle')} onBack={() => nav.goBack()} />

        {/* Recovery Card */}
        <Card>
          <View style={styles.recoveryCenter}>
            {recovery.state === 'active' && (
              <>
                <Flame size={40} color={P} style={styles.iconMargin} />
                <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: P, marginBottom: 4 }}>
                  {T('streakBreakActiveStreak').replace('{n}', String(currentStreak))}
                </Text>
                {(recovery.daysSinceLastBreak ?? 0) > 0 && (
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>
                    {T('streakBreakDaysSince').replace('{n}', String(recovery.daysSinceLastBreak))}
                  </Text>
                )}
                <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>{T('streakBreakGettingStronger')}</Text>
              </>
            )}
            {recovery.state === 'just_broke' && (
              <>
                <Heart size={40} color={COLORS.ORANGE} style={styles.iconMargin} />
                <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: TH.text, marginBottom: 4 }}>
                  {T('streakBreakRestart')}
                </Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>
                  {T('streakBreakPrevStreak').replace('{n}', String(recovery.previousStreak ?? 0))}，{T('streakBreakCanBeLonger')}
                </Text>
                <Pressable onPress={handleCheckin} style={{
                  paddingVertical: 10, paddingHorizontal: 24, borderRadius: 10,
                  backgroundColor: P,
                }}>
                  <Text style={styles.buttonText}>
                    {T('streakBreakCheckinNow')}
                  </Text>
                </Pressable>
              </>
            )}
            {recovery.state === 'at_risk' && (
              <>
                <Clock size={40} color={COLORS.ORANGE} style={styles.iconMargin} />
                <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: TH.text, marginBottom: 4 }}>
                  {T('streakBreakDontForget')}
                </Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>
                  {T('streakBreakActiveStreak').replace('{n}', String(currentStreak))}，{T('streakBreakGettingStronger')}
                </Text>
                <Pressable onPress={handleCheckin} style={{
                  paddingVertical: 10, paddingHorizontal: 24, borderRadius: 10,
                  backgroundColor: P,
                }}>
                  <Text style={styles.buttonText}>
                    {T('streakBreakCheckinNow')}
                  </Text>
                </Pressable>
              </>
            )}
            {recovery.state === 'long_absence' && (
              <>
                <Sprout size={40} color={COLORS.GREEN} style={styles.iconMargin} />
                <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: TH.text, marginBottom: 4 }}>
                  {T('streakBreakNeverTooLate')}
                </Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>
                  {T('streakBreakDaysSince').replace('{n}', String(recovery.daysSinceLastCheckin ?? 0))}
                </Text>
                <Pressable onPress={handleCheckin} style={{
                  paddingVertical: 10, paddingHorizontal: 24, borderRadius: 10,
                  backgroundColor: P,
                }}>
                  <Text style={styles.buttonText}>
                    {T('streakBreakCheckinNow')}
                  </Text>
                </Pressable>
              </>
            )}
          </View>
        </Card>

        {/* Insight Card — hidden when breaks < 3 */}
        {insight.totalBreaks >= 3 && (
          <Card>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 14 }}>
              {T('streakBreakInsight')}
            </Text>

            {/* Weekday distribution */}
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>{T('streakBreakHighDay')}</Text>
            <MiniBarChart values={insight.weekdayDist} labels={weekdayLabels} color={P} th={TH} />

            {/* Stats row */}
            <View style={styles.statsRow}>
              <View style={styles.alignCenter}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: P }}>{insight.avgStreak}</Text>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub }}>{T('streakBreakAvgStreak')}</Text>
              </View>
              <View style={{ width: 1, backgroundColor: TH.border }} />
              <View style={styles.alignCenter}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: P }}>{insight.avgRecoveryDays}</Text>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub }}>{T('streakBreakAvgRecovery')}</Text>
              </View>
            </View>

            {/* Monthly trend */}
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>{T('streakBreakTrend')}</Text>
            <MiniBarChart values={insight.monthlyTrend.map(t => t.count)} labels={monthLabels} color={P} th={TH} />
          </Card>
        )}

        {/* Stats summary */}
        <View style={{
          backgroundColor: TH.card, borderRadius: 16, borderWidth: 1, borderColor: TH.border,
          padding: 16, marginBottom: 12, flexDirection: 'row', gap: 16,
        }}>
          <View style={styles.flexCenter}>
            <Text style={styles.redBreakCount}>{String(breaks.length)}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 4 }}>{T('streakBreakTotal')}</Text>
          </View>
          <View style={{ width: 1, backgroundColor: TH.border }} />
          <View style={styles.flexCenter}>
            <Text style={styles.greenStat}>{longestStreak}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 4 }}>{T('days')}</Text>
          </View>
        </View>

        {breaks.length === 0 ? (
          <Card>
            <View style={styles.emptyCardCenter}>
              <PartyPopper size={32} color={COLORS.GREEN} style={styles.emptyIconMargin} />
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('streakBreakEmpty')}</Text>
            </View>
          </Card>
        ) : (
          breaks.map((b, index) => {
            const hypothetical = hypotheticals[index];
            return (
              <Card key={`break-${b.breakDate}-${index}`}>
                <View style={styles.breakCardHeader}>
                  <View style={styles.breakCardRow}>
                    <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{b.breakDate}</Text>
                    {hypothetical?.available && (
                      <View style={styles.orangeTag}>
                        <Shield size={12} color={COLORS.ORANGE} />
                        <Text style={styles.orangeTagText}>
                          {T('streakBreakHypothetical').replace('{n}', String(hypothetical.hypotheticalStreak))}
                        </Text>
                      </View>
                    )}
                  </View>
                  <View style={styles.lostBadge}>
                    <Text style={styles.lostBadgeText}>-{b.lostStreak} {T('streakBreakDays')}</Text>
                  </View>
                </View>
              </Card>
            );
          })
        )}

        {/* Encouragement Card */}
        {encouragement.length > 0 && (
          <Card>
            {encouragement.map((msg, i) => (
              <Text key={i} style={{
                fontSize: FONT_BODY(), color: i === 0 ? TH.text : TH.sub,
                fontWeight: i === 0 ? '600' : '400',
                lineHeight: 24,
              }}>
                {msg}
              </Text>
            ))}
          </Card>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

function MiniBarChart({ values, labels, color, th }: {
  values: number[];
  labels: string[];
  color: string;
  th: { sub: string };
}) {
  const max = Math.max(...values, 1);
  const maxHeight = 36;
  return (
    <View style={{ flexDirection: 'row', alignItems: 'flex-end', gap: 4, height: maxHeight + 18 }}>
      {values.map((v, i) => (
        <View key={i} style={styles.chartColumn}>
          <View style={{
            width: '100%',
            height: (v / max) * maxHeight,
            backgroundColor: v === max && v > 0 ? color : `${color}40`,
            borderRadius: 3,
            minHeight: v > 0 ? 2 : 0,
          }} />
          <Text style={{ fontSize: FONT_SMALL(), color: th.sub }}>{labels[i]}</Text>
        </View>
      ))}
    </View>
  );
}

