import type { MantraDef } from '@egoless-do/core';
import { dateStr } from '@egoless-do/core';
import React, { useState, useCallback, useMemo, useRef } from 'react';
import { View, Alert } from 'react-native';

import { useTheme, useT } from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';
import { useAudioCache } from '../shared/hooks/useAudioCache';

import { useMantraTimer } from './hooks/useMantraTimer';
import MantraActivePage from './pages/MantraActivePage';
import MantraReportPage from './pages/MantraReportPage';
import MantraSelectPage from './pages/MantraSelectPage';
import MantraStartPage from './pages/MantraStartPage';
import { useMantraAudio } from './useMantraAudio';

// Lazy-loaded native modules — deferred until active session
let _Haptics: typeof import('expo-haptics') | null = null;
function getHaptics() { return _Haptics ??= require('expo-haptics') as typeof import('expo-haptics'); }

let _KeepAwakeHook: typeof import('expo-keep-awake').useKeepAwake | null = null;
function useLazyKeepAwake() {
  if (!_KeepAwakeHook) _KeepAwakeHook = (require('expo-keep-awake') as typeof import('expo-keep-awake')).useKeepAwake;
  _KeepAwakeHook!();
}

type MantraPage = 'select' | 'start' | 'active' | 'report';

// ── Main Screen — State machine + hooks orchestration ──────────
export default function MantraEngine() {
  const nav = useRootNavigation();
  const TH = useTheme();
  const T = useT();
  const { mantraDefs, getMantraTotalCount, getMantraTodayCount, getMantraStreak, addMantraSession, removeMantraDef, addMantraDef } = useShallowStore(s => ({
    mantraDefs: s.mantraDefs, getMantraTotalCount: s.getMantraTotalCount,
    getMantraTodayCount: s.getMantraTodayCount, getMantraStreak: s.getMantraStreak,
    addMantraSession: s.addMantraSession, removeMantraDef: s.removeMantraDef, addMantraDef: s.addMantraDef,
  }));
  useLazyKeepAwake();
  const { playMantra, stopMantra, isPlaying } = useMantraAudio();
  const { downloadAudio, isCached, downloading, progress: dlProgress } = useAudioCache();

  const [page, setPage] = useState<MantraPage>('select');
  const [selectedMantra, setSelectedMantra] = useState<MantraDef | null>(null);
  const [targetRounds, setTargetRounds] = useState(3);
  const [audioCached, setAudioCached] = useState(false);
  const [audioLoop, setAudioLoop] = useState(false);
  const [showDedication, setShowDedication] = useState(false);
  const [dedicationText, setDedicationText] = useState('');
  const [presetSearch, setPresetSearch] = useState('');
  const startSessionSeq = useRef(0);

  const myMantras = useMemo(() =>
    (mantraDefs ?? []).filter((d: MantraDef) => !d.deleted && !d.preset && d.category !== 'sutra' && !!d.name).sort((a: MantraDef, b: MantraDef) => a.sortOrder - b.sortOrder),
    [mantraDefs]
  );

  // Timer hook — manages count, elapsed, pause logic
  const timer = useMantraTimer({
    targetRounds,
    onEndSession: (data) => { addMantraSession({ ...data, date: dateStr() }); },
    onStopAudio: () => { void stopMantra(); setAudioLoop(false); },
  });

  const formatTime = useCallback((ms: number) => {
    const s = Math.floor(ms / 1000);
    return `${Math.floor(s / 60).toString().padStart(2, '0')}:${(s % 60).toString().padStart(2, '0')}`;
  }, []);

  // ── Page transitions ──────────────────────────────────────────

  /** Start session → go to start page */
  const startSession = useCallback(async (mantra: MantraDef) => {
    const seq = ++startSessionSeq.current;
    setSelectedMantra(mantra);
    try {
      const cached = await isCached(mantra.id);
      if (seq !== startSessionSeq.current) return;
      setAudioCached(cached);
    } catch {
      if (seq !== startSessionSeq.current) return;
      setAudioCached(false);
    }
    setPage('start');
  }, [isCached]);

  /** Begin chanting from start page */
  const beginChanting = useCallback(() => {
    timer.start(selectedMantra!);
    if (selectedMantra && audioLoop) {
      playMantra(selectedMantra.id, selectedMantra.name, { loop: true }).catch(() => {});
    }
    setPage('active');
  }, [selectedMantra, audioLoop, timer, playMantra]);

  /** Handle tap on active page — increment count + haptic */
  const handleTap = useCallback(() => {
    if (timer.isPaused) return;
    const H = getHaptics();
    void H.impactAsync(H.ImpactFeedbackStyle.Light);
    timer.increment();
    // timer.count is pre-increment (stale closure), so count+1 = post-increment value
    if ((timer.count + 1) % timer.BEAD_COUNT === 0 && timer.count > 0) {
      void H.notificationAsync(H.NotificationFeedbackType.Success);
    }
  }, [timer]);

  /** End session → go to report */
  const endSession = useCallback(() => {
    timer.end();
    void stopMantra();
    setAudioLoop(false);
    setPage('report');
  }, [timer, stopMantra]);

  /** Full reset → back to select */
  const resetSession = useCallback(() => {
    timer.reset();
    setAudioLoop(false);
    setShowDedication(false);
    setDedicationText('');
    setPage('select');
  }, [timer]);

  /** Exit active page with short-session protection */
  const handleExitActive = useCallback(() => {
    if (timer.elapsed < 30000) {
      Alert.alert(T('chantingTimeTooShort'), '', [
        { text: T('confirm'), onPress: () => resetSession() },
      ]);
    } else {
      Alert.alert(T('chantingExitConfirmTitle'), T('chantingExitConfirmMsg'), [
        { text: T('chantingContinue'), style: 'cancel' },
        { text: T('chantingEndAndRecord'), onPress: endSession },
      ]);
    }
  }, [timer.elapsed, endSession, resetSession, T]);

  /** Toggle audio loop */
  const toggleAudio = useCallback(() => {
    if (!selectedMantra) return;
    if (isPlaying) {
      stopMantra().catch(() => {});
      setAudioLoop(false);
    } else {
      setAudioLoop(true);
      playMantra(selectedMantra.id, selectedMantra.name, { loop: true }).catch(() => {});
    }
  }, [selectedMantra, isPlaying, playMantra, stopMantra]);

  /** Download audio for start page */
  const handleDownloadAudio = useCallback(async () => {
    if (!selectedMantra?.audioUrl) return;
    try {
      await downloadAudio(selectedMantra.id, selectedMantra.audioUrl);
      setAudioCached(true);
    } catch {
      Alert.alert(T('chantingDownloadFailed'));
    }
  }, [selectedMantra, downloadAudio, T]);

  /** Preview audio for start page */
  const handlePreviewAudio = useCallback(async () => {
    if (isPlaying) {
      await stopMantra();
    } else if (selectedMantra) {
      await playMantra(selectedMantra.id, selectedMantra.name, { loop: audioLoop });
    }
  }, [selectedMantra, isPlaying, audioLoop, playMantra, stopMantra]);

  // ── Page routing ──────────────────────────────────────────────

  return (
    <View style={{ flex: 1, backgroundColor: TH.bg }}>
      {page === 'select' && (
        <>
          <SimpleHeader routeName="Mantra" />
          <MantraSelectPage
            myMantras={myMantras}
            targetRounds={targetRounds}
            setTargetRounds={setTargetRounds}
            presetSearch={presetSearch}
            setPresetSearch={setPresetSearch}
            startSession={startSession}
            removeMantraDef={removeMantraDef}
            addMantraDef={addMantraDef}
            getMantraTotalCount={getMantraTotalCount}
            getMantraTodayCount={getMantraTodayCount}
            getMantraStreak={getMantraStreak}
            nav={nav}
          />
        </>
      )}

      {page === 'start' && selectedMantra && (
        <MantraStartPage
          mantra={selectedMantra}
          targetRounds={targetRounds}
          audioCached={audioCached}
          audioLoop={audioLoop}
          setAudioLoop={setAudioLoop}
          isPlaying={isPlaying}
          downloading={downloading}
          dlProgress={dlProgress}
          onBack={() => { void stopMantra(); setPage('select'); }}
          onBeginChanting={beginChanting}
          onDownloadAudio={handleDownloadAudio}
          onPreviewAudio={handlePreviewAudio}
        />
      )}

      {page === 'active' && (
        <MantraActivePage
          mantraName={selectedMantra?.name ?? ''}
          mantraPronunciation={selectedMantra?.pronunciation}
          count={timer.count}
          elapsed={timer.elapsed}
          targetRounds={targetRounds}
          BEAD_COUNT={timer.BEAD_COUNT}
          isPaused={timer.isPaused}
          isPlaying={isPlaying}
          formatTime={formatTime}
          onTap={handleTap}
          onUndo={timer.decrement}
          onToggleAudio={toggleAudio}
          onTogglePause={timer.togglePause}
          onEndSession={endSession}
          onExit={handleExitActive}
        />
      )}

      {page === 'report' && selectedMantra && (
        <MantraReportPage
          mantraName={selectedMantra.name}
          count={timer.count}
          elapsed={timer.elapsed}
          totalAfter={getMantraTotalCount(selectedMantra.id)}
          streak={getMantraStreak(selectedMantra.id)}
          formatTime={formatTime}
          showDedication={showDedication}
          setShowDedication={setShowDedication}
          dedicationText={dedicationText}
          setDedicationText={setDedicationText}
          onReset={resetSession}
        />
      )}
    </View>
  );
}

import {FONT_TITLE, FONT_BODY, FONT_SUB, FONT_SMALL , scaleFontSize, FONT_STAT_CARD} from '@egoless-do/core';
import { useRoute, RouteProp } from '@react-navigation/native';
import React, { useMemo, useState, useCallback } from 'react';
import { View, Text, TouchableOpacity, FlatList, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import type { RootStackParamList } from '../../navigation/types';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

export default function MantraHistoryScreen() {
  const route = useRoute<RouteProp<RootStackParamList, 'MantraHistory'>>();
  const { mantraId } = route.params ?? {};
  const nav = useRootNavigation();
  const TH = useTheme();
  const _T = useT();
  const { mantraDefs, mantraSessions } = useShallowStore(s => ({ mantraDefs: s.mantraDefs, mantraSessions: s.mantraSessions }));
  const [monthOffset, setMonthOffset] = useState(0);

  // 当前显示的月份
  const displayMonth = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() + monthOffset);
    return d;
  }, [monthOffset]);

  const monthYear = displayMonth.getFullYear();
  const monthIdx = displayMonth.getMonth();

  // 咒语名称映射
  const mantraNames = useMemo(() => {
    const map: Record<string, string> = {};
    for (const d of (mantraDefs ?? []).filter(d => !d.deleted)) {
      map[d.id] = d.name;
    }
    return map;
  }, [mantraDefs]);

  // 当前咒语（单咒语模式）
  const singleMantra = useMemo(() =>
    mantraId ? (mantraDefs ?? []).find(d => d.id === mantraId) : undefined,
    [mantraDefs, mantraId]
  );

  // 过滤后的 sessions
  const sessions = useMemo(() =>
    (mantraSessions ?? [])
      .filter(s => !s.deleted && (mantraId ? s.mantraId === mantraId : true))
      .sort((a, b) => b.startedAt - a.startedAt),
    [mantraSessions, mantraId]
  );

  // ── StatsCard ──
  const stats = useMemo(() => {
    const totalCount = sessions.reduce((sum, s) => sum + s.count, 0);
    const totalSec = sessions.reduce((sum, s) => sum + s.durationSec, 0);
    const avgSec = sessions.length > 0 ? Math.round(totalSec / sessions.length) : 0;

    // 连续天数计算
    const dateSet = new Set<string>();
    sessions.forEach(s => {
      const d = new Date(s.startedAt);
      dateSet.add(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`);
    });
    const sortedDates = [...dateSet].sort().reverse();
    let streak = 0;
    const today = new Date();
    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = `${yesterday.getFullYear()}-${String(yesterday.getMonth() + 1).padStart(2, '0')}-${String(yesterday.getDate()).padStart(2, '0')}`;
    if (sortedDates.includes(todayStr) || sortedDates.includes(yesterdayStr)) {
      streak = 1;
      const checkDate = new Date(sortedDates.includes(todayStr) ? today : yesterday);
      for (let i = 1; i < 365; i++) {
        checkDate.setDate(checkDate.getDate() - 1);
        const ds = `${checkDate.getFullYear()}-${String(checkDate.getMonth() + 1).padStart(2, '0')}-${String(checkDate.getDate()).padStart(2, '0')}`;
        if (dateSet.has(ds)) streak++;
        else break;
      }
    }
    return { totalCount, totalSec, avgSec, streak };
  }, [sessions]);

  // ── 热力图 ──
  const heatmapData = useMemo(() => {
    const daysInMonth = new Date(monthYear, monthIdx + 1, 0).getDate();
    const firstDay = new Date(monthYear, monthIdx, 1).getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;

    // 按月统计持咒量（次数）
    const dayCountMap: Record<string, number> = {};
    sessions.forEach(s => {
      const d = new Date(s.startedAt);
      if (d.getFullYear() === monthYear && d.getMonth() === monthIdx) {
        const ds = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        dayCountMap[ds] = (dayCountMap[ds] || 0) + s.count;
      }
    });

    const maxCount = Math.max(1, ...Object.values(dayCountMap));
    const today = new Date();

    const days: { date: string; count: number; intensity: number; isToday: boolean; isFuture: boolean }[] = [];
    for (let i = 0; i < offset; i++) days.push({ date: '', count: 0, intensity: 0, isToday: false, isFuture: false });
    for (let d = 1; d <= daysInMonth; d++) {
      const ds = `${monthYear}-${String(monthIdx + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const count = dayCountMap[ds] || 0;
      const dt = new Date(monthYear, monthIdx, d);
      days.push({
        date: ds,
        count,
        intensity: count > 0 ? Math.max(0.2, count / maxCount) : 0,
        isToday: dt.toDateString() === today.toDateString(),
        isFuture: dt > today,
      });
    }
    return days;
  }, [sessions, monthYear, monthIdx]);

  // ── 按月分组时间线 ──
  const groupedSessions = useMemo(() => {
    const groups: Record<string, typeof sessions> = {};
    for (const s of sessions) {
      const d = new Date(s.startedAt);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(s);
    }
    return Object.entries(groups).sort(([a], [b]) => b.localeCompare(a));
  }, [sessions]);

  const formatTime = useCallback((sec: number) => {
    if (sec < 60) return `${sec}秒`;
    if (sec < 3600) return `${Math.floor(sec / 60)}分${sec % 60 > 0 ? `${sec % 60}秒` : ''}`;
    return `${Math.floor(sec / 3600)}小时${Math.floor((sec % 3600) / 60)}分`;
  }, []);

  const formatShortTime = useCallback((sec: number) => {
    if (sec < 60) return `${sec}s`;
    if (sec < 3600) return `${Math.floor(sec / 60)}m${sec % 60 > 0 ? `${sec % 60}s` : ''}`;
    return `${Math.floor(sec / 3600)}h${Math.floor((sec % 3600) / 60)}m`;
  }, []);

  const formatDate = useCallback((ts: number) => {
    const d = new Date(ts);
    return `${d.getMonth() + 1}/${d.getDate()}`;
  }, []);

  const weekdayLabels = ['一', '二', '三', '四', '五', '六', '日'];

  const renderItem = useCallback(({ item: group }: { item: [string, typeof sessions] }) => {
    const [monthKey, groupSessions] = group;
    return (
      <View style={styles.groupContainer}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 8 }}>
          {parseInt(monthKey.split('-')[0])}年{parseInt(monthKey.split('-')[1])}月
          <Text style={{ fontSize: FONT_SMALL(), fontWeight: '400', color: TH.sub }}> · {groupSessions.length}次</Text>
        </Text>
        {groupSessions.map(s => (
          <View key={s.id} style={{
            backgroundColor: TH.card, borderRadius: 14, padding: 14, marginBottom: 8,
            borderWidth: 1, borderColor: TH.border,
          }}>
            <View style={styles.sessionCardStatsRow}>
              <View style={styles.sessionCardDateRow}>
                {!mantraId && mantraNames[s.mantraId] && (
                  <View style={styles.mantraBadge}>
                    <Text style={styles.mantraBadgeText}>{mantraNames[s.mantraId]}</Text>
                  </View>
                )}
                <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }}>{formatDate(s.startedAt)}</Text>
              </View>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{formatShortTime(s.durationSec)}</Text>
            </View>
            <View style={styles.sessionStatsContainer}>
              <View>
                <Text style={styles.countNumber}>{s.count.toLocaleString()}</Text>
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>次数</Text>
              </View>
              <View>
                <Text style={styles.roundsNumber}>{s.rounds}</Text>
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>遍</Text>
              </View>
              <View>
                <Text style={styles.targetNumber}>{s.targetRounds}</Text>
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>目标</Text>
              </View>
            </View>
          </View>
        ))}
      </View>
    );
  }, [mantraId, mantraNames, TH.card, TH.border, TH.text, TH.sub, formatDate, formatShortTime]);

  const keyExtractor = useCallback((item: [string, typeof sessions]) => item[0], []);

  const ListHeaderComponent = useMemo(() => (
    <>
      {/* ── StatsCard ── */}
      <View style={{ borderRadius: 16, borderWidth: 1, borderColor: `${TH.primary}30`, padding: 16, marginBottom: 16 }}>
        <View style={styles.statsRow}>
          <View style={styles.statItemCenter}>
            <Text style={styles.totalCountNumber}>
              {stats.totalCount.toLocaleString()}
            </Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计次数</Text>
          </View>
          <View style={styles.statItemCenter}>
            <Text style={styles.totalTimeNumber}>
              {formatTime(stats.totalSec)}
            </Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计时长</Text>
          </View>
          <View style={styles.statItemCenter}>
            <Text style={styles.streakNumber}>
              🔥 {String(stats.streak)}
            </Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>连续</Text>
          </View>
          <View style={styles.statItemCenter}>
            <Text style={styles.averageNumber}>
              {formatShortTime(stats.avgSec)}
            </Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>平均</Text>
          </View>
        </View>
      </View>

      {/* ── 热力图 ── */}
      <View style={{ borderRadius: 16, borderWidth: 1, borderColor: `${TH.primary}20`, padding: 16, marginBottom: 16 }}>
        <View style={styles.heatmapHeaderRow}>
          <TouchableOpacity onPress={() => setMonthOffset(o => o - 1)} style={styles.monthNavButton}>
            <Text style={{ fontSize: FONT_TITLE(), color: TH.sub }}>‹</Text>
          </TouchableOpacity>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
            {monthYear}年{monthIdx + 1}月
          </Text>
          <TouchableOpacity onPress={() => setMonthOffset(o => Math.min(o + 1, 0))} style={styles.monthNavButton}>
            <Text style={{ fontSize: FONT_TITLE(), color: TH.sub }}>›</Text>
          </TouchableOpacity>
        </View>

        {/* 星期标签 */}
        <View style={styles.weekdayRow}>
          {weekdayLabels.map(d => (
            <View key={d} style={styles.weekdayCell}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{d}</Text>
            </View>
          ))}
        </View>

        {/* 日历格 */}
        <View style={styles.heatmapGrid}>
          {heatmapData.map((day, i) => (
            <View key={i} style={styles.heatmapDayCell}>
              {day.date ? (
                <View style={{
                  width: 30, height: 30, borderRadius: 15,
                  backgroundColor: day.count > 0
                    ? `rgba(251, 191, 36, ${day.isFuture ? 0.1 : day.intensity})`
                    : day.isToday ? `${TH.primary}20` : 'transparent',
                  borderWidth: day.isToday ? 2 : 0,
                  borderColor: day.isToday ? TH.primary : 'transparent',
                  alignItems: 'center', justifyContent: 'center',
                  opacity: day.isFuture ? 0.3 : 1,
                }}>
                  <Text style={{ fontSize: FONT_SMALL(), color: day.isFuture ? `${TH.sub}60` : TH.text, fontWeight: day.isToday ? '700' : '400' }}>
                    {parseInt(day.date.split('-')[2])}
                  </Text>
                </View>
              ) : <View style={styles.emptyCalendarCell} />}
            </View>
          ))}
        </View>
      </View>
    </>
  ), [stats.totalCount, stats.totalSec, stats.avgSec, stats.streak, formatTime, formatShortTime, FONT_BODY(), FONT_SMALL(), TH.primary, TH.text, TH.sub, monthYear, monthIdx, heatmapData, weekdayLabels]);

  const ListEmptyComponent = useMemo(() => (
    <View style={styles.emptyStateContainer}>
      <Text style={styles.emptyStateEmoji}>📿</Text>
      <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>暂无持咒记录</Text>
    </View>
  ), [FONT_BODY(), TH.sub]);

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* 顶部 */}
      <View style={styles.topBarRow}>
        <TouchableOpacity onPress={() => nav.goBack()} style={styles.backButton}>
          <Text style={{ fontSize: FONT_STAT_CARD(), color: TH.text }}>←</Text>
        </TouchableOpacity>
        <View style={styles.titleContainer}>
          <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: TH.text }}>
            {singleMantra?.name ?? '持咒记录'}
          </Text>
          {!singleMantra && <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>全部咒语</Text>}
        </View>
        <View style={styles.headerStatsContainer}>
          <Text style={styles.totalCountNumber}>
            {stats.totalCount.toLocaleString()}
          </Text>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计</Text>
        </View>
      </View>

      <FlatList
        data={sessions.length === 0 ? [] : groupedSessions}
        renderItem={renderItem}
        keyExtractor={keyExtractor}
        removeClippedSubviews={true}
        ListHeaderComponent={ListHeaderComponent}
        ListEmptyComponent={ListEmptyComponent}
        contentContainerStyle={styles.contentContainer}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  groupContainer: {
    marginBottom: 16,
  },
  sessionCardStatsRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 6,
  },
  sessionCardDateRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  mantraBadge: {
    paddingHorizontal: 8,
    paddingVertical: 3,
    borderRadius: 6,
    backgroundColor: '#FBBF2420',
  },
  mantraBadgeText: {
    fontSize: FONT_BODY(),
    fontWeight: '700',
    color: '#D97706',
  },
  sessionStatsContainer: {
    flexDirection: 'row',
    gap: 20,
  },
  countNumber: {
    fontSize: FONT_TITLE(),
    fontWeight: '800',
    color: '#FBBF24',
  },
  roundsNumber: {
    fontSize: FONT_TITLE(),
    fontWeight: '800',
    color: '#10B981',
  },
  targetNumber: {
    fontSize: FONT_TITLE(),
    fontWeight: '800',
    color: '#F59E0B',
  },
  statsRow: {
    flexDirection: 'row',
    justifyContent: 'space-around',
  },
  statItemCenter: {
    alignItems: 'center',
  },
  totalCountNumber: {
    fontSize: FONT_STAT_CARD(),
    fontWeight: '800',
    color: '#FBBF24',
  },
  totalTimeNumber: {
    fontSize: FONT_STAT_CARD(),
    fontWeight: '800',
    color: '#10B981',
  },
  streakNumber: {
    fontSize: FONT_STAT_CARD(),
    fontWeight: '800',
    color: '#F59E0B',
  },
  averageNumber: {
    fontSize: FONT_STAT_CARD(),
    fontWeight: '800',
    color: '#6366F1',
  },
  heatmapHeaderRow: {
