              </TouchableOpacity>
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* ── 勇气行动弹窗 ── */}
      <Modal visible={showCourage} transparent animationType="fade" onRequestClose={() => setShowCourage(false)}>
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.85)', justifyContent: 'center', padding: 24 }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24 }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text }}>{T('mindCourageLog')}</Text>
              <TouchableOpacity onPress={() => setShowCourage(false)}><X size={20} color={TH.sub} /></TouchableOpacity>
            </View>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('mindCourageAction')}</Text>
            <TextInput value={courageAction} onChangeText={setCourageAction} placeholder="例如：在会议上主动发言"
              placeholderTextColor={TH.sub} style={{ backgroundColor: TH.card, borderRadius: 12, padding: 12, color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border, marginBottom: 16 }} />
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('mindCourageFearBefore')}: {courageFearBefore}/10</Text>
            <View style={{ flexDirection: 'row', gap: 4, marginBottom: 16 }}>
              {Array.from({ length: 10 }, (_, i) => i + 1).map(n => (
                <TouchableOpacity key={n} onPress={() => setCourageFearBefore(n)} hitSlop={{ top: 6, bottom: 6 }} style={{ flex: 1, height: 32, borderRadius: 6, backgroundColor: n <= courageFearBefore ? '#EF4444' : TH.card, borderWidth: n <= courageFearBefore ? 0 : 1, borderColor: TH.border, alignItems: 'center', justifyContent: 'center' }}>
                  <Text style={{ fontSize: FONT_SMALL(), color: n <= courageFearBefore ? '#fff' : TH.sub }}>{n}</Text>
                </TouchableOpacity>
              ))}
            </View>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('mindCourageFeeling')}</Text>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginBottom: 16 }}>
              {FEELING_TAGS.map(tag => {
                const selected = courageFeelingTags.includes(tag);
                return (
                  <TouchableOpacity key={tag} onPress={() => setCourageFeelingTags(prev => selected ? prev.filter(t => t !== tag) : [...prev, tag])}
                    style={{ paddingHorizontal: 12, paddingVertical: 6, borderRadius: 16, backgroundColor: selected ? '#10B981' : TH.card, borderWidth: selected ? 0 : 1, borderColor: TH.border }}>
                    <Text style={{ color: selected ? '#fff' : TH.sub, fontSize: FONT_SUB() }}>{T(FEELING_LABELS[tag] ?? tag)}</Text>
                  </TouchableOpacity>
                );
              })}
            </View>
            <TouchableOpacity onPress={handleSaveCourage} disabled={!courageAction.trim()}
              style={{ backgroundColor: '#10B981', borderRadius: 12, padding: 14, alignItems: 'center', opacity: courageAction.trim() ? 1 : 0.5 }}>
              <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BODY() }}>{T('mindCourageRecord')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

import { FONT_BODY, FONT_SUB } from '@egoless-do/core';
import type { MusicTrack } from '@egoless-do/core';
import { Music, Play, Pause, Repeat, Repeat1, Shuffle } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useTheme } from '../../../components/UI';
import type { PlayMode } from '../useMusicStore';
import { useMusicStore } from '../useMusicStore';

import WaveformBar from './WaveformBar';

const MODE_ICONS: Record<string, typeof Repeat> = {
  sequential: Repeat,
  'repeat-all': Repeat,
  'repeat-one': Repeat1,
  shuffle: Shuffle,
};

interface Props {
  currentTrack: MusicTrack | null;
  isPlaying: boolean;
  loop: boolean;
  onTogglePlay: () => void;
  onToggleLoop: () => void;
  onPressTrackName?: () => void;
  primaryColor: string;
}

export default function MusicMiniBar({ currentTrack, isPlaying, loop, onTogglePlay, onToggleLoop, onPressTrackName, primaryColor }: Props) {
  const TH = useTheme();
  const playMode = useMusicStore(s => s.playMode);
  const currentTime = useMusicStore(s => s.currentTime);
  const duration = useMusicStore(s => s.duration);

  if (!currentTrack) return null;

  const progress = duration > 0 ? currentTime / duration : 0;

  const ModeIcon = MODE_ICONS[playMode] ?? Repeat;
  const isActive = playMode !== 'sequential';

  return (
    <View style={{ paddingHorizontal: 20, paddingVertical: 8, gap: 8 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
        <Music size={14} color={primaryColor} />
        <TouchableOpacity onPress={onPressTrackName} style={{ flex: 1 }}>
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub }} numberOfLines={1}>
            {currentTrack.name}
          </Text>
        </TouchableOpacity>
        <TouchableOpacity onPress={onTogglePlay} style={{ padding: 4 }}>
          {isPlaying ? <Pause size={16} color={TH.text} /> : <Play size={16} color={TH.text} />}
        </TouchableOpacity>
        <TouchableOpacity onPress={onToggleLoop} style={{ padding: 4 }}>
          <ModeIcon size={14} color={isActive ? primaryColor : TH.border} />
        </TouchableOpacity>
      </View>
      {/* Progress bar */}
      {duration > 0 && (
        <View style={{ height: 2, backgroundColor: TH.border, borderRadius: 1 }}>
          <View style={{ height: 2, width: `${progress * 100}%`, backgroundColor: primaryColor, borderRadius: 1 }} />
        </View>
      )}
    </View>
  );
}

import { FONT_BODY, FONT_SUB } from '@egoless-do/core';
import { Repeat, Repeat1, Shuffle, SkipBack, SkipForward, Volume2, VolumeX, Clock } from 'lucide-react-native';
import React, { useState, useCallback } from 'react';
import { View, Text, TouchableOpacity, Modal } from 'react-native';

import AnimatedMusicIcon from '../../../components/AnimatedMusicIcon';
import { useTheme, useT } from '../../../components/UI';
import { audioPlayerRef } from '../services/audioPlayerRef';
import { useMusicStore } from '../useMusicStore';
import type { PlayMode } from '../useMusicStore';

import WaveformBar from './WaveformBar';

const SLEEP_PRESETS = [15, 30, 45, 60, 90];

interface Props {
  primaryColor: string;
  category?: string;
}

export default function PlayerBar({ primaryColor, category }: Props) {
  const TH = useTheme();
  const T = useT();
  const currentTrack = useMusicStore(s => s.currentTrack);
  const isPlaying = useMusicStore(s => s.isPlaying);
  const playMode = useMusicStore(s => s.playMode);
  const currentTime = useMusicStore(s => s.currentTime);
  const duration = useMusicStore(s => s.duration);
  const volume = useMusicStore(s => s.volume);
  const sleepTimerMinutes = useMusicStore(s => s.sleepTimerMinutes);
  const sleepTimerRemaining = useMusicStore(s => s.sleepTimerRemaining);
  const error = useMusicStore(s => s.error);

  const pause = useMusicStore(s => s.pause);
  const resume = useMusicStore(s => s.resume);
  const play = useMusicStore(s => s.play);
  const setPlayMode = useMusicStore(s => s.setPlayMode);
  const playNext = useMusicStore(s => s.playNext);
  const playPrevious = useMusicStore(s => s.playPrevious);
  const setVolume = useMusicStore(s => s.setVolume);
  const setSleepTimer = useMusicStore(s => s.setSleepTimer);
  const setError = useMusicStore(s => s.setError);

  const [showSleepModal, setShowSleepModal] = useState(false);

  const progress = duration > 0 ? currentTime / duration : 0;
  const currentTimeStr = formatTime(currentTime);
  const durationStr = formatTime(duration);

  const PLAY_MODES: { mode: PlayMode; icon: typeof Repeat; labelKey: string }[] = [
    { mode: 'sequential', icon: Repeat, labelKey: 'musicPlayModeSequential' },
    { mode: 'repeat-all', icon: Repeat, labelKey: 'musicPlayModeRepeatAll' },
    { mode: 'repeat-one', icon: Repeat1, labelKey: 'musicPlayModeRepeatOne' },
    { mode: 'shuffle', icon: Shuffle, labelKey: 'musicPlayModeShuffle' },
  ];

  const handleSeek = useCallback((ratio: number) => {
    try { void audioPlayerRef.current?.seekTo(ratio * duration); } catch {}
  }, [duration]);

  const handleTogglePlay = useCallback(() => {
    isPlaying ? pause() : resume();
  }, [isPlaying, pause, resume]);

  const handleCycleMode = useCallback(() => {
    const idx = PLAY_MODES.findIndex(m => m.mode === playMode);
    setPlayMode(PLAY_MODES[(idx + 1) % PLAY_MODES.length].mode);
  }, [playMode, setPlayMode]);

  const handleToggleVolume = useCallback(() => {
    setVolume(volume > 0 ? 0 : 0.3);
  }, [volume, setVolume]);

  const handleSleepSelect = useCallback((minutes: number | null) => {
    setSleepTimer(minutes);
    setShowSleepModal(false);
  }, [setSleepTimer]);

  const formatSleepTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${String(s).padStart(2, '0')}`;
  };

  if (!currentTrack) return null;

  const modeDef = PLAY_MODES.find(m => m.mode === playMode) ?? PLAY_MODES[0];
  const ModeIcon = modeDef.icon;
  const modeLabel = T(modeDef.labelKey);

  return (
    <>
      <View style={{ position: 'absolute', bottom: 0, left: 0, right: 0, backgroundColor: TH.cardSolid, borderTopWidth: 1, borderTopColor: TH.border, paddingHorizontal: 16, paddingTop: 10, paddingBottom: 28 }}>
        {/* Error banner */}
        {error && (
          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', backgroundColor: 'rgba(239,68,68,.2)', borderRadius: 8, padding: 8, marginBottom: 8 }}>
            <Text style={{ color: '#EF4444', fontSize: FONT_SUB(), flex: 1 }}>{T('musicPlayFailed')}</Text>
            <TouchableOpacity onPress={() => { setError(null); play(currentTrack); }}>
              <Text style={{ color: primaryColor, fontSize: FONT_SUB(), fontWeight: '600' }}>{T('musicRetry')}</Text>
            </TouchableOpacity>
          </View>
        )}

        {/* Track info + controls */}
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 8 }}>
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600' }} numberOfLines={1}>
              {currentTrack.name}
            </Text>
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 2 }}>
              {currentTimeStr} / {durationStr}
            </Text>
          </View>

          {/* Sleep timer */}
          {sleepTimerMinutes && (
            <TouchableOpacity onPress={() => setShowSleepModal(true)} style={{ padding: 6 }}>
              <Text style={{ color: primaryColor, fontSize: FONT_SUB(), fontWeight: '600' }}>
                {formatSleepTime(sleepTimerRemaining)}
              </Text>
            </TouchableOpacity>
          )}
          <TouchableOpacity onPress={() => setShowSleepModal(true)} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} style={{ padding: 8 }}>
            <Clock size={18} color={sleepTimerMinutes ? primaryColor : TH.sub} />
          </TouchableOpacity>

          {/* Volume */}
          <TouchableOpacity onPress={handleToggleVolume} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} style={{ padding: 8 }}>
            {volume > 0 ? <Volume2 size={18} color={TH.sub} /> : <VolumeX size={18} color={TH.sub} />}
          </TouchableOpacity>

          {/* Play mode */}
          <TouchableOpacity onPress={handleCycleMode} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} style={{ padding: 8 }}>
            <ModeIcon size={18} color={playMode !== 'sequential' ? primaryColor : TH.sub} />
          </TouchableOpacity>
        </View>

        {/* Playback controls row */}
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 16, marginBottom: 8 }}>
          <TouchableOpacity onPress={playPrevious} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} style={{ padding: 8 }}>
            <SkipBack size={22} color={TH.text} />
          </TouchableOpacity>

          <TouchableOpacity onPress={handleTogglePlay} style={{ padding: 8 }}>
            <AnimatedMusicIcon isPlaying={isPlaying} color={TH.text} size={28} />
          </TouchableOpacity>

          <TouchableOpacity onPress={playNext} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }} style={{ padding: 8 }}>
            <SkipForward size={22} color={TH.text} />
          </TouchableOpacity>

          <View style={{ flex: 1 }} />

          <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{modeLabel}</Text>
        </View>

        {/* Waveform progress bar */}
        <WaveformBar
          trackId={currentTrack.id}
          progress={progress}
          primaryColor={primaryColor}
          inactiveColor={TH.border}
          barCount={50}
          height={26}
          onPress={handleSeek}
        />
      </View>

      {/* Sleep Timer Modal */}
      <Modal visible={showSleepModal} transparent animationType="fade" onRequestClose={() => setShowSleepModal(false)}>
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.5)', justifyContent: 'center', padding: 24 }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, borderWidth: 1, borderColor: TH.border }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_BODY(), color: TH.text, marginBottom: 16, textAlign: 'center' }}>{T('musicSleepTimer')}</Text>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10, justifyContent: 'center' }}>
              {SLEEP_PRESETS.map(min => (
                <TouchableOpacity key={min} onPress={() => handleSleepSelect(min)}
                  style={{ paddingHorizontal: 20, paddingVertical: 12, borderRadius: 12, backgroundColor: sleepTimerMinutes === min ? primaryColor : TH.card }}>
                  <Text style={{ color: sleepTimerMinutes === min ? '#fff' : TH.text, fontWeight: '600', fontSize: FONT_BODY() }}>{T('musicMinutes').replace('{n}', String(min))}</Text>
                </TouchableOpacity>
              ))}
              {sleepTimerMinutes && (
                <TouchableOpacity onPress={() => handleSleepSelect(null)}
                  style={{ paddingHorizontal: 20, paddingVertical: 12, borderRadius: 12, backgroundColor: 'rgba(239,68,68,.15)', width: '100%', alignItems: 'center' }}>
                  <Text style={{ color: '#EF4444', fontWeight: '600', fontSize: FONT_BODY() }}>{T('musicSleepTimerOff')}</Text>
                </TouchableOpacity>
              )}
            </View>
            <TouchableOpacity onPress={() => setShowSleepModal(false)} style={{ marginTop: 16, padding: 12, alignItems: 'center' }}>
              <Text style={{ color: TH.sub, fontSize: FONT_BODY() }}>{T('cancel')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </>
  );
}

function formatTime(sec: number): string {
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${String(s).padStart(2, '0')}`;
}

import { FONT_TITLE, FONT_BODY, FONT_SUB, MUSIC_CATEGORY_META } from '@egoless-do/core';
import type { MusicTrack } from '@egoless-do/core';
import { useRoute, RouteProp } from '@react-navigation/native';
import { ArrowLeft, Music, Heart } from 'lucide-react-native';
import React, { useEffect, useCallback, useMemo } from 'react';
import { View, Text, FlatList, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import type { RootStackParamList } from '../../../navigation/hooks';
import PlayerBar from '../components/PlayerBar';
import TrackListItem from '../components/TrackListItem';
import { useMusicStore, computeTracksByCategory } from '../useMusicStore';

type Route = RouteProp<RootStackParamList, 'MusicCategory'>;

export default function MusicCategoryScreen() {
  const TH = useTheme();
  const T = useT();
  const nav = useRootNavigation();
  const route = useRoute<Route>();
  const { category } = route.params;
  const P = TH.primary;

  const currentTrack = useMusicStore(s => s.currentTrack);
  const isPlaying = useMusicStore(s => s.isPlaying);
  const play = useMusicStore(s => s.play);
  const pause = useMusicStore(s => s.pause);
  const resume = useMusicStore(s => s.resume);
  const favorites = useMusicStore(s => s.favorites);
  const library = useMusicStore(s => s.library);
  const userTracks = useMusicStore(s => s.userTracks);
  const toggleFavorite = useMusicStore(s => s.toggleFavorite);
  const setQueue = useMusicStore(s => s.setQueue);
  const loadFavorites = useMusicStore(s => s.loadFavorites);
  const loadUserTracks = useMusicStore(s => s.loadUserTracks);

  useEffect(() => {
    void loadFavorites();
    void loadUserTracks();
  }, [loadFavorites, loadUserTracks]);

  const meta = MUSIC_CATEGORY_META.find(m => m.key === category);
  const tracks = useMemo(() => computeTracksByCategory(library, userTracks, favorites, category), [library, userTracks, favorites, category]);

  const handlePlay = useCallback((track: MusicTrack) => {
    if (currentTrack?.id === track.id) {
      isPlaying ? pause() : resume();
    } else {
      // Set queue for the category and play
      const idx = tracks.findIndex(t => t.id === track.id);
      setQueue(tracks, idx >= 0 ? idx : 0);
      play(track);
    }
  }, [currentTrack, isPlaying, play, pause, resume, tracks, setQueue]);

  const renderTrackItem = useCallback(({ item }: { item: MusicTrack }) => (
    <TrackListItem
      track={item}
      isCurrent={currentTrack?.id === item.id}
      isPlaying={currentTrack?.id === item.id && isPlaying}
      isFavorite={favorites.includes(item.id)}
      onPlay={() => handlePlay(item)}
      onToggleFavorite={() => toggleFavorite(item.id)}
      primaryColor={P}
    />
  ), [currentTrack, isPlaying, favorites, handlePlay, toggleFavorite, P]);

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={{ paddingTop: 56, paddingHorizontal: 20, paddingBottom: 12, flexDirection: 'row', alignItems: 'center', gap: 12 }}>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <ArrowLeft size={22} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>
          {meta ? T(meta.nameKey) : category}
        </Text>
      </View>

      {/* Track List */}
      {tracks.length === 0 ? (
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 40, gap: 12 }}>
          {category === 'favorites' ? (
            <Heart size={48} color={TH.border} />
          ) : (
            <Music size={48} color={TH.border} />
          )}
          <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>
            {category === 'favorites' ? T('musicEmptyFavorites') : T('musicNoTracks')}
          </Text>
        </View>
      ) : (
        <FlatList
          data={tracks}
          keyExtractor={item => item.id}
          renderItem={renderTrackItem}
          ItemSeparatorComponent={() => <View style={{ height: 1, backgroundColor: TH.border, marginHorizontal: 16 }} />}
          contentContainerStyle={{ paddingBottom: 100 }}
        />
      )}

      {/* Bottom Player Bar */}
      <PlayerBar primaryColor={P} category={category} />
    </SafeAreaView>
  );
}

import { FONT_TITLE, FONT_BODY, FONT_SUB, MUSIC_CATEGORY_META, TRACK_VISUAL } from '@egoless-do/core';
import { ArrowLeft, Music } from 'lucide-react-native';
