  const loadUserTracks = useMusicStore(s => s.loadUserTracks);
  const loadVolume = useMusicStore(s => s.loadVolume);

  useEffect(() => {
    void loadFavorites();
    void loadUserTracks();
    void loadVolume();
  }, [loadFavorites, loadUserTracks, loadVolume]);

