import { FONT_TITLE, FONT_SUB, FONT_SMALL, ALL_SPORTS, type BodyPlanTask, type ExerciseDef } from '@egoless-do/core';
import { useRoute, RouteProp } from '@react-navigation/native';
import React, { useState, useCallback, useMemo, useRef } from 'react';
import { View, ScrollView, Animated } from 'react-native';

import { useTheme, useT } from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

import BodyDashboard from './body/BodyDashboard';
import BodyFlow from './body/BodyFlow';
import { useBodyFlowState } from './body/hooks/useBodyFlowState';
import { useTodayPlan } from './body/hooks/useTodayPlan';

// ── Page state machine ──
type BodyPage = 'dashboard' | 'flow';

const FADE_DURATION = 350;

export default function BodyScreen() {
  const nav = useRootNavigation();
  const TH = useTheme();
  const T = useT();
  const { bodyTrainingPlans, setBodyFlowState, upsertBodyCheckin } = useShallowStore(s => ({
    bodyTrainingPlans: s.bodyTrainingPlans,
    setBodyFlowState: s.setBodyFlowState,
    upsertBodyCheckin: s.upsertBodyCheckin,
  }));
  const [page, setPage] = useState<BodyPage>('dashboard');
  const { todayPlan, weekday: todayWeekday, todayOverride, todayExercises, activeTrainingPlan } = useTodayPlan();
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const fadeAnim = useRef(new Animated.Value(1)).current;
  const transitioningRef = useRef(false);
  const { flowState } = useBodyFlowState();

  // Animated page transition
  const transitionTo = useCallback((target: BodyPage, extra?: () => void) => {
    if (transitioningRef.current) return;
    transitioningRef.current = true;
    Animated.timing(fadeAnim, {
      toValue: 0,
      duration: FADE_DURATION / 2,
      useNativeDriver: true,
    }).start(() => {
      setPage(target);
      extra?.();
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: FADE_DURATION / 2,
        useNativeDriver: true,
      }).start(() => {
        transitioningRef.current = false;
      });
    });
  }, [fadeAnim]);

  // Find today's training plan task
  const todayTrainingTask = useMemo(() => {
    if (!activePlanId) return null;
    const plan = (bodyTrainingPlans ?? []).find(p => p.id === activePlanId && !p.deleted && p.status === 'active');
    if (!plan) return null;
    const task = plan.tasks.find(t => t.weekday === todayWeekday);
    if (!task) return null;
    return { planId: plan.id, planName: plan.name, task };
  }, [activePlanId, bodyTrainingPlans, todayWeekday]);

  // 检测组合模式
  const isComboMode = !!todayExercises && todayExercises.length > 1;

  const handleGoToSport = useCallback((sportKey: string, exercises?: ExerciseDef[]) => {
    const sport = ALL_SPORTS.find(s => s.key === sportKey || s.keyEn === sportKey);
    const navParams: Record<string, unknown> = {
      key: sportKey,
      icon: sport?.icon ?? '🏃',
      color: sport?.color ?? '#f59e0b',
    };

    // 组合模式：传递全部动作到 SportPage
    if (exercises && exercises.length > 1) {
      navParams.exercises = exercises;
      navParams.comboPlanId = activePlanId ?? undefined;
    } else if (activePlanId) {
      const plan = (bodyTrainingPlans ?? []).find(p => p.id === activePlanId && !p.deleted && p.status === 'active');
      const task = plan?.tasks.find(t => t.weekday === todayWeekday);
      if (task) {
        navParams.planId = activePlanId;
        navParams.planTaskWeekday = task.weekday;
      }
    }

    nav.navigate('Sport' as never, navParams as never);
  }, [nav, activePlanId, todayExercises, todayWeekday, bodyTrainingPlans, isComboMode]);

  const handleGoToBreathing = useCallback(() => {
    nav.navigate('Breathing' as never);
  }, [nav]);

  const startFlowWithPlan = useCallback((planId: string) => {
    setActivePlanId(planId);
    transitionTo('flow');
  }, [transitionTo]);

  return (
    <View style={{ flex: 1, backgroundColor: TH.bg }}>
      <SimpleHeader routeName="Body" />
      <Animated.View style={{ flex: 1, opacity: fadeAnim }}>
        <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }}>
          {page === 'flow' ? (
            <BodyFlow
              TH={TH}
              T={T}
              store={{ upsertBodyCheckin }}
              todayPlan={todayPlan}
              trainingPlanTask={todayTrainingTask}
              todayOverride={todayOverride}
              todayExercises={todayExercises}
              onGoToSport={handleGoToSport}
              onGoToBreathing={handleGoToBreathing}
              onExit={() => { setActivePlanId(null); transitionTo('dashboard'); }}
            />
          ) : (
            <BodyDashboard
              onFlowStart={() => transitionTo('flow')}
              onFlowStartWithPlan={startFlowWithPlan}
              onGoToSport={handleGoToSport}
              onGoToBreathing={handleGoToBreathing}
            />
          )}
        </ScrollView>
      </Animated.View>
    </View>
  );
}

import {FONT_TITLE, FONT_BODY, FONT_SUB, FONT_STAT_CARD, dateStr , FONT_LABEL, FONT_SMALL} from '@egoless-do/core';
import { ChevronLeft, ChevronRight, X } from 'lucide-react-native';
import React, { useMemo, useState, useCallback } from 'react';
import { View, Text, FlatList, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

const GIVE_TYPE_CONFIG: Record<string, { icon: string; color: string; labelKey: string }> = {
  material: { icon: '💰', color: '#F59E0B', labelKey: 'giveMaterial' },
  dharma: { icon: '📖', color: '#3B82F6', labelKey: 'giveDharma' },
  fearless: { icon: '🛡', color: '#10B981', labelKey: 'giveFearless' },
};

const WEEKDAY_KEYS = ['bodyWeekMon', 'bodyWeekTue', 'bodyWeekWed', 'bodyWeekThu', 'bodyWeekFri', 'bodyWeekSat', 'bodyWeekSun'];

export default function GiveHistoryPage() {
  const TH = useTheme();
  const T = useT();
  const nav = useRootNavigation();
  const { giveHistory: giveHistoryRaw } = useShallowStore(s => ({
    giveHistory: s.giveHistory,
  }));
  const [monthOffset, setMonthOffset] = useState(0);

  const now = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() + monthOffset);
    return d;
  }, [monthOffset]);

  const year = now.getFullYear();
  const month = now.getMonth();

  const giveHistory = useMemo(() => {
    return (giveHistoryRaw ?? []).filter(g => !g.deleted).sort((a, b) => b.timestamp - a.timestamp);
  }, [giveHistoryRaw]);

  // Stats
  const stats = useMemo(() => {
    const total = giveHistory.length;
    const monthStart = new Date(year, month, 1);
    const monthEnd = new Date(year, month + 1, 0, 23, 59, 59);
    const monthRecords = giveHistory.filter(g => g.timestamp >= monthStart.getTime() && g.timestamp <= monthEnd.getTime());
    const monthCount = monthRecords.length;

    // Longest consecutive streak
    const dateSet = new Set<string>();
    giveHistory.forEach(g => dateSet.add(dateStr(new Date(g.timestamp))));
    const sortedDates = [...dateSet].sort();
    let longest = 0, current = sortedDates.length > 0 ? 1 : 0;
    for (let i = 1; i < sortedDates.length; i++) {
      const prev = new Date(sortedDates[i - 1]);
      const cur = new Date(sortedDates[i]);
      const diff = (cur.getTime() - prev.getTime()) / 86400000;
      if (diff === 1) { current++; } else { longest = Math.max(longest, current); current = 1; }
    }
    longest = Math.max(longest, current);

    // Type distribution
    const byType = { material: 0, dharma: 0, fearless: 0 };
    giveHistory.forEach(g => { byType[g.type] = (byType[g.type] || 0) + 1; });
    const typePercent = { material: 0, dharma: 0, fearless: 0 };
    if (total > 0) {
      typePercent.material = Math.round((byType.material / total) * 100);
      typePercent.dharma = Math.round((byType.dharma / total) * 100);
      typePercent.fearless = Math.round((byType.fearless / total) * 100);
    }

    return { total, monthCount, longest, byType, typePercent };
  }, [giveHistory, year, month]);

  // Heatmap
  const heatmapDays = useMemo(() => {
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;
    const days: { date: string; hasRecord: boolean; isToday: boolean }[] = [];
    for (let i = 0; i < offset; i++) days.push({ date: '', hasRecord: false, isToday: false });
    const today = dateStr();
    for (let d = 1; d <= daysInMonth; d++) {
      const ds = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const hasRecord = giveHistory.some(g => dateStr(new Date(g.timestamp)) === ds);
      days.push({ date: ds, hasRecord, isToday: ds === today });
    }
    return days;
  }, [giveHistory, year, month]);

  const displayHistory = useMemo(() => giveHistory.slice(0, 50), [giveHistory]);

  const renderTimelineItem = useCallback(({ item }: { item: typeof giveHistory[number] }) => {
    const config = GIVE_TYPE_CONFIG[item.type] || GIVE_TYPE_CONFIG.material;
    const d = new Date(item.timestamp);
    return (
      <View style={{ borderLeftWidth: 3, borderLeftColor: config.color, paddingLeft: 12, paddingVertical: 8, marginBottom: 8 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 2 }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{d.getMonth() + 1}/{d.getDate()}</Text>
          <Text style={{ fontSize: FONT_SUB() }}>{config.icon}</Text>
          {item.anonymous && <Text style={{ fontSize: FONT_SUB() }}>🤐</Text>}
          {item.amount && <Text style={{ fontSize: FONT_SMALL(), color: '#F59E0B' }}>¥{item.amount}</Text>}
        </View>
        <Text style={{ fontSize: FONT_BODY(), color: TH.text }} numberOfLines={2}>{item.content}</Text>
        {item.motivation && (
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, fontStyle: 'italic', marginTop: 2 }}>
            {T('giveMotivation')}：{item.motivation}
          </Text>
        )}
      </View>
    );
  }, [TH, T]);

  const listHeader = useMemo(() => (
    <>
      {/* Stats Card */}
      <View style={{ borderRadius: 16, borderWidth: 1, borderColor: `${TH.primary}30`, padding: 16, marginBottom: 16 }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-around' }}>
          {[
            { value: String(stats.total), label: T('giveTotal') },
            { value: String(stats.monthCount), label: T('giveMonth') },
            { value: String(stats.longest), label: T('giveLongestStreak') },
          ].map((s, i) => (
            <View key={i} style={{ alignItems: 'center', gap: 2 }}>
              <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>{s.value}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{s.label}</Text>
            </View>
          ))}
        </View>
      </View>

      {/* Heatmap */}
      <View style={{ borderRadius: 16, borderWidth: 1, borderColor: `${TH.primary}20`, padding: 16, marginBottom: 16 }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
          <TouchableOpacity onPress={() => setMonthOffset(o => o - 1)}>
            <ChevronLeft size={20} color={TH.sub} />
          </TouchableOpacity>
          <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }}>
            {year}/{String(month + 1)} · {String(stats.monthCount)}次
          </Text>
          <TouchableOpacity onPress={() => setMonthOffset(o => Math.min(o + 1, 0))}>
            <ChevronRight size={20} color={TH.sub} />
          </TouchableOpacity>
        </View>
        <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>
          {WEEKDAY_KEYS.map(k => (
            <View key={k} style={{ width: '14.28%', alignItems: 'center', paddingVertical: 4 }}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T(k)}</Text>
            </View>
          ))}
          {heatmapDays.map((day, i) => (
            <View key={i} style={{ width: '14.28%', alignItems: 'center', paddingVertical: 3 }}>
              {day.date ? (
                <View style={{
                  width: 28, height: 28, borderRadius: 14, alignItems: 'center', justifyContent: 'center',
                  backgroundColor: day.hasRecord ? '#F59E0B' : day.isToday ? `${TH.primary}30` : 'transparent',
                }}>
                  <Text style={{ fontSize: FONT_SMALL(), color: day.hasRecord ? '#fff' : TH.text, fontWeight: day.isToday ? '700' : '400' }}>
                    {parseInt(day.date.split('-')[2])}
                  </Text>
                </View>
              ) : <View style={{ width: 28, height: 28 }} />}
            </View>
          ))}
        </View>
      </View>

      {/* Type Distribution */}
      <View style={{ marginBottom: 16 }}>
        <Text style={{ fontSize: FONT_SUB(), fontWeight: '700', color: TH.text, marginBottom: 10 }}>{T('giveDistribution')}</Text>
        {Object.entries(GIVE_TYPE_CONFIG).map(([type, config]) => {
          const count = stats.byType[type as keyof typeof stats.byType] || 0;
          const percent = stats.typePercent[type as keyof typeof stats.typePercent] || 0;
          return (
            <View key={type} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 8 }}>
              <Text style={{ fontSize: FONT_LABEL(), marginRight: 8 }}>{config.icon}</Text>
              <Text style={{ width: 60, fontSize: FONT_BODY(), color: TH.text }}>{T(config.labelKey) || type}</Text>
              <View style={{ flex: 1, height: 8, backgroundColor: `${config.color}20`, borderRadius: 4, overflow: 'hidden' }}>
                <View style={{ width: `${percent}%`, height: '100%', backgroundColor: config.color, borderRadius: 4 }} />
              </View>
              <Text style={{ width: 50, textAlign: 'right', fontSize: FONT_BODY(), color: TH.sub }}>{count} ({percent}%)</Text>
            </View>
          );
        })}
      </View>

      {giveHistory.length > 0 && (
        <Text style={{ fontSize: FONT_SUB(), fontWeight: '700', color: TH.text, marginBottom: 10 }}>{T('giveTimeline')}</Text>
      )}
    </>
  ), [TH, T, stats, year, month, heatmapDays, giveHistory.length]);

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 16, paddingBottom: 0 }}>
        <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{T('giveHistory')}</Text>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <X size={22} color={TH.sub} />
        </TouchableOpacity>
      </View>
      <FlatList
        data={displayHistory}
        keyExtractor={item => item.id}
        renderItem={renderTimelineItem}
        removeClippedSubviews={true}
        contentContainerStyle={{ padding: 16, paddingBottom: 40 }}
        ListHeaderComponent={listHeader}
      />
    </SafeAreaView>
  );
}

import {FONT_TITLE, FONT_BODY, FONT_SUB, FONT_STAT_CARD , FONT_SMALL, FONT_BACK} from '@egoless-do/core';
import type { GiveType } from '@egoless-do/core';
import { HandHeart, Plus, BarChart3, Check, X } from 'lucide-react-native';
import React, { useState, useMemo, useCallback } from 'react';
import { View, Text, FlatList, ScrollView, TouchableOpacity, TextInput, Modal, StyleSheet } from 'react-native';

import { useTheme, useT } from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';


const GIVE_TYPES: { type: GiveType; icon: string; color: string }[] = [
  { type: 'fearless', icon: '🛡', color: '#10B981' },
  { type: 'material', icon: '💰', color: '#F59E0B' },
  { type: 'dharma', icon: '📖', color: '#3B82F6' },
];

export default function GiveScreen() {
  const TH = useTheme();
  const T = useT();
  const nav = useRootNavigation();
  const { giveHistory: giveHistoryRaw, addGive } = useShallowStore(s => ({
    giveHistory: s.giveHistory,
    addGive: s.addGive,
  }));

  const [showModal, setShowModal] = useState(false);
  const [giveType, setGiveType] = useState<GiveType>('fearless');
  const [content, setContent] = useState('');
  const [motivation, setMotivation] = useState('');
  const [amount, setAmount] = useState('');
  const [anonymous, setAnonymous] = useState(false);

  const giveHistory = useMemo(() => {
    return (giveHistoryRaw ?? []).filter(g => !g.deleted).sort((a, b) => b.timestamp - a.timestamp);
  }, [giveHistoryRaw]);

  const stats = useMemo(() => {
    const now = Date.now();
    const weekStart = now - 7 * 24 * 3600000;
    const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
    const total = giveHistory.length;
    const week = giveHistory.filter(g => g.timestamp >= weekStart).length;
    const month = giveHistory.filter(g => g.timestamp >= monthStart.getTime()).length;
    const byType = { material: 0, dharma: 0, fearless: 0 };
    giveHistory.forEach(g => { byType[g.type] = (byType[g.type] || 0) + 1; });
    return { total, week, month, byType };
  }, [giveHistory]);

  const recentRecords = giveHistory.slice(0, 5);

  const handleSave = useCallback(() => {
    if (!content.trim()) return;
    addGive({
      timestamp: Date.now(),
      type: giveType,
      content: content.trim(),
      motivation: motivation.trim() || undefined,
      anonymous,
      amount: giveType === 'material' && amount ? parseFloat(amount) : undefined,
    });
    setContent(''); setMotivation(''); setAmount(''); setAnonymous(false);
    setShowModal(false);
  }, [content, motivation, amount, anonymous, giveType, addGive]);

  const renderGiveItem = useCallback(({ item }: { item: typeof giveHistory[number] }) => {
    const config = GIVE_TYPES.find(t => t.type === item.type);
    const d = new Date(item.timestamp);
    return (
      <View style={[styles.recentRow, { borderLeftColor: config?.color || '#F59E0B' }]}>
        <View style={styles.recentHeader}>
          <Text style={[styles.recentDate, { color: TH.sub }]}>
            {String(d.getMonth() + 1)}/{String(d.getDate())}
          </Text>
          <Text style={styles.recentIcon}>{config?.icon || '💰'}</Text>
          {item.anonymous && <Text style={styles.anonTag}>🤐</Text>}
        </View>
        <Text style={[styles.recentContent, { color: TH.text }]} numberOfLines={2}>{item.content}</Text>
        {item.motivation && (
          <Text style={[styles.recentMotivation, { color: TH.sub }]} numberOfLines={1}>
            心念：{item.motivation}
          </Text>
        )}
      </View>
    );
  }, [TH, T]);

  const listHeader = useMemo(() => (
    <>
      {/* Stats Card */}
      <View style={[styles.statsCard, { borderColor: `${TH.primary}30` }]}>
        <View style={styles.statsHeader}>
          <HandHeart size={20} color="#F59E0B" />
          <Text style={[styles.statsTitle, { color: TH.text }]}>{T('giveTitle')}</Text>
        </View>
        <Text style={[styles.quoteText, { color: TH.sub }]}>{T('giveQuote')}</Text>
        <View style={styles.statsRow}>
          <View style={styles.statItem}>
            <Text style={[styles.statValue, { color: '#F59E0B' }]}>{String(stats.total)}</Text>
            <Text style={[styles.statLabel, { color: TH.sub }]}>{T('giveTotal')}</Text>
          </View>
          <View style={styles.statItem}>
            <Text style={[styles.statValue, { color: TH.text }]}>{String(stats.month)}</Text>
            <Text style={[styles.statLabel, { color: TH.sub }]}>{T('giveMonth')}</Text>
          </View>
          <View style={styles.statItem}>
            <Text style={[styles.statValue, { color: '#10B981' }]}>{String(stats.week)}</Text>
            <Text style={[styles.statLabel, { color: TH.sub }]}>{T('giveWeek')}</Text>
          </View>
        </View>
        {/* Type breakdown */}
        <View style={styles.typeRow}>
          {GIVE_TYPES.map(gt => (
            <View key={gt.type} style={styles.typeItem}>
              <Text style={styles.typeIcon}>{gt.icon}</Text>
              <Text style={[styles.typeCount, { color: gt.color }]}>{String(stats.byType[gt.type] || 0)}</Text>
              <Text style={[styles.typeLabel, { color: TH.sub }]}>{T(`give${gt.type.charAt(0).toUpperCase() + gt.type.slice(1)}`) || gt.type}</Text>
            </View>
          ))}
        </View>
      </View>

      {/* Record button */}
      <TouchableOpacity
        style={[styles.recordBtn, { backgroundColor: '#F59E0B' }]}
        onPress={() => setShowModal(true)}
      >
        <Plus size={20} color="#fff" />
        <Text style={styles.recordBtnText}>{T('giveRecord')}</Text>
      </TouchableOpacity>

      {recentRecords.length > 0 && (
        <Text style={[styles.sectionTitle, { color: TH.text }]}>{T('giveRecent')}</Text>
      )}
    </>
  ), [TH, T, stats, recentRecords.length]);

  const listFooter = useMemo(() => (
    recentRecords.length > 0 ? (
      <TouchableOpacity
        style={[styles.historyBtn, { borderColor: `${TH.primary}30` }]}
        onPress={() => nav.navigate('GiveHistory')}
      >
        <BarChart3 size={18} color={TH.primary} />
        <Text style={[styles.historyBtnText, { color: TH.primary }]}>{T('giveHistory')}</Text>
      </TouchableOpacity>
    ) : (
      <TouchableOpacity
        style={[styles.historyBtn, { borderColor: `${TH.primary}30` }]}
        onPress={() => nav.navigate('GiveHistory')}
      >
        <BarChart3 size={18} color={TH.primary} />
        <Text style={[styles.historyBtnText, { color: TH.primary }]}>{T('giveHistory')}</Text>
      </TouchableOpacity>
    )
  ), [TH, T, nav, recentRecords.length]);

  return (
    <View style={{ flex: 1, backgroundColor: TH.bg }}>
      <SimpleHeader routeName="Give" />
      <FlatList
        data={recentRecords}
        keyExtractor={item => item.id}
        renderItem={renderGiveItem}
        removeClippedSubviews={true}
        contentContainerStyle={{ padding: 16, paddingBottom: 40 }}
        ListHeaderComponent={listHeader}
        ListFooterComponent={listFooter}
      />

      {/* Record Modal */}
      <Modal visible={showModal} animationType="slide" presentationStyle="pageSheet">
        <View style={[styles.modalContainer, { backgroundColor: TH.bg }]}>
          <View style={styles.modalHeader}>
            <Text style={[styles.modalTitle, { color: TH.text }]}>{T('giveRecord')}</Text>
            <TouchableOpacity onPress={() => setShowModal(false)}>
              <X size={22} color={TH.sub} />
            </TouchableOpacity>
          </View>
          <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }}>
            {/* Type selection */}
            <Text style={[styles.modalLabel, { color: TH.text }]}>{T('giveType')}</Text>
            <View style={styles.typeSelectRow}>
              {GIVE_TYPES.map(gt => (
                <TouchableOpacity
                  key={gt.type}
                  style={[styles.typeChip, {
                    backgroundColor: giveType === gt.type ? gt.color : `${gt.color}15`,
                    borderColor: giveType === gt.type ? gt.color : `${gt.color}30`,
                  }]}
                  onPress={() => setGiveType(gt.type)}
                >
                  <Text style={styles.typeChipIcon}>{gt.icon}</Text>
                  <Text style={{ color: giveType === gt.type ? '#fff' : gt.color, fontSize: FONT_BODY(), fontWeight: '600' }}>
                    {T(`give${gt.type.charAt(0).toUpperCase() + gt.type.slice(1)}`) || gt.type}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>

            {/* Content */}
            <Text style={[styles.modalLabel, { color: TH.text }]}>{T('giveContent')}</Text>
            <TextInput
              value={content}
              onChangeText={setContent}
              placeholder={T('giveContentPlaceholder')}
              placeholderTextColor={TH.sub}
              multiline
              style={[styles.modalInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
            />

            {/* Motivation (collapsible) */}
            <Text style={[styles.modalLabel, { color: TH.text }]}>{T('giveMotivation')}</Text>
            <TextInput
              value={motivation}
              onChangeText={setMotivation}
              placeholder={T('giveMotivationPlaceholder')}
              placeholderTextColor={TH.sub}
              multiline
              style={[styles.modalInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
            />

            {/* Amount (material only) */}
            {giveType === 'material' && (
              <>
                <Text style={[styles.modalLabel, { color: TH.text }]}>{T('giveAmount')}</Text>
                <TextInput
                  value={amount}
                  onChangeText={setAmount}
                  placeholder="0"
                  placeholderTextColor={TH.sub}
                  keyboardType="number-pad"
                  style={[styles.modalInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card, width: 120 }]}
                />
              </>
            )}

            {/* Anonymous */}
            <TouchableOpacity
              style={styles.anonRow}
              onPress={() => setAnonymous(!anonymous)}
            >
              <View style={[styles.checkbox, { borderColor: TH.primary, backgroundColor: anonymous ? TH.primary : 'transparent' }]}>
                {anonymous && <Check size={14} color="#fff" />}
              </View>
              <Text style={[styles.anonLabel, { color: TH.text }]}>{T('giveAnonymous')}</Text>
            </TouchableOpacity>
            <Text style={[styles.anonHint, { color: TH.sub }]}>{T('giveAnonymousHint')}</Text>

            {/* Save */}
            <TouchableOpacity
              style={[styles.saveBtn, { backgroundColor: content.trim() ? '#F59E0B' : `${TH.sub}30` }]}
              onPress={handleSave}
              disabled={!content.trim()}
            >
              <Text style={styles.saveBtnText}>{T('giveSave')}</Text>
            </TouchableOpacity>
          </ScrollView>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  statsCard: { borderRadius: 16, borderWidth: 1, padding: 16, marginBottom: 16 },
  statsHeader: { flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 4 },
  statsTitle: { fontSize: FONT_TITLE(), fontWeight: '700' },
  quoteText: { fontSize: FONT_SUB(), marginBottom: 12, fontStyle: 'italic' },
  statsRow: { flexDirection: 'row', justifyContent: 'space-around', marginBottom: 12 },
  statItem: { alignItems: 'center', gap: 2 },
  statValue: { fontSize: FONT_STAT_CARD(), fontWeight: '800' },
  statLabel: { fontSize: FONT_SMALL() },
  typeRow: { flexDirection: 'row', justifyContent: 'space-around' },
  typeItem: { alignItems: 'center', gap: 4 },
  typeIcon: { fontSize: FONT_BACK() },
  typeCount: { fontSize: FONT_BODY(), fontWeight: '700' },
  typeLabel: { fontSize: FONT_SMALL() },
  recordBtn: {
    flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8,
    padding: 16, borderRadius: 14, marginBottom: 16,
  },
  recordBtnText: { color: '#fff', fontSize: FONT_BODY(), fontWeight: '700' },
  section: { marginBottom: 16 },
  sectionTitle: { fontSize: FONT_SUB(), fontWeight: '700', marginBottom: 10 },
  recentRow: { borderLeftWidth: 3, paddingLeft: 12, paddingVertical: 8, marginBottom: 8 },
  recentHeader: { flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 4 },
