                          <View key={tag} style={{ backgroundColor: 'rgba(255,255,255,0.15)', borderRadius: 6, paddingHorizontal: 8, paddingVertical: 3 }}>
                            <Text style={{ fontSize: FONT_BODY(), color: '#fff' }}>{tag}</Text>
                          </View>
                        ))}
                      </View>
                    )}
                  </View>
