                <Text style={{ fontSize: FONT_SMALL(), color: '#fff' }}>{T('bodyAwarenessRecords')}</Text>
              </TouchableOpacity>
            </View>
            <View style={styles.bannerContent}>
              <View style={{ flex: 1 }}>
                {latestCheckin ? (
                  <>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-around', marginBottom: 12, gap: 4 }}>
                      {[
