                    </Text>
                  </View>
                )}
              </View>
            </View>
            <TouchableOpacity
              onPress={() => setShowCheckin(true)}
              activeOpacity={0.85}
              style={[styles.bannerButton, { backgroundColor: 'rgba(255,255,255,0.9)' }]}
            >
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: '#10b981' }}>{T('bodyFlowAwareness')}</Text>
            </TouchableOpacity>
          </View>

          {/* Banner 4: 体重趋势 */}
          <View style={[styles.bannerCard, { backgroundColor: '#3b82f6' }]}>
            <View style={styles.bannerHeader}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                <Text style={{ fontSize: 20 }}>⚖️</Text>
                <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: '#fff' }}>{T('bodyWeightTrend')}</Text>
              </View>
              <TouchableOpacity
                onPress={() => setShowWeightRecord(true)}
                style={{ flexDirection: 'row', alignItems: 'center', gap: 4, backgroundColor: 'rgba(255,255,255,0.2)', paddingHorizontal: 10, paddingVertical: 6, borderRadius: 8 }}
              >
                <Text style={{ fontSize: FONT_SMALL(), color: '#fff', fontWeight: '600' }}>{T('bodyRecordWeight')}</Text>
              </TouchableOpacity>
            </View>
            <View style={styles.bannerContent}>
              <View style={{ flex: 1 }}>
                {weightTrend ? (
                  <>
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 10 }}>
                      <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: '#fff' }}>
                        {`${weightTrend.current} kg`}
                      </Text>
                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                        <TrendingUp size={18} color={weightTrend.diff > 0 ? '#fbbf24' : '#34d399'} style={weightTrend.diff < 0 ? { transform: [{ scaleY: -1 }] } : undefined} />
                        <Text style={{ fontSize: FONT_BODY(), color: weightTrend.diff > 0 ? '#fbbf24' : '#34d399', fontWeight: '600' }}>
                          {`${weightTrend.diff > 0 ? '+' : ''}${weightTrend.diff.toFixed(1)} kg`}
                        </Text>
                      </View>
                    </View>
                    {/* Line chart - last 7 days */}
                    <View style={{ height: 80, marginTop: 4 }}>
                      {(() => {
                        const records = (checkinHistory ?? [])
                          .filter(r => !r.deleted && r.weight != null && r.weight > 0)
                          .sort((a, b) => a.date.localeCompare(b.date))
                          .slice(-7);
                        if (records.length < 2) return null;
                        const weights = records.map(r => r.weight);
                        const minW = Math.min(...weights);
                        const maxW = Math.max(...weights);
                        const range = maxW - minW || 1;
                        const chartHeight = 50;
                        const labelHeight = 20;
                        const totalHeight = chartHeight + labelHeight;
                        const chartWidth = BANNER_WIDTH - 80;
                        const stepX = chartWidth / (records.length - 1);

                        return (
                          <View style={{ position: 'relative', height: totalHeight }}>
                            {/* Line segments */}
                            {records.map((r, i) => {
                              if (i === 0) return null;
                              const prevR = records[i - 1];
                              const x1 = (i - 1) * stepX;
                              const y1 = chartHeight - ((prevR.weight - minW) / range) * (chartHeight - 15);
                              const x2 = i * stepX;
                              const y2 = chartHeight - ((r.weight - minW) / range) * (chartHeight - 15);
                              const length = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
                              const angle = Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI);
                              return (
                                <View
                                  key={`line-${i}`}
                                  style={{
                                    position: 'absolute',
                                    left: x1,
                                    top: y1,
                                    width: length,
                                    height: 2,
                                    backgroundColor: 'rgba(255,255,255,0.8)',
                                    transform: [{ rotate: `${angle}deg` }],
                                    transformOrigin: '0 0',
                                  }}
                                />
                              );
                            })}
                            {/* Data points with weight labels */}
                            {records.map((r, i) => {
                              const x = i * stepX;
                              const y = chartHeight - ((r.weight - minW) / range) * (chartHeight - 15);
                              const isLast = i === records.length - 1;
                              return (
                                <React.Fragment key={`point-${i}`}>
                                  {/* Weight value above point */}
                                  <Text style={{
                                    position: 'absolute',
                                    left: x - 15,
                                    top: y - 18,
                                    fontSize: FONT_SMALL(),
                                    color: '#fff',
                                    fontWeight: isLast ? '700' : '500',
                                    width: 30,
                                    textAlign: 'center',
                                  }}>
                                    {String(r.weight)}
                                  </Text>
                                  {/* Point */}
                                  <View style={{
                                    position: 'absolute',
                                    left: x - 5,
                                    top: y - 5,
                                    width: isLast ? 12 : 8,
                                    height: isLast ? 12 : 8,
                                    borderRadius: isLast ? 6 : 4,
                                    backgroundColor: isLast ? '#fff' : 'rgba(255,255,255,0.7)',
                                  }} />
                                </React.Fragment>
                              );
                            })}
                            {/* Date labels at bottom */}
                            {records.map((r, i) => (
                              <Text
                                key={`label-${i}`}
                                style={{
                                  position: 'absolute',
                                  left: i * stepX - 12,
                                  top: chartHeight + 4,
                                  fontSize: FONT_SMALL(),
                                  color: 'rgba(255,255,255,0.8)',
                                  width: 24,
                                  textAlign: 'center',
                                }}
                              >
                                {r.date.slice(8)}
                              </Text>
                            ))}
                          </View>
                        );
                      })()}
                    </View>
                  </>
                ) : (
                  <View style={{ alignItems: 'center', paddingVertical: 20 }}>
                    <Text style={{ fontSize: 40, marginBottom: 8 }}>📊</Text>
                    <Text style={{ fontSize: FONT_BODY(), color: 'rgba(255,255,255,0.8)' }}>
                      {T('bodyWeightNoData')}
                    </Text>
                  </View>
                )}
              </View>
            </View>
            <TouchableOpacity
              onPress={() => setShowWeightTrend(true)}
              activeOpacity={0.85}
              style={[styles.bannerButton, { backgroundColor: 'rgba(255,255,255,0.9)' }]}
            >
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: '#3b82f6' }}>{T('bodyMoreWeightTrend')}</Text>
            </TouchableOpacity>
          </View>
        </ScrollView>

        {/* Banner indicators */}
        <View style={styles.bannerIndicators}>
          {[0, 1, 2, 3].map(i => (
            <View
              key={i}
              style={[
                styles.bannerDot,
                { backgroundColor: i === currentBanner ? '#fff' : 'rgba(255,255,255,0.4)' }
              ]}
            />
          ))}
        </View>
        {/* Guide text */}
        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, textAlign: 'center', marginTop: 6 }}>
          {T('bodySwipeHint')}
        </Text>
      </View>

      {/* ── 调身目标 ── */}
      <TouchableOpacity
        onPress={() => setShowGoalEdit(true)}
        activeOpacity={0.85}
        style={[styles.goalCard, { backgroundColor: TH.card }]}
      >
        <View style={styles.goalHeader}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
            <View style={[styles.goalIconCircle, { backgroundColor: '#8b5cf6' }]}>
              <Target size={18} color="#fff" />
            </View>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{T('bodyGoal')}</Text>
          </View>
          <Text style={{ fontSize: FONT_SMALL(), color: '#8b5cf6' }}>{activeGoal ? T('bodyGoalEdit') : T('bodyGoalSet')}</Text>
        </View>
        {activeGoal ? (
          <View style={styles.goalContent}>
            <View style={styles.goalMetrics}>
              {activeGoal.targetWeight != null && (
                <View style={styles.goalMetricItem}>
                  <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>{`${activeGoal.targetWeight}kg`}</Text>
                  <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyTargetWeight')}</Text>
                </View>
              )}
              {activeGoal.targetBodyFat != null && (
                <View style={styles.goalMetricItem}>
                  <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>{`${activeGoal.targetBodyFat}%`}</Text>
                  <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyTargetBodyFat')}</Text>
                </View>
              )}
              {activeGoal.strategy && (
                <View style={styles.goalMetricItem}>
                  <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '600', color: '#8b5cf6' }}>
                    {getStrategyLabel(activeGoal.strategy)}
                  </Text>
                  <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyStrategyLabel')}</Text>
                </View>
              )}
            </View>
            {activeGoal.targetDate && (
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 8 }}>{T('bodyTargetDate')}: {activeGoal.targetDate}</Text>
            )}
          </View>
        ) : (
          <View style={styles.goalEmpty}>
            <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('bodyGoalNotSet')}</Text>
          </View>
        )}
      </TouchableOpacity>

      {/* ── 我的训练计划 ── */}
      <TouchableOpacity
        onPress={() => nav.navigate('PlanManagement' as never)}
        activeOpacity={0.85}
        style={[styles.planCard, { backgroundColor: TH.card }]}
      >
        <View style={styles.planHeader}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
            <View style={[styles.planIconCircle, { backgroundColor: '#f59e0b' }]}>
              <Dumbbell size={18} color="#fff" />
            </View>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{T('bodyPlanManagement')}</Text>
          </View>
          <Text style={{ fontSize: FONT_SMALL(), color: '#f59e0b' }}>{activeTrainingPlan ? T('bodyPlanEdit') : T('bodyPlanCreate')}</Text>
        </View>
        {activeTrainingPlan ? (
          <View style={styles.planContent}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{activeTrainingPlan.name}</Text>
              <View style={[styles.planBadge, { backgroundColor: '#10b98115' }]}>
                <Text style={{ fontSize: FONT_SMALL(), color: '#10b981', fontWeight: '600' }}>{T('bodyPlanActive')}</Text>
              </View>
            </View>
            <View style={{ flexDirection: 'row', gap: 12, marginBottom: 8 }}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{activeTrainingPlan.startDate} ~ {activeTrainingPlan.endDate}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{String(activeTrainingPlan.tasks.filter(t => t.sportKey && t.sportKey !== 'rest').length)}天/周</Text>
            </View>
            {planProgress && (
              <View>
                <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                  <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyProgress')}</Text>
                  <Text style={{ fontSize: FONT_SMALL(), color: TH.text, fontWeight: '600' }}>{String(planProgress.weekComplete)}/{String(planProgress.weekTotal)}</Text>
                </View>
                <View style={[styles.progressBarBg, { backgroundColor: TH.border, height: 6 }]}>
                  <View style={[styles.progressBarFill, { backgroundColor: '#f59e0b', height: 6, width: `${planProgress.weekTotal > 0 ? (planProgress.weekComplete / planProgress.weekTotal) * 100 : 0}%` }]} />
                </View>
              </View>
            )}
            {/* 周计划任务 */}
            <View style={{ marginTop: 12, paddingTop: 12, borderTopWidth: 1, borderTopColor: TH.border }}>
              <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 10 }}>{T('bodyWeeklyPlan')}</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
                {activeTrainingPlan.tasks.map((task) => {
                  const exercises = task.exercises ?? [];
                  const isRest = !task.sportKey || task.sportKey === 'rest';
                  const weekdayKeys = ['bodyWeekMon', 'bodyWeekTue', 'bodyWeekWed', 'bodyWeekThu', 'bodyWeekFri', 'bodyWeekSat', 'bodyWeekSun'];
                  const formatEx = (e: ExerciseDef) => {
                    const sets = e.defaultSets;
                    const reps = e.defaultReps;
                    const dur = e.defaultDurationSec;
                    if (sets && reps) return `${sets}×${reps}`;
                    if (sets) return `${sets}组`;
                    if (dur) return `${Math.round(dur / 60)}分钟`;
                    return '';
                  };
                  return (
                    <View key={task.weekday} style={{ width: 'calc((100% - 24px) / 4)', minWidth: 72, borderRadius: 10, borderWidth: 1, borderColor: isRest ? TH.border : '#f59e0b30', backgroundColor: isRest ? TH.bg : '#f59e0b08', padding: 8 }}>
                      <View style={{ width: 22, height: 22, borderRadius: 11, backgroundColor: isRest ? TH.border : '#f59e0b', alignItems: 'center', justifyContent: 'center', marginBottom: 6 }}>
                        <Text style={{ fontSize: 10, color: isRest ? TH.sub : '#fff', fontWeight: '700' }}>{T(weekdayKeys[task.weekday - 1])}</Text>
                      </View>
                      {isRest ? (
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, fontStyle: 'italic' }}>{T('bodyPlanRestDay')}</Text>
                      ) : exercises.length > 0 ? (
                        exercises.map((e, i) => (
                          <Text key={i} style={{ fontSize: 11, color: TH.text, lineHeight: 16 }}>
                            <Text style={{ fontWeight: '600' }}>{e.nameZh}</Text>
                            {formatEx(e) ? <Text style={{ color: TH.sub }}> {formatEx(e)}</Text> : null}
                          </Text>
                        ))
                      ) : (
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>—</Text>
                      )}
                    </View>
                  );
                })}
              </View>
            </View>
          </View>
        ) : (
          <View style={styles.planEmpty}>
            <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('bodyPlanNotSet')}</Text>
          </View>
        )}
      </TouchableOpacity>

      {/* ── 本周进度 ── */}
      {planProgress && (
        <View style={[styles.progressCard, { backgroundColor: TH.card }]}>
          <View style={styles.progressHeader}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
              <TrendingUp size={18} color="#10b981" />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{T('bodyWeeklyProgress')}</Text>
            </View>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>
              {String(planProgress.weekComplete)}/{String(planProgress.weekTotal)}
            </Text>
          </View>
          <View style={styles.progressBarContainer}>
            <View style={[styles.progressBarBg, { backgroundColor: TH.border }]}>
              <View
                style={[styles.progressBarFill, {
                  width: `${planProgress.weekTotal > 0 ? (planProgress.weekComplete / planProgress.weekTotal) * 100 : 0}%`,
                  backgroundColor: '#10b981',
                }]}
              />
            </View>
          </View>
          <View style={styles.progressStats}>
            <View style={styles.progressStatItem}>
              <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: '#f59e0b' }}>{String(planProgress.totalDuration)}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('exerciseMin')}</Text>
            </View>
            <View style={styles.progressStatItem}>
              <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: '#ef4444' }}>{String(planProgress.totalCal)}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>kcal</Text>
            </View>
            <View style={styles.progressStatItem}>
              <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: '#8b5cf6' }}>{String(planProgress.weekComplete)}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyDayCompleted')}</Text>
            </View>
          </View>
        </View>
      )}

      {/* ── 最近训练 ── */}
      {recentExercises.length > 0 && (
        <View style={[styles.recentCard, { backgroundColor: TH.card }]}>
          <View style={styles.recentHeader}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
              <Activity size={18} color="#f59e0b" />
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{T('exerciseRecentActivity')}</Text>
            </View>
            <TouchableOpacity onPress={() => nav.navigate('ExerciseHistory' as never)} style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.primary }}>{T('exerciseHistory')}</Text>
              <ChevronRight size={14} color={TH.primary} />
            </TouchableOpacity>
          </View>
          {recentExercises.map((e, i) => {
            const cat = EXERCISE_CATEGORIES.find(c => c.key === e.sportKey);
            const sportLabel = e.sportKey === COMBO_WORKOUT_SPORT_KEY ? T('bodyComboTraining') : (cat ? T(cat.i18nKey) : e.sportKey);
            return (
            <View key={e.id} style={[styles.recentItem, { borderBottomWidth: i < recentExercises.length - 1 ? 1 : 0, borderBottomColor: TH.border }]}>
              <Text style={{ fontSize: 20 }}>{e.sportIcon}</Text>
              <View style={{ flex: 1, marginLeft: 10 }}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{sportLabel}</Text>
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>
                  {String(Math.floor(e.durationSec / 60))}{T('bodyMin')} {e.calories ? `· ${e.calories}kcal` : ''}
                </Text>
              </View>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>
                {new Date(e.timestamp).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' })}
              </Text>
            </View>
            );
          })}
        </View>
      )}

      <AssessmentModal visible={showAssessment} TH={TH} T={T} profile={profile} onClose={() => setShowAssessment(false)} onSave={handleSaveAssessment} />
      <GoalEditModal visible={showGoalEdit} TH={TH} T={T} goal={activeGoal} profile={profile} onClose={() => setShowGoalEdit(false)} onSave={handleSaveGoal} />
      <BodyCheckinModal visible={showCheckin} TH={TH} T={T} todayPlan={todayPlan} onClose={() => setShowCheckin(false)} onSave={handleSaveCheckin} />
      <WeightRecordModal visible={showWeightRecord} TH={TH} T={T} currentWeight={profile.weight as number | undefined} currentBodyFat={profile.bodyFat as number | undefined} onClose={() => setShowWeightRecord(false)} onSave={handleSaveWeight} />
      <WeightTrendModal visible={showWeightTrend} TH={TH} T={T} checkins={checkinHistory ?? []} onClose={() => setShowWeightTrend(false)} />

      {/* Override modals */}
      <QuickSwapModal visible={showQuickSwap} onClose={() => setShowQuickSwap(false)} onConfirm={handleSwapConfirm} TH={TH} T={T} />
      {todayExercises && (
        <AdjustExerciseModal visible={showAdjustExercise} onClose={() => setShowAdjustExercise(false)} onConfirm={handleAdjustConfirm} exercises={todayExercises} TH={TH} T={T} />
      )}
      <DayActionSheet
        visible={showDayAction}
        onClose={() => setShowDayAction(false)}
        dayLabel={selectedDay ? T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][selectedDay - 1]}`) : ''}
        isRest={selectedDayIsRest}
        hasOverride={!!selectedDayOverride}
        onSwap={() => { setShowDayAction(false); setShowQuickSwap(true); }}
        onSkip={handleDaySkip}
        onSwapDays={() => { setShowDayAction(false); setShowDaySwapPicker(true); }}
        onAdjust={() => { setShowDayAction(false); setShowAdjustExercise(true); }}
        TH={TH} T={T}
      />
      {activeTrainingPlan && (
        <GoalEditLightModal
          visible={showGoalEditLight}
          onClose={() => setShowGoalEditLight(false)}
          onConfirm={handleSaveGoalLight}
          initialStrategy={activeTrainingPlan.strategy}
          initialTargetWeight={activeTrainingPlan.targetWeight}
          initialTargetBodyFat={activeTrainingPlan.targetBodyFat}
          initialGoalNote={activeTrainingPlan.goalNote}
          TH={TH} T={T}
        />
      )}

      {/* Day swap picker modal */}
      <Modal visible={showDaySwapPicker} transparent animationType="fade">
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.5)', justifyContent: 'center', alignItems: 'center' }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, width: '80%', maxWidth: 320 }}>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginBottom: 16, textAlign: 'center' }}>
              {T('bodySwapDays')}
            </Text>
            {[1,2,3,4,5,6,7].filter(d => d !== selectedDay).map(d => (
              <TouchableOpacity
                key={d}
                onPress={() => handleDaySwapConfirm(d)}
                style={{ paddingVertical: 14, paddingHorizontal: 20, borderRadius: 12, marginBottom: 8, backgroundColor: `${TH.primary}15`, borderWidth: 1, borderColor: `${TH.primary}30` }}
              >
                <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', textAlign: 'center' }}>
                  {T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d - 1]}`)}
                </Text>
              </TouchableOpacity>
            ))}
            <TouchableOpacity
              onPress={() => setShowDaySwapPicker(false)}
              style={{ paddingVertical: 12, alignItems: 'center', marginTop: 8 }}
            >
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('commonCancel')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {celebrationData && (
        <CelebrationOverlay
          visible={showCelebration}
          TH={TH} T={T}
          data={celebrationData}
          onDismiss={() => setShowCelebration(false)}
        />
      )}
    </View>
  );
}

// ─── BodyDashboardModals ────────────────────────────────────
// 11 个 Modal 组件集合，从 BodyDashboard.tsx 提取
// 所有数据和回调通过 Props 传入

import { FONT_TITLE, FONT_BODY, FONT_SUB, type BodyGoal, type BodyTrainingPlan, type BodyPlan, type DayOverride, type ExerciseDef, type BodyCheckin } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, Modal } from 'react-native';

import { styles } from './BodyDashboardStyles';
import AdjustExerciseModal from './modals/AdjustExerciseModal';
import AssessmentModal from './modals/AssessmentModal';
import BodyCheckinModal from './modals/BodyCheckinModal';
import DayActionSheet from './modals/DayActionSheet';
import GoalEditLightModal from './modals/GoalEditLightModal';
import GoalEditModal from './modals/GoalEditModal';
import QuickSwapModal from './modals/QuickSwapModal';
import WeightRecordModal from './modals/WeightRecordModal';
import WeightTrendModal from './modals/WeightTrendModal';
import CelebrationOverlay from './screens/CelebrationOverlay';

interface BodyDashboardModalsProps {
  TH: { primary: string; sub: string; bg: string; card: string; cardSolid: string; border: string; text: string };
  T: (key: string, params?: Record<string, string | number>) => string;
  todayPlan?: BodyPlan;
  activeGoal?: BodyGoal;
  activeTrainingPlan?: BodyTrainingPlan;
  profile: Record<string, unknown>;
  todayExercises?: ExerciseDef[];
  selectedDay: number | null;
  selectedDayIsRest: boolean;
  selectedDayOverride: DayOverride | undefined;
  // Visible states
  showAssessment: boolean; showGoalEdit: boolean; showCheckin: boolean;
  showWeightRecord: boolean; showWeightTrend: boolean; showQuickSwap: boolean;
  showAdjustExercise: boolean; showDayAction: boolean; showGoalEditLight: boolean;
  showDaySwapPicker: boolean; showCelebration: boolean;
  // Close handlers
  onCloseAssessment: () => void; onCloseGoalEdit: () => void;
  onCloseCheckin: () => void; onCloseWeightRecord: () => void;
  onCloseWeightTrend: () => void; onCloseQuickSwap: () => void;
  onCloseAdjustExercise: () => void; onCloseDayAction: () => void;
  onCloseGoalEditLight: () => void; onCloseDaySwapPicker: () => void;
  onCloseCelebration: () => void;
  // Save handlers
  onSaveAssessment: (text: string, tags: string[]) => void;
  onSaveGoal: (data: Partial<BodyGoal>) => void;
  onSaveCheckin: (data: { date: string; energy: number; pain: number; comfort: number; sleep: number; tags: string[]; note?: string }) => void;
  onSaveWeight: (data: { date: string; weight: number; bodyFat?: number }) => void;
  onSwapConfirm: (sportKey: string, exercises?: ExerciseDef[]) => void;
  onAdjustConfirm: (adjustments: { exerciseId: string; sets: number; reps: number; durationSec?: number }[]) => void;
  onDaySkip: () => void;
  onOpenQuickSwap: () => void;
  onOpenDaySwapPicker: () => void;
  onOpenAdjustExercise: () => void;
  onDaySwapConfirm: (targetDay: number) => void;
  onSaveGoalLight: (data: { strategy?: string; targetWeight?: number; targetBodyFat?: number; goalNote?: string }) => void;
  // Other
  checkinHistory?: { deleted?: boolean; weight?: number; date: string }[];
  celebrationData: { planName: string; totalDays: number; completedDays: number; totalDurationMin: number; totalCalories: number } | null;
}

export default function BodyDashboardModals({
  TH, T, todayPlan, activeGoal, activeTrainingPlan, profile, todayExercises,
  selectedDay, selectedDayIsRest, selectedDayOverride,
  showAssessment, showGoalEdit, showCheckin, showWeightRecord, showWeightTrend,
  showQuickSwap, showAdjustExercise, showDayAction, showGoalEditLight,
  showDaySwapPicker, showCelebration,
  onCloseAssessment, onCloseGoalEdit, onCloseCheckin, onCloseWeightRecord,
  onCloseWeightTrend, onCloseQuickSwap, onCloseAdjustExercise, onCloseDayAction,
  onCloseGoalEditLight, onCloseDaySwapPicker, onCloseCelebration,
  onSaveAssessment, onSaveGoal, onSaveCheckin, onSaveWeight,
  onSwapConfirm, onAdjustConfirm, onDaySkip, onOpenQuickSwap, onOpenDaySwapPicker, onOpenAdjustExercise, onDaySwapConfirm,
  onSaveGoalLight,
  checkinHistory, celebrationData,
}: BodyDashboardModalsProps) {
  return (
    <>
      <AssessmentModal visible={showAssessment} TH={TH} T={T} profile={profile} onClose={onCloseAssessment} onSave={onSaveAssessment} />
      <GoalEditModal visible={showGoalEdit} TH={TH} T={T} goal={activeGoal} profile={profile} onClose={onCloseGoalEdit} onSave={onSaveGoal} />
      <BodyCheckinModal visible={showCheckin} TH={TH} T={T} todayPlan={todayPlan} onClose={onCloseCheckin} onSave={onSaveCheckin} />
      <WeightRecordModal visible={showWeightRecord} TH={TH} T={T} currentWeight={profile.weight as number | undefined} currentBodyFat={profile.bodyFat as number | undefined} onClose={onCloseWeightRecord} onSave={onSaveWeight} />
      <WeightTrendModal visible={showWeightTrend} TH={TH} T={T} checkins={checkinHistory ?? []} onClose={onCloseWeightTrend} />

      {/* Override modals */}
      <QuickSwapModal visible={showQuickSwap} onClose={onCloseQuickSwap} onConfirm={onSwapConfirm} TH={TH} T={T} />
      {todayExercises && (
        <AdjustExerciseModal visible={showAdjustExercise} onClose={onCloseAdjustExercise} onConfirm={onAdjustConfirm} exercises={todayExercises} TH={TH} T={T} />
      )}
      <DayActionSheet
        visible={showDayAction}
        onClose={onCloseDayAction}
        dayLabel={selectedDay ? T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][selectedDay - 1]}`) : ''}
        isRest={selectedDayIsRest}
        hasOverride={!!selectedDayOverride}
        onSwap={() => { onCloseDayAction(); onOpenQuickSwap(); }}
        onSkip={onDaySkip}
        onSwapDays={() => { onCloseDayAction(); onOpenDaySwapPicker(); }}
        onAdjust={() => { onCloseDayAction(); onOpenAdjustExercise(); }}
        TH={TH} T={T}
      />
      {activeTrainingPlan && (
        <GoalEditLightModal
          visible={showGoalEditLight}
          onClose={onCloseGoalEditLight}
          onConfirm={onSaveGoalLight}
          initialStrategy={activeTrainingPlan.strategy}
          initialTargetWeight={activeTrainingPlan.targetWeight}
          initialTargetBodyFat={activeTrainingPlan.targetBodyFat}
          initialGoalNote={activeTrainingPlan.goalNote}
          TH={TH} T={T}
        />
      )}

      {/* Day swap picker modal */}
      <Modal visible={showDaySwapPicker} transparent animationType="fade">
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.5)', justifyContent: 'center', alignItems: 'center' }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, width: '80%', maxWidth: 320 }}>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginBottom: 16, textAlign: 'center' }}>
              {T('bodySwapDays')}
            </Text>
            {[1,2,3,4,5,6,7].filter(d => d !== selectedDay).map(d => (
              <TouchableOpacity
                key={d}
                onPress={() => onDaySwapConfirm(d)}
                style={{ paddingVertical: 14, paddingHorizontal: 20, borderRadius: 12, marginBottom: 8, backgroundColor: `${TH.primary}15`, borderWidth: 1, borderColor: `${TH.primary}30` }}
              >
                <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', textAlign: 'center' }}>
                  {T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d - 1]}`)}
                </Text>
              </TouchableOpacity>
            ))}
            <TouchableOpacity
              onPress={onCloseDaySwapPicker}
              style={{ paddingVertical: 12, alignItems: 'center', marginTop: 8 }}
            >
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('commonCancel')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {celebrationData && (
        <CelebrationOverlay
          visible={showCelebration}
          TH={TH} T={T}
          data={celebrationData}
          onDismiss={onCloseCelebration}
        />
      )}
    </>
  );
}

import {FONT_TITLE, FONT_BODY, FONT_SUB, FONT_SMALL, FONT_STAT_CARD, ALL_SPORTS, EXERCISE_CATEGORIES, PART_STRING_TO_KEY, SPORT_GROUPS, FONT_LABEL, FONT_STAT_SECTION, scaleFontSize, buildExerciseLibrary,
  type BodyPlan, type BodyPlanTask, type BodyCheckin, type DayOverride, type Theme, type BodySlice, type ExerciseDef} from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import { X, ChevronRight, CheckCircle2, Wind, Activity } from 'lucide-react-native';
import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { View, Text, TouchableOpacity, Alert, Animated } from 'react-native';

import { PrimaryButton, OutlineButton, Card } from '../../../components/UI';

import BodyCheckinInline from './BodyCheckinInline';
import CheckinSuccessCard from './CheckinSuccessCard';
import ExerciseProgressBanner from './components/ExerciseProgressBanner';
import { useBodyFlowState } from './hooks/useBodyFlowState';

type FlowStep = 'practice' | 'breathing' | 'checkin' | 'success';

interface FlowProps {
  TH: Theme;
  T: (key: string) => string;
  onExit: () => void;
  todayPlan?: BodyPlan;
  trainingPlanTask?: { planId: string; planName: string; task: BodyPlanTask } | null;
  todayOverride?: DayOverride;
  todayExercises?: ExerciseDef[];
  store: Record<string, unknown> & Pick<BodySlice, 'upsertBodyCheckin'>;
  onGoToSport?: (sportKey: string, exercises?: ExerciseDef[]) => void;
  onGoToBreathing?: () => void;
}

const TRANSITION_DURATION = 300;

function getFlowSteps(current: FlowStep, T: (key: string) => string, practiceDone: boolean, breathingDone: boolean, awarenessDone: boolean): { key: string; label: string; status: 'pending' | 'completed' | 'skipped' }[] {
  const currentIdx = current === 'success' ? 3 : ['practice', 'breathing', 'checkin'].indexOf(current);
  return [
    { key: 'practice', label: T('bodyFlowPractice'), status: practiceDone ? 'completed' : (currentIdx > 0 ? 'skipped' : 'pending') },
    { key: 'breathing', label: T('bodyFlowBreathing'), status: breathingDone ? 'completed' : (currentIdx > 1 ? 'skipped' : (currentIdx === 1 ? 'pending' : 'skipped')) },
    { key: 'checkin', label: T('bodyFlowAwareness'), status: awarenessDone ? 'completed' : (currentIdx > 2 ? 'skipped' : (currentIdx === 2 ? 'pending' : 'skipped')) },
  ];
}

function ExercisePicker({ TH, T, onSelect }: { TH: Theme; T: (key: string) => string; onSelect: (key: string) => void }) {
  const groups = useMemo(() => {
    // 按 SPORT_GROUPS 分组展示具体运动（而非训练类别）
    return SPORT_GROUPS.map(g => ({
      label: T(g.group) !== g.group ? T(g.group) : g.group,
      items: g.items.map(s => ({ key: s.key, label: s.key, icon: s.icon })),
    })).filter(g => g.items.length > 0);
  }, [T]);

  return (
    <View style={{ marginTop: 12 }}>
      {groups.map(group => (
        <View key={group.label} style={{ marginBottom: 12 }}>
          <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.sub, marginBottom: 8 }}>{group.label}</Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
            {group.items.map(item => (
              <TouchableOpacity key={item.key} onPress={() => onSelect(item.key)}
                style={{
                  flexDirection: 'row', alignItems: 'center', gap: 6,
                  paddingHorizontal: 14, paddingVertical: 10, borderRadius: 12,
                  borderWidth: 1, borderColor: TH.border, backgroundColor: TH.card,
                }}>
                <Text style={{ fontSize: FONT_LABEL() }}>{item.icon}</Text>
                <Text style={{ fontSize: FONT_BODY(), color: TH.text }}>{item.label}</Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>
      ))}
    </View>
  );
}

export default function BodyFlow({ TH, T, onExit, todayPlan, trainingPlanTask, todayOverride, todayExercises, store, onGoToSport, onGoToBreathing }: FlowProps) {
  const {
    flowState,
    setStep,
    markPracticeDone,
    markBreathingDone,
    saveAwareness,
    setSelectedSport,
    resetFlow,
  } = useBodyFlowState();

  // 单一状态源：优先使用 store，否则本地
  const step = flowState?.step ?? 'practice';
  const getInitialSportKey = () => {
    const raw = todayPlan?.sportKey || todayPlan?.part || trainingPlanTask?.task.sportKey;
    if (!raw) return undefined;
    // 中文描述 → 标准 key（如"胸+三头" → "chest_triceps"）
    return PART_STRING_TO_KEY[raw] ?? raw;
  };
  const [selectedSportKey, setSelectedSportKey] = useState<string | undefined>(getInitialSportKey);

  // Animation for step transitions
  const fadeAnim = useRef(new Animated.Value(1)).current;
  const transitioningRef = useRef(false);

  const transitionTo = useCallback((newStep: FlowStep) => {
    if (transitioningRef.current) return;
    transitioningRef.current = true;
    Animated.timing(fadeAnim, {
      toValue: 0,
      duration: TRANSITION_DURATION / 2,
      useNativeDriver: true,
    }).start(() => {
      setStep(newStep);
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: TRANSITION_DURATION / 2,
        useNativeDriver: true,
      }).start(() => {
        transitioningRef.current = false;
      });
    });
  }, [fadeAnim, setStep]);

  const startTimeRef = useRef(Date.now());
  const practiceStartRef = useRef(0);
  const breathingStartRef = useRef(0);
  // 单一状态源：所有状态从 flowState 读取，无局部 useState 副本
  const practiceCompleted = flowState?.practiceCompleted ?? false;
  const breathingCompleted = flowState?.breathingCompleted ?? false;
  const breathingDurationMs = flowState?.breathingDurationMs ?? 0;
  const awarenessData = flowState?.awarenessData ?? null;
  const successStartTimeRef = useRef(0);

  // 单一状态源：flowState，无局部状态同步
  // （移除旧的 useEffect 同步，flowState 直接驱动渲染）

  const handleExitPress = useCallback(() => {
    Alert.alert(
      T('bodyFlowExitConfirm'),
      undefined,
      [
        { text: T('bodyCancel'), style: 'cancel' },
        { text: T('bodyFlowSkip'), style: 'destructive', onPress: () => { onExit(); } },
      ]
    );
  }, [T, onExit]);

  const handleBackPress = useCallback(() => {
    onExit();
  }, [onExit]);

  const navigateToSport = useCallback((sportKey: string) => {
    if (startTimeRef.current === 0) startTimeRef.current = Date.now();
    practiceStartRef.current = Date.now();
    setSelectedSportKey(sportKey);
    setSelectedSport(sportKey);
    // 通知 BodyScreen 跳转到 SportPage
    onGoToSport?.(sportKey, todayExercises && todayExercises.length > 1 ? todayExercises : undefined);
  }, [onGoToSport, setSelectedSport, todayExercises]);

  // 进入流程时重置计时 ref，避免旧值残留
  useEffect(() => {
    if (step === 'practice') {
      practiceStartRef.current = 0;
      breathingStartRef.current = 0;
    }
  }, [step]);

  const navigateToBreathing = useCallback(() => {
    breathingStartRef.current = Date.now();
    onGoToBreathing?.();
  }, [onGoToBreathing]);

  const exerciseLibrary = useMemo(() => buildExerciseLibrary(), []);

  const sportInfo = useMemo(() => {
    if (!selectedSportKey) return null;
    return ALL_SPORTS.find(s => s.key === selectedSportKey || s.keyEn === selectedSportKey)
      ?? EXERCISE_CATEGORIES.find(c => c.key === selectedSportKey);
  }, [selectedSportKey]);

  // ── Helper: resolve current plan info（感知 override） ──
  const currentPlan = useMemo(() => {
    // override 修正：swap 时使用新 sportKey，skip 时视为休息
    const overrideSportKey = todayOverride?.type === 'swap' ? todayOverride.swapSportKey : undefined;
    const effectiveSportKey = overrideSportKey || trainingPlanTask?.task.sportKey || todayPlan?.sportKey || todayPlan?.part;

    if (todayOverride?.type === 'skip') {
      return { name: todayOverride.note || T('bodyOverrideSkip'), sportKey: 'rest', exercises: [], isRest: true };
    }
    if (trainingPlanTask) {
      let exercises = todayOverride?.type === 'adjust' ? undefined : (trainingPlanTask.task.exercises ?? []);
      // 回退: 如果 task 没有 exercises 但有 sportKey, 从动作库查找
      if (!exercises || exercises.length === 0) {
        const rawKey = effectiveSportKey ?? trainingPlanTask.task.sportKey;
        const sk = PART_STRING_TO_KEY[rawKey] || rawKey;
        if (sk && sk !== 'rest') {
          const library = buildExerciseLibrary();
          exercises = library.filter(ex => ex.category === sk);
        }
      }
      return {
        name: trainingPlanTask.planName,
        sportKey: effectiveSportKey ?? trainingPlanTask.task.sportKey,
        exercises,
        isRest: effectiveSportKey === 'rest',
      };
    }
    if (todayPlan?.part && todayPlan.part !== 'rest') {
      let exercises: BodyPlanTask['exercises'] = [];
      const rawKey = PART_STRING_TO_KEY[effectiveSportKey ?? todayPlan.part] || effectiveSportKey || todayPlan.part;
      if (rawKey && rawKey !== 'rest') {
        const library = buildExerciseLibrary();
        exercises = library.filter(ex => ex.category === rawKey);
      }
      return {
        name: todayPlan.part,
        sportKey: effectiveSportKey ?? todayPlan.part,
        exercises,
        isRest: false,
      };
    }
    return null;
  }, [trainingPlanTask, todayPlan]);

  const handleSaveCheckin = useCallback((data: Omit<BodyCheckin, 'id' | 'updatedAt' | 'deleted' | 'synced'>) => {
    store.upsertBodyCheckin(data);
    const checkinData: BodyCheckin = { ...data, id: '', updatedAt: Date.now(), deleted: false, synced: false };
    saveAwareness(checkinData);
    successStartTimeRef.current = Date.now();
    transitionTo('success');
  }, [store, saveAwareness, transitionTo]);

  const handleSkipCheckin = useCallback(() => {
    saveAwareness(null);
    successStartTimeRef.current = Date.now();
    transitionTo('success');
  }, [saveAwareness, transitionTo]);

  // ── Render steps ──
  const renderStep = () => {
    if (step === 'success') {
      const totalMs = successStartTimeRef.current > 0
        ? successStartTimeRef.current - startTimeRef.current
        : 0;
      return (
        <CheckinSuccessCard
          TH={TH} T={T}
          awarenessData={awarenessData}
          practiceCompleted={practiceCompleted}
          breathingCompleted={breathingCompleted}
          breathingDurationMs={breathingDurationMs}
          totalMs={totalMs}
          onFinish={() => { startTimeRef.current = 0; practiceStartRef.current = 0; onExit(); }}
        />
      );
    }

    if (step === 'practice') {
      const isTodayRestDay = todayPlan?.part === 'rest' || trainingPlanTask?.task.sportKey === 'rest';
      const hasTodayPlan = currentPlan !== null && !currentPlan.isRest;
      const activeSportKey = currentPlan?.sportKey ?? '';
      const planExercises = currentPlan?.exercises ?? [];

      return (
        <View>
          <ExerciseProgressBanner steps={getFlowSteps("practice", T, practiceCompleted, breathingCompleted, awarenessData != null)} TH={TH} T={T} readOnly />
          <Card>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, marginBottom: 12 }}>
              <Activity size={22} color="#f59e0b" />
              <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{T('bodyFlowPractice')}</Text>
            </View>
            {practiceCompleted ? (
              <View>
                {/* 头部行：✅ 已完成 + 标题 */}
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 12 }}>
                  <CheckCircle2 size={24} color="#10b981" />
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#10b981' }}>
                    {T('bodyFlowPracticeDone')}
                  </Text>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }} numberOfLines={1}>
                    {flowState?.practiceTitle ?? currentPlan?.name ?? ''}
                  </Text>
                </View>
                {/* 统计横幅 */}
                {(flowState?.totalDurationSec || flowState?.totalCalories) && (
                  <View style={{ flexDirection: 'row', backgroundColor: `${TH.border}30`, borderRadius: 12, padding: 12, marginTop: 8, gap: 8 }}>
                    {flowState?.totalDurationSec ? (
                      <View style={{ flex: 1, alignItems: 'center' }}>
                        <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>
                          {Math.floor(flowState.totalDurationSec / 60)}:{String(flowState.totalDurationSec % 60).padStart(2, '0')}
                        </Text>
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyFlowTotalTime')}</Text>
                      </View>
                    ) : null}
                    <View style={{ flex: 1, alignItems: 'center' }}>
                      <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>{flowState?.comboExercises?.length ?? flowState?.practiceExercises?.length ?? planExercises.length}</Text>
                      <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('bodyPlanUnitExercise')}</Text>
                    </View>
                    {flowState?.totalCalories ? (
                      <View style={{ flex: 1, alignItems: 'center' }}>
                        <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: TH.text }}>{flowState.totalCalories}</Text>
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>kcal</Text>
                      </View>
                    ) : null}
                  </View>
                )}
                {/* 动作列表 — 优先显示实际完成的练习 */}
                {flowState?.comboExercises && flowState.comboExercises.length > 0 ? (
                  <View style={{ backgroundColor: `${TH.border}30`, borderRadius: 12, padding: 12, marginTop: 8 }}>
                    {flowState.comboExercises!.map((ex, i) => (
                      <View key={i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4, borderBottomWidth: i < flowState.comboExercises!.length - 1 ? 1 : 0, borderBottomColor: `${TH.border}50` }}>
                        <Text style={{ fontSize: 20 }}>{ex.icon}</Text>
                        <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }} numberOfLines={1}>{ex.nameZh || ex.sportKey}</Text>
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>
                          {Math.floor(ex.durationSec / 60)}:{(ex.durationSec % 60).toString().padStart(2, '0')}
                        </Text>
                        <Text style={{ fontSize: FONT_SMALL(), color: '#10b981' }}>✓ {T('bodyCompleted')}</Text>
                      </View>
                    ))}
                  </View>
                ) : flowState?.practiceExercises && flowState.practiceExercises.length > 0 ? (
                  <View style={{ backgroundColor: `${TH.border}30`, borderRadius: 12, padding: 12, marginTop: 8 }}>
                    {flowState.practiceExercises!.map((ex, i) => (
                      <View key={i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4, borderBottomWidth: i < flowState.practiceExercises!.length - 1 ? 1 : 0, borderBottomColor: `${TH.border}50` }}>
                        <Text style={{ fontSize: 20 }}>{ex.icon}</Text>
                        <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }} numberOfLines={1}>{ex.nameZh || ex.sportKey}</Text>
                        {ex.reps > 0 && <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{ex.reps} reps</Text>}
                        <Text style={{ fontSize: FONT_SMALL(), color: '#10b981' }}>✓ {T('bodyCompleted')}</Text>
                      </View>
                    ))}
                  </View>
                ) : planExercises.length > 0 ? (
                  <View style={{ backgroundColor: `${TH.border}30`, borderRadius: 12, padding: 12, marginTop: 8 }}>
                    {planExercises.map((ex, i) => (
                      <View key={ex.id || i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4, borderBottomWidth: i < planExercises.length - 1 ? 1 : 0, borderBottomColor: `${TH.border}50` }}>
                        <Text style={{ fontSize: 20 }}>{ex.icon}</Text>
                        <Text style={{ fontSize: FONT_BODY(), color: TH.text, flex: 1 }} numberOfLines={1}>{ex.nameZh || exerciseLibrary.find(lib => lib.category === ex.category)?.nameZh || (() => { const cat = EXERCISE_CATEGORIES.find(c => c.key === ex.category); return cat ? T(cat.i18nKey) : ex.category; })()}</Text>
                        {ex.defaultSets && ex.defaultReps && (
                          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{ex.defaultSets}×{ex.defaultReps}</Text>
                        )}
                        {ex.defaultWeight && (
                          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{ex.defaultWeight}kg</Text>
                        )}
                        <Text style={{ fontSize: FONT_SMALL(), color: '#10b981' }}>✓ {T('bodyCompleted')}</Text>
                      </View>
                    ))}
                  </View>
                ) : null}
              </View>
            ) : hasTodayPlan ? (
              <>
                {trainingPlanTask && (
                  <View style={{ marginBottom: 16 }}>
                    <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 8 }}>{currentPlan?.name}</Text>
                    {planExercises.length > 0 ? (
                      planExercises.map((ex, i) => (
                          <View key={ex.id || i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 6, paddingHorizontal: 10, borderRadius: 8, backgroundColor: `${TH.border}40`, marginBottom: 4 }}>
                            <Text style={{ fontSize: FONT_SMALL(), color: TH.text, flex: 1 }}>
                              {ex.icon} {ex.nameZh}
                              {ex.defaultSets && ex.defaultReps ? `  ${ex.defaultSets}×${ex.defaultReps}` : ''}
                              {ex.defaultWeight ? `  ${ex.defaultWeight}kg` : ''}
                              {ex.defaultDurationSec ? `  ${Math.round(ex.defaultDurationSec / 60)}min` : ''}
                            </Text>
                          </View>
                        ))
                    ) : (
                      <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>{T('bodyPlanNoExercises')}</Text>
                    )}
                  </View>
                )}
                {!trainingPlanTask && planExercises.length > 0 && (
                  <View style={{ marginBottom: 16 }}>
                    <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 8 }}>{currentPlan?.sportKey ? T(`bodyPart${currentPlan.sportKey.charAt(0).toUpperCase() + currentPlan.sportKey.slice(1)}` as never) || currentPlan.name : currentPlan?.name}</Text>
                    {planExercises.map((ex, i) => (
                      <View key={ex.id || i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 6, paddingHorizontal: 10, borderRadius: 8, backgroundColor: `${TH.border}40`, marginBottom: 4 }}>
                        <Text style={{ fontSize: FONT_SMALL(), color: TH.text, flex: 1 }}>
                          {ex.icon} {ex.nameZh}
                          {ex.defaultSets && ex.defaultReps ? `  ${ex.defaultSets}×${ex.defaultReps}` : ''}
                          {ex.defaultDurationSec ? `  ${Math.round(ex.defaultDurationSec / 60)}min` : ''}
                        </Text>
                      </View>
                    ))}
                  </View>
                )}
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, marginBottom: 16 }}>
                  <Text style={{ fontSize: FONT_STAT_SECTION() }}>{sportInfo && 'icon' in sportInfo ? (sportInfo as { icon: string }).icon : '🏋️'}</Text>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
                    {sportInfo && 'i18nKey' in sportInfo ? T((sportInfo as { i18nKey: string }).i18nKey) : (() => { const mapped = PART_STRING_TO_KEY[todayPlan?.part ?? ''] ?? todayPlan?.part; const cat = EXERCISE_CATEGORIES.find(c => c.key === mapped); return cat ? T(cat.i18nKey) : todayPlan?.part ?? ''; })()}
                  </Text>
                </View>
                <PrimaryButton
                  label={T('bodyFlowStartSport')}
                  onPress={() => {
                    const key = selectedSportKey || activeSportKey;
                    if (key) {
                      navigateToSport(key);
                    } else {
                      Alert.alert(T('bodyFlowChooseExercise'));
                    }
                  }}
                  color="#f59e0b"
                  icon={<Activity size={18} color="#fff" />}
                />
                <View style={{ height: 8 }} />
                <OutlineButton label={T('bodyFlowChooseExercise')} onPress={() => setSelectedSportKey(undefined)} color="#f59e0b" />
              </>
            ) : (
              <>
                {isTodayRestDay && (
                  <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center', marginBottom: 12 }}>{T('bodyTodayPlanRest')}</Text>
                )}
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 8 }}>{T('bodyFlowChooseExercise')}</Text>
                <ExercisePicker TH={TH} T={T} onSelect={(key) => { setSelectedSportKey(key); navigateToSport(key); }} />
              </>
            )}
          </Card>
          <View style={{ flexDirection: 'row', gap: 10 }}>
            {practiceCompleted ? (
              <PrimaryButton label={T('bodyFlowBreathing')} onPress={() => transitionTo('breathing')} color="#10b981" icon={<ChevronRight size={18} color="#fff" />} style={{ flex: 1 }} />
            ) : (
              <OutlineButton label={T('bodyFlowSkip')} onPress={() => transitionTo('breathing')} style={{ flex: 1 }} />
            )}
          </View>
        </View>
      );
    }

    if (step === 'breathing') {
      return (
        <View>
          <ExerciseProgressBanner steps={getFlowSteps("breathing", T, practiceCompleted, breathingCompleted, awarenessData != null)} TH={TH} T={T} readOnly />
          <View style={{ borderRadius: 20, overflow: 'hidden', marginBottom: 16 }}>
            <LinearGradient colors={['#06b6d4', '#0891b2']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={{ padding: 24, alignItems: 'center' }}>
              <Wind size={40} color="#fff" />
              <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: '#fff', marginTop: 12, marginBottom: 4 }}>{T('bodyFlowBreathing')}</Text>
              <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.8)' }}>
                {breathingCompleted
                  ? `${T('bodyFlowBreathingTime')}: ${Math.floor(breathingDurationMs / 60000)}${T('bodyMin')}`
                  : T('bodyFlowBreathingHint')}
              </Text>
            </LinearGradient>
          </View>
          {breathingCompleted ? (
            <Card>
              <View style={{ alignItems: 'center', paddingVertical: 8 }}>
                <CheckCircle2 size={40} color="#10b981" />
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#10b981', marginTop: 8 }}>{T('bodyFlowBreathingDone')}</Text>
              </View>
            </Card>
          ) : (
            <Card>
              <Text style={{ fontSize: FONT_BODY(), color: TH.text, textAlign: 'center', lineHeight: 22 }}>{T('bodyFlowBreathingDesc')}</Text>
            </Card>
          )}
          <View style={{ flexDirection: 'row', gap: 10 }}>
            {!breathingCompleted ? (
              <>
                <PrimaryButton label={T('bodyFlowStartBreathing')} onPress={navigateToBreathing} color="#06b6d4" icon={<Wind size={18} color="#fff" />} style={{ flex: 1 }} />
                <OutlineButton label={T('bodyFlowSkip')} onPress={() => transitionTo('checkin')} color="#06b6d4" style={{ flex: 1 }} />
              </>
            ) : (
              <PrimaryButton label={T('bodyFlowAwareness')} onPress={() => transitionTo('checkin')} color="#8b5cf6" icon={<ChevronRight size={18} color="#fff" />} style={{ flex: 1 }} />
            )}
          </View>
        </View>
      );
    }

    // step === 'checkin'
    return (
      <View>
        <ExerciseProgressBanner steps={getFlowSteps("checkin", T, practiceCompleted, breathingCompleted, awarenessData != null)} TH={TH} T={T} readOnly />
        <View style={{ borderRadius: 20, overflow: 'hidden', marginBottom: 16 }}>
          <LinearGradient colors={['#8b5cf6', '#7c3aed']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={{ padding: 24, alignItems: 'center' }}>
            <Text style={{ fontSize: scaleFontSize(40), marginBottom: 8 }}>🧠</Text>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: '#fff', marginTop: 4 }}>{T('bodyFlowAwareness')}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.8)', marginTop: 4 }}>{T('bodyFlowAwarenessHint')}</Text>
          </LinearGradient>
        </View>
        <Card style={{ borderWidth: 0 }}>
          <BodyCheckinInline
            TH={TH} T={T} plan={todayPlan}
            durationSec={flowState?.practiceDurationSec}
            onSave={handleSaveCheckin}
            onSkip={handleSkipCheckin}
          />
        </Card>
      </View>
    );
  };

  return (
    <View>
