        </TouchableOpacity>
        <TouchableOpacity onPress={handleExitPress} style={{ paddingVertical: 8, paddingHorizontal: 4 }}>
          <X size={24} color={TH.sub} />
        </TouchableOpacity>
      </View>
      <Animated.View style={{ opacity: fadeAnim }}>
