import { FONT_TITLE, FONT_SUB, FONT_BODY, FONT_SMALL, dateStr } from '@egoless-do/core';
import type { MindReflection , UnifiedPlanItemForm } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useState, useCallback, useMemo } from 'react';
import {
  View, Text, TextInput, TouchableOpacity, Modal, ScrollView, KeyboardAvoidingView, Platform,
} from 'react-native';
import { useShallow } from 'zustand/react/shallow';

import DatePickerModal from '../../../components/DatePickerModal';
import { useTheme, PrimaryButton, OutlineButton } from '../../../components/UI';
import { useAppStore, type MobileStore } from '../../../store/useAppStore';
import { PlanItemForm, validatePlanItemForm } from '../../plan/components/PlanItemForm';

interface CreatePlanFromReflectionModalProps {
  visible: boolean;
  reflection: MindReflection | null;
  onClose: () => void;
  onCreate: (reflectionId: string, form: UnifiedPlanItemForm) => void;
}

export function CreatePlanFromReflectionModal({
  visible,
  reflection,
  onClose,
  onCreate,
}: CreatePlanFromReflectionModalProps) {
  const TH = useTheme();
  const getActivePlan = useAppStore(useShallow((s: MobileStore) => s.getActivePlan));
  const activePlan = useMemo(() => getActivePlan(), [getActivePlan]);

  const [showStartPicker, setShowStartPicker] = useState(false);
  const [showEndPicker, setShowEndPicker] = useState(false);
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const today = dateStr();
  const planStart = activePlan?.startDate ?? today;
  const planEnd = activePlan?.endDate;

  const defaultStart = today >= planStart ? today : planStart;
  const defaultEnd = planEnd ?? (() => {
    const d = new Date();
    d.setDate(d.getDate() + 30);
    return dateStr(d);
  })();

  const [form, setForm] = useState<UnifiedPlanItemForm>(() => {
    const defaultName = reflection
      ? (reflection.content.split('\n').filter(l => l.trim())[0] || reflection.content).slice(0, 10)
      : '';
    return {
      name: defaultName,
      description: reflection?.content ?? '',
      targetMetric: '',
      startDate: defaultStart,
      endDate: defaultEnd,
      priority: 'medium',
    };
  });

  // Reset form when reflection changes
  React.useEffect(() => {
    if (reflection) {
      const firstLine = (reflection.content.split('\n').filter(l => l.trim())[0] || reflection.content).slice(0, 10);
      setForm({
        name: firstLine,
        description: reflection.content,
        targetMetric: '',
        startDate: defaultStart,
        endDate: defaultEnd,
        priority: 'medium',
      });
      setFormErrors({});
    }
  }, [reflection?.id, setForm, setFormErrors, defaultStart, defaultEnd]);

  const handleSubmit = useCallback(() => {
    const errors = validatePlanItemForm(form, { requireTargetMetric: true });
    setFormErrors(errors);
    if (Object.keys(errors).length > 0) return;
    if (reflection) {
      onCreate(reflection.id, { ...form, tags: reflection.tags });
    }
  }, [form, reflection, onCreate]);

  const handleClose = useCallback(() => {
    setFormErrors({});
    onClose();
  }, [onClose]);

  if (!reflection) return null;

  return (
    <Modal visible={visible} transparent animationType="slide">
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} style={{ flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,.7)' }}>
        <View style={{ backgroundColor: TH.cardSolid, borderTopLeftRadius: 24, borderTopRightRadius: 24, paddingHorizontal: 24, paddingTop: 24, paddingBottom: 40, maxHeight: '90%' }}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text }}>创建计划任务</Text>
            <TouchableOpacity onPress={handleClose}>
              <X size={24} color={TH.sub} />
            </TouchableOpacity>
          </View>
          {activePlan && (
            <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.sub, marginBottom: 16 }}>
              关联计划: {activePlan.name}（{activePlan.startDate} ~ {activePlan.endDate}）
            </Text>
          )}
          <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
            <PlanItemForm
              key={reflection?.id}
              initialValues={form}
              showTargetMetric
              showFrequency
              onChange={setForm}
              onDatePress={(field) => field === 'start' ? setShowStartPicker(true) : setShowEndPicker(true)}
              errors={formErrors}
            />

            {/* 任务链接（只读，显示感念标签） */}
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>任务链接</Text>
            <TextInput
              value={reflection.tags.join(', ')}
              editable={false}
              style={{
                borderWidth: 1, borderColor: TH.border, borderRadius: 8, padding: 10, marginBottom: 12,
                color: TH.sub, backgroundColor: TH.card, fontSize: FONT_BODY(),
              }}
            />

            <View style={{ flexDirection: 'row', gap: 10 }}>
              <OutlineButton label="取消" onPress={handleClose} style={{ flex: 1 }} />
              <PrimaryButton label="创建" onPress={handleSubmit} style={{ flex: 1 }} />
            </View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>

      <DatePickerModal
        visible={showStartPicker}
        value={form.startDate}
        onConfirm={(date) => { setForm(f => ({ ...f, startDate: date })); setShowStartPicker(false); }}
        onClose={() => setShowStartPicker(false)}
        minDate={defaultStart}
        maxDate={form.endDate}
      />
      <DatePickerModal
        visible={showEndPicker}
        value={form.endDate}
        onConfirm={(date) => { setForm(f => ({ ...f, endDate: date })); setShowEndPicker(false); }}
        onClose={() => setShowEndPicker(false)}
        minDate={form.startDate}
        maxDate={planEnd}
      />
    </Modal>
  );
}

import { FONT_TITLE, FONT_SUB, FONT_SMALL, FONT_BODY, dateStr } from '@egoless-do/core';
import type { TrailInsightCache, UnifiedPlanItemForm } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import {
  View, Text, TouchableOpacity, Modal, ScrollView, KeyboardAvoidingView, Platform,
} from 'react-native';
import { useShallow } from 'zustand/react/shallow';

import DatePickerModal from '../../../components/DatePickerModal';
import { useTheme, useT, PrimaryButton, OutlineButton } from '../../../components/UI';
import { useAppStore, type MobileStore } from '../../../store/useAppStore';
import { PlanItemForm, validatePlanItemForm } from '../../plan/components/PlanItemForm';

interface CreatePlanFromTrailModalProps {
  visible: boolean;
  insightCache?: TrailInsightCache;
  onCreate: (form: UnifiedPlanItemForm) => void;
  onClose: () => void;
}

export function CreatePlanFromTrailModal({
  visible,
  insightCache,
  onCreate,
  onClose,
}: CreatePlanFromTrailModalProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const getActivePlan = useAppStore(useShallow((s: MobileStore) => s.getActivePlan));
  const activePlan = useMemo(() => getActivePlan(), [getActivePlan]);

  const [selectedSuggestions, setSelectedSuggestions] = useState<number[]>([]);
  const autoFilled = useRef(false);
  const [showStartPicker, setShowStartPicker] = useState(false);
  const [showEndPicker, setShowEndPicker] = useState(false);
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const today = dateStr();
  const planStart = activePlan?.startDate ?? today;
  const planEnd = activePlan?.endDate;

  const defaultStart = today >= planStart ? today : planStart;
  const defaultEnd = planEnd ?? (() => {
    const d = new Date();
    d.setDate(d.getDate() + 30);
    return dateStr(d);
  })();

  const [form, setForm] = useState<UnifiedPlanItemForm>({
    name: '',
    description: '',
    targetMetric: '',
    startDate: defaultStart,
    endDate: defaultEnd,
    priority: 'medium',
  });

  useEffect(() => {
    if (visible) {
      setForm(f => ({ ...f, startDate: defaultStart, endDate: defaultEnd }));
    }
    if (!visible) {
      autoFilled.current = false;
      setFormErrors({});
      setSelectedSuggestions([]);
    }
  }, [visible, defaultStart, defaultEnd]);

  const suggestions = useMemo(() => {
    return insightCache?.suggestions ?? [];
  }, [insightCache]);

  const handleToggleSuggestion = useCallback((idx: number) => {
    setSelectedSuggestions(prev =>
      prev.includes(idx) ? prev.filter(i => i !== idx) : [...prev, idx]
    );
  }, []);

  const handleApplySelected = useCallback(() => {
    if (suggestions.length === 0) return;
    const selected = selectedSuggestions.map(i => suggestions[i]).filter(Boolean);
    if (selected.length === 1) {
      setForm(f => ({ ...f, name: selected[0] }));
    } else if (selected.length > 1) {
      setForm(f => ({ ...f, name: selected[0], description: selected.slice(1).join('\n') }));
    }
  }, [suggestions, selectedSuggestions]);

  const handleSubmit = useCallback(() => {
    const errors = validatePlanItemForm(form, { requireTargetMetric: false });
    setFormErrors(errors);
    if (Object.keys(errors).length > 0) return;
    onCreate(form);
  }, [form, onCreate]);

  const handleClose = useCallback(() => {
    setFormErrors({});
    onClose();
  }, [onClose]);

  return (
    <Modal visible={visible} transparent animationType="slide">
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} style={{ flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,.7)' }}>
        <View style={{ backgroundColor: TH.cardSolid, borderTopLeftRadius: 24, borderTopRightRadius: 24, paddingHorizontal: 24, paddingTop: 24, paddingBottom: 40, maxHeight: '90%' }}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
            <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text }}>{T('trailPlanTitle')}</Text>
            <TouchableOpacity onPress={handleClose}>
              <X size={24} color={TH.sub} />
            </TouchableOpacity>
          </View>

          {activePlan && (
            <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.sub, marginBottom: 16 }}>
              {T('planGoal')}: {activePlan.name}（{activePlan.startDate} ~ {activePlan.endDate}）
            </Text>
          )}

          <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
            {/* AI 建议 */}
            {suggestions.length > 0 && (
              <View style={{ marginBottom: 16 }}>
                <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.sub, marginBottom: 8 }}>
                  💡 {T('trailPlanAISuggestions')}
                </Text>
                {suggestions.map((s, i) => (
                  <TouchableOpacity
                    key={i}
                    style={{
                      padding: 10, borderWidth: 1, borderRadius: 8, marginBottom: 6,
                      borderColor: selectedSuggestions.includes(i) ? P : TH.border,
                      backgroundColor: selectedSuggestions.includes(i) ? `${P}15` : 'transparent',
                    }}
                    onPress={() => handleToggleSuggestion(i)}
                  >
                    <Text style={{ fontSize: FONT_SMALL(), lineHeight: 18, color: TH.text }}>
                      {selectedSuggestions.includes(i) ? '✓ ' : '○ '}{s}
                    </Text>
                  </TouchableOpacity>
                ))}
                {selectedSuggestions.length > 0 && (
                  <TouchableOpacity
                    style={{ paddingVertical: 8, paddingHorizontal: 16, borderRadius: 8, alignItems: 'center', marginTop: 8, backgroundColor: P }}
                    onPress={handleApplySelected}
                  >
                    <Text style={{ color: '#fff', fontSize: FONT_SMALL(), fontWeight: '600' }}>{T('trailPlanApplySelected')}</Text>
                  </TouchableOpacity>
                )}
              </View>
            )}

            {/* 表单 */}
            <PlanItemForm
              initialValues={form}
              showTargetMetric
              showFrequency
              onChange={setForm}
              onDatePress={(field) => field === 'start' ? setShowStartPicker(true) : setShowEndPicker(true)}
              errors={formErrors}
            />

            <View style={{ flexDirection: 'row', gap: 10, marginTop: 4 }}>
              <OutlineButton label={T('commonCancel')} onPress={handleClose} style={{ flex: 1 }} />
              <PrimaryButton label={T('commonConfirm')} onPress={handleSubmit} style={{ flex: 1 }} />
            </View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>

      <DatePickerModal
        visible={showStartPicker}
        value={form.startDate}
        onConfirm={(date) => { setForm(f => ({ ...f, startDate: date })); setShowStartPicker(false); }}
        onClose={() => setShowStartPicker(false)}
        minDate={defaultStart}
        maxDate={form.endDate}
      />
      <DatePickerModal
        visible={showEndPicker}
        value={form.endDate}
        onConfirm={(date) => { setForm(f => ({ ...f, endDate: date })); setShowEndPicker(false); }}
        onClose={() => setShowEndPicker(false)}
        minDate={form.startDate}
        maxDate={planEnd}
      />
    </Modal>
  );
}

import { FONT_SMALL, FONT_BODY, FONT_TITLE, FONT_TINY , getMoodIcon } from '@egoless-do/core';
import type { Mood } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useState, useCallback, useRef } from 'react';
import {
  View, Text, TextInput, TouchableOpacity, Modal, ScrollView, StyleSheet, Alert, KeyboardAvoidingView, Platform,
} from 'react-native';

import { Events } from '../../../analytics/events';
import { track } from '../../../analytics/track';
import { useTheme, useT } from '../../../components/UI';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


interface CreateReflectionModalProps {
  visible: boolean;
  trailId?: string;
  onClose: () => void;
}

const MOOD_OPTIONS: { mood: Mood; label: string }[] = [
  { mood: 'happy', label: '开心' },
  { mood: 'calm', label: '平静' },
  { mood: 'neutral', label: '平常' },
  { mood: 'sad', label: '难过' },
  { mood: 'anxious', label: '焦虑' },
  { mood: 'grateful', label: '感恩' },
];

export function CreateReflectionModal({ visible, trailId, onClose }: CreateReflectionModalProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { addReflection, addReflectionToTrail } = useShallowStore(s => ({
    addReflection: s.addReflection,
    addReflectionToTrail: s.addReflectionToTrail,
  }));

  const [content, setContent] = useState('');
  const [tagInput, setTagInput] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [selectedMood, setSelectedMood] = useState<Mood | undefined>();
  const savingRef = useRef(false);

  const handleAddTag = useCallback(() => {
    const tag = tagInput.trim();
    if (tag && !tags.includes(tag)) {
      setTags(prev => [...prev, tag.startsWith('#') ? tag : `#${tag}`]);
      setTagInput('');
    }
  }, [tagInput, tags]);

  const handleRemoveTag = useCallback((tag: string) => {
    setTags(prev => prev.filter(t => t !== tag));
  }, []);

  const handleSave = useCallback(() => {
    if (!content.trim() || savingRef.current) return;
    savingRef.current = true;

    // 创建感念
    const newR = addReflection({
      content: content.trim(),
      tags,
      mood: selectedMood ?? '',
    });

    // PostHog: 感念创建（不含 content/mood 原文）
    track(Events.REFLECTION_CREATED, {
      word_count_bucket: content.length < 50 ? 'short' : content.length < 200 ? 'medium' : 'long',
      has_tags: tags.length > 0,
      has_mood: !!selectedMood,
      has_link: !!trailId,
    });

    // 关联到思维脉络
    if (newR && trailId) {
      addReflectionToTrail(trailId, newR.id);
    }

    // 重置表单
    setContent('');
    setTags([]);
    setSelectedMood(undefined);
    setTagInput('');
    savingRef.current = false;
    onClose();
  }, [content, tags, selectedMood, trailId, addReflection, addReflectionToTrail, onClose]);

  const handleClose = useCallback(() => {
    if (content.trim()) {
      Alert.alert(
        '放弃草稿',
        '当前内容未保存，确定要关闭吗？',
        [
          { text: '继续编辑', style: 'cancel' },
          {
            text: '放弃',
            style: 'destructive',
            onPress: () => {
              setContent('');
              setTags([]);
              setSelectedMood(undefined);
              setTagInput('');
              onClose();
            },
          },
        ]
      );
    } else {
      onClose();
    }
  }, [content, onClose]);

  const charCount = content.length;

  return (
    <Modal visible={visible} transparent animationType="fade">
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        <View style={styles.overlay}>
          <View style={[styles.modal, { backgroundColor: TH.cardSolid }]}>
            <View style={styles.header}>
              <Text style={[styles.title, { color: TH.text }]}>新建感念</Text>
              <TouchableOpacity onPress={handleClose}>
                <X size={24} color={TH.sub} />
              </TouchableOpacity>
            </View>

            <ScrollView style={styles.scrollContent} showsVerticalScrollIndicator={false}>
              {/* 内容输入 */}
              <View style={styles.contentWrapper}>
                <TextInput
                  value={content}
                  onChangeText={setContent}
                  placeholder="写下你的感念..."
                  placeholderTextColor={TH.sub}
                  multiline
                  style={[styles.contentInput, { color: TH.text, borderColor: TH.border }]}
                  textAlignVertical="top"
                  autoFocus
                />
                <Text style={[styles.charCount, { color: TH.sub }]}>已写 {charCount} 字</Text>
              </View>

              {/* 标签输入 */}
              <View style={styles.tagSection}>
                <TextInput
                  value={tagInput}
                  onChangeText={setTagInput}
                  placeholder="输入标签，回车添加"
                  placeholderTextColor={TH.sub}
                  style={[styles.tagInput, { color: TH.text, borderColor: TH.border }]}
                  onSubmitEditing={handleAddTag}
                />
                {tags.length > 0 && (
                  <View style={styles.tagsRow}>
                    {tags.map(tag => (
                      <TouchableOpacity
                        key={tag}
                        onPress={() => handleRemoveTag(tag)}
                        style={[styles.tagPill, { backgroundColor: P + '15' }]}
                      >
                        <Text style={[styles.tagPillText, { color: P }]}>{tag} ×</Text>
                      </TouchableOpacity>
                    ))}
                  </View>
                )}
              </View>

              {/* 心情选择 */}
              <View style={styles.moodSection}>
                <Text style={[styles.moodLabel, { color: TH.sub }]}>心情</Text>
                <View style={styles.moodRow}>
                  {MOOD_OPTIONS.map(({ mood, label }) => (
                    <TouchableOpacity
                      key={mood}
                      onPress={() => setSelectedMood(selectedMood === mood ? undefined : mood)}
                      style={[
                        styles.moodButton,
                        selectedMood === mood && { backgroundColor: `${P}30` },
                      ]}
                    >
                      <Text style={styles.moodEmoji}>{getMoodIcon(mood)}</Text>
                      <Text style={[styles.moodText, { color: selectedMood === mood ? P : TH.sub }]}>
                        {label}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </View>
            </ScrollView>

            {/* 操作按钮 */}
            <View style={styles.actions}>
              <TouchableOpacity
                onPress={handleClose}
                style={[styles.actionButton, { borderColor: TH.border }]}
              >
                <Text style={{ color: TH.sub }}>{T('commonCancel')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={handleSave}
                style={[styles.actionButton, { backgroundColor: P }]}
                disabled={!content.trim()}
              >
                <Text style={{ color: '#fff', fontWeight: '600' }}>保存感念</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

