const log = createLogger('Reflections');

interface PlanItem {
  id: string;
  planId: string;
  name: string;
}

interface Props {
  reflection: MindReflection;
  linkedPlanItem?: PlanItem | null;
  searchQuery?: string;
  onPress: (id: string) => void;
  onLongPress: (id: string) => void;
  onEdit?: (id: string) => void;
  onTogglePin?: (id: string) => void;
  onNavigateToPlan?: (planId: string) => void;
  index?: number;
}

function ReflectionCardComponent({
  reflection: r,
  linkedPlanItem,
  searchQuery,
  onPress,
  onLongPress,
  onNavigateToPlan,
  index = 0,
}: Props) {
  const TH = useTheme();
  const P = TH.primary;
  const language = useAppStore(useShallow((s: MobileStore) => s.language));
  const [expanded, setExpanded] = useState(false);

  const displayContent = useMemo(() => {
    if (expanded || r.content.length <= 100) return r.content;
    return r.content.slice(0, 100) + '...';
  }, [r.content, expanded]);

  const colors = useMemo<[string, string]>(() => {
    const c = typeof r.colors === 'string' ? (() => { try { return JSON.parse(r.colors) as unknown as [string, string] | null; } catch { return null; } })() : r.colors;
    return [c?.[0] || MIND_COLORS_EXTENDED[0][0], c?.[1] || MIND_COLORS_EXTENDED[0][1]];
  }, [r.colors]);

  const handlePress = useCallback(() => {
    if (r.content.length > 100 && !expanded) {
      setExpanded(true);
    } else {
      onPress(r.id);
    }
  }, [r.id, r.content.length, expanded, onPress]);

  const handleLongPress = useCallback(() => {
    onLongPress(r.id);
  }, [r.id, onLongPress]);

  const handleLinkPress = useCallback(() => {
    if (r.link) Linking.openURL(r.link).catch((e) => log.error(e));
  }, [r.link]);

  const handlePlanPress = useCallback(() => {
    if (linkedPlanItem && onNavigateToPlan) {
      onNavigateToPlan(linkedPlanItem.planId);
    }
  }, [linkedPlanItem, onNavigateToPlan]);

  const content = (
    <LinearGradient
      colors={colors}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.gradient}
    >
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.timeText}>
          {formatTime(new Date(r.timestamp ?? 0), language, { hour: '2-digit', minute: '2-digit' })}
        </Text>
        <View style={styles.badges}>
          {linkedPlanItem && (
            <TouchableOpacity
              onPress={handlePlanPress}
              style={[styles.badge, { backgroundColor: 'rgba(255,255,255,.2)' }]}
            >
              <ExternalLink size={10} color="#fff" />
              <Text style={styles.badgeText}>{linkedPlanItem.name.slice(0, 6)}</Text>
            </TouchableOpacity>
          )}
        </View>
      </View>

      {/* Content */}
      {searchQuery?.trim() ? (
        <Text style={styles.contentText}>
          {highlightSearchMatch(displayContent, searchQuery).map((seg, i) =>
            seg.highlight ? (
              <Text key={i} style={styles.highlight}>{seg.text}</Text>
            ) : (
              <Text key={i}>{seg.text}</Text>
            )
          )}
        </Text>
      ) : (
        <Text style={styles.contentText}>{displayContent}</Text>
      )}

      {/* Link */}
      {r.link && (
        <TouchableOpacity onPress={handleLinkPress} style={styles.linkContainer}>
          <Link size={12} color="rgba(255,255,255,.7)" />
          <Text style={styles.linkText} numberOfLines={1}>{r.link}</Text>
        </TouchableOpacity>
      )}

      {/* Tags */}
      {(r.tags.length > 0 || r.mood) && (
        <View style={styles.tagsContainer}>
          {r.tags.map((tag) => {
            const category = REFLECTION_CATEGORIES.find((c) => `#${c.label}` === tag);
            return (
              <View key={tag} style={styles.tagPill}>
                <Text style={styles.tagText}>
                  {category ? `${category.icon} ` : ''}{tag}
                </Text>
              </View>
            );
          })}
          {r.mood && (
            <View style={styles.moodPill}>
              <Text style={styles.moodText}>{r.mood}</Text>
            </View>
          )}
        </View>
      )}
    </LinearGradient>
  );

  return (
    <View style={[styles.container, { marginBottom: 10 }]}>
      <View style={[styles.card, { borderColor: TH.border }]}>
        <TouchableOpacity
          onPress={handlePress}
          onLongPress={handleLongPress}
          activeOpacity={0.85}
        >
          {content}
        </TouchableOpacity>
      </View>
    </View>
  );
}

