import { FONT_BODY, FONT_SMALL, FONT_SUB } from '@egoless-do/core';
import { X, BarChart3 } from 'lucide-react-native';
import React from 'react';
import { View, Text, ScrollView, TouchableOpacity, TextInput } from 'react-native';

import { useTheme, useT } from '../../../components/UI';


interface FilterItem {
  key: string;
  value?: string;
  label: string;
}

interface Props {
  searchInput: string;
  onSearchChange: (text: string) => void;
  onSearchClear: () => void;
  onFilterPress: () => void;
  onStatsPress: () => void;
  showFilterDrawer: boolean;
  hasActiveFilters: boolean;
  activeFilters: FilterItem[];
  onRemoveFilter: (key: string, value?: string) => void;
  onClearAllFilters: () => void;
}

export default function SearchFilterBar({
  searchInput, onSearchChange, onSearchClear,
  onFilterPress, onStatsPress, showFilterDrawer,
  hasActiveFilters, activeFilters, onRemoveFilter, onClearAllFilters,
}: Props) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;

  return (
    <>
      {/* Search + toggle row */}
      <View style={{ flexDirection: 'row', gap: 8, marginBottom: 16 }}>
        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', gap: 6, backgroundColor: TH.card, borderRadius: 12, paddingHorizontal: 12, paddingVertical: 10 }}>
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>🔍</Text>
          <TextInput
            value={searchInput}
            onChangeText={onSearchChange}
            placeholder="搜索感念..."
            placeholderTextColor={TH.sub}
            style={{ flex: 1, color: TH.text, fontSize: FONT_BODY(), padding: 0 }}
          />
          {searchInput.length > 0 && (
            <TouchableOpacity onPress={onSearchClear}>
              <X size={16} color={TH.sub} />
            </TouchableOpacity>
          )}
        </View>
        <TouchableOpacity
          onPress={onFilterPress}
          style={{ paddingHorizontal: 14, borderRadius: 10, backgroundColor: showFilterDrawer ? `${P}20` : TH.card, justifyContent: 'center' }}
        >
          <Text style={{ color: showFilterDrawer ? P : TH.sub, fontSize: FONT_SMALL(), fontWeight: '600' }}>筛选</Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={onStatsPress}
          style={{ paddingHorizontal: 14, borderRadius: 10, backgroundColor: TH.card, justifyContent: 'center' }}
        >
          <BarChart3 size={18} color={TH.sub} />
        </TouchableOpacity>
      </View>

      {/* Active Filters Bar */}
      {hasActiveFilters && (
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }} style={{ marginBottom: 12 }}>
          {activeFilters.map((f, i) => (
            <TouchableOpacity
              key={`${f.key}-${f.value ?? i}`}
              onPress={() => onRemoveFilter(f.key, f.value)}
              style={{ flexDirection: 'row', alignItems: 'center', gap: 4, paddingHorizontal: 10, paddingVertical: 6, borderRadius: 16, backgroundColor: `${P}15`, borderWidth: 1, borderColor: `${P}30` }}
            >
              <Text style={{ color: P, fontSize: FONT_SMALL() }}>{f.label}</Text>
              <X size={12} color={P} />
            </TouchableOpacity>
          ))}
          <TouchableOpacity
            onPress={onClearAllFilters}
            style={{ paddingHorizontal: 10, paddingVertical: 6, borderRadius: 16, backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border }}
          >
            <Text style={{ color: TH.sub, fontSize: FONT_SMALL() }}>清除全部</Text>
          </TouchableOpacity>
        </ScrollView>
      )}
    </>
  );
}

import { MIND_COLORS_EXTENDED, FONT_BODY, FONT_SUB, FONT_SMALL, formatDate , FONT_HERO } from '@egoless-do/core';
import { File as FSFile, Directory as FSDirectory } from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { X, Download, Share2, MessageSquare } from 'lucide-react-native';
import React, { useRef, useState, useMemo } from 'react';
import { View, Text, TouchableOpacity, Alert } from 'react-native';
import ViewShot from 'react-native-view-shot';
import type { ViewShotRef } from 'react-native-view-shot';

import { useTheme, useT } from '../../../components/UI';


interface ShareCardProps {
  visible: boolean;
  onClose: () => void;
  reflection: {
    content: string;
    tags: string[];
    mood?: string;
    timestamp: number;
    colors?: readonly [string, string];
  } | null;
  onTextShare?: () => void;
}

export default function ShareCard({ visible, onClose, reflection, onTextShare }: ShareCardProps) {
  const TH = useTheme();
  const T = useT();
  const viewShotRef = useRef<ViewShotRef>(null);
  const [capturing, setCapturing] = useState(false);

  const parsedColors = useMemo(() => {
    if (!reflection) return null;
    if (typeof reflection.colors === 'string') {
      try {
        return JSON.parse(reflection.colors) as readonly [string, string];
      } catch {
        return null;
      }
    }
    return reflection.colors;
  }, [reflection?.colors]);

  const { bgColor, timeStr } = useMemo(() => {
    if (!reflection) return { bgColor: MIND_COLORS_EXTENDED[0][0], timeStr: '' };
    const bgIdx = MIND_COLORS_EXTENDED.findIndex(c => c[0] === (parsedColors?.[0]));
    const bgColor = MIND_COLORS_EXTENDED[bgIdx >= 0 ? bgIdx : 0]?.[0] ?? MIND_COLORS_EXTENDED[0][0];
    const timeStr = formatDate(new Date(reflection.timestamp ?? 0), 'zh', {
      year: 'numeric', month: 'long', day: 'numeric', weekday: 'short',
    });
    return { bgColor, timeStr };
  }, [reflection, parsedColors]);

  if (!visible || !reflection) return null;

  const doCapture = async (): Promise<string> => {
    if (!viewShotRef.current) throw new Error('view not ready');
    return viewShotRef.current.capture();
  };

  const handleCapture = async () => {
    try {
      setCapturing(true);
      const uri = await doCapture();
      const isAvailable = await Sharing.isAvailableAsync();
      if (isAvailable) {
        await Sharing.shareAsync(uri, { mimeType: 'image/png', dialogTitle: T('shareCardShare') });
      } else {
        Alert.alert(T('shareCardUnavailable'), T('shareCardUnavailableMsg'));
      }
    } catch (e) {
      Alert.alert(T('shareCardError'), T('shareCardErrorMsg'));
    } finally {
      setCapturing(false);
    }
  };

  const handleSave = async () => {
    try {
      setCapturing(true);
      const uri = await doCapture();
      // New API: StorageAccessFramework is unavailable; use directory picker instead.
      // (pickDirectoryAsync returns the base Directory type; infer rather than annotate.)
      let dir: Awaited<ReturnType<typeof FSDirectory.pickDirectoryAsync>>;
      try {
        dir = await FSDirectory.pickDirectoryAsync();
      } catch {
        // User cancelled the picker — silently abort (legacy returned granted:false).
        return;
      }
      const base64 = await new FSFile(uri).base64();
      const file = dir.createFile(`reflection-${Date.now()}.png`, 'image/png');
      file.write(base64, { encoding: 'base64' });
      Alert.alert(T('shareCardSaved'), T('shareCardSavedMsg'));
    } catch (e) {
      Alert.alert(T('shareCardError'), T('shareCardSaveErrorMsg'));
    } finally {
      setCapturing(false);
    }
  };

  return (
    <View style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,.8)', justifyContent: 'center', alignItems: 'center', padding: 24, zIndex: 9999 }}>
        {/* Close button */}
        <View style={{ position: 'absolute', top: 60, right: 24, zIndex: 10 }}>
          <TouchableOpacity onPress={onClose} style={{ padding: 8 }}>
            <X size={28} color="#fff" />
          </TouchableOpacity>
        </View>

        {/* Card preview */}
        <ViewShot ref={viewShotRef} options={{ format: 'png', quality: 1 }}>
          <View style={{
            width: 320, overflow: 'hidden',
            backgroundColor: bgColor,
          }}>
          {/* Decorative circles */}
          <View style={{ position: 'absolute', top: -40, right: -40, width: 120, height: 120, borderRadius: 60, backgroundColor: 'rgba(255,255,255,.08)' }} />
          <View style={{ position: 'absolute', bottom: -20, left: -20, width: 80, height: 80, borderRadius: 40, backgroundColor: 'rgba(255,255,255,.05)' }} />

          <View style={{ padding: 28 }}>
            {/* Quote mark */}
            <Text style={{ color: 'rgba(255,255,255,.2)', fontSize: FONT_HERO(), lineHeight: 52, marginBottom: -8 }}>「</Text>

            {/* Content */}
            <Text style={{ color: '#fff', fontSize: FONT_BODY() + 2, lineHeight: 28, marginBottom: 8, fontWeight: '500' }}>
              {reflection.content}
            </Text>

            {/* Closing quote */}
            <Text style={{ color: 'rgba(255,255,255,.2)', fontSize: FONT_HERO(), lineHeight: 52, marginTop: -16, marginBottom: 12, textAlign: 'right' }}>」</Text>

            {/* Tags + Mood */}
            {(reflection.tags.length > 0 || reflection.mood) && (
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginBottom: 16 }}>
                {reflection.tags.map(tag => (
                  <View key={tag} style={{ paddingHorizontal: 12, paddingVertical: 4, borderRadius: 12, backgroundColor: 'rgba(255,255,255,.2)' }}>
                    <Text style={{ color: 'rgba(255,255,255,.9)', fontSize: FONT_SMALL() }}>{tag}</Text>
                  </View>
                ))}
                {reflection.mood && (
                  <View style={{ paddingHorizontal: 12, paddingVertical: 4, borderRadius: 12, backgroundColor: 'rgba(255,255,255,.15)' }}>
                    <Text style={{ color: 'rgba(255,255,255,.8)', fontSize: FONT_SMALL() }}>💭 {reflection.mood}</Text>
                  </View>
                )}
              </View>
            )}

            {/* Footer */}
            <View style={{ borderTopWidth: 1, borderTopColor: 'rgba(255,255,255,.15)', paddingTop: 16, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
              <Text style={{ color: 'rgba(255,255,255,.5)', fontSize: FONT_SMALL() }}>📅 {timeStr}</Text>
              <Text style={{ color: 'rgba(255,255,255,.7)', fontSize: FONT_SMALL() }}>❤️ 心流纪 · Egoless Do</Text>
            </View>
          </View>
        </View>
        </ViewShot>

        {/* Action buttons */}
        <View style={{ flexDirection: 'row', gap: 12, marginTop: 24 }}>
          {onTextShare && (
            <TouchableOpacity onPress={() => { onClose(); onTextShare(); }}
              style={{ flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: 'rgba(255,255,255,.15)', paddingHorizontal: 20, paddingVertical: 12, borderRadius: 24 }}>
              <MessageSquare size={18} color="#fff" />
              <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: '600' }}>{T('shareTextShare')}</Text>
            </TouchableOpacity>
          )}
          <TouchableOpacity onPress={handleCapture} disabled={capturing}
            style={{ flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: 'rgba(255,255,255,.15)', paddingHorizontal: 20, paddingVertical: 12, borderRadius: 24, opacity: capturing ? 0.5 : 1 }}>
            <Share2 size={18} color="#fff" />
            <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: '600' }}>{T('shareImageShare')}</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={handleSave} disabled={capturing}
            style={{ flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: 'rgba(255,255,255,.15)', paddingHorizontal: 20, paddingVertical: 12, borderRadius: 24, opacity: capturing ? 0.5 : 1 }}>
            <Download size={18} color="#fff" />
            <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: '600' }}>{T('shareCardSave')}</Text>
          </TouchableOpacity>
        </View>
    </View>
  );
}

import type { MindReflection, TrailFilters } from '@egoless-do/core';
import {
  parseSmartQuery, computeCandidatePool, buildIndex,
  retrieveTopK, semanticSearchReflections,
} from '@egoless-do/core';
import { describe, it, expect, vi, beforeEach } from 'vitest';

import { mergeResults, runAIPhase2, runAIPhase3, type SearchResult } from './searchPipeline';

// @ts-expect-error — React Native global not available in test env
globalThis.__DEV__ = false;

vi.mock('@egoless-do/core', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@egoless-do/core')>();
  return {
    ...actual,
    createLogger: () => ({ error: vi.fn(), warn: vi.fn(), info: vi.fn(), debug: vi.fn() }),
    parseSmartQuery: vi.fn().mockResolvedValue({ topic: '', filters: {}, question: '' }),
    semanticSearchReflections: vi.fn().mockResolvedValue([]),
    computeCandidatePool: vi.fn().mockReturnValue([]),
    buildIndex: vi.fn().mockReturnValue({}),
    retrieveTopK: vi.fn().mockReturnValue([]),
    isAIRecommendAvailable: vi.fn().mockReturnValue(false),
  };
});

function makeReflection(id: string, overrides: Partial<MindReflection> = {}): MindReflection {
  return {
    id,
    content: `reflection ${id}`,
    timestamp: Date.now(),
    tags: [],
    mood: 'calm',
    deleted: false,
    ...overrides,
  } as MindReflection;
}

describe('searchPipeline', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('mergeResults', () => {
    it('returns empty array for empty input', () => {
      expect(mergeResults([])).toEqual([]);
    });

    it('sorts direct results by score descending', () => {
      const r1 = makeReflection('a');
      const r2 = makeReflection('b');
      const r3 = makeReflection('c');
      const results = [
        { ref: r1, score: 0.5, source: 'direct' as const },
        { ref: r2, score: 0.9, source: 'direct' as const },
        { ref: r3, score: 0.7, source: 'direct' as const },
      ];
      const merged = mergeResults(results);
      expect(merged.map(r => r.id)).toEqual(['b', 'c', 'a']);
    });

    it('puts direct results before extended results', () => {
      const direct = makeReflection('direct', { content: 'direct' });
      const extended = makeReflection('extended', { content: 'extended' });
      const results = [
        { ref: extended, score: 0.99, source: 'extended' as const },
        { ref: direct, score: 0.5, source: 'direct' as const },
      ];
      const merged = mergeResults(results);
      expect(merged[0].id).toBe('direct');
      expect(merged[1].id).toBe('extended');
    });

    it('sorts extended results by score descending within group', () => {
      const e1 = makeReflection('e1');
      const e2 = makeReflection('e2');
      const results = [
        { ref: e1, score: 0.3, source: 'extended' as const },
        { ref: e2, score: 0.8, source: 'extended' as const },
      ];
      const merged = mergeResults(results);
      expect(merged.map(r => r.id)).toEqual(['e2', 'e1']);
    });

    it('handles mixed direct and extended with correct ordering', () => {
      const d1 = makeReflection('d1');
      const d2 = makeReflection('d2');
      const e1 = makeReflection('e1');
      const results = [
        { ref: e1, score: 0.95, source: 'extended' as const },
        { ref: d1, score: 0.3, source: 'direct' as const },
        { ref: d2, score: 0.8, source: 'direct' as const },
      ];
      const merged = mergeResults(results);
      expect(merged.map(r => r.id)).toEqual(['d2', 'd1', 'e1']);
    });

    it('handles single result', () => {
      const r = makeReflection('only');
      const merged = mergeResults([{ ref: r, score: 1.0, source: 'direct' as const }]);
      expect(merged).toHaveLength(1);
      expect(merged[0].id).toBe('only');
    });
  });

  describe('runAIPhase2', () => {
    it('returns shouldReturn=true when result has question and chatHistory is short', async () => {
      const reflections = [makeReflection('r1')];
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: '', filters: {}, question: 'What do you mean?',
      } as any);

      const result = await runAIPhase2(reflections, 'test', {}, [], new Set(), []);

      expect(result).toEqual({
        smartResult: { topic: '', filters: {}, question: 'What do you mean?' },
        shouldReturn: true,
      });
    });

    it('does not return early when question exists but chatHistory is >= 3', async () => {
      const reflections = [makeReflection('r1')];
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: '', filters: {}, question: 'What do you mean?',
      } as any);

      const result = await runAIPhase2(
        reflections, 'test', {}, [], new Set(), ['a', 'b', 'c'],
      );

      // question path skipped, no topic/filters either → returns null
      expect(result.smartResult).toBeNull();
      expect(result.shouldReturn).toBe(false);
    });

    it('expands candidates when result has a topic', async () => {
      const r1 = makeReflection('r1');
      const r2 = makeReflection('r2');
      const reflections = [r1, r2];
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: 'meditation', filters: {}, question: '',
      } as any);
      vi.mocked(computeCandidatePool).mockReturnValue([r1, r2]);
      vi.mocked(buildIndex).mockReturnValue({ id: 'idx' });
      vi.mocked(retrieveTopK).mockReturnValue([
        { index: { id: 'r1' }, score: 0.9 },
        { index: { id: 'r2' }, score: 0.7 },
      ]);

      const allResults: SearchResult[] = [];
      const existingIds = new Set<string>();
      const result = await runAIPhase2(
        reflections, 'meditation', {}, allResults, existingIds, [],
      );

      expect(computeCandidatePool).toHaveBeenCalled();
      expect(allResults).toHaveLength(2);
      expect(allResults[0].source).toBe('direct');
      expect(existingIds.has('r1')).toBe(true);
      expect(existingIds.has('r2')).toBe(true);
      expect(result.smartResult).toBeTruthy();
      expect(result.shouldReturn).toBe(false);
    });

    it('expands candidates when result has filters but no topic', async () => {
      const r1 = makeReflection('r1');
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: '', filters: { tags: ['yoga'] }, question: '',
      } as any);
      vi.mocked(computeCandidatePool).mockReturnValue([r1]);
      vi.mocked(buildIndex).mockReturnValue({ id: 'idx' });
      vi.mocked(retrieveTopK).mockReturnValue([
        { index: { id: 'r1' }, score: 0.8 },
      ]);

      const allResults: SearchResult[] = [];
      const result = await runAIPhase2(
        [r1], 'yoga', { tags: ['old'] }, allResults, new Set(), [],
      );

      expect(computeCandidatePool).toHaveBeenCalledWith(
        [r1],
        expect.objectContaining({ tags: ['yoga'] }),
      );
      expect(allResults).toHaveLength(1);
      expect(result.shouldReturn).toBe(false);
    });

    it('merges filters: uses currentFilters as fallback when result filters are empty', async () => {
      const r1 = makeReflection('r1');
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: '', filters: { tags: [], moods: [] }, question: '',
      } as any);
      vi.mocked(computeCandidatePool).mockReturnValue([r1]);
      vi.mocked(buildIndex).mockReturnValue({ id: 'idx' });
      vi.mocked(retrieveTopK).mockReturnValue([]);

      const currentFilters: TrailFilters = { tags: ['meditation'], moods: ['calm'], timeRange: 'week' };
      await runAIPhase2(
        [r1], 'test', currentFilters, [], new Set(), [],
      );

      expect(computeCandidatePool).toHaveBeenCalledWith(
        [r1],
        expect.objectContaining({
          tags: ['meditation'],
          moods: ['calm'],
          timeRange: 'week',
        }),
      );
    });

    it('deduplicates results via existingIds', async () => {
      const r1 = makeReflection('r1');
      const r2 = makeReflection('r2');
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: 'mindfulness', filters: {}, question: '',
      } as any);
      vi.mocked(computeCandidatePool).mockReturnValue([r1, r2]);
      vi.mocked(buildIndex).mockReturnValue({ id: 'idx' });
      vi.mocked(retrieveTopK).mockReturnValue([
        { index: { id: 'r1' }, score: 0.9 },
        { index: { id: 'r2' }, score: 0.7 },
      ]);

      const allResults: SearchResult[] = [];
      const existingIds = new Set(['r1']); // r1 already seen
      await runAIPhase2(
        [r1, r2], 'mindfulness', {}, allResults, existingIds, [],
      );

      // only r2 should be added
      expect(allResults).toHaveLength(1);
      expect(allResults[0].ref.id).toBe('r2');
    });

    it('returns null smartResult when no question, topic, or filters', async () => {
      vi.mocked(parseSmartQuery).mockResolvedValue({
        topic: '', filters: {}, question: '',
      } as any);

      const result = await runAIPhase2(
        [], 'query', {}, [], new Set(), [],
      );

      expect(result.smartResult).toBeNull();
      expect(result.shouldReturn).toBe(false);
    });

    it('returns null smartResult and shouldReturn=false on error', async () => {
      vi.mocked(parseSmartQuery).mockRejectedValue(new Error('AI down'));

      const result = await runAIPhase2(
        [makeReflection('r1')], 'test', {}, [], new Set(), [],
      );

      expect(result.smartResult).toBeNull();
      expect(result.shouldReturn).toBe(false);
    });
  });

  describe('runAIPhase3', () => {
    it('adds semantic results sorted by relevance with source=extended', async () => {
      const r1 = makeReflection('r1');
      const r2 = makeReflection('r2');
      vi.mocked(semanticSearchReflections).mockResolvedValue([
        { reflectionIndex: 1, relevance: 0.6 },
        { reflectionIndex: 0, relevance: 0.9 },
      ] as any);

      const allResults: SearchResult[] = [];
      const existingIds = new Set<string>();
      const result = await runAIPhase3([r1, r2], 'peace', allResults, existingIds);

      // sorted by relevance descending: index 0 (0.9) first, then index 1 (0.6)
      expect(allResults).toHaveLength(2);
      expect(allResults[0].ref.id).toBe('r1');
      expect(allResults[0].score).toBeCloseTo(0.45); // 0.9 * 0.5
      expect(allResults[0].source).toBe('extended');
      expect(allResults[1].ref.id).toBe('r2');
      expect(allResults[1].score).toBeCloseTo(0.3); // 0.6 * 0.5
      expect(existingIds.has('r1')).toBe(true);
      expect(existingIds.has('r2')).toBe(true);
      expect(result).toEqual({ count: 2, failed: false });
    });

    it('returns count=0 when semantic search returns empty', async () => {
      vi.mocked(semanticSearchReflections).mockResolvedValue([]);

      const allResults: SearchResult[] = [];
      const result = await runAIPhase3(
        [makeReflection('r1')], 'test', allResults, new Set(),
      );

      expect(allResults).toHaveLength(0);
      expect(result).toEqual({ count: 0, failed: false });
    });

    it('returns count=0 and failed=true on error', async () => {
      vi.mocked(semanticSearchReflections).mockRejectedValue(
        new Error('embedding service down'),
      );

      const result = await runAIPhase3(
        [makeReflection('r1')], 'test', [], new Set(),
      );

      expect(result).toEqual({ count: 0, failed: true });
    });

    it('deduplicates: skips reflections already in existingIds', async () => {
      const r1 = makeReflection('r1');
      const r2 = makeReflection('r2');
      vi.mocked(semanticSearchReflections).mockResolvedValue([
        { reflectionIndex: 0, relevance: 0.9 },
        { reflectionIndex: 1, relevance: 0.7 },
      ] as any);

      const allResults: SearchResult[] = [];
      const existingIds = new Set(['r1']); // r1 already seen
      const result = await runAIPhase3([r1, r2], 'test', allResults, existingIds);

      expect(allResults).toHaveLength(1);
      expect(allResults[0].ref.id).toBe('r2');
      // count reports total semantic matches, not added count
      expect(result.count).toBe(2);
    });

    it('skips results where reflectionIndex is out of bounds', async () => {
      const r1 = makeReflection('r1');
      vi.mocked(semanticSearchReflections).mockResolvedValue([
        { reflectionIndex: 0, relevance: 0.8 },
        { reflectionIndex: 5, relevance: 0.9 }, // out of bounds
      ] as any);

      const allResults: SearchResult[] = [];
      const result = await runAIPhase3([r1], 'test', allResults, new Set());

      // only r1 is added; index 5 is undefined → skipped
      expect(allResults).toHaveLength(1);
      expect(allResults[0].ref.id).toBe('r1');
      expect(result.count).toBe(2);
    });
  });
});

// ─── AI Search Pipeline (pure functions) ────────────────────────────
// Extracted from useQuickTrailSearch for testability and reuse.

import {
  computeCandidatePool, buildIndex, retrieveTopK,
  parseSmartQuery, semanticSearchReflections,
  createLogger,
} from '@egoless-do/core';
import type { MindReflection, SmartQueryResult, TrailFilters } from '@egoless-do/core';

const log = createLogger('SearchPipeline');

export type SearchResult = { ref: MindReflection; score: number; source: 'direct' | 'extended' };

/** Phase 2: Intent understanding — parse smart query, expand candidates with new filters. */
export async function runAIPhase2(
  reflections: MindReflection[],
  trimmed: string,
  currentFilters: TrailFilters,
  allResults: SearchResult[],
  existingIds: Set<string>,
  chatHistory: string[],
): Promise<{ smartResult: SmartQueryResult | null; shouldReturn: boolean }> {
  try {
    const result = await parseSmartQuery(reflections, trimmed, chatHistory);
    if (result.question && chatHistory.length < 3) {
      return { smartResult: result, shouldReturn: true };
    }
    if (result.topic || (result.filters && Object.keys(result.filters).length > 0)) {
      const newFilters: TrailFilters = {
        timeRange: result.filters.timeRange || currentFilters.timeRange,
        tags: result.filters.tags?.length ? result.filters.tags : currentFilters.tags,
        moods: result.filters.moods?.length ? result.filters.moods : currentFilters.moods,
      };
      const newCandidates = computeCandidatePool(reflections, newFilters);
      const newIndex = buildIndex(newCandidates);
      const topic = result.topic || trimmed;
      const newScored = retrieveTopK(topic, newIndex, 20);
      for (const s of newScored) {
        if (!existingIds.has(s.index.id)) {
          const ref = newCandidates.find(r => r.id === s.index.id);
          if (ref) { allResults.push({ ref, score: s.score, source: 'direct' }); existingIds.add(ref.id); }
        }
      }
      return { smartResult: result, shouldReturn: false };
    }
    return { smartResult: null, shouldReturn: false };
  } catch (e) {
    log.debug('AI Phase 2 failed:', e);
    return { smartResult: null, shouldReturn: false };
  }
}

/** Phase 3: Semantic expansion — find related reflections via embeddings. */
export async function runAIPhase3(
  reflections: MindReflection[],
  trimmed: string,
  allResults: SearchResult[],
  existingIds: Set<string>,
): Promise<{ count: number; failed: boolean }> {
  try {
    const semanticResults = await semanticSearchReflections(reflections, trimmed);
    if (semanticResults.length > 0) {
      const sorted = semanticResults.sort((a, b) => b.relevance - a.relevance);
      for (const sr of sorted) {
        const ref = reflections[sr.reflectionIndex];
        if (ref && !existingIds.has(ref.id)) {
          allResults.push({ ref, score: sr.relevance * 0.5, source: 'extended' });
          existingIds.add(ref.id);
        }
      }
      return { count: semanticResults.length, failed: false };
    }
    return { count: 0, failed: false };
  } catch (e) {
    log.debug('AI Phase 3 failed:', e);
    return { count: 0, failed: true };
  }
}

/** Merge and rank results: direct matches first (by score), then extended. */
export function mergeResults(allResults: SearchResult[]): MindReflection[] {
  const direct = allResults.filter(r => r.source === 'direct').sort((a, b) => b.score - a.score);
  const extended = allResults.filter(r => r.source === 'extended').sort((a, b) => b.score - a.score);
  return [...direct, ...extended].map(r => r.ref);
}

import {
  computeCandidatePool, buildIndex, retrieveTopK,
  isAIRecommendAvailable,
  createLogger,
} from '@egoless-do/core';
import type { MindReflection, SmartQueryResult, SmartQueryFilters, TrailFilters } from '@egoless-do/core';
import { useState, useMemo, useCallback, useRef, useEffect } from 'react';

import { runAIPhase2, runAIPhase3, mergeResults } from './searchPipeline';
import { useSearchHistory } from './useSearchHistory';

const log = createLogger('Reflections');

export type TimeRange = 'week' | 'month' | '3months' | 'all';
export type MatchMode = 'idle' | 'local' | 'ai' | 'ai-loading';

export interface AnalysisStep {
  id: string;
  text: string;
  status: 'pending' | 'loading' | 'done' | 'error';
  detail?: string;
}

const PAGE_SIZE = 20;

export function useQuickTrailSearch(
  reflections: MindReflection[],
  initialText: string,
  T: (key: string) => string,
  aiConfig?: { mode: string; models: unknown[] },
) {
  const analyzingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const chatHistoryRef = useRef<string[]>([]);

  useEffect(() => () => {
    if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
  }, []);

  // ── Filters ───────────────────────────────────────────────────
  const [searchQuery, setSearchQuery] = useState(initialText);
  const [timeRange, setTimeRange] = useState<TimeRange>('month');
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [selectedMoods, setSelectedMoods] = useState<string[]>([]);

  // ── Smart query ───────────────────────────────────────────────
  const [smartResult, setSmartResult] = useState<SmartQueryResult | null>(null);
  const [chatHistory, setChatHistory] = useState<string[]>([]);

  // ── AI Analysis stream ────────────────────────────────────────
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisSteps, setAnalysisSteps] = useState<AnalysisStep[]>([]);
  const [isSmartParsing, setIsSmartParsing] = useState(false);

  // ── Results ───────────────────────────────────────────────────
  const [matchMode, setMatchMode] = useState<MatchMode>('idle');
  const [matchResults, setMatchResults] = useState<MindReflection[]>([]);
  const [aiDegraded, setAiDegraded] = useState(false);

  // ── Selection ─────────────────────────────────────────────────
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [trailName, setTrailName] = useState('');

  // ── Pagination ───────────────────────────────────────────────
  const [page, setPage] = useState(1);

  // ── Data ──────────────────────────────────────────────────────
  const reflectionsMap = useMemo(() => {
    const map = new Map<string, MindReflection>();
    for (const r of reflections) map.set(r.id, r);
    return map;
  }, [reflections]);

  const userTags = useMemo(() => {
    const tags = new Set<string>();
    for (const r of reflections) {
      if (r.tags) for (const t of r.tags) tags.add(t);
    }
    return Array.from(tags).sort();
  }, [reflections]);

  const userMoods = useMemo(() => {
    const moods = new Set<string>();
    for (const r of reflections) {
      if (r.mood) moods.add(r.mood);
    }
    return Array.from(moods).sort();
  }, [reflections]);

  const aiAvailable = useMemo(() => isAIRecommendAvailable(), []);

  const handleRemoveFilter = useCallback((type: keyof SmartQueryFilters, value?: string) => {
    if (type === 'tags' && value) {
      setSelectedTags(prev => prev.filter(t => t !== value));
    } else if (type === 'moods' && value) {
      setSelectedMoods(prev => prev.filter(m => m !== value));
    } else if (type === 'timeRange') {
      setTimeRange('month');
    }
    setSmartResult(prev => {
      if (!prev?.filters) return prev;
      const updated = { ...prev.filters };
      if (type === 'tags' && value) updated.tags = (updated.tags ?? []).filter(t => t !== value);
      else if (type === 'moods' && value) updated.moods = (updated.moods ?? []).filter(m => m !== value);
      else if (type === 'timeRange') updated.timeRange = undefined;
      return { ...prev, filters: updated };
    });
  }, []);

  // ── Candidate pool + recommendations ──────────────────────────
  const filters: TrailFilters = useMemo(() => ({
    timeRange,
    tags: selectedTags.length > 0 ? selectedTags : [],
    moods: selectedMoods.length > 0 ? selectedMoods : [],
  }), [timeRange, selectedTags, selectedMoods]);

  const candidates = useMemo(() =>
    computeCandidatePool(reflections, filters),
    [reflections, filters],
  );

  // ── Debounced search (local only, AI on-demand) ──────────────
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      const trimmed = searchQuery.trim();
      if (!trimmed) {
        setMatchMode('idle');
        setMatchResults([]);
        return;
      }
      const index = buildIndex(candidates);
      const scored = retrieveTopK(trimmed, index, 20);
      const results = scored.map(s => candidates.find(r => r.id === s.index.id)).filter(Boolean) as MindReflection[];
      setMatchResults(results);
      setMatchMode(results.length > 0 ? 'local' : 'idle');
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [searchQuery, candidates]);

  // ── Selection derived ─────────────────────────────────────────
  const selectedReflections = useMemo(() => {
    return Array.from(selectedIds).map(id => reflectionsMap.get(id)).filter(Boolean) as MindReflection[];
  }, [selectedIds, reflectionsMap]);

  const selectedMoodsList = useMemo(() => {
    const sorted = [...selectedReflections].sort((a, b) => (a.timestamp ?? 0) - (b.timestamp ?? 0));
    const moods: string[] = [];
    let last = '';
    for (const r of sorted) {
      if (r.mood && r.mood !== last) { moods.push(r.mood); last = r.mood; }
    }
    return moods;
  }, [selectedReflections]);

  const selectedDateRange = useMemo(() => {
    if (selectedReflections.length === 0) return undefined;
    const sorted = [...selectedReflections].sort((a, b) => (a.timestamp ?? 0) - (b.timestamp ?? 0));
    return { start: sorted[0].timestamp, end: sorted[sorted.length - 1].timestamp };
  }, [selectedReflections]);

  // ── Search history ─────────────────────────────────────────────
  const { searchHistory, addToHistory } = useSearchHistory();

  // ── AI Pipeline — thin wrappers over pure functions ───────────────
  const runAIPhase2Wrapped = useCallback(async (
    refs: MindReflection[],
    trimmed: string,
    curFilters: TrailFilters,
    allResults: Array<{ ref: MindReflection; score: number; source: 'direct' | 'extended' }>,
    existingIds: Set<string>,
  ) => {
    if (!aiAvailable) return { smartResult: null, shouldReturn: false };
    return runAIPhase2(refs, trimmed, curFilters, allResults, existingIds, chatHistoryRef.current);
  }, [aiAvailable]);

  const runAIPhase3Wrapped = useCallback(async (
    refs: MindReflection[],
    trimmed: string,
    allResults: Array<{ ref: MindReflection; score: number; source: 'direct' | 'extended' }>,
    existingIds: Set<string>,
  ) => {
    if (!aiAvailable) return { count: 0, failed: false };
    return runAIPhase3(refs, trimmed, allResults, existingIds);
  }, [aiAvailable]);

  // ── Handlers ──────────────────────────────────────────────────
  const toggleTag = useCallback((tag: string) => {
    setSelectedTags(prev => {
      const isRemoving = prev.includes(tag);
      setSearchQuery(q => {
        if (isRemoving) return q.replace(new RegExp(`(?:^|\\s)${tag}(?=\\s|$)`, 'g'), '').replace(/\s+/g, ' ').trim();
        return q ? `${q} ${tag}` : tag;
      });
      return isRemoving ? prev.filter(t => t !== tag) : [...prev, tag];
    });
  }, []);

  const toggleMood = useCallback((mood: string) => {
    setSelectedMoods(prev => {
      const isRemoving = prev.includes(mood);
      setSearchQuery(q => {
        if (isRemoving) return q.replace(new RegExp(`(?:^|\\s)${mood}(?=\\s|$)`, 'g'), '').replace(/\s+/g, ' ').trim();
        return q ? `${q} ${mood}` : mood;
      });
      return isRemoving ? prev.filter(m => m !== mood) : [...prev, mood];
    });
  }, []);

  const handleLocalSearch = useCallback(() => {
    const trimmed = searchQuery.trim();
    if (!trimmed) {
      setMatchMode('idle');
      setMatchResults([]);
      setSmartResult(null);
      return;
    }
    const index = buildIndex(candidates);
    const scored = retrieveTopK(trimmed, index, 20);
    const results = scored.map(s => candidates.find(r => r.id === s.index.id)).filter(Boolean) as MindReflection[];
    setMatchResults(results);
    setMatchMode(results.length > 0 ? 'local' : 'idle');
    setSmartResult(null);
    if (results.length > 0) addToHistory(trimmed);
  }, [searchQuery, candidates, addToHistory]);

  const updateStep = useCallback((id: string, updates: Partial<AnalysisStep>) => {
    setAnalysisSteps(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  }, []);

  // ── Three-phase search pipeline ────────────────────────────────
  const [isAISearching, setIsAISearching] = useState(false);

  const handleSmartQuery = useCallback(async () => {
    const trimmed = searchQuery.trim();
    if (!trimmed) {
      setMatchMode('idle');
      setMatchResults([]);
      setSmartResult(null);
      setAnalysisSteps([]);
      return;
    }

    setIsSmartParsing(true);
    setIsAnalyzing(true);
    setMatchMode('ai-loading');
    setAiDegraded(false);
    setPage(1);

    const steps: AnalysisStep[] = [
      { id: 'phase1', text: T('searchPhaseLocal'), status: 'loading' },
      { id: 'phase2', text: T('searchPhaseIntent'), status: 'pending' },
      { id: 'phase3', text: T('searchPhaseSemantic'), status: 'pending' },
      { id: 'merge', text: T('searchPhaseMerge'), status: 'pending' },
    ];
    setAnalysisSteps(steps);

    try {
      // Phase 1: Local RAG search
      const index = buildIndex(candidates);
      const scored = retrieveTopK(trimmed, index, 20);
      const allResults: Array<{ ref: MindReflection; score: number; source: 'direct' | 'extended' }> = [];
      const existingIds = new Set<string>();
      for (const s of scored) {
        const ref = candidates.find(r => r.id === s.index.id);
        if (ref) { allResults.push({ ref, score: s.score, source: 'direct' }); existingIds.add(ref.id); }
      }
      updateStep('phase1', {
        status: 'done',
        detail: allResults.length > 0
          ? T('searchPhaseLocalResult').replace('{n}', String(allResults.length))
          : T('searchPhaseLocalEmpty')
      });

      // Phase 2: Intent understanding
      if (allResults.length <= 3) {
        updateStep('phase2', { status: 'loading' });
        const { smartResult: sr, shouldReturn } = await runAIPhase2Wrapped(reflections, trimmed, filters, allResults, existingIds);
        if (sr) setSmartResult(sr);
        if (shouldReturn) {
          updateStep('phase2', { status: 'done', detail: T('searchPhaseIntentQuestion') });
          const sorted = allResults.sort((a, b) => b.score - a.score);
          setMatchResults(sorted.map(r => r.ref));
          setMatchMode(allResults.length > 0 ? 'local' : 'idle');
          setIsSmartParsing(false);
          if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
          analyzingTimerRef.current = setTimeout(() => setIsAnalyzing(false), 2000);
          return;
        }
        updateStep('phase2', { status: 'done', detail: sr ? T('searchPhaseIntentResult').replace('{n}', String(allResults.length)) : T('searchPhaseIntentSkip') });
      } else {
        updateStep('phase2', { status: 'done', detail: T('searchPhaseIntentSkip') });
      }

      // Phase 3: Semantic expansion
      if (allResults.length <= 3) {
        updateStep('phase3', { status: 'loading' });
        const { count, failed } = await runAIPhase3Wrapped(reflections, trimmed, allResults, existingIds);
        if (failed) { setAiDegraded(true); updateStep('phase3', { status: 'error', detail: T('searchPhaseSemanticFail') }); }
        else updateStep('phase3', { status: 'done', detail: count > 0 ? T('searchPhaseSemanticResult').replace('{n}', String(count)) : T('searchPhaseSemanticEmpty') });
      } else {
        updateStep('phase3', { status: 'done', detail: T('searchPhaseSemanticSkip') });
      }

      // Merge
      updateStep('merge', { status: 'loading' });
      const directCount = allResults.filter(r => r.source === 'direct').length;
      const extendedCount = allResults.filter(r => r.source === 'extended').length;
      const finalResults = mergeResults(allResults);
      setMatchResults(finalResults);
      setMatchMode(finalResults.length > 0 ? 'ai' : 'idle');
      if (finalResults.length > 0) addToHistory(trimmed);
      updateStep('merge', {
        status: 'done',
        detail: T('searchPhaseMergeResult')
          .replace('{n}', String(finalResults.length))
          .replace('{d}', String(directCount))
          .replace('{e}', String(extendedCount))
      });
    } catch (e) {
      log.warn('SmartQuery pipeline error:', e);
      const index = buildIndex(candidates);
      const scored = retrieveTopK(trimmed, index, 20);
      const fallback = scored.map(s => candidates.find(r => r.id === s.index.id)).filter(Boolean) as MindReflection[];
      setMatchResults(fallback);
      setMatchMode('local');
      setAiDegraded(true);
      setSmartResult(null);
      setAnalysisSteps(prev => prev.map(s =>
        s.status === 'loading' ? { ...s, status: 'error' as const, detail: T('searchDegraded') } : s
      ));
    } finally {
      setIsSmartParsing(false);
      if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
      analyzingTimerRef.current = setTimeout(() => setIsAnalyzing(false), 2000);
    }
  }, [searchQuery, reflections, candidates, filters, aiAvailable, runAIPhase2Wrapped, runAIPhase3Wrapped, updateStep, addToHistory, T]);

  // AI on-demand search (Phase 2 + 3, appends to local results)
  const handleAISearch = useCallback(async () => {
    const trimmed = searchQuery.trim();
    if (!trimmed || !aiAvailable) return;

    setIsAISearching(true);
    setIsSmartParsing(true);
    setIsAnalyzing(true);
    setAiDegraded(false);

    const steps: AnalysisStep[] = [
      { id: 'phase2', text: T('searchPhaseIntent'), status: 'loading' },
      { id: 'phase3', text: T('searchPhaseSemantic'), status: 'pending' },
      { id: 'merge', text: T('searchPhaseMerge'), status: 'pending' },
    ];
    setAnalysisSteps(steps);

    try {
      const existingIds = new Set(matchResults.map(r => r.id));
      const allResults: Array<{ ref: MindReflection; score: number; source: 'direct' | 'extended' }> =
        matchResults.map(r => ({ ref: r, score: 0, source: 'direct' as const }));

      // Phase 2
      const { smartResult: sr, shouldReturn } = await runAIPhase2Wrapped(reflections, trimmed, filters, allResults, existingIds);
      if (sr) setSmartResult(sr);
      if (shouldReturn) {
        updateStep('phase2', { status: 'done', detail: T('searchPhaseIntentQuestion') });
        setIsSmartParsing(false);
        setIsAISearching(false);
        if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
        analyzingTimerRef.current = setTimeout(() => setIsAnalyzing(false), 2000);
        return;
      }
      updateStep('phase2', { status: 'done', detail: sr ? T('searchPhaseIntentResult').replace('{n}', String(allResults.length)) : T('searchPhaseIntentSkip') });

      // Phase 3
      updateStep('phase3', { status: 'loading' });
      const { count, failed } = await runAIPhase3(reflections, trimmed, allResults, existingIds);
      if (failed) { setAiDegraded(true); updateStep('phase3', { status: 'error', detail: T('searchPhaseSemanticFail') }); }
      else updateStep('phase3', { status: 'done', detail: count > 0 ? T('searchPhaseSemanticResult').replace('{n}', String(count)) : T('searchPhaseSemanticEmpty') });

      // Merge
      updateStep('merge', { status: 'loading' });
      const directCount = allResults.filter(r => r.source === 'direct').length;
      const extendedCount = allResults.filter(r => r.source === 'extended').length;
      const finalResults = mergeResults(allResults);
      setMatchResults(finalResults);
      setMatchMode(finalResults.length > 0 ? 'ai' : 'idle');
      if (finalResults.length > 0) addToHistory(trimmed);
      updateStep('merge', {
        status: 'done',
        detail: T('searchPhaseMergeResult')
          .replace('{n}', String(finalResults.length))
          .replace('{d}', String(directCount))
          .replace('{e}', String(extendedCount))
      });
    } catch (e) {
      log.warn('AISearch pipeline error:', e);
      setAiDegraded(true);
    } finally {
      setIsSmartParsing(false);
      setIsAISearching(false);
      if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
      analyzingTimerRef.current = setTimeout(() => setIsAnalyzing(false), 2000);
    }
  }, [searchQuery, reflections, matchResults, filters, aiAvailable, runAIPhase2Wrapped, runAIPhase3Wrapped, updateStep, addToHistory, T]);

  const handleSmartAnswer = useCallback((answer: string) => {
    setChatHistory(prev => {
      const next = [...prev, answer];
      chatHistoryRef.current = next;
      return next;
    });
    if (analyzingTimerRef.current) clearTimeout(analyzingTimerRef.current);
    analyzingTimerRef.current = setTimeout(() => { handleSmartQuery().catch(err => log.error(err, { message: 'handleSmartQuery' })); }, 100);
  }, [handleSmartQuery]);

  const handleClear = useCallback(() => {
    setSearchQuery('');
    setMatchMode('idle');
    setMatchResults([]);
    setSmartResult(null);
    setChatHistory([]);
    setPage(1);
    setAiDegraded(false);
  }, []);

  return {
    // State
    searchQuery, setSearchQuery,
    timeRange, setTimeRange,
    selectedTags, setSelectedTags, toggleTag,
    selectedMoods, setSelectedMoods, toggleMood,
    matchMode, matchResults,
    smartResult, setSmartResult,
    analysisSteps, isAnalyzing, isSmartParsing,
    aiDegraded,
    selectedIds, setSelectedIds,
    trailName, setTrailName,
    page, setPage,
    searchHistory,
    isAISearching,
    chatHistory, setChatHistory,
    // Derived
    reflectionsMap, userTags, userMoods, aiAvailable,
    candidates, filters,
    selectedReflections, selectedMoodsList, selectedDateRange,
    PAGE_SIZE,
    // Actions
    handleSmartQuery, handleAISearch, handleSmartAnswer, handleClear,
    handleLocalSearch, handleRemoveFilter, addToHistory,
    resetFilters: () => {
      setTimeRange('month');
      setSelectedTags([]);
      setSelectedMoods([]);
      setSearchQuery('');
      setMatchMode('idle');
      setMatchResults([]);
    },
  };
}

