                    />
                  </View>
                  <Text style={[styles.moodCount, { color: TH.sub }]}>
                    {count}
                  </Text>
                </View>
              );
            })}
          </View>
        )}
      </View>
    );
  };

  const renderTagsTab = () => {
    const maxCount = tagFrequency[0]?.[1] ?? 1;

    return (
      <View style={styles.tabContent}>
        <Text style={[styles.sectionTitle, { color: TH.sub }]}>
