            暂无标签数据
          </Text>
        ) : (
          <>
            {/* Tag cloud */}
            <View style={styles.tagCloud}>
              {tagFrequency.map(([tag, count]) => {
                const scale = count / maxCount;
                const fontSize = 12 + scale * 12;
                return (
                  <Text
                    key={tag}
                    style={{
                      color: P,
                      fontSize,
                      fontWeight: scale > 0.6 ? '700' : '400',
                      marginRight: 8,
                      marginBottom: 4,
                    }}
                  >
                    {tag}
                  </Text>
                );
              })}
            </View>

            {/* Ranking */}
            <Text
              style={[
                styles.sectionTitle,
