                    />
                  </View>
                  <Text style={[styles.rankingCount, { color: TH.sub }]}>
                    {count}
                  </Text>
                </View>
              );
            })}
          </>
        )}
      </View>
    );
  };

  const renderLinkedTaskTab = () => {
    const { linkedCount, rate, groups } = linkedTaskStats;
    const maxCount = groups[0]?.count ?? 1;

    return (
      <View style={styles.tabContent}>
        {/* Overview */}
