import { View, Text, FlatList, TouchableOpacity, TextInput, KeyboardAvoidingView, Platform, StyleSheet, Alert, ListRenderItemInfo } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import type { RootStackParamList } from '../../../navigation/types';
import { safeGetItem, safeSetItem } from '../../../store/safeAsyncStorage';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';

const log = createLogger('Reflections');
import RecommendCard from '../insights/RecommendCard';

import CreateThoughtTrailModal from './CreateThoughtTrailModal';
import SmartQueryPanel from './SmartQueryPanel';

const TRAIL_IGNORED_KEY = 'trailIgnoredPatterns';

export default function MindTrailScreen() {
  // ═══════════════════════════════════════════════════════════════
  // Section 1: Store Data & Navigation
  // ═══════════════════════════════════════════════════════════════
  const TH = useTheme();
  const T = useT();
  const { ignoredRecPatterns, aiMode, aiModels, thoughtTrails: rawThoughtTrails, reflections: rawReflections, createThoughtTrail, deleteThoughtTrail, addIgnoredRecPattern } = useShallowStore(s => ({
    ignoredRecPatterns: s.ignoredRecPatterns,
    aiMode: s.aiMode,
    aiModels: s.aiModels,
    thoughtTrails: s.thoughtTrails,
    reflections: s.reflections,
    createThoughtTrail: s.createThoughtTrail,
    deleteThoughtTrail: s.deleteThoughtTrail,
    addIgnoredRecPattern: s.addIgnoredRecPattern,
  }));
  const nav = useNavigation<StackNavigationProp<RootStackParamList>>();

  // ═══════════════════════════════════════════════════════════════
  // Section 2: Local State & Refs
  // ═══════════════════════════════════════════════════════════════
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [inputText, setInputText] = useState('');
  const [recommendations, setRecommendations] = useState<TrailRecommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);
  const [isAILoading, setIsAILoading] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const aiGenerationRef = useRef(0);
  const smartAnswerTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (smartAnswerTimerRef.current) clearTimeout(smartAnswerTimerRef.current); }, []);
  useEffect(() => () => { if (smartAbortRef.current) smartAbortRef.current.abort(); }, []);

  // Smart query state (integrated into bottom input)
  const [smartResult, setSmartResult] = useState<SmartQueryResult | null>(null);
  const [chatHistory, setChatHistory] = useState<string[]>([]);
  const chatHistoryRef = useRef<string[]>([]);
  const [isSmartParsing, setIsSmartParsing] = useState(false);
  const [queryResults, setQueryResults] = useState<MindReflection[]>([]);
  const [showQueryPanel, setShowQueryPanel] = useState(false);
  const smartAbortRef = useRef<AbortController | null>(null);

  // AsyncStorage-based ignored patterns (persists across sessions, local only)
  const ignoredPatternsRef = useRef<string[]>([]);
  const [ignoredVersion, setIgnoredVersion] = useState(0);
  useEffect(() => {
    void safeGetItem(TRAIL_IGNORED_KEY).then(raw => {
      if (raw) {
        try { ignoredPatternsRef.current = JSON.parse(raw) as string[]; } catch { /* corrupted cache — ignore */ }
      }
    });
  }, []);

  // All ignored patterns: merge store (session) + AsyncStorage (persistent)
  const allIgnoredPatterns = useMemo(() => {
    const storePatterns = ignoredRecPatterns ?? [];
    return [...new Set([...storePatterns, ...ignoredPatternsRef.current])];
  }, [ignoredRecPatterns, ignoredVersion]);

  // ═══════════════════════════════════════════════════════════════
  // Section 3: Data Filtering & AI Availability
  // ═══════════════════════════════════════════════════════════════
  const aiAvailable = useMemo(() => {
    return isAIRecommendAvailable({ mode: aiMode, models: aiModels });
  }, [aiMode, aiModels]);

  const thoughtTrails = useMemo(() =>
    (rawThoughtTrails ?? []).filter(t => !t.deleted),
    [rawThoughtTrails]
  );

  const manualTrails = useMemo(() =>
    thoughtTrails.filter(t => t.source === 'manual' || !t.source),
    [thoughtTrails]
  );

  const aiTrails = useMemo(() =>
    thoughtTrails.filter(t => t.source === 'ai'),
    [thoughtTrails]
  );

  const reflections = useMemo(() =>
    (rawReflections ?? []).filter(r => !r.deleted),
    [rawReflections]
  );

  // 推荐候选源：最近 30 天内、未分配到任何思维脉络的感念
  const recommendationCandidates = useMemo(() => {
    const thirtyDaysAgo = Date.now() - 30 * MS_PER_DAY;
    return reflections.filter(r =>
      r.timestamp >= thirtyDaysAgo &&
      (!r.thoughtTrailIds || r.thoughtTrailIds.length === 0)
    );
  }, [reflections]);

  // ═══════════════════════════════════════════════════════════════
  // Section 4: Recommendation Engine
  // ═══════════════════════════════════════════════════════════════

  // Progressive loading: local first, then AI
  // 用 ref 读取 thoughtTrails 和 ignoredPatterns，避免 store rehydration 触发 effect 重新执行
  const mountedRef = useRef(true);
  useEffect(() => () => { mountedRef.current = false; }, []);
  const thoughtTrailsRef = useRef(thoughtTrails);
  thoughtTrailsRef.current = thoughtTrails;
  const ignoredPatternsForRecsRef = useRef(allIgnoredPatterns);
  ignoredPatternsForRecsRef.current = allIgnoredPatterns;

  useEffect(() => {
    // 候选不足 3 条时不推荐
    if (recommendationCandidates.length < 3) {
      setRecommendations([]);
      setIsLoadingRecs(false);
      return;
    }

    const currentTrails = thoughtTrailsRef.current;
    const currentIgnored = ignoredPatternsForRecsRef.current;
    // 用 generation 计数器代替 abort：旧请求自然完成但不采用结果
    const gen = ++aiGenerationRef.current;

    const loadRecs = async () => {
      setIsLoadingRecs(true);
      setIsAILoading(false);

      try {
        // Step 1: Load local recommendations immediately (<100ms)
        const localRecs = computeRecommendations(recommendationCandidates, currentTrails).slice(0, 2);
        const localWithReason = localRecs.map(rec => ({
          ...rec,
          reason: rec.reason || '',
          source: 'local' as const,
        }));
        const withPrefs = applyUserPreferences(localWithReason, currentIgnored);
        if (!mountedRef.current) return;
        setRecommendations(withPrefs);
        setIsLoadingRecs(false);

        // Step 2: Load AI recommendations in background (if available)
        if (aiAvailable && recommendationCandidates.length >= 3) {
          setIsAILoading(true);

          try {
            const aiResult = await recommendTrailsViaAI(recommendationCandidates);
            // 如果 effect 已经重新执行（新一轮），忽略旧结果
            if (aiGenerationRef.current !== gen) return;
            if (aiResult.recommendations.length > 0) {
              const tgt = aiResult.targetReflections;
              const aiRecs: TrailRecommendation[] = aiResult.recommendations.slice(0, 2).map(rec => ({
                name: rec.name,
                narrative: rec.description,
                reflectionIds: rec.reflectionIndices.map(i => tgt[i]?.id).filter(Boolean),
                moods: rec.reflectionIndices.map(i => tgt[i]?.mood).filter(Boolean) as string[],
                primaryTag: '',
                startDate: rec.reflectionIndices.length > 0 ? Math.min(...rec.reflectionIndices.map(i => tgt[i]?.timestamp ?? Infinity)) : Date.now(),
                endDate: rec.reflectionIndices.length > 0 ? Math.max(...rec.reflectionIndices.map(i => tgt[i]?.timestamp ?? -Infinity)) : Date.now(),
                spanDays: 1,
                trend: 'flat' as const,
                assignedCount: 0,
                score: rec.confidence,
                type: 'ai' as const,
                reason: rec.description,
                source: 'ai' as const,
              }));

              // 使用 mergeAndRank 替代简单拼接，>50% 重叠去重
              const latestIgnored = ignoredPatternsForRecsRef.current;
              const merged = mergeAndRank(localWithReason, aiRecs).slice(0, 2);
              const mergedWithPrefs = applyUserPreferences(merged, latestIgnored);
              if (mountedRef.current) setRecommendations(mergedWithPrefs);
            }
          } catch (e) {
            log.debug('AI recommendations failed (using local only):', e);
          } finally {
            if (aiGenerationRef.current === gen) {
              setIsAILoading(false);
            }
          }
        }
      } catch (e) {
        log.error(e, { message: 'Failed to load recommendations' });
        if (mountedRef.current) setIsLoadingRecs(false);
      }
    };

    void loadRecs();
  }, [recommendationCandidates, aiAvailable, refreshKey]);

  const visibleRecs = recommendations;

  const handleCreateTrail = useCallback((trailId: string) => {
    nav.navigate('ThoughtTrailDetail', { trailId });
  }, [nav]);

  const handleOneClickCreate = useCallback((rec: TrailRecommendation) => {
    const trailId = createThoughtTrail(rec.name, rec.reason || rec.narrative, rec.reflectionIds, 'ai');
    setRecommendations(prev => prev.filter(r => r !== rec));
    Alert.alert('创建成功', `「${rec.name}」已创建`, [
      { text: '查看详情', onPress: () => nav.navigate('ThoughtTrailDetail', { trailId }) },
      { text: '继续浏览', style: 'cancel' },
    ]);
  }, [createThoughtTrail, nav]);

  const handleCustomCreate = useCallback((rec: TrailRecommendation) => {
    setRecommendations(prev => prev.filter(r => r !== rec));
    nav.navigate('QuickCreateTrail', { selectedIds: rec.reflectionIds });
  }, [nav]);

  const handleNotInterested = useCallback((rec: TrailRecommendation) => {
    const pattern = buildIgnoredPattern(rec);
    addIgnoredRecPattern(pattern);
    // 同时写入 AsyncStorage，确保重启后仍然忽略
    const next = [...new Set([...ignoredPatternsRef.current, pattern])];
    ignoredPatternsRef.current = next;
    safeSetItem(TRAIL_IGNORED_KEY, JSON.stringify(next)).catch((e) => log.error(e));
    // 触发 allIgnoredPatterns 重新计算
    setIgnoredVersion(k => k + 1);
    setRecommendations(prev => prev.filter(r => r !== rec));
  }, [addIgnoredRecPattern]);

  const handleRefresh = useCallback(() => {
    setRefreshKey(k => k + 1);
  }, []);

  const handleDeleteTrail = useCallback((trailId: string, trailName: string) => {
    Alert.alert(
      '删除思维脉络',
      `确定要删除「${trailName}」吗？`,
      [
        { text: '取消', style: 'cancel' },
        {
          text: '删除',
          style: 'destructive',
          onPress: () => deleteThoughtTrail(trailId),
        },
      ]
    );
  }, [deleteThoughtTrail]);

  // Smart query handlers
  const handleSmartQuery = useCallback(async (text?: string) => {
    const trimmed = (text ?? inputText).trim();
    if (!trimmed) {
      setSmartResult(null);
      setQueryResults([]);
      setShowQueryPanel(false);
      return;
    }

    // 短输入：直接跳转
    if (trimmed.length <= 6) {
      setInputText('');
      nav.navigate('QuickCreateTrail', { initialText: trimmed });
      return;
    }

    // 长输入：智能查询
    setShowQueryPanel(true);
    setIsSmartParsing(true);

    // Cancel previous smart query
    if (smartAbortRef.current) {
      smartAbortRef.current.abort();
    }
    const controller = new AbortController();
    smartAbortRef.current = controller;

    if (!aiAvailable) {
      const localResults = matchByKeyword(trimmed, reflections);
      setQueryResults(localResults);
      setIsSmartParsing(false);
      return;
    }

    try {
      const result = await parseSmartQuery(reflections, trimmed, chatHistoryRef.current, { signal: controller.signal });
      if (controller.signal.aborted) return;
      setSmartResult(result);

      if (result.question && chatHistoryRef.current.length < 3) {
        setIsSmartParsing(false);
        return;
      }

      const filters: TrailFilters = {
        timeRange: result.filters.timeRange || 'all',
        tags: result.filters.tags || [],
        moods: result.filters.moods || [],
      };
      const filteredCandidates = computeCandidatePool(reflections, filters);
      const topic = result.topic || trimmed;

      const aiResults = await matchReflectionsToTopic(filteredCandidates, topic, { signal: controller.signal });
      if (controller.signal.aborted) return;
      const localResults = matchByKeyword(topic, filteredCandidates);

      if (aiResults.length > 0) {
        const aiReflections = aiResults
          .map(r => filteredCandidates[r.reflectionIndex])
          .filter(Boolean);
        const localIds = new Set(localResults.map(r => r.id));
        const merged = [...localResults];
        for (const r of aiReflections) {
          if (!localIds.has(r.id)) merged.push(r);
        }
        setQueryResults(merged);
      } else {
        setQueryResults(localResults);
      }
    } catch (e) {
      if (controller.signal.aborted) return;
      log.debug('SmartQuery error:', e);
      setQueryResults(matchByKeyword(trimmed, reflections));
      setSmartResult(null);
    } finally {
      if (!controller.signal.aborted) {
        setIsSmartParsing(false);
      }
    }
  }, [inputText, reflections, aiAvailable, nav]);

  const handleSmartAnswer = useCallback((answer: string) => {
    setChatHistory(prev => {
      const next = [...prev, answer];
      chatHistoryRef.current = next;
      return next;
    });
    if (smartAnswerTimerRef.current) clearTimeout(smartAnswerTimerRef.current);
    smartAnswerTimerRef.current = setTimeout(() => { void handleSmartQuery(answer); }, 100);
  }, [handleSmartQuery]);

  const handleCloseQueryPanel = useCallback(() => {
    if (smartAbortRef.current) {
      smartAbortRef.current.abort();
    }
    setShowQueryPanel(false);
    setSmartResult(null);
    setQueryResults([]);
    setChatHistory([]);
    setInputText('');
  }, []);

  const handleSubmitEditing = useCallback(() => {
    const text = inputText.trim();
    if (!text) return;

    if (text.length <= 6) {
      setInputText('');
      nav.navigate('QuickCreateTrail', { initialText: text });
    } else {
      void handleSmartQuery(text);
    }
  }, [inputText, nav, handleSmartQuery]);

  // ── FlatList data building ──
  type TrailFlatItem =
    | { type: 'manual-header' }
    | { type: 'manual-empty' }
    | { type: 'manual-trail'; trail: ThoughtTrail; stats: ReturnType<typeof getTrailStats> }
    | { type: 'ai-header' }
    | { type: 'ai-trail'; trail: ThoughtTrail; stats: ReturnType<typeof getTrailStats> }
    | { type: 'rec-header' }
    | { type: 'rec-item'; rec: TrailRecommendation; realIdx: number }
    | { type: 'rec-refresh' }
    | { type: 'rec-empty' };

  const trailFlatData: TrailFlatItem[] = useMemo(() => {
    const items: TrailFlatItem[] = [];

    // Manual Trails section
    items.push({ type: 'manual-header' });
    if (manualTrails.length === 0) {
      items.push({ type: 'manual-empty' });
    } else {
      for (const trail of manualTrails) {
        items.push({ type: 'manual-trail', trail, stats: getTrailStats(trail, reflections) });
      }
    }

    // AI Trails section
    if (aiTrails.length > 0) {
      items.push({ type: 'ai-header' });
      for (const trail of aiTrails) {
        items.push({ type: 'ai-trail', trail, stats: getTrailStats(trail, reflections) });
      }
    }

    // Recommendations section
    items.push({ type: 'rec-header' });
    if (visibleRecs.length > 0) {
      visibleRecs.forEach((rec, _i) => {
        items.push({ type: 'rec-item', rec, realIdx: recommendations.indexOf(rec) });
      });
      items.push({ type: 'rec-refresh' });
    } else if (!isLoadingRecs) {
      items.push({ type: 'rec-empty' });
    }

    return items;
  }, [manualTrails, aiTrails, visibleRecs, reflections, isLoadingRecs, recommendations]);

  const trailKeyExtractor = useCallback((item: TrailFlatItem, index: number) => {
    if (item.type === 'manual-trail') return `manual-${item.trail.id}`;
    if (item.type === 'ai-trail') return `ai-${item.trail.id}`;
    if (item.type === 'rec-item') return `rec-${item.realIdx}`;
    return `${item.type}-${index}`;
  }, []);

  const renderTrailItem = useCallback(({ item }: ListRenderItemInfo<TrailFlatItem>) => {
    switch (item.type) {
      case 'manual-header':
        return (
          <View style={styles.sectionHeader}>
            <Text style={[styles.sectionTitle, { color: TH.text }]}>
              {T('thoughtTrail')} ({manualTrails.length})
            </Text>
          </View>
        );
      case 'manual-empty':
        return (
          <View style={styles.emptyContainer}>
            <Text style={[styles.emptyText, { color: TH.sub }]}>暂无手动创建的脉络</Text>
          </View>
        );
      case 'manual-trail': {
        const stats = item.stats;
        return (
          <TouchableOpacity
            onPress={() => nav.navigate('ThoughtTrailDetail', { trailId: item.trail.id })}
            style={[styles.trailCard, { backgroundColor: TH.cardSolid, borderColor: TH.border }]}
          >
            <View style={styles.trailCardHeader}>
              <Text style={[styles.trailName, { color: TH.text, flex: 1 }]}>{item.trail.name}</Text>
              <TouchableOpacity
                onPress={() => handleDeleteTrail(item.trail.id, item.trail.name)}
                hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
              >
                <Trash2 size={16} color={TH.sub} />
              </TouchableOpacity>
            </View>
            <Text style={[styles.trailInfo, { color: TH.sub }]}>
              {String(stats.count)} {T('thoughtTrailReflections')}
              {stats.dateRange ? ` · ${stats.dateRange.start} ~ ${stats.dateRange.end}` : ''}
            </Text>
            {stats.moodChanges.length > 0 && (
              <Text style={[styles.moodChanges, { color: TH.sub }]}>
                心情变化: {stats.moodChanges.map(m => getMoodIcon(m)).join(' → ')}
              </Text>
            )}
          </TouchableOpacity>
        );
      }
      case 'ai-header':
        return (
          <View style={styles.sectionHeader}>
            <Text style={[styles.sectionTitle, { color: TH.text }]}>
              AI 创建的脉络 ({aiTrails.length})
            </Text>
          </View>
        );
      case 'ai-trail': {
        const stats = item.stats;
        return (
          <TouchableOpacity
            onPress={() => nav.navigate('ThoughtTrailDetail', { trailId: item.trail.id })}
            style={[styles.trailCard, { backgroundColor: TH.cardSolid, borderColor: TH.border }]}
          >
            <View style={styles.trailCardHeader}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, flex: 1 }}>
                <View style={{
                  backgroundColor: '#8B5CF620', borderRadius: 4,
                  paddingHorizontal: 6, paddingVertical: 2,
                }}>
                  <Text style={{ fontSize: FONT_TINY(), color: '#8B5CF6' }}>AI</Text>
                </View>
                <Text style={[styles.trailName, { color: TH.text, marginBottom: 0 }]}>{item.trail.name}</Text>
              </View>
              <TouchableOpacity
                onPress={() => handleDeleteTrail(item.trail.id, item.trail.name)}
                hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
              >
                <Trash2 size={16} color={TH.sub} />
              </TouchableOpacity>
            </View>
            <Text style={[styles.trailInfo, { color: TH.sub }]}>
              {String(stats.count)} {T('thoughtTrailReflections')}
              {stats.dateRange ? ` · ${stats.dateRange.start} ~ ${stats.dateRange.end}` : ''}
            </Text>
            {stats.moodChanges.length > 0 && (
              <Text style={[styles.moodChanges, { color: TH.sub }]}>
                心情变化: {stats.moodChanges.map(m => getMoodIcon(m)).join(' → ')}
              </Text>
            )}
          </TouchableOpacity>
        );
      }
      case 'rec-header':
        return (
          <View style={styles.sectionHeader}>
            <Text style={[styles.sectionTitle, { color: TH.text }]}>
              推荐思维脉络
            </Text>
            {isLoadingRecs && (
              <Text style={{ fontSize: FONT_TINY(), color: TH.sub }}>加载中...</Text>
            )}
            {isAILoading && !isLoadingRecs && (
              <Text style={{ fontSize: FONT_TINY(), color: TH.primary }}>AI 推荐加载中...</Text>
            )}
          </View>
        );
      case 'rec-item':
        return (
          <RecommendCard
            rec={item.rec}
            onOneClickCreate={handleOneClickCreate}
            onCustomCreate={handleCustomCreate}
            onNotInterested={handleNotInterested}
          />
        );
      case 'rec-refresh':
        return (
          <TouchableOpacity
            onPress={handleRefresh}
            style={{
              flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
              gap: 6, paddingVertical: 12,
            }}
          >
            <RefreshCw size={14} color={TH.primary} />
            <Text style={{ fontSize: FONT_SMALL(), color: TH.primary }}>换一批</Text>
          </TouchableOpacity>
        );
      case 'rec-empty':
        return (
          <View style={styles.emptyContainer}>
            <Text style={[styles.emptyText, { color: TH.sub }]}>暂无推荐</Text>
            <Text style={[styles.emptyText, { color: TH.sub, marginTop: 4 }]}>
              多记录感念后会自动生成推荐
            </Text>
          </View>
        );
    }
    return null;
  }, [
    TH, T, nav, manualTrails, aiTrails, isLoadingRecs, isAILoading,
    handleDeleteTrail, handleOneClickCreate, handleCustomCreate,
    handleNotInterested, handleRefresh,
  ]);

  // ═══════════════════════════════════════════════════════════════
  // Section 5: Render
  // ═══════════════════════════════════════════════════════════════

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={() => nav.goBack()} style={styles.backButton}>
          <ArrowLeft size={24} color={TH.text} />
        </TouchableOpacity>
        <Text style={[styles.headerTitle, { color: TH.text }]}>{T('mindTrail')}</Text>
        <View style={{ width: 40 }} />
      </View>

      {/* Content */}
      <FlatList
        data={trailFlatData}
        renderItem={renderTrailItem}
        keyExtractor={trailKeyExtractor}
        removeClippedSubviews={true}
        style={{ flex: 1 }}
        contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 32 }}
        showsVerticalScrollIndicator={false}
      />

      {/* Smart Query Panel */}
      <SmartQueryPanel
        show={showQueryPanel}
        onClose={handleCloseQueryPanel}
        smartResult={smartResult}
        onSmartAnswer={handleSmartAnswer}
        onSmartQuery={handleSmartQuery}
        isSmartParsing={isSmartParsing}
        queryResults={queryResults}
        onQuickCreate={(selectedIds) => {
          handleCloseQueryPanel();
          nav.navigate('QuickCreateTrail', { selectedIds });
        }}
        chatHistory={chatHistory}
      />

      {/* Bottom Bar */}
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
        <View style={[styles.bottomBar, { backgroundColor: TH.bg, borderTopColor: TH.border }]}>
          <View style={[styles.inputRow, { backgroundColor: TH.card, borderColor: TH.border }]}>
            <Zap size={16} color="#8B5CF6" />
            <TextInput
              style={[styles.input, { color: TH.text }]}
              placeholder="描述你想追踪的思维脉络..."
              placeholderTextColor={TH.sub}
              value={inputText}
              onChangeText={setInputText}
              returnKeyType="send"
              onSubmitEditing={handleSubmitEditing}
            />
            {inputText.length > 0 && (
              <TouchableOpacity onPress={() => { setInputText(''); handleCloseQueryPanel(); }}>
                <X size={16} color={TH.sub} />
              </TouchableOpacity>
            )}
            <TouchableOpacity
              onPress={handleSubmitEditing}
              style={[styles.sendBtn, { backgroundColor: inputText.trim() ? '#8B5CF6' : `${TH.sub}20` }]}
            >
              <Send size={16} color={inputText.trim() ? '#fff' : TH.sub} />
            </TouchableOpacity>
          </View>
          <TouchableOpacity
            onPress={() => setShowCreateModal(true)}
            style={[styles.manualBtn, { borderColor: TH.primary }]}
          >
            <Plus size={18} color={TH.primary} />
            <Text style={[styles.manualBtnText, { color: TH.primary }]}>{T('manualCreateTrail')}</Text>
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>

      {/* Create Modal */}
      <CreateThoughtTrailModal
        visible={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onSuccess={handleCreateTrail}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  backButton: {
    width: 40,
    height: 40,
    justifyContent: 'center',
    alignItems: 'center',
  },
  headerTitle: {
    fontSize: FONT_TITLE(),
    fontWeight: '700',
  },
  tabContent: {
    paddingHorizontal: 16,
  },
  section: {
    marginBottom: 24,
  },
  sectionHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: 12,
    marginBottom: 12,
  },
  sectionTitle: {
    fontSize: FONT_LABEL(),
    fontWeight: '600',
  },
  emptyContainer: {
    alignItems: 'center',
    paddingVertical: 32,
  },
  emptyText: {
    fontSize: FONT_BODY(),
  },
  trailCard: {
    padding: 16,
    borderRadius: 12,
    borderWidth: 1,
    marginBottom: 12,
  },
  trailCardHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  trailName: {
    fontSize: FONT_BODY(),
    fontWeight: '600',
    marginBottom: 4,
  },
  trailInfo: {
    fontSize: FONT_SMALL(),
    marginBottom: 4,
  },
  moodChanges: {
    fontSize: FONT_SMALL(),
  },
  queryPanel: {
    paddingHorizontal: 16,
    paddingTop: 12,
    paddingBottom: 8,
    borderTopWidth: 1,
  },
  bottomBar: {
    paddingHorizontal: 16,
    paddingTop: 10,
    paddingBottom: 24,
    borderTopWidth: 1,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 12,
    borderWidth: 1,
    paddingHorizontal: 12,
    paddingVertical: 8,
    gap: 8,
  },
  input: {
    flex: 1,
    fontSize: FONT_BODY(),
    paddingVertical: 4,
  },
  sendBtn: {
    width: 32,
    height: 32,
    borderRadius: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  manualBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 6,
    marginTop: 8,
    paddingVertical: 12,
    borderRadius: 10,
    borderWidth: 1,
  },
  manualBtnText: {
    fontSize: FONT_BODY(),
    fontWeight: '600',
  },
});

import {FONT_TITLE, FONT_BODY, FONT_SMALL, FONT_TINY, FONT_BUTTON,
  getMoodIcon, generateTrailName, formatDateShort, scaleFontSize, FONT_HERO} from '@egoless-do/core';
import type { MindReflection } from '@egoless-do/core';
import { useNavigation, useRoute, RouteProp } from '@react-navigation/native';
import { StackNavigationProp } from '@react-navigation/stack';
import {
  ArrowLeft, X, Send, Check, ChevronDown,
  RefreshCw, Plus, Sparkles, Loader2,
} from 'lucide-react-native';
import React, { useState, useMemo, useCallback } from 'react';
import {
  View, Text, ScrollView, TouchableOpacity, TextInput,
  KeyboardAvoidingView, Platform, StyleSheet,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import type { RootStackParamList } from '../../../navigation/types';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';
import { FilterTags } from '../core/FilterTags';
import { useQuickTrailSearch, type TimeRange } from '../hooks/useQuickTrailSearch';
import { AIAnalysisStream, createAnalysisMessages } from '../insights/AIAnalysisStream';
import InsightPanel from '../insights/InsightPanel';
import { SmartQueryBubble } from '../insights/SmartQueryBubble';
import SelectionSummary from '../shared/SelectionSummary';

import ReflectionCheckItem from './ReflectionCheckItem';

const TIME_RANGE_OPTIONS: { key: TimeRange; labelKey: string }[] = [
  { key: 'week', labelKey: 'freqThisWeek' },
  { key: 'month', labelKey: 'freqThisMonth' },
  { key: '3months', labelKey: 'last3Months' },
  { key: 'all', labelKey: 'allTime' },
];

export default function QuickCreateTrailScreen() {
  const TH = useTheme();
  const T = useT();
  const nav = useNavigation<StackNavigationProp<RootStackParamList>>();
  const route = useRoute<RouteProp<RootStackParamList, 'QuickCreateTrail'>>();
  const { reflections: rawReflections, aiMode, aiModels, createThoughtTrail } = useShallowStore(s => ({
    reflections: s.reflections,
    aiMode: s.aiMode,
    aiModels: s.aiModels,
    createThoughtTrail: s.createThoughtTrail,
  }));

  const initialText = route.params?.initialText ?? '';
  const initialSelectedIds = route.params?.selectedIds ?? [];

  const reflections = useMemo(() =>
    (rawReflections ?? []).filter(r => !r.deleted),
    [rawReflections]
  );

  const aiConfig = useMemo(() => ({
    mode: aiMode,
    models: aiModels,
  }), [aiMode, aiModels]);

  const {
    searchQuery, setSearchQuery,
    timeRange, setTimeRange,
    selectedTags, setSelectedTags, toggleTag,
    selectedMoods, setSelectedMoods, toggleMood,
    matchMode, matchResults,
    smartResult, setSmartResult,
    analysisSteps, isAnalyzing,
    aiDegraded,
    selectedIds, setSelectedIds,
    trailName, setTrailName,
    page, setPage,
    searchHistory,
    isAISearching,
    chatHistory,
    reflectionsMap, userTags, userMoods, aiAvailable,
    selectedReflections, selectedMoodsList, selectedDateRange,
    PAGE_SIZE,
    handleSmartQuery, handleAISearch, handleSmartAnswer, handleClear,
    handleLocalSearch, handleRemoveFilter,
    resetFilters,
  } = useQuickTrailSearch(reflections, initialText, T, aiConfig);

  // ── UI-only state ─────────────────────────────────────────────
  const [showTimeDropdown, setShowTimeDropdown] = useState(false);
  const [showTagDropdown, setShowTagDropdown] = useState(false);
  const [showMoodDropdown, setShowMoodDropdown] = useState(false);
  const [skipThreshold, setSkipThreshold] = useState(false);
  const [showPreview, setShowPreview] = useState(initialSelectedIds.length > 0);

  // ── Selection with initial IDs ────────────────────────────────
  const initializedRef = React.useRef(false);
  if (!initializedRef.current && initialSelectedIds.length > 0) {
    setSelectedIds(new Set(initialSelectedIds));
    initializedRef.current = true;
  }

  // Auto-generate trail name when selection changes
  React.useEffect(() => {
    if (selectedIds.size > 0 && !trailName) {
      const name = generateTrailName(selectedReflections, T);
      setTrailName(name);
    } else if (selectedIds.size === 0) {
      setTrailName('');
    }
  }, [selectedIds.size, selectedReflections, trailName, T]);

  // ── Component-level handlers ──────────────────────────────────
  const toggleSelect = useCallback((id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, [setSelectedIds]);

  const handleSelectAll = useCallback(() => {
    setSelectedIds(new Set(matchResults.map(r => r.id)));
  }, [matchResults, setSelectedIds]);

  const handleDeselectAll = useCallback(() => {
    setSelectedIds(new Set());
  }, [setSelectedIds]);

  const handleOnlyUnassigned = useCallback(() => {
    const list = matchResults.filter(r => !r.thoughtTrailIds?.length).map(r => r.id);
    setSelectedIds(new Set(list));
  }, [matchResults, setSelectedIds]);

  const handleCreate = useCallback(() => {
    const ids = Array.from(selectedIds);
    if (ids.length === 0) return;

    const name = trailName || generateTrailName(
      ids.map(id => reflectionsMap.get(id)).filter(Boolean) as MindReflection[],
      T
    );

    const trailId = createThoughtTrail(name, '', ids, 'manual');

    setSelectedIds(new Set());
    setTrailName('');
    nav.navigate('ThoughtTrailDetail', { trailId });
  }, [selectedIds, trailName, reflectionsMap, createThoughtTrail, nav, T, setSelectedIds, setTrailName]);

  const handleGoRecord = useCallback(() => {
    nav.navigate('Reflections' as never, { showNew: true } as never);
  }, [nav]);

  // ── Render helpers ────────────────────────────────────────────
  const timeRangeLabel = TIME_RANGE_OPTIONS.find(o => o.key === timeRange)?.labelKey ?? 'thisMonth';

  const showInsightPanel = !searchQuery && !showPreview;
  const showMatchResults = matchMode !== 'idle' || searchQuery.length > 0;
  const showPreviewSection = showPreview && selectedIds.size > 0 && !showMatchResults;

  // Empty state: not enough reflections (skip if user chose manual mode)
  if (reflections.length < 5 && !skipThreshold) {
    return (
      <SafeAreaView edges={['top', 'bottom']} style={[styles.safeArea, { backgroundColor: TH.bg }]}>
        {/* Header */}
        <View style={styles.headerRow}>
          <TouchableOpacity onPress={() => nav.goBack()}>
            <ArrowLeft size={24} color={TH.text} />
          </TouchableOpacity>
          <Text style={[styles.title, { color: TH.text }]}>{T('quickCreateTrail')}</Text>
          <TouchableOpacity onPress={() => nav.goBack()}>
            <X size={24} color={TH.sub} />
          </TouchableOpacity>
        </View>

        <View style={styles.emptyCenter}>
          <Text style={styles.emptyEmoji}>📝</Text>
          <Text style={[styles.emptyMessage, { color: TH.text }]}>
            {T('quickTrailNotEnough').replace('{n}', String(reflections.length))}
          </Text>
          <Text style={[styles.emptySubtext, { color: TH.sub }]}>
            {T('quickTrailKeepRecording')}
          </Text>
          <TouchableOpacity
            onPress={() => nav.navigate('Reflections' as never, { showNew: true } as never)}
            style={[styles.emptyGoRecordBtn, { backgroundColor: TH.primary }]}
          >
            <Text style={styles.emptyGoRecordText}>{T('quickTrailGoRecord')}</Text>
          </TouchableOpacity>

          <TouchableOpacity
            onPress={() => setSkipThreshold(true)}
            style={styles.skipBtn}
          >
            <Text style={[styles.smallText, { color: TH.primary }]}>{T('quickTrailManualSelect')} →</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView edges={['top']} style={[styles.safeArea, { backgroundColor: TH.bg }]}>
      <KeyboardAvoidingView style={styles.flex1} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
        {/* Header */}
        <View style={styles.headerRow}>
          <TouchableOpacity onPress={() => nav.goBack()}>
            <ArrowLeft size={24} color={TH.text} />
          </TouchableOpacity>
          <Text style={[styles.title, { color: TH.text }]}>{T('quickCreateTrail')}</Text>
          {selectedIds.size > 0 ? (
            <TouchableOpacity
              onPress={handleCreate}
              style={[styles.createBtnSmall, { backgroundColor: TH.primary }]}
            >
              <Text style={styles.createBtnSmallText}>确认创建</Text>
            </TouchableOpacity>
          ) : (
            <TouchableOpacity onPress={() => nav.goBack()}>
              <X size={24} color={TH.sub} />
            </TouchableOpacity>
          )}
        </View>

        <ScrollView
          style={styles.flex1}
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          onScrollBeginDrag={() => { setShowTimeDropdown(false); setShowTagDropdown(false); setShowMoodDropdown(false); }}
        >
          {/* Backdrop: close dropdowns on tap outside */}
          {(showTimeDropdown || showTagDropdown || showMoodDropdown) && (
            <TouchableOpacity
              activeOpacity={1}
              onPress={() => { setShowTimeDropdown(false); setShowTagDropdown(false); setShowMoodDropdown(false); }}
              style={styles.backdrop}
            />
          )}

          {/* Smart query bubble */}
          {smartResult?.question && chatHistory.length < 3 && (
            <SmartQueryBubble
              question={smartResult.question}
              onAnswer={handleSmartAnswer}
              onSkip={() => {
                setSmartResult(prev => prev ? { ...prev, question: null } : null);
                void handleSmartQuery();
              }}
            />
          )}

          {/* AI Analysis stream */}
          {analysisSteps.length > 0 && (
            <AIAnalysisStream
              messages={createAnalysisMessages(analysisSteps)}
              isAnalyzing={isAnalyzing}
              onComplete={() => {}}
            />
          )}

          {/* Conversation input */}
          <View style={styles.inputSection}>
            <View style={[styles.inputContainer, { backgroundColor: TH.card, borderColor: TH.border }]}>
              <TextInput
                value={searchQuery}
                onChangeText={setSearchQuery}
                onSubmitEditing={handleLocalSearch}
                placeholder={T('quickTrailSearchPlaceholder')}
                placeholderTextColor={TH.sub}
                multiline
                numberOfLines={3}
                textAlignVertical="top"
                style={[styles.textInput, { color: TH.text }]}
                returnKeyType="send"
                blurOnSubmit
              />

              {/* Bottom row: actions */}
              <View style={styles.inputActionsRow}>
                <View style={styles.inputActionsInner}>
                  {searchQuery.length > 0 && (
                    <TouchableOpacity onPress={handleClear} style={styles.clearBtn}>
                      <X size={16} color={TH.sub} />
                    </TouchableOpacity>
                  )}
                  <TouchableOpacity
                    onPress={handleLocalSearch}
                    style={[
                      styles.sendBtn,
                      { backgroundColor: searchQuery.trim() ? TH.primary : `${TH.sub}20` },
                    ]}
                  >
                    <Send size={16} color={searchQuery.trim() ? '#fff' : TH.sub} />
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </View>

          {/* AI on-demand search button */}
          {searchQuery.trim().length > 0 && aiAvailable && (
            <View style={styles.aiSearchSection}>
              <TouchableOpacity
                onPress={handleAISearch}
                disabled={isAISearching}
                style={[
                  styles.aiSearchBtn,
                  {
                    backgroundColor: isAISearching ? `${TH.sub}15` : '#8B5CF615',
                    borderColor: isAISearching ? TH.border : '#8B5CF630',
                    opacity: isAISearching ? 0.7 : 1,
                  },
                ]}
              >
                {isAISearching ? (
                  <Loader2 size={16} color="#8B5CF6" />
                ) : (
                  <Sparkles size={16} color="#8B5CF6" />
                )}
                <Text style={styles.aiSearchBtnText}>
                  {isAISearching ? T('aiSearching') : T('aiSearchButton')}
                </Text>
              </TouchableOpacity>
            </View>
          )}

          {/* Filter row: dropdowns */}
          <View style={styles.filterRow}>
            {/* Time range dropdown */}
            <View style={styles.relativeFlex1}>
              <TouchableOpacity
                onPress={() => { setShowTimeDropdown(!showTimeDropdown); setShowTagDropdown(false); setShowMoodDropdown(false); }}
                style={[
                  styles.dropdownTrigger,
                  {
                    backgroundColor: timeRange !== 'month' ? `${TH.primary}15` : TH.card,
                    borderColor: timeRange !== 'month' ? TH.primary : TH.border,
                  },
                ]}
              >
                <Text style={[styles.smallText, { color: TH.text }]}>{T(timeRangeLabel)}</Text>
                <ChevronDown size={14} color={TH.sub} />
              </TouchableOpacity>
              {showTimeDropdown && (
                <View style={[styles.dropdownMenu, { backgroundColor: TH.card, borderColor: TH.border }]}>
                  {TIME_RANGE_OPTIONS.map(opt => (
                    <TouchableOpacity
                      key={opt.key}
                      onPress={() => {
                        setTimeRange(opt.key);
                        setShowTimeDropdown(false);
                        const label = T(opt.labelKey);
                        setSearchQuery(q => {
                          const cleaned = q.replace(new RegExp(`(?:^|\\s)(?:${TIME_RANGE_OPTIONS.map(o => T(o.labelKey)).join('|')})(?=\\s|$)`, 'g'), '').replace(/\s+/g, ' ').trim();
                          return cleaned ? `${cleaned} ${label}` : label;
                        });
                      }}
                      style={[
                        styles.dropdownItem,
                        { backgroundColor: timeRange === opt.key ? `${TH.primary}15` : 'transparent' },
                      ]}
                    >
                      <Text style={{ fontSize: FONT_SMALL(), color: timeRange === opt.key ? TH.primary : TH.text }}>
                        {T(opt.labelKey)}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>
              )}
            </View>

            {/* Tags dropdown */}
            <View style={styles.relativeFlex1}>
              <TouchableOpacity
                onPress={() => { setShowTagDropdown(!showTagDropdown); setShowTimeDropdown(false); setShowMoodDropdown(false); }}
                style={[
                  styles.dropdownTrigger,
                  {
                    backgroundColor: selectedTags.length > 0 ? `${TH.primary}15` : TH.card,
                    borderColor: selectedTags.length > 0 ? TH.primary : TH.border,
                  },
                ]}
              >
                <Text style={[styles.smallText, { color: TH.text }]}>
                  {selectedTags.length > 0 ? `标签 (${selectedTags.length})` : '标签'}
                </Text>
                <ChevronDown size={14} color={TH.sub} />
              </TouchableOpacity>
              {showTagDropdown && (
                <View style={[styles.dropdownMenuScrollable, { backgroundColor: TH.card, borderColor: TH.border }]}>
                  <ScrollView>
                    <TouchableOpacity
                      onPress={() => setSelectedTags([])}
                      style={[
                        styles.dropdownItem,
                        { backgroundColor: selectedTags.length === 0 ? `${TH.primary}15` : 'transparent' },
                      ]}
                    >
                      <View style={[
                        styles.checkbox,
                        {
                          borderColor: selectedTags.length === 0 ? TH.primary : TH.border,
                          backgroundColor: selectedTags.length === 0 ? TH.primary : 'transparent',
                        },
                      ]}>
                        {selectedTags.length === 0 && <Check size={12} color="#fff" />}
                      </View>
                      <Text style={[styles.smallText, { color: TH.text }]}>全部</Text>
                    </TouchableOpacity>
                    {userTags.map(tag => {
                      const active = selectedTags.includes(tag);
                      return (
                        <TouchableOpacity
                          key={tag}
                          onPress={() => toggleTag(tag)}
                          style={[
                            styles.dropdownItem,
                            { backgroundColor: active ? `${TH.primary}15` : 'transparent' },
                          ]}
                        >
                          <View style={[
                            styles.checkbox,
                            {
                              borderColor: active ? TH.primary : TH.border,
                              backgroundColor: active ? TH.primary : 'transparent',
                            },
                          ]}>
                            {active && <Check size={12} color="#fff" />}
                          </View>
                          <Text style={[styles.smallText, { color: TH.text }]}>{tag}</Text>
                        </TouchableOpacity>
                      );
                    })}
                  </ScrollView>
                </View>
              )}
            </View>

            {/* Moods dropdown */}
            <View style={styles.relativeFlex1}>
              <TouchableOpacity
                onPress={() => { setShowMoodDropdown(!showMoodDropdown); setShowTimeDropdown(false); setShowTagDropdown(false); }}
                style={[
                  styles.dropdownTrigger,
                  {
                    backgroundColor: selectedMoods.length > 0 ? '#8B5CF615' : TH.card,
                    borderColor: selectedMoods.length > 0 ? '#8B5CF6' : TH.border,
                  },
                ]}
              >
                <Text style={[styles.smallText, { color: TH.text }]}>
                  {selectedMoods.length > 0 ? `心情 (${selectedMoods.length})` : '心情'}
                </Text>
                <ChevronDown size={14} color={TH.sub} />
              </TouchableOpacity>
              {showMoodDropdown && (
                <View style={[styles.dropdownMenuScrollable, { backgroundColor: TH.card, borderColor: TH.border }]}>
                  <ScrollView>
                    <TouchableOpacity
                      onPress={() => setSelectedMoods([])}
                      style={[
                        styles.dropdownItem,
                        { backgroundColor: selectedMoods.length === 0 ? '#8B5CF615' : 'transparent' },
                      ]}
                    >
                      <View style={[
                        styles.checkboxMood,
                        {
                          borderColor: selectedMoods.length === 0 ? '#8B5CF6' : TH.border,
                          backgroundColor: selectedMoods.length === 0 ? '#8B5CF6' : 'transparent',
                        },
                      ]}>
                        {selectedMoods.length === 0 && <Check size={12} color="#fff" />}
                      </View>
                      <Text style={[styles.smallText, { color: TH.text }]}>全部</Text>
                    </TouchableOpacity>
                    {userMoods.map(mood => {
                      const active = selectedMoods.includes(mood);
                      return (
                        <TouchableOpacity
                          key={mood}
                          onPress={() => toggleMood(mood)}
                          style={[
                            styles.dropdownItem,
                            { backgroundColor: active ? '#8B5CF615' : 'transparent' },
                          ]}
                        >
                          <View style={[
                            styles.checkboxMood,
                            {
                              borderColor: active ? '#8B5CF6' : TH.border,
                              backgroundColor: active ? '#8B5CF6' : 'transparent',
                            },
                          ]}>
                            {active && <Check size={12} color="#fff" />}
                          </View>
                          <Text style={[styles.smallText, { color: TH.text }]}>
                            {getMoodIcon(mood)} {mood}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </ScrollView>
                </View>
              )}
            </View>
          </View>

          {/* Smart query filter tags */}
          {smartResult && Object.keys(smartResult.filters).length > 0 && (
            <FilterTags
              filters={smartResult.filters}
              onRemoveFilter={handleRemoveFilter}
              onAddPress={() => { setShowTimeDropdown(true); }}
            />
          )}

          {/* Reset filters */}
          {(selectedTags.length > 0 || selectedMoods.length > 0 || timeRange !== 'month') && (
            <View style={styles.resetFiltersRow}>
              <TouchableOpacity onPress={resetFilters}>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub }}>{T('quickTrailResetFilters')}</Text>
              </TouchableOpacity>
            </View>
          )}

          {/* ── Inline creation panel ── */}
          {selectedIds.size > 0 && (
            <View style={[styles.creationPanel, { backgroundColor: TH.card, borderColor: TH.border }]}>
              <View style={styles.creationPanelHeader}>
                <SelectionSummary
                  count={selectedIds.size}
                  moods={selectedMoodsList}
                  startDate={selectedDateRange?.start}
                  endDate={selectedDateRange?.end}
                />
                <TouchableOpacity
                  onPress={handleCreate}
                  style={[styles.createBtnLarge, { backgroundColor: TH.primary }]}
                >
                  <Text style={styles.createBtnLargeText}>
                    {T('quickTrailCreate')}
                  </Text>
                </TouchableOpacity>
              </View>

              {/* Assigned notice */}
              {(() => {
                const assignedCount = selectedReflections.filter(r => r.thoughtTrailIds && r.thoughtTrailIds.length > 0).length;
                return assignedCount > 0 ? (
                  <Text style={[styles.assignedNotice, { color: TH.sub }]}>
                    ℹ️ {T('quickTrailAssignedNotice').replace('{n}', String(assignedCount))} {T('quickTrailAssignedExplain')}
                  </Text>
                ) : null;
              })()}

              {/* Trail name input */}
              <View style={[styles.trailNameRow, { borderColor: TH.border, backgroundColor: TH.bg }]}>
                <TextInput
                  value={trailName}
                  onChangeText={setTrailName}
                  placeholder={T('quickTrailNamePlaceholder')}
                  placeholderTextColor={TH.sub}
                  style={[styles.trailNameInput, { color: TH.text }]}
                />
                <TouchableOpacity onPress={() => setTrailName(generateTrailName(selectedReflections, T))}>
                  <RefreshCw size={14} color={TH.sub} />
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* ── Preview: pre-selected reflections ── */}
          {showPreviewSection && (
            <View style={styles.previewSection}>
              <View style={[styles.rowBetween, { marginBottom: 12 }]}>
                <Text style={[styles.bodyBold, { color: TH.text }]}>
                  已选感念 · {selectedIds.size}{T('quickTrailReflections')}
                </Text>
                <TouchableOpacity
                  onPress={() => { setShowPreview(false); }}
                  style={styles.addMoreBtn}
                >
                  <Plus size={14} color={TH.primary} />
                  <Text style={[styles.smallTextPrimary, { color: TH.primary }]}>添加更多</Text>
                </TouchableOpacity>
              </View>

              {selectedReflections.map(ref => (
                <View
                  key={ref.id}
                  style={[styles.previewCard, { backgroundColor: TH.card, borderColor: TH.primary }]}
                >
                  {/* Content */}
                  <View style={styles.flex1}>
                    <View style={styles.previewMetaRow}>
                      <Text style={[styles.smallText, { color: TH.sub }]}>
                        {formatDateShort(ref.timestamp)}
                      </Text>
                      <Text style={styles.previewMoodIcon}>{getMoodIcon(ref.mood)}</Text>
                      {ref.tags.slice(0, 2).map(tag => (
                        <Text key={tag} style={[styles.previewTag, { color: TH.primary, backgroundColor: `${TH.primary}15` }]}>
                          {tag}
                        </Text>
                      ))}
                    </View>
                    <Text style={[styles.previewContent, { color: TH.text }]} numberOfLines={2}>
                      {ref.content}
                    </Text>
                  </View>

                  {/* Remove button */}
                  <TouchableOpacity
                    onPress={() => toggleSelect(ref.id)}
                    style={styles.removeBtn}
                  >
                    <X size={18} color={TH.sub} />
                  </TouchableOpacity>
                </View>
              ))}
            </View>
          )}

          {/* ── Insight Panel (empty input) ── */}
          {showInsightPanel && (
            <View style={styles.insightPanelWrapper}>
            <InsightPanel
              visible
              reflections={reflections}
              onTagPress={(tag) => setSearchQuery(tag)}
              onMoodPress={(mood) => setSearchQuery(mood)}
              onGoRecord={handleGoRecord}
            />
            </View>
          )}

          {/* ── Search history ── */}
          {showInsightPanel && searchHistory.length > 0 && (
            <View style={styles.searchHistorySection}>
              <Text style={[styles.searchHistoryLabel, { color: TH.sub }]}>{T('searchHistory')}</Text>
              <View style={styles.searchHistoryTags}>
                {searchHistory.map((q, i) => (
                  <TouchableOpacity
                    key={`${q}-${i}`}
                    onPress={() => setSearchQuery(q)}
                    style={[styles.searchHistoryTag, { backgroundColor: TH.card, borderColor: TH.border }]}
                  >
                    <Text style={[styles.smallText, { color: TH.text }]}>{q}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          )}

          {/* ── Match results section ── */}
          {showMatchResults && (
            <View style={styles.matchResultsSection}>
              {/* AI degradation indicator */}
              {aiDegraded && (
                <View style={styles.aiDegradedBanner}>
                  <Text style={styles.aiDegradedIcon}>⚠️</Text>
                  <Text style={styles.aiDegradedText}>{T('searchDegraded')}</Text>
                </View>
              )}

              <View style={[styles.rowBetween, { marginBottom: 12 }]}>
                <Text style={[styles.bodyBold, { color: TH.text }]}>
                  {T('quickTrailMatch')} · {matchResults.length}{T('quickTrailReflections')}
                </Text>
              </View>

              {matchResults.length > 0 ? (
                <>
                  {/* Bulk actions - top */}
                  <View style={[styles.bulkActionsRow, { borderBottomColor: TH.border }]}>
                    <View style={styles.bulkActionsLeft}>
                      <TouchableOpacity onPress={handleSelectAll}>
                        <Text style={[styles.smallTextPrimary, { color: TH.primary }]}>{T('quickTrailSelectAll')}</Text>
                      </TouchableOpacity>
                      <TouchableOpacity onPress={handleDeselectAll}>
                        <Text style={[styles.smallText, { color: TH.sub }]}>{T('quickTrailDeselectAll')}</Text>
                      </TouchableOpacity>
                      <TouchableOpacity onPress={handleOnlyUnassigned}>
                        <Text style={[styles.smallText, { color: TH.sub }]}>{T('quickTrailOnlyUnassigned')}</Text>
                      </TouchableOpacity>
                    </View>
                    <Text style={[styles.smallText, { color: TH.sub }]}>
                      {T('quickTrailSelected').replace('{n}', String(selectedIds.size))}
                    </Text>
                  </View>

                  {matchResults.slice(0, page * PAGE_SIZE).map(ref => (
                    <ReflectionCheckItem
                      key={ref.id}
                      ref={ref}
                      isSelected={selectedIds.has(ref.id)}
                      onToggle={() => toggleSelect(ref.id)}
                    />
                  ))}

                  {/* Load more button */}
                  {matchResults.length > page * PAGE_SIZE && (
                    <TouchableOpacity
                      onPress={() => setPage(p => p + 1)}
                      style={[styles.loadMoreBtn, { backgroundColor: `${TH.primary}10` }]}
                    >
                      <Text style={[styles.smallText, { color: TH.primary }]}>
                        {T('searchLoadMore').replace('{n}', String(Math.min(PAGE_SIZE, matchResults.length - page * PAGE_SIZE)))}
                      </Text>
                    </TouchableOpacity>
                  )}
                </>
              ) : (
                <View style={styles.noResultsContainer}>
                  <Text style={styles.noResultsEmoji}>🔍</Text>
                  <Text style={[styles.noResultsText, { color: TH.sub }]}>
                    {T('quickTrailNoResults')}
                  </Text>
                  <Text style={[styles.smallText, { color: TH.sub }]}>
                    {T('quickTrailTryAgain')}
                  </Text>
                  <TouchableOpacity onPress={resetFilters} style={styles.noResultsResetBtn}>
                    <Text style={[styles.smallText, { color: TH.primary }]}>{T('quickTrailResetFilters')}</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>
          )}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

