  Pencil, Flame, Target, CalendarDays, Brain, Scale, Droplets,
  Database, LogOut, ChevronRight, Check, X, Camera, Lock, RotateCcw,
  Trophy, Timer, Utensils, Quote, Footprints, ClipboardList, ListChecks,
} from 'lucide-react-native';
import React, { useState, useMemo, useCallback } from 'react';
import {
  View, Text, ScrollView, TouchableOpacity, TextInput, Alert, ActivityIndicator, KeyboardAvoidingView, Platform, Modal,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, useTheme, useT } from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore, type MobileStore } from '../../store/useAppStore';



const log = createLogger('Profile');

export default function ProfileScreen() {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const {
    userProfile, auth, checkinHistory, habits, reflections,
    exerciseLog, fastingHistory, plans, planItems,
    waterGoal, streak, totalMedMinutes,
  } = useShallowStore(s => ({
    userProfile: s.userProfile,
    auth: s.auth,
    checkinHistory: s.checkinHistory,
    habits: s.habits,
    reflections: s.reflections,
    exerciseLog: s.exerciseLog,
    fastingHistory: s.fastingHistory,
    plans: s.plans,
    planItems: s.planItems,
    waterGoal: s.waterGoal,
    streak: s.streak,
    totalMedMinutes: s.totalMedMinutes,
  }));
  const nav = useRootNavigation();

  // Typed helper to avoid ESLint no-unsafe-* warnings on getStore()
  // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call
  const getStore = () => useAppStore.getState() as MobileStore;

  const [editNickname, setEditNickname] = useState(userProfile.nickname ?? '');
  const [editingNickname, setEditingNickname] = useState(false);
  const [editMotto, setEditMotto] = useState(userProfile.motto ?? '');
  const [editingMotto, setEditingMotto] = useState(false);
  const [editWeight, setEditWeight] = useState(userProfile.weight != null ? String(userProfile.weight) : '');
  const [editHeight, setEditHeight] = useState(userProfile.height != null ? String(userProfile.height) : '');
  const [editGender, setEditGender] = useState<'male' | 'female' | 'private'>(userProfile.gender ?? 'private');
  const [editWaterGoal, setEditWaterGoal] = useState(String(waterGoal));
  const [clearing, setClearing] = useState(false);
  const [resetting, setResetting] = useState(false);
  const [pwdModalVisible, setPwdModalVisible] = useState(false);
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [pwdChanging, setPwdChanging] = useState(false);
  const [pwdError, setPwdError] = useState('');

  const weightUnit = useShallowStore(s => s.weightUnit);
  const setWeightUnit = useShallowStore(s => s.setWeightUnit);

  const profileStats = useMemo(() => {
    const totalCheckinDays = (checkinHistory ?? []).filter(c => c.done && !c.deleted).length;
    const activeHabits = (habits ?? []).filter(h => !h.deleted && h.status !== 'archived').length;
    const totalReflections = (reflections ?? []).filter(r => !r.deleted).length;
    return { totalCheckinDays, activeHabits, totalReflections };
  }, [checkinHistory, habits, reflections]);

  const journeyStats = useMemo(() => {
    const createdAt = auth.user?.createdAt;
    const joinedDays = createdAt ? Math.max(1, Math.floor((Date.now() - createdAt) / 86400000)) : 0;
    // Longest streak
    const history = (checkinHistory ?? []).filter(c => !c.deleted);
    let longestStreak = 0, current = 0;
    for (const c of history) { if (c.done) { current++; longestStreak = Math.max(longestStreak, current); } else { current = 0; } }
    // Total exercise hours
    const totalExerciseSec = (exerciseLog ?? []).filter(e => !e.deleted).reduce((s, e) => s + e.durationSec, 0);
    const totalExerciseHours = Math.round(totalExerciseSec / 3600);
    // Total fasting hours
    const totalFastingMs = (fastingHistory ?? []).filter(f => !f.deleted && f.endedAt).reduce((s, f) => s + ((f.endedAt ?? 0) - f.startedAt), 0);
    const totalFastingHours = Math.round(totalFastingMs / 3600000);
    // Plans & tasks
    const totalPlans = (plans ?? []).filter(p => !p.deleted).length;
    const totalPlanItems = (planItems ?? []).filter(i => !i.deleted).length;
    return { joinedDays, longestStreak, totalExerciseHours, totalFastingHours, totalPlans, totalPlanItems };
  }, [auth.user?.createdAt, checkinHistory, exerciseLog, fastingHistory, plans, planItems]);

  const displayName = userProfile.nickname ?? auth.user?.name ?? T('settingsDefaultName');
  const avatarUri = userProfile.avatar;

  const pickAvatar = async () => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access
      const permStatus = (await ImagePicker.requestMediaLibraryPermissionsAsync()).status;
      if (permStatus !== 'granted') {
        Alert.alert(T('profilePermDenied'), T('profilePermDeniedMsg'));
        return;
      }
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ['images'],
        allowsEditing: true,
        aspect: [1, 1],
        quality: 0.5,
        base64: true,
      });
      if (!result.canceled && result.assets[0]) {
        const asset = result.assets[0];
        // Resize to ~200x200 to keep base64 small for sync
        const base64 = `data:image/jpeg;base64,${asset.base64}`;
        getStore().updateUserProfile({ avatar: base64 });
      }
    } catch (e) {
      log.error(e, { message: 'Avatar pick error' });
    }
  };

  const removeAvatar = () => {
    getStore().updateUserProfile({ avatar: undefined });
  };

  const saveNickname = () => {
    getStore().updateUserProfile({ nickname: editNickname.trim() || undefined });
    setEditingNickname(false);
  };

  const saveMotto = () => {
    getStore().updateUserProfile({ motto: editMotto.trim() || undefined });
    setEditingMotto(false);
  };

  const saveWeight = useCallback((val: string) => {
    setEditWeight(val);
    const num = val ? parseFloat(val) : undefined;
    if (num !== undefined && !isNaN(num)) {
      getStore().updateUserProfile({ weight: num });
    }
  }, []);

  const saveHeight = useCallback((val: string) => {
    setEditHeight(val);
    const num = val ? parseFloat(val) : undefined;
    if (num !== undefined && !isNaN(num)) {
      getStore().updateUserProfile({ height: num });
    }
  }, []);

  const handleGenderChange = useCallback((gender: 'male' | 'female' | 'private') => {
    setEditGender(gender);
    getStore().updateUserProfile({ gender });
  }, []);

  const saveWaterGoal = useCallback((val: string) => {
    setEditWaterGoal(val);
    const num = parseInt(val, 10);
    if (!isNaN(num) && num > 0) getStore().setWaterGoal(num);
  }, []);

  const handleChangePassword = useCallback(async () => {
    setPwdError('');
    if (!currentPassword) { setPwdError(T('profilePwdCurrentRequired')); return; }
    if (!newPassword) { setPwdError(T('profilePwdNewRequired')); return; }
    const validationError = validatePassword(newPassword);
    if (validationError) { setPwdError(validationError); return; }
    if (newPassword !== confirmPassword) { setPwdError(T('profilePwdNotMatch')); return; }
    setPwdChanging(true);
    try {
      const token = getStore().auth.token;
      if (!token) { setPwdError(T('profilePwdAuthError')); setPwdChanging(false); return; }
      await apiChangePassword(token, currentPassword, newPassword);
      setPwdModalVisible(false);
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      // Clear auth state — server already blacklisted old token and revoked refresh tokens
      await getStore().logout?.();
      Alert.alert(
        T('commonSuccess'),
        T('profilePwdChanged'),
        [{ text: T('commonOk') }],
      );
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : T('profilePwdChangeFailed');
      setPwdError(msg);
    } finally {
      setPwdChanging(false);
    }
  }, [currentPassword, newPassword, confirmPassword, T, nav]);

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: TH.bg }}>
      <SimpleHeader routeName="Profile" />
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
      <ScrollView
        contentContainerStyle={{ padding: 16, paddingBottom: 60 }}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
      >
        {/* Avatar + Name */}
        <Card style={{ marginBottom: 12 }}>
          <View style={{ alignItems: 'center', gap: 12 }}>
            <TouchableOpacity accessibilityLabel={'更换头像'} onPress={pickAvatar} onLongPress={avatarUri ? removeAvatar : undefined}>
              <View style={{
                width: 80, height: 80, borderRadius: 40,
                backgroundColor: `${P}30`,
                alignItems: 'center', justifyContent: 'center',
                overflow: 'hidden',
              }}>
                {avatarUri ? (
                  <Image source={{ uri: avatarUri }} style={{ width: 80, height: 80, borderRadius: 40 }} contentFit="cover" />
                ) : (
                  <Text style={{ fontSize: scaleFontSize(32), fontWeight: '700', color: P }}>
                    {displayName.charAt(0).toUpperCase()}
                  </Text>
                )}
              </View>
              {/* Camera overlay */}
              <View style={{
                position: 'absolute', bottom: 0, right: 0,
                width: 28, height: 28, borderRadius: 14,
                backgroundColor: P, alignItems: 'center', justifyContent: 'center',
                borderWidth: 2, borderColor: TH.card,
              }}>
                <Camera size={14} color="#fff" />
              </View>
            </TouchableOpacity>

            {editingNickname ? (
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, width: '100%' }}>
                <TextInput
                  value={editNickname}
                  onChangeText={setEditNickname}
                  placeholder={T('settingsNickname')}
                  placeholderTextColor={TH.sub}
                  style={{
                    flex: 1, backgroundColor: TH.bg, borderRadius: 10, padding: 12,
                    color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
                  }}
                />
                <TouchableOpacity accessibilityLabel={T('commonSave')} onPress={saveNickname} style={{ padding: 8 }}>
                  <Check size={22} color={COLORS.GREEN} />
                </TouchableOpacity>
                <TouchableOpacity accessibilityLabel={T('commonCancel')} onPress={() => { setEditingNickname(false); setEditNickname(userProfile.nickname ?? ''); }} style={{ padding: 8 }}>
                  <X size={22} color={TH.sub} />
                </TouchableOpacity>
              </View>
            ) : (
              <TouchableOpacity accessibilityLabel={'编辑昵称'} onPress={() => setEditingNickname(true)} style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE() }}>{displayName}</Text>
                <Pencil size={14} color={TH.sub} />
              </TouchableOpacity>
            )}

            <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
              {auth.user?.email ?? ''}
            </Text>

            {/* Motto — in user card */}
            {editingMotto ? (
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, width: '100%' }}>
                <TextInput
                  value={editMotto}
                  onChangeText={setEditMotto}
                  placeholder={T('profileMottoPlaceholder')}
                  placeholderTextColor={TH.sub}
                  style={{
                    flex: 1, backgroundColor: TH.bg, borderRadius: 10, padding: 10,
                    color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
                    fontStyle: 'italic',
                  }}
                />
                <TouchableOpacity accessibilityLabel={T('commonSave')} onPress={saveMotto} style={{ padding: 6 }}>
                  <Check size={20} color={COLORS.GREEN} />
                </TouchableOpacity>
                <TouchableOpacity accessibilityLabel={T('commonCancel')} onPress={() => { setEditingMotto(false); setEditMotto(userProfile.motto ?? ''); }} style={{ padding: 6 }}>
                  <X size={20} color={TH.sub} />
                </TouchableOpacity>
              </View>
            ) : (
              <TouchableOpacity accessibilityLabel={'编辑座右铭'} onPress={() => setEditingMotto(true)} style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginTop: 4 }}>
                <Quote size={14} color={P} />
                <Text style={{ color: userProfile.motto ? TH.text : TH.sub, fontSize: FONT_SUB(), fontStyle: 'italic', flex: 1 }}>
                  {userProfile.motto || T('profileMottoPlaceholder')}
                </Text>
                <Pencil size={10} color={TH.sub} />
              </TouchableOpacity>
            )}
          </View>
        </Card>

        {/* Body data */}
        <Card style={{ marginBottom: 12 }}>
          <Text style={{ color: TH.sub, fontSize: FONT_SUB(), fontWeight: '600', marginBottom: 12 }}>
            {T('profileBodyData')}
          </Text>

          {/* Weight */}
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12, gap: 8 }}>
            <Scale size={18} color={P} />
            <Text style={{ color: TH.text, fontSize: FONT_BODY(), width: 60 }}>{T('profileWeight')}</Text>
            <TextInput
              value={editWeight}
              onChangeText={saveWeight}
              placeholder="—"
              placeholderTextColor={TH.sub}
              keyboardType="numeric"
              style={{
                flex: 1, backgroundColor: TH.bg, borderRadius: 10, padding: 10,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
                textAlign: 'center',
              }}
            />
            <TouchableOpacity
              accessibilityLabel={T('settingsSelectWeightUnit')}
              onPress={() => Alert.alert(T('settingsWeightUnit'), '', [
                { text: T('weightUnitKg'), onPress: () => setWeightUnit('kg') },
                { text: T('weightUnitLb'), onPress: () => setWeightUnit('lb') },
                { text: T('commonCancel'), style: 'cancel' },
              ])}
              style={{
                paddingHorizontal: 12, paddingVertical: 10,
                backgroundColor: `${P}20`, borderRadius: 10,
              }}
            >
              <Text style={{ color: P, fontSize: FONT_SUB(), fontWeight: '600' }}>{weightUnit}</Text>
            </TouchableOpacity>
          </View>

          {/* Height */}
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12, gap: 8 }}>
            <View style={{ width: 18, alignItems: 'center' }}><Text style={{ fontSize: FONT_LABEL(), color: P }}>📏</Text></View>
            <Text style={{ color: TH.text, fontSize: FONT_BODY(), width: 60 }}>{T('profileHeight')}</Text>
            <TextInput
              value={editHeight}
              onChangeText={saveHeight}
              placeholder="—"
              placeholderTextColor={TH.sub}
              keyboardType="numeric"
              style={{
                flex: 1, backgroundColor: TH.bg, borderRadius: 10, padding: 10,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
                textAlign: 'center',
              }}
            />
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), width: 30, textAlign: 'left' }}>cm</Text>
          </View>

          {/* Gender */}
          <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12, gap: 8 }}>
            <View style={{ width: 18, alignItems: 'center' }}><Text style={{ fontSize: FONT_LABEL(), color: P }}>⚤</Text></View>
            <Text style={{ color: TH.text, fontSize: FONT_BODY(), width: 60 }}>{T('profileGender')}</Text>
            <TouchableOpacity
              accessibilityLabel={T('profileGender')}
              onPress={() => Alert.alert(T('profileGender'), '', [
                { text: T('profileGenderPrivate'), onPress: () => handleGenderChange('private') },
                { text: T('profileGenderMale'), onPress: () => handleGenderChange('male') },
                { text: T('profileGenderFemale'), onPress: () => handleGenderChange('female') },
                { text: T('commonCancel'), style: 'cancel' },
              ])}
              style={{
                flex: 1, paddingVertical: 10, borderRadius: 10,
                backgroundColor: TH.bg, borderWidth: 1, borderColor: TH.border,
                flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between',
                paddingHorizontal: 12,
              }}
            >
              <Text style={{ color: editGender ? TH.text : TH.sub, fontSize: FONT_BODY() }}>
                {editGender ? T(`profileGender${editGender.charAt(0).toUpperCase() + editGender.slice(1)}`) : '—'}
              </Text>
              <ChevronRight size={16} color={TH.sub} />
            </TouchableOpacity>
          </View>

          {/* Water goal */}
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
            <Droplets size={18} color="#3B82F6" />
            <Text style={{ color: TH.text, fontSize: FONT_BODY(), width: 60 }}>{T('profileWaterGoal')}</Text>
            <TextInput
              value={editWaterGoal}
              onChangeText={saveWaterGoal}
              keyboardType="numeric"
              style={{
                flex: 1, backgroundColor: TH.bg, borderRadius: 10, padding: 10,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
                textAlign: 'center',
              }}
            />
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), width: 30 }}>ml</Text>
          </View>
        </Card>

        {/* Journey */}
        <Card style={{ marginBottom: 12 }}>
          <Text style={{ color: TH.sub, fontSize: FONT_SUB(), fontWeight: '600', marginBottom: 12 }}>
            {T('profileJourney')}
          </Text>
          <View style={{ height: 1, backgroundColor: TH.border, marginBottom: 12 }} />
          {/* Stats rows */}
          {[
            { icon: <CalendarDays size={16} color="#10B981" />, value: `${journeyStats.joinedDays} ${T('calendarDays')}`, label: T('profileJoinedDays') },
            { icon: <Flame size={16} color="#F59E0B" />, value: `${streak} ${T('calendarDays')}`, label: T('checkinStreak') },
            { icon: <Trophy size={16} color="#F59E0B" />, value: `${journeyStats.longestStreak} ${T('calendarDays')}`, label: T('profileLongestStreak') },
            { icon: <CalendarDays size={16} color="#10B981" />, value: `${profileStats.totalCheckinDays} ${T('calendarDays')}`, label: T('globalPulse.totalDays') },
            { icon: <Target size={16} color={P} />, value: `${profileStats.activeHabits}`, label: T('habits') },
            { icon: <Brain size={16} color="#8B5CF6" />, value: `${profileStats.totalReflections}`, label: T('reflections') },
            { icon: <ClipboardList size={16} color="#3B82F6" />, value: `${journeyStats.totalPlans}`, label: T('plan') },
            { icon: <ListChecks size={16} color="#3B82F6" />, value: `${journeyStats.totalPlanItems}`, label: T('planTodoList') },
            { icon: <Timer size={16} color="#8B5CF6" />, value: `${totalMedMinutes} ${T('medMinutes')}`, label: T('accMed') },
            { icon: <Footprints size={16} color={P} />, value: `${journeyStats.totalExerciseHours} ${T('medMinutes')}`, label: T('profileTotalExercise') },
            { icon: <Utensils size={16} color="#EF4444" />, value: `${journeyStats.totalFastingHours} ${T('medMinutes')}`, label: T('profileTotalFasting') },
          ].map((s, i, arr) => (
            <View key={i} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 8, borderBottomWidth: i < arr.length - 1 ? 1 : 0, borderBottomColor: TH.border }}>
              {s.icon}
              <Text style={{ color: TH.text, fontSize: FONT_BODY(), flex: 1, marginLeft: 10 }}>{s.label}</Text>
              <Text style={{ color: P, fontSize: FONT_BODY(), fontWeight: '600' }}>{s.value}</Text>
            </View>
          ))}
        </Card>

        {/* Account */}
        <Card style={{ marginBottom: 12 }}>
          <Text style={{ color: TH.sub, fontSize: FONT_SUB(), fontWeight: '600', marginBottom: 8 }}>
            {T('profileAccount')}
          </Text>
          <TouchableOpacity
            accessibilityLabel={T('profileChangePassword')}
            onPress={() => setPwdModalVisible(true)}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12 }}
          >
            <Lock size={18} color={P} style={{ marginRight: 12 }} />
            <Text style={{ color: P, fontSize: FONT_BODY(), flex: 1 }}>{T('profileChangePassword')}</Text>
          </TouchableOpacity>
          <View style={{ height: 1, backgroundColor: TH.border }} />
          <TouchableOpacity
            accessibilityLabel={T('settingsResetData')}
            disabled={resetting}
            onPress={() => {
              Alert.alert(
                T('settingsResetConfirmTitle'),
                T('settingsResetConfirmMsg'),
                [
                  { text: T('commonCancel'), style: 'cancel' },
                  {
                    text: T('settingsResetData'),
                    style: 'destructive',
                    onPress: async () => {
                      try {
                        setResetting(true);
                        const { forceFullSync } = await import('../sync/SyncService');
                        await forceFullSync();
                        Alert.alert(T('settingsResetDone'), T('settingsResetDoneMsg'));
                      } catch (e) {
                        Alert.alert(T('error') || '错误', String(e));
                      } finally {
                        setResetting(false);
                      }
                    },
                  },
                ],
              );
            }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12 }}
          >
            {resetting
              ? <ActivityIndicator size="small" color={COLORS.RED} style={{ marginRight: 12 }} />
              : <RotateCcw size={18} color={COLORS.RED} style={{ marginRight: 12 }} />
            }
            <Text style={{ color: resetting ? TH.sub : COLORS.RED, fontSize: FONT_BODY(), flex: 1 }}>
              {resetting ? T('clearDataLoading') : T('settingsResetData')}
            </Text>
          </TouchableOpacity>
          <View style={{ height: 1, backgroundColor: TH.border }} />
          <TouchableOpacity
            accessibilityLabel={T('settingsClearData')}
            disabled={clearing}
            onPress={() => {
              Alert.alert(
                T('settingsClearData'),
                T('settingsClearConfirm'),
                [
                  { text: T('commonCancel'), style: 'cancel' },
                  {
                    text: T('settingsClearData'),
                    style: 'destructive',
                    onPress: async () => {
                      setClearing(true);
                      try {
                        await getStore().clearLocalData();
                      } catch {
                        Alert.alert(T('clearDataPushFail'));
                      }
                      setClearing(false);
                    },
                  },
                ],
              );
            }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12 }}
          >
            {clearing
              ? <ActivityIndicator size="small" color={TH.sub} style={{ marginRight: 12 }} />
              : <Database size={18} color="#F59E0B" style={{ marginRight: 12 }} />
            }
            <Text style={{ color: clearing ? TH.sub : '#F59E0B', fontSize: FONT_BODY(), flex: 1 }}>
              {clearing ? T('clearDataLoading') : T('settingsClearData')}
            </Text>
          </TouchableOpacity>
          <View style={{ height: 1, backgroundColor: TH.border }} />
          <TouchableOpacity
            accessibilityLabel={T('settingsLogout')}
            onPress={async () => { await getStore().logout(); nav.reset({ index: 0, routes: [{ name: 'Login' }] }); }}
            style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 12 }}
          >
            <LogOut size={18} color="#EF4444" style={{ marginRight: 12 }} />
            <Text style={{ color: '#EF4444', fontSize: FONT_BODY(), flex: 1 }}>{T('settingsLogout')}</Text>
          </TouchableOpacity>
        </Card>
      </ScrollView>
      </KeyboardAvoidingView>

      {/* Password Change Modal */}
      <Modal visible={pwdModalVisible} transparent animationType="fade" onRequestClose={() => setPwdModalVisible(false)}>
        <KeyboardAvoidingView style={{ flex: 1, justifyContent: 'center' }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <View style={{
          flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'center',
          padding: 24,
        }}>
          <ScrollView
            contentContainerStyle={{ flexGrow: 1, justifyContent: 'center' }}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
          <View style={{
            backgroundColor: TH.card, borderRadius: 16, padding: 24,
            shadowColor: '#000', shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.15, shadowRadius: 12,
            elevation: 8,
          }}>
            <Text style={{ color: TH.text, fontSize: FONT_TITLE(), fontWeight: '700', marginBottom: 20, textAlign: 'center' }}>
              {T('profileChangePassword')}
            </Text>

            <TextInput
              value={currentPassword}
              onChangeText={setCurrentPassword}
              placeholder={T('profilePwdCurrent')}
              placeholderTextColor={TH.sub}
              secureTextEntry
              returnKeyType="next"
              blurOnSubmit={false}
              style={{
                backgroundColor: TH.bg, borderRadius: 10, padding: 14, marginBottom: 12,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
              }}
            />

            <TextInput
              value={newPassword}
              onChangeText={setNewPassword}
              placeholder={T('profilePwdNew')}
              placeholderTextColor={TH.sub}
              secureTextEntry
              returnKeyType="next"
              blurOnSubmit={false}
              style={{
                backgroundColor: TH.bg, borderRadius: 10, padding: 14, marginBottom: 12,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
              }}
            />

            <TextInput
              value={confirmPassword}
              onChangeText={setConfirmPassword}
              placeholder={T('profilePwdConfirm')}
              placeholderTextColor={TH.sub}
              secureTextEntry
              returnKeyType="done"
              onSubmitEditing={handleChangePassword}
              style={{
                backgroundColor: TH.bg, borderRadius: 10, padding: 14, marginBottom: 12,
                color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border,
              }}
            />

            {pwdError ? (
              <Text style={{ color: '#EF4444', fontSize: FONT_SUB(), marginBottom: 12, textAlign: 'center' }}>{pwdError}</Text>
            ) : null}

            <View style={{ flexDirection: 'row', gap: 12 }}>
              <TouchableOpacity
                accessibilityLabel={T('commonCancel')}
                onPress={() => { setPwdModalVisible(false); setPwdError(''); setCurrentPassword(''); setNewPassword(''); setConfirmPassword(''); }}
                disabled={pwdChanging}
                style={{
                  flex: 1, paddingVertical: 14, borderRadius: 10,
                  backgroundColor: TH.bg, alignItems: 'center',
                }}
              >
                <Text style={{ color: TH.text, fontSize: FONT_BODY(), fontWeight: '600' }}>{T('commonCancel')}</Text>
              </TouchableOpacity>

              <TouchableOpacity
                accessibilityLabel={T('profilePwdSubmit')}
                onPress={handleChangePassword}
                disabled={pwdChanging}
                style={{
                  flex: 1, paddingVertical: 14, borderRadius: 10,
                  backgroundColor: P, alignItems: 'center',
                  opacity: pwdChanging ? 0.6 : 1,
                }}
              >
                {pwdChanging
                  ? <ActivityIndicator size="small" color="#fff" />
                  : <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: '600' }}>{T('profilePwdSubmit')}</Text>
                }
              </TouchableOpacity>
            </View>
          </View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>
      </Modal>
    </SafeAreaView>
  );
}

import { COLORS, FONT_BODY, FONT_SUB, FONT_BUTTON, FONT_EMPTY, MS_PER_DAY, MS_PER_WEEK } from '@egoless-do/core';
import type { RecycleBinItem, RecycleBinEntityType } from '@egoless-do/core';
import {
  Trash2, RotateCcw, Target, Sparkles, Utensils, Dumbbell, ClipboardList, Clock, Wind,
} from 'lucide-react-native';
import React from 'react';
import {
  View, Text, ScrollView, TouchableOpacity, Alert,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, useTheme, useT, ScreenHeader } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

const EXPIRY_MS = MS_PER_WEEK;

const ENTITY_ICONS: Record<RecycleBinEntityType, React.ComponentType<{ size?: number; color?: string }>> = {
  habit: Target,
  reflection: Sparkles,
  food: Utensils,
  exercise: Dumbbell,
  plan: ClipboardList,
  breath: Wind,
};

const ENTITY_COLORS: Record<RecycleBinEntityType, string> = {
  habit: COLORS.GREEN,
  reflection: '#7C3AED',
  food: COLORS.ORANGE,
  exercise: COLORS.BLUE,
  plan: '#E11D48',
  breath: '#0EA5E9',
};

function getItemName(item: RecycleBinItem): string {
  const d = item.data as unknown as Record<string, unknown>;
  switch (item.entityType) {
    case 'habit': return (d.name as string) ?? '习惯';
    case 'reflection': return ((d.content as string) ?? '').slice(0, 30) || '感念';
    case 'food': return (d.name as string) ?? '饮食';
    case 'exercise': return (d.sportKey as string) ?? '运动';
    case 'plan': return (d.name as string) ?? '计划';
    case 'breath': return (d.presetKey as string) ?? '调息';
    default: return '未知';
  }
}

function getDaysLeft(deletedAt: number): number {
  const remaining = EXPIRY_MS - (Date.now() - deletedAt);
  return Math.max(0, Math.ceil(remaining / MS_PER_DAY));
}

export default function RecycleBinScreen() {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const nav = useRootNavigation();
  const recycleBin = useShallowStore(s => s.recycleBin ?? []);
  const restoreFromRecycleBin = useShallowStore(s => s.restoreFromRecycleBin);
  const removeFromRecycleBin = useShallowStore(s => s.removeFromRecycleBin);
  const emptyRecycleBin = useShallowStore(s => s.emptyRecycleBin);

  const handleRestore = (id: string) => {
    Alert.alert(T('recycleBinRestore'), T('recycleBinRestoreConfirm'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('confirm'), onPress: () => restoreFromRecycleBin(id) },
    ]);
  };

  const handleDelete = (id: string) => {
    Alert.alert(T('recycleBinDelete'), T('recycleBinDeleteConfirm'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('confirm'), style: 'destructive', onPress: () => removeFromRecycleBin(id) },
    ]);
  };

  const handleEmptyAll = () => {
    Alert.alert(T('recycleBinEmptyAll'), T('recycleBinEmptyConfirm'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('confirm'), style: 'destructive', onPress: () => emptyRecycleBin() },
    ]);
  };

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }}>
        <ScreenHeader title={T('recycleBinTitle')} compact onBack={() => nav.goBack()} />

        {recycleBin.length === 0 ? (
          <View style={{ alignItems: 'center', marginTop: 80 }}>
            <Trash2 size={48} color={TH.sub} />
            <Text style={{ color: TH.sub, fontSize: FONT_EMPTY(), marginTop: 16 }}>{T('recycleBinEmpty')}</Text>
          </View>
        ) : (
          <>
            {/* Items */}
            {recycleBin.map(item => {
              const Icon = ENTITY_ICONS[item.entityType] ?? Trash2;
              const color = ENTITY_COLORS[item.entityType] ?? TH.sub;
              const daysLeft = getDaysLeft(item.deletedAt);

              return (
                <Card key={item.id} style={{ marginBottom: 10, padding: 14 }}>
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
                    <View style={{
                      width: 40, height: 40, borderRadius: 12,
                      backgroundColor: `${color}20`, alignItems: 'center', justifyContent: 'center',
                    }}>
                      <Icon size={20} color={color} />
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={{ color: TH.text, fontWeight: '600', fontSize: FONT_BODY() }} numberOfLines={1}>
                        {getItemName(item)}
                      </Text>
                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginTop: 4 }}>
                        <Clock size={12} color={TH.sub} />
                        <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                          {T('recycleBinDaysLeft').replace('{days}', String(daysLeft))}
                        </Text>
                      </View>
                    </View>
                    <View style={{ flexDirection: 'row', gap: 8 }}>
                      <TouchableOpacity
                        onPress={() => handleRestore(item.id)}
                        style={{
                          width: 36, height: 36, borderRadius: 18,
                          backgroundColor: `${COLORS.GREEN}20`, alignItems: 'center', justifyContent: 'center',
                        }}
                      >
                        <RotateCcw size={16} color={COLORS.GREEN} />
                      </TouchableOpacity>
                      <TouchableOpacity
                        onPress={() => handleDelete(item.id)}
                        style={{
                          width: 36, height: 36, borderRadius: 18,
                          backgroundColor: `${COLORS.RED}20`, alignItems: 'center', justifyContent: 'center',
                        }}
                      >
                        <Trash2 size={16} color={COLORS.RED} />
                      </TouchableOpacity>
                    </View>
                  </View>
                </Card>
              );
            })}

            {/* Empty All button */}
            <TouchableOpacity
              onPress={handleEmptyAll}
              style={{
                flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
                gap: 8, paddingVertical: 12, marginTop: 8,
                borderRadius: 12, borderWidth: 1, borderColor: COLORS.RED,
              }}
            >
              <Trash2 size={16} color={COLORS.RED} />
              <Text style={{ color: COLORS.RED, fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('recycleBinEmptyAll')}</Text>
            </TouchableOpacity>
          </>
        )}

        {/* Auto-delete hint */}
        <Text style={{
          color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', marginTop: 24,
        }}>
          {T('recycleBinAutoDelete')}
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

import { THEMES, LANG_LIST, COLORS, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BUTTON, FONT_CLOSE, createLogger, formatDate , FONT_STAT_CARD } from '@egoless-do/core';
import type { ThemeName } from '@egoless-do/core';
import NetInfo from '@react-native-community/netinfo';
import { Image } from 'expo-image';
import {
  BarChart3, CalendarDays, Utensils, Shield, HeartCrack,
  Heart, RefreshCw, Hand, PersonStanding, Trash2,
  Check, X, ChevronRight, Bell, Clock, Globe, Palette,
  Cloud, CloudUpload, History, Info, Lock, ClipboardList,
  Music, Binary, Brain, Dumbbell, Timer, BarChart2,
} from 'lucide-react-native';
import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  View, Text, ScrollView, TouchableOpacity, Modal, Alert, Platform, ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { optIn, optOut } from '../../analytics/posthog';
import { getAnalyticsConsent, setAnalyticsConsent } from '../../analytics/privacy';
import { SyncConflictPanel } from '../../components/SyncConflictPanel';
import TimePickerModal from '../../components/TimePickerModal';
import {
  Card, useTheme, useT, ScreenHeader, RowItem, Toggle,
} from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useAppStore, useShallowStore } from '../../store/useAppStore';


const log = createLogger('Settings');

interface SettingRow {
  label: string;
  sub?: string;
  icon?: React.ReactNode;
  right?: React.ReactNode;
  onPress?: () => void;
  last?: boolean;
}

import { useRootNavigation } from '../../navigation/hooks';
import {
  requestNotificationPermission, scheduleDailyReminder, cancelAllReminders,
} from '../notifications/NotificationService';

export default function SettingsScreen() {
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const {
    theme, setTheme, language, setLanguage,
    auth, userProfile, streak,
    remindEnabled, remindTime, setRemindEnabled, setRemindTime,
  } = useShallowStore(s => ({
    theme: s.theme,
    setTheme: s.setTheme,
    language: s.language,
    setLanguage: s.setLanguage,
    auth: s.auth,
    userProfile: s.userProfile,
    streak: s.streak,
    remindEnabled: s.remindEnabled,
    remindTime: s.remindTime,
    setRemindEnabled: s.setRemindEnabled,
    setRemindTime: s.setRemindTime,
  }));
  const nav   = useRootNavigation();

  const healthSyncEnabled = useShallowStore(s => s.healthSyncEnabled);
  const setHealthSyncEnabled = useShallowStore(s => s.setHealthSyncEnabled);
  const [showTheme, setShowTheme]         = useState(false);
  const [showLang, setShowLang]           = useState(false);
  const [showTimePicker, setShowTimePicker] = useState(false);
  const [timeEdit, setTimeEdit]           = useState(remindTime);
  const [clearing, setClearing]           = useState(false);
  const [analyticsConsent, setAnalyticsConsentState] = useState<'anonymous' | 'necessary' | 'denied'>('necessary');

  useEffect(() => {
    getAnalyticsConsent().then(setAnalyticsConsentState).catch(() => {});
  }, []);

  // Schedule reminder on mount if enabled
  useEffect(() => {
    if (remindEnabled) {
      const [h, m] = remindTime.split(':').map(Number);
      scheduleDailyReminder(h, m).catch((e) => log.error(e));
    }
  }, []);

  // Sync state
  const [online, setOnline]       = useState(true);
  const [syncing, setSyncing]     = useState(false);
  const syncingRef = useRef(false);
  const [lastSyncAt, setLastSyncAt] = useState<number | null>(null);
  const [pendingCount, setPendingCount] = useState(0);
  const syncTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Monitor connectivity
  useEffect(() => {
    const unsub = NetInfo.addEventListener(state => {
      setOnline(state.isConnected ?? false);
    });
    return () => unsub();
  }, []);

  const runSync = useCallback(async () => {
    if (syncingRef.current) return;
    syncingRef.current = true;
    setSyncing(true);
    try {
      const { runSync: runSyncService } = await import('../sync/SyncService');
      await runSyncService();
      setLastSyncAt(Date.now());
      setPendingCount(0);
    } catch (e) {
      log.warn('[Sync] Error:', e);
    }
    syncingRef.current = false;
    setSyncing(false);
  }, []);

  // Periodic sync (fallback when realtime connection is not active)
  const SYNC_FALLBACK_INTERVAL = 5 * 60 * 1000; // 5 minutes
  const onlineRef = useRef(online);
  useEffect(() => { onlineRef.current = online; }, [online]);
  useEffect(() => {
    syncTimerRef.current = setInterval(() => {
      if (onlineRef.current) void runSync();
    }, SYNC_FALLBACK_INTERVAL);
    return () => { if (syncTimerRef.current) clearInterval(syncTimerRef.current); };
  }, [runSync]);

  const triggerSync = () => {
    if (!online) return;
    void runSync();
  };

  const sections: Array<{ title: string; rows: SettingRow[] }> = [
    {
      title: T('settingsRemind'),
      rows: [
        {
          label: T('settingsRemindOn'), icon: <Bell size={20} color={P} />,
          right: <Toggle on={remindEnabled} onChange={async () => {
            try {
              const next = !remindEnabled;
              if (next) {
                const granted = await requestNotificationPermission();
                if (!granted) { Alert.alert(T('notifPermDenied'), T('notifPermDeniedMsg')); return; }
                const [h, m] = remindTime.split(':').map(Number);
                await scheduleDailyReminder(h, m);
              } else {
                await cancelAllReminders();
              }
              setRemindEnabled(next);
            } catch (e) { log.error(e, { message: 'Reminder toggle error' }); }
          }} />,
        },
        {
          label: T('settingsRemindTime'), icon: <Clock size={20} color={P} />,
          right: (
            <TouchableOpacity accessibilityLabel={T('settingsRemindTime')} onPress={() => { setTimeEdit(remindTime); setShowTimePicker(true); }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{remindTime} {T('commonEdit')}</Text>
                <ChevronRight size={14} color={TH.sub} />
              </View>
            </TouchableOpacity>
          ),
          last: true,
        },
      ],
    },
    {
      title: T('settingsData'),
      rows: [
        {
          label: T('settingsStats'), icon: <BarChart3 size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('Stats'),
        },
        {
          label: T('settingsHistory'), icon: <CalendarDays size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('CheckinHistory'),
        },
        {
          label: T('planHistory'), icon: <ClipboardList size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('PlanHistory'),
        },
        {
          label: T('exerciseHistory'), icon: <Dumbbell size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('ExerciseHistory'),
        },
        {
          label: T('meditationHistory'), icon: <Binary size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('MedHistory'),
        },
        {
          label: T('fastingHistory'), icon: <Timer size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('FastHistory'),
        },
        {
          label: T('settingsFoodLog'), icon: <Utensils size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('FoodLog'),
        },
        {
          label: T('settingsGrace'), icon: <Shield size={20} color={P} />, sub: T('settingsGraceDesc'),
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('Grace'),
        },
        {
          label: T('settingsStreakBreak'), icon: <HeartCrack size={20} color={P} />, sub: T('settingsStreakBreakDesc'),
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('StreakBreak'),
        },
        {
          label: T('recycleBin'), icon: <Trash2 size={20} color={P} />, sub: T('recycleBinDesc'),
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('RecycleBin'),
          last: true,
        },
      ],
    },
    {
      title: T('settingsGeneral'),
      rows: [
        {
          label: T('settingsTheme'), icon: <Palette size={20} color={P} />,
          right: (
            <TouchableOpacity accessibilityLabel={T('settingsSelectTheme')} onPress={() => setShowTheme(true)}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{THEMES[theme].name}</Text>
                <ChevronRight size={14} color={TH.sub} />
              </View>
            </TouchableOpacity>
          ),
        },
        {
          label: T('settingsLanguage'), icon: <Globe size={20} color={P} />,
          right: (
            <TouchableOpacity accessibilityLabel={T('settingsSelectLang')} onPress={() => setShowLang(true)}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
                  {LANG_LIST.find(l => l.code === language)?.flag ?? '🇨🇳'}{' '}
                  {LANG_LIST.find(l => l.code === language)?.name ?? T('settingsLanguage')}
                </Text>
                <ChevronRight size={14} color={TH.sub} />
              </View>
            </TouchableOpacity>
          ),
        },
        {
          label: T('settingsAIModel'),
          sub: T('settingsAIModelDesc'),
          icon: <Brain size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('AISettings'),
        },
        {
          label: T('analyticsDataSharing', { default: '分析数据共享' }),
          sub: T('analyticsDataSharingDesc', { default: '发送匿名使用数据帮助改进产品' }),
          icon: <BarChart2 size={20} color={P} />,
          right: <Toggle on={analyticsConsent === 'anonymous'} onChange={async (enabled) => {
            const newConsent = enabled ? 'anonymous' : 'necessary';
            try {
              await setAnalyticsConsent(newConsent);
              setAnalyticsConsentState(newConsent);
              if (enabled) await optIn(); else await optOut();
            } catch {
              // 静默失败
            }
          }} />,
          last: true,
        },
      ],
    },
    {
      title: T('settingsHealthSection'),
      rows: [
        {
          label: T('settingsAppleHealth'),
          sub: healthSyncEnabled ? T('settingsConnected') : T('settingsNotEnabled'),
          icon: <Heart size={20} color={P} />,
          right: <Toggle on={healthSyncEnabled} onChange={async () => {
            try {
              if (!healthSyncEnabled) {
                const { isHealthAvailable, requestHealthPermissions } = await import('../health/HealthService');
                if (!isHealthAvailable()) {
                  Alert.alert(T('healthUnavailable'), T('healthUnavailableMsg'));
                  return;
                }
                const granted = await requestHealthPermissions();
                if (!granted) {
                  Alert.alert(T('healthPermDenied'), T('healthPermDeniedMsg'));
                  return;
                }
                setHealthSyncEnabled(true);
              } else {
                setHealthSyncEnabled(false);
              }
            } catch (e) { log.error(e, { message: 'Health sync toggle error' }); }
          }} />,
          last: true,
        },
      ],
    },
    {
      title: T('settingsSync'),
      rows: [
        {
          label: T('settingsSyncStatus'), icon: <Cloud size={20} color={P} />,
          sub: online ? (syncing ? T('settingsSyncing') : T('settingsConnected')) : T('settingsOffline'),
          right: (
            <View style={{
              width: 8, height: 8, borderRadius: 4,
              backgroundColor: online ? (syncing ? COLORS.YELLOW : COLORS.GREEN) : '#6B7280',
            }} />
          ),
        },
        {
          label: T('settingsPending'), icon: <CloudUpload size={20} color={P} />,
          right: <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{pendingCount} {T('settingsPendingUnit')}</Text>,
        },
        {
          label: T('settingsLastSync'), icon: <History size={20} color={P} />,
          right: (
            <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
              {lastSyncAt
                ? formatDate(new Date(lastSyncAt), language, { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' })
                : T('settingsNeverSync')}
            </Text>
          ),
        },
        {
          label: T('settingsManualSync'),
          icon: <RefreshCw size={20} color={P} />,
          right: (
            <TouchableOpacity accessibilityLabel={T('settingsManualSync')} onPress={triggerSync} disabled={syncing || !online}>
              <Text style={{ color: P, fontSize: FONT_SUB() }}>
                {syncing ? T('settingsSyncing') : T('settingsSyncNow')}
              </Text>
            </TouchableOpacity>
          ),
        },
      ],
    },
    {
      title: T('settingsAbout'),
      rows: [
        {
          label: T('settingsShareFriend'), icon: <Hand size={20} color={P} />,
          sub: T('settingsShareDesc'),
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: async () => {
            try {
              const Sharing = await import('expo-sharing');
              await Sharing.shareAsync('https://egoless-do.app', {
                dialogTitle: T('settingsShareFriend'),
              });
            } catch {
              // Sharing not available
            }
          },
        },
        {
          label: T('settingsVersion'), icon: <Info size={20} color={P} />,
          right: <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>v1.0.0</Text>,
        },
        {
          label: T('settingsPrivacy'), icon: <Lock size={20} color={P} />,
          right: <ChevronRight size={18} color={TH.sub} />,
          onPress: () => nav.navigate('PrivacyPolicy'),
          last: true,
        },
      ],
    },
  ];

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: TH.bg }}>
      <SimpleHeader routeName="Settings" />
      <ScrollView
        contentContainerStyle={{ padding: 16, paddingBottom: 60 }}
        showsVerticalScrollIndicator={false}
      >

        {/* Profile card */}
        <Card style={{ marginBottom: 8 }}>
          <TouchableOpacity accessibilityLabel={T('profileAccount')} onPress={() => auth.isSignedIn && nav.navigate('Profile')}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 14 }}>
              <View style={{
                width: 56, height: 56, borderRadius: 28,
                backgroundColor: `${P}30`,
                alignItems: 'center', justifyContent: 'center',
                overflow: 'hidden',
              }}>
                {userProfile.avatar ? (
                  <Image source={{ uri: userProfile.avatar }} style={{ width: 56, height: 56, borderRadius: 28 }} contentFit="cover" />
                ) : (
                  <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '700', color: P }}>
                    {(userProfile.nickname ?? auth.user?.name ?? '?').charAt(0).toUpperCase()}
                  </Text>
                )}
              </View>
              <View style={{ flex: 1 }}>
                <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE() }}>
                  {userProfile.nickname ?? auth.user?.name ?? T('settingsDefaultName')}
                </Text>
                <Text style={{ color: TH.sub, fontSize: FONT_SUB(), marginTop: 3 }}>
                  {streak} {T('checkinStreak')} · {auth.isSignedIn ? T('settingsConnected') : T('settingsOffline')}
                </Text>
              </View>
              {auth.isSignedIn ? (
                <View style={{
                  paddingHorizontal: 12, paddingVertical: 6,
                  borderRadius: 12, backgroundColor: `${P}20`,
                }}>
                  <Text style={{ color: P, fontSize: FONT_SUB(), fontWeight: '600' }}>{T('settingsFreePlan')}</Text>
                </View>
              ) : (
                <TouchableOpacity
                  accessibilityLabel={T('settingsLogin')}
                  onPress={() => nav.navigate('Login')}
                  style={{
                    paddingHorizontal: 16, paddingVertical: 8,
                    borderRadius: 12, backgroundColor: P,
                  }}>
                  <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '700' }}>{T('settingsLogin')}</Text>
                </TouchableOpacity>
              )}
            </View>
          </TouchableOpacity>
          <TouchableOpacity
            accessibilityLabel={T('musicTitle')}
            onPress={() => nav.navigate('Music')}
            style={{
              flexDirection: 'row', alignItems: 'center', gap: 12,
              marginTop: 14, paddingTop: 14,
              borderTopWidth: 1, borderTopColor: TH.border,
            }}>
            <View style={{
              width: 36, height: 36, borderRadius: 18,
              backgroundColor: `${P}20`,
              alignItems: 'center', justifyContent: 'center',
            }}>
              <Music size={18} color={P} />
            </View>
            <Text style={{ color: TH.text, fontSize: FONT_BODY(), flex: 1 }}>{T('musicTitle')}</Text>
            <ChevronRight size={18} color={TH.sub} />
          </TouchableOpacity>
        </Card>

        <SyncConflictPanel />

        {sections.map(({ title, rows }) => (
          <View key={title} style={{ marginBottom: 4 }}>
            <Text style={{
              color: TH.sub, fontSize: FONT_SUB(), fontWeight: '600',
              paddingVertical: 12, textTransform: 'uppercase', letterSpacing: 1,
            }}>
              {title}
            </Text>
            <Card style={{ padding: 0 }}>
              <View style={{ paddingHorizontal: 16 }}>
                {rows.map((r, i) => (
                  <RowItem key={r.label} {...r} last={r.last ?? i === rows.length - 1} />
                ))}
              </View>
            </Card>
          </View>
        ))}

        {/* Footer brand */}
        <Text style={{
          textAlign: 'center', color: TH.sub,
          fontSize: FONT_SUB(), paddingVertical: 16,
        }}>
          {T('settingsFooter')}
        </Text>
      </ScrollView>

      {/* Time picker modal */}
      <TimePickerModal
        visible={showTimePicker}
        value={timeEdit}
        onConfirm={async (time) => {
          try {
            setRemindTime(time);
            setShowTimePicker(false);
            if (remindEnabled) {
              const [h, m] = time.split(':').map(Number);
              await scheduleDailyReminder(h, m);
            }
          } catch (e) { log.error(e, { message: 'Time picker error' }); }
        }}
        onClose={() => setShowTimePicker(false)}
      />

      {/* Theme picker */}
      <Modal visible={showTheme} transparent animationType="slide">
        <View style={{ flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,.6)' }}>
          <View style={{
            backgroundColor: TH.cardSolid,
            borderTopLeftRadius: 24, borderTopRightRadius: 24,
            padding: 24, paddingBottom: 48,
          }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 20 }}>
              <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE() }}>{T('settingsSelectTheme')}</Text>
              <TouchableOpacity accessibilityLabel={T('commonClose')} onPress={() => setShowTheme(false)}>
                <X size={26} color={TH.sub} />
              </TouchableOpacity>
            </View>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 12 }}>
              {(Object.keys(THEMES) as ThemeName[]).map(key => {
                const th = THEMES[key];
                return (
                  <TouchableOpacity
                    key={key}
                    accessibilityLabel={th.name}
                    onPress={() => { setTheme(key); setShowTheme(false); }}
                    style={{
                      width: '30%', borderRadius: 14, overflow: 'hidden',
                      borderWidth: 2,
                      borderColor: theme === key ? th.primary : 'transparent',
                    }}
                  >
                    <View style={{ height: 60, backgroundColor: th.bg, justifyContent: 'flex-end', padding: 8 }}>
                      <View style={{ width: '60%', height: 5, borderRadius: 3, backgroundColor: th.primary, marginBottom: 4 }} />
                      <View style={{ width: '40%', height: 3, borderRadius: 2, backgroundColor: th.card }} />
                    </View>
                    <View style={{ backgroundColor: TH.card, padding: 6, alignItems: 'center' }}>
                      <Text style={{ color: TH.text, fontSize: FONT_SUB() }}>{th.name}</Text>
                    </View>
                  </TouchableOpacity>
                );
              })}
            </View>
          </View>
        </View>
      </Modal>

      {/* Language picker */}
      <Modal visible={showLang} transparent animationType="slide">
        <View style={{ flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(0,0,0,.6)' }}>
          <View style={{
            backgroundColor: TH.cardSolid,
            borderTopLeftRadius: 24, borderTopRightRadius: 24,
            padding: 24, paddingBottom: 48, maxHeight: '70%',
          }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 20 }}>
              <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE() }}>{T('settingsSelectLang')}</Text>
              <TouchableOpacity accessibilityLabel={T('commonClose')} onPress={() => setShowLang(false)}>
                <X size={26} color={TH.sub} />
              </TouchableOpacity>
            </View>
            {LANG_LIST.map(l => (
              <TouchableOpacity
                key={l.code}
                accessibilityLabel={l.name}
                onPress={() => { setLanguage(l.code); setShowLang(false); }}
                style={{
                  flexDirection: 'row', alignItems: 'center',
                  justifyContent: 'space-between',
                  paddingVertical: 14,
                  borderBottomWidth: 1, borderBottomColor: TH.border,
                }}
              >
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
                  <Text style={{ fontSize: FONT_CLOSE() }}>{l.flag}</Text>
                  <Text style={{ color: TH.text, fontSize: FONT_BODY() }}>{l.name}</Text>
                </View>
                {l.code === language && (
                  <Check size={20} color={P} />
                )}
              </TouchableOpacity>
            ))}
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

import {
  SleepEntry, SleepQuality, WorkState,
  BODY_STATE_PRESETS, MIND_STATE_PRESETS, formatSleepDuration,
  FONT_TITLE, FONT_BODY, FONT_SUB, FONT_LABEL } from '@egoless-do/core';
import { X, Star, Moon, Sun } from 'lucide-react-native';
import React, { useState, useEffect, useCallback } from 'react';
import {
  View, Text, Modal, ScrollView, TouchableOpacity, TextInput,
  KeyboardAvoidingView, Platform, StyleSheet,
} from 'react-native';

import { useTheme, useT } from '../../components/UI';
import { useAppStore, useShallowStore } from '../../store/useAppStore';


interface Props {
  visible: boolean;
  onClose: () => void;
}

/** Parse a "HH:MM" string into today's timestamp (ms). */
function parseHHMM(str: string): number | undefined {
  const m = str.match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return undefined;
  const hours = parseInt(m[1], 10);
  const minutes = parseInt(m[2], 10);
  if (hours > 23 || minutes > 59) return undefined;
  const d = new Date();
  d.setHours(hours, minutes, 0, 0);
  return d.getTime();
}

/** Format a timestamp back to "HH:MM". */
function formatHHMM(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

const WORK_STATES: { key: WorkState; labelKey: string }[] = [
  { key: 'energetic', labelKey: 'sleepWorkEnergetic' },
  { key: 'normal',    labelKey: 'sleepWorkNormal' },
  { key: 'tired',     labelKey: 'sleepWorkTired' },
  { key: 'exhausted', labelKey: 'sleepWorkExhausted' },
];

export default function DiaryModal({ visible, onClose }: Props) {
  const TH    = useTheme();
  const T     = useT();
  const P     = TH.primary;
  const { getTodaySleep, saveSleepDiary, autoSyncHabits } = useShallowStore(s => ({
    getTodaySleep: s.getTodaySleep,
    saveSleepDiary: s.saveSleepDiary,
    autoSyncHabits: s.autoSyncHabits,
  }));

  // ── Form state ──
  const [bedtimeStr, setBedtimeStr] = useState('');
  const [wakeStr, setWakeStr]       = useState('');
  const [quality, setQuality]       = useState<number>(0);
  const [workState, setWorkState]   = useState<WorkState | null>(null);
  const [bodyState, setBodyState]   = useState<string[]>([]);
  const [mindState, setMindState]   = useState<string[]>([]);
  const [customBodyTag, setCustomBodyTag] = useState('');
  const [customMindTag, setCustomMindTag] = useState('');
  const [note, setNote]             = useState('');

  // Pre-fill from today's existing data when modal opens
  useEffect(() => {
    if (!visible) return;
    const today = getTodaySleep();
    if (today) {
      setBedtimeStr(today.bedtimeAt ? formatHHMM(today.bedtimeAt) : '');
      setWakeStr(today.wakeAt ? formatHHMM(today.wakeAt) : '');
      setQuality(today.quality ?? 0);
      setWorkState(today.workState ?? null);
      setBodyState(today.bodyState ?? []);
      setMindState(today.mindState ?? []);
      setNote(today.note ?? '');
    } else {
      // Reset form
      setBedtimeStr('');
      setWakeStr('');
      setQuality(0);
      setWorkState(null);
      setBodyState([]);
      setMindState([]);
      setCustomBodyTag('');
      setCustomMindTag('');
      setNote('');
    }
  }, [visible]);

  // Auto-calculate duration
  const bedtimeAt = parseHHMM(bedtimeStr);
  const wakeAt    = parseHHMM(wakeStr);

  let durationMin: number | undefined;
  if (bedtimeAt != null && wakeAt != null) {
    let diff = wakeAt - bedtimeAt;
    if (diff < 0) diff += 24 * 60 * 60 * 1000; // cross midnight
    durationMin = Math.round(diff / 60000);
  }

  // ── Toggle helpers ──
  const toggleTag = useCallback((list: string[], setList: React.Dispatch<React.SetStateAction<string[]>>, tag: string) => {
    setList(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  }, []);

  const addCustomTag = useCallback((
    tag: string,
    list: string[],
    setList: React.Dispatch<React.SetStateAction<string[]>>,
    clear: () => void,
  ) => {
    const trimmed = tag.trim();
    if (trimmed && !list.includes(trimmed)) {
      setList(prev => [...prev, trimmed]);
      clear();
    }
  }, []);

  // ── Save ──
  const handleSave = useCallback(() => {
    const entry: Partial<SleepEntry> = {};
    if (bedtimeAt != null) entry.bedtimeAt = bedtimeAt;
    if (wakeAt != null)    entry.wakeAt    = wakeAt;
    if (quality > 0)       entry.quality   = quality as SleepQuality;
    if (workState)         entry.workState = workState;
    if (bodyState.length)  entry.bodyState = bodyState;
    if (mindState.length)  entry.mindState = mindState;
    if (note.trim())       entry.note      = note.trim();

    saveSleepDiary(entry);
    autoSyncHabits?.();
    onClose();
  }, [bedtimeAt, wakeAt, quality, workState, bodyState, mindState, note, saveSleepDiary, autoSyncHabits, onClose]);

  // ── Render section label ──
  const SectionLabel = ({ icon, text }: { icon: React.ReactNode; text: string }) => (
    <View style={s.sectionLabel}>
      {icon}
      <Text style={[s.sectionLabelText, { color: TH.text }]}>{text}</Text>
    </View>
  );

  return (
    <Modal visible={visible} transparent animationType="slide">
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        style={s.overlay}
      >
        <View style={[s.sheet, { backgroundColor: TH.cardSolid }]}>
          {/* ── Header ── */}
          <View style={s.header}>
            <Text style={[s.headerTitle, { color: TH.text }]}>填写今日日记</Text>
            <TouchableOpacity onPress={onClose} hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}>
              <X size={24} color={TH.sub} />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={{ paddingBottom: 20 }}>

            {/* ── 1. Bedtime / Wake Time ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Moon size={16} color={P} />} text="入睡 / 起床时间" />
              <View style={s.timeRow}>
                <View style={s.timeCol}>
                  <Text style={[s.timeLabel, { color: TH.sub }]}>
                    <Moon size={12} color={TH.sub} /> 入睡
                  </Text>
                  <TextInput
                    value={bedtimeStr}
                    onChangeText={setBedtimeStr}
                    placeholder="HH:MM"
                    placeholderTextColor={TH.sub}
                    keyboardType="numbers-and-punctuation"
                    maxLength={5}
                    style={[s.timeInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
                  />
                </View>
                <View style={s.timeCol}>
                  <Text style={[s.timeLabel, { color: TH.sub }]}>
                    <Sun size={12} color={TH.sub} /> 起床
                  </Text>
                  <TextInput
                    value={wakeStr}
                    onChangeText={setWakeStr}
                    placeholder="HH:MM"
                    placeholderTextColor={TH.sub}
                    keyboardType="numbers-and-punctuation"
                    maxLength={5}
                    style={[s.timeInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
                  />
                </View>
              </View>
              {durationMin != null && (
                <View style={[s.durationBadge, { backgroundColor: `${P}15` }]}>
                  <Text style={[s.durationText, { color: P }]}>
                    {formatSleepDuration(durationMin)}
                  </Text>
                </View>
              )}
            </View>

            {/* ── 2. Quality Rating ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Star size={16} color={P} />} text="睡眠质量" />
              <View style={s.starRow}>
                {[1, 2, 3, 4, 5].map(i => (
                  <TouchableOpacity key={i} onPress={() => setQuality(i)}>
                    <Star
                      size={32}
                      color={i <= quality ? '#F59E0B' : `${TH.sub}40`}
                      fill={i <= quality ? '#F59E0B' : 'transparent'}
                    />
                  </TouchableOpacity>
                ))}
              </View>
            </View>

            {/* ── 3. Work State (single-select) ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Text style={{ fontSize: FONT_LABEL() }}>💼</Text>} text={T('sleepWorkState') || '工作状态'} />
              <View style={s.chipRow}>
                {WORK_STATES.map(({ key, labelKey }) => {
                  const selected = workState === key;
                  return (
                    <TouchableOpacity
                      key={key}
                      onPress={() => setWorkState(selected ? null : key)}
                      style={[
                        s.chip,
                        {
                          borderColor: selected ? P : TH.border,
                          backgroundColor: selected ? `${P}20` : 'transparent',
                        },
                      ]}
                    >
                      <Text style={[s.chipText, { color: selected ? P : TH.text }]}>
                        {T(labelKey)}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
            </View>

            {/* ── 4. Body State (multi-select) ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Text style={{ fontSize: FONT_LABEL() }}>🏃</Text>} text={T('sleepBodyState') || '身体状态'} />
              <View style={s.chipRow}>
                {BODY_STATE_PRESETS.map(tag => {
                  const selected = bodyState.includes(tag);
                  return (
                    <TouchableOpacity
                      key={tag}
                      onPress={() => toggleTag(bodyState, setBodyState, tag)}
                      style={[
                        s.chip,
                        {
                          borderColor: selected ? P : TH.border,
                          backgroundColor: selected ? `${P}20` : 'transparent',
                        },
                      ]}
                    >
                      <Text style={[s.chipText, { color: selected ? P : TH.text }]}>{tag}</Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              <View style={s.customTagRow}>
                <TextInput
                  value={customBodyTag}
                  onChangeText={setCustomBodyTag}
                  placeholder={T('sleepCustomTag') || '自定义标签'}
                  placeholderTextColor={TH.sub}
                  style={[s.customTagInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
                  onSubmitEditing={() => addCustomTag(customBodyTag, bodyState, setBodyState, () => setCustomBodyTag(''))}
                />
                <TouchableOpacity
                  onPress={() => addCustomTag(customBodyTag, bodyState, setBodyState, () => setCustomBodyTag(''))}
                  style={[s.addTagBtn, { backgroundColor: P }]}
                >
                  <Text style={s.addTagBtnText}>{T('sleepAddTag') || '添加标签'}</Text>
                </TouchableOpacity>
              </View>
              {/* Show custom tags that are not in presets */}
              {bodyState.filter(t => !BODY_STATE_PRESETS.includes(t)).length > 0 && (
                <View style={[s.chipRow, { marginTop: 8 }]}>
                  {bodyState.filter(t => !BODY_STATE_PRESETS.includes(t)).map(tag => (
                    <TouchableOpacity
                      key={tag}
                      onPress={() => toggleTag(bodyState, setBodyState, tag)}
                      style={[s.chip, { borderColor: P, backgroundColor: `${P}20` }]}
                    >
                      <Text style={[s.chipText, { color: P }]}>{tag}</Text>
                      <X size={12} color={P} style={{ marginLeft: 4 }} />
                    </TouchableOpacity>
                  ))}
                </View>
              )}
            </View>

            {/* ── 5. Mind State (multi-select) ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Text style={{ fontSize: FONT_LABEL() }}>🧠</Text>} text={T('sleepMindState') || '心理状态'} />
              <View style={s.chipRow}>
                {MIND_STATE_PRESETS.map(tag => {
                  const selected = mindState.includes(tag);
                  return (
                    <TouchableOpacity
                      key={tag}
                      onPress={() => toggleTag(mindState, setMindState, tag)}
                      style={[
                        s.chip,
                        {
                          borderColor: selected ? P : TH.border,
                          backgroundColor: selected ? `${P}20` : 'transparent',
                        },
                      ]}
                    >
                      <Text style={[s.chipText, { color: selected ? P : TH.text }]}>{tag}</Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              <View style={s.customTagRow}>
                <TextInput
                  value={customMindTag}
                  onChangeText={setCustomMindTag}
                  placeholder={T('sleepCustomTag') || '自定义标签'}
                  placeholderTextColor={TH.sub}
                  style={[s.customTagInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
                  onSubmitEditing={() => addCustomTag(customMindTag, mindState, setMindState, () => setCustomMindTag(''))}
                />
                <TouchableOpacity
                  onPress={() => addCustomTag(customMindTag, mindState, setMindState, () => setCustomMindTag(''))}
                  style={[s.addTagBtn, { backgroundColor: P }]}
                >
                  <Text style={s.addTagBtnText}>{T('sleepAddTag') || '添加标签'}</Text>
                </TouchableOpacity>
              </View>
              {mindState.filter(t => !MIND_STATE_PRESETS.includes(t)).length > 0 && (
                <View style={[s.chipRow, { marginTop: 8 }]}>
                  {mindState.filter(t => !MIND_STATE_PRESETS.includes(t)).map(tag => (
                    <TouchableOpacity
                      key={tag}
                      onPress={() => toggleTag(mindState, setMindState, tag)}
                      style={[s.chip, { borderColor: P, backgroundColor: `${P}20` }]}
                    >
                      <Text style={[s.chipText, { color: P }]}>{tag}</Text>
                      <X size={12} color={P} style={{ marginLeft: 4 }} />
                    </TouchableOpacity>
                  ))}
                </View>
              )}
            </View>

            {/* ── 6. Note ── */}
            <View style={[s.card, { borderColor: `${P}30` }]}>
              <SectionLabel icon={<Text style={{ fontSize: FONT_LABEL() }}>📝</Text>} text={T('sleepNote') || '今日感悟'} />
              <TextInput
                value={note}
                onChangeText={setNote}
                placeholder={T('sleepNotePlaceholder') || '记录今日感悟...'}
                placeholderTextColor={TH.sub}
                multiline
                numberOfLines={3}
                style={[s.noteInput, { color: TH.text, borderColor: TH.border, backgroundColor: TH.card }]}
              />
            </View>

            {/* ── 7. Save Button ── */}
            <TouchableOpacity
              onPress={handleSave}
              style={[s.saveBtn, { backgroundColor: quality > 0 ? P : `${P}50` }]}
              disabled={quality === 0}
            >
              <Text style={s.saveBtnText}>{T('commonSave') || '保存'}</Text>
            </TouchableOpacity>

            {/* Cancel */}
            <TouchableOpacity onPress={onClose} style={[s.cancelBtn, { borderColor: TH.border }]}>
              <Text style={[s.cancelBtnText, { color: TH.sub }]}>{T('commonCancel') || '取消'}</Text>
            </TouchableOpacity>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

