      <View style={{ flex: 1, justifyContent: 'center', padding: 24 }}>
        <View style={[styles.reportCard, { borderColor: `${TH.primary}20` }]}>
          <Text style={[styles.reportTitle, { color: TH.primary }]}>
            {completed ? `🌙 ${T('sleepBarrierComplete')}` : `🌙 ${T('sleepRitual')}`}
          </Text>
          {barrierElapsed > 0 && (
            <View style={styles.reportRow}>
              <Clock size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepDuration')}</Text>
              <Text style={[styles.reportValue, { color: TH.text }]}>{formatSleepDuration(Math.floor(barrierElapsed / 60))}</Text>
            </View>
          )}
          {awayMin > 0 && (
            <View style={styles.reportRow}>
              <Moon size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepAwayTime')}</Text>
              <Text style={[styles.reportValue, { color: awayMin > 5 ? '#EF4444' : '#10B981' }]}>
                {awayMin}{T('sleepMinutes')}
              </Text>
            </View>
          )}
          {quality > 0 && (
            <View style={styles.reportRow}>
              <Star size={16} color="#F59E0B" />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>睡眠质量</Text>
              <Text style={[styles.reportValue, { color: '#F59E0B' }]}>{'★'.repeat(quality)}</Text>
            </View>
          )}
          {validGratitude.length > 0 && (
            <View style={styles.reportRow}>
              <Heart size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepGratitude')}</Text>
              <Text style={[styles.reportValue, { color: TH.text }]}>
                {validGratitude.length}{T('sleepCompleted')}
              </Text>
            </View>
          )}
          {completedPractice.length > 0 && (
            <View style={styles.reportRow}>
              <Wind size={16} color="#8B5CF6" />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>修行记录</Text>
              <Text style={[styles.reportValue, { color: '#8B5CF6' }]}>{completedPractice.join(', ')}</Text>
            </View>
          )}
          {sleepStreak > 0 && (
            <View style={styles.reportRow}>
              <Text style={{ fontSize: FONT_LABEL() }}>🔥</Text>
              <Text style={[styles.reportLabel, { color: TH.sub }]}>连续天数</Text>
              <Text style={[styles.reportValue, { color: '#EF4444' }]}>{sleepStreak} 天</Text>
            </View>
          )}
        </View>

        <View style={styles.reportBtnRow}>
          <TouchableOpacity
            style={[styles.saveBtn, { backgroundColor: TH.primary, flex: 1 }]}
            onPress={onFinish}
          >
            <Text style={styles.saveBtnText}>回到首页</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.saveBtn, { backgroundColor: `${TH.primary}15`, flex: 1, borderWidth: 1, borderColor: `${TH.primary}30` }]}
            onPress={onViewHistory}
          >
            <Text style={[styles.saveBtnText, { color: TH.primary }]}>查看历史</Text>
          </TouchableOpacity>
        </View>
      </View>
    </SafeAreaView>
  );
}

import { dateStr, createLogger } from '@egoless-do/core';
import { useEffect, useRef, useState, useCallback } from 'react';
import { AppState, Platform } from 'react-native';

import { useAppStore, useShallowStore } from '../../store/useAppStore';

const log = createLogger('SleepNotify');

// Lazy-loaded expo-notifications — deferred until first actual use
let _Notifications: typeof import('expo-notifications') | null = null;
let _handlerConfigured = false;

function getNotifications(): typeof import('expo-notifications') {
  if (!_Notifications) {
    _Notifications = require('expo-notifications') as typeof import('expo-notifications');
  }
  // Configure handler once on first access
  if (!_handlerConfigured) {
    _handlerConfigured = true;
    _Notifications.setNotificationHandler({
      handleNotification: async () => ({
        shouldShowBanner: true,
        shouldShowList: true,
        shouldPlaySound: true,
        shouldSetBadge: false,
      }),
    });
  }
  return _Notifications;
}

export function useSleepNotifications() {
  const { sleepGoal, getTodaySleep, saveSleepDiary } = useShallowStore(s => ({
    sleepGoal: s.sleepGoal,
    getTodaySleep: s.getTodaySleep,
    saveSleepDiary: s.saveSleepDiary,
  }));
  const [showBedtimeModal, setShowBedtimeModal] = useState(false);
  const autoRecordTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const appStateRef = useRef(AppState.currentState);

  // Request notification permissions
  const requestPermissions = useCallback(async () => {
    if (Platform.OS === 'web') return false;
    const Notifications = getNotifications();
    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;
    if (existingStatus !== 'granted') {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }
    return finalStatus === 'granted';
  }, []);

  // Schedule sleep reminders
  const scheduleReminders = useCallback(async () => {
    if (!sleepGoal.enabled) return;
    const Notifications = getNotifications();

    // Cancel existing sleep notifications
    await cancelReminders();

    const granted = await requestPermissions();
    if (!granted) {
      log.warn('Notification permission not granted');
      return;
    }

    const [bedHour, bedMin] = sleepGoal.targetBedtime.split(':').map(Number);

    // Reminder 1: before bedtime
    const reminderMin = bedMin - sleepGoal.reminderBeforeMin;
    let reminderHour = bedHour;
    let adjustedMin = reminderMin;
    if (reminderMin < 0) {
      reminderHour = (bedHour - 1 + 24) % 24;
      adjustedMin = reminderMin + 60;
    }

    await Notifications.scheduleNotificationAsync({
      content: {
        title: '🌙 距离目标入睡还有 ' + sleepGoal.reminderBeforeMin + ' 分钟',
        body: '准备放下手机，开始睡眠仪轨',
        data: { type: 'sleep-reminder' },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DAILY,
        hour: reminderHour,
        minute: adjustedMin,
      },
      identifier: 'sleep-reminder-before',
    });

    // Reminder 2: at bedtime
    await Notifications.scheduleNotificationAsync({
      content: {
        title: '🌙 现在是 ' + sleepGoal.targetBedtime + '，该入睡了',
        body: '点击开始睡眠仪轨',
        data: { type: 'sleep-bedtime' },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DAILY,
        hour: bedHour,
        minute: bedMin,
      },
      identifier: 'sleep-reminder-bedtime',
    });

    log.info('Sleep reminders scheduled', { bedtime: sleepGoal.targetBedtime, before: sleepGoal.reminderBeforeMin });
  }, [sleepGoal, requestPermissions]);

  // Cancel sleep notifications
  const cancelReminders = useCallback(async () => {
    const Notifications = getNotifications();
    await Notifications.cancelScheduledNotificationAsync('sleep-reminder-before').catch(() => {});
    await Notifications.cancelScheduledNotificationAsync('sleep-reminder-bedtime').catch(() => {});
  }, []);

  // Handle foreground notification (show modal instead)
  useEffect(() => {
    if (!sleepGoal.enabled) return;
    const Notifications = getNotifications();

    const subscription = Notifications.addNotificationReceivedListener(notification => {
      const type = notification.request.content.data?.type;
      if (type === 'sleep-bedtime') {
        // Show modal instead of notification when app is in foreground
        if (AppState.currentState === 'active') {
          setShowBedtimeModal(true);
          // Start 1-min auto-record timer
          autoRecordTimerRef.current = setTimeout(() => {
            const today = dateStr();
            const existing = getTodaySleep();
            if (!existing) {
              saveSleepDiary({ bedtimeAt: Date.now(), barrierDone: false });
            }
            setShowBedtimeModal(false);
          }, 60000);
        }
      }
    });

    return () => subscription.remove();
  }, [sleepGoal.enabled]);

  // Handle notification tap (when app was in background)
  useEffect(() => {
    if (!sleepGoal.enabled) return;
    const Notifications = getNotifications();

    const subscription = Notifications.addNotificationResponseReceivedListener(response => {
      const type = response.notification.request.content.data?.type;
      if (type === 'sleep-bedtime' || type === 'sleep-reminder') {
        // Navigate to sleep screen - handled by the caller
      }
    });

    return () => subscription.remove();
  }, [sleepGoal.enabled]);

  // Dismiss bedtime modal and cancel auto-record
  const dismissBedtimeModal = useCallback(() => {
    if (autoRecordTimerRef.current) {
      clearTimeout(autoRecordTimerRef.current);
      autoRecordTimerRef.current = null;
    }
    setShowBedtimeModal(false);
  }, []);

  // Start ritual from modal
  const startRitualFromModal = useCallback(() => {
    dismissBedtimeModal();
    // Caller should navigate to barrier
  }, [dismissBedtimeModal]);

  // Schedule/cancel when goal changes
  useEffect(() => {
    if (sleepGoal.enabled) {
      void scheduleReminders();
    } else {
      void cancelReminders();
    }
  }, [sleepGoal.enabled, sleepGoal.targetBedtime, sleepGoal.reminderBeforeMin]);

  return {
    showBedtimeModal,
    dismissBedtimeModal,
    startRitualFromModal,
    scheduleReminders,
    cancelReminders,
    requestPermissions,
  };
}

import { FONT_HERO, FONT_CLOSE, FONT_TITLE } from '@egoless-do/core';
import React, { useEffect, useRef } from 'react';
import { View, Animated, Dimensions, StyleSheet, StatusBar, type TextStyle } from 'react-native';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');
const STAR_COUNT = 80;
const METEOR_COUNT = 3;

interface StarProps {
  x: number;
  y: number;
  size: number;
  delay: number;
}

function Star({ x, y, size, delay }: StarProps) {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.5)).current;
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    const animate = () => {
      Animated.sequence([
        Animated.delay(delay),
        Animated.parallel([
          Animated.timing(opacity, {
            toValue: 1,
            duration: 1000,
            useNativeDriver: true,
          }),
          Animated.spring(scale, {
            toValue: 1,
            friction: 2,
            tension: 40,
            useNativeDriver: true,
          }),
        ]),
      ]).start(() => {
        const twinkle = () => {
          if (!mountedRef.current) return;
          Animated.sequence([
            Animated.timing(opacity, {
              toValue: 0.3 + Math.random() * 0.7,
              duration: 500 + Math.random() * 1000,
              useNativeDriver: true,
            }),
            Animated.timing(opacity, {
              toValue: 1,
              duration: 500 + Math.random() * 1000,
              useNativeDriver: true,
            }),
          ]).start(twinkle);
        };
        twinkle();
      });
    };
    animate();
    return () => { mountedRef.current = false; };
  }, []);

  return (
    <Animated.View
      style={[
        styles.star,
        {
          left: x,
          top: y,
          width: size,
          height: size,
          borderRadius: size / 2,
          opacity,
          transform: [{ scale }],
        },
      ]}
    />
  );
}

function Meteor({ delay }: { delay: number }) {
  const translateX = useRef(new Animated.Value(-100)).current;
  const translateY = useRef(new Animated.Value(-100)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const mountedRef = useRef(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    mountedRef.current = true;
    const animate = () => {
      if (!mountedRef.current) return;
      const startX = Math.random() * SCREEN_WIDTH * 0.5;
      const startY = -50;
      const endX = startX + SCREEN_WIDTH * 0.6;
      const endY = startY + SCREEN_HEIGHT * 0.6;

      translateX.setValue(startX);
      translateY.setValue(startY);

      Animated.sequence([
        Animated.delay(delay),
        Animated.parallel([
          Animated.timing(opacity, {
            toValue: 1,
            duration: 200,
            useNativeDriver: true,
          }),
          Animated.timing(translateX, {
            toValue: endX,
            duration: 800,
            useNativeDriver: true,
          }),
          Animated.timing(translateY, {
            toValue: endY,
            duration: 800,
            useNativeDriver: true,
          }),
        ]),
        Animated.timing(opacity, {
          toValue: 0,
          duration: 300,
          useNativeDriver: true,
        }),
      ]).start(() => {
        if (mountedRef.current) {
          timerRef.current = setTimeout(animate, 2000 + Math.random() * 4000);
        }
      });
    };
    animate();
    return () => { mountedRef.current = false; if (timerRef.current) clearTimeout(timerRef.current); };
  }, []);

  return (
    <Animated.View
      style={[
        styles.meteor,
        {
          opacity,
          transform: [
            { translateX },
            { translateY },
            { rotate: '45deg' },
          ],
        },
      ]}
    />
  );
}

function Nebula() {
  const scale1 = useRef(new Animated.Value(1)).current;
  const scale2 = useRef(new Animated.Value(1)).current;
  const opacity1 = useRef(new Animated.Value(0.3)).current;
  const opacity2 = useRef(new Animated.Value(0.2)).current;

  useEffect(() => {
    let mounted = true;
    const animate1 = () => {
      if (!mounted) return;
      Animated.sequence([
        Animated.parallel([
          Animated.timing(scale1, {
            toValue: 1.2,
            duration: 4000,
            useNativeDriver: true,
          }),
          Animated.timing(opacity1, {
            toValue: 0.5,
            duration: 4000,
            useNativeDriver: true,
          }),
        ]),
        Animated.parallel([
          Animated.timing(scale1, {
            toValue: 1,
            duration: 4000,
            useNativeDriver: true,
          }),
          Animated.timing(opacity1, {
            toValue: 0.3,
            duration: 4000,
            useNativeDriver: true,
          }),
        ]),
      ]).start(animate1);
    };

    const animate2 = () => {
      if (!mounted) return;
      Animated.sequence([
        Animated.parallel([
          Animated.timing(scale2, {
            toValue: 1.3,
            duration: 5000,
            useNativeDriver: true,
          }),
          Animated.timing(opacity2, {
            toValue: 0.4,
            duration: 5000,
            useNativeDriver: true,
          }),
        ]),
        Animated.parallel([
          Animated.timing(scale2, {
            toValue: 1,
            duration: 5000,
            useNativeDriver: true,
          }),
          Animated.timing(opacity2, {
            toValue: 0.2,
            duration: 5000,
            useNativeDriver: true,
          }),
        ]),
      ]).start(animate2);
    };

    animate1();
    const timer = setTimeout(animate2, 2000);
    return () => { mounted = false; clearTimeout(timer); };
  }, []);

  return (
    <>
      <Animated.View
        style={[
          styles.nebula,
          styles.nebula1,
          {
            opacity: opacity1,
            transform: [{ scale: scale1 }],
          },
        ]}
      />
      <Animated.View
        style={[
          styles.nebula,
          styles.nebula2,
          {
            opacity: opacity2,
            transform: [{ scale: scale2 }],
          },
        ]}
      />
    </>
  );
}

interface SplashScreenProps {
  onFinish: () => void;
}

function GlowText({ text, style, delay: baseDelay = 0 }: { text: string; style: TextStyle; delay?: number }) {
  const chars = text.split('');
  const opacities = useRef(chars.map(() => new Animated.Value(0))).current;
  const glows = useRef(chars.map(() => new Animated.Value(0))).current;

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    chars.forEach((_, i) => {
      const delay = baseDelay + i * 120;
      const t = setTimeout(() => {
        Animated.timing(opacities[i], { toValue: 1, duration: 400, useNativeDriver: false }).start();
        Animated.sequence([
          Animated.timing(glows[i], { toValue: 1, duration: 300, useNativeDriver: false }),
          Animated.timing(glows[i], { toValue: 0.4, duration: 600, useNativeDriver: false }),
        ]).start();
      }, delay);
      timers.push(t);
    });
    return () => { timers.forEach(clearTimeout); };
  }, []);

  return (
    <View style={{ flexDirection: 'row', justifyContent: 'center', flexWrap: 'wrap' }}>
      {chars.map((char, i) => {
        const shadowRadius = glows[i].interpolate({
          inputRange: [0, 1],
          outputRange: [4, 25],
        });
        return (
          <Animated.Text
            key={i}
            style={[
              style,
              {
                opacity: opacities[i],
                textShadowRadius: shadowRadius,
              },
            ]}
          >
            {char}
          </Animated.Text>
        );
      })}
    </View>
  );
}

function BreathingText({ text, style, delay: baseDelay = 0 }: { text: string; style: TextStyle; delay?: number }) {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.95)).current;
  const breathe = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    let mounted = true;
    Animated.sequence([
      Animated.delay(baseDelay),
      Animated.parallel([
        Animated.timing(opacity, { toValue: 1, duration: 800, useNativeDriver: true }),
        Animated.spring(scale, { toValue: 1, friction: 8, tension: 30, useNativeDriver: true }),
      ]),
    ]).start(() => {
      const pulse = () => {
        if (!mounted) return;
        Animated.sequence([
          Animated.timing(breathe, { toValue: 1.03, duration: 2000, useNativeDriver: true }),
          Animated.timing(breathe, { toValue: 1, duration: 2000, useNativeDriver: true }),
        ]).start(pulse);
      };
      pulse();
    });
    return () => { mounted = false; };
  }, []);

  return (
    <Animated.Text
      style={[
        style,
        {
          opacity,
          transform: [{ scale: Animated.multiply(scale, breathe) }],
        },
      ]}
    >
      {text}
    </Animated.Text>
  );
}

export default function SplashScreen({ onFinish }: SplashScreenProps) {
  const titleOpacity = useRef(new Animated.Value(0)).current;
  const titleTranslateY = useRef(new Animated.Value(30)).current;
  const titleGlow = useRef(new Animated.Value(0)).current;
  const containerOpacity = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const seq = Animated.sequence([
      Animated.delay(800),
      Animated.parallel([
        Animated.timing(titleOpacity, {
          toValue: 1,
          duration: 1000,
          useNativeDriver: false,
        }),
        Animated.spring(titleTranslateY, {
          toValue: 0,
          friction: 6,
          tension: 40,
          useNativeDriver: false,
        }),
      ]),
      Animated.delay(2500),
      Animated.timing(containerOpacity, {
        toValue: 0,
        duration: 500,
        useNativeDriver: true,
      }),
    ]);
    seq.start(() => {
      onFinish();
    });
    const t = setTimeout(() => {
      Animated.timing(titleGlow, {
        toValue: 1,
        duration: 1200,
        useNativeDriver: false,
      }).start();
    }, 800);
    return () => { seq.stop(); clearTimeout(t); };
  }, []);

  const titleShadowRadius = titleGlow.interpolate({
    inputRange: [0, 1],
    outputRange: [10, 35],
  });

  const stars = useRef<StarProps[]>(
    Array.from({ length: STAR_COUNT }, () => ({
      x: Math.random() * SCREEN_WIDTH,
      y: Math.random() * SCREEN_HEIGHT,
      size: 1 + Math.random() * 3,
      delay: Math.random() * 2000,
    }))
  ).current;

  return (
    <Animated.View style={[styles.container, { opacity: containerOpacity }]}>
      <StatusBar barStyle="light-content" translucent backgroundColor="transparent" />
      
      {/* Background */}
      <View style={styles.background} />

      {/* Nebula effects */}
      <Nebula />

      {/* Stars */}
      {stars.map((star, index) => (
        <Star key={index} {...star} />
      ))}

      {/* Meteors */}
      {Array.from({ length: METEOR_COUNT }, (_, i) => (
        <Meteor key={i} delay={1000 + i * 2000} />
      ))}

      {/* Title */}
      <View style={styles.titleContainer}>
        <Animated.Text
          style={[
            styles.title,
            {
              opacity: titleOpacity,
              transform: [{ translateY: titleTranslateY }],
              textShadowRadius: titleShadowRadius,
            },
          ]}
        >
          心流纪
        </Animated.Text>
        <GlowText
          text="Egoless Do"
          style={styles.subtitle}
          delay={1400}
        />
        <BreathingText
          text="记录每一份觉知"
          style={styles.tagline}
          delay={2200}
        />
      </View>
    </Animated.View>
  );
}

