  CalendarDays, Zap, Dumbbell, TrendingUp, BarChart3,
  Clock, ClipboardList,
 ChevronLeft } from 'lucide-react-native';
import React, { useMemo, useState } from 'react';
import { View, Text, ScrollView, TouchableOpacity, Dimensions, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, useTheme, useT } from '../../components/UI';
import BarChart from '../../components/charts/BarChart';
import CalendarGrid from '../../components/charts/CalendarGrid';
import LineChart from '../../components/charts/LineChart';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';


const CHART_W = Dimensions.get('window').width - 64;

const TABS = ['overview', 'plan', 'habits', 'reflections', 'exercise', 'meditation', 'fasting'] as const;
type TabKey = typeof TABS[number];

const TAB_I18N: Record<TabKey, string> = {
  overview: 'statsTabOverview',
  plan: 'statsTabPlan',
  reflections: 'statsTabReflections',
  exercise: 'statsTabExercise',
  meditation: 'statsTabMeditation',
  fasting: 'statsTabFasting',
  habits: 'statsTabHabits',
};

const CHART_TABS = ['calories', 'water', 'weight', 'exercise'] as const;
type ChartKey = typeof CHART_TABS[number];

export default function StatsScreen() {
  const TH = useTheme();
  const T = useT();
  const { exerciseLog: rawExerciseLog, fastingHistory: rawFastingHistory, userProfile, totalMedMinutes: rawTotalMedMinutes, medHistory: rawMedHistory, reflections: rawReflections, plans: rawPlans, planItems: rawPlanItems, planItemCheckins, habits: rawHabits, graceHistory, checkinHistory: rawCheckinHistory, foodLog: rawFoodLog, streak } = useShallowStore(s => ({
    exerciseLog: s.exerciseLog,
    fastingHistory: s.fastingHistory,
    userProfile: s.userProfile,
    totalMedMinutes: s.totalMedMinutes,
    medHistory: s.medHistory,
    reflections: s.reflections,
    plans: s.plans,
    planItems: s.planItems,
    planItemCheckins: s.planItemCheckins,
    habits: s.habits,
    graceHistory: s.graceHistory,
    checkinHistory: s.checkinHistory,
    foodLog: s.foodLog,
    streak: s.streak,
  }));
  const P = TH.primary;
  const nav = useRootNavigation();

  const [activeTab, setActiveTab] = useState<TabKey>('overview');
  const [activeChart, setActiveChart] = useState<ChartKey>('exercise');

  // ── Common data ──
  const exerciseLog = useMemo(() => (rawExerciseLog ?? []).filter(e => !e.deleted), [rawExerciseLog]);
  const now = Date.now();
  const todayD = new Date(now);
  const today = `${todayD.getFullYear()}-${String(todayD.getMonth() + 1).padStart(2, '0')}-${String(todayD.getDate()).padStart(2, '0')}`;
  const weekStart = now - 7 * 24 * 3600 * 1000;
  const monthStart = now - 30 * 24 * 3600 * 1000;

  // ── Fasting stats ──
  const fastingHistory = useMemo(() => (rawFastingHistory ?? []).filter(f => !f.deleted), [rawFastingHistory]);
  const totalFastCount = fastingHistory.length;
  const totalFastHours = useMemo(() => {
    const totalSec = fastingHistory.reduce((sum, f) => {
      const s = f.startedAt ?? 0;
      const e = f.endedAt ?? 0;
      return sum + (e > 0 ? (e - s) / 1000 : 0);
    }, 0);
    return Math.round(totalSec / 3600);
  }, [fastingHistory]);
  const fastingDates = useMemo(() => {
    if (!fastingHistory.length) return [] as string[];
    return [...new Set(fastingHistory.map(f => {
      if (!f.startedAt) return null;
      const d = new Date(f.startedAt);
      if (isNaN(d.getTime())) return null;
      return dateStr(d);
    }).filter(Boolean as unknown as <T>(x: T) => x is NonNullable<T>))].sort();
  }, [fastingHistory]);
  const fastStreak = useMemo(() => {
    if (!fastingDates.length) return 0;
    const reversed = [...fastingDates].reverse();
    const todayStr = dateStr();
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = dateStr(yesterday);
    if (reversed[0] !== todayStr && reversed[0] !== yesterdayStr) return 0;
    let streak = 1;
    for (let i = 1; i < reversed.length; i++) {
      const prev = new Date(reversed[i - 1]);
      const curr = new Date(reversed[i]);
      const diff = (prev.getTime() - curr.getTime()) / 86400000;
      if (Math.abs(diff - 1) < 0.1) streak++;
      else break;
    }
    return streak;
  }, [fastingDates]);
  const fastKcal = useMemo(() => {
    const totalHours = fastingHistory.reduce((sum, f) => {
      const s = f.startedAt ?? 0;
      const e = f.endedAt ?? 0;
      return sum + (e > 0 ? (e - s) / 3600000 : 0);
    }, 0);
    return Math.round(estimateFastingKcal(totalHours, userProfile.weight ?? 70, userProfile.gender ?? 'male', userProfile.age ?? 30));
  }, [fastingHistory, userProfile]);

  // ── Meditation stats ──
  const totalMedMin = rawTotalMedMinutes;
  const medHistory = rawMedHistory ?? [];
  const todayMedMin = useMemo(() => getTodayMedMinutes(activeOnly(medHistory)), [medHistory]);
  const medSessionCount = useMemo(() => activeOnly(medHistory).length, [medHistory]);

  // ── Exercise stats ──
  const exerciseStats = useMemo(() => {
    const weekKm = exerciseLog.filter(e => e.timestamp >= weekStart).reduce((s, e) => s + (e.distanceKm ?? 0), 0);
    const monthKm = exerciseLog.filter(e => e.timestamp >= monthStart).reduce((s, e) => s + (e.distanceKm ?? 0), 0);
    const allPaces = exerciseLog.filter(e => e.avgPace && e.avgPace > 0).map(e => e.avgPace!);
    const bestPace = allPaces.length > 0 ? Math.min(...allPaces) : 0;
    const totalExerciseMin = Math.round(exerciseLog.reduce((s, e) => s + e.durationSec, 0) / 60);
    const totalExerciseCount = exerciseLog.length;
    return { weekKm, monthKm, bestPace, totalExerciseMin, totalExerciseCount };
  }, [exerciseLog, weekStart, monthStart]);
  const { weekKm, monthKm, bestPace, totalExerciseMin, totalExerciseCount } = exerciseStats;

  // ── Reflections stats ──
  const reflections = rawReflections ?? [];
  const reflCount = useMemo(() => activeOnly(reflections).length, [reflections]);

  // ── Plan stats ──
  const plans = rawPlans ?? [];
  const planStats = useMemo(() => {
    const planItems = (rawPlanItems ?? []).filter(i => !i.deleted);
    const activePlans = plans.filter(p => !p.deleted && p.status === 'in_progress');
    const totalPlanTasks = planItems.length;
    const completedPlanTasks = planItems.filter(i => i.status === 'completed').length;
    return { planItems, activePlans, totalPlanTasks, completedPlanTasks };
  }, [rawPlanItems, plans]);
  const { planItems, activePlans, totalPlanTasks, completedPlanTasks } = planStats;

  // ── Other stats ──
  const activeHabits = useMemo(() => (rawHabits ?? []).filter(h => !h.deleted && h.status === 'inProgress').length, [rawHabits]);
  const graceCount = (graceHistory ?? []).filter(g => !g.deleted).length;

  // ── Chart data ──
  const weightData = useMemo(() => aggregateWeightData(rawCheckinHistory ?? [], 30), [rawCheckinHistory]);
  const caloriesData = useMemo(() => aggregateDailyCalories(rawFoodLog ?? [], 7), [rawFoodLog]);
  const waterData = useMemo(() => aggregateDailyWater(rawCheckinHistory ?? [], 7), [rawCheckinHistory]);
  const exerciseTrendData = useMemo(() => aggregateWeeklyKm(exerciseLog, 8), [exerciseLog]);

  // ── Render helpers ──
  const renderStatGrid = (items: { value: string; unit: string; label: string; icon?: React.ComponentType<{size?: number; color?: string}> }[], columns = 2) => (
    <View style={styles.statGridRow}>
      {items.map((s, i) => (
        <View key={i} style={{ width: columns === 2 ? '48%' : '31%', borderRadius: 14, padding: 16, alignItems: 'center', gap: 6, backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border }}>
          {s.icon && <s.icon size={22} color={P} />}
          <Text style={{ fontWeight: '700', color: P, fontSize: FONT_STAT_CARD(), textAlign: 'center' }}>
            {s.value}<Text style={{ fontSize: FONT_SUB(), fontWeight: '400', color: TH.sub }}> {s.unit}</Text>
          </Text>
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, textAlign: 'center' }}>{s.label}</Text>
        </View>
      ))}
    </View>
  );

  const renderChartArea = () => (
    <Card style={styles.cardMarginBottom}>
      <View style={styles.chartTabRow}>
        {CHART_TABS.map(key => {
          const labels: Record<ChartKey, string> = { calories: T('statsDailyCalories'), water: T('waterIntake'), weight: T('statsWeightTrend'), exercise: T('statsExerciseTrend') };
          const active = activeChart === key;
          return (
            <TouchableOpacity key={key} onPress={() => setActiveChart(key)}
              style={{ paddingHorizontal: 10, paddingVertical: 5, borderRadius: 8, backgroundColor: active ? `${P}18` : 'transparent' }}>
              <Text style={{ fontSize: FONT_SUB(), color: active ? P : TH.sub, fontWeight: active ? '600' : '400' }}>{labels[key]}</Text>
            </TouchableOpacity>
          );
        })}
      </View>
      {activeChart === 'calories' && caloriesData.some(d => d.value > 0) && (
        <BarChart data={caloriesData.map(d => d.value)} labels={caloriesData.map(d => d.label)} width={CHART_W} height={150} color="#F59E0B" />
      )}
      {activeChart === 'calories' && !caloriesData.some(d => d.value > 0) && (
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 40 }}>{T('statsNoData')}</Text>
      )}
      {activeChart === 'water' && waterData.some(d => d.value > 0) && (
        <BarChart data={waterData.map(d => d.value)} labels={waterData.map(d => d.label)} width={CHART_W} height={150} color="#3B82F6" />
      )}
      {activeChart === 'water' && !waterData.some(d => d.value > 0) && (
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 40 }}>{T('statsNoData')}</Text>
      )}
      {activeChart === 'weight' && weightData.length >= 2 && (
        <LineChart data={weightData.map(d => d.value)} labels={weightData.map(d => d.date)} width={CHART_W} height={160} color="#E91E63" showArea suffix={T('statsKg')} />
      )}
      {activeChart === 'weight' && weightData.length < 2 && (
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 40 }}>{T('statsNoData')}</Text>
      )}
      {activeChart === 'exercise' && exerciseTrendData.some(d => d.value > 0) && (
        <LineChart data={exerciseTrendData.map(d => d.value)} labels={exerciseTrendData.map(d => d.label)} width={CHART_W} height={160} color="#3B82F6" showArea suffix="km" />
      )}
      {activeChart === 'exercise' && !exerciseTrendData.some(d => d.value > 0) && (
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 40 }}>{T('statsNoData')}</Text>
      )}
      {activeChart === 'calories' && !caloriesData.some(d => d.value > 0) && (
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 40 }}>{T('statsNoData')}</Text>
      )}
    </Card>
  );

  const renderHabitList = () => {
    const habits = (rawHabits ?? []).filter(h => !h.deleted && h.status === 'inProgress');
    if (!habits.length) return null;
    return (
      <Card style={{ marginBottom: 12 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 10 }}>{T('statsHabitProgress')}</Text>
        {habits.map(h => {
          const pct = h.targetDays > 0 ? Math.min(Math.round(h.doneDays / h.targetDays * 100), 100) : 0;
          return (
            <View key={h.id} style={{ paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: TH.border }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
                <Flame size={16} color={COLORS.ORANGE} />
                <Text style={{ flex: 1, fontSize: FONT_BODY(), color: TH.text }} numberOfLines={1}>{h.name}</Text>
                <Text style={{ fontSize: FONT_SUB(), color: COLORS.ORANGE, fontWeight: '600' }}>{h.streak}{T('days')}</Text>
              </View>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 6 }}>
                <View style={{ flex: 1, height: 4, backgroundColor: TH.border, borderRadius: 2, overflow: 'hidden' }}>
                  <View style={{ height: 4, backgroundColor: P, borderRadius: 2, width: `${pct}%` }} />
                </View>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{h.doneDays}/{h.targetDays}</Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, width: 36, textAlign: 'right' }}>{pct}%</Text>
              </View>
            </View>
          );
        })}
      </Card>
    );
  };

  const renderPlanList = () => {
    if (!activePlans.length) return null;
    return (
      <Card style={{ marginBottom: 12 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 10 }}>{T('statsPlanList')}</Text>
        {activePlans.map(p => {
          const items = planItems.filter(i => i.planId === p.id);
          const done = items.filter(i => i.status === 'completed').length;
          const pct = computePlanProgress(p);
          return (
            <View key={p.id} style={{ marginBottom: 16 }}>
              {/* Plan header */}
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4 }}>
                <ClipboardList size={16} color={P} />
                <Text style={{ flex: 1, fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }} numberOfLines={1}>{p.name}</Text>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{done}/{items.length}</Text>
                <View style={{ width: 60, height: 4, backgroundColor: TH.border, borderRadius: 2, overflow: 'hidden' }}>
                  <View style={{ height: 4, backgroundColor: P, borderRadius: 2, width: `${pct}%` }} />
                </View>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub, width: 36, textAlign: 'right' }}>{pct}%</Text>
              </View>
              {/* Tree items */}
              {items.length > 0 && (
                <View style={{ marginLeft: 8 }}>
                  {items.map((item, idx) => {
                    const { doneCount: checkedDays, expectedDays } = countItemDoneDays(item, planItemCheckins, today);
                    const itemPct = expectedDays > 0 ? Math.min(Math.round((checkedDays / expectedDays) * 100), 100) : 0;
                    const isLast = idx === items.length - 1;
                    return (
                      <View key={item.id} style={{ flexDirection: 'row' }}>
                        {/* Vertical line + dot */}
                        <View style={{ width: 20, alignItems: 'center' }}>
                          <View style={{ position: 'absolute', top: 0, bottom: isLast ? '50%' : 0, width: 1, backgroundColor: TH.border }} />
                          <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: item.status === 'completed' ? P : TH.border, marginTop: 8, zIndex: 1 }} />
                        </View>
                        {/* Content - same layout as plan header */}
                        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 4 }}>
                          <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>·</Text>
                          <Text style={{ flex: 1, fontSize: FONT_SUB(), color: item.status === 'completed' ? TH.sub : TH.text, textDecorationLine: item.status === 'completed' ? 'line-through' : 'none' }} numberOfLines={1}>{item.name}</Text>
                          <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{checkedDays}/{expectedDays}</Text>
                          <View style={{ width: 60, height: 4, backgroundColor: TH.border, borderRadius: 2, overflow: 'hidden' }}>
                            <View style={{ height: 4, backgroundColor: item.status === 'completed' ? P : COLORS.GREEN, borderRadius: 2, width: `${itemPct}%` }} />
                          </View>
                          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, width: 36, textAlign: 'right' }}>{itemPct}%</Text>
                        </View>
                      </View>
                    );
                  })}
                </View>
              )}
            </View>
          );
        })}
      </Card>
    );
  };

  const renderCalendar = () => (
    <Card style={{ marginBottom: 12 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 12 }}>
        <CalendarDays size={15} color={TH.text} />
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{T('statsCheckinHeatmap')}</Text>
      </View>
      <CalendarGrid history={(rawCheckinHistory ?? []).filter(c => !c.deleted)}
        primaryColor={P} textColor={TH.text} subColor={TH.sub} borderColor={TH.border}
        onDayPress={(date) => nav.navigate('CheckinDetail', { date })} />
    </Card>
  );

  // ── Tab content ──
  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <>
            {renderStatGrid([
              { value: `${streak}`, unit: T('days'), label: T('streak'), icon: Flame },
              { value: `${(rawCheckinHistory ?? []).filter(c => !c.deleted).length}`, unit: T('days'), label: T('statsTotalCheckinDays'), icon: CalendarDays },
              { value: `${activeOnly(plans).length}`, unit: '', label: T('statsPlanTotal'), icon: ClipboardList },
              { value: `${completedPlanTasks}`, unit: '', label: T('statsCompletedTasks'), icon: Target },
              { value: `${(rawHabits ?? []).filter(h => !h.deleted).length}`, unit: '', label: T('statsHabitCount'), icon: Star },
              { value: `${reflCount}`, unit: '', label: T('statsReflections'), icon: Sparkles },
              { value: `${totalExerciseMin}`, unit: T('exerciseMin'), label: T('statsExerciseDuration'), icon: Dumbbell },
              { value: `${totalMedMin}`, unit: T('medMinutes'), label: T('statsMeditation'), icon: Target },
              { value: `${totalFastCount}`, unit: T('fastTimes'), label: T('statsTotalFasting'), icon: Clock },
            ], 3)}
            {renderChartArea()}
            {renderHabitList()}
            {renderPlanList()}
          </>
        );
      case 'fasting':
        return (
          <>
            {renderStatGrid([
              { value: `${totalFastCount}`, unit: T('fastTimes'), label: T('fastTotal') },
              { value: `${totalFastHours}`, unit: T('fastHours'), label: T('fastTotalHours') },
              { value: `${fastStreak}`, unit: T('days'), label: T('fastStreak') },
            ], 3)}
            <View style={{ flexDirection: 'row', gap: 8, marginBottom: 12 }}>
              <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', gap: 6, padding: 12, backgroundColor: TH.card, borderRadius: 12, borderWidth: 1, borderColor: TH.border }}>
                <Flame size={16} color={COLORS.ORANGE} />
                <View>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{fastKcal} kcal</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('fastKcalSaved')}</Text>
                </View>
              </View>
              <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', gap: 6, padding: 12, backgroundColor: TH.card, borderRadius: 12, borderWidth: 1, borderColor: TH.border }}>
                <TrendingUp size={16} color="#E91E63" />
                <View>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{(fastKcal / 7700).toFixed(2)} {T('fastKg')}</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('fastWeightLoss')}</Text>
                </View>
              </View>
            </View>
          </>
        );
      case 'meditation':
        return renderStatGrid([
          { value: `${totalMedMin}`, unit: T('medMinutes'), label: T('accMed') },
          { value: `${todayMedMin}`, unit: T('medMinutes'), label: T('medTitle') },
          { value: `${medSessionCount}`, unit: T('fastTimes'), label: T('shareCardSession') },
        ], 3);
      case 'exercise':
        return (
          <>
            {renderStatGrid([
              { value: `${weekKm.toFixed(1)}`, unit: 'km', label: T('exerciseWeekKm') },
              { value: `${monthKm.toFixed(1)}`, unit: 'km', label: T('exerciseMonthKm') },
              { value: bestPace > 0 ? `${Math.floor(bestPace / 60)}:${String(Math.floor(bestPace % 60)).padStart(2, '0')}` : '--', unit: '/km', label: T('exerciseBestPace') },
            ], 3)}
            {renderStatGrid([
              { value: `${totalExerciseMin}`, unit: T('exerciseMin'), label: T('exerciseTotalTime'), icon: Dumbbell },
              { value: `${totalExerciseCount}`, unit: T('fastTimes'), label: T('exerciseTotalCount'), icon: Dumbbell },
            ])}
            {exerciseTrendData.some(d => d.value > 0) && (
              <Card>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 12 }}>{T('statsExerciseTrend')}</Text>
                <LineChart data={exerciseTrendData.map(d => d.value)} labels={exerciseTrendData.map(d => d.label)} width={CHART_W} height={160} color="#3B82F6" showArea suffix="km" />
              </Card>
            )}
          </>
        );
      case 'reflections':
        return renderStatGrid([
          { value: `${reflCount}`, unit: '', label: T('statsReflections') },
          { value: `${(rawReflections ?? []).filter(r => !r.deleted && r.mood).length}`, unit: '', label: T('mood') },
          { value: `${Object.keys((rawReflections ?? []).filter(r => !r.deleted).reduce((acc, r) => { (r.tags ?? []).forEach(t => acc[t] = 1); return acc; }, {} as Record<string, number>)).length}`, unit: '', label: T('addTags') },
        ], 3);
      case 'plan':
        return (
          <>
            {renderStatGrid([
              { value: `${activePlans.length}`, unit: '', label: T('statsPlanTotal'), icon: ClipboardList },
              { value: `${totalPlanTasks}`, unit: '', label: T('statsPlanTasks'), icon: Target },
              { value: `${completedPlanTasks}`, unit: '', label: T('statsPlanDone'), icon: Star },
            ], 3)}
            {renderPlanList()}
          </>
        );
      case 'habits':
        return (
          <>
            {renderStatGrid([
              { value: `${activeHabits}`, unit: '', label: T('statsActiveHabits'), icon: Star },
              { value: `${graceCount}`, unit: '', label: T('statsGraceCount'), icon: Shield },
            ])}
            {renderHabitList()}
          </>
        );
    }
  };

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }} showsVerticalScrollIndicator={false}>
        {/* Back button + title */}
        <TouchableOpacity onPress={() => nav.goBack()} style={{ marginBottom: 12, flexDirection: 'row', alignItems: 'center', alignSelf: 'flex-start' }}>
          <ChevronLeft size={28} color={TH.text} />
          <Text style={{ fontSize: FONT_TITLE(), fontWeight: '600', color: TH.text, marginLeft: 4 }}>{T('statsTitle')}</Text>
        </TouchableOpacity>

        {/* Calendar heatmap */}
        {renderCalendar()}

        {/* Tabs */}
        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 12 }} contentContainerStyle={{ gap: 6 }}>
          {TABS.map(key => {
            const active = activeTab === key;
            return (
              <TouchableOpacity key={key} onPress={() => setActiveTab(key)}
                style={{ paddingHorizontal: 14, paddingVertical: 8, borderRadius: 20, backgroundColor: active ? P : TH.card, borderWidth: 1, borderColor: active ? P : TH.border }}>
                <Text style={{ fontSize: FONT_BODY(), color: active ? '#fff' : TH.text, fontWeight: active ? '600' : '400' }}>{T(TAB_I18N[key])}</Text>
              </TouchableOpacity>
            );
          })}
        </ScrollView>

        {/* Tab content */}
        {renderTabContent()}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  statGridRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginBottom: 16,
  },
  cardMarginBottom: {
    marginBottom: 12,
  },
  chartTabRow: {
    flexDirection: 'row',
    gap: 6,
    marginBottom: 8,
  },
});

import { FONT_TITLE, FONT_BODY, FONT_SUB, FONT_SMALL, FONT_STAT_SECTION , FONT_STAT_CARD } from '@egoless-do/core';
import type { MantraDef } from '@egoless-do/core';
import React, { useMemo } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

const WEEKDAY_LABELS = ['一', '二', '三', '四', '五', '六', '日'];

function startOfDay(d: Date): Date {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function dateKey(d: Date): string {
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

export default function SutraHistoryScreen() {
  const nav = useRootNavigation();
  const TH = useTheme();
  const T = useT();
  const { mantraSessions, mantraDefs } = useShallowStore(s => ({ mantraSessions: s.mantraSessions, mantraDefs: s.mantraDefs }));

  const allSessions = useMemo(() =>
    (mantraSessions ?? []).filter(s => !s.deleted).sort((a, b) => b.startedAt - a.startedAt),
    [mantraSessions]
  );

  const mySutras = useMemo(() =>
    (mantraDefs ?? []).filter(d => !d.deleted && d.preset !== true),
    [mantraDefs]
  );

  const sutraMap = useMemo(() => {
    const m: Record<string, MantraDef> = {};
    for (const d of (mantraDefs ?? []).filter(d => !d.deleted)) m[d.id] = d;
    return m;
  }, [mantraDefs]);

  const stats = useMemo(() => {
    const totalCount = allSessions.reduce((sum, s) => sum + s.count, 0);
    const totalSec = allSessions.reduce((sum, s) => sum + s.durationSec, 0);
    const dateSet = new Set<string>();
    allSessions.forEach(s => dateSet.add(dateKey(new Date(s.startedAt))));

    let streak = 0;
    const today = startOfDay(new Date());
    const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);
    if (dateSet.has(dateKey(today)) || dateSet.has(dateKey(yesterday))) {
      streak = 1;
      const check = new Date(dateSet.has(dateKey(today)) ? today : yesterday);
      for (let i = 1; i < 365; i++) {
        check.setDate(check.getDate() - 1);
        if (dateSet.has(dateKey(check))) streak++;
        else break;
      }
    }
    return { totalCount, totalSec, streak };
  }, [allSessions]);

  const now = new Date();
  const monthYear = now.getFullYear();
  const monthIdx = now.getMonth();
  const heatmapData = useMemo(() => {
    const daysInMonth = new Date(monthYear, monthIdx + 1, 0).getDate();
    const firstDay = new Date(monthYear, monthIdx, 1).getDay();
    const offset = firstDay === 0 ? 6 : firstDay - 1;

    const dayCountMap: Record<string, number> = {};
    allSessions.forEach(s => {
      const d = new Date(s.startedAt);
      if (d.getFullYear() === monthYear && d.getMonth() === monthIdx) {
        dayCountMap[dateKey(d)] = (dayCountMap[dateKey(d)] || 0) + s.count;
      }
    });

    const maxCount = Math.max(1, ...Object.values(dayCountMap));
    const today = new Date();
    const days: { date: string; count: number; intensity: number; isToday: boolean }[] = [];
    for (let i = 0; i < offset; i++) days.push({ date: '', count: 0, intensity: 0, isToday: false });
    for (let d = 1; d <= daysInMonth; d++) {
      const dt = new Date(monthYear, monthIdx, d);
      const ds = dateKey(dt);
      const count = dayCountMap[ds] || 0;
      days.push({ date: ds, count, intensity: count > 0 ? Math.max(0.2, count / maxCount) : 0, isToday: dt.toDateString() === today.toDateString() });
    }
    return days;
  }, [allSessions, monthYear, monthIdx]);

  const distribution: { sutra: MantraDef; total: number; pct: number }[] = useMemo(() => {
    const total = stats.totalCount;
    return mySutras
      .map(sutra => {
        const sutraTotal = (mantraSessions ?? []).filter(s => !s.deleted && s.mantraId === sutra.id).reduce((a, b) => a + b.count, 0);
        const pct = total > 0 ? Math.round((sutraTotal / total) * 100) : 0;
        return { sutra, total: sutraTotal, pct };
      })
      .filter(d => d.total > 0)
      .sort((a, b) => b.total - a.total);
  }, [mySutras, mantraSessions, stats.totalCount]);

  const formatTime = (sec: number) => {
    if (sec < 60) return sec + '秒';
    if (sec < 3600) return Math.floor(sec / 60) + '分' + (sec % 60 > 0 ? (sec % 60) + '秒' : '');
    return Math.floor(sec / 3600) + '小时' + Math.floor((sec % 3600) / 60) + '分';
  };

  const formatShortTime = (sec: number) => {
    if (sec < 60) return sec + 's';
    if (sec < 3600) return Math.floor(sec / 60) + 'm' + (sec % 60 > 0 ? (sec % 60) + 's' : '');
    return Math.floor(sec / 3600) + 'h' + Math.floor((sec % 3600) / 60) + 'm';
  };

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <View style={styles.headerRow}>
        <TouchableOpacity onPress={() => nav.goBack()} style={styles.backButton}>
          <Text style={{ fontSize: FONT_STAT_CARD(), color: TH.text }}>←</Text>
        </TouchableOpacity>
        <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: TH.text, flex: 1 }}>{T('sutraHistory')}</Text>
        <View style={styles.alignRight}>
          <Text style={styles.goldStatText}>{stats.totalCount.toLocaleString()}</Text>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计</Text>
        </View>
      </View>

      <ScrollView contentContainerStyle={styles.scrollContent}>
        {/* Stats card */}
        <View style={[styles.statsCard, { borderColor: TH.primary + '30' }]}>
          <View style={styles.statsRow}>
            <View style={styles.statItem}>
              <Text style={styles.goldStatText}>{stats.totalCount.toLocaleString()}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计颗数</Text>
            </View>
            <View style={styles.statItem}>
              <Text style={styles.greenStatText}>{formatTime(stats.totalSec)}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>累计时长</Text>
            </View>
            <View style={styles.statItem}>
              <Text style={styles.orangeStatText}>🔥 {stats.streak}</Text>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>连续</Text>
            </View>
          </View>
        </View>

        {/* Calendar heatmap this month */}
        <View style={[styles.calendarSection, { borderColor: TH.primary + '20' }]}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 12 }}>
            {monthYear}年{monthIdx + 1}月
          </Text>
          <View style={styles.weekRow}>
            {WEEKDAY_LABELS.map(d => (
              <View key={d} style={styles.weekDayCell}>
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{d}</Text>
              </View>
            ))}
          </View>
          <View style={styles.heatmapWrap}>
            {heatmapData.map((day, i) => (
              <View key={i} style={styles.dayCell}>
                {day.date ? (
                  <View style={{
                    ...styles.dayCircle,
                    backgroundColor: day.count > 0 ? 'rgba(212, 165, 116, ' + day.intensity + ')' : day.isToday ? TH.primary + '20' : 'transparent',
                    borderWidth: day.isToday ? 2 : 0,
                    borderColor: day.isToday ? TH.primary : 'transparent',
                  }}>
                    <Text style={[styles.textSize12, { color: TH.text, fontWeight: day.isToday ? '700' : '400' }]}>
                      {Number(day.date.split('-')[2])}
                    </Text>
                  </View>
                ) : <View style={styles.emptyDay} />}
              </View>
            ))}
          </View>
        </View>

        {/* Distribution */}
        {distribution.length > 0 && (
          <View style={[styles.cardSection, { backgroundColor: TH.card, borderColor: TH.border }]}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 8 }}>经文分布</Text>
            {distribution.map(({ sutra, total, pct }) => (
              <View key={sutra.id} style={styles.distributionItem}>
                <View style={styles.distributionHeader}>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.text }}>{sutra.name}</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{pct}%</Text>
                </View>
                <View style={[styles.barTrack, { backgroundColor: TH.primary + '15' }]}>
                  <View style={[styles.barFill, { width: `${pct}%` }]} />
                </View>
                <Text style={[styles.textSize10, { color: TH.sub, marginTop: 2 }]}>{total.toLocaleString()} 颗 ({pct}%)</Text>
              </View>
            ))}
          </View>
        )}

        {/* History list */}
        <View style={[styles.cardSection, { backgroundColor: TH.card, borderColor: TH.border }]}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 8 }}>{T('sutraHistory')}</Text>
          {allSessions.length === 0 ? (
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), textAlign: 'center', paddingVertical: 16 }}>{T('sutraNoRecords')}</Text>
          ) : allSessions.slice(0, 30).map(s => {
            const sutra = sutraMap[s.mantraId];
            const d = new Date(s.startedAt);
            const dateStr = (d.getMonth() + 1) + '/' + d.getDate();
            return (
              <View key={s.id} style={[styles.sessionItem, { borderBottomColor: TH.border }]}>
                <View style={styles.sessionRow}>
                  <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600' }}>{sutra?.name ?? '未知'}</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{dateStr}</Text>
                </View>
                <View style={styles.sessionMeta}>
                  <Text style={[styles.textSize10, { color: TH.sub }]}>{s.count}颗 · {s.rounds}遍</Text>
                  <Text style={[styles.textSize10, { color: TH.sub }]}>{formatShortTime(s.durationSec)}</Text>
                  {s.dedication ? <Text style={styles.textDedication}>回向</Text> : null}
                </View>
              </View>
            );
          })}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  // Layout
  headerRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingTop: 8, paddingBottom: 8 },
  backButton: { marginRight: 12 },
  alignRight: { alignItems: 'flex-end' },
  scrollContent: { paddingHorizontal: 16, paddingBottom: 40 },

  // Card sections
  statsCard: { borderRadius: 16, borderWidth: 1, padding: 16, marginBottom: 16 },
  calendarSection: { borderRadius: 16, borderWidth: 1, padding: 16, marginBottom: 16 },
  cardSection: { borderRadius: 16, padding: 16, marginBottom: 16, borderWidth: 1 },

  // Stats row
  statsRow: { flexDirection: 'row', justifyContent: 'space-around' },
  statItem: { alignItems: 'center' },
  goldStatText: { fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#D4A574' },
  greenStatText: { fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#10B981' },
  orangeStatText: { fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#F59E0B' },

  // Calendar heatmap
  weekRow: { flexDirection: 'row', marginBottom: 4 },
  weekDayCell: { width: '14.28%', alignItems: 'center' },
  heatmapWrap: { flexDirection: 'row', flexWrap: 'wrap' },
  dayCell: { width: '14.28%', alignItems: 'center', paddingVertical: 2, minHeight: 32 },
  dayCircle: { width: 30, height: 30, borderRadius: 15, alignItems: 'center', justifyContent: 'center' },
  emptyDay: { width: 30, height: 30 },

  // Distribution
  distributionItem: { marginBottom: 8 },
  distributionHeader: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 },
  barTrack: { height: 8, borderRadius: 4, overflow: 'hidden' },
  barFill: { height: '100%', backgroundColor: '#D4A574', borderRadius: 4 },

  // Session items
  sessionItem: { paddingVertical: 8, borderBottomWidth: 1 },
  sessionRow: { flexDirection: 'row', justifyContent: 'space-between' },
  sessionMeta: { flexDirection: 'row', gap: 12, marginTop: 4 },

  // Shared text styles
  textSize12: { fontSize: FONT_SMALL() },
  textSize10: { fontSize: FONT_SMALL() },
  textDedication: { fontSize: FONT_SMALL(), color: '#D4A574' },
});

import {FONT_TITLE, FONT_BODY, FONT_SUB, FONT_STAT_SECTION, FONT_SMALL, DEDICATION_TEMPLATES, SUTRA_CATEGORIES, dateStr , scaleFontSize, FONT_STAT_CARD, FONT_BACK, FONT_HERO} from '@egoless-do/core';
import type { MantraDef, MantraCategory } from '@egoless-do/core';
import * as Haptics from 'expo-haptics';
import { useKeepAwake } from 'expo-keep-awake';
import { BarChart3, Plus, ChevronDown, ChevronRight, X } from 'lucide-react-native';
import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { View, Text, ScrollView, TouchableOpacity, TextInput, Modal, KeyboardAvoidingView, Platform, Alert, FlatList, ListRenderItemInfo } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT, PrimaryButton, OutlineButton } from '../../components/UI';
import SimpleHeader from '../../navigation/SimpleHeader';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';
import { MalaRing } from '../shared/components/MalaRing';
import { useAudioCache } from '../shared/hooks/useAudioCache';

import { useSutraAudio } from './useSutraAudio';


type SutraPage = 'select' | 'start' | 'active' | 'report';

const BEAD_COUNT = 108;
const SUTRA_CATEGORY_ORDER: MantraCategory[] = ['sutra', 'dharani', 'buddha_name', 'custom'];

export default function SutraScreen() {
  return <SutraScreenInner />;
}

function SutraScreenInner() {
  const nav = useRootNavigation();
  const TH = useTheme();
  const T = useT();
  const { mantraDefs, getMantraTotalCount, getMantraStreak, getMantraTodayCount, addMantraSession, removeMantraDef, initializePresetsIncremental, addPresetSutra, addMantraDef } = useShallowStore(s => ({
    mantraDefs: s.mantraDefs,
    getMantraTotalCount: s.getMantraTotalCount,
    getMantraStreak: s.getMantraStreak,
    getMantraTodayCount: s.getMantraTodayCount,
    addMantraSession: s.addMantraSession,
    removeMantraDef: s.removeMantraDef,
    initializePresetsIncremental: s.initializePresetsIncremental,
    addPresetSutra: s.addPresetSutra,
    addMantraDef: s.addMantraDef,
  }));
  useKeepAwake();
  const { playSutra, stopSutra, isPlaying } = useSutraAudio();
  useEffect(() => () => { stopSutra(); }, [stopSutra]);
  const { downloadAudio, isCached, downloading, progress: dlProgress } = useAudioCache();

  const [page, setPage] = useState<SutraPage>('select');
  const [selectedSutra, setSelectedSutra] = useState<MantraDef | null>(null);
  const [targetRounds, setTargetRounds] = useState(7);
  const [audioCached, setAudioCached] = useState(false);
  const [count, setCount] = useState(0);
  const countRef = useRef(0);
  const [isPaused, setIsPaused] = useState(false);
  const [startTime, setStartTime] = useState(0);
  const startTimeRef = useRef(0);
  const [elapsed, setElapsed] = useState(0);
  const elapsedRef = useRef(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const pausedElapsedRef = useRef(0);
  const pauseStartRef = useRef(0);
  const startSessionSeq = useRef(0);
  const [showAddCustom, setShowAddCustom] = useState(false);
  const [customName, setCustomName] = useState('');
  const [customSubtitle, setCustomSubtitle] = useState('');
  const [customCategory, setCustomCategory] = useState<MantraCategory>('sutra');
  const [customText, setCustomText] = useState('');
  const [showDedication, setShowDedication] = useState(false);
  const [dedicationText, setDedicationText] = useState(DEDICATION_TEMPLATES[0]);
  const [pendingSessionData, setPendingSessionData] = useState<{ count: number; rounds: number; durationSec: number } | null>(null);
  const [foldedCategories, setFoldedCategories] = useState<Record<MantraCategory, boolean>>({
    sutra: false, dharani: true, buddha_name: true, custom: true,
  });
  const [presetSearch, setPresetSearch] = useState('');


  const mySutras = useMemo(() =>
    (mantraDefs ?? [])
      .filter((d: MantraDef) => !d.deleted && d.preset !== true && d.category === 'sutra')
      .sort((a: MantraDef, b: MantraDef) => a.sortOrder - b.sortOrder),
    [mantraDefs]
  );

  const presetSutras = useMemo(() =>
    (mantraDefs ?? []).filter((d: MantraDef) => d.preset === true && !d.deleted && d.category === 'sutra'),
    [mantraDefs]
  );

  const [presetsReady, setPresetsReady] = useState(false);
  useEffect(() => {
    if (presetsReady) return;
    if (typeof initializePresetsIncremental !== 'function') return;
    // 迁移 + 补全预设（幂等，安全可重入）
    initializePresetsIncremental();
    setPresetsReady(true);
  }, [presetsReady]);

  // helpers
  const pad2 = (n: number) => String(n).padStart(2, '0');
  const formatTime = (ms: number) => {
    const s = Math.floor(ms / 1000);
    return pad2(Math.floor(s / 60)) + ':' + pad2(s % 60);
  };

  useEffect(() => {
    if (page === 'active' && !isPaused && startTime > 0) {
      timerRef.current = setInterval(() => {
        const e = Date.now() - startTime - pausedElapsedRef.current;
        elapsedRef.current = e;
        setElapsed(e);
      }, 1000);
    }
    return () => { if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; } };
  }, [page, isPaused, startTime]);

  const startSession = useCallback(async (sutra: MantraDef) => {
    const seq = ++startSessionSeq.current;
    setSelectedSutra(sutra);
    setCount(0); countRef.current = 0;
    setStartTime(0); startTimeRef.current = 0;
    setElapsed(0); elapsedRef.current = 0;
    pausedElapsedRef.current = 0; setIsPaused(false);
    try {
      const cached = await isCached(sutra.id);
      if (seq !== startSessionSeq.current) return;
      setAudioCached(cached);
    } catch {
      if (seq !== startSessionSeq.current) return;
      setAudioCached(false);
    }
    setPage('start');
  }, [isCached]);

  const toggleCategoryFold = useCallback((cat: MantraCategory) => {
    setFoldedCategories(prev => ({ ...prev, [cat]: !prev[cat] }));
  }, []);

  const isPresetInMy = useCallback((name: string) => mySutras.some((m: MantraDef) => m.name === name), [mySutras]);

  const addPresetToMy = useCallback((preset: MantraDef) => {
    if (typeof addPresetSutra === 'function') addPresetSutra(preset);
  }, [addPresetSutra]);

  const removeFromMy = useCallback((id: string) => { removeMantraDef(id); }, [removeMantraDef]);

  const addCustomSutra = useCallback(() => {
    if (!customName.trim()) return;
    addMantraDef({
      name: customName.trim(),
      subtitle: customSubtitle.trim() || undefined,
      category: customCategory,
      preset: false,
      fullText: customText.trim() || undefined,
    });
    setShowAddCustom(false);
    setCustomName(''); setCustomSubtitle(''); setCustomText('');
  }, [customName, customSubtitle, customCategory, customText, addMantraDef]);

  const beginChanting = useCallback(() => {
    const now = Date.now();
    setStartTime(now); startTimeRef.current = now;
    setElapsed(0); elapsedRef.current = 0;
    pausedElapsedRef.current = 0; setIsPaused(false);
    setPage('active');
  }, []);

  const handleTap = useCallback(() => {
    if (isPaused) return;
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setCount(prev => {
      const next = prev + 1;
      countRef.current = next;
      if (next % BEAD_COUNT === 0 && next > 0) {
        void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      }
      return next;
    });
  }, [isPaused]);

  const handleUndo = useCallback(() => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setCount(prev => {
      const v = Math.max(0, prev - 1);
      countRef.current = v;
      return v;
    });
  }, []);

  const togglePause = useCallback(() => {
    if (isPaused) {
      pausedElapsedRef.current += Date.now() - pauseStartRef.current;
    } else {
      pauseStartRef.current = Date.now();
      stopSutra();
    }
    setIsPaused(!isPaused);
  }, [isPaused, stopSutra]);

  const endSession = useCallback(() => {
    const completedAt = Date.now();
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    stopSutra();
    const c = countRef.current;
    const durationSec = Math.floor((completedAt - startTimeRef.current - pausedElapsedRef.current) / 1000);
    const rounds = Math.floor(c / BEAD_COUNT);
    setPendingSessionData({ count: c, rounds, durationSec });
    setShowDedication(true);
    setPage('report');
  }, [stopSutra]);

  // Reset all session state
  const resetSession = useCallback(() => {
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    stopSutra();
    setCount(0); countRef.current = 0;
    setStartTime(0); startTimeRef.current = 0;
    setElapsed(0); elapsedRef.current = 0;
    pausedElapsedRef.current = 0;
    setIsPaused(false);
    setShowDedication(false);
    setPendingSessionData(null);
    setDedicationText(DEDICATION_TEMPLATES[0]);
    setPage('select');
  }, [stopSutra]);

  // Exit active page with short-session protection
  const handleExitActive = useCallback(() => {
    if (elapsedRef.current < 30000) {
      Alert.alert(T('chantingTimeTooShort'), '', [
        { text: T('confirm'), onPress: () => resetSession() },
      ]);
    } else {
      Alert.alert(T('chantingExitConfirmTitle'), T('chantingExitConfirmMsg'), [
        { text: T('chantingContinue'), style: 'cancel' },
        { text: T('chantingEndAndRecord'), onPress: endSession },
      ]);
    }
  }, [endSession, resetSession, T]);

  const saveSession = useCallback(() => {
    if (!selectedSutra || !pendingSessionData) { setShowDedication(false); setPage('select'); return; }
    addMantraSession({
      mantraId: selectedSutra.id,
      date: dateStr(),
      count: pendingSessionData.count,
      rounds: pendingSessionData.rounds,
      durationSec: pendingSessionData.durationSec,
      startedAt: startTime,
      completedAt: startTime + pendingSessionData.durationSec * 1000,
      targetRounds,
      dedication: dedicationText || undefined,
    });
    setShowDedication(false);
    setPendingSessionData(null);
    setPage('select');
  }, [selectedSutra, pendingSessionData, startTime, targetRounds, dedicationText, addMantraSession]);

  const categoryLabel = useCallback((cat: MantraCategory) => {
    const found = SUTRA_CATEGORIES.find(c => c.key === cat);
    return found ? T(found.labelKey) : cat;
  }, [T]);

  const categoryColor = useCallback((cat: MantraCategory) => {
    const map: Record<MantraCategory, string> = { sutra: '#6366F1', dharani: '#D97706', buddha_name: '#10B981', custom: '#8B5CF6' };
    return map[cat] || '#9CA3AF';
  }, []);

  const filteredPresets = useMemo(() =>
    presetSutras.filter((p: MantraDef) => {
      if (!presetSearch) return true;
      const q = presetSearch.toLowerCase();
      return p.name.toLowerCase().includes(q) || (p.subtitle || '').toLowerCase().includes(q);
    }),
    [presetSutras, presetSearch]
  );

  const presetByCategory = useMemo(() => {
    const map: Record<MantraCategory, MantraDef[]> = { sutra: [], dharani: [], buddha_name: [], custom: [] };
    for (const p of filteredPresets) {
      const cat: MantraCategory = p.category;
      if (!map[cat]) map[cat] = [];
      map[cat].push(p);
    }
    return map;
  }, [filteredPresets]);

  // FlatList helpers for select page
  const renderSutraItem = useCallback(({ item: m }: ListRenderItemInfo<MantraDef>) => {
    const total = getMantraTotalCount(m.id);
    const today = getMantraTodayCount(m.id);
    const streak = getMantraStreak(m.id);
    const progress = m.targetCount ? Math.min(100, Math.round(total / m.targetCount * 100)) : null;
    return (
      <TouchableOpacity onPress={() => startSession(m)}
        style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 8, borderWidth: 1, borderColor: TH.border }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{m.name}</Text>
            {m.subtitle && <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{m.subtitle}</Text>}
            {today > 0 && <Text style={{ fontSize: FONT_SMALL(), color: '#10B981', marginTop: 4 }}>{T('sutraTodayCount')} {today}</Text>}
          </View>
          <View style={{ alignItems: 'flex-end' }}>
            <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#D4A574' }}>{total.toLocaleString()}</Text>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('sutraTotalRounds')}</Text>
          </View>
        </View>
        {progress !== null && (
          <View style={{ marginTop: 8 }}>
            <View style={{ height: 4, backgroundColor: TH.border + '60', borderRadius: 2, overflow: 'hidden' }}>
              <View style={{ height: 4, width: `${progress}%`, backgroundColor: '#D4A574', borderRadius: 2 }} />
            </View>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 2 }}>
              {total.toLocaleString()} / {m.targetCount != null ? m.targetCount.toLocaleString() : '0'} ({progress}%)
            </Text>
          </View>
        )}
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 8 }}>
          <Text style={{ fontSize: FONT_SMALL(), color: '#F59E0B' }}>🔥 {streak}天</Text>
          <TouchableOpacity onPress={() => removeFromMy(m.id)} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}>
            <Text style={{ fontSize: FONT_SMALL(), color: '#EF4444' }}>{T('sutraRemove')}</Text>
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
    );
  }, [TH, T, startSession, getMantraTotalCount, getMantraTodayCount, getMantraStreak, removeFromMy]);

  const sutraListHeader = useMemo(() => (
    <View>
      <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 16 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 8 }}>{T('sutraTargetRounds')}</Text>
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
          {[1, 3, 7, 21, 108].map(n => (
            <TouchableOpacity key={n} onPress={() => setTargetRounds(n)}
              style={{ paddingHorizontal: 14, paddingVertical: 8, borderRadius: 10, backgroundColor: targetRounds === n ? '#D4A574' : TH.border }}>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: targetRounds === n ? '#fff' : TH.text }}>{n}</Text>
            </TouchableOpacity>
          ))}
        </View>
      </View>

      <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 12 }}>{T('sutraMySutras')}</Text>
    </View>
  ), [TH, T, targetRounds]);

  const sutraEmptyState = useMemo(() => (
    <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 24, alignItems: 'center' }}>
      <Text style={{ fontSize: scaleFontSize(40), marginBottom: 8 }}>📿</Text>
      <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>{T('sutraNoSutras')}</Text>
      <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, textAlign: 'center', marginTop: 4 }}>{T('sutraAddHint')}</Text>
    </View>
  ), [TH, T]);

  const sutraListFooter = useMemo(() => (
    <View style={{ marginTop: 16 }}>
      <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 12 }}>{T('sutraPresetLibrary')}</Text>
      <TextInput style={{ backgroundColor: TH.card, borderRadius: 12, paddingHorizontal: 14, paddingVertical: 10, color: TH.text, fontSize: FONT_SUB(), marginBottom: 10, borderWidth: 1, borderColor: TH.border }}
        placeholder={T('sutraSearchPlaceholder')} placeholderTextColor={TH.sub} value={presetSearch} onChangeText={setPresetSearch} />

      {SUTRA_CATEGORY_ORDER.map(cat => {
        const list = presetByCategory[cat] ?? [];
        if (list.length === 0) return null;
        const folded = foldedCategories[cat];
        const color = categoryColor(cat);
        return (
          <View key={cat} style={{ marginBottom: 16 }}>
            <TouchableOpacity onPress={() => toggleCategoryFold(cat)} style={{ marginBottom: 10, flexDirection: 'row', alignItems: 'center' }}>
              {folded ? <ChevronRight size={16} color={color} /> : <ChevronDown size={16} color={color} />}
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color, marginLeft: 4 }}>{categoryLabel(cat)} ({list.length})</Text>
            </TouchableOpacity>
            {!folded && (
              <View style={{ gap: 6 }}>
                {list.map(p => {
                  const added = isPresetInMy(p.name);
                  return (
                    <TouchableOpacity key={p.id} onPress={() => !added && addPresetToMy(p)}
                      style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: TH.card, borderRadius: 14, paddingVertical: 12, paddingHorizontal: 14, borderWidth: 1, borderColor: TH.border }}>
                      <View style={{ flex: 1 }}>
                        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                          <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{p.name}</Text>
                          <View style={{ paddingHorizontal: 6, paddingVertical: 2, borderRadius: 4, backgroundColor: color + '20' }}>
                            <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color }}>{categoryLabel(p.category)}</Text>
                          </View>
                          {p.pageCount ? <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{p.pageCount}页</Text> : null}
                        </View>
                        {p.subtitle ? <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 2 }} numberOfLines={1}>{p.subtitle}</Text> : null}
                      </View>
                      {added
                        ? <Text style={{ fontSize: FONT_SMALL(), color: '#10B981', fontWeight: '700' }}>{T('sutraAlreadyAdded')}</Text>
                        : <Plus size={18} color={TH.primary} />}
                    </TouchableOpacity>
                  );
                })}
              </View>
            )}
          </View>
        );
      })}

      <TouchableOpacity onPress={() => setShowAddCustom(true)}
        style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 14, paddingHorizontal: 14, borderRadius: 14, backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border, marginTop: 8 }}>
        <Plus size={18} color={TH.primary} />
        <Text style={{ fontSize: FONT_BODY(), color: TH.primary, fontWeight: '600' }}>{T('sutraImportCustom')}</Text>
      </TouchableOpacity>
    </View>
  ), [TH, T, presetSearch, presetByCategory, foldedCategories, toggleCategoryFold, categoryColor, categoryLabel, isPresetInMy, addPresetToMy, setShowAddCustom]);

  if (page === 'select') {
    return (
      <View style={{ flex: 1, backgroundColor: TH.bg }}>
        <SimpleHeader routeName="Sutra" />
        <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingTop: 8, paddingBottom: 8 }}>
          <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: TH.text, flex: 1 }}>{T('sutraSubtitle')}</Text>
          <TouchableOpacity onPress={() => nav.navigate('SutraHistory', {})}>
            <BarChart3 size={18} color={TH.sub} />
          </TouchableOpacity>
        </View>

        <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
          <FlatList
            data={mySutras}
            renderItem={renderSutraItem}
            keyExtractor={(item: MantraDef) => item.id}
            removeClippedSubviews={true}
            ListHeaderComponent={sutraListHeader}
            ListEmptyComponent={sutraEmptyState}
            ListFooterComponent={sutraListFooter}
            contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 40 }}
            keyboardShouldPersistTaps="handled"
          />
        </KeyboardAvoidingView>

        <Modal visible={showAddCustom} transparent animationType="fade">
          <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.75)', justifyContent: 'center', padding: 24 }}>
            <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24 }}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{T('sutraImportTitle')}</Text>
                <TouchableOpacity onPress={() => setShowAddCustom(false)}><X size={22} color={TH.sub} /></TouchableOpacity>
              </View>
              <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('sutraImportName')}</Text>
              <TextInput value={customName} onChangeText={setCustomName} placeholder="例如：药师经" placeholderTextColor={TH.sub}
                style={{ backgroundColor: TH.card, borderRadius: 12, padding: 12, color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border, marginBottom: 12 }} />
              <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('sutraImportSubtitle')}</Text>
              <TextInput value={customSubtitle} onChangeText={setCustomSubtitle} placeholder="" placeholderTextColor={TH.sub}
                style={{ backgroundColor: TH.card, borderRadius: 12, padding: 12, color: TH.text, fontSize: FONT_BODY(), borderWidth: 1, borderColor: TH.border, marginBottom: 12 }} />
              <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('sutraImportCategory')}</Text>
              <View style={{ flexDirection: 'row', gap: 8, marginBottom: 12 }}>
                {SUTRA_CATEGORY_ORDER.map(cat => (
                  <TouchableOpacity key={cat} onPress={() => setCustomCategory(cat)}
                    style={{ flex: 1, paddingVertical: 10, borderRadius: 8, alignItems: 'center', backgroundColor: customCategory === cat ? categoryColor(cat) : TH.card, borderWidth: customCategory === cat ? 0 : 1, borderColor: TH.border }}>
                    <Text style={{ color: customCategory === cat ? '#fff' : TH.text, fontWeight: '600', fontSize: FONT_SUB() }}>{categoryLabel(cat)}</Text>
                  </TouchableOpacity>
                ))}
              </View>
              <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', marginBottom: 6 }}>{T('sutraImportText')}</Text>
              <TextInput value={customText} onChangeText={setCustomText} placeholder={T('sutraImportPlaceholder')} placeholderTextColor={TH.sub} multiline
                style={{ backgroundColor: TH.card, borderRadius: 12, padding: 12, color: TH.text, fontSize: FONT_BODY(), minHeight: 80, textAlignVertical: 'top', borderWidth: 1, borderColor: TH.border, marginBottom: 16 }} />
              <TouchableOpacity onPress={addCustomSutra} disabled={!customName.trim()}
                style={{ backgroundColor: '#D4A574', borderRadius: 12, padding: 14, alignItems: 'center', opacity: customName.trim() ? 1 : 0.5 }}>
                <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BODY() }}>{T('sutraImportBtn')}</Text>
              </TouchableOpacity>
            </View>
          </View>
        </Modal>
      </View>
    );
  }


  if (page === 'start' && selectedSutra) {
    const handleDownloadAudio = async () => {
      if (!selectedSutra?.audioUrl) return;
      try {
        await downloadAudio(selectedSutra.id, selectedSutra.audioUrl);
        setAudioCached(true);
      } catch {
        Alert.alert(T('chantingDownloadFailed'));
      }
    };

    const handlePreviewAudio = async () => {
      if (isPlaying) {
        await stopSutra();
      } else {
        await playSutra(selectedSutra.id, { loop: false });
      }
    };

    return (
      <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
        {/* Back button */}
        <TouchableOpacity onPress={() => { stopSutra(); setPage('select'); }}
          style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingTop: 8, paddingBottom: 8 }}>
          <Text style={{ fontSize: FONT_STAT_CARD(), color: TH.text }}>←</Text>
          <Text style={{ fontSize: FONT_BODY(), color: TH.text, marginLeft: 8 }}>{T('chantingBack')}</Text>
        </TouchableOpacity>

        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', padding: 24 }}>
          <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: TH.text, marginBottom: 8, textAlign: 'center' }}>{selectedSutra.name}</Text>
          {selectedSutra.subtitle && (
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 16, textAlign: 'center' }}>{selectedSutra.subtitle}</Text>
          )}
          {selectedSutra.pronunciation && (
            <Text style={{ fontSize: FONT_BODY(), color: '#D4A574', marginBottom: 16, textAlign: 'center' }}>{selectedSutra.pronunciation}</Text>
          )}
          {selectedSutra.meaning && (
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 16, textAlign: 'center', fontStyle: 'italic' }}>{selectedSutra.meaning}</Text>
          )}
          {selectedSutra.pageCount != null && (
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 24, textAlign: 'center' }}>{selectedSutra.pageCount} {T('sutraPages')} · 每遍 108 颗</Text>
          )}

          {/* Audio section */}
          {selectedSutra.audioUrl ? (
            <View style={{ alignItems: 'center', marginBottom: 24 }}>
              {downloading === selectedSutra.id ? (
                <View style={{ paddingVertical: 12, paddingHorizontal: 24, borderRadius: 14, backgroundColor: '#D4A57415', borderWidth: 1, borderColor: '#D4A57430', minWidth: 200, alignItems: 'center' }}>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#D4A574' }}>{T('chantingDownloadProgress')} {Math.round(dlProgress * 100)}%</Text>
                  <View style={{ height: 4, width: '100%', backgroundColor: `${TH.border}60`, borderRadius: 2, marginTop: 8 }}>
                    <View style={{ height: 4, width: `${dlProgress * 100}%`, backgroundColor: '#D4A574', borderRadius: 2 }} />
                  </View>
                </View>
              ) : (
                <TouchableOpacity onPress={audioCached ? handlePreviewAudio : handleDownloadAudio}
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 12, paddingHorizontal: 24, borderRadius: 14, backgroundColor: '#D4A57415', borderWidth: 1, borderColor: '#D4A57430' }}>
                  <Text style={{ fontSize: FONT_BACK() }}>{isPlaying ? '🔊' : audioCached ? '▶️' : '⬇️'}</Text>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#D4A574' }}>
                    {isPlaying ? T('chantingListening') : audioCached ? T('chantingListening') : T('chantingDownloadAudio')}
                  </Text>
                </TouchableOpacity>
              )}
              {selectedSutra.audioAttribution ? (
                <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 8, textAlign: 'center' }}>
                  {T('chantingAudioSource')}: {selectedSutra.audioAttribution}
                </Text>
              ) : null}
            </View>
          ) : (
            <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 24 }}>{T('chantingNoAudio')}</Text>
          )}

          <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 8 }}>{T('sutraTargetRounds')}</Text>
          <View style={{ flexDirection: 'row', gap: 8, marginBottom: 32, flexWrap: 'wrap', justifyContent: 'center' }}>
            {[1, 3, 7, 21, 108].map(n => (
              <TouchableOpacity key={n} onPress={() => setTargetRounds(n)}
                style={{ paddingHorizontal: 14, paddingVertical: 8, borderRadius: 10, backgroundColor: targetRounds === n ? '#D4A574' : TH.border }}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: targetRounds === n ? '#fff' : TH.text }}>{n}</Text>
              </TouchableOpacity>
            ))}
          </View>

          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 24, textAlign: 'center' }}>
            {T('sutraTargetDesc')}: {targetRounds} 遍 · 每遍 108 颗
          </Text>

          <TouchableOpacity onPress={beginChanting}
            style={{ paddingVertical: 16, paddingHorizontal: 48, borderRadius: 16, backgroundColor: '#D4A574' }}>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: '#fff' }}>{T('sutraStartChantNew')}</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }


  if (page === 'active') {
    const currentRound = Math.floor(count / BEAD_COUNT);

    const handleToggleAudio = async () => {
      if (!selectedSutra) return;
      if (isPlaying) {
        stopSutra();
      } else {
        const ok = await playSutra(selectedSutra.id, { loop: true });
        if (!ok) Alert.alert(T('chantingPleaseDownloadFirst'));
      }
    };

    return (
      <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
        {/* Exit button */}
        <TouchableOpacity onPress={handleExitActive}
          style={{ position: 'absolute', top: 16, right: 16, zIndex: 10, paddingVertical: 8, paddingHorizontal: 12, borderRadius: 8, backgroundColor: `${TH.card}CC` }}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#EF4444' }}>✕ {T('chantingExit')}</Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}
          activeOpacity={1}
          onPress={handleTap}
        >
          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginBottom: 4 }}>{selectedSutra?.name}</Text>
          {selectedSutra?.pronunciation && (
            <Text style={{ fontSize: FONT_SMALL(), color: '#D4A574', marginBottom: 4 }}>{selectedSutra.pronunciation}</Text>
          )}

          <MalaRing
            count={count}
            beadCount={BEAD_COUNT}
            size={280}
            beadColor="#D4A574"
            trackColor={TH.border + '40'}
            textColor="#D4A574"
            centerSubLabel={String(BEAD_COUNT)}
            centerLabel={T('sutraRound') + ' ' + currentRound}
          />

          <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 16 }}>
            {formatTime(elapsed)} · {T('sutraTargetDesc')}: {targetRounds} 遍
          </Text>

          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub + '80', marginTop: 8 }}>
            {T('sutraTapAnywhere')}
          </Text>
        </TouchableOpacity>

        <View style={{ flexDirection: 'row', justifyContent: 'space-around', paddingHorizontal: 20, paddingBottom: 20 }}>
          <TouchableOpacity onPress={handleUndo}
            style={{ paddingVertical: 12, paddingHorizontal: 16, borderRadius: 12, backgroundColor: TH.card }}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{T('sutraUndo')}</Text>
          </TouchableOpacity>

          <TouchableOpacity onPress={handleToggleAudio}
            style={{ paddingVertical: 12, paddingHorizontal: 16, borderRadius: 12, backgroundColor: isPlaying ? '#D4A574' : TH.card }}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: isPlaying ? '#fff' : TH.text }}>
              {isPlaying ? '🔊' : '🔇'}
            </Text>
          </TouchableOpacity>

          {isPaused ? (
            <TouchableOpacity onPress={togglePause}
              style={{ paddingVertical: 12, paddingHorizontal: 20, borderRadius: 12, backgroundColor: '#10B981' }}>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#fff' }}>{T('sutraResume')}</Text>
            </TouchableOpacity>
          ) : (
            <TouchableOpacity onPress={togglePause}
              style={{ paddingVertical: 12, paddingHorizontal: 20, borderRadius: 12, backgroundColor: TH.card }}>
              <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{T('sutraPause')}</Text>
            </TouchableOpacity>
          )}

          <TouchableOpacity onPress={endSession}
            style={{ paddingVertical: 12, paddingHorizontal: 24, borderRadius: 12, backgroundColor: '#EF4444' }}>
            <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: '#fff' }}>{T('sutraStop')}</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }


  // report page — use pendingSessionData for session-specific numbers (not stale state)
  const psd = pendingSessionData;
  const reportCount = psd?.count ?? 0;
  const reportRounds = psd?.rounds ?? 0;
  const reportDurationSec = psd?.durationSec ?? 0;
  const totalAfter = selectedSutra ? getMantraTotalCount(selectedSutra.id) : 0;
  const streak = selectedSutra ? getMantraStreak(selectedSutra.id) : 0;

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingTop: 8, paddingBottom: 8 }}>
        <TouchableOpacity onPress={resetSession} style={{ marginRight: 12 }}>
          <Text style={{ fontSize: FONT_STAT_CARD(), color: TH.text }}>←</Text>
        </TouchableOpacity>
        <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: TH.text, flex: 1 }}>{T('sutraChantComplete')}</Text>
      </View>
      <ScrollView contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 40 }}>

        <View style={{ borderRadius: 20, overflow: 'hidden', marginBottom: 16 }}>
          <View style={{ backgroundColor: '#D4A574', padding: 24, alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_HERO() }}>☸</Text>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '800', color: '#fff', marginTop: 8 }}>{selectedSutra?.name}</Text>
            <Text style={{ fontSize: scaleFontSize(36), fontWeight: '800', color: '#fff', marginTop: 8 }}>
              {reportCount.toLocaleString()} 颗 · {reportRounds} 遍
            </Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.8)', marginTop: 4 }}>
              {reportDurationSec > 60 ? Math.floor(reportDurationSec / 60) + 'm' : reportDurationSec + 's'}
            </Text>
          </View>
        </View>

        <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 16 }}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-around' }}>
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#D4A574' }}>{totalAfter.toLocaleString()}</Text>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('sutraTotalRounds')}</Text>
            </View>
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#F59E0B' }}>🔥 {streak}</Text>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('sutraStreak')}</Text>
            </View>
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '800', color: '#10B981' }}>
                {reportDurationSec > 60 ? Math.floor(reportDurationSec / 60) + 'm' : reportDurationSec + 's'}
              </Text>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('sutraSessionDuration')}</Text>
            </View>
          </View>
