// ── Tests ────────────────────────────────────────────────────────────
describe('SyncApplyService', () => {
  let svc: SyncApplyService;

  beforeEach(() => {
    vi.clearAllMocks();
    resetMockDb();
    svc = new SyncApplyService();
  });

  // ── Pure method tests (4) ──────────────────────────────────────────
  describe('serverPayloadToRow', () => {
