  recoverOrphans: mockRecoverOrphans,
  shouldRunOrphanRecovery: mockShouldRunOrphanRecovery,
}));

vi.mock('@egoless-do/core', () => ({
  apiSyncPush: mockApiSyncPush,
  apiSyncPull: mockApiSyncPull,
  apiSyncPullPost: mockApiSyncPullPost,
  apiSyncCheck: mockApiSyncCheck,
  createLogger: () => ({ debug: vi.fn(), error: vi.fn(), warn: vi.fn(), info: vi.fn() }),
  ApiError: mockApiError,
  KickedOutError: mockKickedOutError,
  ALL_ENTITY_TABLES: ['habits'],
  SCHEMAS: { habit: { sqlite: { table: 'habits' }, pocketbase: { collection: 'habits' } } },
}));

// Dynamic import mocks
vi.mock('../../store/syncStore', () => ({
  useSyncStore: { getState: () => ({ addConflict: vi.fn() }) },
}));

// ── Import SUT ────────────────────────────────────────────────────
import { SyncEngine } from './SyncEngine';

// ── Helpers ───────────────────────────────────────────────────────

function makeEngine(overrides: Record<string, unknown> = {}) {
  return new SyncEngine({
    applyService: overrides.applyService as never ?? mockApplyService,
    realtimeController: overrides.realtimeController as never ?? mockRealtimeController,
    rehydrationManager: overrides.rehydrationManager as never ?? mockRehydrationManager,
    resetService: overrides.resetService as never ?? mockResetService,
    timestampManager: overrides.timestampManager as never ?? mockTimestampManager,
  });
}

function makeQueueItem(id: number, entity: string, entityId: string, op = 'upsert', payload = '{}') {
  return { id, entity, entity_id: entityId, operation: op, payload, retry_count: 0, created_at: Date.now() };
}

// ── Tests ─────────────────────────────────────────────────────────

describe('SyncEngine', () => {
  let engine: SyncEngine;

  beforeEach(() => {
    vi.clearAllMocks();

    // Default DB mock
    mockOpenDatabase.mockResolvedValue(mockDb);
    mockDb.runAsync.mockResolvedValue({ changes: 1 });

    // Default apply service mock
    mockApplyService.applyServerChanges.mockResolvedValue({});
    mockApplyService.serverPayloadToRow.mockReturnValue(null);

    // Default app store mock
    mockAppStore._auth = { token: null, refreshToken: null, user: null };
    mockAppStore.getState.mockReturnValue(mockAppStore);

    engine = makeEngine();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  // ================================================================
  // Configuration & State
  // ================================================================

  describe('Configuration & State', () => {
    it('setTokenProvider / getUserIdProvider correctly wires providers', () => {
      const tokenFn = () => 'my-token';
      const userIdFn = () => 'user-1';
      engine.setTokenProvider(tokenFn);
      engine.setUserIdProvider(userIdFn);

      // Connect realtime triggers tokenProvider — proves it was stored
      mockRealtimeController.isRealtimeConnected.mockReturnValue(false);
      engine.connectRealtime();
      expect(mockRealtimeController.connectRealtime).toHaveBeenCalledWith(
        undefined,
        expect.any(Function), // token getter
        expect.any(Function), // change handler
        expect.any(Function), // kicked-out handler
        expect.any(Function), // lastSyncAt getter (was raw value, now a function)
        expect.any(Function), // deletedIds provider
        expect.any(Function), // onServerTime callback
      );
      // Verify the token getter returns our value
      // vitest mock.calls is any[][] — extract typed callback
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const tokenGetter = mockRealtimeController.connectRealtime.mock.calls[0][1];
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      expect(tokenGetter()).toBe('my-token');
    });

    it('triggerSyncDebounced fires callback after 2-second debounce', () => {
      vi.useFakeTimers();
      const cb = vi.fn();
      engine.setSyncTriggerCallback(cb);
      engine.setTokenProvider(() => 'test-token');

      engine.triggerSyncDebounced();
      expect(cb).not.toHaveBeenCalled();

      vi.advanceTimersByTime(2000);
      expect(cb).toHaveBeenCalledTimes(1);
    });

    it('triggerSyncDebounced resets timer on repeated calls', () => {
      vi.useFakeTimers();
      const cb = vi.fn();
      engine.setSyncTriggerCallback(cb);
      engine.setTokenProvider(() => 'test-token');

      engine.triggerSyncDebounced();
      vi.advanceTimersByTime(1000);
      engine.triggerSyncDebounced(); // reset
      vi.advanceTimersByTime(1000);
      expect(cb).not.toHaveBeenCalled(); // not yet

      vi.advanceTimersByTime(1000);
      expect(cb).toHaveBeenCalledTimes(1);
    });

    it('clearSyncTrigger cancels pending debounce', () => {
      vi.useFakeTimers();
      const cb = vi.fn();
      engine.setSyncTriggerCallback(cb);
      engine.setTokenProvider(() => 'test-token');

      engine.triggerSyncDebounced();
      engine.clearSyncTrigger();
      vi.advanceTimersByTime(5000);
      expect(cb).not.toHaveBeenCalled();
    });

    it('isSyncing returns current sync state', () => {
      expect(engine.isSyncing()).toBe(false);
    });
  });

  // ================================================================
  // runSync — concurrency control
  // ================================================================

  describe('runSync concurrency control', () => {
    it('rejects concurrent call when _syncing=true', async () => {
      engine.setTokenProvider(() => 'token');
      // First sync hangs on drainQueue — but _syncing is set synchronously before await
      let resolveDrain: (v: unknown[]) => void;
      mockDrainQueue.mockImplementation(() => new Promise(r => { resolveDrain = r; }));

      const p1 = engine.runSync();
      // Yield to microtask so runSync gets past token check and into drainQueue
      await new Promise<void>(r => setTimeout(r, 0));

      // Second sync should return immediately since _syncing=true
      await engine.runSync();
      expect(engine.isSyncing()).toBe(true);

      // Release the first sync
      resolveDrain!([]);
      await p1;
    });

    it('120-second timeout forces reset and allows new sync', async () => {
      vi.useFakeTimers();
      vi.setSystemTime(0);

      // Start a sync that hangs
      mockDrainQueue.mockImplementation(() => new Promise(() => {})); // never resolves
      const p1 = engine.runSync();
      // Drain microtasks
      await vi.advanceTimersByTimeAsync(0);

      // Advance time past 120s timeout
      vi.setSystemTime(121_000);

      // New sync should succeed — it aborts the old one
      mockDrainQueue.mockResolvedValue([]);
      await engine.runSync();
      expect(engine.isSyncing()).toBe(false);

      // Clean up
      vi.advanceTimersByTime(100_000);
      try { await p1; } catch { /* ignore */ }
    });

    it('proceeds when _initialSyncing=true (no longer defers)', async () => {
      // Set _initialSyncing directly via private access
      (engine as unknown as Record<string, boolean>)._initialSyncing = true;
      engine.setTokenProvider(() => 'token');

      await engine.runSync();

      // The deferral was removed; sync proceeds normally
      expect(mockDrainQueue).toHaveBeenCalled();
    });
  });

  // ================================================================
  // Token recovery
  // ================================================================

  describe('Token recovery', () => {
    it('attempts refreshAuth when token is null, then syncs', async () => {
      mockAppStore._auth = { token: null, refreshToken: 'refresh-123', user: { id: 'u1' } };
      mockAppStore.refreshAuth.mockImplementation(async () => {
        mockAppStore._auth.token = 'refreshed-token';
      });
      mockDrainQueue.mockResolvedValue([]);
      mockAppStore.getState.mockReturnValue(mockAppStore);
      engine.setTokenProvider(() => mockAppStore._auth?.token ?? null);
      engine.setTokenRecoveryFn(async () => {
        await mockAppStore.refreshAuth();
        return mockAppStore._auth.token;
      });

      await engine.runSync();

      expect(mockAppStore.refreshAuth).toHaveBeenCalled();
      expect(mockDrainQueue).toHaveBeenCalled();
    });

    it('does NOT call logout when refreshAuth fails (preserve auth state)', async () => {
      mockAppStore._auth = { token: null, refreshToken: 'refresh-123', user: { id: 'u1' } };
      mockAppStore.getState.mockReturnValue(mockAppStore);
      mockAppStore.refreshAuth.mockResolvedValue(undefined);
      engine.setTokenProvider(() => mockAppStore._auth?.token ?? null);
      engine.setUserIdProvider(() => mockAppStore._auth?.user?.id ?? null);
      engine.setTokenRecoveryFn(async () => {
        await mockAppStore.refreshAuth();
        return mockAppStore._auth.token;
      });
      engine.setKickedOutHandler(() => mockAppStore.logout());

      await engine.runSync();

      expect(mockAppStore.logout).not.toHaveBeenCalled();
      expect(mockDrainQueue).not.toHaveBeenCalled();
    });

    it('does NOT call logout when user was never logged in', async () => {
      mockAppStore._auth = { token: null, refreshToken: null, user: null };
      mockAppStore.getState.mockReturnValue(mockAppStore);
      engine.setTokenProvider(() => mockAppStore._auth?.token ?? null);
      engine.setUserIdProvider(() => mockAppStore._auth?.user?.id ?? null);
      engine.setKickedOutHandler(() => mockAppStore.logout());

      await engine.runSync();

      expect(mockAppStore.logout).not.toHaveBeenCalled();
      expect(mockDrainQueue).not.toHaveBeenCalled();
    });

    it('proactively refreshes a near-expiry token before syncing', async () => {
      // Token is present but expires in 1 min (within 5-min skew) → runSync
      // should call the recovery fn to refresh before proceeding.
      mockAppStore._auth = {
        token: 'stale-token',
        refreshToken: 'refresh-123',
        user: { id: 'u1' },
        expiresAt: Date.now() + 60 * 1000,
      };
      mockAppStore.refreshAuth.mockImplementation(async () => {
        mockAppStore._auth.token = 'refreshed-token';
        mockAppStore._auth.expiresAt = Date.now() + 60 * 60 * 1000;
      });
      mockDrainQueue.mockResolvedValue([]);
      mockAppStore.getState.mockReturnValue(mockAppStore);
      engine.setTokenProvider(() => mockAppStore._auth?.token ?? null);
      engine.setTokenExpiryProvider(() => mockAppStore._auth?.expiresAt);
      const recoveryFn = vi.fn(async () => {
        await mockAppStore.refreshAuth();
        return mockAppStore._auth.token ?? null;
      });
      engine.setTokenRecoveryFn(recoveryFn);

      await engine.runSync();

      expect(recoveryFn).toHaveBeenCalled();
      expect(mockAppStore.refreshAuth).toHaveBeenCalled();
      expect(mockDrainQueue).toHaveBeenCalled();
    });

    it('does NOT refresh a far-future-expiry token', async () => {
      mockAppStore._auth = {
        token: 'fresh-token',
        refreshToken: 'refresh-123',
        user: { id: 'u1' },
        expiresAt: Date.now() + 60 * 60 * 1000, // 1h — well outside skew
      };
      mockDrainQueue.mockResolvedValue([]);
      mockAppStore.getState.mockReturnValue(mockAppStore);
      engine.setTokenProvider(() => mockAppStore._auth?.token ?? null);
      engine.setTokenExpiryProvider(() => mockAppStore._auth?.expiresAt);
      const recoveryFn = vi.fn(async () => 'should-not-be-called');
      engine.setTokenRecoveryFn(recoveryFn);

      await engine.runSync();

      expect(recoveryFn).not.toHaveBeenCalled();
      expect(mockDrainQueue).toHaveBeenCalled();
    });
  });

  // ================================================================
  // executePush
  // ================================================================

  describe('executePush', () => {
    beforeEach(() => {
      engine.setTokenProvider(() => 'token');
    });

    it('skips push when queue is empty', async () => {
      mockDrainQueue.mockResolvedValue([]);
      await engine.runSync();
      expect(mockApiSyncPush).not.toHaveBeenCalled();
    });

    it('batch pushes + marks accepted items synced', async () => {
      const items = [
        makeQueueItem(1, 'habit', 'h1'),
        makeQueueItem(2, 'habit', 'h2'),
      ];
      // First drain returns items, second returns empty (end loop)
      mockDrainQueue.mockResolvedValueOnce(items).mockResolvedValueOnce([]);
      mockApiSyncPush.mockResolvedValueOnce({ serverTime: Date.now(), rejected: [] });

      await engine.runSync();

      expect(mockApiSyncPush).toHaveBeenCalledTimes(1);
      const callArgs = mockApiSyncPush.mock.calls[0];
      expect(callArgs[1]).toBe(0); // lastSyncAt
      expect(callArgs[2]).toHaveLength(2); // 2 changes
      expect(mockApplyService.markSyncedAndRemove).toHaveBeenCalledWith(
        expect.objectContaining({ habit: ['h1', 'h2'] }),
        expect.anything(),
        expect.anything(),
        expect.any(Function),
      );
    });

    it('API failure triggers exponential backoff retry', async () => {
      const items = [makeQueueItem(1, 'habit', 'h1')];
      mockDrainQueue.mockResolvedValueOnce(items);
      mockApiSyncPush.mockRejectedValueOnce(new Error('Network error'));

      await engine.runSync();

      // retry_count=0, new count=1, delay = min(2^1 * 1000, 60000) = 2000
      expect(mockMarkQueueItemRetry).toHaveBeenCalledWith(1, 1, expect.any(Number));
    });

    it('marks item as failed after MAX_RETRY_ATTEMPTS (5)', async () => {
      const items = [makeQueueItem(1, 'habit', 'h1', 'upsert')];
      items[0].retry_count = 4; // next attempt will be 5
      mockDrainQueue.mockResolvedValueOnce(items);
      mockApiSyncPush.mockRejectedValueOnce(new Error('fail'));

      await engine.runSync();

      expect(mockMarkQueueItemFailed).toHaveBeenCalledWith(1, 'fail');
      expect(mockMarkQueueItemRetry).not.toHaveBeenCalled();
    });

    it('auto-resolves rejected items with serverData (server-wins)', async () => {
      const items = [makeQueueItem(1, 'habit', 'h1')];
      mockDrainQueue.mockResolvedValueOnce(items);

      mockApplyService.serverPayloadToRow.mockReturnValueOnce({ name: 'Updated', id: 'h1' });
      mockApiSyncPush.mockResolvedValueOnce({
        serverTime: Date.now(),
        rejected: [{ entity: 'habit', entityId: 'h1', serverData: { name: 'Updated' } }],
      });

      await engine.runSync();

      // Should have run UPDATE + possible INSERT
      expect(mockDb.runAsync).toHaveBeenCalledWith(
        expect.stringContaining('UPDATE habits'),
        expect.arrayContaining(['Updated', 'h1']),
      );
      expect(mockRemoveQueueItems).toHaveBeenCalledWith([1]);
    });

    it('marks conflict when rejected item has no serverData', async () => {
      const items = [makeQueueItem(1, 'habit', 'h1')];
      mockDrainQueue.mockResolvedValueOnce(items);

      mockApiSyncPush.mockResolvedValueOnce({
        serverTime: Date.now(),
        rejected: [{ entity: 'habit', entityId: 'h1' }], // no serverData
      });

      await engine.runSync();

      expect(mockMarkQueueItemConflict).toHaveBeenCalledWith(1, 'Server rejected');
    });
  });

  // ================================================================
  // executePull
  // ================================================================

  describe('executePull', () => {
    beforeEach(() => {
      engine.setTokenProvider(() => 'token');
      engine.setUserIdProvider(() => 'user-1');
    });

    it('normal pull calls applyServerChanges', async () => {
      const serverData = { habit: [{ id: 'h1', name: 'test' }] };
      mockDrainQueue.mockResolvedValue([]);
      mockApiSyncCheck.mockResolvedValueOnce({ hasChanges: true, changed: { habit: 1 } });
      mockApiSyncPull.mockResolvedValueOnce({ data: serverData, serverTime: Date.now() });
      mockApplyService.applyServerChanges.mockResolvedValueOnce({ habits: [{ id: 'h1' }] });

      await engine.runSync();

      expect(mockApiSyncPull).toHaveBeenCalledWith('token', 'user-1', undefined);
      expect(mockApplyService.applyServerChanges).toHaveBeenCalledWith(
        serverData,
        expect.any(Set),
        expect.anything(),
        expect.any(Number), // clockOffset
      );
    });

    it('push rejection causes pull of only conflicted entities (apiSyncPullPost)', async () => {
      const items = [makeQueueItem(1, 'habit', 'h1')];
      mockDrainQueue.mockResolvedValueOnce(items);

      mockApiSyncPush.mockResolvedValueOnce({
        serverTime: Date.now(),
        rejected: [{ entity: 'habit', entityId: 'h1' }],
      });
      // apiSyncPullPost for post-push pull and for conflict pull
      mockApiSyncPullPost.mockResolvedValue({ data: {}, serverTime: Date.now() });

      await engine.runSync();

      // The pull phase with rejections uses apiSyncPullPost, not apiSyncPull
      expect(mockApiSyncPullPost).toHaveBeenCalled();
    });

    it('abort signal interrupts pull phase', async () => {
      engine.setTokenProvider(() => 'token');

      mockDrainQueue.mockResolvedValue([]);
      mockApiSyncCheck.mockResolvedValueOnce({ hasChanges: true, changed: { habit: 1 } });
      mockApiSyncPull.mockImplementation(async () => {
        // By the time pull resolves, abort has already been signaled in the push→pull flow
        return { data: {}, serverTime: Date.now() };
      });
      mockApplyService.applyServerChanges.mockRejectedValueOnce(
        new TestDOMException('Aborted', 'AbortError'),
      );

      // Should not throw — caught by the try/catch in runSync
      await engine.runSync();

      expect(mockApplyService.applyServerChanges).toHaveBeenCalled();
    });
  });

  // ================================================================
  // Kicked-out detection
  // ================================================================

  describe('Kicked-out detection', () => {
    beforeEach(() => {
      engine.setTokenProvider(() => 'token');
      const kickedOutFn = vi.fn();
      engine.setKickedOutHandler(kickedOutFn);
    });

    it('push-phase 401 KICKED_OUT triggers kicked-out callback', async () => {
      mockDrainQueue.mockResolvedValueOnce([makeQueueItem(1, 'habit', 'h1')]);
      const err = new mockApiError(401, 'KICKED_OUT', 'Session expired');
      mockApiSyncPush.mockRejectedValueOnce(err);

      await engine.runSync();

      expect(mockRealtimeController.disconnectRealtime).toHaveBeenCalled();
    });

    it('pull-phase 401 KICKED_OUT triggers kicked-out callback', async () => {
      mockDrainQueue.mockResolvedValue([]);
      const err = new mockKickedOutError('Kicked out');
      mockApiSyncCheck.mockRejectedValueOnce(err);

      await engine.runSync();

      expect(mockRealtimeController.disconnectRealtime).toHaveBeenCalled();
    });
  });

  // ================================================================
  // Reset delegation
  // ================================================================

  describe('Reset delegation', () => {
    it('softReset delegates to SyncResetService', async () => {
      await engine.softReset();
      expect(mockResetService.softReset).toHaveBeenCalledWith(
        expect.any(Function), // disconnectRealtime
        expect.any(Function), // resetLastSyncAt
      );
      // Verify the callbacks work
      // vitest mock.calls is any[][] — extract typed callbacks
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const disconnectCb = mockResetService.softReset.mock.calls[0][0];
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const resetCb = mockResetService.softReset.mock.calls[0][1];
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      disconnectCb();
      expect(mockRealtimeController.disconnectRealtime).toHaveBeenCalled();
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      resetCb();
      expect(mockTimestampManager.resetLastSyncAt).toHaveBeenCalled();
    });

    it('hardReset delegates to SyncResetService with confirm token', async () => {
      await engine.hardReset('CONFIRM_HARD_RESET');
      expect(mockResetService.hardReset).toHaveBeenCalledWith(
        'CONFIRM_HARD_RESET',
        expect.any(Function),
        expect.any(Function),
      );
    });
  });

  // ================================================================
  // forceFullSync
  // ================================================================

  describe('forceFullSync', () => {
    it('resets lastSyncAt to 0 before running sync', async () => {
      engine.setTokenProvider(() => 'token');
      mockDrainQueue.mockResolvedValue([]);

      await engine.forceFullSync();

      expect(mockTimestampManager.resetLastSyncAt).toHaveBeenCalled();
      expect(mockTimestampManager.saveLastSyncAt).toHaveBeenCalledWith(0);
    });
  });

  // ================================================================
  // recordMetric
  // ================================================================

  describe('recordMetric', () => {
    it('records metrics with correct fields', () => {
      (engine as unknown as Record<string, (...args: unknown[]) => unknown>).recordMetric(1500, 5, 3, true);
      const metrics = engine.getSyncMetrics();
      expect(metrics).toHaveLength(1);
      expect(metrics[0]).toMatchObject({
        durationMs: 1500,
        pushed: 5,
        pulled: 3,
        success: true,
      });
    });

    it('caps at 20 entries (MAX_METRICS)', () => {
      for (let i = 0; i < 25; i++) {
        (engine as unknown as Record<string, (...args: unknown[]) => unknown>).recordMetric(i, 0, 0, true);
      }
      expect(engine.getSyncMetrics()).toHaveLength(20);
      // Oldest entries should be dropped — first entry is now from i=5
      expect(engine.getSyncMetrics()[0].durationMs).toBe(5);
    });
  });

  // ================================================================
  // Orphan recovery
  // ================================================================

  describe('orphanRecovery', () => {
    beforeEach(() => {
      engine.setTokenProvider(() => 'token');
    });

    it('runs orphanRecovery when condition is met (30s cooldown)', async () => {
      mockShouldRunOrphanRecovery.mockReturnValue(true);
      mockRecoverOrphans.mockResolvedValue({ total: 2, byEntity: { habit: 2 } });
      mockDrainQueue.mockResolvedValue([]);

      await engine.runSync();

      expect(mockRecoverOrphans).toHaveBeenCalled();
    });

    it('skips orphanRecovery when condition not met', async () => {
      mockShouldRunOrphanRecovery.mockReturnValue(false);
      mockDrainQueue.mockResolvedValue([]);

      await engine.runSync();

      expect(mockRecoverOrphans).not.toHaveBeenCalled();
    });
  });

  // ================================================================
  // Rehydration delegation
  // ================================================================

  describe('Rehydration delegation', () => {
    it('rehydrateFromDb delegates to SyncRehydrationManager', async () => {
      mockRehydrationManager.rehydrateFromDb.mockResolvedValue({ habits: [{ id: 'h1' }] });
      const patch = await engine.rehydrateFromDb(['habit']);
      expect(mockRehydrationManager.rehydrateFromDb).toHaveBeenCalledWith(['habit']);
      expect(patch).toEqual({ habits: [{ id: 'h1' }] });
    });

    it('lazyRehydrate delegates to SyncRehydrationManager', async () => {
      engine.setChangeHandler(() => {});
      await engine.lazyRehydrate('habit');
      expect(mockRehydrationManager.lazyRehydrate).toHaveBeenCalledWith('habit', expect.any(Function));
    });
  });

  // ================================================================
  // getSyncStatus
  // ================================================================

  describe('getSyncStatus', () => {
    it('returns current status', async () => {
      mockGetQueueCount.mockResolvedValue(5);
      mockTimestampManager.getLastSyncAt.mockReturnValue(1000);

      const status = await engine.getSyncStatus();

      expect(status).toEqual({
        lastSyncAt: 1000,
        pendingCount: 5,
        isSyncing: false,
      });
    });

    it('handles getQueueCount failure gracefully', async () => {
      mockGetQueueCount.mockRejectedValue(new Error('db error'));

      const status = await engine.getSyncStatus();
      expect(status.pendingCount).toBe(0);
    });
  });

  // ================================================================
  // Edge cases
  // ================================================================

  describe('Edge cases', () => {
    it('triggerSyncDebounced warns when no callback set', () => {
      engine.triggerSyncDebounced();
      // Should not throw — just logs a warning
    });

    it('connectRealtime returns early when no token', () => {
      engine.connectRealtime();
      expect(mockRealtimeController.connectRealtime).not.toHaveBeenCalled();
    });

    it('runSync handles corrupt queue item payload gracefully', async () => {
      engine.setTokenProvider(() => 'token');
      const badItem = { ...makeQueueItem(1, 'habit', 'h1'), payload: 'invalid-json' };
      mockDrainQueue.mockResolvedValueOnce([badItem]).mockResolvedValueOnce([]);

      await engine.runSync();

      expect(mockMarkQueueItemFailed).toHaveBeenCalledWith(1, 'Corrupt payload');
      expect(mockApiSyncPush).not.toHaveBeenCalled(); // no valid changes
    });

    it('runSync completes even when cleanup throws', async () => {
      engine.setTokenProvider(() => 'token');
      mockDrainQueue.mockResolvedValue([]);
      // Force cleanup failure
      mockDb.runAsync.mockRejectedValue(new Error('cleanup error'));

      // Should not throw
      await engine.runSync();
      expect(engine.isSyncing()).toBe(false);
    });

    it('MigrationDone getter/setter works', () => {
      expect(engine.getMigrationDone()).toBe(false);
      engine.setMigrationDone(true);
      expect(engine.getMigrationDone()).toBe(true);
    });
  });
});

import {
  apiSyncPush, apiSyncPull, apiSyncPullPost, apiSyncCheck,
  createLogger, ApiError, KickedOutError,
  ALL_ENTITY_TABLES,
} from '@egoless-do/core';
import type { SyncEntity, SyncPushResult, SyncPullResult } from '@egoless-do/core';

import { openDatabase, getState, setState, withDbLock } from '../../db/schema';
import { isValidSqlName } from '../../db/sqlHelper';
import {
  drainQueue, removeQueueItems, getQueueCount, pruneStaleQueueItems,
  markQueueItemFailed, markQueueItemConflict, markQueueItemRetry, resetAllPendingForRetry,
  getLastSyncTimestamp, setLastSyncTimestamp,
  type SyncQueueItem,
} from '../../db/syncQueue';
import { flushWrites } from '../../store/storageAdapter';

import { SyncApplyService, ENTITY_CONFIG } from './SyncApplyService';
import { SyncRealtimeController } from './SyncRealtimeController';
import { SyncRehydrationManager } from './SyncRehydrationManager';
import { SyncResetService } from './SyncResetService';
import { SyncTimestampManager } from './SyncTimestampManager';
import { recoverOrphans, shouldRunOrphanRecovery, type EntityConfig, type GetRowMapperFn } from './orphanRecovery';

const DOMException = (globalThis as Record<string, unknown>).DOMException as typeof Error | undefined
  ?? class DOMException extends Error {
    constructor(message?: string, name?: string) {
      super(message);
      this.name = name ?? 'DOMException';
    }
  };

const log = createLogger('SyncEngine');
const PUSH_PULL_SEPARATE_THRESHOLD = 20;
const SYNC_TIMEOUT_MS = 120_000;
const MAX_RETRY_ATTEMPTS = 5;
// Proactively refresh the access token if it expires within this skew window.
// Matches the 5-min window used in useSync.ts so all sync triggers (debounced
// writes, foreground, realtime) benefit, not just the useSync foreground path.
const TOKEN_REFRESH_SKEW_MS = 5 * 60 * 1000;

// ALL_ENTITY_TABLES is now imported from @egoless-do/core (derived from SCHEMAS)

export interface SyncMetric {
  timestamp: number;
  durationMs: number;
  pushed: number;
  pulled: number;
  success: boolean;
  error?: string;
}

export interface SyncEngineDeps {
  applyService?: SyncApplyService;
  realtimeController?: SyncRealtimeController;
  rehydrationManager?: SyncRehydrationManager;
  resetService?: SyncResetService;
  timestampManager?: SyncTimestampManager;
  // Injectable db and queue dependencies (for testability)
  db?: {
    openDatabase: typeof openDatabase;
    getState: typeof getState;
    setState: typeof setState;
    withDbLock: typeof withDbLock;
  };
  syncQueue?: {
    drainQueue: typeof drainQueue;
    removeQueueItems: typeof removeQueueItems;
    getQueueCount: typeof getQueueCount;
    pruneStaleQueueItems: typeof pruneStaleQueueItems;
    markQueueItemFailed: typeof markQueueItemFailed;
    markQueueItemConflict: typeof markQueueItemConflict;
    markQueueItemRetry: typeof markQueueItemRetry;
    resetAllPendingForRetry: typeof resetAllPendingForRetry;
    setLastSyncTimestamp: typeof setLastSyncTimestamp;
  };
  storageAdapter?: {
    flushWrites: typeof flushWrites;
  };
}

export class SyncEngine {
  private _applyService: SyncApplyService;
  private _realtimeController: SyncRealtimeController;
  private _rehydrationManager: SyncRehydrationManager;
  private _timestampManager: SyncTimestampManager;
  private _resetService: SyncResetService;
  private _db: NonNullable<SyncEngineDeps['db']> | null = null;
  private _syncQueue: NonNullable<SyncEngineDeps['syncQueue']> | null = null;
  private _storageAdapter: NonNullable<SyncEngineDeps['storageAdapter']> | null = null;

  constructor(deps?: SyncEngineDeps) {
    this._applyService = deps?.applyService ?? new SyncApplyService();
    this._realtimeController = deps?.realtimeController ?? new SyncRealtimeController();
    this._rehydrationManager = deps?.rehydrationManager ?? new SyncRehydrationManager();
    this._timestampManager = deps?.timestampManager ?? new SyncTimestampManager();
    this._resetService = deps?.resetService ?? new SyncResetService();
    this._db = deps?.db ?? null;
    this._syncQueue = deps?.syncQueue ?? null;
    this._storageAdapter = deps?.storageAdapter ?? null;
  }

  // ── Injected-dependency helpers (fall back to direct imports) ──────────
  private _openDatabase(): ReturnType<typeof openDatabase> {
    return this._db ? this._db.openDatabase() : openDatabase();
  }
  private _withDbLock<T>(fn: () => Promise<T>): Promise<T> {
    return this._db ? this._db.withDbLock(fn) : withDbLock(fn);
  }
  private _flushWrites(): ReturnType<typeof flushWrites> {
    return this._storageAdapter ? this._storageAdapter.flushWrites() : flushWrites();
  }
  private _drainQueue(limit: number): ReturnType<typeof drainQueue> {
    return this._syncQueue ? this._syncQueue.drainQueue(limit) : drainQueue(limit);
  }
  private _removeQueueItems(ids: number[]): ReturnType<typeof removeQueueItems> {
    return this._syncQueue ? this._syncQueue.removeQueueItems(ids) : removeQueueItems(ids);
  }
  private _getQueueCount(): ReturnType<typeof getQueueCount> {
    return this._syncQueue ? this._syncQueue.getQueueCount() : getQueueCount();
  }
  private _pruneStaleQueueItems(): ReturnType<typeof pruneStaleQueueItems> {
    return this._syncQueue ? this._syncQueue.pruneStaleQueueItems() : pruneStaleQueueItems();
  }
  private _markQueueItemFailed(id: number, reason: string): ReturnType<typeof markQueueItemFailed> {
    return this._syncQueue ? this._syncQueue.markQueueItemFailed(id, reason) : markQueueItemFailed(id, reason);
  }
  private _markQueueItemConflict(id: number, reason: string): ReturnType<typeof markQueueItemConflict> {
    return this._syncQueue ? this._syncQueue.markQueueItemConflict(id, reason) : markQueueItemConflict(id, reason);
  }
  private _markQueueItemRetry(id: number, attempt: number, nextRetryAt: number): ReturnType<typeof markQueueItemRetry> {
    return this._syncQueue ? this._syncQueue.markQueueItemRetry(id, attempt, nextRetryAt) : markQueueItemRetry(id, attempt, nextRetryAt);
  }
  private _resetAllPendingForRetry(): ReturnType<typeof resetAllPendingForRetry> {
    return this._syncQueue ? this._syncQueue.resetAllPendingForRetry() : resetAllPendingForRetry();
  }
  private _setLastSyncTimestamp(entity: string, iso: string): ReturnType<typeof setLastSyncTimestamp> {
    return this._syncQueue ? this._syncQueue.setLastSyncTimestamp(entity, iso) : setLastSyncTimestamp(entity, iso);
  }

  private _syncing = false;
  private _syncingSince = 0;
  private _syncGeneration = 0;
  private _abortController: AbortController | null = null;
  private _orphanRecoveryDone = false;
  private _migrationDone = false;
  private _syncMetrics: SyncMetric[] = [];
  private static MAX_METRICS = 20;
  private _tokenProvider: (() => string | null) | null = null;
  private _userIdProvider: (() => string | null) | null = null;
  private _tokenExpiryProvider: (() => number | null | undefined) | null = null;
  private _onChanges: ((patch: Record<string, unknown>) => void) | null = null;
  private _deletedIdsProvider: (() => Set<string>) | null = null;
  private _onKickedOut: (() => void) | null = null;
  private _tokenRecoveryFn: (() => Promise<string | null>) | null = null;
  private _hasSyncedDeletes = false;
  private _forcePull = false;
  private _lastRoutineCleanupAt = 0;
  private _initialSyncing = false;
  private _lastOrphanScanAt = 0;
  private _syncTriggerCallback: (() => void) | null = null;
  private _syncTriggerTimer: ReturnType<typeof setTimeout> | null = null;
  private static SYNC_TRIGGER_DEBOUNCE_MS = 2000;
  private _onSyncError: ((error: string) => void) | null = null;

  // ── Configuration ────────────────────────────────────────────────
  setTokenProvider(fn: () => string | null) { this._tokenProvider = fn; }
  setUserIdProvider(fn: () => string | null) { this._userIdProvider = fn; }
  /** Provides the token's absolute expiry (ms epoch) so runSync can refresh proactively. */
  setTokenExpiryProvider(fn: () => number | null | undefined) { this._tokenExpiryProvider = fn; }
  setChangeHandler(fn: (patch: Record<string, unknown>) => void) { this._onChanges = fn; }
  setDeletedIdsProvider(fn: () => Set<string>) { this._deletedIdsProvider = fn; }
  setKickedOutHandler(fn: () => void) { this._onKickedOut = fn; }
  setTokenRecoveryFn(fn: () => Promise<string | null>) { this._tokenRecoveryFn = fn; }
  setRealtimeLogoutHandler(fn: () => void) { this._realtimeController.setLogoutHandler(fn); }
  setRealtimeUserIdProvider(fn: () => string | undefined) { this._realtimeController.setUserIdProvider(fn); }
  setRealtimeRunSync(fn: () => void) { this._realtimeController.setRunSync(fn); }
  setRealtimeApplyServerChanges(fn: (data: Record<string, unknown[]>, deletedIds: Set<string>) => Promise<Record<string, unknown>>) { this._realtimeController.setApplyServerChanges(fn); }
  setMigrationDone(v: boolean) { this._migrationDone = v; }
  getMigrationDone(): boolean { return this._migrationDone; }
  setSyncErrorHandler(fn: (error: string) => void) { this._onSyncError = fn; }
  setLastSyncAt(ts: number) { this._timestampManager.setLastSyncAt(ts); }
  getClockOffset(): number { return this._timestampManager.getClockOffset(); }

  // ── Debounced sync trigger ────────────────────────────────────────
  setSyncTriggerCallback(fn: () => void) { this._syncTriggerCallback = fn; }

  triggerSyncDebounced(): void {
    if (!this._syncTriggerCallback) {
      log.warn('triggerSyncDebounced called but _syncTriggerCallback is null');
      return;
    }
    // Guard: skip entirely if not authenticated (prevents false kicked-out on cold start)
    const token = this._tokenProvider?.();
    if (!token) {
      log.debug('triggerSyncDebounced: no token, skipping');
      return;
    }
    if (this._syncTriggerTimer) clearTimeout(this._syncTriggerTimer);
    this._syncTriggerTimer = setTimeout(async () => {
      this._syncTriggerTimer = null;
      log.debug('Debounced sync trigger firing');
      this._syncTriggerCallback?.();
      // Only re-trigger if there's still a token (prevents infinite loop after logout)
      const freshToken = this._tokenProvider?.();
      if (!freshToken) return;
      const remaining = await this._getQueueCount();
      if (remaining > 0) this.triggerSyncDebounced();
    }, SyncEngine.SYNC_TRIGGER_DEBOUNCE_MS);
  }

  clearSyncTrigger(): void {
    if (this._syncTriggerTimer) { clearTimeout(this._syncTriggerTimer); this._syncTriggerTimer = null; }
  }

  async isDeviceSyncedBefore(): Promise<boolean> {
    return this._rehydrationManager.isDeviceSyncedBefore();
  }

  // ── Realtime (SSE) ───────────────────────────────────────────────
  connectRealtime(pbUrl?: string): void {
    const token = this._tokenProvider?.();
    if (!token) return;

    this.disconnectRealtime();
    // Wire callbacks to eliminate dynamic imports in SyncRealtimeController
    this._realtimeController.setRunSync(() => { this.runSync().catch(e => log.error(e, { phase: 'realtime-sync' })); });
    this._realtimeController.setApplyServerChanges(
      (data, deletedIds) => this._applyService.applyServerChanges(data, deletedIds, undefined, this.clockOffset),
    );
    this._realtimeController.connectRealtime(
      pbUrl,
      () => this._tokenProvider?.() ?? null,
      (patch) => this._onChanges?.(patch),
      () => this.handleKickedOut(),
      () => this._timestampManager.getLastSyncAt(),
      () => this._deletedIdsProvider?.() ?? new Set(),
      (serverTime) => {
        if (serverTime > 0) {
          this._timestampManager.setLastSyncAt(Math.max(this._timestampManager.getLastSyncAt(), serverTime));
          void this._timestampManager.saveLastSyncAt(this._timestampManager.getLastSyncAt());
          this._timestampManager.updateClockOffset(serverTime);
        }
      },
    );
  }

  disconnectRealtime(): void {
    this._realtimeController.disconnectRealtime();
  }

  isRealtimeConnected(): boolean {
    return this._realtimeController.isRealtimeConnected();
  }

  // ── Clock offset & timestamp (delegated to SyncTimestampManager) ──
  private get lastSyncAt() { return this._timestampManager.getLastSyncAt(); }
  private set lastSyncAt(ts: number) { this._timestampManager.setLastSyncAt(ts); }
  private get clockOffset() { return this._timestampManager.getClockOffset(); }

  // ── Soft/Hard reset (delegated to SyncResetService) ─────────────────
  async softReset(): Promise<void> {
    return this._resetService.softReset(
      () => this.disconnectRealtime(),
      () => this._timestampManager.resetLastSyncAt(),
    );
  }

  async hardReset(confirmToken?: string): Promise<void> {
    this._syncing = false;
    return this._resetService.hardReset(
      confirmToken,
      () => this.disconnectRealtime(),
      () => this._timestampManager.resetLastSyncAt(),
    );
  }

  // ── Kicked out ───────────────────────────────────────────────────
  private isKickedOutError(err: unknown): boolean {
    return err instanceof KickedOutError || (err instanceof ApiError && err.status === 401 && err.code === 'KICKED_OUT');
  }

  private handleKickedOut() {
    log.warn('Kicked out');
    this.disconnectRealtime();
    this._onKickedOut?.();
  }

  // ── Apply server changes (delegated to SyncApplyService) ─────────────
  async applyServerChanges(data: Record<string, unknown[]>, deletedIds?: Set<string>, signal?: AbortSignal): Promise<Record<string, unknown>> {
    return this._applyService.applyServerChanges(data, deletedIds, signal, this.clockOffset);
  }

  // ── Server payload helpers (delegated to SyncApplyService) ───────────
  private serverPayloadToRow(entity: string, r: Record<string, unknown>): Record<string, unknown> | null {
    return this._applyService.serverPayloadToRow(entity, r);
  }

  // ── Mark synced helpers (delegated to SyncApplyService) ──────────────
  private async markSyncedAndRemove(upserted: Record<string, string[]>, deleted: Record<string, string[]>, queueIds: number[]): Promise<void> {
    return this._applyService.markSyncedAndRemove(upserted, deleted, queueIds, () => { this._hasSyncedDeletes = true; });
  }

  // ── Push phase ──────────────────────────────────────────────────
  private async executePush(
    token: string,
    userId: string | undefined,
    freshToken: () => string,
    lastSyncAt: number,
    signal: AbortSignal,
    generation: number,
  ): Promise<{ pushedAnything: boolean; pushedItemCount: number; pushApplySucceeded: boolean; lastPushResult: SyncPushResult | null }> {
    let pushedAnything = false;
    let pushedItemCount = 0;
    let pushApplySucceeded = false;
    let lastPushResult: SyncPushResult | null = null;

    for (let batch = 0; batch < 10; batch++) {
      // Reset items stuck in 'syncing' status from a previous crashed sync
      // before drainQueue so they get picked up again
      try {
        await this._resetAllPendingForRetry();
      } catch (e) { log.error(e, { phase: 'resetStuck' }); }
      const items = await this._drainQueue(50).catch(e => { log.error(e, { phase: 'drain' }); return [] as SyncQueueItem[]; });
      log.debug(`drainQueue batch ${batch + 1}: ${items.length} items`);
      if (!items.length) break;
      pushedAnything = true;
      pushedItemCount += items.length;

      const changes: Array<{ entity: SyncEntity; entityId: string; payload: Record<string, unknown>; operation: 'upsert' | 'delete'; changedFields?: string[] }> = [];
      for (const item of items) {
        try {
          const parsed = JSON.parse(item.payload) as Record<string, unknown> & { _changedFields?: string[] };
          const changedFields = parsed._changedFields;
          if (changedFields) delete parsed._changedFields;
          changes.push({ entity: item.entity as SyncEntity, entityId: item.entity_id, payload: parsed, operation: item.operation === 'delete' ? 'delete' : 'upsert', changedFields });
        } catch {
          await this._markQueueItemFailed(item.id, 'Corrupt payload');
        }
      }
      if (!changes.length) continue;

      let pushResult: SyncPushResult;
      try {
        pushResult = await apiSyncPush(freshToken(), lastSyncAt, changes, userId, signal);
        log.info(`Push OK: ${changes.length} changes, serverTime=${pushResult.serverTime}, rejected=${pushResult.rejected?.length ?? 0}`);
      } catch (pushErr: unknown) {
        if (this.isKickedOutError(pushErr)) { this.handleKickedOut(); return { pushedAnything, pushedItemCount, pushApplySucceeded, lastPushResult: null }; }
        log.error(pushErr, { phase: 'push' });
        for (const item of items) {
          try {
            const na = item.retry_count + 1;
            if (na >= MAX_RETRY_ATTEMPTS) await this._markQueueItemFailed(item.id, (pushErr instanceof Error ? pushErr.message : null) || 'Push failed');
            else await this._markQueueItemRetry(item.id, na, Date.now() + Math.min(Math.pow(2, na) * 1000, 60000));
          } catch (markErr) {
            // Atomicity guard: if marking retry fails, mark as failed instead of losing the item
            log.error(markErr, { phase: 'markRetry-fallback', itemId: item.id });
            try { await this._markQueueItemFailed(item.id, 'Retry mark failed'); } catch (e) { log.error(e, { phase: 'markRetry-fallback' }); } // last resort
          }
        }
        break;
      }
      lastPushResult = pushResult;

      const rejectedSet = new Set<string>();
      if (Array.isArray(pushResult.rejected)) {
        for (const r of pushResult.rejected) {
          if (r) rejectedSet.add(`${r.entity}:${r.entityId}`);
        }
      }
      const acceptedItems = items.filter(i => !rejectedSet.has(`${i.entity}:${i.entity_id}`));
      const rejectedItems = items.filter(i => rejectedSet.has(`${i.entity}:${i.entity_id}`));

      // Auto-resolve conflicts (server-wins)
      const autoResolvedIds: number[] = [];
      for (const item of rejectedItems) {
        const rejection = pushResult.rejected?.find(
          (r) => r?.entity === item.entity && r?.entityId === item.entity_id,
        );
        if (rejection?.serverData) {
          try {
            const config = ENTITY_CONFIG[item.entity];
            let resolved = false;
            if (config) {
              if (!isValidSqlName(config.table)) throw new Error(`Invalid table name: ${config.table}`);
              if (!isValidSqlName(config.pk)) throw new Error(`Invalid pk name: ${config.pk}`);
              // Server says record is deleted — mark local as deleted too
              if (rejection.error === 'deleted') {
                await this._withDbLock(async () => {
                  const db = await this._openDatabase();
                  await db.runAsync(
                    `UPDATE ${config.table} SET deleted=1, synced=1 WHERE ${config.pk}=?`,
                    [item.entity_id],
                  );
                });
                log.debug(`[SyncEngine] Marked ${item.entity}:${item.entity_id} as deleted (server rejected)`);
                resolved = true;
              } else {
              const row = this._applyService.serverPayloadToRow(item.entity, rejection.serverData);
              if (row) {
                const cols = Object.keys(row);
                const vals = Object.values(row) as (string | number | null)[];
                for (const col of cols) {
                  if (!isValidSqlName(col)) throw new Error(`Invalid column name: ${col}`);
                }
                if (cols.length) {
                  const db = await this._openDatabase();
                  const skipReason = await this._withDbLock<string | null>(async () => {
                    // Don't resurrect locally-deleted records
                    const local = await db.getFirstAsync<{ deleted: number }>(
                      `SELECT deleted FROM ${config.table} WHERE ${config.pk}=?`, [item.entity_id],
                    );
                    if (local?.deleted === 1) {
                      await this._markQueueItemConflict(item.id, 'Locally deleted');
                      return 'deleted';
                    }
                    const setClause = cols.map(c => `${c}=?`).join(',');
                    const r2 = await db.runAsync(`UPDATE ${config.table} SET ${setClause},deleted=0,synced=1 WHERE ${config.pk}=?`, [...vals, item.entity_id]);
                    if (r2.changes === 0) {
                      await db.runAsync(`INSERT INTO ${config.table} (${cols.join(',')},synced) VALUES (${cols.map(() => '?').join(',')},1)`, vals);
                    }
                    return null;
                  });
                  if (skipReason === 'deleted') {
                    log.debug(`[SyncEngine] Skipping auto-resolve for deleted ${item.entity}:${item.entity_id}`);
                    continue;
                  }
                  resolved = true;
                }
              }
              } // end else (not 'deleted' error)
            }
            if (resolved) {
              autoResolvedIds.push(item.id);
            } else {
              await this._markQueueItemConflict(item.id, 'Invalid serverData');
              try {
                const { useSyncStore } = await import('../../store/syncStore');
                useSyncStore.getState().addConflict({
                  id: item.id.toString(),
                  entity: item.entity,
                  entityId: item.entity_id,
                  localData: item.payload,
                  remoteData: rejection.serverData,
                  timestamp: Date.now(),
                });
              } catch (e) { log.warn(e, { phase: 'addConflict' }); } // intentional: conflict UI is optional
            }
          } catch (resolveErr) {
            log.error(resolveErr, { entity: item.entity, id: item.entity_id, phase: 'auto-resolve' });
            await this._markQueueItemConflict(item.id, 'Auto-resolve failed');
          }
        } else {
          // No serverData → cannot auto-resolve.
          // If this item has been retried too many times, mark as permanently failed to avoid infinite loop.
          if (item.retry_count + 1 >= MAX_RETRY_ATTEMPTS) {
            await this._markQueueItemFailed(item.id, rejection?.error || 'Server rejected — max retries exceeded');
            log.warn(`[SyncEngine] Permanently failed: ${item.entity}:${item.entity_id} (${rejection?.error})`);
          } else {
            await this._markQueueItemConflict(item.id, rejection?.error || 'Server rejected');
          }
        }
      }
      if (autoResolvedIds.length) await this._withDbLock(async () => { await this._removeQueueItems(autoResolvedIds); });

      // Mark synced
      try {
        const upserted: Record<string, string[]> = {};
        const deletedMap: Record<string, string[]> = {};
        for (const item of acceptedItems) {
          (item.operation === 'delete' ? deletedMap : upserted)[item.entity] ??= [];
          (item.operation === 'delete' ? deletedMap : upserted)[item.entity].push(item.entity_id);
        }
        await this._applyService.markSyncedAndRemove(upserted, deletedMap, acceptedItems.map(i => i.id), () => { this._hasSyncedDeletes = true; });
      } catch (markErr) {
        log.error(markErr, { phase: 'markSyncedAndRemove' });
      }

      // Post-push pull for small batches
      if (pushResult.serverTime && pushedItemCount <= PUSH_PULL_SEPARATE_THRESHOLD) {
        try {
          const affectedEntities = [...new Set(items.map(i => i.entity))];
          const pullResult = await apiSyncPullPost(freshToken(), { entities: affectedEntities, since: lastSyncAt > 0 ? lastSyncAt : undefined });
          if (pullResult?.data) {
            const patch = await this._applyService.applyServerChanges(pullResult.data, this._deletedIdsProvider?.() ?? new Set(), signal, this.clockOffset);
            // Guard: skip _onChanges if this sync was superseded (ghost sync prevention)
            if (patch && Object.keys(patch).length && this._syncGeneration === generation) this._onChanges?.(patch);
            pushApplySucceeded = true;
          }
        } catch (pushPullErr) {
          log.warn(pushPullErr, { phase: 'post-push pull' });
        }
      }
    }

    // Update timestamps once after all push batches complete, outside the loop.
    // This ensures the pull phase can still run even if the signal is aborted after push,
    // since the pull phase has its own timestamp handling for received data.
    if (lastPushResult?.serverTime) {
      this.updateTimestamps(lastPushResult.serverTime, generation);
    }

    return { pushedAnything, pushedItemCount, pushApplySucceeded, lastPushResult };
  }

  // ── Pull phase ──────────────────────────────────────────────────
  private async executePull(
    pushedAnything: boolean,
    pushedItemCount: number,
    lastPushResult: SyncPushResult | null,
    pushApplySucceeded: boolean,
    token: string,
    userId: string | undefined,
    freshToken: () => string,
    signal: AbortSignal,
    myGeneration: number,
  ): Promise<void> {
    // If push applied everything cleanly + no rejections, skip full pull (unless forcePull)
    const pushAllClean = pushedAnything && lastPushResult?.rejected?.length === 0;
    const wasLargePush = pushAllClean && pushedItemCount > PUSH_PULL_SEPARATE_THRESHOLD;
    if (this._forcePull || (!pushAllClean && !pushApplySucceeded)) {
      this._forcePull = false;
      let pullEntities: string[] | undefined;
      // If there were rejections, check only conflicted entities
      const rejected = lastPushResult?.rejected;
      if (rejected && rejected.length > 0) {
        const conflicted = new Set<string>();
        for (const r of rejected) {
          if (r?.entity) conflicted.add(r.entity);
        }
        if (conflicted.size > 0) pullEntities = [...conflicted];
      }

      let hasChanges = true;
      try {
        const cr = pullEntities
          ? { hasChanges: true, changed: Object.fromEntries(pullEntities.map(e => [e, 1])) }
          : await apiSyncCheck(freshToken(), this.lastSyncAt, userId);
        hasChanges = cr.hasChanges;
      } catch (checkErr) {
        if (this.isKickedOutError(checkErr)) { this.handleKickedOut(); return; }
        hasChanges = true;
      }

      if (hasChanges) {
        let pullResult: SyncPullResult | null = null;
        try {
          if (pullEntities) {
            pullResult = await apiSyncPullPost(freshToken(), { entities: pullEntities, since: this.lastSyncAt > 0 ? this.lastSyncAt : undefined });
          } else {
            pullResult = await apiSyncPull(freshToken(), userId, this.lastSyncAt > 0 ? this.lastSyncAt : undefined);
          }
        } catch (pullErr) {
          if (this.isKickedOutError(pullErr)) { this.handleKickedOut(); return; }
          log.error(pullErr, { phase: 'pull' });
        }

        if (pullResult?.data) {
          let patch: Record<string, unknown> = {};
          try {
            patch = await this._applyService.applyServerChanges(pullResult.data, this._deletedIdsProvider?.() ?? new Set(), signal, this.clockOffset);
          } catch (applyErr) {
            log.error(applyErr, { phase: 'applyServerChanges' });
          }
          // Guard: skip _onChanges if this sync was superseded (ghost sync prevention)
          if (patch && Object.keys(patch).length && this._syncGeneration === myGeneration) this._onChanges?.(patch);

          // Per-entity timestamps
          try {
            const st = pullResult.serverTime;
            const iso = st > 0 ? new Date(st).toISOString() : new Date().toISOString();
            for (const entity of Object.keys(pullResult.data)) {
              if (Array.isArray(pullResult.data[entity]) && pullResult.data[entity].length > 0) {
                await this._setLastSyncTimestamp(entity, iso);
              }
            }
          } catch (tsErr) {
            log.warn(tsErr, { phase: 'updateSyncTimestamps' });
          }
        }
      }
    }

    // Large-push safeguard: even when push was clean, check if server has new changes
    if (wasLargePush) {
      try {
        const cr = await apiSyncCheck(freshToken(), this.lastSyncAt, userId);
        if (cr.hasChanges) {
          const pullResult = await apiSyncPull(freshToken(), userId, this.lastSyncAt > 0 ? this.lastSyncAt : undefined);
          if (pullResult?.data) {
            const patch = await this._applyService.applyServerChanges(pullResult.data, this._deletedIdsProvider?.() ?? new Set(), signal, this.clockOffset);
            // Guard: skip _onChanges if this sync was superseded (ghost sync prevention)
            if (patch && Object.keys(patch).length && this._syncGeneration === myGeneration) this._onChanges?.(patch);
          }
        }
      } catch (checkErr) {
        if (this.isKickedOutError(checkErr)) { this.handleKickedOut(); return; }
        log.warn(checkErr, { phase: 'large-push check' });
      }
    }
  }

  // ── Timestamp update helper ─────────────────────────────────────
  private updateTimestamps(serverTime: number, generation: number): void {
    if (this._syncGeneration === generation && serverTime > 0) {
      this._timestampManager.setLastSyncAt(Math.max(this._timestampManager.getLastSyncAt(), serverTime));
      void this._timestampManager.saveLastSyncAt(this._timestampManager.getLastSyncAt());
      this._timestampManager.updateClockOffset(serverTime);
    }
  }

  // ── Main sync ────────────────────────────────────────────────────
  async runSync(): Promise<void> {
    // ── Concurrency guard (generation-based, avoids TOCTOU) ──
    // Abort previous sync if timed out
    if (this._syncing && Date.now() - this._syncingSince > SYNC_TIMEOUT_MS) {
      log.warn('Previous sync timed out, aborting');
      this._abortController?.abort();
      this._abortController = null;
      this._syncing = false;
    }

    // Another healthy sync is still running — defer
    if (this._syncing) {
      log.info('Sync already in progress, deferring');
      return;
    }

    const myGeneration = ++this._syncGeneration;

    // ── Token check ────────────────────────────────────────────────────
    let token = this._tokenProvider?.();

    // Proactive token refresh: if the token is present but near expiry, refresh
    // BEFORE attempting push/pull. Centralizes the pre-sync refresh so all sync
    // triggers (debounced writes, foreground, realtime) benefit — previously only
    // the useSync foreground path refreshed, leaving write-triggered syncs to
    // fail with 401 and stall until the next foreground.
    if (token) {
      const expiresAt = this._tokenExpiryProvider?.();
      if (expiresAt && expiresAt < Date.now() + TOKEN_REFRESH_SKEW_MS) {
        try {
          const refreshed = await this._tokenRecoveryFn?.() ?? null;
          if (refreshed) {
            token = refreshed;
            log.info('runSync: token near expiry, refreshed proactively');
          }
        } catch (e) {
          // Best-effort: proceed with the current token; if it's truly expired
          // the server will return 401 and items will be retried next sync.
          log.warn('runSync: proactive token refresh failed', e);
        }
      }
    }

    if (!token) {
      log.warn('runSync: no token, attempting recovery...');
      try {
        if (this._tokenRecoveryFn) {
          log.debug('Attempting token refresh via recovery function...');
          token = await this._tokenRecoveryFn() ?? undefined;
          if (token) log.info('Token refreshed, proceeding with sync');
        }
        if (!token) {
          log.warn('No recovery possible');
          this.clearSyncTrigger();
          // Don't trigger kicked-out here — the auth state is still valid,
          // and the user may have a token that still works for read operations.
          // If the server rejects the token during push/pull, the kicked-out
          // handler will fire then. This prevents premature logout on startup.
          this._syncing = false;
          return;
        }
      } catch (e) {
        log.error(e, { msg: 'Token recovery failed' });
        this._syncing = false;
        return;
      }
    }

    // Token confirmed available — safe to mark as syncing
    this._syncing = true;
    this._syncingSince = Date.now();
    log.info('runSync starting, token present');
    const userId = this._userIdProvider?.() ?? undefined;
    const freshToken = () => this._tokenProvider?.() ?? '';

    // ── Pre-sync preparation ───────────────────────────────────────────
    await this._flushWrites();
    await this._timestampManager.loadLastSyncAt();
    await this._timestampManager.loadClockOffset();
    this._abortController = new AbortController();
    const { signal } = this._abortController;

    // Reset failed/conflict items back to pending so they get another chance
    await this._resetAllPendingForRetry().catch(e => log.error(e, { phase: 'resetFailed' }));
    await this._pruneStaleQueueItems().catch(e => log.error(e, { phase: 'prune' }));

    // Orphan recovery — skip if last sync was <30s ago (orphan events are rare)
    if (shouldRunOrphanRecovery(this._lastOrphanScanAt)) {
      try {
        const result = await recoverOrphans(
          ENTITY_CONFIG as Record<string, EntityConfig>,
          (entity: string) => this._applyService.getRowMapper(entity),
        );
        if (result.total > 0) {
          log.info(`Orphan recovery: ${result.total} items`, { byEntity: result.byEntity });
        }
        this._orphanRecoveryDone = true;
        this._lastOrphanScanAt = Date.now();
      } catch (e) {
        log.error(e, { phase: 'orphan-recovery' });
      }
    }

    // ── Execute phases ─────────────────────────────────────────────────
    try {
      // Push phase
      const ctx = await this.executePush(token, userId, freshToken, this._timestampManager.getLastSyncAt(), signal, myGeneration);
      if (signal.aborted) throw new DOMException('Aborted', 'AbortError');
      if (this._syncGeneration !== myGeneration) { log.info('Sync superseded after push'); return; }

      // Pull phase
      await this.executePull(
        ctx.pushedAnything, ctx.pushedItemCount, ctx.lastPushResult, ctx.pushApplySucceeded,
        token, userId, freshToken, signal,
        myGeneration,
      );

      // Cleanup
      await this.internalCleanup();
      this.recordMetric(Date.now() - this._syncingSince, ctx.pushedItemCount, 0, true);
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : String(err);
      if (err instanceof Error && err.name === 'AbortError') log.warn('Aborted');
      else log.error(err);
      this.recordMetric(Date.now() - this._syncingSince, 0, 0, false, errMsg);
      this._onSyncError?.(errMsg);
    } finally {
      if (this._syncGeneration === myGeneration) {
        this._syncing = false;
        this._abortController = null;
      }
    }
  }

  private recordMetric(durationMs: number, pushed: number, pulled: number, success: boolean, error?: string): void {
    this._syncMetrics.push({ timestamp: Date.now(), durationMs, pushed, pulled, success, error });
    if (this._syncMetrics.length > SyncEngine.MAX_METRICS) this._syncMetrics.shift();
  }

  getSyncMetrics(): SyncMetric[] { return [...this._syncMetrics]; }

  async getSyncStatus(): Promise<{ lastSyncAt: number; pendingCount: number; isSyncing: boolean }> {
    const pendingCount = await this._getQueueCount().catch(() => 0);
    return { lastSyncAt: this._timestampManager.getLastSyncAt(), pendingCount, isSyncing: this._syncing };
  }

  isSyncing(): boolean { return this._syncing; }

  private async purgeDeletedRecords(): Promise<void> {
    try {
      // Note: openDatabase returns a singleton — safe to call outside withDbLock.
      // The lock only guards the DB operations below, not the connection retrieval.
      const db = await this._openDatabase();
      await this._withDbLock(async () => {
        for (const table of ALL_ENTITY_TABLES) {
          if (!isValidSqlName(table)) { log.warn(`Skipping invalid table name: ${table}`); continue; }
          await db.runAsync(`DELETE FROM ${table} WHERE deleted = 1 AND synced = 1`);
        }
      });
    } catch (e) {
      log.error(e, { phase: 'purgeDeletedRecords' });
    }
  }

  private async cleanupCorruptedRecords(): Promise<void> {
    try {
      // Note: openDatabase returns a singleton — safe to call outside withDbLock.
      // The lock only guards the DB operations below, not the connection retrieval.
      const db = await this._openDatabase();
      const done = await getState(db, 'corruptionCleanupDone');
      if (done !== 'true') {
        // First-time cleanup: wrap in withDbLock for transactional safety
        await this._withDbLock(async () => {
          const r1 = await db.runAsync("DELETE FROM habits WHERE name IS NULL OR name = '' OR name = 'undefined'");
          if (r1.changes > 0) log.info(`Cleaned ${r1.changes} corrupted habits`);
          const r2 = await db.runAsync("DELETE FROM mind_reflections WHERE content IS NULL OR content = ''");
          if (r2.changes > 0) log.info(`Cleaned ${r2.changes} corrupted reflections`);
          const r3 = await db.runAsync("DELETE FROM plans WHERE name IS NULL OR name = ''");
          if (r3.changes > 0) log.info(`Cleaned ${r3.changes} corrupted plans`);
          const r4 = await db.runAsync("DELETE FROM exercise_entries WHERE sport_key IS NULL OR sport_key = '' OR sport_key = 'unknown'");
          if (r4.changes > 0) log.info(`Cleaned ${r4.changes} corrupted exercises`);
          await setState(db, 'corruptionCleanupDone', 'true');
        });
      }
      // Throttled routine cleanup — only run every 5 minutes to avoid per-sync overhead
      const ROUTINE_CLEANUP_INTERVAL = 5 * 60 * 1000;
      const now = Date.now();
      if (now - this._lastRoutineCleanupAt > ROUTINE_CLEANUP_INTERVAL) {
        this._lastRoutineCleanupAt = now;
        // Each DELETE in its own try/catch so one failure doesn't block the rest
        try {
          const r5 = await db.runAsync("DELETE FROM mantra_defs WHERE (name IS NULL OR name = '') AND deleted = 0");
          if (r5.changes > 0) log.info(`Cleaned ${r5.changes} corrupted mantra_defs`);
        } catch (e) { log.warn(e, { phase: 'routineCleanup:mantra_defs' }); }
        try {
          const r6 = await db.runAsync("DELETE FROM thought_trails WHERE (name IS NULL OR name = '') AND deleted = 0");
          if (r6.changes > 0) log.info(`Cleaned ${r6.changes} corrupted thought_trails`);
        } catch (e) { log.warn(e, { phase: 'routineCleanup:thought_trails' }); }
        try {
          const r7 = await db.runAsync("DELETE FROM trail_notes WHERE (content IS NULL OR content = '') AND deleted = 0");
          if (r7.changes > 0) log.info(`Cleaned ${r7.changes} corrupted trail_notes`);
        } catch (e) { log.warn(e, { phase: 'routineCleanup:trail_notes' }); }
        try {
          const r8 = await db.runAsync("DELETE FROM visions WHERE (text IS NULL OR text = '') AND deleted = 0");
          if (r8.changes > 0) log.info(`Cleaned ${r8.changes} corrupted visions`);
        } catch (e) { log.warn(e, { phase: 'routineCleanup:visions' }); }
        try {
          const r9 = await db.runAsync("DELETE FROM daily_custom_todos WHERE (name IS NULL OR name = '') AND deleted = 0");
          if (r9.changes > 0) log.info(`Cleaned ${r9.changes} corrupted daily_custom_todos`);
        } catch (e) { log.warn(e, { phase: 'routineCleanup:daily_custom_todos' }); }
      }
    } catch (e) {
      log.error(e, { phase: 'cleanupCorruptedRecords' });
    }
  }

  private async internalCleanup(): Promise<void> {
    await this.cleanupCorruptedRecords();
    if (this._hasSyncedDeletes) {
      await this.purgeDeletedRecords();
      this._hasSyncedDeletes = false;
    }
  }

  // ── Full sync (public API) ───────────────────────────────────────
  async sync(): Promise<void> { return this.runSync(); }
  async push(): Promise<void> { /* push-only not yet needed */ return this.runSync(); }
  async pull(): Promise<void> { /* pull-only not yet needed */ return this.runSync(); }
  async forceFullSync(): Promise<void> {
    const { SCHEMAS } = await import('@egoless-do/core');
    const { openDatabase, withDbLock, setState: setDbState } = await import('../../db/schema');
    const { ENTITY_STORE_KEY } = await import('./SyncApplyService');
    try {
      const db = await openDatabase();
      await withDbLock(async () => {
        const tables = new Set(Object.values(SCHEMAS).map(s => s.sqlite.table));
        // Clear all entity tables but preserve app_state/settings
        for (const table of tables) {
          await db.runAsync(`DELETE FROM ${table}`).catch(() => {});
        }
        // Also clear sync queue to avoid pushing stale ghost deletions
        await db.runAsync('DELETE FROM sync_queue').catch(() => {});
        // Mark initial sync as done so overlay doesn't show
        await setDbState(db, 'initialSyncDone', 'true');
      });
      log.info('Cleared all entity tables for full sync');
    } catch (e) {
      log.warn('Failed to clear tables (non-fatal):', e);
    }
    // Reset sync timestamp and force pull
    this._timestampManager.resetLastSyncAt();
    await this._timestampManager.saveLastSyncAt(0);
    this._forcePull = true;
    // Clear store entity data
    const { useAppStore } = await import('../../store/useAppStore');
    const emptyPatch: Record<string, unknown[]> = {};
    for (const storeKey of Object.values(ENTITY_STORE_KEY)) {
      emptyPatch[storeKey] = [];
    }
    useAppStore.setState(emptyPatch as Parameters<typeof useAppStore.setState>[0]);
    return this.runSync();
  }

  // ── Rehydrate (delegated to SyncRehydrationManager) ─────────────────
  async rehydrateFromDb(entities?: string[]): Promise<Record<string, unknown>> {
    return this._rehydrationManager.rehydrateFromDb(entities);
  }

  /** Register a locally deleted entity so sync won't resurrect it within the next 60s */
  registerLocalDelete(entity: string, id: string) {
    this._applyService.registerLocalDelete(entity, id);
  }

  /** Lazy-load a single entity from SQLite into the store. Useful for cold-start optimization. */
  async lazyRehydrate(entity: string): Promise<void> {
    return this._rehydrationManager.lazyRehydrate(entity, this._onChanges);
  }

  // ── Initial sync (delegated to SyncRehydrationManager) ────────────
  async initialSync(token: string, userId?: string): Promise<'done' | 'partial'> {
    return this._rehydrationManager.initialSync(
      token, userId,
      this.applyServerChanges.bind(this),
      (err) => this.isKickedOutError(err),
      (v) => { this._initialSyncing = v; },
    );
  }

  async resumeInitialSync(token: string, userId?: string): Promise<void> {
    await this._rehydrationManager.resumeInitialSync(
      token, userId,
      this.applyServerChanges.bind(this),
      (err) => this.isKickedOutError(err),
    );
    // Update _lastSyncAt using server-adjusted time to avoid clock skew issues
    const serverNow = Date.now() + this._timestampManager.getClockOffset();
    this._timestampManager.setLastSyncAt(serverNow);
    await this._timestampManager.saveLastSyncAt(serverNow);
  }
}

// ─── SyncRealtimeController ────────────────────────────────────────────
// Extracted from SyncEngine.ts (PR-2 of AR-01 refactoring)
// Manages realtime connection (SSE) and fallback polling.

import { apiSyncPullPost, apiSyncCheck, createLogger, KickedOutError } from '@egoless-do/core';
import type { SyncEntity } from '@egoless-do/core';
import NetInfo from '@react-native-community/netinfo';

import { openDatabase, getState, setState } from '../../db/schema';
import { getQueueCount, resetAllPendingForRetry } from '../../db/syncQueue';

import { RealtimeAgent, type RealtimeChangeEvent } from './RealtimeAgent';

const log = createLogger('SyncRealtime');

export class SyncRealtimeController {
  private _realtimeAgent = new RealtimeAgent();
  private _sseConnected = false;
  private _realtimeFallbackTimer: ReturnType<typeof setInterval> | null = null;
  private _netInfoUnsubscribe: (() => void) | null = null;
  private _realtimeDebounce = new Map<string, ReturnType<typeof setTimeout>>();
  private _realtimeEventTimes = new Map<string, number[]>();
  private _logoutHandler: (() => void) | null = null;
  private _userIdProvider: (() => string | undefined) | null = null;
  private _networkRecoveryTimer: ReturnType<typeof setTimeout> | null = null;
  private _runSync: (() => void) | null = null;
  private _applyServerChanges: ((data: Record<string, unknown[]>, deletedIds: Set<string>) => Promise<Record<string, unknown>>) | null = null;
  private _onServerTime: ((serverTime: number) => void) | null = null;

  constructor() {}

  setLogoutHandler(fn: () => void) { this._logoutHandler = fn; }
  setUserIdProvider(fn: () => string | undefined) { this._userIdProvider = fn; }
  setRunSync(fn: () => void) { this._runSync = fn; }
  setApplyServerChanges(fn: (data: Record<string, unknown[]>, deletedIds: Set<string>) => Promise<Record<string, unknown>>) { this._applyServerChanges = fn; }
  setOnServerTime(fn: (serverTime: number) => void) { this._onServerTime = fn; }

  // ── Connection Management ──────────────────────────────────────────────

  connectRealtime(
    pbUrl: string | undefined,
    getToken: () => string | null,
    onChange: (patch: Record<string, unknown>) => void,
    onKickedOut: () => void,
    getLastSyncAt: () => number,
    deletedIdsProvider: () => Set<string>,
    onServerTime?: (serverTime: number) => void,
  ): void {
    this._onServerTime = onServerTime ?? null;
    const token = getToken();
    if (!token) return;

    this.disconnectRealtime();
    this.startNetworkRecoveryListener(onChange, getLastSyncAt, deletedIdsProvider, getToken);

    if (pbUrl) {
      this._realtimeAgent.setChangeHandler((event) => this.handleRealtimeEvent(event, onChange, getLastSyncAt, deletedIdsProvider, getToken));
      this._realtimeAgent.setStatusHandler((connected) => {
        this._sseConnected = connected;
        if (!connected && !this._realtimeFallbackTimer) this.startFallbackPolling(getToken, onChange, getLastSyncAt, deletedIdsProvider);
        else if (connected) this.stopFallbackPolling();
      });
      // Wire heartbeat failure detection → logout handler
      // Note: RealtimeAgent no longer uses heartbeat failures for kicked-out detection.
      // This handler is kept for compatibility but will only fire if explicitly triggered
      // by the RealtimeAgent in the future. Kicked-out is handled via API 401 KICKED_OUT.
      this._realtimeAgent.setKickedOutHandler(() => {
        log.warn('Realtime heartbeat failure threshold reached, triggering kicked-out');
        this._logoutHandler?.();
      });
      this._realtimeAgent.connect(pbUrl, token, () => getToken() ?? '');
    }
    // Only start fallback polling if SSE isn't going to be connected
    if (!pbUrl) this.startFallbackPolling(getToken, onChange, getLastSyncAt, deletedIdsProvider);
  }

  disconnectRealtime(): void {
    this._realtimeAgent.disconnect();
    this._sseConnected = false;
    this.stopFallbackPolling();
    this.stopNetworkRecoveryListener();
    // Clear pending debounce timers and event time tracking
    for (const timer of this._realtimeDebounce.values()) clearTimeout(timer);
    this._realtimeDebounce.clear();
    this._realtimeEventTimes.clear();
  }

  isRealtimeConnected(): boolean {
    return this._sseConnected;
  }

  // ── Fallback Polling ───────────────────────────────────────────────────

  private stopFallbackPolling() {
    if (this._realtimeFallbackTimer) {
      clearInterval(this._realtimeFallbackTimer);
      this._realtimeFallbackTimer = null;
    }
  }

  private startFallbackPolling(
    getToken: () => string | null,
    onChange: (patch: Record<string, unknown>) => void,
    getLastSyncAt: () => number,
    deletedIdsProvider: () => Set<string>,
  ) {
    if (this._realtimeFallbackTimer) return;
    this._realtimeFallbackTimer = setInterval(() => {
      const currentToken = getToken();
      if (currentToken) void this.pollForChanges(currentToken, onChange, getLastSyncAt(), deletedIdsProvider);
    }, 120_000);
  }

  private async pollForChanges(
    token: string,
    onChange: (patch: Record<string, unknown>) => void,
    lastSyncAt: number,
    deletedIdsProvider: () => Set<string>,
  ): Promise<void> {
    try {
      const queueCount = await getQueueCount();
      if (queueCount > 0) {
        this._runSync?.();
        return;
      }

      try {
        const userId = this._userIdProvider?.() ?? undefined;

        const checkResult = await apiSyncCheck(token, lastSyncAt, userId);
        if (!checkResult.hasChanges) return;
        const changedEntities = Object.keys(checkResult.changed);
        if (changedEntities.length > 0) {
          const result = await apiSyncPullPost(token, {
            entities: changedEntities,
            since: lastSyncAt > 0 ? lastSyncAt : undefined,
          });
          if (result?.data) {
            const deletedIds = deletedIdsProvider();
            const patch = await (this._applyServerChanges?.(result.data, deletedIds) ?? Promise.resolve({}));
            if (patch && Object.keys(patch).length) onChange(patch);

            // Update lastSyncAt via callback
            if (result?.serverTime) {
              this._onServerTime?.(result.serverTime);
            }
          }
          return;
        }
      } catch (checkErr) {
        if (checkErr instanceof KickedOutError) {
          this._logoutHandler?.();
          return;
        }
        log.warn(checkErr, { phase: 'poll-check' });
        return;
      }

      this._runSync?.();
    } catch (err) {
      log.error(err, { phase: 'poll' });
    }
  }

  // ── Network Recovery ───────────────────────────────────────────────────

  private startNetworkRecoveryListener(
    onChange: (patch: Record<string, unknown>) => void,
    getLastSyncAt: () => number,
    deletedIdsProvider: () => Set<string>,
    getToken: () => string | null,
  ): void {
    if (this._netInfoUnsubscribe) return;
    this._netInfoUnsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected && state.isInternetReachable) {
        // Debounce: network flapping can fire rapid connect/disconnect events;
        // wait 2 seconds of stability before acting to avoid repeated resets.
        if (this._networkRecoveryTimer) clearTimeout(this._networkRecoveryTimer);
        this._networkRecoveryTimer = setTimeout(() => {
          this._networkRecoveryTimer = null;
          (async () => {
            const count = await resetAllPendingForRetry().catch(() => 0);
            if (count > 0) {
              log.info(`Network recovered, resetting ${count} items`);
              this._runSync?.();
            }
          })();
        }, 2000);
      }
    });
  }

  private stopNetworkRecoveryListener(): void {
    if (this._networkRecoveryTimer) { clearTimeout(this._networkRecoveryTimer); this._networkRecoveryTimer = null; }
    this._netInfoUnsubscribe?.();
    this._netInfoUnsubscribe = null;
  }

  // ── Realtime Event Handling ────────────────────────────────────────────

  private getAdaptiveDebounce(entity: string): number {
    const times = this._realtimeEventTimes.get(entity) || [];
    const now = Date.now();
    const recent = times.filter(t => now - t < 2000);
    this._realtimeEventTimes.set(entity, [...recent, now]);
    if (recent.length >= 5) return 1500;
    if (recent.length >= 2) return 300;
    return 0;
  }

  handleRealtimeEvent(
    event: RealtimeChangeEvent,
    onChange: (patch: Record<string, unknown>) => void,
    getLastSyncAt: () => number,
    deletedIdsProvider: () => Set<string>,
    getToken: () => string | null,
  ): void {
    const { entity, payload } = event;
    if (!entity) return;

    const delay = this.getAdaptiveDebounce(entity);
    if (delay === 0) {
      void this.processRealtimeEntity(entity, payload, onChange, getLastSyncAt, deletedIdsProvider, getToken);
      return;
    }

    // Debounced path: always use null payload to force incremental pull.
    // This prevents data loss when intermediate events are dropped by debounce.
    // PocketBase SSE sends notifications without per-record payloads, so the
    // pull path (apiSyncPullPost with since=lastSyncAt) catches ALL changes
    // for this entity type regardless of how many events were debounced.
    const existing = this._realtimeDebounce.get(entity);
    if (existing) clearTimeout(existing);
    this._realtimeDebounce.set(entity, setTimeout(() => {
      this._realtimeDebounce.delete(entity);
      void this.processRealtimeEntity(entity, null, onChange, getLastSyncAt, deletedIdsProvider, getToken);
    }, delay));
  }

  private async processRealtimeEntity(
    entity: string,
    payload: unknown,
    onChange: (patch: Record<string, unknown>) => void,
    getLastSyncAt: () => number,
    deletedIdsProvider: () => Set<string>,
    getToken: () => string | null,
  ): Promise<void> {
    const token = getToken();
    if (!token) return;

    try {
      if (payload) {
        // Direct payload processing - apply immediately
        const deletedIds = deletedIdsProvider();
        const patch = await (this._applyServerChanges?.({ [entity]: [payload] }, deletedIds) ?? Promise.resolve({}));
        if (patch && Object.keys(patch).length) onChange(patch);
        return;
      }

      // No payload - do incremental pull
      const currentLastSyncAt = getLastSyncAt();
      const result = await apiSyncPullPost(token, {
        entities: [entity],
        since: currentLastSyncAt > 0 ? currentLastSyncAt : undefined,
      });
      if (result?.data?.[entity]) {
        const deletedIds = deletedIdsProvider();
        const patch = await (this._applyServerChanges?.({ [entity]: result.data[entity] }, deletedIds) ?? Promise.resolve({}));
        if (patch && Object.keys(patch).length) onChange(patch);
      }

      // Update lastSyncAt via callback
      if (result?.serverTime) {
        this._onServerTime?.(result.serverTime);
      }
    } catch (err) {
      if (err instanceof KickedOutError) {
        this._logoutHandler?.();
        return;
      }
      log.warn(err, { phase: 'realtime-pull' });
      // Don't trigger full sync — SSE will retry on next event
    }
  }
}

