        deleted: (r.deleted as number) === 1,
      }),
    },
    {
      entity: 'trailNote', table: 'trail_notes', pk: 'id',
      toPayload: (r) => ({
        id: r.id, trailId: r.trail_id, content: r.content,
        tags: safeJson(r.tags), mood: r.mood, source: r.source,
        guidedQuestion: r.guided_question, noteOrder: r.note_order,
        createdAt: r.created_at, updatedAt: r.updated_at,
        deleted: (r.deleted as number) === 1,
      }),
    },
    {
      entity: 'reflectionLink', table: 'reflection_links', pk: 'link_id',
      toPayload: (r) => ({
        linkId: r.link_id, fromId: r.from_id, toId: r.to_id,
        linkType: r.link_type, note: r.note,
        createdAt: r.created_at, updatedAt: r.updated_at,
        deleted: (r.deleted as number) === 1,
      }),
    },
    {
      entity: 'aiConfig', table: 'ai_configs', pk: 'config_id',
      toPayload: (r) => ({
        configId: r.config_id, mode: r.mode,
        models: safeJson(r.models),
        updatedAt: r.updated_at, deleted: (r.deleted as number) === 1,
      }),
    },
    {
      entity: 'checkinReview', table: 'checkin_reviews', pk: 'id',
      toPayload: (r) => ({
        id: r.id, userId: r.user_id, reviewId: r.review_id,
        period: r.period, startDate: r.start_date, endDate: r.end_date,
        reviewData: safeJson(r.review_data),
        updatedAt: r.updated_at, deleted: (r.deleted as number) === 1,
      }),
    },
  ];

  const db = await openDatabase();

  for (const { entity, table, pk, toPayload } of migrations) {
    const rows = await db.getAllAsync<Record<string, unknown>>(
      `SELECT * FROM ${table}`
    );
    if (rows.length === 0) continue;
    // Batch all inserts for this entity into a single lock acquisition
    const { withDbLock } = await import('../../db/schema');
    await withDbLock(async () => {
      for (const row of rows) {
        const id = row[pk] as string;
        if (!id) continue;
        const isDeleted = (row.deleted as number) === 1;
        const operation = isDeleted ? 'delete' : 'upsert';
        const payload = toPayload(row);
        if (isDeleted) payload.deleted = true;
        await db.runAsync(
          `INSERT INTO sync_queue (entity, entity_id, operation, payload, created_at, status)
           VALUES (?, ?, ?, ?, ?, ?)
           ON CONFLICT(entity, entity_id) DO UPDATE SET
             operation = excluded.operation, payload = excluded.payload,
             created_at = excluded.created_at, status = 'pending',
             retry_count = 0, next_retry_at = 0, last_error = NULL`,
          [entity, id, operation, JSON.stringify(payload), Date.now(), 'pending'],
        );
        count++;
      }
    });
  }

  // Mark migration complete
  await db.runAsync(
    'INSERT OR REPLACE INTO app_state(key, value) VALUES(?, ?)',
    [MIGRATION_KEY, '1']
  );

  log.info('Migrated %d unsynced records to sync_queue', count);
  return count;
}

function safeJson(v: unknown): unknown {
  if (v == null) return [];
  if (typeof v === 'string') { try { return JSON.parse(v) as unknown; } catch { return []; } }
  return v;
}

function safeJsonObj(v: unknown): Record<string, unknown> {
  if (v == null) return {};
  if (typeof v === 'string') { try { const p = JSON.parse(v) as unknown; return (typeof p === 'object' && p !== null && !Array.isArray(p)) ? p as Record<string, unknown> : {}; } catch { return {}; } }
  return (typeof v === 'object' && v !== null && !Array.isArray(v)) ? v as Record<string, unknown> : {};
}

function safeParseColors(v: unknown): unknown {
  if (v == null) return null;
  if (typeof v === 'string') { try { return JSON.parse(v) as unknown; } catch { return null; } }
  return v;
}

// ─── Orphan Recovery Logic ──────────────────────────────────────────
// Extracted from SyncEngine to reduce God Class complexity.
// Finds records in SQLite that are not in sync_queue and re-enqueues them.

import { createLogger } from '@egoless-do/core';
import type { SyncEntity } from '@egoless-do/core';

import { openDatabase } from '../../db/schema';
import { enqueueChange } from '../../db/syncQueue';

const log = createLogger('OrphanRecovery');

/** Entity configuration for orphan recovery */
export interface EntityConfig {
  table: string;
  pk: string;
}

/** Row mapper function type */
export type RowMapper = (row: Record<string, unknown>) => Record<string, unknown>;

/** Function to get row mapper for an entity */
export type GetRowMapperFn = (entity: string) => RowMapper | undefined;

/** Result of orphan recovery scan */
export interface OrphanRecoveryResult {
  total: number;
  byEntity: Record<string, number>;
}

/** Scan for orphaned records and re-enqueue them for sync.
 *  Orphans are records with synced=0 or synced=2 that are not in sync_queue.
 *  Runs up to 5 rounds of 200 items per entity to handle large backlogs.
 */
export async function recoverOrphans(
  entityConfig: Record<string, EntityConfig>,
  getRowMapper: GetRowMapperFn,
  maxRounds = 5,
  batchSize = 200,
): Promise<OrphanRecoveryResult> {
  const db = await openDatabase();
  let total = 0;
  const byEntity: Record<string, number> = {};

  for (let round = 0; round < maxRounds; round++) {
    let roundTotal = 0;

    for (const [entity, config] of Object.entries(entityConfig)) {
      try {
        // Single query: fetch full rows directly (eliminates N+1 pattern)
        const orphans = await db.getAllAsync<Record<string, unknown>>(
          `SELECT * FROM ${config.table} WHERE (synced=0 OR synced=2) AND ${config.pk} NOT IN (SELECT entity_id FROM sync_queue WHERE entity=?) LIMIT ?`,
          [entity, batchSize],
        );

        for (const full of orphans) {
          const id = full[config.pk] as string;
          if (!id) continue;

          try {
            // Convert snake_case SQLite row to camelCase entity for consistent server data
            const mapper = getRowMapper(entity);
            const entityData = mapper ? mapper(full) : full;
            await enqueueChange(entity as SyncEntity, id, 'upsert', entityData as Record<string, unknown>);
          } catch (e) {
            log.error(e, { entity, id, phase: 'orphan-enqueue' });
          }
        }

        const count = orphans.length;
        roundTotal += count;
        if (count > 0) {
          byEntity[entity] = (byEntity[entity] || 0) + count;
        }
      } catch (e) {
        log.error(e, { entity, phase: 'orphan-scan' });
      }
    }

    total += roundTotal;
    if (roundTotal === 0) break;
  }

  return { total, byEntity };
}

/** Check if orphan recovery should run based on last scan time.
 *  Returns true if enough time has passed since last scan.
 */
export function shouldRunOrphanRecovery(lastScanAt: number, minIntervalMs = 30_000): boolean {
  return !lastScanAt || Date.now() - lastScanAt > minIntervalMs;
}

