// ─── useSync hook (mobile) ────────────────────────────────────────
// Connects SyncService to the app lifecycle: foreground triggers sync,
// token comes from Zustand store, server changes update store.
import { registerPushToken, getSyncUrl, createLogger } from '@egoless-do/core';
import type { RecycleBinItem } from '@egoless-do/core';
import { useEffect, useRef, useState, useCallback } from 'react';
import { AppState, Platform, type AppStateStatus } from 'react-native';

import { getState, openDatabase } from '../../db/schema';
import { getQueueCount, setOnEnqueuedCallback } from '../../db/syncQueue';
import { mobileStorageAdapter, flushWrites, setStorageAdapterTrigger, setRegisterLocalDelete } from '../../store/storageAdapter';
import { useSyncStore } from '../../store/syncStore';
import { useAppStore, useShallowStore } from '../../store/useAppStore';
import type { MobileStore } from '../../store/useAppStore';
import { useMusicStore } from '../music/useMusicStore';

import { runSync, setSyncTokenProvider, setSyncUserIdProvider, setSyncChangeHandler, setDeletedIdsProvider, connectRealtime, disconnectRealtime, isMigrationDone, setMigrationDone, resetMigrationFlag, rehydrateFromDb, setKickedOutHandler, resumeInitialSync, setSyncTriggerCallback, triggerSyncDebounced, clearSyncTrigger, registerLocalDelete, setSyncErrorHandler } from './SyncService';
import { mergeSyncPatch } from './mergeSyncPatch';
import { migrateToSyncQueue } from './migrateToSyncQueue';

const log = createLogger('Sync');

type SyncableItem = { id?: string; deleted?: boolean; updatedAt?: number; [k: string]: unknown };
type SyncPatch = Record<string, SyncableItem[] | unknown>;

const getNotifications = () => import('expo-notifications');

export function useSync() {
  const token = useShallowStore(s => s.auth.token);
  const isSignedIn = useShallowStore(s => s.auth.isSignedIn);
  const syncingRef = useRef(false);
  const [kickOutVisible, setKickOutVisible] = useState(false);
  const [hasPendingData, setHasPendingData] = useState(false);

  // Kick out handlers
  const handleSyncAndLogout = useCallback(async () => {
    const auth = useAppStore.getState().auth;
    if (auth.token) {
      try {
        await useAppStore.getState().refreshAuth();
      } catch (e) { log.debug('Token refresh failed during kick-out:', e); }
    }
    const newToken = useAppStore.getState().auth.token;
    if (newToken) {
      try {
        await runSync(); // Push pending data with fresh token
      } catch {
        log.error('Sync before logout failed, staying logged in');
        setKickOutVisible(true); // Re-show dialog on failure
        return;
      }
    }
    setKickOutVisible(false);
    void useAppStore.getState().logout();
  }, []);

  const handleLogoutDirectly = useCallback(() => {
    setKickOutVisible(false);
    void useAppStore.getState().logout();
  }, []);

  // Wire up token provider & change handler once
  useEffect(() => {
    setSyncTokenProvider(() => {
      const state = useAppStore.getState();
      const token = state.auth.token;
      if (!token) {
        log.warn(`tokenProvider: token is null! isSignedIn=${state.auth.isSignedIn}, refreshToken=${state.auth.refreshToken ? 'yes' : 'no'}, expiresAt=${state.auth.expiresAt}`);
      }
      return token;
    });
    log.info('Token provider and sync callbacks registered');
    setSyncUserIdProvider(() => useAppStore.getState().auth.user?.id ?? null);

    // Wire up debounced sync trigger: WriteBatcher flush → triggerSyncDebounced → runSync
    setSyncTriggerCallback(() => { runSync().catch((e) => log.error(e)); });
    setOnEnqueuedCallback(() => { triggerSyncDebounced(); });
    // Wire WriteBatcher flush → triggerSyncDebounced (breaks circular dependency)
    setStorageAdapterTrigger(() => { triggerSyncDebounced(); });
    // Wire local delete → SyncApplyService (prevents sync resurrection)
    setRegisterLocalDelete((entity, id) => { registerLocalDelete(entity, id); });

    // Register kicked out handler
    setKickedOutHandler(async () => {
      const count = await getQueueCount();
      setHasPendingData(count > 0);
      setKickOutVisible(true);
    });

    // Wire sync error to UI store
    setSyncErrorHandler((error) => {
      useSyncStore.getState().setSyncError(error);
    });

    setSyncChangeHandler(async (patch: SyncPatch) => {
      try {
        // Use functional updater to ensure atomicity (prevents race conditions)
        let changedEntities: string[] = [];
        useAppStore.setState((state: MobileStore) => {
          const result = mergeSyncPatch(state, patch);
          changedEntities = result.changedEntities;
          return result.storePatch;
        });

        // Restore music data from synced profile
        if (changedEntities.includes('profile') || patch.userProfile) {
          const up = useAppStore.getState().userProfile;
          if (up) {
            const musicPatch: Record<string, unknown> = {};
            if (up.musicFavorites && Array.isArray(up.musicFavorites)) musicPatch.favorites = up.musicFavorites;
            if (up.musicVolume !== undefined && typeof up.musicVolume === 'number') musicPatch.volume = up.musicVolume;
            if (up.musicPlayMode && typeof up.musicPlayMode === 'string') musicPatch.playMode = up.musicPlayMode;
            if (Object.keys(musicPatch).length) useMusicStore.setState(musicPatch as Partial<ReturnType<typeof useMusicStore.getState>>);
          }
        }

        if (changedEntities.includes('meditation')) {
          useAppStore.getState().calculateTotalMedMin();
        }

        if (changedEntities.includes('checkin')) {
          useAppStore.getState().calculateStreak();
        }
      } catch (callbackErr) {
        log.error(callbackErr, { msg: '_onChanges callback error' });
      }
    });
    // Provide recycle bin IDs so sync can skip locally deleted items
    setDeletedIdsProvider(() => {
      const recycleBin = useAppStore.getState().recycleBin ?? [];
      return new Set(recycleBin.map((r: RecycleBinItem) => r.id as string));
    });
  }, []);

  // Register push token on sign in
  useEffect(() => {
    if (!isSignedIn || !token) return;

    const getExpoPushToken = async () => {
      try {
        const Notifications = await getNotifications();
        const { status: existingStatus } = await Notifications.getPermissionsAsync();
        let finalStatus = existingStatus;

        if (existingStatus !== 'granted') {
          const { status } = await Notifications.requestPermissionsAsync();
          finalStatus = status;
        }

        if (finalStatus !== 'granted') {
          log.info('Permission denied');
          return null;
        }

        const projectId = process.env.EXPO_PUBLIC_PROJECT_ID;
        if (!projectId) {
          log.info('No project ID configured');
          return null;
        }

        const tokenData = await Notifications.getExpoPushTokenAsync({ projectId });
        return tokenData.data;
      } catch (err) {
        log.error(err, { msg: 'Failed to get push token' });
        return null;
      }
    };

    // Retry once with refreshed token if auth fails
    registerPushToken(token, Platform.OS as 'ios' | 'android', getExpoPushToken).catch(() => {
      const { refreshToken, refreshAuth } = useAppStore.getState();
      if (refreshToken) {
        refreshAuth().then(() => {
          const freshToken = useAppStore.getState().auth.token;
          if (freshToken) {
            registerPushToken(freshToken, Platform.OS as 'ios' | 'android', getExpoPushToken).catch(() => {});
          }
        }).catch(() => {});
      }
    });
  }, [isSignedIn, token]);

  // Connect realtime on sign in (short polling)
  useEffect(() => {
    if (!isSignedIn || !token) {
      disconnectRealtime();
      return;
    }

    connectRealtime(getSyncUrl());

    return () => {
      disconnectRealtime();
    };
  }, [isSignedIn, token]);

  // Sync on foreground if signed in
  const prevTokenRef = useRef(token);
  useEffect(() => {
    if (!isSignedIn || !token) return;

    const sync = async () => {
      if (syncingRef.current) return; // Prevent concurrent syncs
      syncingRef.current = true;
      try {
        // Proactive token refresh: only refresh if token is within 5 min of expiry
        const auth = useAppStore.getState().auth;
        if (auth.expiresAt && auth.expiresAt < Date.now() + 5 * 60 * 1000) {
          try {
            await useAppStore.getState().refreshAuth();
          } catch {
            // Best-effort: if refresh fails, sync will handle token recovery
          }
        }

        // One-time migration: move old unsynced records to sync_queue
        if (!isMigrationDone()) {
          await migrateToSyncQueue();
          setMigrationDone();
        }

        // Check if initial sync was interrupted — resume from breakpoint
        const db = await openDatabase();
        const initialDone = await getState(db, 'initialSyncDone');
        if (initialDone !== 'true' && token) {
          const userId = useAppStore.getState().auth.user?.id;
          await resumeInitialSync(token, userId);
          // Rehydrate after resume — flush pending writes first
          await flushWrites();
          const dbPatch = await rehydrateFromDb();
          if (Object.keys(dbPatch).length) {
            useAppStore.setState(dbPatch as Partial<MobileStore>);
          }
          useAppStore.getState().calculateStreak();
          if (dbPatch.medHistory) useAppStore.getState().calculateTotalMedMin();
        }

        // runSync() manages _lastSyncAt internally — no need to set it here
        await runSync();
      } catch (e) {
        log.error(e);
      } finally {
        syncingRef.current = false;
      }
    };

    // Only trigger sync if token actually changed (prevents retry loop on token refresh)
    if (prevTokenRef.current !== token) {
      prevTokenRef.current = token;
    }

    // Initial sync on mount
    void sync();

    // Sync when app returns to foreground
    const sub = AppState.addEventListener('change', (state: AppStateStatus) => {
      if (state === 'active') void sync();
    });

    return () => sub.remove();
  }, [isSignedIn, token]);

  return {
    kickOutVisible,
    hasPendingData,
    handleSyncAndLogout,
    handleLogoutDirectly,
  };
}

import {FONT_BODY, FONT_SUB, FONT_BADGE, type Theme , DedicationSettings, Dedication , FONT_SMALL, scaleFontSize} from '@egoless-do/core';
import { Settings, PenLine, History } from 'lucide-react-native';
import React, { useState, useMemo } from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useAppStore, useShallowStore } from '../../store/useAppStore';

import DedicationCard from './components/DedicationCard';
import DedicationSettingsModal from './modals/DedicationSettingsModal';

interface Props {
  TH: Theme;
  T: (key: string) => string;
  onNavigateToWrite: () => void;
}

export default function DedicationTab({ TH, T, onNavigateToWrite }: Props) {
  const { dedicationSettings, dedications, updateDedicationSettings } = useShallowStore(s => ({ dedicationSettings: s.dedicationSettings, dedications: s.dedications, updateDedicationSettings: s.updateDedicationSettings }));
  const [showSettings, setShowSettings] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const settings = dedicationSettings;
  const filteredDedications = useMemo(() =>
    (dedications ?? [])
      .filter((d: Dedication) => !d.deleted)
      .sort((a: Dedication, b: Dedication) => b.date.localeCompare(a.date)),
    [dedications]
  );

  // Check if overdue (no dedication for current period)
  const isOverdue = useMemo(() => {
    if (filteredDedications.length === 0) return true;
    const latest = filteredDedications[0];
    const latestDate = new Date(latest.date + 'T00:00:00');
    const now = new Date();
    const daysSince = Math.floor((now.getTime() - latestDate.getTime()) / (24 * 60 * 60 * 1000));
    if (settings.frequency === 'weekly' && daysSince >= 7) return true;
    if (settings.frequency === 'biweekly' && daysSince >= 14) return true;
    if (settings.frequency === 'monthly' && daysSince >= 30) return true;
    if (settings.frequency === 'custom' && daysSince >= (settings.customDays ?? 14)) return true;
    return false;
  }, [filteredDedications, settings]);

  const frequencyLabel = useMemo(() => {
    const map: Record<string, string> = {
      weekly: T('vowDedWeekly'),
      biweekly: T('vowDedBiweekly'),
      monthly: T('vowDedMonthly'),
      custom: T('vowDedCustom'),
    };
    return map[settings.frequency] ?? settings.frequency;
  }, [settings.frequency, T]);

  const handleSaveSettings = (newSettings: Partial<DedicationSettings>) => {
    updateDedicationSettings(newSettings);
  };

  return (
    <View>
      {/* Settings summary */}
      <View style={{
        backgroundColor: TH.card,
        borderRadius: 16,
        padding: 16,
        marginBottom: 12,
        borderWidth: 1,
        borderColor: TH.border,
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
      }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
          <Settings size={18} color="#8B5CF6" />
          <View>
            <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }}>
              {T('vowDedSettings')}
            </Text>
            <Text style={{ fontSize: FONT_BADGE(), color: TH.sub, marginTop: 2 }}>
              {frequencyLabel}
              {settings.remindEnabled ? ` · ${T('vowDedRemind')}` : ''}
            </Text>
          </View>
        </View>
        <TouchableOpacity
          onPress={() => setShowSettings(true)}
          style={{
            paddingVertical: 6, paddingHorizontal: 14,
            borderRadius: 8, backgroundColor: '#8B5CF615',
          }}
        >
          <Text style={{ fontSize: FONT_BADGE(), color: '#8B5CF6', fontWeight: '600' }}>
            {T('vowEdit')}
          </Text>
        </TouchableOpacity>
      </View>

      {/* Write dedication button */}
      <TouchableOpacity
        onPress={onNavigateToWrite}
        style={{
          borderRadius: 16, padding: 20, marginBottom: 16,
          backgroundColor: isOverdue ? '#8B5CF6' : `${TH.primary}15`,
          borderWidth: isOverdue ? 0 : 1,
          borderColor: isOverdue ? 'transparent' : `${TH.primary}30`,
          flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 10,
        }}
      >
        <PenLine size={20} color={isOverdue ? '#fff' : '#8B5CF6'} />
        <Text style={{
          fontSize: FONT_BODY(), fontWeight: '700',
          color: isOverdue ? '#fff' : '#8B5CF6',
        }}>
          {T('vowDedWrite')}
        </Text>
        {isOverdue && (
          <View style={{
            backgroundColor: 'rgba(255,255,255,0.2)',
            paddingHorizontal: 8, paddingVertical: 2, borderRadius: 8,
          }}>
            <Text style={{ fontSize: FONT_SMALL(), color: '#fff', fontWeight: '600' }}>
              {T('vowDedNoWrite')}
            </Text>
          </View>
        )}
      </TouchableOpacity>

      {/* History */}
      <View style={{
        flexDirection: 'row', alignItems: 'center', gap: 8,
        marginBottom: 12, marginLeft: 4,
      }}>
        <History size={16} color={TH.sub} />
        <Text style={{ fontSize: FONT_SUB(), fontWeight: '700', color: TH.text }}>
          {T('vowDedHistory')}
        </Text>
        <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>{filteredDedications.length}</Text>
      </View>

      {filteredDedications.length === 0 ? (
        <View style={{
          backgroundColor: TH.card, borderRadius: 16, padding: 24,
          alignItems: 'center', borderWidth: 1, borderColor: TH.border,
        }}>
          <Text style={{ fontSize: scaleFontSize(32), marginBottom: 8 }}>📝</Text>
          <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>
            {T('vowDedNoWrite')}
          </Text>
        </View>
      ) : (
        filteredDedications.map(d => (
          <DedicationCard
            key={d.id}
            TH={TH}
            T={T}
            dedication={d}
            expanded={expandedId === d.id}
            onToggle={() => setExpandedId(expandedId === d.id ? null : d.id)}
          />
        ))
      )}

      {/* Settings modal */}
      <DedicationSettingsModal
        visible={showSettings}
        TH={TH}
        T={T}
        settings={settings}
        onClose={() => setShowSettings(false)}
        onSave={handleSaveSettings}
      />
    </View>
  );
}

import { FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BADGE, FONT_STAT_CARD, dateStr } from '@egoless-do/core';
import type { DedicationType } from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import { Save, ArrowLeft } from 'lucide-react-native';
import React, { useState, useMemo } from 'react';
import { View, Text, ScrollView, TextInput, TouchableOpacity, Alert, StyleSheet } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT, ProgressBar } from '../../components/UI';
import { useAppStore, useShallowStore } from '../../store/useAppStore';

import { useVowProgress } from './useVowProgress';

interface Props {
  onBack: () => void;
}

export default function DedicationWriteScreen({ onBack }: Props) {
  const TH = useTheme();
  const T = useT();
  const { dedicationSettings, addDedication } = useShallowStore(s => ({ dedicationSettings: s.dedicationSettings, addDedication: s.addDedication }));
  const progress = useVowProgress();

  const [insight, setInsight] = useState('');
  const [adjustment, setAdjustment] = useState('');

  const settings = dedicationSettings;
  const { dedicationStats } = progress;
  const { practiceDays, totalDays, habitStats, planProgress, visionProgressData } = dedicationStats;

  const periodLabel = useMemo(() => {
    const now = new Date();
    const today = dateStr(now);
    const map: Record<DedicationType, string> = {
      weekly: `${T('vowDedWeekly')} · ${today}`,
      biweekly: `${T('vowDedBiweekly')} · ${today}`,
      monthly: `${T('vowDedMonthly')} · ${today}`,
      custom: `${T('vowDedCustom')} · ${today}`,
    };
    return map[settings.frequency] ?? today;
  }, [settings.frequency, T]);

  const practicePct = totalDays > 0 ? Math.round((practiceDays / totalDays) * 100) : 0;

  const handleSave = () => {
    addDedication({
      date: dateStr(),
      periodLabel,
      type: settings.frequency,
      practiceDays,
      totalDays,
      habitStats,
      planProgress,
      visionProgress: visionProgressData,
      insight: insight.trim() || undefined,
      adjustment: adjustment.trim() || undefined,
    });
    Alert.alert('', T('vowDedSave'), [{ text: 'OK', onPress: onBack }]);
  };

  return (
    <SafeAreaView edges={['top', 'bottom']} style={[styles.container, { backgroundColor: TH.bg }]}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        {/* Header */}
        <View style={styles.header}>
          <TouchableOpacity onPress={onBack} style={styles.backButton}>
            <ArrowLeft size={20} color={TH.text} />
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: TH.text }]}>
            {T('vowDedWrite')}
          </Text>
        </View>

        {/* Period info */}
        <View style={styles.gradientCard}>
          <LinearGradient
            colors={['#7C3AED', '#8B5CF6']}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={styles.gradientPadding}
          >
            <Text style={styles.gradientSub}>
              {T('vowDedPeriod')}
            </Text>
            <Text style={styles.gradientTitle}>
              {periodLabel}
            </Text>
          </LinearGradient>
        </View>

        {/* Auto-generated summary */}
        <View style={[styles.summaryCard, { backgroundColor: TH.card, borderColor: TH.border }]}>
          <View style={styles.summaryTitleRow}>
            <Text style={[styles.summaryTitle, { color: TH.text }]}>
              {T('vowDedSummary')}
            </Text>
          </View>
          <Text style={[styles.autoHint, { color: TH.sub }]}>
            {T('vowDedAutoHint')}
          </Text>

          {/* Practice days */}
          <View style={styles.sectionWrapper}>
            <View style={styles.habitPlanRow}>
              <Text style={[styles.bodyText, { color: TH.text }]}>{T('vowDedDays')}</Text>
              <Text style={styles.practiceDays}>{practiceDays}/{totalDays}</Text>
            </View>
            <ProgressBar pct={practicePct} color="#8B5CF6" />
          </View>

          {/* Habit stats */}
          {habitStats.length > 0 && (
            <View style={styles.sectionWrapper}>
              <Text style={[styles.sectionTitle, { color: TH.text }]}>
                {T('vowProgressHabitDone')}
              </Text>
              {habitStats.map(h => (
                <View key={h.habitId} style={styles.habitPlanRow}>
                  <Text style={[styles.bodyText, { color: TH.text }]}>{h.name}</Text>
                  <View style={styles.statCountRow}>
                    <Text style={styles.completedCount}>
                      {String(h.completed)}/{String(h.total)}
                    </Text>
                    {h.prevCompleted !== undefined && h.completed > h.prevCompleted && (
                      <Text style={styles.prevDelta}>
                        +{String(h.completed - h.prevCompleted)}
                      </Text>
                    )}
                  </View>
                </View>
              ))}
            </View>
          )}

          {/* Plan progress */}
          {planProgress.length > 0 && (
            <View style={styles.sectionWrapper}>
              <Text style={[styles.sectionTitle, { color: TH.text }]}>
                {T('vowProgressPlanDone')}
              </Text>
              {planProgress.map(p => (
                <View key={p.planId} style={styles.habitPlanRow}>
                  <Text style={[styles.bodyText, { color: TH.text }]}>{p.name}</Text>
                  <Text style={styles.completedCount}>
                    +{p.progressDelta}%
                  </Text>
                </View>
              ))}
            </View>
          )}

          {/* Vision progress */}
          {visionProgressData.length > 0 && (
            <View>
              <Text style={[styles.sectionTitle, { color: TH.text }]}>
                {T('vowProgress')}
              </Text>
              {visionProgressData.map(v => {
                const vision = progress.visionProgress.find(vp => vp.vision.id === v.visionId)?.vision;
                return (
                  <View key={v.visionId} style={styles.habitPlanRow}>
                    <Text style={[styles.bodyText, { color: TH.text }]} numberOfLines={1}>
                      {vision?.text ?? v.visionId}
                    </Text>
                    <Text style={styles.prevDelta}>
                      {v.before}% → {v.after}%
                    </Text>
                  </View>
                );
              })}
            </View>
          )}
        </View>

        {/* Insight input */}
        <View style={styles.inputSection}>
          <Text style={[styles.inputLabel, { color: TH.text }]}>
            {T('vowDedInsight')}
          </Text>
          <TextInput
            value={insight}
            onChangeText={setInsight}
            placeholder={T('vowDedInsightPlaceholder')}
            placeholderTextColor={TH.sub}
            multiline
            maxLength={1000}
            style={[styles.insightInput, { backgroundColor: TH.card, color: TH.text, borderColor: TH.border }]}
          />
        </View>

        {/* Adjustment input */}
        <View style={styles.adjustmentSection}>
          <Text style={[styles.inputLabel, { color: TH.text }]}>
            {T('vowDedAdjustment')}
          </Text>
          <TextInput
            value={adjustment}
            onChangeText={setAdjustment}
            placeholder={T('vowDedAdjustmentPlaceholder')}
            placeholderTextColor={TH.sub}
            multiline
            maxLength={1000}
            style={[styles.adjustmentInput, { backgroundColor: TH.card, color: TH.text, borderColor: TH.border }]}
          />
        </View>

        {/* Save button */}
        <TouchableOpacity
          onPress={handleSave}
          style={styles.saveButton}
        >
          <Save size={18} color="#fff" />
          <Text style={styles.saveButtonText}>
            {T('vowDedSave')}
          </Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingBottom: 40,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
