            </Text>
            <Text style={{ fontSize: FONT_SUB(), color: '#fff', fontWeight: '700' }}>
              {thisWeekPracticeDays}/7
            </Text>
          </View>
          <View style={{ height: 8, backgroundColor: 'rgba(255,255,255,0.2)', borderRadius: 4, overflow: 'hidden' }}>
