import { dateStr } from '@egoless-do/core';
import type { Vision, Dedication, HabitStat, PlanProgress, VisionProgress, Habit, Plan, PlanItem } from '@egoless-do/core';
import { useMemo } from 'react';

import { useAppStore, useShallowStore } from '../../store/useAppStore';


export interface DayData {
  date: string;
  label: string;
  habits: { id: string; name: string }[];
  plans: { id: string; name: string }[];
  isToday: boolean;
}

export interface VowProgressData {
  thisWeekPracticeDays: number;
  thisMonthPracticeDays: number;
  longestStreak: number;
  todayCompleted: { id: string; name: string; type: 'habit' | 'plan' }[];
  dailyData: DayData[];
  visionProgress: { vision: Vision; pct: number }[];
  dedicationStats: {
    practiceDays: number;
    totalDays: number;
    habitStats: HabitStat[];
    planProgress: PlanProgress[];
    visionProgressData: VisionProgress[];
  };
}

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export function useVowProgress(): VowProgressData {
  const { habits, plans, planItems, visions } = useShallowStore(s => ({
    habits: s.habits,
    plans: s.plans,
    planItems: s.planItems,
    visions: s.visions,
  }));

  return useMemo(() => {
    const today = new Date();
    const todayStr = dateStr(today);

    // Compute week boundaries (Mon-Sun)
    const dayOfWeek = today.getDay(); // 0=Sun
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    const monday = new Date(today);
    monday.setDate(today.getDate() + mondayOffset);
    monday.setHours(0, 0, 0, 0);

    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);

    const weekDates: string[] = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      weekDates.push(dateStr(d));
    }

    // Get active habits & plans
    const activeHabits = (habits ?? []).filter((h: Habit) => !h.deleted);
    const activePlans = (plans ?? []).filter((p: Plan) => !p.deleted);

    // Build daily checkin sets from habits
    const dateToHabits = new Map<string, { id: string; name: string }[]>();
    const dateToPlans = new Map<string, { id: string; name: string }[]>();

    for (const h of activeHabits) {
      const dates: string[] = h.checkedDates ?? [];
      for (const date of dates) {
        if (!dateToHabits.has(date)) dateToHabits.set(date, []);
        dateToHabits.get(date)!.push({ id: h.id, name: h.name });
      }
    }

    // Plan progress comes from plan.progress field
    for (const p of activePlans) {
      // Plans don't have daily checkins in the same way; track by progress changes
      // We'll count any plan with progress > 0 as active
    }

    // This week practice days
    const thisWeekPracticeDays = weekDates.filter(d => {
      const h = dateToHabits.get(d);
      const pl = dateToPlans.get(d);
      return (h && h.length > 0) || (pl && pl.length > 0);
    }).length;

    // This month practice days
    const monthStart = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-01`;
    let thisMonthPracticeDays = 0;
    const allPracticeDates = new Set<string>();
    for (const d of dateToHabits.keys()) allPracticeDates.add(d);
    for (const d of dateToPlans.keys()) allPracticeDates.add(d);
    const sortedAll = [...allPracticeDates].sort();
    for (const d of sortedAll) {
      if (d >= monthStart && d <= todayStr) thisMonthPracticeDays++;
    }

    // Longest streak from all practice dates
    let longestStreak = 0;
    let currentStreak = 0;
    const allSorted = [...allPracticeDates].sort();
    for (let i = 0; i < allSorted.length; i++) {
      if (i === 0) {
        currentStreak = 1;
      } else {
        const prev = new Date(allSorted[i - 1] + 'T00:00:00');
        const curr = new Date(allSorted[i] + 'T00:00:00');
        const diffMs = curr.getTime() - prev.getTime();
        const diffDays = diffMs / (24 * 60 * 60 * 1000);
        if (diffDays === 1) {
          currentStreak++;
        } else {
          currentStreak = 1;
        }
      }
      longestStreak = Math.max(longestStreak, currentStreak);
    }

    // Today completed
    const todayCompleted: { id: string; name: string; type: 'habit' | 'plan' }[] = [];
    for (const h of dateToHabits.get(todayStr) ?? []) {
      todayCompleted.push({ ...h, type: 'habit' });
    }
    for (const p of dateToPlans.get(todayStr) ?? []) {
      todayCompleted.push({ ...p, type: 'plan' });
    }

    // Daily data for the week
    const dailyData: DayData[] = weekDates.map((d, i) => ({
      date: d,
      label: DAY_LABELS[i],
      habits: dateToHabits.get(d) ?? [],
      plans: dateToPlans.get(d) ?? [],
      isToday: d === todayStr,
    }));

    // Vision progress - plans use plan.visionId, habits use habit.visionId
    const activeVisions = (visions ?? []).filter((v: Vision) => !v.deleted && v.status === 'active');
    const planItemsAll = (planItems ?? []).filter((i: PlanItem) => !i.deleted);

    // Pre-build plan→items map for O(1) lookup
    const planToItems = new Map<string, PlanItem[]>();
    for (const pi of planItemsAll) {
      const existing = planToItems.get(pi.planId);
      if (existing) existing.push(pi);
      else planToItems.set(pi.planId, [pi]);
    }

    const visionProgress = activeVisions.map(vision => {
      let totalCompleted = 0;
      let totalExpected = 0;

      // Plans linked via direct FK (plan.visionId)
      const linkedPlans = activePlans.filter((p: Plan) => p.visionId === vision.id && !p.deleted);
      for (const plan of linkedPlans) {
        const items = planToItems.get(plan.id) ?? [];
        const done = items.filter((i: PlanItem) => i.status === 'completed').length;
        totalCompleted += done;
        totalExpected += items.length || 1;
      }

      // Habits linked via direct FK (habit.visionId)
      const linkedHabits = activeHabits.filter((h: Habit) => !h.deleted && h.visionId === vision.id);
      for (const habit of linkedHabits) {
        const dates: string[] = habit.checkedDates ?? [];
        const completed = dates.length;
        totalCompleted += completed;
        totalExpected += Math.max(completed, 30);
      }

      if (totalExpected === 0) return { vision, pct: 0 };
      const pct = Math.round((totalCompleted / totalExpected) * 100);
      return { vision, pct: Math.min(pct, 100) };
    });

    // Dedication stats (for the current period)
    const totalDays = 7; // default weekly
    let practiceDays = 0;
    for (let i = 0; i < totalDays; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const ds = dateStr(d);
      const h = dateToHabits.get(ds);
      const pl = dateToPlans.get(ds);
      if ((h && h.length > 0) || (pl && pl.length > 0)) practiceDays++;
    }

    const habitStats: HabitStat[] = activeHabits.map((h: Habit) => {
      const history = (h as Habit & { checkinHistory?: Record<string, boolean> }).checkinHistory ?? {};
      const weekStartStr = weekDates[0];
      const completed = Object.entries(history).filter(([d, done]) => done && d >= weekStartStr && d <= todayStr).length;
      return {
        habitId: h.id,
        name: h.name,
        completed,
        total: 7,
      };
    });

    const planProgressResult: PlanProgress[] = activePlans.map((p: Plan) => {
      const items = (p as Plan & { items?: { done?: boolean }[] }).items ?? [];
      const done = items.filter((it: { done?: boolean }) => it.done).length;
      return {
        planId: p.id,
        name: p.name,
        progressDelta: items.length > 0 ? Math.round((done / items.length) * 100) : 0,
      };
    });

    const visionProgressData: VisionProgress[] = visionProgress.map(vp => ({
      visionId: vp.vision.id,
      before: 0,
      after: vp.pct,
    }));

    return {
      thisWeekPracticeDays,
      thisMonthPracticeDays,
      longestStreak,
      todayCompleted,
      dailyData,
      visionProgress,
      dedicationStats: {
        practiceDays,
        totalDays,
        habitStats,
        planProgress: planProgressResult,
        visionProgressData,
      },
    };
  }, [habits, plans, planItems, visions]);
}

// ─── SessionComplete 禅修结束卡片 ────────────────────────────────
// 显示时长/日期 + 笔记 + 八触记录 + 禅定阶段 + 回向 + 完成/放弃
import {EIGHT_TACTILE_KEYS, EIGHT_TACTILE_LABEL_KEYS, EMPTY_EIGHT_TACTILE,
  SAM_STAGE_LABEL_KEYS, FONT_SUB, FONT_CARD_TITLE, FONT_STAT_CARD, FONT_BODY, FONT_SMALL, FONT_LABEL, scaleFontSize} from '@egoless-do/core';
import type { EightTactile, EightTactileKey, SamStage } from '@egoless-do/core';
import React, { useState } from 'react';
import { View, Text, Pressable, TextInput, ScrollView, StyleSheet } from 'react-native';

import { useT } from '../../components/UI';

interface ClosingData {
  closingNotes?: string;
  eightTactile?: EightTactile;
  selfReportedStage?: SamStage;
  selfReportedStageText?: string;
  dedicationId?: string;
}

interface Props {
  durationSec: number;
  startTime: number;
  sankalpa?: string;
  onSave: (data: ClosingData) => void;
  onAbandon: () => void;
}

export default function SessionComplete({ durationSec, startTime, sankalpa, onSave, onAbandon }: Props) {
  const T = useT();
  const [note, setNote] = useState('');
  const [eightTactile, setEightTactile] = useState<EightTactile>({ ...EMPTY_EIGHT_TACTILE });
  const [selfReportedStage, setSelfReportedStage] = useState<SamStage>('not_specified');
  const [selfReportedStageText, setSelfReportedStageText] = useState('');

  const minutes = Math.floor(durationSec / 60);
  const seconds = durationSec % 60;
  const dateStr = new Date(startTime).toLocaleDateString(undefined, {
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit',
  });

  const toggleTactile = (key: EightTactileKey) => {
    setEightTactile(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = () => {
    onSave({
      closingNotes: note || undefined,
      eightTactile,
      selfReportedStage,
      selfReportedStageText: selfReportedStage === 'other' ? (selfReportedStageText || undefined) : undefined,
    });
  };

  const SAM_STAGES: SamStage[] = [
    'not_specified', 'scattered', 'desire_realm', 'preparation',
    'first_jhana', 'second_jhana', 'third_jhana', 'fourth_jhana', 'other',
  ];

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      <View style={styles.header}>
        <Text style={styles.title}>{T('zhiguanSessionComplete')}</Text>
      </View>

      <View style={styles.durationCard}>
        <Text style={styles.durationValue}>{minutes}</Text>
        <Text style={styles.durationUnit}>{T('zhiguanMinutes')}</Text>
        {seconds > 0 && (
          <Text style={styles.durationSeconds}>+{seconds}s</Text>
        )}
      </View>

      <Text style={styles.dateText}>{dateStr}</Text>

      {/* Eight Tactile */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>{T('zhiguanEightTactileTitle')}</Text>
        <Text style={styles.sectionHint}>{T('zhiguanEightTactileHint')}</Text>
        <View style={styles.chipGroup}>
          {EIGHT_TACTILE_KEYS.map((key, idx) => (
            <Pressable
              key={key}
              style={[styles.chip, eightTactile[key] && styles.chipActive]}
              onPress={() => toggleTactile(key)}
            >
              <Text style={[styles.chipText, eightTactile[key] && styles.chipTextActive]}>
                {T(EIGHT_TACTILE_LABEL_KEYS[key])}
              </Text>
            </Pressable>
          ))}
        </View>
      </View>

      {/* Self-reported Stage */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>{T('zhiguanSelfReportedTitle')}</Text>
        <Text style={styles.sectionHint}>{T('zhiguanSelfReportedHint')}</Text>
        <View style={styles.chipGroup}>
          {SAM_STAGES.map(stage => (
            <Pressable
              key={stage}
              style={[styles.chip, selfReportedStage === stage && styles.chipActive]}
              onPress={() => setSelfReportedStage(stage)}
            >
              <Text style={[styles.chipText, selfReportedStage === stage && styles.chipTextActive]}>
                {T(SAM_STAGE_LABEL_KEYS[stage])}
              </Text>
            </Pressable>
          ))}
        </View>
        {selfReportedStage === 'other' && (
          <TextInput
            style={[styles.textInput, { marginTop: 8, minHeight: 40 }]}
            value={selfReportedStageText}
            onChangeText={setSelfReportedStageText}
            placeholder={T('zhiguanSelfReportedOtherPlaceholder')}
            placeholderTextColor="#8B7355"
            maxLength={200}
          />
        )}
      </View>
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>{T('zhiguanClosingNotes')}</Text>
        <TextInput
          style={styles.textInput}
          value={note}
          onChangeText={setNote}
          placeholder={T('zhiguanClosingNotesPlaceholder')}
          placeholderTextColor="#8B7355"
          multiline
          maxLength={800}
        />
      </View>

      {sankalpa ? (
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>{T('zhiguanDedication')}</Text>
          <View style={styles.dedicationCard}>
            <Text style={styles.dedicationText}>{sankalpa}</Text>
          </View>
        </View>
      ) : null}

      <View style={styles.actions}>
        <Pressable style={styles.saveButton} onPress={handleSave}>
          <Text style={styles.saveButtonText}>{T('zhiguanFinish')}</Text>
        </Pressable>
        <Pressable style={styles.abandonButton} onPress={onAbandon}>
          <Text style={styles.abandonButtonText}>{T('zhiguanAbandon')}</Text>
        </Pressable>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#FAF7F2' },
  content: { padding: 20 },
  header: { alignItems: 'center', marginBottom: 24 },
  title: { fontSize: FONT_STAT_CARD(), fontWeight: '700', color: '#4A3F35' },
  durationCard: { alignItems: 'center', backgroundColor: '#F5EFE6', borderRadius: 16, padding: 24, marginBottom: 16 },
  durationValue: { fontSize: scaleFontSize(64), fontWeight: '300', color: '#C9A96E' },
  durationUnit: { fontSize: FONT_LABEL(), color: '#8B7355', marginTop: 4 },
  durationSeconds: { fontSize: FONT_SUB(), color: '#8B7355', marginTop: 2 },
  dateText: { fontSize: FONT_SUB(), color: '#8B7355', textAlign: 'center', marginBottom: 24 },
  section: { marginBottom: 20 },
  sectionTitle: { fontSize: FONT_BODY(), fontWeight: '600', color: '#4A3F35', marginBottom: 6 },
  sectionHint: { fontSize: FONT_SMALL(), color: '#8B7355', marginBottom: 10 },
  chipGroup: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },
  chip: { paddingVertical: 8, paddingHorizontal: 14, borderRadius: 20, backgroundColor: '#F5EFE6', borderWidth: 1, borderColor: '#E5DDD0' },
  chipActive: { backgroundColor: '#C9A96E', borderColor: '#C9A96E' },
  chipText: { fontSize: FONT_SUB(), color: '#4A3F35' },
