export default function AppNavigator() {
  const TH = useTheme();
  const theme = useShallowStore(s => s.theme);
  const isSignedIn = useShallowStore(s => s.auth.isSignedIn);
  const navRef = useRef<NavigationContainerRef<RootStackParamList>>(null);
  const prevScreenRef = useRef<string | undefined>(undefined);
  const { kickOutVisible, hasPendingData, handleSyncAndLogout, handleLogoutDirectly } = useSync();
  const [syncOverlayVisible, setSyncOverlayVisible] = useState(false);
  const [syncPhase, setSyncPhase] = useState(1);

  // Check initial sync state on mount — only show overlay on first device login
  useEffect(() => {
    if (!isSignedIn) return;
    void isDeviceSyncedBefore().then(synced => {
      if (synced) return; // Device already synced before — no overlay needed
      void import('../db/schema').then(({ openDatabase, getState }) => {
        void openDatabase().then(async (db) => {
          const done = await getState(db, 'initialSyncDone');
          if (done !== 'true') {
            setSyncOverlayVisible(true);
            const phase = await getState(db, 'initialSyncPhase');
            setSyncPhase(parseInt(phase || '1', 10));
          }
        });
      }).catch(e => log.error(e, { phase: 'navigation-init' }));
    });
  }, [isSignedIn]);

  // Auth expiry check on startup
  useEffect(() => {
    if (!isSignedIn) return;
    const expiresAt = useAppStore.getState().auth.expiresAt;
    const refreshAuth = useAppStore.getState().refreshAuth;
    // Only refresh if token is actually expired (not just on startup)
    if (expiresAt && expiresAt < Date.now()) {
      refreshAuth().catch(e => log.error(e, { phase: 'navigation-init' }));
    }
  }, [isSignedIn]);

  // Navigate to Login when signed out, or to MainTabs when auth restored from SecureStore
  const prevIsSignedIn = useRef(isSignedIn);
  useEffect(() => {
    if (!prevIsSignedIn.current && isSignedIn && navRef.current) {
      // Auth restored from SecureStore — navigate to main app
      navRef.current.reset({ index: 0, routes: [{ name: 'MainTabs' }] });
    } else if (prevIsSignedIn.current && !isSignedIn && navRef.current) {
      // Signed out — navigate to login
      navRef.current.reset({ index: 0, routes: [{ name: 'Login' }] });
    }
    prevIsSignedIn.current = isSignedIn;
  }, [isSignedIn]);

  // Handle habit alarm notification tap
  useEffect(() => {
    let sub: { remove?: () => void } | undefined;
    let mounted = true;
    void import('expo-notifications').then(Notifications => {
      if (!mounted) return;
      sub = Notifications.addNotificationResponseReceivedListener(response => {
        const habitId = response.notification.request.content.data?.habitId as string;
        if (habitId && navRef.current) {
          navRef.current.navigate('HabitDetail', { habitId });
        }
      });
    });
    return () => { mounted = false; sub?.remove?.(); };
  }, []);

  return (
    <ErrorBoundary theme={theme}>
    <View style={{ flex: 1, backgroundColor: TH.bg }}>
    {TH.starfield && <StarfieldBackground />}
    <NavigationContainer
      ref={navRef}
      onStateChange={() => {
        // PostHog 页面浏览追踪
        const route = navRef.current?.getCurrentRoute();
        if (!route) return;
        const currentScreen = route.name;
        if (currentScreen !== prevScreenRef.current) {
          const prev = prevScreenRef.current;
          prevScreenRef.current = currentScreen;
          // 动态导入避免循环依赖
          import('../analytics/track').then(({ screen }) => {
            screen(currentScreen, { previous_screen: prev });
          }).catch(() => {});
        }
      }}
      theme={{
        dark: theme !== 'light',
        colors: {
          primary:    TH.primary,
          background: TH.bg,
          card:       TH.cardSolid,
          text:       TH.text,
          border:     TH.border,
          notification: TH.primary,
        },
        fonts: {
          regular: { fontFamily: 'System', fontWeight: '400' },
          medium:  { fontFamily: 'System', fontWeight: '500' },
          bold:    { fontFamily: 'System', fontWeight: '700' },
          heavy:   { fontFamily: 'System', fontWeight: '800' },
        },
      }}
    >
      <Stack.Navigator id="root-stack" screenOptions={{ headerShown: false }} initialRouteName={isSignedIn ? 'MainTabs' : 'Login'}>
        <Stack.Screen name="Login" component={withErrorBoundary(withLazy(LoginScreen))} />
        <Stack.Screen name="Register" component={withErrorBoundary(withLazy(RegisterScreen))} />
        <Stack.Screen name="ForgotPassword" component={withLazy(ForgotPasswordScreen)} />
        <Stack.Screen name="MainTabs"     component={MainTabs} />
        <Stack.Screen name="GlobalMap"    component={GlobalPulseScreen} />
        <Stack.Screen name="Sport"        component={withErrorBoundary(SportPage)} />
        <Stack.Screen name="FastHistory"  component={FastHistoryWrapper} />
        <Stack.Screen name="FastCalendar" component={withLazy(React.lazy(async () => ({ default: (await import('../features/fasting/FastHistoryPage')).FastCalendarScreen })))} />
        <Stack.Screen name="MedHistory"   component={MedHistoryWrapper} />
        <Stack.Screen name="MedCalendar"  component={withLazy(React.lazy(async () => ({ default: (await import('../features/meditation/MedHistoryPage')).MedCalendarScreen })))} />
        <Stack.Screen name="SleepHistory" component={withErrorBoundary(SleepHistoryPage)} />
        <Stack.Screen name="PreceptHistory" component={withErrorBoundary(PreceptHistoryPage)} />
        <Stack.Screen name="BreathHistory" component={withErrorBoundary(BreathHistoryPage)} />
        <Stack.Screen name="GiveHistory" component={withErrorBoundary(GiveHistoryPage)} />
        <Stack.Screen name="FoodLog"      component={withErrorBoundary(FoodLogPage)} />
        <Stack.Screen name="Grace"        component={withErrorBoundary(GracePage)} />
        <Stack.Screen name="StreakBreak" component={StreakBreakScreen} />
        <Stack.Screen name="CheckinHistory" component={withErrorBoundary(CheckinHistoryScreen)} />
        <Stack.Screen name="CheckinDetail" component={withErrorBoundary(CheckinDetailScreen)} />
<Stack.Screen name="DayCheckin" component={withErrorBoundary(DayCheckinScreen)} />
        <Stack.Screen name="ReviewHistory" component={withErrorBoundary(ReviewHistoryScreen)} />
        <Stack.Screen name="ReviewDetail" component={ReviewDetailScreen} />
        <Stack.Screen name="ExerciseHistory" component={withErrorBoundary(ExerciseHistoryScreen)} />
        <Stack.Screen name="PlanCreate"     component={withErrorBoundary(PlanCreateScreen)} />
        <Stack.Screen name="PlanDetail"     component={withErrorBoundary(PlanDetailScreen)} />
        <Stack.Screen name="PlanHistory"    component={withErrorBoundary(PlanHistoryScreen)} />
        <Stack.Screen name="RecycleBin"    component={RecycleBinScreen} />
        <Stack.Screen name="PrivacyPolicy" component={PrivacyPolicyScreen} />
        <Stack.Screen name="AISettings"    component={withErrorBoundary(AISettingsScreen)} />
        <Stack.Screen name="Profile"       component={withErrorBoundary(ProfileScreen)} />
        <Stack.Screen name="Music"         component={withErrorBoundary(MusicScreen)} />
        <Stack.Screen name="MusicCategory" component={MusicCategoryScreen} />
        <Stack.Screen name="Stats"         component={withErrorBoundary(StatsScreen)} />
        <Stack.Screen name="ReflectionStats" component={ReflectionStatsScreen} />
        <Stack.Screen name="MindTrail"     component={MindTrailScreen} />
        <Stack.Screen name="QuickCreateTrail" component={QuickCreateTrailScreen} options={{ headerShown: false }} />
        <Stack.Screen name="ThoughtTrailDetail" component={ThoughtTrailDetailScreen} />
        <Stack.Screen name="ReflectionDetail" component={withErrorBoundary(ReflectionDetailScreen)} />
        <Stack.Screen name="Insight"       component={InsightScreen} />
        <Stack.Screen name="Review"        component={ReviewScreen} />
        <Stack.Screen name="StrategyLibrary" component={StrategyLibrary} />
        <Stack.Screen name="HabitDetail"   component={withErrorBoundary(HabitDetailScreen)} />
        <Stack.Screen name="RelationMap"   component={RelationMapView} />
        <Stack.Screen name="MantraHistory" component={MantraHistoryScreen} />
        <Stack.Screen name="SutraHistory" component={withErrorBoundary(SutraHistoryScreen)} />
        <Stack.Screen name="Zhiguan" component={ZhiguanScreen} />
        <Stack.Screen name="ZhiguanHistory" component={withErrorBoundary(ZhiguanHistoryScreen)} />
        <Stack.Screen name="BodyPlanEditor" component={withErrorBoundary(BodyPlanEditorScreen)} />
        <Stack.Screen name="PlanManagement" component={withErrorBoundary(PlanManagementScreen)} />
        <Stack.Screen name="BodyCheckinHistory" component={withErrorBoundary(BodyCheckinHistoryScreen)} />
      </Stack.Navigator>
    </NavigationContainer>
    <KickOutModal
      visible={kickOutVisible}
      hasPendingData={hasPendingData}
      onSyncAndLogout={handleSyncAndLogout}
      onLogoutDirectly={handleLogoutDirectly}
    />
    <SyncProgressOverlay visible={syncOverlayVisible && isSignedIn} phase={syncPhase} />
    {isSignedIn && !syncOverlayVisible && <SyncBanner />}
    {isSignedIn && (
      <FabButton
        primaryColor={TH.primary}
        onPress={() => navRef.current?.navigate('MainTabs', { screen: 'Reflections', params: { showNew: true } })}
      />
    )}
    </View>
    </ErrorBoundary>
  );
}

import type { SyncEntity } from '@egoless-do/core';
import { createLogger } from '@egoless-do/core';

import { openDatabase, withDbLock } from '../db/schema';
import { SYNC_QUEUE_UPSERT_SQL } from '../db/sqlHelper';

import { ENTITY_TABLE_MAP } from './entityTableMap';
import { isNotNullConstraintError, decideNotNullRetry } from './flushPolicy';

const log = createLogger('Sync');

interface WriteOp {
  entity: SyncEntity;
  id: string;
  data: Record<string, unknown>;
  operation: 'upsert' | 'delete';
  changedFields?: string[];
}

export class WriteBatcher {
  private _pendingWrites = new Map<string, WriteOp>();
  private _flushTimer: ReturnType<typeof setTimeout> | null = null;
  private _flushDelayMs: number;
  private _onFlushed: (() => void) | null = null;
  private _onPersistError: ((error: Error, entity: string, id: string) => void) | null = null;
  private _retryCount = 0;
  // Counts consecutive NOT NULL failures per key so we surface the error once
  // and then stop retrying (instead of dropping the record silently on the 1st try).
  private _notNullAttempts = new Map<string, number>();

  constructor(flushDelayMs = 250, onFlushed?: () => void, onPersistError?: (error: Error, entity: string, id: string) => void) {
    this._flushDelayMs = flushDelayMs;
    this._onFlushed = onFlushed ?? null;
    this._onPersistError = onPersistError ?? null;
  }

  write(entity: SyncEntity, id: string, data: Record<string, unknown>, changedFields?: string[]) {
    const key = `${entity}:${id}`;
    const existing = this._pendingWrites.get(key);
    if (existing) {
      // If the existing entry is a delete, don't resurrect it — keep the delete
      if (existing.operation === 'delete') return;
      // Create a NEW object (don't mutate in-place) to avoid corrupting in-flight flush snapshots
      this._pendingWrites.set(key, {
        entity, id,
        data: { ...existing.data, ...data },
        operation: 'upsert',
        changedFields: changedFields
          ? [...new Set([...(existing.changedFields ?? []), ...changedFields])]
          : existing.changedFields ?? [],
      });
    } else {
      this._pendingWrites.set(key, { entity, id, data, operation: 'upsert', changedFields });
    }
    this._scheduleFlush();
  }

  markDeleted(entity: SyncEntity, id: string, now = Date.now()) {
    this._pendingWrites.set(`${entity}:${id}`, {
      entity, id,
      data: { updatedAt: now, deleted: true },
      operation: 'delete',
    });
    this._scheduleFlush();
  }

  private _scheduleFlush() {
    if (this._flushTimer) return;
    this._flushTimer = setTimeout(() => {
      this._flushTimer = null;
      void this._flush();
    }, this._flushDelayMs);
  }

  async flushNow(): Promise<boolean> {
    if (this._flushTimer) {
      clearTimeout(this._flushTimer);
      this._flushTimer = null;
    }
    if (this._pendingWrites.size === 0) { log.debug("flushNow: no pending writes"); return false; }
    log.debug(`flushNow: flushing ${this._pendingWrites.size} pending writes`);
    await this._flush();
    return true;
  }

  get pendingCount(): number { return this._pendingWrites.size; }

  private async _flush() {
    const keys = [...this._pendingWrites.entries()].map(([k]) => k);
    // Snapshot value references to detect merges during async flush
    const snapRefs = new Map(keys.map(k => [k, this._pendingWrites.get(k)!]));
    const writes = keys.map(k => snapRefs.get(k)!);
    if (writes.length === 0) return;
    log.debug(`Flushing ${writes.length} writes: ${writes.map(w => w.entity).join(', ')}`);
      for (const w of writes) { log.debug(`  flush entity=${w.entity} id=${w.id} op=${w.operation}`); }

    const db = await openDatabase();
    // Records that fail deterministically (e.g. NOT NULL on a column the payload
    // doesn't carry) can't be fixed by retrying — drop them individually instead
    // of discarding the whole batch.
    const failedKeys = new Set<string>();
    // Keys that failed with NOT NULL — kept in the pending queue for retry
    // (see the NOT NULL branch above) and therefore must NOT be deleted.
    const notNullKeys = new Set<string>();
    try {
      await withDbLock(async () => {
        for (const w of writes) {
          const key = `${w.entity}:${w.id}`;
          const config = ENTITY_TABLE_MAP[w.entity];
          if (!config) { log.warn(`[Flush] No config for entity=${w.entity} id=${w.id}`); continue; }

          // Each record's data-write and its sync_queue enqueue must be atomic:
          // a crash between them would otherwise leave local data persisted but
          // never queued for sync. Wrap both in a single SQLite transaction.
          await db.runAsync('BEGIN TRANSACTION');
          try {
            if (w.operation === 'delete') {
              const nowVal = typeof w.data.updatedAt === 'number' ? w.data.updatedAt : Date.now();
              await db.runAsync(
                `UPDATE ${config.table} SET deleted = 1, synced = 0, updated_at = ? WHERE ${config.pk} = ?`,
                [nowVal, w.id],
              );
            } else {
              const row = config.toRow(w.data);
              const columns = Object.keys(row);
              const values = Object.values(row) as (string | number | null)[];
              const setClause = columns.map(c => `${c}=?`).join(',');
              const placeholders = columns.map(() => '?').join(',');

              log.debug(`[Flush] UPDATE ${config.table} SET ${setClause},synced=0 WHERE ${config.pk}=${w.id}`);
              const result = await db.runAsync(
                `UPDATE ${config.table} SET ${setClause},synced=0 WHERE ${config.pk}=?`,
                [...values, w.id],
              );
              log.debug(`[Flush] UPDATE result: changes=${result.changes}`);
              if (result.changes === 0) {
                log.debug(`[Flush] INSERT ${config.table} (${columns.join(',')},deleted,synced) VALUES (${placeholders},0,0)`);
                try {
                  await db.runAsync(
                    `INSERT INTO ${config.table} (${columns.join(',')},deleted,synced) VALUES (${placeholders},0,0)`,
                    values,
                  );
                } catch (insertErr: unknown) {
                  const msg = insertErr instanceof Error ? insertErr.message : String(insertErr);
                  if (msg.includes('UNIQUE constraint')) {
                    await db.runAsync(
                      `UPDATE ${config.table} SET ${setClause},synced=0 WHERE ${config.pk}=?`,
                      [...values, w.id],
                    );
                  } else throw insertErr;
                }
              }
            }

            // Each record's data write + sync_queue enqueue in one transaction
            const payload = w.changedFields
              ? { ...w.data, _changedFields: w.changedFields }
              : w.data;

            await db.runAsync(
              SYNC_QUEUE_UPSERT_SQL,
              [w.entity, w.id, w.operation, JSON.stringify(payload), Date.now(), 'pending'],
            );

            await db.runAsync('COMMIT');
          } catch (txErr) {
            await db.runAsync('ROLLBACK');
            const msg = txErr instanceof Error ? txErr.message : String(txErr);
            // Deterministic schema constraint failure (e.g. a NOT NULL column the
            // payload doesn't carry) will fail on every retry and can't be fixed
            // here. Report the single record and drop it, rather than aborting the
            // whole batch — previously this rethrew, retried 10x, and discarded all
            // pending writes (M-3). Transient errors (disk I/O, mid-write crash)
            // still propagate to the per-item fallback so the M-1 no-data-without-
            // queue guarantee holds.
            if (isNotNullConstraintError(msg)) {
              // A NOT NULL failure means an entity's toRow() omits a required column.
              // Previously this record was dropped from the batch on the 1st failure,
              // so the data existed only in memory and was lost when the app was killed
              // (and was never queued for sync). Now we KEEP it in the pending queue so
              // it is retried and surfaced, rather than silently discarded.
              const prev = this._notNullAttempts.get(key) ?? 0;
              const decision = decideNotNullRetry(prev);
              this._notNullAttempts.set(key, decision.nextAttempts);
              if (decision.action === 'report') {
                // Surface only on the first failure to avoid log spam; the dev must fix
                // the missing column in the entity's toRow().
                log.error(txErr, { entity: w.entity, id: w.id, phase: 'flush-notnull' });
                if (this._onPersistError) {
                  this._onPersistError(
                    txErr instanceof Error ? txErr : new Error(msg),
                    w.entity,
                    w.id,
                  );
                }
              } else if (decision.action === 'giveup') {
                // Give up after NOT_NULL_MAX_ATTEMPTS to avoid an endless retry loop, but log it.
                log.error(txErr, { entity: w.entity, id: w.id, phase: 'flush-notnull-giveup' });
                failedKeys.add(key);
                this._notNullAttempts.delete(key);
                continue;
              }
              notNullKeys.add(key); // keep pending for retry; not dropped
              continue;
            }
            throw txErr; // transient → outer per-item fallback path
          }
        }
        // Force WAL pages back into the main DB file so a process kill (common on
        // MIUI) cannot drop un-checkpointed commits.
        try { await db.execAsync('PRAGMA wal_checkpoint(TRUNCATE)'); } catch { /* best-effort */ }
      });
      // Only remove entries that weren't merged with new data during flush,
      // plus records that failed deterministically (reported and dropped above).
      // NOT NULL keys are intentionally retained so they are retried next flush.
      for (const k of keys) {
        if (this._pendingWrites.get(k) === snapRefs.get(k) || failedKeys.has(k)) {
          if (!notNullKeys.has(k)) this._pendingWrites.delete(k);
        }
      }
      this._retryCount = 0;
      this._onFlushed?.();
    } catch (err) {
      log.error(err, { msg: 'flush failed' });
      let allFallbacksOk = true;
      await withDbLock(async () => {
        for (const w of writes) {
          const config = ENTITY_TABLE_MAP[w.entity];
          if (!config) { log.warn(`[Flush] No config for entity=${w.entity} id=${w.id}`); continue; }
          try {
            // Fallback: write to both data table AND sync_queue individually
            if (w.operation === 'delete') {
              await db.runAsync(
                `UPDATE ${config.table} SET deleted = 1, synced = 0, updated_at = ? WHERE ${config.pk} = ?`,
                [Date.now(), w.id],
              );
            } else {
              const row = config.toRow(w.data);
              const cols = Object.keys(row);
              const vals = Object.values(row) as (string | number | null)[];
              const setClause = cols.map(c => `${c}=?`).join(',');
              const placeholders = cols.map(() => '?').join(',');
              const r = await db.runAsync(
                `UPDATE ${config.table} SET ${setClause},synced=0 WHERE ${config.pk}=?`,
                [...vals, w.id],
              );
              if (r.changes === 0) {
                await db.runAsync(
                  `INSERT INTO ${config.table} (${cols.join(',')},synced) VALUES (${placeholders},0)`,
                  vals,
                );
              }
            }
            const fallbackPayload = w.changedFields
              ? { ...w.data, _changedFields: w.changedFields }
              : w.data;
            await db.runAsync(
              SYNC_QUEUE_UPSERT_SQL,
              [w.entity, w.id, w.operation, JSON.stringify(fallbackPayload), Date.now(), 'pending'],
            );
          } catch (reErr) {
            log.error(reErr, { msg: 'fallback write failed' });
            allFallbacksOk = false;
            if (this._onPersistError) {
              const err = reErr instanceof Error ? reErr : new Error(String(reErr));
              this._onPersistError(err, w.entity, w.id);
            }
          }
        }
        try { await db.execAsync('PRAGMA wal_checkpoint(TRUNCATE)'); } catch { /* best-effort */ }
      });
      if (allFallbacksOk) {
        // All fallback writes succeeded — remove entries not merged with new data
        for (const k of keys) {
          if (this._pendingWrites.get(k) === snapRefs.get(k)) this._pendingWrites.delete(k);
        }
        this._retryCount = 0;
      } else {
        // Remove only successfully written entries; keep failed ones for retry
        // We can't distinguish which succeeded, so keep all for retry
        // but new arrivals are still preserved since we use specific keys
        // Schedule a retry with backoff so stuck entries are eventually flushed
        if (!this._flushTimer) {
          this._retryCount++;
          if (this._retryCount >= 10) {
            log.error('WriteBatcher: max retries reached, discarding pending writes', { count: this._pendingWrites.size });
            // Notify about each discarded write so UI can show error state
            for (const [, entry] of this._pendingWrites) {
              this._onPersistError?.(new Error('Write discarded after max retries'), entry.entity, entry.id);
            }
            this._pendingWrites.clear();
            this._retryCount = 0;
            return;
          }
          this._flushTimer = setTimeout(() => {
            this._flushTimer = null;
            if (this._pendingWrites.size > 0) void this._flush();
          }, 5000);
        }
      }
      // Trigger sync callback only when all fallback writes succeeded
      if (allFallbacksOk) {
        this._onFlushed?.();
      }
    }
  }
}

// ─── File-based JSON Storage ──────────────────────────────────────
// 纯文件存储，不依赖 expo-sqlite，作为最后防线
// 使用 legacy 导入以保持 EncodingType / writeAsStringAsync / getInfoAsync 兼容
import { createLogger } from '@egoless-do/core';
import * as FileSystem from 'expo-file-system/legacy';

const log = createLogger('FileStorage');

const STORAGE_DIR = FileSystem.documentDirectory + 'egoless_storage/';
const TOKEN_FILE = STORAGE_DIR + 'auth.json';
const DATA_FILE = STORAGE_DIR + 'data.json';

/** Shape of the persisted auth token file. */
interface AuthTokenFile {
  token?: string;
  refreshToken?: string;
  expiresAt?: number;
}

/** 确保存储目录存在 */
async function ensureDir(): Promise<void> {
  try {
    const info = await FileSystem.getInfoAsync(STORAGE_DIR);
    if (!info.exists) {
      await FileSystem.makeDirectoryAsync(STORAGE_DIR, { intermediates: true });
    }
  } catch (e) {
    log.warn('ensureDir failed:', e instanceof Error ? e.message : String(e));
  }
}

/** 保存 token 到文件 */
export async function saveTokenToFile(token: string, refreshToken: string, expiresAt?: number): Promise<void> {
  try {
    await ensureDir();
    const data = JSON.stringify({ token, refreshToken, expiresAt: expiresAt ?? null });
    await FileSystem.writeAsStringAsync(TOKEN_FILE, data, { encoding: FileSystem.EncodingType.UTF8 });
  } catch (e) {
    log.error('saveTokenToFile failed:', e instanceof Error ? e.message : String(e));
  }
}

/** 从文件加载 token */
export async function loadTokenFromFile(): Promise<{ token: string; refreshToken: string; expiresAt?: number } | null> {
  try {
    await ensureDir();
    const info = await FileSystem.getInfoAsync(TOKEN_FILE);
    if (!info.exists) return null;
    const raw = await FileSystem.readAsStringAsync(TOKEN_FILE, { encoding: FileSystem.EncodingType.UTF8 });
    const data = JSON.parse(raw) as AuthTokenFile;
    if (data.token && data.refreshToken) {
      return { token: data.token, refreshToken: data.refreshToken, expiresAt: data.expiresAt ?? undefined };
    }
  } catch (e) {
    log.warn('loadTokenFromFile failed:', e instanceof Error ? e.message : String(e));
  }
  return null;
}

/** 清除文件中的 token */
export async function clearTokenFile(): Promise<void> {
  try {
    await ensureDir();
    const info = await FileSystem.getInfoAsync(TOKEN_FILE);
    if (info.exists) {
      await FileSystem.deleteAsync(TOKEN_FILE, { idempotent: true });
    }
  } catch {
    // 忽略
  }
}

/** 保存数据到文件（按 entity 分文件） */
export async function saveDataToFile(entity: string, id: string, data: Record<string, unknown>): Promise<void> {
  try {
    await ensureDir();
    const file = STORAGE_DIR + entity + '.json';
    let all: Record<string, unknown> = {};
    try {
      const info = await FileSystem.getInfoAsync(file);
      if (info.exists) {
        const raw = await FileSystem.readAsStringAsync(file, { encoding: FileSystem.EncodingType.UTF8 });
        all = JSON.parse(raw) as Record<string, unknown>;
      }
    } catch {
      // 文件不存在或损坏，从头开始
    }
    all[id] = data;
    await FileSystem.writeAsStringAsync(file, JSON.stringify(all), { encoding: FileSystem.EncodingType.UTF8 });
  } catch (e) {
    log.error('saveDataToFile failed:', e instanceof Error ? e.message : String(e));
  }
}

/** 从文件加载数据 */
export async function loadDataFromFile(entity: string): Promise<Record<string, unknown> | null> {
  try {
    await ensureDir();
    const file = STORAGE_DIR + entity + '.json';
    const info = await FileSystem.getInfoAsync(file);
    if (!info.exists) return null;
    const raw = await FileSystem.readAsStringAsync(file, { encoding: FileSystem.EncodingType.UTF8 });
    return JSON.parse(raw);
  } catch (e) {
    log.warn('loadDataFromFile failed:', e instanceof Error ? e.message : String(e));
  }
  return null;
}

/** 标记删除 */
export async function markDeleteInFile(entity: string, id: string): Promise<void> {
  try {
    await ensureDir();
    const file = STORAGE_DIR + entity + '.json';
    const info = await FileSystem.getInfoAsync(file);
    if (!info.exists) return;
    const raw = await FileSystem.readAsStringAsync(file, { encoding: FileSystem.EncodingType.UTF8 });
    const all: Record<string, unknown> = JSON.parse(raw) as Record<string, unknown>;
    if (all[id]) {
      (all[id] as Record<string, unknown>).deleted = true;
      await FileSystem.writeAsStringAsync(file, JSON.stringify(all), { encoding: FileSystem.EncodingType.UTF8 });
    }
  } catch (e) {
    log.warn('markDeleteInFile failed:', e instanceof Error ? e.message : String(e));
  }
}

// ─── App Initialization — replaces onRehydrateStorage logic ──
// Called from App.tsx after the Zustand store is created.
// Loads all persisted data from SQLite, restores auth tokens,
// and sets up daily reset management.

import { DailyResetManager , createLogger, setSentryBridge, apiGetMe, configureFontScale, setPocketbaseToken, setPocketbaseUrl } from '@egoless-do/core';
import { AppState, PixelRatio } from 'react-native';

import { PB_URL } from '../config';
import { openDatabase, setState as setAppState, checkpointDatabase } from '../db/schema';
import {
  rehydrateFromDb,
  runSync,
  setTokenRecoveryFn,
  setSyncTokenExpiryProvider,
  setRealtimeLogoutHandler,
  setRealtimeUserIdProvider,
} from '../features/sync/SyncService';
import { captureException, captureMessage, addBreadcrumb, setSentryUser, clearSentryUser } from '../sentry';

import { migrateAsyncStorageToSQLite, migrateSettingsToSQLite } from './migrateAsyncStorage';
import { loadSecureTokensWithRetry, saveSecureTokens, clearSecureTokens } from './secureAuth';
import { mobileStorageAdapter as adapter, flushWrites } from './storageAdapter';
import { registerCleanup } from './subscriptionRegistry';
import { useAppStore, setAutoSyncCallback, type PartialMobileStore, type MobileStore } from './useAppStore';

const log = createLogger('App');

/** Tracks visibility listener subscription for cleanup on teardown. */
let _visibilitySubscription: { remove: () => void } | null = null;

/** Non-profile keys persisted in app_state table (profile settings use profile entity instead). */
const SETTINGS_KEYS = [
  'sleepGoal',      // SleepGoal object — persisted via SleepSlice.persistSettings, not in profile
  'auth',           // { isSignedIn, user, isGuest } — no tokens
  'recycleBin',     // RecycleBinItem[]
  'bodyFlowState',  // BodyFlow session state — persisted via BodySlice.setBodyFlowState
] as const;

/**
 * Load serialized settings from SQLite app_state via adapter.getSettings()
 * and return them as a partial store patch.
 */
async function loadSettingsPatch(): Promise<PartialMobileStore> {
  const patch: Record<string, unknown> = {};
  for (const key of SETTINGS_KEYS) {
    try {
      const val = await adapter.getSettings(key);
      if (val !== null && val !== undefined) {
        patch[key] = val;
      }
    } catch (err) {
      log.error(err, { message: `Failed to load setting: ${key}` });
    }
  }
  return patch as PartialMobileStore;
}

/**
 * Application initialization — runs once at startup after the store is created.
 *
 * Responsibilities:
 * 1. Run one-time AsyncStorage → SQLite migrations
 * 2. Load all settings + entity data from SQLite into the store
 * 3. Restore auth tokens from SecureStore
 * 4. Wire up runtime subscriptions (token sync, auto sync)
 * 5. Start DailyResetManager (backed by SQLite)
 * 6. Recalculate derived state (streak, medMinutes)
 * 7. Clean up expired recycle bin items
 */
export async function initApp(): Promise<void> {
  // Wire up Sentry bridge for all logger.error/warn calls
  setSentryBridge({ captureException, captureMessage, addBreadcrumb });

  // ── Step 0: Configure font scaling from system settings ─────
  // Must run before any StyleSheet.create() evaluates FONT_* constants.
  configureFontScale(PixelRatio.getFontScale());

  const store = useAppStore.getState;
  const setState = useAppStore.setState;

  // ── 关键实体列表（首屏必需，≤ 5 个）──
  const CRITICAL_ENTITIES = ['profile', 'habit', 'checkin'];

  try {
    // ── Step 1: Open SQLite DB ─────────────────────────────────
    const db = await openDatabase();
    // Declared in the OUTER try scope so Step 8 (derived-state recalc) can read it
    // even if the DB init steps below threw and were caught by the inner guard.
    const entityPatch: Record<string, unknown> = {};
    // Inner guard: a failure in opening/migrating/loading SQLite must NOT prevent
    // the auth-token restore (Step 4) and the token-save subscription (Step 5)
    // from running. Otherwise the token is never restored into memory and the
    // user is forced to re-login on every cold start (esp. on MIUI, where the
    // process is killed aggressively and SQLite open/migrate is more fragile).
    try {

    // ── Step 2: Run migrations (one-time, idempotent) ──────────
    // 并行化：迁移 + Token 加载同时进行
    const [, tokens] = await Promise.all([
      (async () => {
        try {
          const didMigrate = await migrateAsyncStorageToSQLite(db, adapter);
          if (didMigrate) {
            await setAppState(db, 'needs_initial_sync', '1');
          }
        } catch (err) {
          log.error(err, { message: 'Entity migration failed (non-fatal)' });
        }
        try {
          await migrateSettingsToSQLite(db, adapter);
        } catch (err) {
          log.error(err, { message: 'Settings migration failed (non-fatal)' });
        }
      })(),
      loadSecureTokensWithRetry().catch(() => null),
    ]);

    // ── Step 3: Flush pending writes, then load ────────────────
    try { await flushWrites(); } catch (err) { log.error(err, { message: 'Flush failed (non-fatal)' }); }

    let settingsPatch: PartialMobileStore = {};
    let entityPatch: Record<string, unknown> = {};
    try {
      [settingsPatch, entityPatch] = await Promise.all([
        loadSettingsPatch(),
        rehydrateFromDb(CRITICAL_ENTITIES),  // ← 仅加载关键实体
      ]);
    } catch (err) {
      log.error(err, { message: 'Data loading failed (non-fatal)' });
    }

    // Merge settings + entities into store in one batch
    const fullPatch = { ...settingsPatch, ...entityPatch } as PartialMobileStore;

    // Unpack profile fields into top-level store keys
    // Profile blob is the primary source of truth (updated by flushProfileSettings on every change).
    // These fields are NOT loaded from app_state — profile entity is the sole source.
    const profile = fullPatch.userProfile as Record<string, unknown> | undefined;
    if (profile) {
      const PROFILE_UNPACK_KEYS = [
        'waterMl', 'waterGoal', 'weightUnit', 'calGoal', 'customFoodPresets',
        'theme', 'language', 'remindEnabled', 'remindTime',
        'healthSyncEnabled', 'customTags', 'customMoods', 'allTagsOrder', 'allMoodsOrder',
        'reflectionFilters', 'ignoredRecPatterns',
      ] as const;
      for (const key of PROFILE_UNPACK_KEYS) {
        if (profile[key] !== undefined) {
          (fullPatch as Record<string, unknown>)[key] = profile[key];
        }
      }
    }

    if (Object.keys(fullPatch).length > 0) {
      setState(fullPatch);
    }

    // ── 性能优化：延迟加载非关键实体（首屏后）──
    const __perf_critical = performance.now();
    log.info(`[Perf] Critical path: ${__perf_critical - __perf_t0}ms`);

    // 延迟加载剩余 36 实体（不阻塞首屏）
    const DEFERRABLE_ENTITIES = [
      'reflection', 'food', 'fasting', 'exercise', 'meditation', 'plan', 'planItem',
      'planItemCheckin', 'sleep', 'breath', 'mantra', 'mantraSession', 'mantraDef',
      'zhiguanSession', 'give', 'grace', 'sutra', 'fear', 'courage', 'vision',
      'dedication', 'bodyGoal', 'bodyPlan', 'bodyTrainingPlan', 'weightRecord',
      'bodyCheckin', 'foodPreset', 'customWuxing', 'motivationEntry', 'checkinReview',
      'aiConfig', 'thoughtTrail', 'trailNote', 'reflectionLink', 'dailyCustomTodo',
      'dailyTodoHistory', 'recycleBin',
    ];
    setTimeout(async () => {
      try {
        const deferredPatch = await rehydrateFromDb(DEFERRABLE_ENTITIES);
        if (Object.keys(deferredPatch).length > 0) {
          setState(deferredPatch);
        }
        log.info(`[Perf] Deferred load: ${performance.now() - __perf_t0}ms`);
      } catch (err) {
        log.error(err, { message: 'Deferred entity load failed (non-fatal)' });
      }
    }, 100);  // 延迟 100ms，让首屏渲染优先

    // ── Step 3a: Deduplicate bodyTrainingPlans (cleanup legacy duplicates from pre-fix data) ──
    try {
      const plans = (store().bodyTrainingPlans ?? []) as Array<Record<string, unknown>>;
      const seen = new Set<string>();
      const duplicates: string[] = [];
      for (const p of plans) {
        const sig = `${String(p.name ?? '').trim()}|${p.startDate}|${p.endDate}|${p.status}`;
        if (seen.has(sig)) {
          duplicates.push(p.id as string);
        } else {
          seen.add(sig);
        }
      }
      if (duplicates.length > 0) {
        log.warn(`dedupBodyPlans: removing ${duplicates.length} duplicate plan(s)`);
        const dupSet = new Set(duplicates);
        setState({
          bodyTrainingPlans: plans.filter((p: Record<string, unknown>) => !dupSet.has(p.id)),
        } as PartialMobileStore);
        for (const id of duplicates) {
          adapter.markDeleted('bodyTrainingPlan' as Parameters<typeof adapter.markDeleted>[0], id).catch(e => log.error(e));
        }
      }
    } catch (err) {
      log.error(err, { message: 'Plan deduplication failed (non-fatal)' });
    }

    // ── Step 3b: Clean up ghost entries (atomically inside setState to avoid race with realtime) ──
    try {
      const GHOST_CHECKS: Array<[string, string, (item: Record<string, unknown>) => boolean]> = [
        ['foodLog', 'food', f => f.name == null && f.calories == null && f.timestamp == null],
        ['exerciseLog', 'exercise', f => f.sportKey == null && f.date == null],
        ['plans', 'plan', f => f.name == null && f.startDate == null],
        ['medHistory', 'meditation', f => f.date == null && f.durationSec == null],
        ['sleepHistory', 'sleep', f => f.date == null && f.startTs == null],
        ['breathHistory', 'breath', f => f.date == null && f.durationSec == null],
        ['sessions', 'zhiguanSession', f => f.startTs == null && f.status == null],
        ['mantraSessions', 'mantraSession', f => f.mantraId == null && f.date == null],
        ['mantraDefs', 'mantraDef', f => f.name == null && f.subtitle == null],
        ['visions', 'vision', f => f.text == null && f.type == null],
        ['dedications', 'dedication', f => f.date == null && f.periodLabel == null],
        ['fearEntries', 'fearEntry', f => f.content == null && f.date == null],
        ['courageEntries', 'courageEntry', f => f.action == null && f.date == null],
        ['giveHistory', 'give', f => f.content == null && f.date == null],
        ['motivationLog', 'motivationEntry', f => f.foodId == null && f.motivation == null],
        ['readingSessions', 'sutraReading', f => f.mantraId == null && f.date == null],
      ];
      const toDelete: Array<{ entity: string; id: string }> = [];
      // Step 1: Pure computation — find ghosts from current store state (outside setState)
      const s = store();
      const ghostPatch: Record<string, unknown[]> = {};
      for (const [storeKey, entity, isGhost] of GHOST_CHECKS) {
        const items = (s[storeKey as keyof typeof s] ?? []) as Array<Record<string, unknown>>;
        const ghosts = items.filter(i => !i.deleted && isGhost(i));
        if (ghosts.length > 0) {
          log.warn(`cleanupGhosts: ${storeKey} - removing ${ghosts.length} ghost entries`);
          ghostPatch[storeKey] = items.map(i => ghosts.some(g => g.id === i.id) ? { ...i, deleted: true, updatedAt: Date.now() } : i);
          for (const g of ghosts) toDelete.push({ entity, id: g.id as string });
        }
      }
      // Step 2: Apply state atomically
      if (Object.keys(ghostPatch).length > 0) {
        setState(ghostPatch as PartialMobileStore);
      }
      for (const { entity, id } of toDelete) {
        adapter.markDeleted(entity as Parameters<typeof adapter.markDeleted>[0], id).catch(e => log.error(e));
      }
    } catch (err) {
      log.error(err, { message: 'Ghost cleanup failed (non-fatal)' });
    }
    } catch (dbErr) {
      log.error(dbErr, { message: 'Core data init (DB open/migrate/load) failed (non-fatal) — auth/session restore will still run' });
    }

    // ── Step 4: Restore auth tokens from SecureStore ──────────
    try {
      const secureTokens = await loadSecureTokensWithRetry();
      if (secureTokens) {
        const currentAuth = store().auth;
        // Always restore tokens from SecureStore if available (regardless of isSignedIn state)
        // This handles cases where the in-memory/sqlite auth state was lost (crash, migration)
        if (secureTokens.token) {
          // Try to verify the token is still valid by calling getMe
          // If it fails, keep the token anyway — refreshAuth() will handle it later
          const authPatch: Record<string, unknown> = {
            token: secureTokens.token,
            refreshToken: secureTokens.refreshToken,
          };
          if (secureTokens.expiresAt) {
            authPatch.expiresAt = secureTokens.expiresAt;
          }

          // Verify token validity in background — don't block app startup
          apiGetMe(secureTokens.token).then(({ user }) => {
            // Token is valid — update user info
            const latestAuth = store().auth;
            if (latestAuth.token === secureTokens.token) {
              setState({ auth: { ...latestAuth, user } } as PartialMobileStore);
            }
          }).catch(() => {
            // Token expired or invalid — proactively refresh instead of waiting for next sync
            log.info('SecureStore token expired, proactively refreshing');
            store().refreshAuth().catch(e => log.error(e, { message: 'Startup token refresh failed' }));
          });

          if (!currentAuth.isSignedIn) {
            // Restore full auth state from SecureStore
            setState({
              auth: {
                ...currentAuth,
                ...authPatch,
                isSignedIn: true,
                isLoading: false,
              },
            } as PartialMobileStore);
          } else if (!currentAuth.token) {
            // Token was lost but user was still marked signed in
            setState({
              auth: { ...currentAuth, ...authPatch },
            } as PartialMobileStore);
          }

          // Bridge the restored PB token into the PocketBase SDK authStore (defensive;
          // see docs/auth-token-bridge.md §6-4). No-op if SDK singleton is unused.
          setPocketbaseUrl(PB_URL);
          setPocketbaseToken(secureTokens.token ?? null);
        }
      }
    } catch (err) {
      log.error(err, { message: 'SecureStore load failed — user may appear logged out despite valid tokens' });
    }

    // Guard: if user appears signed in but has no token (SecureStore empty/corrupt),
    // clear signed-in state to prevent stuck "no token" state on next sync.
    {
      const auth = store().auth;
      if (auth.isSignedIn && !auth.token) {
        log.warn('isSignedIn=true but no token — clearing auth state');
        setState({ auth: { ...auth, isSignedIn: false, isLoading: false } } as PartialMobileStore);
      }
    }

    // ── Step 5: Wire auth token changes → SecureStore + Sentry user ─
    // Store unsubscribe handle for testability (subscription is permanent in production).
    const _unsubscribeAuth = useAppStore.subscribe((state: MobileStore, prevState: MobileStore) => {
      const newToken = state.auth.token;
      const newRefresh = state.auth.refreshToken;
      const oldToken = prevState.auth.token;
      const oldRefresh = prevState.auth.refreshToken;
      if (newToken !== oldToken || newRefresh !== oldRefresh) {
        // Persist whenever the token changes. A partial write (token present but
        // refreshToken missing) must still be saved so a later restore can recover
        // the session instead of forcing a re-login. refreshAuth() will mint a new
        // refresh token when needed.
        if (newToken) {
          saveSecureTokens(newToken, newRefresh ?? '', state.auth.expiresAt).catch(e => log.error(e, { phase: 'saveSecureTokens' }));
        }
      } else if (!newToken && oldToken) {
        clearSecureTokens().catch(e => log.error(e, { phase: 'clearSecureTokens' }));
      }
      // Keep the PocketBase SDK authStore in sync with the current token (defensive bridge).
      if (newToken !== oldToken) {
        setPocketbaseToken(newToken ?? null);
      }
      // Sync Sentry user context on auth state changes
      if (state.auth.isSignedIn && state.auth.user && (!prevState.auth.isSignedIn || state.auth.user.id !== prevState.auth.user?.id)) {
        void setSentryUser({ id: state.auth.user.id, email: state.auth.user.email, name: state.auth.user.name });
        // PostHog 用户识别（匿名化）
        void import('../analytics/privacy').then(({ anonymizeUserId }) => {
          void anonymizeUserId(state.auth.user!.id).then(anonId => {
            void import('../analytics/track').then(({ identify }) => {
              identify(anonId, {
                guest: state.auth.user!.isGuest || false,
                language: state.language,
                theme: state.theme,
              });
            }).catch(() => {});
          });
        }).catch(() => {});
      } else if (!state.auth.isSignedIn && prevState.auth.isSignedIn) {
        void clearSentryUser();
      }
    });
    // Suppress unused variable warning — _unsubscribeAuth is stored for testability
    void _unsubscribeAuth;
    registerCleanup(() => _unsubscribeAuth());

    // ── Step 5b: Durable flush + checkpoint on app background ──
    // MIUI kills backgrounded apps extremely aggressively. When we transition to
    // the background we (1) re-persist the token to all 3 layers — giving the OS
    // time to finish the async SecureStore/SQLite/file writes started at login;
    // (2) flush any pending WriteBatcher writes so recent local data is committed;
    // (3) checkpoint the WAL so a subsequent kill can't drop the un-flushed WAL
    // tail (which would otherwise lose both local data and the session on cold
    // start). All best-effort and fire-and-forget.
    const _bgSub = AppState.addEventListener('change', (state) => {
      if (state === 'background' || state === 'inactive') {
        const a = store().auth;
        if (a.token) {
          saveSecureTokens(a.token, a.refreshToken ?? '', a.expiresAt).catch(e => log.error(e, { phase: 'bg-saveSecureTokens' }));
        }
        flushWrites().catch(e => log.error(e, { phase: 'bg-flushWrites' }));
        checkpointDatabase().catch(e => log.error(e, { phase: 'bg-checkpoint' }));
        // 性能优化：background 批量文件备份（替代 per-op 同步写）
        // backupAllEntitiesToFile 尚未在 fileStorage.ts 中实现，动态导入后按可选
        // 函数访问；保留 catch 兜底，避免静默失败。
        import('./fileStorage').then((mod) => {
          const backupAllEntitiesToFile = (mod as { backupAllEntitiesToFile?: () => Promise<void> }).backupAllEntitiesToFile;
          if (backupAllEntitiesToFile) {
            backupAllEntitiesToFile().catch((e: unknown) => log.error(e, { phase: 'bg-backupAll' }));
          }
        }).catch(() => {});
      }
    });
    void _bgSub;

    // ── Step 6: Set up auto-sync callback ─────────────────────
    // Connect the store's triggerAutoSync → SyncEngine so data mutations trigger sync
    setAutoSyncCallback(() => {
      store().autoSyncPlanItems?.();
      store().autoSyncHabits?.();
      runSync().catch((e) => log.error(e));
    });

    // ── Step 6b: Wire token recovery for SyncEngine ──────────
    // Avoids circular import: SyncEngine → useAppStore
    setTokenRecoveryFn(async () => {
      const auth = store().auth;
      if (auth.refreshToken) {
        await store().refreshAuth();
        return store().auth.token ?? null;
      }
      return null;
    });

    // Wire token expiry provider so runSync can proactively refresh an
    // expiring token before push/pull (covers all sync triggers, not just
    // the useSync foreground path).
    setSyncTokenExpiryProvider(() => store().auth.expiresAt);

    // ── Step 6c: Wire realtime controller callbacks ──────────
    // Avoids circular import: SyncRealtimeController → useAppStore
    // Note: do NOT call store().logout() here — that would force the user out
    // immediately on any network hiccup. The SyncEngine's kicked-out handler
    // (wired in useSync.ts) shows a modal and lets the user decide.
    setRealtimeLogoutHandler(() => {
      log.warn('Realtime kicked-out signal received — ignoring to preserve auth');
    });
    setRealtimeUserIdProvider(() => store().auth.user?.id ?? undefined);

    // ── Step 7: Create DailyResetManager with SQLite storage ──
    const dailyReset = new DailyResetManager({
      getLastReset: async () => {
        const val = await adapter.getSettings('lastDailyReset');
        return typeof val === 'string' ? val : null;
      },
      setLastReset: (date: string) => { adapter.persistSettings('lastDailyReset', date).catch(e => log.error(e)); },
      getCheckinHistory: () => store().checkinHistory ?? [],
      applyPatch: (patch) => setState(patch as PartialMobileStore),
      getProfile: () => (store().userProfile ?? {}) as Record<string, unknown>,
      getWaterGoal: () => store().waterGoal ?? 2000,
      persistProfile: (data) => {
        const s = store();
        adapter.persistChange('profile', 'self', {
          ...data,
          calGoal: s.calGoal, customFoodPresets: s.customFoodPresets,
          theme: s.theme, language: s.language,
          remindEnabled: s.remindEnabled, remindTime: s.remindTime,
          healthSyncEnabled: s.healthSyncEnabled,
          customTags: s.customTags, customMoods: s.customMoods,
          allTagsOrder: s.allTagsOrder, allMoodsOrder: s.allMoodsOrder,
        } as Record<string, unknown>).catch((e) => log.error(e));
      },
      onPlanDailyReset: (previousDate) => {
        store().performDailyReset?.(previousDate);
      },
      onHabitDailyReset: () => {
        store().checkHabitAutoStatus?.();
      },
      addVisibilityListener: (callback) => {
        // Store subscription for cleanup on teardown
        _visibilitySubscription = AppState.addEventListener('change', (s) => {
          if (s === 'active') callback();
        });
        registerCleanup(() => { _visibilitySubscription?.remove(); _visibilitySubscription = null; });
      },
    });

    // ── Step 8: Recalculate derived state ──────────────────────
    // 性能优化：派生状态懒加载（各 Screen mount 时计算）
    // 不再在 initApp 中同步计算 calculateStreak / calculateTotalMedMin

    // ── Step 9: Clean up expired recycle bin items ─────────────
    try { store().cleanupRecycleBin(); } catch (err) { log.error(err, { message: 'Recycle bin cleanup failed (non-fatal)' }); }

    // ── Step 10: Start daily reset checks ──────────────────────
    // Pass Promise.resolve() so the first check runs immediately (no waiting for sync).
    // This is intentional: the daily reset should fire on app start regardless of sync
    // status, because the user's local timezone may have crossed midnight while offline.
    try { dailyReset.start(Promise.resolve()); } catch (err) { log.error(err, { message: 'Daily reset start failed (non-fatal)' }); }

    log.info('App initialized successfully');
  } catch (err) {
    log.error(err, { message: 'App initialization failed — database open error' });
  }
}

