  }));
}

function seedEntityData() {
  memoryAsyncStorage.set('egoless-do-mobile', JSON.stringify({
    habits: [{ id: 'h1', name: 'Morning meditation', deleted: false }],
    reflections: [{ id: 'r1', content: 'Test reflection', deleted: false }],
