// ─── AI Service ────────────────────────────────────────────────
import type {
  AIConfig, AIResult, ModelConfig, AIMode,
  TagSuggestion, MoodDetection, TrailInsight,
  ReviewGuide, GenerateOptions
} from './types';
import type { CheckinReview } from '../types';
import { buildReviewPrompt, parseReviewAIResponse } from '../business/review';
import { LocalAIEngine } from './local-engine';
import { createProvider, testConnection } from './cloud-providers';
import type { CloudProvider } from './cloud-providers';
import { createLogger } from '../logger';

const log = createLogger('AI');

export class AIService {
  private localEngine: LocalAIEngine;
  private providers: Map<string, CloudProvider> = new Map();
  private config: AIConfig;

  constructor(config?: Partial<AIConfig>) {
    this.localEngine = new LocalAIEngine();
    this.config = {
      mode: 'hybrid',
      models: [],
      localEngineEnabled: true,
      ...config,
    };
    this.initProviders();
  }

  private initProviders() {
    for (const model of this.config.models) {
      if (model.enabled) {
        try {
          this.providers.set(model.id, createProvider(model));
        } catch (e) {
          log.warn('Failed to create provider for', model.id, e);
        }
      }
    }
  }

  // 获取配置
  getConfig(): AIConfig {
    return { ...this.config };
  }

  // 获取模式
  getMode(): AIMode {
    return this.config.mode;
  }

  // 设置模式
  setMode(mode: AIMode) {
    this.config.mode = mode;
  }

  // 更新配置
  updateConfig(config: Partial<AIConfig>) {
    if (config.mode !== undefined) {
      this.config.mode = config.mode;
    }
    if (config.models !== undefined) {
      this.config.models = config.models;
      this.providers.clear();
      this.initProviders();
    }
    if (config.localEngineEnabled !== undefined) {
      this.config.localEngineEnabled = config.localEngineEnabled;
    }
    log.debug('Config updated, providers:', this.providers.size);
  }

  // 获取所有模型配置
  getModels(): ModelConfig[] {
    return [...this.config.models];
  }

  // 获取已启用的模型
  getEnabledModels(): ModelConfig[] {
    return this.config.models.filter(m => m.enabled);
  }

  // 获取默认模型
  getDefaultModel(): ModelConfig | null {
    return this.config.models.find(m => m.isDefault && m.enabled) || 
           this.config.models.find(m => m.enabled) || 
           null;
  }

  // 添加模型
  addModel(model: ModelConfig) {
    this.config.models.push(model);
    if (model.enabled) {
      try {
        this.providers.set(model.id, createProvider(model));
      } catch (e) {
        log.warn('Failed to create provider:', e);
      }
    }
  }

  // 更新模型
  updateModel(modelId: string, updates: Partial<ModelConfig>) {
    const index = this.config.models.findIndex(m => m.id === modelId);
    if (index >= 0) {
      this.config.models[index] = { ...this.config.models[index], ...updates };

      // 更新提供商
      if (updates.enabled !== undefined || updates.apiKey || updates.baseUrl) {
        if (this.config.models[index].enabled) {
          try {
            this.providers.set(modelId, createProvider(this.config.models[index]));
          } catch (e) {
            log.warn('Failed to update provider:', e);
          }
        } else {
          this.providers.delete(modelId);
        }
      }
    }
  }

  // 删除模型
  removeModel(modelId: string) {
    this.config.models = this.config.models.filter(m => m.id !== modelId);
    this.providers.delete(modelId);
  }

  // 设置默认模型
  setDefaultModel(modelId: string) {
    this.config.models.forEach(m => {
      m.isDefault = m.id === modelId;
    });
  }

  // 测试模型连接
  async testModel(modelId: string): Promise<{ success: boolean; error?: string; latency?: number }> {
    const model = this.config.models.find(m => m.id === modelId);
    if (!model) return { success: false, error: '模型不存在' };
    return testConnection(model);
  }

  // 获取云端提供商
  private getCloudProvider(preferredModelId?: string): CloudProvider | null {
    // 优先使用指定的模型
    if (preferredModelId) {
      const provider = this.providers.get(preferredModelId);
      if (provider) return provider;
    }

    // 使用默认模型
    const defaultModel = this.getDefaultModel();
    if (defaultModel) {
      const provider = this.providers.get(defaultModel.id);
      if (provider) return provider;
    }

    // 使用第一个可用的
    for (const provider of this.providers.values()) {
      return provider;
    }

    return null;
  }

  // 云端生成（公开 API，供 trail-recommender、insight-profile 等模块调用）
  async generateCloud(prompt: string, options?: GenerateOptions & { preferredModelId?: string; signal?: AbortSignal }): Promise<AIResult<string>> {
    log.debug('Getting cloud provider...');
    log.debug('preferredModelId:', options?.preferredModelId);
    log.debug('Available providers:', Array.from(this.providers.keys()));

    const provider = this.getCloudProvider(options?.preferredModelId);

    if (!provider) {
      log.debug('No provider available!');
      log.debug('Config models:', this.config.models.map(m => ({ id: m.id, enabled: m.enabled, isDefault: m.isDefault })));
      return {
        success: false,
        error: '没有可用的云端模型，请先配置',
        source: 'cloud',
      };
    }

    log.debug('Using provider, generating...');

    try {
      const result = await provider.generate(prompt, { ...options, signal: options?.signal });
      log.debug('Generation successful, result length:', result?.length ?? 0);
      return {
        success: true,
        data: result,
        source: 'cloud',
      };
    } catch (error) {
      log.error(error, { section: 'AI Cloud', step: 'generation' });
      return {
        success: false,
        error: error instanceof Error ? error.message : '请求失败',
        source: 'cloud',
      };
    }
  }

  // ========== 功能方法 ==========

  // 情绪识别（本地）
  detectMood(content: string): MoodDetection {
    return this.localEngine.detectMood(content);
  }

  // 标签建议（本地）
  suggestTags(content: string, history: string[]): TagSuggestion[] {
    return this.localEngine.suggestTags(content, history);
  }

  // 内容扩展（本地）
  suggestContentExpansion(content: string): string[] {
    return this.localEngine.suggestContentExpansion(content);
  }

  // 脉络洞察（增强版，支持脉络感念）
  async generateTrailInsight(
    reflections: Array<{ content: string; mood: string }>,
    options?: { useCloud?: boolean; preferredModelId?: string; signal?: AbortSignal; trailNotes?: Array<{ content: string; source: string; guidedQuestion?: string }> }
  ): Promise<TrailInsight> {
    const localInsight = this.localEngine.generateTrailInsight(reflections);

    if (!options?.useCloud || this.config.mode === 'local') {
      return localInsight;
    }

    const noteSection = options.trailNotes && options.trailNotes.length > 0
      ? `\n\n脉络内的反思笔记：\n${options.trailNotes.map((n, i) =>
          `[反思${i + 1}${n.source === 'guided' ? '(引导式)' : '(自由)'}] ${n.guidedQuestion ? `引导问题：${n.guidedQuestion}\n` : ''}${n.content}`
        ).join('\n')}`
      : '';

    const prompt = `请分析以下思维脉络，提供洞察：

感念记录：
${reflections.map((r, i) => `${i + 1}. [${r.mood}] ${r.content}`).join('\n')}${noteSection}

请用中文提供：
1. 核心摘要（一句话）
2. 关键要点（2-3个）
3. 转折点
4. 建议`;

    const result = await this.generateCloud(prompt, {
      preferredModelId: options?.preferredModelId,
      signal: options?.signal,
      systemPrompt: '你是一个帮助用户分析思维脉络的助手。请深入分析感念和反思笔记中的情绪变化、思维模式和成长轨迹。',
    });

    if (result.success && result.data) {
      return this.parseTrailInsight(result.data, localInsight);
    }

    return localInsight;
  }

  // 脉络复盘思路
  async generateTrailReviewGuide(
    items: Array<{ content: string; mood?: string; timestamp: number; kind: 'reflection' | 'note' }>,
    options?: { useCloud?: boolean; preferredModelId?: string; signal?: AbortSignal }
  ): Promise<ReviewGuide> {
    const localGuide: ReviewGuide = {
      perspectives: [
        '从成长角度看，这段时间你经历了哪些变化？',
        '从挑战角度看，哪些困难推动了你的思考？',
        '从关系角度看，他人的影响如何塑造了你的认知？',
      ],
      observations: [`这条脉络包含 ${items.length} 条记录`],
      suggestions: [],
    };

    if (!options?.useCloud || this.config.mode === 'local') {
      return localGuide;
    }

    const prompt = `基于用户思维脉络的记录，从多个维度给出复盘思路和启示：

${items.map(r => {
  const date = new Date(r.timestamp).toLocaleDateString();
  const type = r.kind === 'note' ? '[反思]' : '[感念]';
  return `${date} ${type} ${r.mood ? `[${r.mood}]` : ''} ${r.content}`;
}).join('\n')}

请用中文提供：
1. 3-4个不同维度的复盘思路（如成长角度、挑战角度、关系角度、价值观角度等），每个思路用一句话点明该维度的思考方向
2. 2-3个观察发现（基于记录中的模式和变化）
3. 1-2个行动建议`;

    const result = await this.generateCloud(prompt, {
      preferredModelId: options?.preferredModelId,
      signal: options?.signal,
      systemPrompt: '你是一个善于多维度思考的复盘顾问，帮助用户从不同视角审视自己的思维脉络，发现深层的成长启示。',
    });

    if (result.success && result.data) {
      return this.parseReviewGuide(result.data, localGuide);
    }

    return localGuide;
  }

  private parseTrailInsight(aiResult: string, fallback: TrailInsight): TrailInsight {
    try {
      const lines = aiResult.split('\n').filter(l => l.trim());
      const summary = lines[0] || fallback.summary;
      const keyPoints = lines.filter(l => l.match(/^\d+\./)).map(l => l.replace(/^\d+\.\s*/, '')).slice(0, 3);

      // 提取转折点：查找"转折"相关段落
      const turningPoints: string[] = [];
      const tpSection = lines.findIndex(l => /转折|关键|节点/.test(l));
      if (tpSection >= 0) {
        for (let i = tpSection + 1; i < lines.length; i++) {
          if (/^\d+\./.test(lines[i])) turningPoints.push(lines[i].replace(/^\d+\.\s*/, ''));
          else if (lines[i].trim() === '' || /[：:]$/.test(lines[i])) break;
        }
      }

      // 提取建议：查找"建议"相关段落
      const suggestions: string[] = [];
      const sgSection = lines.findIndex(l => /建议|推荐|可以/.test(l));
      if (sgSection >= 0) {
        for (let i = sgSection + 1; i < lines.length; i++) {
          if (/^\d+\./.test(lines[i])) suggestions.push(lines[i].replace(/^\d+\.\s*/, ''));
          else if (lines[i].trim() === '' || /[：:]$/.test(lines[i])) break;
        }
      }

      return {
        summary,
        keyPoints: keyPoints.length > 0 ? keyPoints : fallback.keyPoints,
        turningPoints: turningPoints.length > 0 ? turningPoints : fallback.turningPoints,
        suggestions: suggestions.length > 0 ? suggestions : fallback.suggestions,
      };
    } catch {
      return fallback;
    }
  }

  // 复盘引导
  async generateReviewGuide(
    weekReflections: Array<{ content: string; mood: string; timestamp: number }>,
    options?: { useCloud?: boolean; preferredModelId?: string }
  ): Promise<ReviewGuide> {
    const localGuide: ReviewGuide = {
      perspectives: ['这周整体感觉如何？', '有什么特别的时刻吗？', '下周想继续保持什么？'],
      observations: [`这周记录了 ${weekReflections.length} 条感念`],
      suggestions: [],
    };

    if (!options?.useCloud || this.config.mode === 'local') {
      return localGuide;
    }

    const prompt = `基于用户本周的感念记录，生成复盘引导：

${weekReflections.map(r => `[${new Date(r.timestamp).toLocaleDateString()}] ${r.content}`).join('\n')}

请用中文提供：
1. 3个引导性问题
2. 2-3个观察发现
3. 1-2个建议`;

    const result = await this.generateCloud(prompt, {
      preferredModelId: options?.preferredModelId,
      systemPrompt: '你是一个智慧的复盘引导者，用温暖、启发性的语言。',
    });

    if (result.success && result.data) {
      return this.parseReviewGuide(result.data, localGuide);
    }

    return localGuide;
  }

  private parseReviewGuide(aiResult: string, fallback: ReviewGuide): ReviewGuide {
    try {
      const lines = aiResult.split('\n').filter(l => l.trim());
      const perspectives = lines.filter(l => l.match(/^\d+\./)).map(l => l.replace(/^\d+\.\s*/, '')).slice(0, 4);
      const observations = lines.filter(l => l.match(/^[-•]/)).map(l => l.replace(/^[-•]\s*/, '')).slice(0, 3);

      return {
        perspectives: perspectives.length > 0 ? perspectives : fallback.perspectives,
        observations: observations.length > 0 ? observations : fallback.observations,
        suggestions: fallback.suggestions,
      };
    } catch {
      return fallback;
    }
  }

  // 打卡复盘AI生成
  async generateCheckinReview(
    reviewData: Omit<CheckinReview, 'id' | 'updatedAt' | 'deleted' | 'aiSummary' | 'highlights' | 'improvements'>,
    options?: { useCloud?: boolean; preferredModelId?: string }
  ): Promise<{ summary: string; highlights: string[]; improvements: string[] }> {
    const defaultResult = {
      summary: '本周整体表现良好，继续保持。',
      highlights: ['坚持打卡'],
      improvements: ['继续保持'],
    };

    log.debug('Starting generateCheckinReview...');
    log.debug('useCloud:', options?.useCloud);
    log.debug('config.mode:', this.config.mode);
    log.debug('enabledModels:', this.getEnabledModels().length);
    log.debug('defaultModel:', this.getDefaultModel()?.id ?? 'none');

    if (!options?.useCloud || this.config.mode === 'local') {
      log.debug('Skipping cloud AI (useCloud=false or mode=local)');
      return defaultResult;
    }

    const prompt = buildReviewPrompt(reviewData);
    log.debug('Prompt length:', prompt.length);

    const result = await this.generateCloud(prompt, {
      preferredModelId: options?.preferredModelId,
      systemPrompt: '你是一位专业的个人成长分析师，同时具备温暖的鼓励能力。你的分析基于数据，既有专业深度，又能给予建设性的鼓励。请用中文回答。',
    });

    log.debug('Cloud result:', result.success ? 'SUCCESS' : 'FAILED');
    if (!result.success) {
      log.error(new Error(result.error), { section: 'AI Review' });
    }

    if (result.success && result.data) {
      const parsed = parseReviewAIResponse(result.data);
      log.debug('Parsed summary length:', parsed.summary.length);
      return parsed;
    }

    log.debug('Using default result');
    return defaultResult;
  }
}

// 单例
let instance: AIService | null = null;

export function getAIService(config?: Partial<AIConfig>): AIService {
  if (!instance) {
    instance = new AIService(config);
  } else if (config) {
    // 更新现有实例的配置
    instance.updateConfig(config);
  }
  return instance;
}

export function resetAIService() {
  instance = null;
}

// ─── Cloud AI Providers ────────────────────────────────────────
import type { ModelConfig, GenerateOptions } from './types';
import { createLogger } from '../logger';

const log = createLogger('AI');

export interface CloudProvider {
  name: string;
  generate(prompt: string, options?: GenerateOptions & { signal?: AbortSignal }): Promise<string>;
}

// 通用 OpenAI 兼容提供商
export class OpenAICompatibleProvider implements CloudProvider {
  constructor(private config: ModelConfig) {}

  get name() { return this.config.name; }

  async generate(prompt: string, options?: GenerateOptions & { signal?: AbortSignal }): Promise<string> {
    const { apiKey, baseUrl, model, maxTokens, temperature } = this.config;

    // 本地模型（如Ollama）不需要API Key
    const isLocal = baseUrl.includes('localhost') || baseUrl.includes('127.0.0.1');
    if (!apiKey && !isLocal) {
      throw new Error('请先配置API Key');
    }

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };

    if (apiKey) {
      headers['Authorization'] = `Bearer ${apiKey}`;
    }

    const url = `${baseUrl.replace(/\/$/, '')}/chat/completions`;

    const response = await fetch(url, {
      method: 'POST',
      headers,
      signal: options?.signal,
      body: JSON.stringify({
        model,
        messages: [
          ...(options?.systemPrompt ? [{ role: 'system', content: options.systemPrompt }] : []),
          { role: 'user', content: prompt },
        ],
        max_tokens: options?.maxTokens ?? maxTokens,
        temperature: options?.temperature ?? temperature,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`API错误: ${response.status} - ${error}`);
    }

    let data: unknown;
    try {
      data = await response.json();
    } catch {
      throw new Error(`API返回非JSON响应 (status: ${response.status})`);
    }
    const obj = data as Record<string, unknown> | undefined;
    const choices = obj?.choices as Array<Record<string, unknown>> | undefined;
    const msg = choices?.[0]?.message as Record<string, unknown> | undefined;
    const content = (msg?.content || msg?.reasoning_content) as string | undefined;
    log.debug('[CloudProvider] Response choices:', choices?.length, 'content:', content?.slice(0, 50), 'finish_reason:', choices?.[0]?.finish_reason);
    if (!content) {
      throw new Error(`API返回空内容，响应: ${JSON.stringify(data).slice(0, 200)}`);
    }
    return content;
  }
}

// 提供商工厂（现在统一使用 OpenAI 兼容格式）
export function createProvider(config: ModelConfig): CloudProvider {
  return new OpenAICompatibleProvider(config);
}

// 测试连接
export async function testConnection(config: ModelConfig): Promise<{ success: boolean; error?: string; latency?: number }> {
  const startTime = Date.now();
  try {
    const provider = createProvider(config);
    await provider.generate('你好', { maxTokens: 10 });
    return { 
      success: true, 
      latency: Date.now() - startTime,
    };
  } catch (error) {
    return { 
      success: false, 
      error: error instanceof Error ? error.message : '连接失败',
      latency: Date.now() - startTime,
    };
  }
}

// ─── Context-aware Reminder Service ────────────────────────────
import type { MindReflection, Habit, CheckinEntry } from '../types';
import { dateStr, activeOnly } from '../utils';

export interface ContextReminder {
  id: string;
  type: 'mood_pattern' | 'habit_risk' | 'streak_at_risk' | 'reflection_gap';
  title: string;
  message: string;
  priority: 'low' | 'medium' | 'high';
  action?: string;
  createdAt: number;
}

// 检测情绪模式
export function detectMoodPatterns(reflections: MindReflection[]): ContextReminder[] {
  const reminders: ContextReminder[] = [];
  const recentReflections = reflections
    .filter(r => !r.deleted)
    .sort((a, b) => b.timestamp - a.timestamp)
    .slice(0, 10);

  if (recentReflections.length < 3) return reminders;

  // 检测连续负面情绪
  const recentMoods = recentReflections.slice(0, 5).map(r => r.mood);
  const negativeMoods = ['焦虑', '难过', '生气', '疲惫'];
  const consecutiveNegative = recentMoods.every(m => negativeMoods.includes(m));

  if (consecutiveNegative) {
    reminders.push({
      id: 'mood_negative_pattern',
      type: 'mood_pattern',
      title: '情绪关注',
      message: '最近几天的情绪都比较低落，要不要找朋友聊聊或做一些放松的活动？',
      priority: 'high',
      action: '记录感念',
      createdAt: Date.now(),
    });
  }

  // 检测情绪转变
  const moodChanges = recentReflections.slice(0, 5).filter((r, i) => 
    i > 0 && r.mood !== recentReflections[i - 1].mood
  ).length;

  if (moodChanges >= 3) {
    reminders.push({
      id: 'mood_fluctuation',
      type: 'mood_pattern',
      title: '情绪波动',
      message: '最近情绪变化较多，可以尝试记录一下是什么在影响你',
      priority: 'medium',
      action: '记录感念',
      createdAt: Date.now(),
    });
  }

  return reminders;
}

// 检测习惯风险
export function detectHabitRisks(habits: Habit[]): ContextReminder[] {
  const reminders: ContextReminder[] = [];
  const today = dateStr();

  habits.filter(h => !h.deleted && h.status === 'inProgress').forEach(habit => {
    const checkedDates = [...(habit.checkedDates ?? [])].sort();
    const lastChecked = checkedDates[checkedDates.length - 1];

    // 检测连续未打卡
    if (lastChecked && lastChecked !== today) {
      const parseLocal = (s: string) => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); };
      const lastDate = parseLocal(lastChecked);
      const todayDate = parseLocal(today);
      const daysDiff = Math.floor((todayDate.getTime() - lastDate.getTime()) / (24 * 60 * 60 * 1000));

      if (daysDiff >= 2) {
        reminders.push({
          id: `habit_risk_${habit.id}`,
          type: 'habit_risk',
          title: `${habit.name} 即将中断`,
          message: `已经 ${daysDiff} 天没有打卡了，连续记录可能会中断`,
          priority: daysDiff >= 3 ? 'high' : 'medium',
          action: '去打卡',
          createdAt: Date.now(),
        });
      }
    }

    // 检测即将完成
    const progress = habit.targetDays > 0 ? habit.doneDays / habit.targetDays : 0;
    if (progress >= 0.8 && progress < 1) {
      reminders.push({
        id: `habit_almost_${habit.id}`,
        type: 'habit_risk',
        title: `${habit.name} 即将完成`,
        message: `还差 ${habit.targetDays - habit.doneDays} 天就达成目标了，加油！`,
        priority: 'low',
        action: '查看详情',
        createdAt: Date.now(),
      });
    }
  });

  return reminders;
}

// 检测打卡连续性风险
export function detectStreakRisks(checkinHistory: CheckinEntry[]): ContextReminder[] {
  const reminders: ContextReminder[] = [];
  const today = dateStr();
  const yesterday = dateStr(new Date(Date.now() - 24 * 60 * 60 * 1000));

  const todayCheckin = checkinHistory.find(c => c.date === today && !c.deleted);
  const yesterdayCheckin = checkinHistory.find(c => c.date === yesterday && !c.deleted);

  // 今天还没打卡
  if (!todayCheckin) {
    const hour = new Date().getHours();
    if (hour >= 20) {
      reminders.push({
        id: 'checkin_today',
        type: 'streak_at_risk',
        title: '今天还没打卡',
        message: '记得完成今天的打卡，保持连续记录',
        priority: 'medium',
        action: '去打卡',
        createdAt: Date.now(),
      });
    }
  }

  // 昨天没打卡
  if (!yesterdayCheckin && todayCheckin) {
    reminders.push({
      id: 'checkin_yesterday',
      type: 'streak_at_risk',
      title: '昨天没有打卡',
      message: '昨天的记录缺失，可能会影响连续天数统计',
      priority: 'low',
      createdAt: Date.now(),
    });
  }

  return reminders;
}

// 检测感念间隔
export function detectReflectionGaps(reflections: MindReflection[]): ContextReminder[] {
  const reminders: ContextReminder[] = [];
  const sortedReflections = reflections
    .filter(r => !r.deleted)
    .sort((a, b) => b.timestamp - a.timestamp);

  if (sortedReflections.length === 0) return reminders;

  const lastReflection = sortedReflections[0];
  const daysSinceLastReflection = Math.floor(
    (Date.now() - lastReflection.timestamp) / (24 * 60 * 60 * 1000)
  );

  if (daysSinceLastReflection >= 3) {
    reminders.push({
      id: 'reflection_gap',
      type: 'reflection_gap',
      title: '好久没记录了',
      message: `已经 ${daysSinceLastReflection} 天没有记录感念了，有什么想法吗？`,
      priority: daysSinceLastReflection >= 7 ? 'high' : 'medium',
      action: '记录感念',
      createdAt: Date.now(),
    });
  }

  return reminders;
}

// 获取所有情境提醒
export function getAllContextReminders(
  reflections: MindReflection[],
  habits: Habit[],
  checkinHistory: CheckinEntry[]
): ContextReminder[] {
  const reminders: ContextReminder[] = [
    ...detectMoodPatterns(reflections),
    ...detectHabitRisks(habits),
    ...detectStreakRisks(checkinHistory),
    ...detectReflectionGaps(reflections),
  ];

  // 按优先级排序
  const priorityOrder = { high: 0, medium: 1, low: 2 };
  return reminders.sort((a, b) => priorityOrder[a.priority] - priorityOrder[b.priority]);
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { computeLocalInsights } from './insight-profile';
import type { MindReflection } from '../types/reflection';

beforeEach(() => { vi.useFakeTimers(); vi.setSystemTime(new Date('2026-07-07T12:00:00')); });
afterEach(() => { vi.useRealTimers(); });

function makeReflection(overrides: Partial<MindReflection> = {}): MindReflection {
  return {
    id: 'r1', content: 'test', mood: '开心', tags: [],
    timestamp: Date.now(), deleted: false,
    ...overrides,
  } as MindReflection;
}

// ─── computeLocalInsights ─────────────────────────────────────
describe('computeLocalInsights', () => {
  it('returns zero counts for empty input', () => {
    const result = computeLocalInsights([], 'week');
    expect(result.totalCount).toBe(0);
    expect(result.avgPerDay).toBe(0);
    expect(result.streakDays).toBe(0);
    expect(result.hotTags).toEqual([]);
    expect(result.moodDistribution).toEqual([]);
  });

  it('counts active reflections within time range', () => {
    const now = Date.now();
    const r = [
      makeReflection({ id: 'r1', timestamp: now - 86400000 }),      // 1 day ago
      makeReflection({ id: 'r2', timestamp: now - 2 * 86400000 }),  // 2 days ago
      makeReflection({ id: 'r3', timestamp: now - 40 * 86400000 }), // 40 days ago
    ];
    const week = computeLocalInsights(r, 'week');
    expect(week.totalCount).toBe(2);

    const month = computeLocalInsights(r, 'month'); // 30-day window
    expect(month.totalCount).toBe(2); // 40 days ago is outside 30-day window
  });

  it('excludes deleted reflections', () => {
    const r = [
      makeReflection({ id: 'r1', deleted: false, timestamp: Date.now() }),
      makeReflection({ id: 'r2', deleted: true, timestamp: Date.now() }),
