// ─── Insight Profile: local stats + AI-powered analysis ───
import type { MindReflection } from '../types/reflection';
import { getMoodIcon } from '../business/thought-trail';
import { buildReflectionSummary } from '../business/trail-creation';
import type { AIResult } from './types';
import { getAIService } from './ai-service';
import { extractJSON, repairJSON } from './json-utils';
import { isAIRecommendAvailable } from './trail-recommender';
import { dateStr, activeOnly } from '../utils';
import { createLogger } from '../logger';

const log = createLogger('AI');

// ─── Types ───────────────────────────────────────────────────────────

export interface InsightProfile {
  totalCount: number;
  streakDays: number;
  avgPerDay: number;
  hotTags: HotTag[];
  moodDistribution: MoodEntry[];
  hotTopics: HotTopic[];
  insightSummary: string;
  timeRange: 'week' | 'month';
  startDate: number;
  endDate: number;
}

export interface HotTag {
  tag: string;
  count: number;
  percentage: number;
  trend: 'rising' | 'stable' | 'declining';
  sampleReflectionIds: string[];
}

export interface MoodEntry {
  mood: string;
  icon: string;
  count: number;
  percentage: number;
}

export interface HotTopic {
  word: string;
  count: number;
  category: string;
  sampleReflectionIds: string[];
  aiReason?: string;
}

// ─── Constants ───────────────────────────────────────────────────────

const TIME_RANGE_DAYS: Record<string, number> = { week: 7, month: 30 };

// ─── Local Stats (synchronous) ───────────────────────────────────────

export function computeLocalInsights(
  reflections: MindReflection[],
  timeRange: 'week' | 'month',
): Omit<InsightProfile, 'hotTopics' | 'insightSummary'> {
  const now = Date.now();
  const days = TIME_RANGE_DAYS[timeRange] ?? 7;
  const cutoff = now - days * 86400000;
  const prevCutoff = cutoff - days * 86400000;

  const active = reflections.filter(r => !r.deleted && r.timestamp >= cutoff);
  const prevActive = reflections.filter(r => !r.deleted && r.timestamp >= prevCutoff && r.timestamp < cutoff);

  const sorted = [...active].sort((a, b) => a.timestamp - b.timestamp);
  const startDate = sorted.length > 0 ? sorted[0].timestamp : now;
  const endDate = sorted.length > 0 ? sorted[sorted.length - 1].timestamp : now;

  return {
    totalCount: active.length,
    streakDays: computeStreakDays(reflections, days),
    avgPerDay: active.length > 0 ? Math.round((active.length / days) * 10) / 10 : 0,
    hotTags: computeHotTags(active, prevActive),
    moodDistribution: computeMoodDistribution(active),
    timeRange,
    startDate,
    endDate,
  };
}

// ─── Streak days ─────────────────────────────────────────────────────

function computeStreakDays(reflections: MindReflection[], maxDays: number): number {
  const active = activeOnly(reflections);
  if (active.length === 0) return 0;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const dateSet = new Set<string>();
  for (const r of active) {
    dateSet.add(dateStr(new Date(r.timestamp)));
  }

  let streak = 0;
  for (let i = 0; i < maxDays; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    if (dateSet.has(dateStr(d))) {
      streak++;
    } else {
      break;
    }
  }
  return streak;
}

// ─── Hot tags ────────────────────────────────────────────────────────

function computeHotTags(current: MindReflection[], prev: MindReflection[]): HotTag[] {
  const tagCounts = new Map<string, { count: number; ids: string[] }>();
  for (const r of current) {
    for (const tag of r.tags) {
      const entry = tagCounts.get(tag) ?? { count: 0, ids: [] };
      entry.count++;
      entry.ids.push(r.id);
      tagCounts.set(tag, entry);
    }
  }

  const prevTagCounts = new Map<string, number>();
  for (const r of prev) {
    for (const tag of r.tags) {
      prevTagCounts.set(tag, (prevTagCounts.get(tag) ?? 0) + 1);
    }
  }

  const total = current.length || 1;
  return [...tagCounts.entries()]
    .map(([tag, { count, ids }]) => {
      const prevCount = prevTagCounts.get(tag) ?? 0;
      let trend: HotTag['trend'] = 'stable';
      if (count > prevCount) trend = 'rising';
      else if (count < prevCount) trend = 'declining';
      return {
        tag,
        count,
        percentage: Math.round((count / total) * 100),
        trend,
        sampleReflectionIds: ids,
      };
    })
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);
}

// ─── Mood distribution ───────────────────────────────────────────────

function computeMoodDistribution(current: MindReflection[]): MoodEntry[] {
  const moodCounts = new Map<string, number>();
  for (const r of current) {
    if (r.mood) moodCounts.set(r.mood, (moodCounts.get(r.mood) ?? 0) + 1);
  }

  const total = current.length || 1;
  return [...moodCounts.entries()]
    .map(([mood, count]) => ({
      mood,
      icon: getMoodIcon(mood),
      count,
      percentage: Math.round((count / total) * 100),
    }))
    .sort((a, b) => b.count - a.count);
}

// ─── AI Insight Generation ───────────────────────────────────────────

const INSIGHT_PROFILE_SYSTEM = `分析感念记录，输出JSON:
{"summary":"20字内洞察","topics":[{"word":"2-4字主题词","count":出现次数,"category":"分类","reason":"一句话原因","reflectionIndices":[序号]}]}
topics限3-5个，不要输出其他内容。`;

export async function generateInsightProfile(
  reflections: MindReflection[],
  timeRange: 'week' | 'month',
): Promise<{ insightSummary: string; hotTopics: HotTopic[] } | null> {
  if (!isAIRecommendAvailable()) return null;

  const days = TIME_RANGE_DAYS[timeRange] ?? 7;
  const cutoff = Date.now() - days * 86400000;
  const active = reflections
    .filter(r => !r.deleted && r.timestamp >= cutoff)
    .sort((a, b) => b.timestamp - a.timestamp)
    .slice(0, 20);

  if (active.length < 3) return null;

  const summaries = active.map(r => buildReflectionSummary(r));
  const list = summaries.map((s, i) => `[${i}] ${s}`).join('\n');

  const prompt = `感念记录:\n${list}\n\n提取高频主题词。`;

  try {
    const service = getAIService();
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 20000);
    let result: AIResult<string>;
    try {
      result = await service.generateCloud(prompt, {
        systemPrompt: INSIGHT_PROFILE_SYSTEM,
        maxTokens: 4000,
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }

    if (!result?.success || !result?.data) return null;
    return parseInsightResponse(result.data, active);
  } catch (e) {
    log.error(e, { context: '[InsightProfile]' });
    return null;
  }
}

function parseInsightResponse(
  raw: string,
  reflections: MindReflection[],
): { insightSummary: string; hotTopics: HotTopic[] } | null {
  try {
    const jsonStr = extractJSON(raw);
    let parsed: unknown;
    try {
      parsed = JSON.parse(jsonStr);
    } catch {
      // 尝试修复截断的 JSON：补全缺失的括号
      const repaired = repairJSON(jsonStr);
      parsed = JSON.parse(repaired);
    }

    const obj = parsed as Record<string, unknown> | undefined;
    const summary = typeof obj?.summary === 'string' ? obj.summary : '';

    const topicsRaw = obj?.topics || obj?.hotTopics || obj?.themes || obj?.keywords;
    if (!Array.isArray(topicsRaw)) {
      return { insightSummary: summary, hotTopics: [] };
    }

    const hotTopics: HotTopic[] = topicsRaw
      .filter((t) => {
        const item = t as Record<string, unknown>;
        return item && (item.word || item.keyword || item.theme) && (typeof item.count === 'number' || typeof item.frequency === 'number');
      })
      .map((t) => {
        const item = t as Record<string, unknown>;
        return {
        word: String(item.word || item.keyword || item.theme || ''),
        count: Number(item.count || item.frequency || 0),
        category: String(item.category || item.type || item.tag || ''),
        sampleReflectionIds: (Array.isArray(item.reflectionIndices) ? item.reflectionIndices as number[] : [])
          .filter((i: number) => i >= 0 && i < reflections.length)
          .map((i: number) => reflections[i].id),
        aiReason: item.reason ? String(item.reason) : undefined,
      };
      })
      .filter(t => t.word)
      .slice(0, 5);

    return { insightSummary: summary, hotTopics };
  } catch {
    return null;
  }
}

import { describe, it, expect } from 'vitest';
import { extractJSON, findLastBalancedJSON, repairJSON } from './json-utils';

// ─── extractJSON ────────────────────────────────────────────
describe('extractJSON', () => {
  it('extracts JSON from markdown code block', () => {
    const input = 'Here is the result:\n```json\n{"key": "value"}\n```\nDone.';
    expect(extractJSON(input)).toBe('{"key": "value"}');
  });

  it('extracts JSON from code block without json tag', () => {
    const input = '```\n[1, 2, 3]\n```';
    expect(extractJSON(input)).toBe('[1, 2, 3]');
  });

  it('finds last balanced JSON array in plain text', () => {
    const input = 'Thinking... [not valid {"a":1} and here is the result: [1, 2, 3]';
    const result = extractJSON(input);
    expect(JSON.parse(result)).toEqual([1, 2, 3]);
  });

  it('finds last balanced JSON object in plain text', () => {
    const input = 'Some reasoning text {"incomplete and then {"valid": true}';
    const result = extractJSON(input);
    expect(JSON.parse(result)).toEqual({ valid: true });
  });

  it('returns raw text when no JSON found', () => {
    expect(extractJSON('no json here')).toBe('no json here');
  });

  it('finds the last balanced JSON structure in nested text', () => {
    const json = '{"a": {"b": [1, 2]}, "c": true}';
    const input = `thinking...\n${json}`;
    // extractJSON finds last balanced array first, which is [1, 2]
    // then falls back to object. The function finds the innermost balanced structure.
    const result = extractJSON(input);
    // Result should be valid JSON
    expect(() => JSON.parse(result)).not.toThrow();
  });
});

// ─── findLastBalancedJSON ────────────────────────────────────
describe('findLastBalancedJSON', () => {
  it('finds a balanced object', () => {
    expect(findLastBalancedJSON('{"a": 1}', '{', '}')).toBe('{"a": 1}');
  });

  it('finds a balanced array', () => {
    expect(findLastBalancedJSON('[1, 2, 3]', '[', ']')).toBe('[1, 2, 3]');
  });

  it('returns null for unbalanced input', () => {
    expect(findLastBalancedJSON('{broken', '{', '}')).toBeNull();
  });

  it('finds the LAST balanced structure', () => {
    const input = '{"first": 1} some text {"second": 2}';
    expect(findLastBalancedJSON(input, '{', '}')).toBe('{"second": 2}');
  });

  it('handles strings with braces inside', () => {
    expect(findLastBalancedJSON('{"text": "hello {world}"}', '{', '}')).toBe('{"text": "hello {world}"}');
  });

  it('handles escaped quotes in strings', () => {
    expect(findLastBalancedJSON('{"text": "he said \\"hi\\""}', '{', '}')).toBe('{"text": "he said \\"hi\\""}');
  });

  it('returns null for empty string', () => {
    expect(findLastBalancedJSON('', '{', '}')).toBeNull();
  });
});

// ─── repairJSON ──────────────────────────────────────────────
describe('repairJSON', () => {
  it('returns valid JSON unchanged', () => {
    const valid = '{"a": 1}';
    expect(repairJSON(valid)).toBe(valid);
  });

  it('auto-closes missing closing brace', () => {
    const result = repairJSON('{"a": 1');
    expect(JSON.parse(result)).toEqual({ a: 1 });
  });

  it('auto-closes missing closing bracket', () => {
    const result = repairJSON('[1, 2, 3');
    expect(JSON.parse(result)).toEqual([1, 2, 3]);
  });

  it('truncates to last structural close', () => {
    // repairJSON finds the last complete } at depth 0 and truncates there
    const input = '{"valid": true} and then {"broken": incom';
    const result = repairJSON(input);
    expect(() => JSON.parse(result)).not.toThrow();
    expect(JSON.parse(result)).toEqual({ valid: true });
  });

  it('auto-closes simple missing braces', () => {
    const result = repairJSON('{"a": [1, 2');
    // Should close both [ and {
    expect(() => JSON.parse(result)).not.toThrow();
  });

  it('trims whitespace', () => {
    const result = repairJSON('  {"a": 1}  ');
    expect(result).toBe('{"a": 1}');
  });
});

// ─── Shared AI utilities ──────────────────────────────────────────
import { createLogger } from '../logger';

const log = createLogger('AI:utils');

/**
 * Extract JSON from AI response text. Handles:
 * - Markdown code blocks (```json ... ```)
 * - Balanced braces/brackets (finds the last valid JSON object/array)
 * - Falls back to raw text
 */
export function extractJSON(raw: string): string {
  const codeBlockMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) return codeBlockMatch[1].trim();

  // Find the last complete JSON array (thinking text precedes results)
  const lastArray = findLastBalancedJSON(raw, '[', ']');
  if (lastArray) return lastArray;

  const lastObject = findLastBalancedJSON(raw, '{', '}');
  if (lastObject) return lastObject;

  return raw.trim();
}

/**
 * Find the last balanced JSON structure by scanning right-to-left.
 * Handles thinking/reasoning text that may precede the actual JSON.
 */
export function findLastBalancedJSON(text: string, open: string, close: string): string | null {
  for (let i = text.length - 1; i >= 0; i--) {
    if (text[i] === close) {
      let depth = 0;
      let inString = false;
      let escape = false;
      for (let j = i; j >= 0; j--) {
        const ch = text[j];
        if (escape) { escape = false; continue; }
        if (ch === '\\') { escape = true; continue; }
        if (ch === '"') { inString = !inString; continue; }
        if (inString) continue;
        if (ch === close) depth++;
        if (ch === open) depth--;
        if (depth === 0) {
          const candidate = text.slice(j, i + 1);
          try {
            JSON.parse(candidate);
            return candidate;
          } catch {
            break;
          }
        }
      }
    }
  }
  return null;
}

/**
 * Attempt to repair truncated or malformed JSON from AI responses.
 * Truncates to the last structural closing brace, then auto-closes
 * any remaining open brackets/braces.
 */
export function repairJSON(str: string): string {
  let s = str.trim();
  let lastStructuralClose = -1;
  let depth = 0, inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) lastStructuralClose = i; }
  }
  if (lastStructuralClose >= 0) {
    s = s.slice(0, lastStructuralClose + 1);
  }
  // Auto-close missing brackets/braces
  let openBrackets = 0, closeBrackets = 0, openBraces = 0, closeBraces = 0;
  let inString = false, escaped = false;
  for (const ch of s) {
    if (escaped) { escaped = false; continue; }
    if (ch === '\\') { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '[') openBrackets++;
    else if (ch === ']') closeBrackets++;
    else if (ch === '{') openBraces++;
    else if (ch === '}') closeBraces++;
  }
  for (let i = closeBrackets; i < openBrackets; i++) s += ']';
  for (let i = closeBraces; i < openBraces; i++) s += '}';
  return s;
}

import { describe, it, expect } from 'vitest';
import { applyForceLayout } from './layout-algorithms';
import type { LayoutNode, LayoutEdge } from './layout-algorithms';

describe('applyForceLayout', () => {
  it('modifies node positions', () => {
    const nodes: LayoutNode[] = [
      { id: 'a', x: 0, y: 0, vx: 0, vy: 0, size: 10 },
      { id: 'b', x: 100, y: 0, vx: 0, vy: 0, size: 10 },
    ];
    const edges: LayoutEdge[] = [{ from: 'a', to: 'b' }];

    const beforeA = { x: nodes[0].x, y: nodes[0].y };
    applyForceLayout(nodes, edges, 800, 600);

    // At least one node should have moved
    const moved = nodes[0].x !== beforeA.x || nodes[0].y !== beforeA.y ||
                  nodes[1].x !== 100 || nodes[1].y !== 0;
    expect(moved).toBe(true);
  });

  it('handles empty nodes gracefully', () => {
    expect(() => applyForceLayout([], [], 800, 600)).not.toThrow();
  });

  it('handles single node', () => {
    const nodes: LayoutNode[] = [
      { id: 'a', x: 400, y: 300, vx: 0, vy: 0, size: 10 },
    ];
    applyForceLayout(nodes, [], 800, 600);
    // Single node should be pulled toward center
    expect(nodes[0].x).toBeDefined();
    expect(nodes[0].y).toBeDefined();
  });

  it('accepts custom config without error', () => {
    const nodes: LayoutNode[] = [
      { id: 'a', x: 0, y: 0, vx: 0, vy: 0, size: 10 },
      { id: 'b', x: 50, y: 0, vx: 0, vy: 0, size: 10 },
    ];
    const edges: LayoutEdge[] = [{ from: 'a', to: 'b' }];

    expect(() => {
      applyForceLayout(nodes, edges, 800, 600, {
        repulsionForce: 100,
        attractionForce: 0.01,
        centerGravity: 0.005,
        damping: 0.9,
        maxIterations: 10,
      });
    }).not.toThrow();
  });
});

// ─── Force-directed Layout Algorithm ────────────────────────────

export interface LayoutNode {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
}

export interface LayoutEdge {
  from: string;
  to: string;
}

export interface LayoutConfig {
  repulsionForce: number;
  attractionForce: number;
  centerGravity: number;
  damping: number;
  minDistance: number;
  maxIterations: number;
}

const DEFAULT_CONFIG: LayoutConfig = {
  repulsionForce: 1500,
  attractionForce: 0.005,
  centerGravity: 0.01,
  damping: 0.85,
  minDistance: 50,
  maxIterations: 100,
};

// 计算两点距离
function distance(a: LayoutNode, b: LayoutNode): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy) || 1;
}

// 应用力导向布局
export function applyForceLayout(
  nodes: LayoutNode[],
  edges: LayoutEdge[],
  width: number,
  height: number,
  config: Partial<LayoutConfig> = {}
): void {
  const cfg = { ...DEFAULT_CONFIG, ...config };

  // 初始化位置（如果未设置）
  nodes.forEach(node => {
    if (node.x === 0 && node.y === 0) {
      node.x = width / 2 + (Math.random() - 0.5) * width * 0.5;
      node.y = height / 2 + (Math.random() - 0.5) * height * 0.5;
    }
  });

  // 迭代计算
  for (let iter = 0; iter < cfg.maxIterations; iter++) {
    let totalMovement = 0;

    // 计算斥力（所有节点对之间）
    for (let i = 0; i < nodes.length; i++) {
      let fx = 0, fy = 0;

      for (let j = 0; j < nodes.length; j++) {
        if (i === j) continue;

        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;

        // 斥力与距离平方成反比
        const force = cfg.repulsionForce / (dist * dist);
        fx += (dx / dist) * force;
        fy += (dy / dist) * force;
      }

      nodes[i].vx += fx;
      nodes[i].vy += fy;
    }

    // 计算引力（沿边）
    const nodeMap = new Map(nodes.map(n => [n.id, n]));
    edges.forEach(edge => {
      const from = nodeMap.get(edge.from);
      const to = nodeMap.get(edge.to);
      if (!from || !to) return;

      const dx = to.x - from.x;
      const dy = to.y - from.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;

      // 引力与距离成正比
      const force = (dist - 100) * cfg.attractionForce;
      const fx = (dx / dist) * force;
      const fy = (dy / dist) * force;

      from.vx += fx;
      from.vy += fy;
      to.vx -= fx;
      to.vy -= fy;
    });

    // 中心引力
    nodes.forEach(node => {
      node.vx += (width / 2 - node.x) * cfg.centerGravity;
      node.vy += (height / 2 - node.y) * cfg.centerGravity;
    });

    // 更新位置
    nodes.forEach(node => {
      // 应用阻尼
      node.vx *= cfg.damping;
      node.vy *= cfg.damping;

      // 限制速度
      const speed = Math.sqrt(node.vx * node.vx + node.vy * node.vy);
      if (speed > 50) {
        node.vx = (node.vx / speed) * 50;
        node.vy = (node.vy / speed) * 50;
      }

      // 更新位置
      node.x += node.vx;
      node.y += node.vy;

      // 边界约束
      const padding = node.size;
      node.x = Math.max(padding, Math.min(width - padding, node.x));
      node.y = Math.max(padding, Math.min(height - padding, node.y));

      // 计算总移动量
      totalMovement += Math.abs(node.vx) + Math.abs(node.vy);
    });

    // 如果移动量很小，提前结束
    if (totalMovement < nodes.length * 0.1) {
      break;
    }
  }
}

// 层次布局
export function applyHierarchicalLayout(
  nodes: LayoutNode[],
  edges: LayoutEdge[],
  width: number,
  height: number
): void {
  // 构建邻接表
  const children = new Map<string, string[]>();
  const parents = new Map<string, string[]>();

  edges.forEach(edge => {
    const c = children.get(edge.from) ?? [];
    c.push(edge.to);
    children.set(edge.from, c);

    const p = parents.get(edge.to) ?? [];
    p.push(edge.from);
    parents.set(edge.to, p);
  });

  // 找到根节点（没有父节点的节点）
  const roots = nodes.filter(n => !parents.has(n.id) || parents.get(n.id)!.length === 0);

  // BFS 分层
  const levels = new Map<string, number>();
  const queue: { id: string; level: number }[] = roots.map(r => ({ id: r.id, level: 0 }));

  while (queue.length > 0) {
    const { id, level } = queue.shift()!;
    if (levels.has(id)) continue;
    levels.set(id, level);

    const c = children.get(id) ?? [];
    c.forEach(childId => {
      queue.push({ id: childId, level: level + 1 });
    });
  }

  // 处理未访问的节点
  nodes.forEach(node => {
    if (!levels.has(node.id)) {
      levels.set(node.id, 0);
    }
  });

  // 计算每层的节点数
  const levelCounts = new Map<number, number>();
  levels.forEach(level => {
    levelCounts.set(level, (levelCounts.get(level) ?? 0) + 1);
  });

  // 分配位置
  const levelIndices = new Map<number, number>();
  const maxLevel = Math.max(...levels.values());
  const levelHeight = height / (maxLevel + 1);

  nodes.forEach(node => {
    const level = levels.get(node.id) ?? 0;
    const index = levelIndices.get(level) ?? 0;
    const count = levelCounts.get(level) ?? 1;
    const levelWidth = width / (count + 1);

    node.x = levelWidth * (index + 1);
    node.y = levelHeight * (level + 0.5);

    levelIndices.set(level, index + 1);
  });
}

// 环形布局
export function applyCircularLayout(
  nodes: LayoutNode[],
  width: number,
  height: number
): void {
  const centerX = width / 2;
  const centerY = height / 2;
  const radius = Math.min(width, height) * 0.35;

  nodes.forEach((node, i) => {
    const angle = (2 * Math.PI * i) / nodes.length;
    node.x = centerX + radius * Math.cos(angle);
    node.y = centerY + radius * Math.sin(angle);
  });
}

// 网格布局
export function applyGridLayout(
  nodes: LayoutNode[],
  width: number,
  height: number
): void {
  const cols = Math.ceil(Math.sqrt(nodes.length));
  const rows = Math.ceil(nodes.length / cols);
  const cellWidth = width / cols;
  const cellHeight = height / rows;

  nodes.forEach((node, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    node.x = cellWidth * (col + 0.5);
    node.y = cellHeight * (row + 0.5);
  });
}

// 节点聚合（大量节点时使用）
export function aggregateNodes(
  nodes: LayoutNode[],
  threshold: number
): LayoutNode[] {
  if (nodes.length <= threshold) return nodes;

  const aggregated: LayoutNode[] = [];
  const used = new Set<string>();

  nodes.forEach(node => {
    if (used.has(node.id)) return;

    const cluster: LayoutNode[] = [node];
    used.add(node.id);

    // 找附近的节点
    nodes.forEach(other => {
      if (used.has(other.id)) return;
      const dist = Math.sqrt(
        Math.pow(node.x - other.x, 2) + Math.pow(node.y - other.y, 2)
      );
      if (dist < 50) {
        cluster.push(other);
        used.add(other.id);
      }
    });

    // 创建聚合节点
    if (cluster.length > 1) {
      const avgX = cluster.reduce((sum, n) => sum + n.x, 0) / cluster.length;
      const avgY = cluster.reduce((sum, n) => sum + n.y, 0) / cluster.length;
      aggregated.push({
        id: `cluster_${node.id}`,
        x: avgX,
        y: avgY,
        vx: 0,
        vy: 0,
        size: Math.min(60, 20 + cluster.length * 5),
      });
    } else {
      aggregated.push(node);
    }
  });

  return aggregated;
}

// ─── Local AI Engine (Rule-based) ──────────────────────────────
import type { TagSuggestion, MoodDetection, TrailInsight } from './types';

const MOOD_DICT: Record<string, { mood: string; weight: number }> = {
  '开心': { mood: '开心', weight: 1 },
  '快乐': { mood: '开心', weight: 0.9 },
  '高兴': { mood: '开心', weight: 0.9 },
  '满足': { mood: '开心', weight: 0.8 },
  '兴奋': { mood: '兴奋', weight: 1 },
  '期待': { mood: '兴奋', weight: 0.7 },
  '感恩': { mood: '感恩', weight: 1 },
  '感谢': { mood: '感恩', weight: 0.8 },
  '平静': { mood: '平静', weight: 1 },
  '放松': { mood: '平静', weight: 0.9 },
  '安宁': { mood: '平静', weight: 0.8 },
  '焦虑': { mood: '焦虑', weight: 1 },
  '担心': { mood: '焦虑', weight: 0.8 },
  '紧张': { mood: '焦虑', weight: 0.8 },
  '不安': { mood: '焦虑', weight: 0.7 },
  '难过': { mood: '难过', weight: 1 },
  '伤心': { mood: '难过', weight: 0.9 },
  '失望': { mood: '难过', weight: 0.8 },
  '沮丧': { mood: '难过', weight: 0.7 },
  '生气': { mood: '生气', weight: 1 },
  '愤怒': { mood: '生气', weight: 1 },
  '烦躁': { mood: '生气', weight: 0.8 },
  '疲惫': { mood: '疲惫', weight: 1 },
  '累': { mood: '疲惫', weight: 0.9 },
  '困': { mood: '疲惫', weight: 0.8 },
};

const KEYWORD_PATTERNS: Record<string, string[]> = {
  insight: ['领悟', '明白', '意识到', '发现', '原来', '终于'],
  question: ['为什么', '怎么', '如何', '什么', '是否'],
  decision: ['决定', '准备', '打算', '计划', '要'],
  reflection: ['反思', '回顾', '思考', '琢磨', '想'],
  action: ['做', '执行', '实施', '行动', '开始'],
};

const KEYWORD_TAG_MAP: Record<string, string[]> = {
  '工作': ['#工作', '#职场'],
  '学习': ['#学习', '#成长'],
  '运动': ['#运动', '#健身'],
  '冥想': ['#冥想', '#修行'],
  '读书': ['#阅读', '#学习'],
  '焦虑': ['#焦虑', '#情绪'],
  '开心': ['#开心', '#情绪'],
  '朋友': ['#社交', '#朋友'],
  '家人': ['#家庭', '#亲情'],
};

export class LocalAIEngine {
  detectMood(content: string): MoodDetection {
    const results: Array<{ mood: string; weight: number }> = [];

    for (const [keyword, { mood, weight }] of Object.entries(MOOD_DICT)) {
      if (content.includes(keyword)) {
        results.push({ mood, weight });
      }
    }

    if (results.length === 0) {
      return { mood: '平静', confidence: 0.5, alternatives: [] };
    }

    results.sort((a, b) => b.weight - a.weight);

    return {
      mood: results[0].mood,
      confidence: results[0].weight,
      alternatives: [...new Set(results.map(r => r.mood))].slice(1, 4),
    };
  }

  suggestTags(content: string, history: string[]): TagSuggestion[] {
    const suggestions: TagSuggestion[] = [];
    const contentLower = content.toLowerCase();

    for (const tag of history) {
      const tagClean = tag.replace('#', '').toLowerCase();
      if (tagClean && contentLower.includes(tagClean)) {
        suggestions.push({ tag, confidence: 0.9, reason: '内容包含此标签' });
      }
    }

    for (const [keyword, tags] of Object.entries(KEYWORD_TAG_MAP)) {
      if (contentLower.includes(keyword)) {
        for (const tag of tags) {
          if (!suggestions.find(s => s.tag === tag)) {
            suggestions.push({ tag, confidence: 0.7, reason: `包含关键词"${keyword}"` });
          }
        }
      }
    }

    return suggestions.slice(0, 5);
  }

  suggestContentExpansion(content: string): string[] {
    const suggestions: string[] = [];

    if (content.length < 20) {
      suggestions.push('可以描述一下具体的情况吗？');
      suggestions.push('当时你的感受是什么？');
    }

    for (const [category, keywords] of Object.entries(KEYWORD_PATTERNS)) {
      for (const keyword of keywords) {
        if (content.includes(keyword)) {
          switch (category) {
            case 'insight': suggestions.push('这个领悟是怎么来的？'); break;
            case 'question': suggestions.push('你找到答案了吗？'); break;
            case 'decision': suggestions.push('是什么促使你做这个决定？'); break;
            case 'reflection': suggestions.push('反思后你有什么新的发现？'); break;
            case 'action': suggestions.push('执行后效果如何？'); break;
          }
          break;
        }
      }
    }

    return [...new Set(suggestions)].slice(0, 3);
  }

  generateTrailInsight(reflections: Array<{ content: string; mood: string }>): TrailInsight {
    const moods = reflections.map(r => r.mood);
    const transitionCount = moods.filter((m, i) => i > 0 && m !== moods[i - 1]).length;

    return {
      summary: `这条脉络包含 ${reflections.length} 条感念，心情经历了 ${transitionCount} 次变化`,
      keyPoints: this.extractKeyPoints(reflections.map(r => r.content)),
      turningPoints: this.findTurningPoints(reflections),
      suggestions: this.generateSuggestions(reflections),
    };
  }

  private extractKeyPoints(contents: string[]): string[] {
    const keyPoints: string[] = [];

    for (const content of contents) {
      for (const keywords of Object.values(KEYWORD_PATTERNS)) {
        for (const keyword of keywords) {
          if (content.includes(keyword)) {
            const sentences = content.split(/[。！？.!?]/);
            for (const sentence of sentences) {
              if (sentence.includes(keyword) && sentence.length > 5) {
                keyPoints.push(sentence.trim());
                break;
              }
            }
          }
        }
      }
    }

    return [...new Set(keyPoints)].slice(0, 3);
  }

  private findTurningPoints(reflections: Array<{ content: string; mood: string }>): string[] {
    const turningPoints: string[] = [];

    for (let i = 1; i < reflections.length; i++) {
      if (reflections[i].mood !== reflections[i - 1].mood) {
        turningPoints.push(`从"${reflections[i - 1].mood}"转变为"${reflections[i].mood}"`);
      }
    }

    return turningPoints.slice(0, 3);
  }

  private generateSuggestions(reflections: Array<{ content: string; mood: string }>): string[] {
    const suggestions: string[] = [];
    const lastMood = reflections[reflections.length - 1]?.mood;

    if (lastMood === '焦虑' || lastMood === '难过') {
      suggestions.push('可以尝试与朋友聊聊，或者做一些放松的活动');
    }

    if (lastMood === '开心' || lastMood === '兴奋') {
      suggestions.push('记录下是什么让你开心，以后可以回顾');
    }

    return suggestions;
  }
}

