// ─── Auth API client (shared across all platforms) ─────────────────
import type { AuthUser } from './types';
import type { SyncPushResult, SyncCheckResult, SyncPullPostBody, SyncPullResult, SyncChange, SyncPushResponseItem } from './sync/types';
import { buildHeaders, fetchWithTimeout, handleJsonResponse, SYNC_REQUEST_TIMEOUT } from './fetch';
import { createLogger } from './logger';

const log = createLogger('Auth');

export interface AuthResponse {
  user: AuthUser;
  token: string;
  refreshToken: string;
  expiresAt: number;
}

export interface RefreshResponse {
  token: string;
  refreshToken: string;
  expiresAt: number;
}

/**
 * Returned by apiLogin/apiWechatLogin when the user has MFA enabled.
 * The client must NOT treat this as a completed login — it should prompt
 * for the MFA code and call apiVerifyMFALogin(mfaToken, code) to obtain
 * the real access token.
 */
export interface MFARequiredResponse {
  mfaRequired: true;
  mfaToken: string;
  expiresAt: number;
}

export type LoginResult = AuthResponse | MFARequiredResponse;

/**
 * Thrown by AuthSlice.login() when the server responds with mfaRequired.
 * Carries the mfaToken so the UI can call verifyMfaLogin(mfaToken, code).
 */
export class MFARequiredError extends Error {
  mfaToken: string;
  constructor(mfaToken: string) {
    super('MFA required');
    this.name = 'MFARequiredError';
    this.mfaToken = mfaToken;
  }
}

let apiBase = '';
let syncBase = '';

export function setApiBase(base: string) {
  apiBase = base.replace(/\/+$/, '');
}

export function setSyncApiBase(base: string) {
  syncBase = base.replace(/\/+$/, '');
}

function getSyncBase(): string {
  return syncBase || apiBase;
}

export function getSyncUrl(): string {
  return getSyncBase();
}

const COMMON_PASSWORDS = [
  'password', '12345678', 'qwerty123', 'password1', 'admin123',
  'password123', '123456789', 'iloveyou', 'abc123456', 'monkey123',
  'dragon123', 'letmein123', 'trustno1', 'sunshine1', 'princess1',
  'football1', 'shadow123', 'master123', 'hello1234', 'charlie1',
  'donald123', 'qwerty12', 'login123', 'welcome1', 'passw0rd',
  'michael1', 'ninja123', 'mustang1', 'jessica1', 'hunter12',
  'summer12', 'qwerty1234', 'zaq12wsx', 'asdfghjk', '1qaz2wsx',
  'qwertyui', '1q2w3e4r', '00000000', '11111111', '1234567890',
];

export function validatePassword(pwd: string): string | null {
  if (pwd.length < 10) return '密码长度至少10位';
  if (pwd.length > 128) return '密码长度不能超过128位';
  if (!/[a-zA-Z]/.test(pwd)) return '密码需包含字母';
  if (!/[0-9]/.test(pwd)) return '密码需包含数字';
  if (!/[^a-zA-Z0-9]/.test(pwd)) return '密码需包含特殊符号';
  if (COMMON_PASSWORDS.some(p => pwd.toLowerCase().includes(p))) return '密码不能包含常见词汇';
  return null;
}

// ── Register ──────────────────────────────────────────────────────
export async function apiRegister(email: string, password: string, name: string, code: string): Promise<AuthResponse> {
  const res = await fetchWithTimeout(`${apiBase}/api/auth/register`, {
    method: 'POST',
    headers: buildHeaders(),
    body: JSON.stringify({ email, password, name, code }),
  });
  return handleJsonResponse<AuthResponse>(res);
}

// ── Send verification code ────────────────────────────────────────
export async function apiSendCode(email: string, type?: 'register' | 'reset'): Promise<{ ok: boolean; message: string }> {
  const res = await fetchWithTimeout(`${apiBase}/api/auth/send-code`, {
    method: 'POST',
    headers: buildHeaders(),
    body: JSON.stringify({ email, type }),
  });
