// ─── Checkin business logic (pure functions) ───────────────────
import type { CheckinEntry } from '../types';
import { dateStr, calculateCheckinStreak, computeLongestStreak as computeLongestStreakRaw, activeOnly } from '../utils';

// ─── Incomplete reason constants ───────────────────────────────
export const INCOMPLETE_REASONS = [
  { code: 'time',     icon: '⏰' },
  { code: 'health',   icon: '🏥' },
  { code: 'external', icon: '📋' },
  { code: 'mood',     icon: '😔' },
  { code: 'forgot',   icon: '💭' },
  { code: 'other',    icon: '💬' },
] as const;

export type IncompleteReasonCode = typeof INCOMPLETE_REASONS[number]['code'];

export interface IncompleteItem {
  type: 'practice' | 'habit' | 'planItem';
  name: string;
}

/** Detect incomplete checkin items for today */
export function getIncompleteItems(params: {
  habits: Array<{ name: string; status: string; checkedDates?: string[] }>;
  planItems: Array<{ id: string; name: string }>;
  planItemCheckins: Array<{ planItemId: string; date: string; done: boolean; linkedModule?: string; deleted?: boolean }>;
  today: string;
}): IncompleteItem[] {
  const { habits, planItems, planItemCheckins, today } = params;
  const result: IncompleteItem[] = [];

  // Habits (inProgress only)
  for (const h of habits) {
    if (h.status === 'inProgress' && !h.checkedDates?.includes(today)) {
      result.push({ type: 'habit', name: h.name });
    }
  }

  // Plan items (exclude auto-checked via linkedModule)
  for (const item of planItems) {
    const checkin = planItemCheckins.find(c => !c.deleted && c.planItemId === item.id && c.date === today);
    if (!checkin?.done && !checkin?.linkedModule) {
      result.push({ type: 'planItem', name: item.name });
    }
  }

  return result;
}

/** Get food log entries for a specific date (derived from timestamp) */
export function getFoodLogByDate<T extends { timestamp: number; deleted?: boolean }>(foodLog: T[], date: string): T[] {
  return (foodLog ?? []).filter(f => dateStr(new Date(f.timestamp)) === date && !f.deleted);
}

export function computeLongestStreakFromHistory(history: CheckinEntry[]): number {
  return computeLongestStreakRaw(history.filter(c => c.done && !c.deleted).map(c => c.date));
}

/** Get streak and totalDays for a specific date from history (handles legacy records without totalDays) */
export function getStatsForDate(history: CheckinEntry[], date: string): { streak: number; totalDays: number } {
  const record = history.find(c => c.date === date && !c.deleted);
  if (record?.totalDays != null && record?.streak != null) {
    return { streak: record.streak, totalDays: record.totalDays };
  }
  const doneUpToDate = history.filter(c => c.done && !c.deleted && c.date <= date);
  const totalDays = record?.totalDays ?? doneUpToDate.length;
  const streak = record?.streak ?? calculateCheckinStreak(doneUpToDate, date);
  return { streak, totalDays };
}

export function submitCheckinEntry(
  history: CheckinEntry[],
  done: boolean,
  note: string,
  dateOverride?: string,
  weight?: number,
  grace?: boolean,
): { record: CheckinEntry; history: CheckinEntry[]; streak: number } {
  const today = dateOverride ?? dateStr();
  const withoutToday = history.filter(c => c.date !== today);
  const tempRecord: CheckinEntry = {
    date: today, done, note, streak: 0, weight,
    grace: grace ?? false,
    timestamp: Date.now(), updatedAt: Date.now(), deleted: false,
  };
  const newHistory = [tempRecord, ...withoutToday];
  const newStreak = calculateCheckinStreak(newHistory);
  const totalDays = newHistory.filter(c => c.done && !c.deleted).length;
  const record: CheckinEntry = { ...tempRecord, streak: newStreak, totalDays };
  return { record, history: [record, ...withoutToday], streak: newStreak };
}

/** Parsed checkin note structure */
export interface ParsedCheckinNote {
  userNote: string;
  practices: string[];
  customs: string[];
  planItems: Array<string | { id: string; [key: string]: unknown }>;
  fasted: boolean;
  waterMl: number;
  habits: string[];
  food: number;
  incompleteReason: string;
  incompleteNote: string;
}

/** Parse checkin note from JSON or legacy format */
export function parseCheckinNote(raw: string): ParsedCheckinNote {
  if (!raw) return { userNote: '', practices: [], customs: [], planItems: [], fasted: false, waterMl: 0, habits: [], food: 0, incompleteReason: '', incompleteNote: '' };
  
  try {
    // Raw JSON shape — fields are optional/loose since notes come from untrusted
    // client input and sync. The defaults below normalize to ParsedCheckinNote.
    const data = JSON.parse(raw) as {
      note?: string;
      practices?: unknown;
      customs?: unknown;
      planItems?: unknown;
      fasted?: unknown;
      water?: unknown;
      habits?: unknown;
      food?: unknown;
      incompleteReason?: string;
      incompleteNote?: string;
    };
    if (typeof data === 'object' && data !== null) {
      return {
        userNote: data.note ?? '',
        practices: (data.practices as string[] | undefined) ?? [],
        customs: (data.customs as string[] | undefined) ?? [],
        planItems: (data.planItems as Array<string | { id: string; [key: string]: unknown }> | undefined) ?? [],
        fasted: !!data.fasted,
        waterMl: typeof data.water === 'number' ? data.water : 0,
        habits: (data.habits as string[] | undefined) ?? [],
        food: typeof data.food === 'number' ? data.food : 0,
        incompleteReason: data.incompleteReason ?? '',
        incompleteNote: data.incompleteNote ?? '',
      };
    }
  } catch {
    // Not JSON — fall back to legacy emoji+delimiter format
    // Log warning for potentially corrupted data (partial JSON, truncated by sync, etc.)
    if (raw.startsWith('{')) {
      console.warn('[parseCheckinNote] Failed to parse note that looks like JSON:', raw.slice(0, 80));
    }
  }
  
  // Legacy format: emoji prefixes + ' · ' delimiter
  const parts = raw.split(' · ');
  const practices: string[] = [];
  const customs: string[] = [];
  const noteParts: string[] = [];
  const EMOJI_TO_KEY: Record<string, string> = { '🧘': 'sit', '🧍': 'stand', '📿': 'chant' };
  
  for (const p of parts) {
    const matchedEmoji = Object.keys(EMOJI_TO_KEY).find(e => p.startsWith(e));
    if (matchedEmoji) {
      practices.push(EMOJI_TO_KEY[matchedEmoji]);
    } else if (p.startsWith('✓')) {
      customs.push(p.slice(1));
    } else if (p) {
      noteParts.push(p);
    }
  }
  
  return { userNote: noteParts.join(' · '), practices, customs, planItems: [], fasted: false, waterMl: 0, habits: [], food: 0, incompleteReason: '', incompleteNote: '' };
}

import { describe, it, expect } from 'vitest';
import { fuzzCoordinate, isValidCoordinate, calculateDistance } from './coordinateFuzzing';

// ─── isValidCoordinate ───────────────────────────────────────
describe('isValidCoordinate', () => {
  it('accepts valid coordinates', () => {
    expect(isValidCoordinate(39.9, 116.4)).toBe(true);   // Beijing
    expect(isValidCoordinate(-33.8, 151.2)).toBe(true);   // Sydney
    expect(isValidCoordinate(0, 0)).toBe(true);            // Null Island
  });

  it('rejects out-of-range latitude', () => {
    expect(isValidCoordinate(91, 0)).toBe(false);
    expect(isValidCoordinate(-91, 0)).toBe(false);
  });

  it('rejects out-of-range longitude', () => {
    expect(isValidCoordinate(0, 181)).toBe(false);
    expect(isValidCoordinate(0, -181)).toBe(false);
  });

  it('accepts boundary values', () => {
    expect(isValidCoordinate(90, 180)).toBe(true);
    expect(isValidCoordinate(-90, -180)).toBe(true);
  });
});

// ─── calculateDistance ───────────────────────────────────────
describe('calculateDistance', () => {
  it('returns 0 for same point', () => {
    expect(calculateDistance(39.9, 116.4, 39.9, 116.4)).toBe(0);
  });

  it('calculates approximate distance between Beijing and Shanghai', () => {
    // ~1,068 km
    const dist = calculateDistance(39.9, 116.4, 31.2, 121.5);
    expect(dist).toBeGreaterThan(1000000); // > 1000km
    expect(dist).toBeLessThan(1200000);    // < 1200km
  });

  it('is symmetric', () => {
    const d1 = calculateDistance(0, 0, 10, 10);
    const d2 = calculateDistance(10, 10, 0, 0);
    expect(d1).toBeCloseTo(d2, 0);
  });
});

// ─── fuzzCoordinate ──────────────────────────────────────────
describe('fuzzCoordinate', () => {
  it('returns valid coordinates', () => {
    const [lat, lng] = fuzzCoordinate(39.9, 116.4, 'test-secret');
    expect(isValidCoordinate(lat, lng)).toBe(true);
  });

  it('produces different results for different secrets', () => {
    const [lat1, lng1] = fuzzCoordinate(39.9, 116.4, 'secret-a');
    const [lat2, lng2] = fuzzCoordinate(39.9, 116.4, 'secret-b');
    expect(lat1 !== lat2 || lng1 !== lng2).toBe(true);
  });

  it('produces consistent results for same inputs', () => {
    const r1 = fuzzCoordinate(39.9, 116.4, 'test-secret');
    const r2 = fuzzCoordinate(39.9, 116.4, 'test-secret');
    expect(r1).toEqual(r2);
  });

  it('offsets are within ~500m of original', () => {
    const lat = 39.9, lng = 116.4;
    const [fuzzedLat, fuzzedLng] = fuzzCoordinate(lat, lng, 'test');
    const dist = calculateDistance(lat, lng, fuzzedLat, fuzzedLng);
    expect(dist).toBeLessThan(600); // allow small margin for rounding
  });

  it('clamps coordinates to valid range', () => {
    // Near the poles
    const [lat, lng] = fuzzCoordinate(89.99, 0, 'test');
    expect(lat).toBeLessThanOrEqual(90);
    expect(lat).toBeGreaterThanOrEqual(-90);
  });
});

