  it('should compute avgScore from reflection moods', () => {
    const today = new Date();
    const refs = [
      makeRef({ id: 'r1', mood: '开心', timestamp: today.getTime() }),
      makeRef({ id: 'r2', mood: '平静', timestamp: today.getTime() }),
