/** 获取 EXERCISE_CATEGORY 的中文名（用于去重） */
function getCategoryZhName(cat: typeof EXERCISE_CATEGORIES[number]): string | undefined {
  // 注意：不包含 taiji/yoga，因为它们也是 ALL_SPORTS 中的具体运动，不应被去重跳过
  const map: Record<string, string> = {};
  return map[cat.key];
}

