      slice.emptyRecycleBin();

      expect(store.state().recycleBin).toEqual([]);
    });
  });

  describe('cleanupRecycleBin', () => {
    it('removes items older than 1 week', () => {
      const twoWeeksAgo = Date.now() - MS_PER_WEEK - 1000;
      const store = makeTestStore({
        recycleBin: [
