import { dateStr } from '../utils';
import type { SleepEntry, SleepGoal } from '../types';
import { DEFAULT_SLEEP_GOAL } from '../types';
import type { StorageAdapter, SleepSlice } from './types';
import type { SliceCreator } from './sliceHelper';
import { createLogger } from '../logger';
const log = createLogger('Sleep');

function uuid(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export function createSleepSlice(
  adapter: StorageAdapter,
  onSync?: () => void,
): SliceCreator<SleepSlice> {
  return (set, get) => ({
    sleepHistory: [],
    sleepGoal: { ...DEFAULT_SLEEP_GOAL },

    getTodaySleep() {
      const today = dateStr();
      return (get().sleepHistory ?? []).find(s => s.date === today && !s.deleted);
    },

    completeBarrier(opts) {
      const today = dateStr();
      const now = Date.now();
      let persistEntry: SleepEntry | undefined;
      set(s => {
        const existing = (s.sleepHistory ?? []).find(e => e.date === today && !e.deleted);
        if (existing) {
          const updated: SleepEntry = { ...existing, barrierDone: true, barrierMin: opts.barrierMin, awayMin: opts.awayMin, practice: opts.practice, updatedAt: now };
          persistEntry = updated;
          return { sleepHistory: s.sleepHistory.map(e => e.id === existing.id ? updated : e) };
        }
        const entry: SleepEntry = { id: uuid(), date: today, barrierDone: true, barrierMin: opts.barrierMin, awayMin: opts.awayMin, practice: opts.practice, updatedAt: now, deleted: false };
        persistEntry = entry;
        return { sleepHistory: [...s.sleepHistory, entry] };
      });
      if (persistEntry) adapter.persistChange('sleep', persistEntry.id, persistEntry).catch(e => log.error(e));
      onSync?.();
    },

    saveSleepDiary(partial) {
      const today = dateStr();
      const now = Date.now();
      let persistEntry: SleepEntry | undefined;
      set(s => {
        const existing = (s.sleepHistory ?? []).find(e => e.date === today && !e.deleted);
        if (existing) {
          const updated: SleepEntry = { ...existing, ...partial, id: existing.id, date: today, updatedAt: now };
          if (updated.bedtimeAt && updated.wakeAt) {
            let diff = updated.wakeAt - updated.bedtimeAt;
            if (diff < 0) diff += 24 * 60 * 60 * 1000; // cross-midnight correction
            updated.durationMin = Math.round(diff / 60000);
          }
          persistEntry = updated;
          return { sleepHistory: s.sleepHistory.map(e => e.id === existing.id ? updated : e) };
        }
        const entry: SleepEntry = { id: uuid(), date: today, barrierDone: false, updatedAt: now, deleted: false, ...partial };
        if (entry.bedtimeAt && entry.wakeAt) {
          let diff = entry.wakeAt - entry.bedtimeAt;
          if (diff < 0) diff += 24 * 60 * 60 * 1000;
          entry.durationMin = Math.round(diff / 60000);
        }
        persistEntry = entry;
        return { sleepHistory: [...s.sleepHistory, entry] };
      });
      if (persistEntry) adapter.persistChange('sleep', persistEntry.id, persistEntry).catch(e => log.error(e));
      onSync?.();
    },

    setSleepGoal(goal) {
      set({ sleepGoal: goal });
      adapter.persistSettings('sleepGoal', goal).catch(e => log.error(e));
    },
  });
}

// ─── Slice-level error tracking slice ─────────────────────────
import type { SliceError, SliceErrorState } from './types';
import type { SliceCreator } from './sliceHelper';

const MAX_SLICE_ERRORS = 20;

export function createSliceErrorSlice(): SliceCreator<SliceErrorState> {
  return (set) => ({
    sliceErrors: [],

    addSliceError(error: SliceError) {
      set(s => ({
        sliceErrors: [...s.sliceErrors, error].slice(-MAX_SLICE_ERRORS),
      }));
    },

    clearSliceErrors() {
      set({ sliceErrors: [] });
    },
  });
}

import { describe, it, expect } from 'vitest';
import { createThoughtTrailSlice } from './createThoughtTrailSlice';
import type { StorageAdapter } from './types';
import type { ThoughtTrail } from '../types/thought-trail';

/** No-op adapter for unit tests — all persistence calls are silently ignored. */
const noopAdapter: StorageAdapter = {
  persistChange: async () => {},
  markDeleted: async () => {},
  batchDelete: async () => {},
  persistSettings: async () => {},
  getSettings: async () => null,
  transaction: async (fn) => fn(),
};

function makeTestStore(initialState: any = {}) {
  let state: any = {
    thoughtTrails: [],
    reflections: [],
    trailNotes: [],
    planItems: [],
    ...initialState,
  };
  const set = (fn: any) => {
    const patch = typeof fn === 'function' ? fn(state) : fn;
    state = { ...state, ...patch };
  };
  const get = () => state;
  const api = { setState: set, getState: get, getInitialState: () => state, subscribe: () => () => {}, destroy: () => {} };
  return { state, set, get: get as any, api };
}

const makeTrail = (overrides: Partial<ThoughtTrail> = {}): ThoughtTrail => ({
  id: 't1',
  name: 'Test Trail',
  reflectionIds: [],
  noteIds: [],
  source: 'manual',
  createdAt: 1000,
  updatedAt: 1000,
  deleted: false,
  ...overrides,
});

describe('createThoughtTrailSlice', () => {
  describe('setInsightCache', () => {
    it('sets insightCache on the trail', () => {
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail()],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);

      const cache = {
        summary: 'test summary',
        keyPoints: ['point 1'],
        turningPoints: ['turn 1'],
        suggestions: ['suggest 1'],
        generatedAt: Date.now(),
        source: 'local' as const,
      };

      slice.setInsightCache('t1', cache);

      const trail = get().thoughtTrails.find((t: any) => t.id === 't1');
      expect(trail.insightCache).toEqual(cache);
    });

    it('overwrites existing insightCache', () => {
      const existingCache = {
        summary: 'old',
        keyPoints: [],
        turningPoints: [],
        suggestions: [],
        generatedAt: 1000,
        source: 'local' as const,
      };
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail({ insightCache: existingCache })],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);

      const newCache = { ...existingCache, summary: 'new', generatedAt: 2000 };
      slice.setInsightCache('t1', newCache);

      const trail = get().thoughtTrails.find((t: any) => t.id === 't1');
      expect(trail.insightCache.summary).toBe('new');
    });
  });

  describe('setReviewCache', () => {
    it('sets reviewCache on the trail', () => {
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail()],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);

      const cache = {
        perspectives: ['persp1'],
        observations: ['obs1'],
        suggestions: ['s1'],
        generatedAt: Date.now(),
        source: 'cloud' as const,
      };

      slice.setReviewCache('t1', cache);

      const trail = get().thoughtTrails.find((t: any) => t.id === 't1');
      expect(trail.reviewCache).toEqual(cache);
    });
  });

  describe('createPlanItemFromTrail', () => {
    it('returns false when trail not found', () => {
      const { set, get, api } = makeTestStore();
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);
      const result = slice.createPlanItemFromTrail('missing', {
        name: 'test',
        description: '',
        priority: 'medium',
        startDate: '2026-01-01',
        endDate: '2026-01-31',
      });
      expect(result).toBe(false);
    });

    it('returns false when no active plan', () => {
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail()],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);
      const result = slice.createPlanItemFromTrail('t1', {
        name: 'test',
        description: '',
        priority: 'medium',
        startDate: '2026-01-01',
        endDate: '2026-01-31',
      });
      expect(result).toBe(false);
    });
  });

  describe('getTrailPlanItems', () => {
    it('returns plan items with matching trailId', () => {
      const { set, get, api } = makeTestStore({
        planItems: [
          { id: 'p1', trailId: 't1', name: 'task 1', deleted: false },
          { id: 'p2', trailId: 't1', name: 'task 2', deleted: false },
          { id: 'p3', trailId: 't2', name: 'task 3', deleted: false },
          { id: 'p4', trailId: 't1', name: 'task 4', deleted: true },
        ],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);
      const items = slice.getTrailPlanItems('t1');
      expect(items).toHaveLength(2);
      expect(items[0].id).toBe('p1');
      expect(items[1].id).toBe('p2');
    });

    it('returns empty array when no matching items', () => {
      const { set, get, api } = makeTestStore({
        planItems: [{ id: 'p1', trailId: 't2', name: 'task', deleted: false }],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);
      const items = slice.getTrailPlanItems('t1');
      expect(items).toEqual([]);
    });
  });

  describe('deleteThoughtTrail', () => {
    it('cascade deletes trail notes', () => {
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail({ noteIds: ['n1', 'n2'] })],
        trailNotes: [
          { id: 'n1', trailId: 't1', content: 'a', tags: [], source: 'free', order: 0, createdAt: 1000, updatedAt: 1000, deleted: false },
          { id: 'n2', trailId: 't1', content: 'b', tags: [], source: 'free', order: 1, createdAt: 2000, updatedAt: 2000, deleted: false },
          { id: 'n3', trailId: 't2', content: 'c', tags: [], source: 'free', order: 0, createdAt: 1000, updatedAt: 1000, deleted: false },
        ],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);

      slice.deleteThoughtTrail('t1');

      const state = get();
      expect(state.thoughtTrails).toHaveLength(1);
      expect(state.thoughtTrails[0].deleted).toBe(true);
      expect(state.trailNotes.filter((n: any) => !n.deleted)).toHaveLength(1);
      expect(state.trailNotes.filter((n: any) => !n.deleted)[0].id).toBe('n3');
    });

    it('removes trail ID from reflections', () => {
      const { set, get, api } = makeTestStore({
        thoughtTrails: [makeTrail({ reflectionIds: ['r1', 'r2'] })],
        reflections: [
          { id: 'r1', thoughtTrailIds: ['t1'], updatedAt: 0, deleted: false },
          { id: 'r2', thoughtTrailIds: ['t1', 't2'], updatedAt: 0, deleted: false },
        ],
      });
      const slice = createThoughtTrailSlice(noopAdapter)(set, get, api);

      slice.deleteThoughtTrail('t1');

      const state = get();
      expect(state.reflections[0].thoughtTrailIds).not.toContain('t1');
      expect(state.reflections[1].thoughtTrailIds).toContain('t2');
      expect(state.reflections[1].thoughtTrailIds).not.toContain('t1');
    });
  });
});

