// ─── Recycle bin types ────────────────────────────────────────────
import type { Habit } from './habit';
import type { MindReflection } from './reflection';
import type { FoodEntry } from './food';
import type { ExerciseEntry } from './exercise';
import type { Plan, PlanItem } from './plan';
import type { BreathingRecord } from './breath';

export type RecycleBinEntityType = 'habit' | 'reflection' | 'food' | 'exercise' | 'plan' | 'breath' | 'planItem';

export interface RecycleBinItem {
  id: string;
  entityType: RecycleBinEntityType;
  data: Habit | MindReflection | FoodEntry | ExerciseEntry | Plan | BreathingRecord | PlanItem;
  deletedAt: number;
}

// ─── Shared base types ────────────────────────────────────────────

/** Known canonical mood values. Use these for type-safe mood handling. */
export type KnownMood =
  | '开心' | '兴奋' | '感恩' | '平静'
  | '焦虑' | '难过' | '生气' | '疲惫'
  | '满足' | '释然' | '淡定';

/** Mood string — prefer KnownMood values for new code */
export type Mood = KnownMood | (string & {});
export type HabitStatus = 'notStarted' | 'inProgress' | 'paused' | 'abandoned' | 'completed';
export type ThemeName = 'dark' | 'light' | 'ocean' | 'rose' | 'cosmos';

/** Base interface for all syncable entities */
export interface Syncable {
  updatedAt: number;
  deleted: boolean;
}

export interface Theme {
  name: string;
  nameEn?: string;
  bg: string;
  card: string;
  cardSolid: string;
  text: string;
  sub: string;
  border: string;
  primary: string;
  accent: string;
  navBg: string;
  starfield: boolean;
  warning?: string;
}

import { describe, it, expect, vi } from 'vitest';
import {
  fmt, fmtMS, dateStr, yesterday, tomorrow, daysInMonth,
  uid, computeStreak, estimateFastingKcal,
  calculateCheckinStreak, buildHeatmapGrid,
} from './utils';

describe('fmt', () => {
  it('formats seconds to HH:MM:SS', () => {
    expect(fmt(0)).toBe('00:00:00');
    expect(fmt(61)).toBe('00:01:01');
    expect(fmt(3661)).toBe('01:01:01');
  });
  it('clamps negative to 0', () => {
    expect(fmt(-5)).toBe('00:00:00');
  });
});

describe('fmtMS', () => {
  it('formats seconds to MM:SS', () => {
    expect(fmtMS(0)).toBe('00:00');
    expect(fmtMS(90)).toBe('01:30');
  });
});

describe('dateStr', () => {
  it('returns YYYY-MM-DD format', () => {
    const result = dateStr(new Date(2026, 0, 15));
    expect(result).toBe('2026-01-15');
  });
  it('pads single digits', () => {
    const result = dateStr(new Date(2026, 2, 5));
    expect(result).toBe('2026-03-05');
  });
});

describe('daysInMonth', () => {
  it('returns correct days', () => {
    expect(daysInMonth(2026, 0)).toBe(31);  // Jan
    expect(daysInMonth(2026, 1)).toBe(28);  // Feb (not leap)
    expect(daysInMonth(2024, 1)).toBe(29);  // Feb (leap)
    expect(daysInMonth(2026, 11)).toBe(31); // Dec
  });
});

describe('computeStreak', () => {
  it('returns 0 for empty', () => {
    expect(computeStreak([])).toBe(0);
  });
  it('returns 0 when most recent is too old', () => {
    expect(computeStreak(['2020-01-01'])).toBe(0);
  });
  it('returns 1 for today only', () => {
    const today = dateStr();
    expect(computeStreak([today])).toBe(1);
  });
  it('returns 1 for yesterday only', () => {
    expect(computeStreak([yesterday()])).toBe(1);
  });
  it('counts consecutive days', () => {
    const today = dateStr();
    const y = yesterday();
    expect(computeStreak([today, y])).toBe(2);
  });
  it('breaks on gap', () => {
    const today = dateStr();
    const d = new Date();
    d.setDate(d.getDate() - 3);
    const threeDaysAgo = dateStr(d);
    expect(computeStreak([today, threeDaysAgo])).toBe(1);
  });
  it('deduplicates', () => {
    const today = dateStr();
    expect(computeStreak([today, today])).toBe(1);
  });
});

describe('estimateFastingKcal', () => {
  it('uses BMR formula for male', () => {
    // BMR = 10*70 + 6.25*170 - 5*30 + 5 = 700 + 1062.5 - 150 + 5 = 1617.5
    // hourly = 1617.5 / 24 = 67.396
    // 16h = 67.396 * 16 = 1078.33 → 1078
    expect(estimateFastingKcal(16, 70, 'male', 30, 170)).toBe(1078);
  });
  it('uses BMR formula for female', () => {
    // BMR = 10*60 + 6.25*160 - 5*25 - 161 = 600 + 1000 - 125 - 161 = 1314
    // hourly = 1314 / 24 = 54.75
    // 16h = 54.75 * 16 = 876
    expect(estimateFastingKcal(16, 60, 'female', 25, 160)).toBe(876);
  });
});

